VALUES ('2cb83325-806d-4585-aad7-515e3577b245', 'ALG.01', 2, 'choice', 'Simplify by combining like terms', 'Simplify $3a^2+2a-a^2+5a$.', '["$4a^2+7a$","$2a^2+7a$","$9a^2$","$2a^2+3a$"]', '$2a^2+7a$', NULL, 'The $a^2$ terms: $3a^2-a^2=2a^2$. The $a$ terms: $2a+5a=7a$. The result is $2a^2+7a$.', 'checked', '{"lint":[],"solve":{"answer":"$2a^2+7a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 - 1)a^2 + (2 + 5)a = 2a^2 + 7a.","run_id":"claude-code","at":"2026-10-19T07:04:01.173Z"}}', 'ai', NULL, NULL)
