VALUES ('05bfdfed-b3f1-4c7a-9b04-ba4e4c017e40', 'ALG.02', 3, 'numeric', 'Decide whether expressions are equal', 'For which number $c$ is $c(x+2)+3x$ equal to $8x+10$ for every value of $x$?', '[]', '5', '8-3', '$c(x+2)+3x=(c+3)x+2c$. We need $c+3=8$ and $2c=10$. Both give $c=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(c+3)x+2c: c+3=8 gives c=5, and 2c=10 matches.","run_id":"claude-code","at":"2026-10-19T01:40:43.203Z"}}', 'ai', NULL, NULL)
