VALUES ('018c6e85-e1bf-4ddf-93ef-81bd80533dae', 'ALG.04', 2, 'numeric', 'Evaluate an expression with several variables', 'Find the value of $2(x+y)-3(x-y)$ when $x=5$ and $y=2$.', '[]', '5', '2*(5+2)-3*(5-2)', '$2\times7=14$ and $3\times3=9$. So $14-9=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(7)-3(3)=14-9=5","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('030a1e20-0887-4875-bcfa-32c01abc9f49', 'ALG.04', 2, 'choice', 'Solve a formula for one variable: two steps', 'Solve $T=2a+3b$ for $a$.', '["$a=\\frac{T+3b}{2}$","$a=T-3b$","$a=\\frac{T-3b}{2}$","$a=\\frac{T-b}{2}$"]', '$a=\frac{T-3b}{2}$', NULL, 'Subtract $3b$: $2a=T-3b$. Divide by 2: $a=\frac{T-3b}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$a=\\frac{T-3b}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2a=T-3b, a=(T-3b)/2","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c102e4c-f74e-4d49-b36b-38e30097857b', 'ALG.04', 3, 'numeric', 'Reason about how an expression changes', 'If $x+y=7$, what is the value of $3x+3y-4$?', '[]', '17', '3*7-4', '$3x+3y=3(x+y)=21$. So $21-4=17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+y)-4=21-4=17","run_id":"claude-code","at":"2026-10-19T07:04:01.211Z"}}', 'ai', NULL, NULL)
