INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1973db16-0d46-403d-9638-c87a1d203c5b', 'ALG.05', 1, 'choice', 'Check which pair solves a system', 'Which pair $(x, y)$ makes both $2x+y=9$ and $x+y=6$ true?', '["$(4, 1)$","$(3, 3)$","$(2, 4)$","$(5, 1)$"]', '$(3, 3)$', NULL, '$(3, 3)$ gives $2\times3+3=9$ and $3+3=6$. Each other pair breaks at least one equation.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract: x=3; y=3. Check 6+3=9","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
