INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14e31e7d-a644-4655-b629-af8e38b4f265', 'ALG.05', 1, 'numeric', 'Find an unknown coefficient from a solution', 'The pair $(x,y)=(2,5)$ is a solution of $3x+ky=31$. What is $k$?', '[]', '5', '(31-3*2)/5', 'Put in $x=2$, $y=5$: $6+5k=31$. So $5k=25$ and $k=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2)+5k=31, 5k=25, k=5","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
