INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0644a46f-a17e-4719-adde-8f460a0b64e5', 'ALG.05', 2, 'choice', 'Solve a system by substitution', 'Solve $x+y=14$ and $x=3y-2$. What is $x$?', '["4","10","12","8"]', '10', '14-4', 'Replace $x$: $(3y-2)+y=14$, so $4y=16$ and $y=4$. Then $x=14-4=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3y-2+y=14, y=4, x=10","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
