INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ec83f6d-4743-4645-9b83-3be8bf26fa54', 'ALG.05', 2, 'numeric', 'Solve a system of three equations', 'If $x+y+z=20$, $x-y=1$ and $y-z=2$, what is $x$?', '[]', '8', '8', '$x=y+1$ and $z=y-2$. So $(y+1)+y+(y-2)=20$, which gives $3y-1=20$ and $y=7$. Then $x=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=z+2, x=z+3; 3z+5=20, z=5, x=8","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
