INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0804b176-e9d1-4e10-9c51-8f435afb0ac2', 'ALG.05', 3, 'numeric', 'Count the solutions of a system', 'The system $3x+ky=7$ and $6x+8y=20$ has no solution. What is $k$?', '[]', '4', '4', 'Doubling the first equation gives $6x+2ky=14$. For no solution the $y$ parts must match, so $2k=8$ and $k=4$. Then the right sides differ ($14$ and $20$), so the equations clash.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel: 3/6=k/8, k=4; 3x+4y=7 vs 3x+4y=10, no solution","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f5c30b-62ce-4289-8120-ed023c3f97cd', 'ALG.05', 3, 'numeric', 'Solve a system of three equations', 'Solve $x+y+z=6$, $x+2y+3z=14$ and $x+4y+9z=36$. What is $z$?', '[]', '3', '3', 'Subtract the first from the second: $y+2z=8$. Subtract the second from the third: $2y+6z=22$, so $y+3z=11$. Then $z=11-8=3$ (and $y=2$, $x=1$).', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"eq2-eq1: y+2z=8; eq3-eq2: y+3z=11; z=3 (y=2, x=1)","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eff1abb-624b-450a-97d6-7f2eb39736b4', 'ALG.06', 1, 'numeric', 'Using a ratio to find a quantity', 'A necklace has red beads and green beads in the ratio $2:7$. It has 14 red beads. How many beads does it have altogether?', '[]', '63', '14/2*9', '14 red beads is $7 \times 2$, so multiply both parts by 7: 14 red and 49 green. Altogether $14+49 = 63$.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 2 parts = 14, part 7; green 49; total 9*7 = 63.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
