INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f192ba6-9a94-430d-8612-397de9a6b0c6', 'ALG.06', 1, 'numeric', 'Percent increase and decrease', 'A toy costs 40 dollars. It is on sale for 10% off. What is the sale price in dollars?', '[]', '36', '40-4', '10% of 40 is 4. The sale price is $40 - 4 = 36$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10% of 40 = 4; 40-4 = 36.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
