INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04d665c8-6c43-49ca-b278-b5ab55b498fd', 'ALG.06', 3, 'choice', 'Writing and simplifying ratios', 'The ratio of apples to bananas is $2:3$, and the ratio of bananas to cherries is $6:5$. What is the ratio of apples to cherries?', '["$2:5$","$5:4$","$4:5$","$12:5$"]', '$4:5$', NULL, 'Make the banana numbers match: $2:3 = 4:6$. Then apples : bananas : cherries is $4:6:5$, so apples to cherries is $4:5$.', 'checked', '{"lint":[],"solve":{"answer":"$4:5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a:b = 2:3 = 4:6, b:c = 6:5, so a:c = 4:5.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06cb7171-351f-471a-83d2-fcef32448b3d', 'ALG.06', 3, 'numeric', 'Using a ratio to find a quantity', 'The sides of a rectangle are in the ratio $3:4$ and its perimeter is 56 cm. What is the area of the rectangle, in square centimeters?', '[]', '192', '12*16', 'Sides are $3k$ and $4k$, and the perimeter is $2(3k+4k) = 14k = 56$, so $k = 4$. The sides are 12 and 16, and the area is $12 \times 16 = 192$.', 'checked', '{"lint":[],"solve":{"answer":"192","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length+width = 28 = 7 parts, part 4: 12 by 16; area 192.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04552532-e129-4ded-a8e7-4d9ddca3bfb6', 'ALG.07', 1, 'choice', 'Scale drawings, maps and similar figures', 'On a map, 1 inch stands for 5 miles. Two towns are 4 inches apart on the map. How many miles apart are they?', '["$9$","$1.25$","$25$","$20$"]', '$20$', '4*5', 'Each inch is 5 miles, so 4 inches is $4 \times 5 = 20$ miles.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*5 = 20.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00025c19-4b72-4a9d-b990-8114ab6c0577', 'ALG.07', 1, 'choice', 'Telling direct from inverse variation', 'Which pair of quantities vary inversely?', '["The number of apples bought and the total cost","The time walked at a steady speed and the distance walked","The number of people sharing a pizza and the size of each person''s slice","The hours worked at a fixed wage and the pay earned"]', 'The number of people sharing a pizza and the size of each person''s slice', NULL, 'When more people share one pizza, each slice is smaller: as one goes up the other goes down by the same factor. The other pairs go up together, so they vary directly.', 'checked', '{"lint":[],"solve":{"answer":"The number of people sharing a pizza and the size of each person''s slice","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fixed pizza: more people, smaller slices (product constant). Others are direct.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07caf6aa-c0fc-42cd-9b5a-444f915d8555', 'ALG.07', 1, 'choice', 'Telling direct from inverse variation', 'Every ticket to a show costs the same. How are the number of tickets bought and the total cost related?', '["inversely proportional","directly proportional","not related","always equal"]', 'directly proportional', NULL, 'Twice the tickets cost twice as much, and the total divided by the number of tickets is always the price of one ticket. That is direct proportion.', 'checked', '{"lint":[],"solve":{"answer":"directly proportional","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost = price * number: direct.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11e6eda8-3d7d-4331-81c7-f6b8b7a8714c', 'ALG.07', 2, 'choice', 'Solving proportions', 'If $\frac{a}{b} = \frac{3}{7}$ (with $b \neq 0$), what is $\frac{a+b}{b}$?', '["$\\frac{3}{10}$","$\\frac{10}{7}$","$\\frac{4}{7}$","$\\frac{7}{10}$"]', '$\frac{10}{7}$', NULL, 'Take $a = 3k$ and $b = 7k$. Then $a + b = 10k$, so $\frac{a+b}{b} = \frac{10k}{7k} = \frac{10}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{10}{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a/b + 1 = 3/7 + 1 = 10/7.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10c99973-0e66-4004-b691-11bce5cab689', 'ALG.07', 2, 'numeric', 'Direct variation', 'The distance $d$ a cyclist rides is directly proportional to the time $t$ she rides. In 1.5 hours she rides 45 kilometers. How many kilometers does she ride in 4 hours?', '[]', '120', '45/1.5*4', 'Her speed is $45 \div 1.5 = 30$ kilometers per hour, so in 4 hours she rides $30 \times 4 = 120$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 km/h * 4 = 120.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('008a79b5-2d8e-42b8-b91b-3d60707680f5', 'ALG.07', 2, 'numeric', 'Direct variation', 'The cost of a sandwich platter is directly proportional to the number of people it feeds. A platter for 8 people costs 52 dollars. How many dollars does a platter for 12 people cost?', '[]', '78', '52/8*12', 'It costs $52 \div 8 = 6.5$ dollars per person, so for 12 people it costs $6.5 \times 12 = 78$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"78","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6.5 per person * 12 = 78.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0009ec8c-e488-4fde-ab8c-cca53152d4c0', 'ALG.07', 3, 'choice', 'Solving proportions', 'Suppose $\frac{a}{b} = \frac{3}{5}$ and $\frac{b}{c} = \frac{10}{7}$. What is $\frac{a}{c}$?', '["$\\frac{7}{6}$","$\\frac{21}{50}$","$\\frac{13}{12}$","$\\frac{6}{7}$"]', '$\frac{6}{7}$', NULL, 'Multiply: $\frac{a}{c} = \frac{a}{b} \times \frac{b}{c} = \frac{3}{5} \times \frac{10}{7} = \frac{30}{35} = \frac{6}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a/c = (a/b)(b/c) = 3/5*10/7 = 6/7.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02b87f2f-8865-4b72-89cb-869e54fafd86', 'ALG.07', 3, 'choice', 'Telling direct from inverse variation', 'The quantity $A$ varies directly with $B$, and $B$ varies inversely with $C$. Which statement is true?', '["The product $A \\times C$ is always the same.","The ratio $\\frac{A}{C}$ is always the same.","The sum $A + C$ is always the same.","The difference $A - C$ is always the same."]', 'The product $A \times C$ is always the same.', NULL, '$A = kB$ and $BC = m$ for fixed numbers $k$ and $m$. So $AC = kBC = km$, which does not change. Thus $A$ and $C$ vary inversely.', 'checked', '{"lint":[],"solve":{"answer":"The product $A \\times C$ is always the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = kB, B = m/C, A = km/C, so AC = km constant.","run_id":"claude-code","at":"2026-10-19T01:41:49.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13a484c2-b74d-4df8-a7a9-1609d0088b4a', 'ALG.08', 1, 'choice', 'Point-slope form', 'Which is the point-slope form of the line with slope $4$ through the point $(2, 7)$?', '["$y-2=4(x-7)$","$y+7=4(x+2)$","$y-7=4(x-2)$","$y-7=2(x-4)$"]', '$y-7=4(x-2)$', NULL, 'Point-slope form is $y-y_1=m(x-x_1)$. With $m=4$, $x_1=2$ and $y_1=7$ it is $y-7=4(x-2)$.', 'checked', '{"lint":[],"solve":{"answer":"$y-7=4(x-2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y-y1=m(x-x1): y-7=4(x-2)","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c1f284-3411-4113-8b43-0a4c855e9368', 'ALG.08', 1, 'choice', 'Using a line: points on it, horizontal and vertical lines, rates', 'Which statement about the line $x=4$ is true?', '["It is horizontal and it crosses the $y$-axis at $(0, 4)$.","It is vertical and it crosses the $y$-axis at $(0, 4)$.","It is vertical and it crosses the $x$-axis at $(4, 0)$.","It is horizontal and it crosses the $x$-axis at $(4, 0)$."]', 'It is vertical and it crosses the $x$-axis at $(4, 0)$.', NULL, 'Every point on $x=4$ has $x=4$, so the line is vertical. At $y=0$ the point is $(4, 0)$ on the $x$-axis. It never reaches $x=0$, so it has no $y$-intercept.', 'checked', '{"lint":[],"solve":{"answer":"It is vertical and it crosses the $x$-axis at $(4, 0)$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=4 is vertical, meets x-axis at (4,0)","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('231d9e6b-deba-4930-a66b-bb8381003ef1', 'ALG.08', 1, 'numeric', 'Using a line: points on it, horizontal and vertical lines, rates', 'A plant is 12 cm tall and grows 2 cm each week. Its height after $x$ weeks is $y=2x+12$ cm. How tall is it after 5 weeks, in centimeters?', '[]', '22', '2*5+12', 'Put in $x=5$: $y=2(5)+12=22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*5+12=22","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
