VALUES ('1e6c25d4-8bff-439f-a401-139695f4b2b5', 'ALG.09', 1, 'choice', 'Absolute value inequalities', 'Which of these numbers satisfies $|x|>4$?', '["$4$","$0$","$-5$","$-3$"]', '$-5$', NULL, 'The distance of $-5$ from $0$ is $5$, which is more than $4$. The others have distance $4$, $0$ and $3$.', 'checked', '{"lint":[],"solve":{"answer":"$-5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-5|=5>4","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
