INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18800a82-5223-4c56-80f6-7c7be0dcbc7f', 'ALG.09', 2, 'numeric', 'Inequality word problems', 'Jo scored 78, 85 and 90 on three tests. She wants an average of at least 85 over four tests. What is the lowest score she can get on the fourth test?', '[]', '87', '85*4-78-85-90', 'Four tests with average at least 85 need a total of at least $4\times 85=340$. The first three total $253$, so the fourth must be at least $340-253=87$.', 'checked', '{"lint":[],"solve":{"answer":"87","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"need total >=340; 340-253=87","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('019cba15-5a7b-48a2-ad57-53200088ceef', 'ALG.09', 2, 'numeric', 'Inequality word problems', 'Plan A costs 15 dollars plus 3 dollars per hour. Plan B costs 6 dollars per hour. For how many whole numbers of hours (1 or more) is plan B cheaper than plan A?', '[]', '4', '4', 'Plan B is cheaper when $6h<15+3h$, so $3h<15$ and $h<5$. The whole numbers of hours from 1 to 4 work: 4 values. (At 5 hours both cost 30 dollars.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6h<15+3h, h<5: 1..4 -> 4","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ff3e070-fc22-4abe-9f67-eec8e8e8af33', 'ALG.09', 3, 'choice', 'Absolute value inequalities', 'Which inequality has the solution $-1<x<5$?', '["$|x-2|>3$","$|x-2|<3$","$|x+2|<3$","$|x-3|<3$"]', '$|x-2|<3$', NULL, 'The interval from $-1$ to $5$ has centre $2$ and half-width $3$, so it is the set of $x$ within $3$ of $2$: $|x-2|<3$. The other choices give intervals centred at $2$ (outside), $-2$ and $3$.', 'checked', '{"lint":[],"solve":{"answer":"$|x-2|<3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"centre 2, radius 3: |x-2|<3","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10106fd9-07e1-4e41-bf6c-80b9621eb1aa', 'ALG.09', 3, 'numeric', 'Inequality word problems', 'The sum of three consecutive integers is greater than 40 and less than 60. How many such sets of three consecutive integers are there?', '[]', '6', '18-13+1', 'Let the smallest be $n$. The sum is $3n+3$, and $40<3n+3<60$ gives $37<3n<57$, so $12.3\ldots<n<19$. The values are $n=13, 14, \ldots, 18$: 6 sets.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3m with middle m: 40<3m<60, 13.3<m<20, m=14..19: 6","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f9e1937-1461-43e7-9d00-d130d21f5886', 'ALG.10', 1, 'choice', 'Factor a monic quadratic', 'Which expression is equal to $x^2+7x+12$?', '["$(x+3)(x+4)$","$(x-3)(x-4)$","$(x+2)(x+6)$","$(x+7)(x+12)$"]', '$(x+3)(x+4)$', NULL, 'We need two numbers that multiply to 12 and add to 7. Those are 3 and 4, so $x^2+7x+12=(x+3)(x+4)$. Check: $(x+3)(x+4)=x^2+7x+12$.', 'checked', '{"lint":[],"solve":{"answer":"$(x+3)(x+4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need two numbers with product 12 and sum 7: 3 and 4. (x+3)(x+4)=x^2+7x+12.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c0fdf3-688e-4c2c-9aa5-8894ff50ca58', 'ALG.10', 1, 'choice', 'Solve a quadratic equation by factoring', 'Solve $x^2-5x+6=0$. What is the smaller solution?', '["3","6","-2","2"]', '2', NULL, 'Factor: $x^2-5x+6=(x-2)(x-3)=0$. So $x=2$ or $x=3$. The smaller is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)(x-3)=0: 2 or 3. Smaller 2.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
