VALUES ('06421b27-ece8-4a6f-aa75-894f9ec9b128', 'ALG.10', 1, 'choice', 'Expressions in the roots', 'The solutions of $x^2-10x+21=0$ are $r$ and $s$. What is $rs-(r+s)$?', '["11","31","-11","21"]', '11', '21-10', '$r+s=10$ and $rs=21$, so $rs-(r+s)=21-10=11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"rs=21, r+s=10. 11.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
