INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('153a43b7-74d5-4d20-a4ce-eccda88add15', 'ALG.10', 2, 'choice', 'Equations with a common factor of x', 'Dev solves $x^2=11x$ by dividing both sides by $x$. He gets $x=11$. What went wrong?', '["He lost the solution $x=-11$.","He lost the solution $x=0$.","He should have found $x=121$.","Nothing: $x=11$ is the only solution."]', 'He lost the solution $x=0$.', NULL, 'Dividing by $x$ is not allowed when $x$ could be 0. Instead write $x^2-11x=0$, so $x(x-11)=0$, giving $x=0$ or $x=11$. Dev lost $x=0$.', 'checked', '{"lint":[],"solve":{"answer":"He lost the solution $x=0$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-11x=0, x(x-11)=0: 0 or 11. Dividing by x lost x=0.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
