VALUES ('20a6d2e3-9308-4dea-8311-65dab25c64b5', 'ALG.11', 2, 'choice', 'Use a difference of squares to calculate', 'Which is the value of $103\times97$?', '["10009","9994","9991","10000"]', '9991', '10000-9', '$103\times97=(100+3)(100-3)=100^2-3^2=10000-9=9991$.', 'checked', '{"lint":[],"solve":{"answer":"9991","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(100+3)(100-3)=10000-9=9991.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
