VALUES ('093ceeb1-a7c0-4ee9-8d79-ec9220244e42', 'ALG.12', 3, 'numeric', 'Adding and subtracting complex numbers', 'The ten numbers $1+i,\ 2+2i,\ 3+3i,\ \ldots,\ 10+10i$ are added together. What is the real part of the total?', '[]', '55', '10*11/2', 'The real parts are $1,2,\ldots,10$. Their sum is $\frac{10\cdot11}{2}=55$.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Real parts 1+...+10=55.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
