INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('063f2709-6bd3-4d10-a5d8-6005571a42de', 'ALG.13', 1, 'choice', 'Quadratic formula with rational solutions', 'Which formula gives the solutions of $ax^2+bx+c=0$?', '["$x=\\dfrac{-b\\pm\\sqrt{b^2-4ac}}{2a}$","$x=\\dfrac{b\\pm\\sqrt{b^2-4ac}}{2a}$","$x=\\dfrac{-b\\pm\\sqrt{b^2+4ac}}{2a}$","$x=\\dfrac{-b\\pm\\sqrt{b^2-4ac}}{a}$"]', '$x=\dfrac{-b\pm\sqrt{b^2-4ac}}{2a}$', NULL, 'This is the quadratic formula. The others change a sign (of $b$ or of $4ac$) or use $a$ in the denominator instead of $2a$.', 'checked', '{"lint":[],"solve":{"answer":"$x=\\dfrac{-b\\pm\\sqrt{b^2-4ac}}{2a}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Standard formula x=(-b±√(b^2-4ac))/(2a).","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f2f58fd-0c9b-40ab-b2de-918930f3e972', 'ALG.13', 1, 'choice', 'Finding a coefficient from the discriminant', 'The equation $x^2+kx+9=0$ has exactly one solution and $k>0$. What is $k$?', '["$3$","$6$","$9$","$18$"]', '$6$', '6', 'The discriminant $k^2-36$ must be $0$, so $k^2=36$. Since $k>0$, $k=6$.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k^2-36=0, k>0: 6.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a4a023e-974d-403e-b982-c55bd258e114', 'ALG.13', 1, 'numeric', 'Building an equation from its solutions', 'Two numbers add to $9$ and multiply to $14$. What is the larger number?', '[]', '7', '7', 'They are the solutions of $x^2-9x+14=0$, which factors as $(x-2)(x-7)=0$. The larger is $7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t^2-9t+14=0: 7 and 2; larger 7.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
