INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dd49cd5-d2da-4980-99f1-bf818c6ceeab', 'ALG.13', 3, 'numeric', 'Solving by completing the square', 'What is the larger solution of $3x^2-6x-9=0$?', '[]', '3', '1+2', 'Divide by 3: $x^2-2x-3=0$, so $x^2-2x=3$. Add $1$: $(x-1)^2=4$. So $x-1=\pm2$, and $x=3$ or $x=-1$. The larger is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-2x-3=0, (x-1)^2=4, x=3 or -1; larger 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('065b5899-ebbd-4651-99a6-c468a8fed216', 'ALG.13', 3, 'numeric', 'Computing the discriminant', 'Compute the discriminant of $\frac12x^2+x-4=0$.', '[]', '9', '1+8', '$a=\frac12,\ b=1,\ c=-4$. $b^2-4ac=1-4\cdot\frac12\cdot(-4)=1+8=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-4*(1/2)*(-4)=1+8=9.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
