INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cff518d-cc02-4402-ba35-21d224b2089a', 'ALG.16', 2, 'numeric', 'Function notation and expressions like f(a+1)', 'A linear function $f$ has $f(1)=4$, $f(2)=7$, $f(3)=10$ and $f(4)=13$. What is $f(10)$?', '[]', '31', '3*10+1', 'Each step of 1 in the input adds 3 to the output, so $f(x)=3x+1$ and $f(10)=31$.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Steps of 3: f(x)=3x+1, f(10)=31","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
