INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dca00ce-f569-4953-b245-ca2064fd3895', 'ALG.16', 2, 'choice', 'Find the formula of an inverse function', 'If $f(x)=2x+6$, which rule gives $f^{-1}(x)$?', '["$f^{-1}(x)=\\frac{x+6}{2}$","$f^{-1}(x)=\\frac{x}{2}-6$","$f^{-1}(x)=2x-6$","$f^{-1}(x)=\\frac{x-6}{2}$"]', '$f^{-1}(x)=\frac{x-6}{2}$', NULL, 'Set $y=2x+6$ and solve for $x$: $x=\frac{y-6}{2}$. Swapping names gives $f^{-1}(x)=\frac{x-6}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$f^{-1}(x)=\\frac{x-6}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=2x+6 -> x=(y-6)/2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('095ea69c-43b7-4e1f-af6e-6dcb54d40f83', 'ALG.16', 2, 'numeric', 'Properties of inverse functions and one-to-one functions', 'Let $f(x)=2x+3$, and let $g$ be the inverse function of $f$. What is $g(f(g(11)))$?', '[]', '4', NULL, '$g(11)=4$ because $f(4)=11$. Then $f(4)=11$, and $g(11)=4$ again.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(f(y))=y so g(f(g(11)))=g(11)=(11-3)/2=4","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0de3ef60-ab9b-4f1e-9311-41cda52a1609', 'ALG.16', 3, 'numeric', 'Find an unknown number in the rule of a function', 'Let $f(x)=ax^2+bx$ with $f(1)=5$ and $f(2)=14$. Find $f(3)$.', '[]', '27', '2*9+3*3', '$a+b=5$ and $4a+2b=14$, i.e. $2a+b=7$. Subtract: $a=2$, so $b=3$. Then $f(3)=2\cdot9+3\cdot3=27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+b=5, 4a+2b=14 -> 2a+b=7, a=2, b=3, f(3)=18+9=27","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18ea160e-5c01-4619-99f8-843eafa19de9', 'ALG.16', 3, 'choice', 'Domain of a function', 'The domain of a function is exactly all numbers $x$ with $x\ge-2$. Which could be that function?', '["$f(x)=\\sqrt{x-2}$","$f(x)=\\sqrt{2-x}$","$f(x)=\\sqrt{x+2}$","$f(x)=\\frac{1}{x+2}$"]', '$f(x)=\sqrt{x+2}$', NULL, '$\sqrt{x+2}$ needs $x+2\ge0$, i.e. $x\ge-2$. The others give $x\ge2$, $x\le2$, and $x\ne-2$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x)=\\sqrt{x+2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(x+2) needs x>=-2; 1/(x+2) excludes -2, sqrt(x-2) x>=2, sqrt(2-x) x<=2","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
