INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cde2b11-6fc0-4bf7-8292-90f29e28ab89', 'ALG.17', 2, 'choice', 'Reflect a graph across an axis', 'The graph of $y=x+4$ is reflected across the $y$-axis. What is the equation of the new graph?', '["$y=-x-4$","$y=x-4$","$y=-x+4$","$y=-(x+4)$"]', '$y=-x+4$', NULL, 'Replace $x$ by $-x$: $y=-x+4$. The $y$-intercept stays at $4$ because the point $(0,4)$ is on the axis.', 'checked', '{"lint":[],"solve":{"answer":"$y=-x+4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Replace x by -x: y=-x+4","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
