VALUES ('08eca811-9591-4c27-b6be-3d074b945564', 'ALG.17', 2, 'numeric', 'Stretch or compress a graph horizontally', 'Let $f(x)=x^2+1$. What is the $y$-coordinate of the point on the graph of $y=f\left(\frac{x}{2}\right)$ where $x=6$?', '[]', '10', '3^2+1', '$f\left(\frac62\right)=f(3)=9+1=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(3)=9+1=10","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
