INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04f94c9b-1759-40a0-a89a-8fa95e96eadc', 'ALG.17', 2, 'numeric', 'Describe how one equation changes into another', 'The graph of $y=f(x-4)+9$ comes from the graph of $y=f(x)$ by moving it some units right and some units up. What is the total of those two numbers of units?', '[]', '13', '4+9', 'Replacing $x$ by $x-4$ moves right 4. Adding 9 moves up 9. The total is $13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"right 4, up 9, total 13","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
