INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1252f7c0-0d40-4a80-b3ca-c3ffba9ef4e3', 'ALG.14', 1, 'choice', 'Direction of opening and number of x-intercepts', 'Which parabola opens downward?', '["$y=3x^2-1$","$y=-3x^2+1$","$y=(x-3)^2$","$y=x^2-3x$"]', '$y=-3x^2+1$', NULL, 'A parabola opens downward when the number multiplying $x^2$ is negative. Only $y=-3x^2+1$ has a negative number there.', 'checked', '{"lint":[],"solve":{"answer":"$y=-3x^2+1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leading coefficient -3<0.","run_id":"claude-code","at":"2026-10-22T12:33:29.092Z"}}', 'ai', NULL, NULL)
