INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00b02d62-6bc3-4d8e-9913-96f747464c61', 'ALG.14', 2, 'choice', 'Find the intercepts of a parabola', 'How far apart are the $x$-intercepts of $y=x^2-10x+16$?', '["10","6","8","16"]', '6', '8-2', '$x^2-10x+16=(x-2)(x-8)$, so the intercepts are 2 and 8. They are $8-2=6$ apart.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)(x-8); roots 2, 8; 6 apart.","run_id":"claude-code","at":"2026-10-22T12:33:29.092Z"}}', 'ai', NULL, NULL)
