INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('072b3791-d241-4d85-a6be-e67629a17799', 'ALG.14', 2, 'choice', 'Find the intercepts of a parabola', 'Which parabola has $y$-intercept 5 and passes through the point $(1,0)$?', '["$y=x^2-5x+5$","$y=5x^2-6x+1$","$y=x^2+6x+5$","$y=x^2-6x+5$"]', '$y=x^2-6x+5$', NULL, 'The $y$-intercept is the constant term, 5. At $x=1$, $y=1-6+5=0$, so $(1,0)$ is on the graph. The others fail one of the two tests.', 'checked', '{"lint":[],"solve":{"answer":"$y=x^2-6x+5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y-intercept 5 leaves options 2-4. At x=1: 1+6+5=12, 1-5+5=1, 1-6+5=0. So x^2-6x+5 (option 1 has y-int 1).","run_id":"claude-code","at":"2026-10-22T12:33:29.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02b901cd-11b2-48df-ab4d-e7633be0b5f6', 'ALG.14', 3, 'numeric', 'Find the vertex of a quadratic in standard form', 'The parabola $y=x^2+bx+c$ has its vertex at $(2,-1)$. Find $c$.', '[]', '3', '4-1', 'The equation is $y=(x-2)^2-1=x^2-4x+4-1=x^2-4x+3$. So $c=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)^2-1=x^2-4x+3; c=3.","run_id":"claude-code","at":"2026-10-22T12:33:29.092Z"}}', 'ai', NULL, NULL)
