INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08d1dafe-da53-4790-a03d-a004d136c4d3', 'ALG.14', 3, 'numeric', 'Use symmetry and given points to find a parabola', 'The parabola $y=x^2+bx+c$ passes through $(1,2)$ and $(3,2)$. What is its minimum value?', '[]', '1', '1', 'The axis is halfway between: $x=2$, so $b=-4$. Then $1-4+c=2$ gives $c=5$, and $y=x^2-4x+5=(x-2)^2+1$. The minimum is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Axis x=2, b=-4; 1-4+c=2, c=5; (x-2)^2+1, min 1.","run_id":"claude-code","at":"2026-10-22T12:33:29.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02bfdb67-2031-4097-b317-5facd086656c', 'ALG.15', 1, 'numeric', 'Count the whole-number solutions', 'How many integers $x$ satisfy $(x+2)(x-3)\le0$?', '[]', '6', NULL, 'The product is $\le0$ from $x=-2$ to $x=3$, including both ends. The integers are $-2,-1,0,1,2,3$: 6 of them.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+2)(x-3)<=0: -2<=x<=3: -2,-1,0,1,2,3 = 6.","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
