INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2574ea28-90d5-48e9-80d8-2975272578c5', 'ALG.18', 1, 'numeric', 'Evaluating a polynomial', 'A polynomial is $3x^3 - 2x^2 + x + 4$. Plug in $x = 1$ and find the result.', '[]', '6', '3-2+1+4', 'Since $1$ to any power is 1, $p(1) = 3 - 2 + 1 + 4 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 - 2 + 1 + 4 = 6.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15022fd7-1377-40e8-b723-7096a2fda990', 'ALG.18', 2, 'choice', 'Degree and leading coefficient', 'What is the leading term of $(x^2 - 5)(2x^3 + x)$ when it is multiplied out?', '["$2x^6$","$3x^5$","$2x^5$","$x^5$"]', '$2x^5$', NULL, 'The leading term comes from multiplying the two leading terms: $x^2 \cdot 2x^3 = 2x^5$. Exponents add, and coefficients multiply.', 'checked', '{"lint":[],"solve":{"answer":"$2x^5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leading term = x^2 * 2x^3 = 2x^5. Full product: 2x^5 + x^3 - 10x^3 - 5x = 2x^5 - 9x^3 - 5x.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22c8c057-6290-40a6-ba2d-9930f41410f7', 'ALG.18', 2, 'choice', 'Adding and subtracting polynomials', 'The sides of a triangle, in centimeters, are $2x + 3$, $3x - 1$ and $x + 6$. Which expression gives the perimeter?', '["$6x + 10$","$5x + 8$","$6x + 8$","$6x + 18$"]', '$6x + 8$', NULL, 'Add the three sides: the $x$ terms give $2x + 3x + x = 6x$ and the numbers give $3 - 1 + 6 = 8$. The perimeter is $6x + 8$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+3)+(3x-1)+(x+6) = 6x + 8.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e80de6f-0739-4ca0-b1de-0af00b3cbbda', 'ALG.18', 2, 'choice', 'Roots of a polynomial', 'What is the sum of the roots of $x(x - 4)(x + 9)$?', '["5","-13","-5","9"]', '-5', '0+4-9', 'The roots are 0, 4 and $-9$. Their sum is $-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots 0, 4, -9; sum -5.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
