INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f3a5a3e-997e-4c67-806f-21535b39bdd3', 'ALG.19', 1, 'numeric', 'Solving exponential equations', 'A number $x$ makes $5^x = 125$ true. What is $x$?', '[]', '3', '3', '$5 \cdot 5 \cdot 5 = 125$, so $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"125 = 5^3, x = 3.","run_id":"claude-code","at":"2026-10-22T12:33:29.203Z"}}', 'ai', NULL, NULL)
