INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ac9495c-570d-4581-b90e-ddeec01c261c', 'ALG.19', 2, 'numeric', 'Exponential growth and decay', 'A deposit of 500 dollars doubles in value every 10 years. How many dollars will it be worth after 30 years?', '[]', '4000', '500*2^3', '30 years is 3 doubling periods. $500 \cdot 2^3 = 500 \cdot 8 = 4000$.', 'checked', '{"lint":[],"solve":{"answer":"4000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 years = 3 doublings: 500 * 8 = 4000.","run_id":"claude-code","at":"2026-10-22T12:33:29.203Z"}}', 'ai', NULL, NULL)
