INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31285004-683d-4540-8948-7c2233acfcc3', 'ALG.19', 2, 'numeric', 'Solving exponential equations', 'Solve $3^x \cdot 3^{x+1} = 243$.', '[]', '2', '2', 'The left side is $3^{2x+1}$ and $243 = 3^5$. So $2x + 1 = 5$ and $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^(2x + 1) = 243 = 3^5 -> 2x + 1 = 5 -> x = 2.","run_id":"claude-code","at":"2026-10-22T12:33:29.203Z"}}', 'ai', NULL, NULL)
