VALUES ('090e757e-2cdb-49e9-98e3-cbb160052f48', 'ALG.20', 1, 'choice', 'Solve absolute value equations', 'Which choice lists every value of $x$ that satisfies $|x| = 6$?', '["$x = 6$ only","$x = -6$ only","$x = 6$ or $x = -6$","$x = 36$ or $x = -36$"]', '$x = 6$ or $x = -6$', NULL, 'Both $6$ and $-6$ are 6 units from 0, so both work.', 'checked', '{"lint":[],"solve":{"answer":"$x = 6$ or $x = -6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numbers 6 units from 0: 6 and -6.","run_id":"claude-code","at":"2026-10-22T12:33:29.239Z"}}', 'ai', NULL, NULL)
