INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a7d1590-fc84-4e92-aa1d-1f70da091346', 'ALG.20', 2, 'numeric', 'Floor and ceiling: equations, ranges and counting', 'A recipe uses 3 eggs per batch and Sam makes 7 batches. Eggs are sold only in cartons of 12. How many cartons must Sam buy?', '[]', '2', '(21+3)/12', 'He needs $3 \cdot 7 = 21$ eggs. $21 \div 12 = 1.75$, so he must round up to 2 cartons.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Eggs needed 3 x 7 = 21; 21/12 = 1.75, so ceil = 2 cartons.","run_id":"claude-code","at":"2026-10-22T12:33:29.239Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1209b551-c0cd-4cff-9099-c7686b79ba85', 'ALG.20', 2, 'numeric', 'Evaluate piecewise-defined functions', 'Let $f(x) = 3x - 2$ for $x \le 1$ and $f(x) = x^2$ for $x > 1$. Find $f(-2) + f(3)$.', '[]', '1', '(3*(-2)-2)+3^2', '$f(-2) = 3(-2) - 2 = -8$ and $f(3) = 9$. The sum is $1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(-2) = 3(-2) - 2 = -8; f(3) = 9; sum 1.","run_id":"claude-code","at":"2026-10-22T12:33:29.239Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b5d887-e7bb-4677-995d-61ff9c5e1cd4', 'ALG.20', 2, 'numeric', 'Solve equations with piecewise-defined functions', 'Let $g(x) = x + 1$ for $x \le 0$ and $g(x) = 2x$ for $x > 0$. Find the value of $x$ for which $g(x) = -4$.', '[]', '-5', '-4-1', '$x + 1 = -4$ gives $x = -5$, and $-5 \le 0$ fits. $2x = -4$ gives $x = -2$, which is not positive. So $x = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x <= 0: x + 1 = -4 gives x = -5 (ok). x > 0: 2x = -4 gives x = -2 (rejected). x = -5.","run_id":"claude-code","at":"2026-10-22T12:33:29.239Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('022bdca7-d691-44a7-ab9b-8f6901f2a0f8', 'ALG.20', 3, 'numeric', 'Evaluate absolute value expressions', 'Let $a = |-3| - |-8|$ and $b = |-2| - 9$. Find $|a| + |b|$.', '[]', '12', '(8-3)+(9-2)', '$a = 3 - 8 = -5$, so $|a| = 5$. $b = 2 - 9 = -7$, so $|b| = 7$. The sum is $12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a = 3 - 8 = -5; b = 2 - 9 = -7; |a| + |b| = 5 + 7 = 12.","run_id":"claude-code","at":"2026-10-22T12:33:29.239Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0047d5b3-1e7f-44fb-ab32-8a72d2bc31b2', 'ALG.20', 3, 'choice', 'Solve equations with piecewise-defined functions', 'Let $f(x) = 2x + 1$ for $x < 1$ and $f(x) = x^2 + a$ for $x \ge 1$. If $f(f(0)) = 7$, what is $a$?', '["7","5","1","6"]', '6', '7-1', '$f(0) = 1$. Then $f(1) = 1^2 + a = 1 + a$. Setting $1 + a = 7$ gives $a = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = 2(0) + 1 = 1. f(1) uses x >= 1: 1 + a = 7, a = 6.","run_id":"claude-code","at":"2026-10-22T12:33:29.239Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09fbeeb7-eb45-44b9-a161-476b05794ff7', 'ALG.21', 1, 'choice', 'Arithmetic sequences: terms and common difference', 'An arithmetic sequence has first term 7 and common difference 3. What is its 5th term?', '["19","16","22","21"]', '19', '7+4*3', 'The terms are 7, 10, 13, 16, 19. The 5th term is $7 + 4 \cdot 3 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a5 = 7 + 4*3 = 19.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
