INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('032163e6-a464-4177-bb1f-c777c6aaa432', 'ALG.21', 1, 'choice', 'Geometric sequences: terms and common ratio', 'What is the common ratio of the geometric sequence 81, 27, 9, 3, …?', '["$3$","$-54$","$\\frac{1}{3}$","$\\frac{1}{27}$"]', '$\frac{1}{3}$', NULL, 'Divide any term by the one before it: $27 \div 81 = \frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27/81 = 1/3; 9/27 = 1/3.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
