INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18af32ca-3ed0-42e2-9131-20f14d5cdd77', 'ALG.21', 2, 'numeric', 'Arithmetic sequences: terms and common difference', 'The numbers 5, $x$ and 21 are three consecutive terms of an arithmetic sequence. Find $x$.', '[]', '13', '(5+21)/2', 'The middle term is the average of its neighbors: $\frac{5 + 21}{2} = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x is the average: (5 + 21)/2 = 13.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
