INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18d4be17-0102-4fd5-bca8-14469616c7a7', 'ALG.21', 2, 'numeric', 'Sequences and series: rules, notation and applications', 'A ball is dropped from 80 centimeters and bounces back up to half of its previous height each time. How high, in centimeters, does it go on its third bounce?', '[]', '10', '80/2/2/2', 'The bounces reach 40, 20 and 10 centimeters. So the third bounce reaches $10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bounce heights 40, 20, 10. Third bounce reaches 10 cm.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
