INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('098dfb38-933b-4d3c-be0e-1e6a2c2c562b', 'BA2.03', 3, 'choice', 'Addition stories and missing numbers', 'Zoe has 55 blocks. Ned has 14 more than Zoe. Val has 17 more than Ned. How many blocks do the three children have in all?', '["200","210","220","110"]', '210', '55+69+86', 'Ned has 55 + 14 = 69. Val has 69 + 17 = 86. Total: 55 + 69 + 86 = 210.', 'checked', '{"lint":[],"solve":{"answer":"210","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zoe 55, Ned 69, Val 86. 55 + 69 + 86 = 210.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
