INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('140e078d-7ea5-4303-a35b-986e4220c2a7', 'BA2.04', 2, 'choice', 'Subtracting three-digit numbers', 'Which number is $732 - 464$? Be careful when you regroup.', '["332","268","278","258"]', '268', '732-464', 'Ones: 2 is less than 4, so regroup 1 from the next place: 12 - 4 = 8. Tens: 3 - 1 = 2, and 2 is less than 6, so regroup 1 from the next place: 12 - 6 = 6. Hundreds: 7 - 1 = 6, then 6 - 4 = 2. The difference is 268.', 'checked', '{"lint":[],"solve":{"answer":"268","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"732 - 464 = 268.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
