INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ee7d3ae-6b26-48d6-b23b-c92d0bbfdb58', 'BA2.04', 2, 'numeric', 'Regrouping and mental subtraction', 'To work out $67 - 29$, Val regroups 67 as 5 tens and 17 ones. What is $67 - 29$?', '[]', '38', '67-29', '17 - 9 = 8 ones. 5 - 2 = 3 tens. So the answer is 38.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 tens 17 ones - 2 tens 9 ones = 3 tens 8 ones = 38.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
