INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('052a73d0-1085-4b99-ab7b-cd1cc4f3470b', 'BA2.08', 3, 'choice', 'Find the last number of a list', 'A book is 75 pages long, and its first page is numbered 120. Pages are numbered by ones. What is the number of the last page?', '["195","194","196","45"]', '194', '120+75-1', 'The last page is 74 more than the first. 120 + 74 = 194.', 'checked', '{"lint":[],"solve":{"answer":"194","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 + 75 - 1 = 194.","run_id":"claude-code","at":"2026-10-19T01:23:03.680Z"}}', 'ai', NULL, NULL)
