VALUES ('0b6e1530-dd24-4bc2-aafd-334585fdfe3b', 'BA2.10', 1, 'choice', 'Comparing and ordering big numbers', 'Which sentence is true?', '["$2{,}650 < 2{,}560$","$2{,}650 > 2{,}560$","$3{,}045 > 3{,}450$","$1{,}200 = 1{,}020$"]', '$2{,}650 > 2{,}560$', NULL, 'Both 2,650 and 2,560 have 2 thousands. 2,650 has 6 hundreds and 2,560 has 5 hundreds, so 2,650 is greater. The other sentences are not true.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}650 > 2{,}560$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,650 has 6 hundreds vs 5 hundreds, so it is greater. Others are false.","run_id":"claude-code","at":"2026-10-19T01:26:38.791Z"}}', 'ai', NULL, NULL)
