INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b1c497a-d8b7-428c-bf49-308358df90ae', 'BA2.11', 1, 'choice', 'Missing digits in a difference', '$63 - 4\square = 15$ What digit goes in the box?', '["8","9","7","6"]', '8', NULL, 'The number taken away is the first number minus the difference: 63 - 15 = 48. So the full equation is 63 - 48 = 15, and the missing digit is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"63-15=48, box 8.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
