INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('161e0238-3fb1-4969-97f1-feedcabebb6e', 'BA2.11', 2, 'choice', 'Missing digits in a sum', '$79A + B8 = 866$ Each letter stands for one digit. What digit is A?', '["9","8","7","6"]', '8', NULL, 'Work column by column, starting with the ones, and check each column (including any regrouped 1). The only way to fill in every gap is 798 + 68 = 866. So A = 8, B = 6.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"866-790=76 = A + B8, so A+10B=68: B=6, A=8. 798+68=866.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
