ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c21f682-5ff3-4eea-8d74-309efbca07da', 'BA2.11', 3, 'choice', 'Addition and subtraction stories', 'A truck carried $6{,}000$ bricks. It left $2{,}591$ bricks at one house and $1{,}843$ bricks at another house. How many bricks were still on the truck?', '["$1{,}576$","$1{,}566$","$1{,}466$","$1{,}666$"]', '$1{,}566$', NULL, 'Bricks left at the houses: $2{,}591$ + $1{,}843$ = $4{,}434$. Bricks still on the truck: $6{,}000$ - $4{,}434$ = $1{,}566$.', 'checked', '{"lint":[],"solve":{"answer":"$1{,}566$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6000-2591=3409; 3409-1843=1566.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
