INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b198cef-fdb5-4cbc-ab39-9f3429249c87', 'BA2.12', 1, 'numeric', 'Working backwards and guess and check', 'I think of a number and double it. My answer is 10. What number did I think of?', '[]', '5', '10/2', 'Doubling makes a number twice as big, so undo it by halving. Half of 10 is 5. Check: 5 + 5 = 10.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/2=5.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
