INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e7e21bc-bf7a-4eb5-b7d9-15d802c84983', 'BA3.02', 2, 'choice', 'Finding the nth number in a skip-counting list', 'What is the 9th number in the list $2, 5, 8, \ldots$?', '["24","27","26","29"]', '26', '2+8*3', 'The list goes up by 3. There are 8 jumps from the 1st number to the 9th. 2 + 8 x 3 = 26.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 8 x 3 = 26.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
