VALUES ('245cbc5a-01bd-4a89-b862-5a6f91107491', 'BA3.02', 2, 'choice', 'Finding the nth number in a skip-counting list', 'Count backward by 4s: $50, 46, 42, \ldots$ What is the 8th number you say?', '["18","22","24","26"]', '22', '50-7*4', 'There are 7 jumps from the 1st number to the 8th. 7 x 4 = 28 and 50 - 28 = 22.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 7 x 4 = 22.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
