INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('232f5465-9929-4c48-ab3d-1f6813e034c4', 'BA3.07', 2, 'numeric', 'Balance puzzles', 'A balance is level. The left pan holds 2 identical cubes and a 5 gram weight. The right pan holds 17 grams. How many grams does one cube weigh?', '[]', '6', '(17-5)/2', 'The 2 cubes weigh $17 - 5 = 12$ grams, so one cube weighs $12 \div 2 = 6$ grams.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2c + 5 = 17, 2c = 12, c = 6.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
