INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a3699a8-43a4-4d51-82f4-357770505e0a', 'BA3.07', 3, 'choice', 'Balance puzzles', 'A balance is level. The left pan holds 4 identical cups. The right pan holds 2 of the same cups, a 12 gram weight and a 6 gram weight. How many grams does one cup weigh?', '["18","36","9","12"]', '9', '(12+6)/2', 'Take 2 cups off each pan. Then 2 cups balance $12 + 6 = 18$ grams, so one cup weighs $18 \div 2 = 9$ grams.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4c = 2c + 18, c = 9.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
