INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00f329b3-e6c0-4ca8-8969-c33d09d427b5', 'BA3.11', 3, 'choice', 'Deciding whether an answer is reasonable', 'Tom has 700 dollars. A sofa costs 342 dollars, a table costs 251 dollars and a lamp costs 118 dollars. Tom rounds each price to the nearest 100 dollars and adds them to get 700 dollars. Can Tom buy all three things with his 700 dollars? Choose the sentence that is correct.', '["Yes, because the rounded prices add up to exactly 700 dollars, which is enough.","Yes, because the exact prices add up to 691 dollars, which is less than 700 dollars.","No, because the sofa and the table alone add up to more than 700 dollars.","No, because the exact prices add up to 711 dollars, which is more than 700 dollars."]', 'No, because the exact prices add up to 711 dollars, which is more than 700 dollars.', NULL, 'Rounding gives 300 + 300 + 100 = 700, but a rounded sum is only an estimate and it is exactly at the limit, so it cannot decide. Add the real prices: 342 + 251 + 118 = 711. That is more than 700 dollars, so Tom does not have enough.', 'checked', '{"lint":[],"solve":{"answer":"No, because the exact prices add up to 711 dollars, which is more than 700 dollars.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exact total: 342 + 251 + 118 = 711, which is more than 700, so Tom cannot buy all three. Option A is wrong (the estimate hides the overage), B has the wrong sum, D is false (342 + 251 = 593 < 700). C is correct.","run_id":"claude-code","at":"2026-10-22T12:51:48.907Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
