INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07249e26-2f6b-4775-bb65-3530bc748de6', 'BA4.01', 3, 'numeric', 'Angles of isosceles and equilateral triangles', 'In an isosceles triangle, each of the two equal base angles is $15^\circ$ bigger than the top angle. How many degrees is the top angle?', '[]', '50', '(180-30)/3', 'If the top angle is t, the base angles are t + 15 each. So 3t + 30 = 180, 3t = 150 and t = 50.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t + 2(t + 15) = 180, 3t = 150, t = 50 (base angles 65).","run_id":"claude-code","at":"2026-10-19T01:26:44.069Z"}}', 'ai', NULL, NULL)
