VALUES ('1469e0aa-606f-4425-9992-aa99b13efe50', 'BA4.02', 2, 'choice', 'Multiplying by multiples of 10, 100 and 1,000', 'A school orders 30 boxes of crayons. Each box has 120 crayons. How many crayons is that?', '["$3{,}600$","$360$","$36{,}000$","$450$"]', '$3{,}600$', NULL, '3 x 12 = 36, and the two zeros (one from 30, one from 120) are added back: 3,600.', 'checked', '{"lint":[],"solve":{"answer":"$3{,}600$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 x 120 = 3,600.","run_id":"claude-code","at":"2026-10-19T01:26:44.107Z"}}', 'ai', NULL, NULL)
