VALUES ('1993ed9f-4d80-44c2-a821-9013a345efb3', 'BA4.02', 2, 'numeric', 'Missing digits, missing factors and multiplication word problems', 'Ben reads 35 pages a day for 21 days. His book has 800 pages. How many pages has he NOT read yet?', '[]', '65', '800-35*21', '35 x 21 = 700 + 35 = 735. Then 800 - 735 = 65.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35 x 21 = 735; 800 - 735 = 65.","run_id":"claude-code","at":"2026-10-19T01:26:44.107Z"}}', 'ai', NULL, NULL)
