VALUES ('112dd4d6-8034-4d50-9149-868cd5ee749c', 'BA4.02', 3, 'numeric', 'Missing digits, missing factors and multiplication word problems', 'A hall has 24 rows of 38 seats downstairs and 16 rows of 42 seats upstairs. How many seats are there in all?', '[]', '1584', '24*38+16*42', 'Downstairs: 24 x 38 = 912. Upstairs: 16 x 42 = 672. 912 + 672 = 1,584.', 'checked', '{"lint":[],"solve":{"answer":"1584","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 x 38 = 912; 16 x 42 = 672; total 1,584.","run_id":"claude-code","at":"2026-10-19T01:26:44.107Z"}}', 'ai', NULL, NULL)
