INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ae34905-4cf9-43de-a358-b249f1405ff5', 'BA4.06', 1, 'choice', 'Deciding what must be true', 'If it rains, the school picnic is held indoors. It rained on Saturday. Where was the picnic held?', '["Outdoors","At the park","Indoors","It was cancelled"]', 'Indoors', NULL, 'The rule says rain means the picnic is indoors. It rained, so it was held indoors.', 'checked', '{"lint":[],"solve":{"answer":"Indoors","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"It rained, so indoors.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
