INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03b7e043-4111-4d16-b3e6-0332bfbef2ad', 'BA4.07', 1, 'numeric', 'Prime factorization', '$12 = 2 \times 2 \times ?$ and all the numbers in the product are prime. What is the missing number?', '[]', '3', '12/4', '2 x 2 = 4 and 4 x 3 = 12. So the missing prime is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 2 x 2 x 3. Missing number 3.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
