VALUES ('1cb99148-9f08-4e5d-87f7-a4b232436b88', 'BA4.07', 1, 'choice', 'Common multiples and least common multiple', 'What is the least common multiple of 5 and 10?', '["5","10","15","50"]', '10', '10', '10 is a multiple of 5 and of 10 itself. No smaller number is a multiple of 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 is a multiple of 5; LCM 10.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
