INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0882bec7-c436-4f14-a83d-478c298c534e', 'BA4.08', 2, 'numeric', 'Equivalent fractions', 'A recipe uses $\frac{2}{3}$ cup of milk. How many sixths of a cup is that?', '[]', '4', '2*2', '3 x 2 = 6, so multiply the top by 2: 2 x 2 = 4. So 2/3 cup is 4/6 cup, which is 4 sixths.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6: 4 sixths.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
