INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b65e915-8b54-4f4c-99da-47d8fd17a8eb', 'BA4.08', 3, 'choice', 'Equivalent fractions', 'A fraction is equal to $\frac{2}{5}$. Its numerator and denominator add up to 35. What is its numerator?', '["14","25","5","10"]', '10', '2*35/7', 'In 2/5 the top and bottom add to 2 + 5 = 7. To reach 35 we multiply the top and bottom by 35 / 7 = 5, giving 10/25. Check: 10 + 25 = 35. The numerator is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2k + 5k = 35, k = 5: 10/25. Numerator 10.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0689e884-09ab-412f-95d5-e4b4a7c1ac32', 'BA4.08', 3, 'choice', 'Simplest form', 'How many fractions with a denominator of 12 and a numerator from 1 to 11 are already in simplest form?', '["3","5","4","6"]', '4', '4', 'The numerator and 12 must share no factor but 1. Numerators 1, 5, 7 and 11 work. The others (2, 3, 4, 6, 8, 9, 10) share 2 or 3 with 12. So 4 fractions.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerators 1-11 sharing no factor with 12: 1, 5, 7, 11. Count 4.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
