VALUES ('1ac1a950-0af6-404c-9792-fc52135c129a', 'BA4.09', 1, 'choice', 'Negative numbers and opposites', 'Which number is the opposite of 7?', '["$-7$","$7$","$0$","$-17$"]', '$-7$', '-7', 'The opposite of a number is the same distance from 0 on the other side. The opposite of 7 is -7.', 'checked', '{"lint":[],"solve":{"answer":"$-7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The opposite of 7 is -7.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
