VALUES ('0deac727-1f36-4d5e-8de1-9c082308c964', 'BA4.09', 1, 'numeric', 'Distance between integers', 'What is the distance between $-4$ and 0?', '[]', '4', '4', 'From -4 to 0 is 4 steps.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-4 - 0| = 4.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
