INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('233c6c14-d888-42af-93cb-8a79977ed9c7', 'BA4.09', 2, 'choice', 'Negative numbers and opposites', 'Which statement is true?', '["A negative number is greater than its opposite","The opposite of a positive number is positive","Zero is its own opposite","Every integer is greater than its opposite"]', 'Zero is its own opposite', NULL, '0 is the same distance from 0 as itself, so it is its own opposite. A negative number is always less than its opposite, and the opposite of a positive number is negative. Because 0 is not greater than itself, "every integer is greater than its opposite" is false too.', 'checked', '{"lint":[],"solve":{"answer":"Zero is its own opposite","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 = -0, true. A negative is less than its positive opposite; the opposite of a positive is negative; negatives and 0 are not greater than their opposites.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
