VALUES ('02efae68-59eb-4ec0-8d0d-298a0af27336', 'BA4.09', 2, 'choice', 'Elevation stories', 'A submarine is at $-45$ meters. It rises 20 meters and then dives 35 meters. What is its elevation now, in meters?', '["$-10$","$-100$","$10$","$-60$"]', '$-60$', '-45+20-35', '-45 + 20 = -25. Then -25 - 35 = -60 meters.', 'checked', '{"lint":[],"solve":{"answer":"$-60$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-45 + 20 = -25; -25 - 35 = -60.","run_id":"claude-code","at":"2026-10-19T01:30:24.816Z"}}', 'ai', NULL, NULL)
