VALUES ('07651cc7-427b-46ae-81c4-683144cd6ed1', 'BA4.10', 1, 'choice', 'Subtracting fractions with unlike denominators', 'What is $\frac{7}{10} - \frac{1}{5}$?', '["$\\frac{6}{5}$","$\\frac{3}{5}$","$\\frac{4}{5}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, '1/5 = 2/10, so 7/10 - 2/10 = 5/10 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/10 - 2/10 = 5/10 = 1/2.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
