INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02a3767b-a5c5-41d1-a02a-c1c3148b3809', 'BA4.10', 2, 'choice', 'Adding and subtracting mixed numbers with unlike denominators', 'A board is $4\frac{1}{2}$ feet long. Dan cuts off a piece that is $1\frac{3}{4}$ feet long. How long is the board that is left?', '["$3\\frac{1}{4}$","$2\\frac{1}{4}$","$3\\frac{3}{4}$","$2\\frac{3}{4}$"]', '$2\frac{3}{4}$', NULL, '4 1/2 = 4 2/4. Since 2/4 is less than 3/4, change 4 2/4 into 3 6/4. Then 3 6/4 - 1 3/4 = 2 3/4 feet.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 2/4 - 1 3/4 = 3 6/4 - 1 3/4 = 2 3/4.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
