INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066134cb-b811-440d-85f6-19b89213ea38', 'BA4.06', 3, 'choice', 'Truth-tellers and liars: several speakers', 'One of four friends broke a vase. Gus says: "Hana broke it." Hana says: "Ivy broke it." Ivy says: "Hana is lying." Jo says: "I did not break it." Exactly one of the four friends is lying. Who broke the vase?', '["Gus","Ivy","Hana","Jo"]', 'Hana', NULL, 'Try each friend as the one who broke the vase, and count how many of the four are lying. If Gus broke it, Gus and Hana both lie: 2 liars. If Ivy broke it, Gus and Ivy both lie: 2 liars. If Jo broke it, Gus, Hana and Jo all lie: 3 liars. If Hana broke it, only Hana lies, because she said Ivy did it; Gus, Ivy and Jo tell the truth. That is exactly 1 liar, so Hana broke the vase.', 'checked', '{"lint":[],"solve":{"answer":"Hana","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gus (Hana) and Hana (Ivy) cannot both be true, so the one liar is Gus or Hana. If Gus lies, Hana is truthful, so Ivy''s ''Hana is lying'' is false: two liars, impossible. So Hana lies, Gus is truthful: Hana broke it. Check: Ivy true, Jo true. Exactly one liar.","run_id":"claude-code","at":"2026-10-22T12:51:48.907Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
