VALUES ('01c54e6d-18d5-4e79-9059-7bdb24c397bc', 'BA5.02', 3, 'choice', 'Multiplying and dividing integers', 'Four scores in a game are $-6$, 3, $-9$ and 4. What is their mean (the sum divided by 4)?', '["-8","2","-4","-2"]', '-2', '(-6+3-9+4)/4', 'The sum is $-6 + 3 - 9 + 4 = -8$. And $-8 \div 4 = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6 + 3 - 9 + 4 = -8; -8 / 4 = -2.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
