VALUES ('07c39119-9fdb-4101-b132-6252783c57ee', 'BA5.02', 3, 'numeric', 'Order of operations with integers', 'What is $100 \div (-5) \div (-2) + (-4) \times (-3) \times (-2)$?', '[]', '-14', '100/-5/-2+(-4)*(-3)*(-2)', 'First part: $100 \div (-5) = -20$, then $-20 \div (-2) = 10$. Second part: $(-4) \times (-3) = 12$, and $12 \times (-2) = -24$. Total $10 + (-24) = -14$.', 'checked', '{"lint":[],"solve":{"answer":"-14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 / -5 = -20; -20 / -2 = 10; (-4)(-3)(-2) = -24; 10 - 24 = -14.","run_id":"claude-code","at":"2026-10-19T01:36:23.635Z"}}', 'ai', NULL, NULL)
