INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29a6ed5a-d6c1-4d04-9373-f7be5dae577f', 'BA5.03', 1, 'numeric', 'Combining like terms', 'There are $n$ pens in each of 4 cups and $n$ pens in each of 5 boxes. The total number of pens is $?n$. What number is the ?', '[]', '9', '4+5', 'There are 4 + 5 = 9 groups of $n$ pens, so the total is $9n$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 cups give 4n, 5 boxes give 5n; total 4n + 5n = 9n.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
