INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06276877-4537-4811-aa4c-b1ed9f40accd', 'BA5.04', 2, 'numeric', 'Finding the range', 'The range of a list is 24 and its smallest number is 17. What is the largest number?', '[]', '41', '17+24', 'Largest = smallest + range = $17 + 24 = 41$.', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 + 24 = 41.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
