VALUES ('1760c597-14c4-420e-8fef-e7f5f965001c', 'BA5.05', 1, 'choice', 'Greatest common factor', 'What is the greatest common factor of 7 and 14?', '["14","7","2","1"]', '7', '7', '7 divides 7 and also divides 14, and nothing bigger divides 7. So the greatest common factor is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 divides 14; gcd 7.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
