VALUES ('07f73aca-0aea-4cd6-8063-b81daeeb37ce', 'BA5.05', 1, 'choice', 'Least common multiple', 'What is the least common multiple of 4 and 6?', '["24","2","12","18"]', '12', '12', 'Multiples of 4: 4, 8, 12. Multiples of 6: 6, 12. The least shared multiple is 12. (24 is also a common multiple, but not the least.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(4,6)=12.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
