INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('031c89aa-b534-480e-b71b-f33117c994f5', 'BA5.05', 2, 'numeric', 'Greatest common factor', 'What is the greatest number that is a factor of all three of 16, 24 and 40?', '[]', '8', '8', '16 = 8 x 2, 24 = 8 x 3 and 40 = 8 x 5, and 2, 3 and 5 share no factor. So the greatest common factor is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"gcd(16,24,40)=8.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
