INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('181019a4-3071-4d36-9aaa-1be83dff99ee', 'BA5.05', 3, 'numeric', 'Greatest common factor', 'The greatest common factor of 45 and another number is 9. The other number is between 50 and 60. What is it?', '[]', '54', '54', 'The other number is a multiple of 9, and the only multiple of 9 between 50 and 60 is 54. Check: 45 = 9 x 5 and 54 = 9 x 6, and 5 and 6 share no factor.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Must be multiple of 9 in 50-60: only 54. gcd(45,54)=9.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
