INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08ec7bbd-c32b-4862-872f-15a8ae8f9adc', 'BA5.06', 1, 'choice', 'Dividing fractions', 'What is $\frac{1}{2} \div 3$?', '["$\\frac{3}{2}$","6","$\\frac{1}{6}$","$\\frac{2}{3}$"]', '$\frac{1}{6}$', NULL, 'Dividing by 3 is the same as multiplying by $\frac{1}{3}$: $\frac{1}{2} \times \frac{1}{3} = \frac{1}{6}$. Cutting a half into 3 equal parts gives sixths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 1/3 = 1/6.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
