INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('153de3b8-9d49-4460-bf82-1b3bcfab8299', 'BA5.06', 1, 'numeric', 'Dividing with whole numbers and mixed numbers', 'A rope is 8 meters long. It is cut into pieces that are each $\frac{1}{4}$ meter long. How many pieces are there?', '[]', '32', '8/(1/4)', 'Each meter makes 4 pieces, so 8 meters make 8 x 4 = 32 pieces.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 / (1/4) = 32.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
