INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e58da4c-2bca-4817-a53c-1037ff942982', 'BA5.06', 2, 'choice', 'Fraction stories with several steps', 'Dan reads $\frac{2}{5}$ of his book on Monday. On Tuesday he reads $\frac{1}{2}$ of the REST of the book. What fraction of the whole book has he read by the end of Tuesday?', '["$\\frac{7}{10}$","$\\frac{9}{10}$","$\\frac{3}{10}$","$\\frac{3}{5}$"]', '$\frac{7}{10}$', NULL, 'After Monday $\frac{3}{5}$ is left. Half of that is $\frac{3}{10}$. In all: $\frac{2}{5} + \frac{3}{10} = \frac{4}{10} + \frac{3}{10} = \frac{7}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 + 1/2 x 3/5 = 2/5 + 3/10 = 7/10.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('115caa78-57c8-406f-aff9-8567e01a5266', 'BA5.06', 3, 'numeric', 'Reciprocals', 'What is the reciprocal of the product $\frac{3}{5} \times \frac{10}{9}$? Write your answer as a fraction or a mixed number.', '[]', '3/2', '(5*9)/(3*10)', '$\frac{3}{5} \times \frac{10}{9} = \frac{30}{45} = \frac{2}{3}$. The reciprocal of $\frac{2}{3}$ is $\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 x 10/9 = 30/45 = 2/3; reciprocal 3/2.","run_id":"claude-code","at":"2026-10-19T01:35:32.506Z"}}', 'ai', NULL, NULL)
