VALUES ('29996eb9-f69c-4e66-a6ae-889f0089b3d3', 'BA5.11', 3, 'choice', 'Square roots of whole numbers', 'The square root of a number is 17. What is the number?', '["34","144","187","289"]', '289', '17*17', 'The number is 17 times 17. 17 times 17 = 170 + 119 = 289.', 'checked', '{"lint":[],"solve":{"answer":"289","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17^2=289","run_id":"claude-code","at":"2026-10-19T01:39:00.540Z"}}', 'ai', NULL, NULL)
