INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be07425-5dfb-44a9-b0f5-55d6062de9a4', 'BA5.12', 1, 'numeric', 'Evaluating powers', 'What is $3^{4}$?', '[]', '81', '3*3*3*3', '3 to the 4th power means 3 times 3 times 3 times 3. 3 times 3 is 9, 9 times 3 is 27, and 27 times 3 is 81.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^4=3*3*3*3=81","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ccae4d0-0ffd-4158-b272-f8354b952b26', 'BA5.12', 1, 'choice', 'Powers of powers', 'Ana says $(2^3)^2 = 2^5$. Dan says $(2^3)^2 = 2^6$. Who is right?', '["Dan, because 3 times 2 is 6","Ana, because 3 + 2 is 5","Neither, because the answer is $2^9$","Both are right"]', 'Dan, because 3 times 2 is 6', NULL, '$(2^3)^2 = 2^3 \times 2^3$, which is six 2s multiplied, so it is $2^6$. In a power of a power you multiply the exponents (3 times 2 = 6), not add them.', 'checked', '{"lint":[],"solve":{"answer":"Dan, because 3 times 2 is 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2^3)^2=2^3*2^3=2^6; Dan","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06f606fc-d8a6-4248-926c-5cd45aa072d5', 'BA5.12', 1, 'choice', 'Last digit of a power', 'What is the last digit of $10^{7}$?', '["1","7","5","0"]', '0', '0', 'Every power of 10 is a 1 followed by zeros ($10^7$ is 10,000,000), so it ends in 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10^7 ends in 0","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
