INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0448e628-4327-41ab-849e-ecf1eae65c6c', 'BA5.12', 2, 'numeric', 'Last digit of a power', 'What is the last digit of $3^{20}$?', '[]', '1', '1', 'The last digits of powers of 3 go 3, 9, 7, 1, then repeat every 4 powers. 20 is a multiple of 4, so $3^{20}$ ends where the cycle ends, in 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3: 3,9,7,1 cycle of 4; 20 divisible by 4 -> 1","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
