INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f3edff-a570-488a-82cf-4a46c559fca7', 'GEO.01', 1, 'numeric', 'Naming polygons', 'A polygon is named $ABCDEFG$, using seven letters. How many sides does it have?', '[]', '7', '7', 'Each letter is a vertex, and a polygon has as many sides as vertices. So it has $7$ sides.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Seven vertices give seven sides.","run_id":"claude-code","at":"2026-10-22T19:38:47.909Z"}}', 'ai', NULL, NULL)
