INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01887946-b000-4492-ac15-73eee4b39404', 'GEO.01', 1, 'choice', 'Counting segments', 'Seven fence posts stand in a straight row. A string is stretched between every two posts. How many strings are needed?', '["42","21","14","28"]', '21', '7*6/2', 'Each post is joined to $6$ others, giving $7 \times 6 = 42$ ends, but every string has two ends. So there are $\frac{7 \times 6}{2} = 21$ strings.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(7,2)=21.","run_id":"claude-code","at":"2026-10-22T19:38:47.909Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00adc4cb-413f-4ab7-b2d2-9457b2ab5812', 'GEO.01', 2, 'choice', 'Lines, segments and rays', 'Points $A$, $B$ and $C$ lie on a line in that order. Which statement is true?', '["Segment $AC$ is part of segment $AB$","Segment $AB$ is part of ray $AC$","Ray $BA$ is part of segment $AB$","Ray $AB$ is the same figure as segment $AB$"]', 'Segment $AB$ is part of ray $AC$', NULL, 'Ray $AC$ starts at $A$ and passes through $B$ on its way to $C$, so it contains segment $AB$. A longer figure cannot be part of a shorter one, and a ray never stops, so it cannot be a segment or inside one.', 'checked', '{"lint":[],"solve":{"answer":"Segment $AB$ is part of ray $AC$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ray AC starts at A through B and C, so it contains segment AB. Others false.","run_id":"claude-code","at":"2026-10-22T19:38:47.909Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aaf61e4-2126-4979-a14e-353a25577102', 'GEO.01', 2, 'numeric', 'Counting triangles', 'Six trees are planted so that no three are in a line. Three of the trees are chosen as the corners of a triangle. How many different triangles can be made?', '[]', '20', '6*5*4/6', 'There are $6 \times 5 \times 4 = 120$ ways to pick three trees in order, and each triangle is counted $6$ times, so there are $\frac{120}{6} = 20$ triangles.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(6,3)=20.","run_id":"claude-code","at":"2026-10-22T19:38:47.909Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('078440ca-d0bf-46fe-b7ea-5ecfca87472b', 'GEO.01', 2, 'numeric', 'Counting triangles', 'Seven points are in a plane, and no three of them are on one line. Point $P$ is one of the seven. How many triangles with all three corners among the seven points do not have $P$ as a corner?', '[]', '20', '6*5*4/6', 'Leave $P$ out. The corners come from the other $6$ points, in $\frac{6 \times 5 \times 4}{3 \times 2 \times 1} = 20$ ways. No three points are on one line, so each choice of three points is a triangle.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangles without P use 3 of the other 6 points, no three collinear: C(6,3) = 20.","run_id":"claude-code","at":"2026-10-23T00:30:06.000Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bb36064-6577-4ba0-ad1a-19bacbe2ac4a', 'GEO.01', 3, 'numeric', 'Naming angles', 'Point $D$ is on side $BC$ of triangle $ABC$, between $B$ and $C$, and segment $AD$ is drawn. How many different angles, each less than $180^\circ$, are formed by pairs of the drawn segments, with vertex $A$, $B$, $C$ or $D$? Count $\angle ABC$ and $\angle ABD$ as the same angle, since they have the same sides.', '[]', '7', '3+1+1+2', 'At $A$ the rays $AB$, $AD$ and $AC$ give $3$ angles. At $B$ there is $1$ angle and at $C$ there is $1$. At $D$ the rays $DA$, $DB$ and $DC$ give $\angle ADB$ and $\angle ADC$, while $\angle BDC$ is a straight angle of $180^\circ$ and is not counted. In all, $3 + 1 + 1 + 2 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At A: BAD, DAC, BAC (3). At B: ABC (1). At C: ACB (1). At D: ADB, ADC (2; BDC is straight). Total 7.","run_id":"claude-code","at":"2026-10-22T19:38:47.909Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0900b174-54ac-4a73-9dfe-9cf2422ec967', 'GEO.01', 3, 'choice', 'Counting lines', 'Four points are in a plane. Which of these CANNOT be the number of different lines that pass through at least two of the points?', '["1","4","5","6"]', '5', NULL, 'If all $4$ points are collinear there is $1$ line. If $3$ are collinear and one is off the line there are $1 + 3 = 4$ lines. If no three are collinear there are $6$ lines. No arrangement gives $5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four points give 1 (all collinear), 4 (exactly three collinear) or 6 (none three). Two collinear triples among 4 points force all 4 collinear, so 5 is impossible.","run_id":"claude-code","at":"2026-10-22T19:38:47.909Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bb6b39e-421b-4758-85d7-14a27776e6d0', 'GEO.02', 1, 'numeric', 'Parallel lines and a transversal', 'A line crosses two parallel lines. At the first crossing, one of the angles measures 65 degrees. The corresponding angle at the second crossing measures how many degrees?', '[]', '65', '65', 'When a line crosses two parallel lines, corresponding angles are equal. So the angle is also 65 degrees.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles at parallel lines are equal: 65.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14e4530c-991f-4561-a75f-8619de26b850', 'GEO.02', 1, 'numeric', 'Interior angle sum of a polygon', 'From one corner of a polygon, diagonals are drawn that split it into 5 triangles. How many sides does the polygon have?', '[]', '7', '5+2', 'A polygon with $n$ sides splits into $n-2$ triangles. So $n-2=5$ and $n=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Diagonals from one vertex split an n-gon into n-2 triangles. n - 2 = 5, n = 7.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('075884fc-af37-4e64-b8f5-aa492d5fc298', 'GEO.02', 1, 'numeric', 'Angle bisectors and angles around a point', 'An angle of 80 degrees is cut into two equal angles by its bisector. How many degrees is each of the two angles?', '[]', '40', '80/2', 'A bisector splits an angle into two equal parts. Each part is $80\div2=40$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80/2 = 40.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
