INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05aa0ad8-5914-4f64-87e7-d9966b1742d2', 'GEO.02', 2, 'choice', 'Exterior angle of a triangle', 'An exterior angle of a triangle measures $130^\circ$. The two interior angles that are not next to it are equal. What does each of them measure?', '["$130$","$50$","$65$","$25$"]', '$65$', '130/2', 'The exterior angle equals the sum of those two equal angles, so each is $130\div2=65$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"$65$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The two remote interior angles sum to 130; equal, so 65 each.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
