INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ae245fa-f04f-49c0-afa9-b2fdb3bd6c50', 'GEO.17', 2, 'choice', 'Equations of circles', 'Which of these points is inside the circle $x^2 + y^2 = 36$?', '["$(4, 5)$","$(5, 3)$","$(6, 1)$","$(-5, -4)$"]', '$(5, 3)$', NULL, 'A point is inside when $x^2 + y^2 < 36$. The four points give $34$, $41$, $37$ and $41$. Only $(5, 3)$ is inside.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5,3):34<36 inside; (4,5):41; (6,1):37; (-5,-4):41.","run_id":"claude-code","at":"2026-10-23T00:09:47.384Z"}}', 'ai', NULL, NULL)
