INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('120a8f5d-a756-40b9-9ecf-280fc434c9ba', 'NC17.1.OA.1', 2, 'numeric', 'Take from: start unknown', 'Some kids were on the swings. 5 kids left. Now 8 kids are on the swings. How many kids were on the swings at first?', '[]', '13', '8+5', 'Think ? - 5 = 8. The 5 who left and the 8 who stayed make 8 + 5 = 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? - 5 = 8, so 13.","run_id":"claude-code","at":"2026-10-24T02:55:27.632Z"}}', 'ai', NULL, NULL)
