INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0757a63c-3c10-4818-bd20-198829aa0537', 'NC17.1.MD.1', 3, 'numeric', 'Count objects compared with a third object', 'Kim uses a string to compare 3 things. The shoe is longer than the string. The book is shorter than the string. The plate is longer than the string. How many of the 3 things are longer than the book?', '[]', '2', '2', 'The book is shorter than the string. The shoe and the plate are both longer than the string, so both are longer than the book. The book is not longer than itself. So 2 things are longer than the book.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"shoe > string, plate > string, book < string. Longer than book: shoe, plate = 2.","run_id":"claude-code","at":"2026-10-24T08:22:27.614Z"}}', 'ai', NULL, NULL)
