INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('074f5b69-ebc9-4c2d-8e6d-77498fcaf5f5', 'NC17.2.NBT.3', 3, 'choice', 'Fix a mistake in writing a number', 'Jax wrote nine hundred fifty as $900 + 5$. Which sum shows nine hundred fifty in expanded form?', '["$900 + 5$","$90 + 50$","$900 + 500$","$900 + 50$"]', '$900 + 50$', NULL, 'Nine hundred fifty is 900 and 50. Jax used 5 ones instead of 5 tens.', 'checked', '{"lint":[],"solve":{"answer":"$900 + 50$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nine hundred fifty = 9 hundreds + 5 tens = 900 + 50.","run_id":"claude-code","at":"2026-10-28T19:34:46.264Z"}}', 'ai', NULL, NULL)
