INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('188c5a4d-3098-4650-ba75-064bffd56c72', 'NC17.2.NBT.4', 1, 'numeric', 'Find the greater or lesser of two numbers', 'Mia has 305 beads. Leo has 503 beads. How many beads does the child with fewer beads have?', '[]', '305', NULL, '305 has 3 hundreds and 503 has 5 hundreds. 305 is less, so the child with fewer beads has 305.', 'checked', '{"lint":[],"solve":{"answer":"305","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds 3<5, so Mia has fewer: 305.","run_id":"claude-code","at":"2026-10-24T03:05:01.840Z"}}', 'ai', NULL, NULL)
