VALUES ('022b7656-4bc6-4534-8ac8-7e10744d5bb9', 'NC17.2.NBT.4', 1, 'numeric', 'Order three-digit numbers', 'Which number is the least: 726, 267 or 672? Type that number.', '[]', '267', NULL, 'Look at the hundreds: 7, 2 and 6. The least hundreds digit is 2, so 267 is the least.', 'checked', '{"lint":[],"solve":{"answer":"267","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds 7,2,6: least 267.","run_id":"claude-code","at":"2026-10-24T03:05:01.840Z"}}', 'ai', NULL, NULL)
