VALUES ('10f0c586-6c5e-4833-8c60-ea35009ae015', 'NC17.2.NBT.4', 1, 'choice', 'Find a number greater or less than a given number', 'Which number is greater than 450?', '["405","445","540","450"]', '540', NULL, '540 has 5 hundreds, and 450 has 4 hundreds. So 540 is greater. The others are less than or equal to 450.', 'checked', '{"lint":[],"solve":{"answer":"540","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"540>450; 445,405<450; 450=450.","run_id":"claude-code","at":"2026-10-24T03:05:01.840Z"}}', 'ai', NULL, NULL)
