INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c0fb9db-1130-4dcb-a77e-dcb44eac4c5a', 'NC17.2.NBT.4', 2, 'choice', 'Choose the true comparison with >, = or <', 'Which comparison of 356 and 365 is true?', '["$356 > 365$","$356 = 365$","$356 < 365$","$365 < 356$"]', '$356 < 365$', NULL, 'The hundreds are the same (3). The tens are 5 and 6, and 5 is less than 6. So $356 < 365$.', 'checked', '{"lint":[],"solve":{"answer":"$356 < 365$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same hundreds; tens 5<6, so 356<365.","run_id":"claude-code","at":"2026-10-24T03:05:01.840Z"}}', 'ai', NULL, NULL)
