INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3311d3f6-513e-472e-9d8a-52cb96e7b9f2', 'NC17.2.NBT.4', 2, 'choice', 'Find a number greater or less than a given number', 'Which number makes $? < 428$ true?', '["428","432","417","500"]', '417', NULL, '417 has 4 hundreds, like 428. The tens are 1 and 2, and 1 is less. So $417 < 428$. The others are not less than 428.', 'checked', '{"lint":[],"solve":{"answer":"417","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"417<428; 432, 500 greater; 428 equal.","run_id":"claude-code","at":"2026-10-24T03:05:01.840Z"}}', 'ai', NULL, NULL)
