VALUES ('17691aae-ec9e-46b4-aa4d-5a58b3a15588', 'NC17.2.NBT.4', 2, 'choice', 'Compare three-digit numbers with symbols', 'Which number sentence is true?', '["$629 > 692$","$692 < 629$","$629 < 692$","$629 = 692$"]', '$629 < 692$', NULL, 'Both numbers have 6 hundreds. Compare the tens: 2 tens is less than 9 tens. So 629 is less than 692.', 'checked', '{"lint":[],"solve":{"answer":"$629 < 692$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same hundreds (6); tens 2 < 9, so 629 < 692. The others are false.","run_id":"claude-code","at":"2026-10-24T08:45:12.325Z"}}', 'ai', NULL, NULL)
