INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00a9b211-c597-40de-8f32-92cde9739bd4', 'NC17.2.NBT.4', 3, 'choice', 'Compare numbers in expanded form', 'Compare using expanded form. Which statement is true?', '["$300 + 20 + 7 < 372$","$300 + 20 + 7 > 372$","$300 + 20 + 7 = 372$","$300 + 70 + 2 < 327$"]', '$300 + 20 + 7 < 372$', NULL, '$300 + 20 + 7$ is 327. 327 has 2 tens and 372 has 7 tens, so $327 < 372$. Also $300 + 70 + 2$ is 372, which is not less than 327.', 'checked', '{"lint":[],"solve":{"answer":"$300 + 20 + 7 < 372$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"327 vs 372: 327<372 true; 327>372 false; 372<327 false; equal false.","run_id":"claude-code","at":"2026-10-24T03:05:01.840Z"}}', 'ai', NULL, NULL)
