VALUES ('00526943-b3c1-4e45-b92d-7227f9bbb89c', 'NC17.2.NBT.4', 3, 'choice', 'Find a number greater or less than a given number', 'Which number is greater than 346 and less than 354?', '["345","354","350","359"]', '350', NULL, '350 is more than 346 and less than 354. 345 is less than 346. 354 is equal to 354, not less. 359 is greater than 354.', 'checked', '{"lint":[],"solve":{"answer":"350","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Between 346 and 354 exclusive: 350. 354 equal, 359 above, 345 below.","run_id":"claude-code","at":"2026-10-24T03:05:01.840Z"}}', 'ai', NULL, NULL)
