VALUES ('35eedf40-17d9-4083-a926-6ba6123eb5e5', 'NC17.2.NBT.5', 2, 'choice', 'Place-value strategy: add tens and ones', 'Which shows a way to find $54 + 28$ by adding the tens and then the ones?', '["$50 + 20 + 4 + 2$","$5 + 2 + 4 + 8$","$50 + 20 + 4 + 8$","$54 + 20 + 8 + 2$"]', '$50 + 20 + 4 + 8$', NULL, '54 is 50 + 4 and 28 is 20 + 8. So 54 + 28 = 50 + 20 + 4 + 8 = 70 + 12 = 82.', 'checked', '{"lint":[],"solve":{"answer":"$50 + 20 + 4 + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54=50+4, 28=20+8; 50+20+4+8=82 = 54+28. Others give 19, 84, 76.","run_id":"claude-code","at":"2026-10-24T03:07:42.753Z"}}', 'ai', NULL, NULL)
