INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1126eb1d-bb8f-4db1-bc8b-e3981d9ec8ac', 'NC17.3.OA.8', 1, 'choice', 'Add and subtract in two steps', 'A parking lot has 30 cars. 8 cars leave and 5 cars come in. How many cars are in the lot now?', '["33","27","17","43"]', '27', '30-8+5', '$30 - 8 = 22$. Then $22 + 5 = 27$ cars.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30-8+5=27.","run_id":"claude-code","at":"2026-10-28T19:29:58.710Z"}}', 'ai', NULL, NULL)
