INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab5865b-578c-41f5-8be6-821d5eca1dec', 'NC17.3.OA.8', 1, 'choice', 'Write an equation with an unknown', 'A store has 6 shelves with 4 toys on each shelf. It sells 5 toys. There are $t$ toys left. Which equation matches the story?', '["$6 + 4 - 5 = t$","$6 \\times 4 + 5 = t$","$6 \\times 4 - 5 = t$","$(6 - 5) \\times 4 = t$"]', '$6 \times 4 - 5 = t$', NULL, 'First find all the toys, $6 \times 4$. Then take away the 5 sold: $6 \times 4 - 5 = t$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 4 - 5 = t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 toys, sell 5: 6 x 4 - 5 = t.","run_id":"claude-code","at":"2026-10-28T19:29:58.763Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
