INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0813e87b-2377-4d1c-adb6-989ddfa85dcb', 'NC17.3.OA.9', 2, 'choice', 'Rows, columns and symmetry of the multiplication table', 'In a multiplication table the product of row 6 and column 4 is the same as the product of row 4 and column 6. Why?', '["The order of the factors does not change the product","Both 6 and 4 are even numbers","The numbers 6 and 4 are next to each other","The table repeats after the 5s"]', 'The order of the factors does not change the product', NULL, 'Because $6 \times 4 = 4 \times 6$: when you multiply, the order of the two factors does not change the product (both are 24).', 'checked', '{"lint":[],"solve":{"answer":"The order of the factors does not change the product","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 = 4 x 6 = 24 by the commutative property.","run_id":"claude-code","at":"2026-10-24T03:05:24.243Z"}}', 'ai', NULL, NULL)
