INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05af737f-a109-4e52-9efb-e0c1ebba591a', 'NC17.3.OA.9', 2, 'numeric', 'Skip counting on a hundreds board', 'Count by 3s from 3: 3, 6, 9, and so on. What is the first number you say that is in the row from 31 to 40 of a hundreds board?', '[]', '33', '33', 'The pattern says 30, 33, 36, 39 ... The first one from 31 to 40 is 33.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3, 6, ..., 27, 30, 33. 30 is in the row 21-30; 33 is the first in 31-40.","run_id":"claude-code","at":"2026-10-28T19:32:34.371Z"}}', 'ai', NULL, NULL)
