INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('242c5810-879e-4d2e-a9a4-8d08443adf04', 'NC17.3.OA.9', 3, 'choice', 'Even and odd products and sums', 'Sam says that $6 \times 5$ must be even because 6 is even. Which reason explains his idea?', '["6 is greater than 5, so the answer is even","Multiplying always gives an even number","Since 5 is odd, odd numbers make the answer even","6 is made of 3 pairs, so 6 groups of 5 can be split into pairs"]', '6 is made of 3 pairs, so 6 groups of 5 can be split into pairs', NULL, '6 is even, so it can be split into pairs. Then 6 groups of 5 also split into pairs with none left over, so the product (30) is even. The other reasons are not true.', 'checked', '{"lint":[],"solve":{"answer":"6 is made of 3 pairs, so 6 groups of 5 can be split into pairs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 3 pairs, so 6 groups of 5 is 3 pairs of groups of 5: 2 x 15 = 30, even. Other options are false reasons.","run_id":"claude-code","at":"2026-10-24T03:05:24.243Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f13e7c7-e8c2-432a-999e-7e11a458be22', 'NC17.3.OA.9', 3, 'choice', 'The diagonal of the multiplication table', 'The products on the diagonal of a multiplication table are 1, 4, 9, 16, 25. The steps between them are 3, 5, 7 and 9. Which describes the steps?', '["Each step is 3 more than the step before","Each step is 2 more than the step before","Each step is double the step before","All the steps are the same size"]', 'Each step is 2 more than the step before', NULL, '5 - 3 = 2, 7 - 5 = 2 and 9 - 7 = 2. Each step is 2 more than the one before.', 'checked', '{"lint":[],"solve":{"answer":"Each step is 2 more than the step before","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,5,7,9: each step is 2 more than the one before.","run_id":"claude-code","at":"2026-10-28T19:34:46.233Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
