INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ccbbbe9-aa70-490b-9830-3135bc3f219e', 'NC17.3.NBT.3', 2, 'choice', 'Properties: break apart and regroup factors', 'Jon thinks of $4 \times 60$ as $(4 \times 6) \times 10$. What is $4 \times 60$?', '["240","24","2400","64"]', '240', '4*60', '$4 \times 6 = 24$, and then $24 \times 10 = 240$.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24, x 10 = 240.","run_id":"claude-code","at":"2026-10-24T03:07:42.792Z"}}', 'ai', NULL, NULL)
