INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('250e1453-2e8a-4d43-ac4e-ec2e30a6d31b', 'NC17.3.NBT.3', 2, 'numeric', 'Find the missing factor', 'What number makes this true? $5 \times ? = 200$', '[]', '40', '200/5', '200 is 20 tens. 5 times 4 tens is 20 tens, so the ? is 40. Check: $5 \times 40 = 200$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200 = 20 tens; 5 x 4 tens = 20 tens, so ? = 40.","run_id":"claude-code","at":"2026-10-24T03:07:42.792Z"}}', 'ai', NULL, NULL)
