VALUES ('116707d4-b843-4db2-8917-c3c07186414a', 'NC17.3.NBT.3', 3, 'choice', 'Check which product is correct', 'Which equation is NOT true?', '["$5 \\times 30 = 160$","$2 \\times 80 = 160$","$4 \\times 40 = 160$","$8 \\times 20 = 160$"]', '$5 \times 30 = 160$', NULL, '$5 \times 30 = 150$, not 160. The other three equal 160: $2 \times 8 = 16$, $4 \times 4 = 16$ and $8 \times 2 = 16$ tens.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times 30 = 160$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x40=160, 8x20=160, 5x30=150 (not 160), 2x80=160.","run_id":"claude-code","at":"2026-10-24T03:07:42.792Z"}}', 'ai', NULL, NULL)
