INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53bcae18-f160-4da9-bd2e-946ef475e4fa', 'NC17.3.NBT.3', 3, 'numeric', 'Area of a rectangle with a multiple of 10', 'A rectangle is 6 units wide and 70 units long. It is cut into two parts. One part is 6 units by 40 units. What is the area of the other part in square units?', '[]', '180', '6*70-6*40', 'The whole rectangle has area $6 \times 70 = 420$. The 6-by-40 part has area $6 \times 40 = 240$. The other part is $420 - 240 = 180$.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other part is 6 by 30: 6 x 30 = 180. (Check 6x70=420, 420-240=180.)","run_id":"claude-code","at":"2026-10-24T03:07:42.792Z"}}', 'ai', NULL, NULL)
