INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34e9e31c-060f-4735-9a5f-7d00471f23d5', 'NC17.3.NF.1', 1, 'numeric', 'Find the number of equal parts from a unit fraction', 'A rectangle is cut into equal parts. One part is $\frac{1}{6}$ of the rectangle. How many equal parts is the rectangle cut into?', '[]', '6', '6', 'The denominator 6 tells how many equal parts make the whole. The rectangle is cut into 6 equal parts.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A unit fraction 1/6 means the whole is cut into 6 equal parts.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
