INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2525542e-18bb-4ef8-992b-983e7f920ee2', 'NC17.3.NF.1', 1, 'choice', 'Meaning of the numerator and denominator of a unit fraction', 'In the fraction $\frac{1}{8}$, what does the 8 tell you?', '["The whole is exactly 8 units long","There are 8 parts that are shaded","The whole is cut into 8 equal parts","Each of the parts is 8 units long"]', 'The whole is cut into 8 equal parts', NULL, 'The bottom number, the denominator, tells how many equal parts the whole is cut into. In $\frac{1}{8}$ it is cut into 8 equal parts.', 'checked', '{"lint":[],"solve":{"answer":"The whole is cut into 8 equal parts","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The denominator 8 tells how many equal parts the whole is cut into.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
