INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('058e7edc-f0d2-4feb-8ec4-c19465233803', 'NC17.3.NF.1', 1, 'numeric', 'Unit fractions on a length or number-line model', 'A string 1 yard long is cut into 6 equal pieces. What fraction of a yard is each piece? Write your answer as a fraction.', '[]', '1/6', '1/6', 'One yard is cut into 6 equal pieces, so each piece is $\frac{1}{6}$ of a yard.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 yard into 6 equal pieces: each is 1/6 yard.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
