INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19a037d9-52f2-47b8-97c4-7d85b836ed2a', 'NC17.3.NF.1', 2, 'numeric', 'Build a fraction from unit fractions', 'A strip is cut into 8 equal parts. Tia colors 3 of the parts. Each part is $\frac{1}{8}$ of the strip. What fraction of the strip does Tia color? Write your answer as a fraction.', '[]', '3/8', '3/8', 'Tia colors 3 parts, and each part is $\frac{1}{8}$. So she colors $\frac{1}{8} + \frac{1}{8} + \frac{1}{8} = \frac{3}{8}$ of the strip.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 parts of size 1/8: 1/8+1/8+1/8 = 3/8.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
