INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('266dff23-4c6f-4ad0-bf4a-7951fc8eac6b', 'NC17.3.NF.1', 2, 'choice', 'Size of unit fractions: more equal parts, smaller parts', 'Nina and Omar have candy bars of the same length. Nina cuts hers into 3 equal pieces. Omar cuts his into 6 equal pieces. Which statement is true?', '["Omar’s pieces are longer than Nina’s pieces","Omar’s pieces are the same length as Nina’s pieces","Omar’s pieces are shorter than Nina’s pieces","Omar’s pieces are twice as long as Nina’s pieces"]', 'Omar’s pieces are shorter than Nina’s pieces', NULL, 'The bars are the same length. The more equal pieces a bar is cut into, the shorter each piece is. Sixths are shorter than thirds.', 'checked', '{"lint":[],"solve":{"answer":"Omar’s pieces are shorter than Nina’s pieces","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same length: 6 equal pieces are smaller than 3 equal pieces (1/6 < 1/3); Omar’s are half as long, so shorter.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a4780b9-24a4-4b91-b15e-fa05a8cfffc6', 'NC17.3.NF.1', 2, 'numeric', 'Use a unit fraction to find a part or the whole', 'A 12-centimeter ribbon is cut into 3 equal pieces. Each piece is $\frac{1}{3}$ of the ribbon. How many centimeters long is each piece?', '[]', '4', '12/3', 'One third of 12 centimeters is $12 \div 3 = 4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 cm into 3 equal pieces: 12/3 = 4 cm.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
