INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14d055f9-0c87-4986-846e-448ff82ea335', 'NC17.3.NF.1', 3, 'choice', 'Parts must be equal to make a unit fraction', 'A square cake is made of 16 small squares that are all the same size. It is cut into 4 pieces. Which cut makes each piece $\frac{1}{4}$ of the cake?', '["Pieces of 4, 4, 4 and 4 small squares","Pieces of 8, 4, 2 and 2 small squares","Pieces of 5, 5, 3 and 3 small squares","Pieces of 6, 4, 4 and 2 small squares"]', 'Pieces of 4, 4, 4 and 4 small squares', NULL, 'Fourths are 4 EQUAL pieces. $16 \div 4 = 4$, so each piece must have 4 small squares.', 'checked', '{"lint":[],"solve":{"answer":"Pieces of 4, 4, 4 and 4 small squares","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 squares into 4 equal pieces: 16/4 = 4 each; only 4,4,4,4 is equal.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3388dd24-c3f0-48c0-b057-5dd082f6baab', 'NC17.3.NF.1', 3, 'choice', 'Use a unit fraction to find a part or the whole', 'Mia and Sam each eat $\frac{1}{4}$ of their own pizza. Mia’s pizza is large and Sam’s pizza is small. Which statement is true?', '["Sam eats more pizza than Mia","They eat the same amount of pizza","Mia eats more pizza than Sam","Mia eats $\\frac{1}{2}$ of her pizza"]', 'Mia eats more pizza than Sam', NULL, '$\frac{1}{4}$ of a large whole is more than $\frac{1}{4}$ of a small whole. A fraction only compares well when the wholes are the same size.', 'checked', '{"lint":[],"solve":{"answer":"Mia eats more pizza than Sam","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A fraction depends on the size of the whole: 1/4 of a large pizza is more than 1/4 of a small one, so Mia eats more.","run_id":"claude-code","at":"2026-10-24T03:13:29.708Z"}}', 'ai', NULL, NULL)
