INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('004b6b9f-1e6e-455b-94f7-ce7e6ad53792', 'NC17.3.NF.2', 3, 'choice', 'A unit fraction is one equal part of a whole', 'Which statement is true when a number line from 0 to 1 is cut into 3 equal parts?', '["Each part is $\\frac{1}{3}$ long, and 2 parts reach 1.","Each part is $\\frac{1}{2}$ long, and 3 parts reach 1.","Each part is $\\frac{1}{3}$ long, and 4 parts reach 1.","Each part is $\\frac{1}{3}$ long, and 3 parts reach 1."]', 'Each part is $\frac{1}{3}$ long, and 3 parts reach 1.', NULL, '3 equal parts make the whole length 1, so each part is 1/3 long and 3 of them reach 1.', 'checked', '{"lint":[],"solve":{"answer":"Each part is $\\frac{1}{3}$ long, and 3 parts reach 1.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thirds: each 1/3, 3 parts reach 3/3 = 1.","run_id":"claude-code","at":"2026-10-24T03:10:42.653Z"}}', 'ai', NULL, NULL)
