INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f61f3c9-5fa7-4fcb-a162-090a1648f826', 'NC17.3.NF.3', 1, 'choice', 'Identify equivalent fractions', 'Which fraction is equal to $\frac{1}{2}$?', '["$\\frac{1}{4}$","$\\frac{2}{4}$","$\\frac{2}{3}$","$\\frac{1}{3}$"]', '$\frac{2}{4}$', NULL, 'Cut each half into 2 equal parts. Then 1 half is the same as 2 of 4 equal parts, so $\frac{1}{2}$ = $\frac{2}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 2/4 (each half split in two). 1/4, 2/3, 1/3 are not half.","run_id":"claude-code","at":"2026-10-24T03:15:26.400Z"}}', 'ai', NULL, NULL)
