INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d194fc1-ec16-4067-b681-e9324a77f1f2', 'NC17.3.NF.3', 1, 'choice', 'Equivalent fractions on a number line', 'On a number line, the space from 0 to 1 is split into 2 equal parts, so $\frac{1}{2}$ is halfway. Now the space from 0 to 1 is split into 4 equal parts instead. Which fraction names the halfway point?', '["$\\frac{2}{4}$","$\\frac{1}{4}$","$\\frac{3}{4}$","$\\frac{4}{4}$"]', '$\frac{2}{4}$', NULL, 'With 4 equal parts, the halfway point is 2 parts from 0. That point is $\frac{2}{4}$, the same point as $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halfway between 0 and 1 with 4 parts is the 2nd mark: 2/4.","run_id":"claude-code","at":"2026-10-24T03:15:26.400Z"}}', 'ai', NULL, NULL)
