VALUES ('3e55e472-3797-442a-a90d-0bd79ce1f93b', 'NC17.3.NF.3', 2, 'choice', 'Identify equivalent fractions', 'Which fraction is equal to $\frac{3}{4}$?', '["$\\frac{6}{8}$","$\\frac{3}{8}$","$\\frac{6}{4}$","$\\frac{4}{5}$"]', '$\frac{6}{8}$', NULL, 'Cut each fourth into 2 equal parts. Then 3 fourths becomes 6 eighths, so $\frac{3}{4}$ = $\frac{6}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 6/8. 3/8 smaller, 6/4 > 1, 4/5 not equal.","run_id":"claude-code","at":"2026-10-24T03:15:26.400Z"}}', 'ai', NULL, NULL)
