INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4791a72b-21cd-4da3-af0e-d5824e24eb88', 'NC17.3.NF.3', 2, 'choice', 'Equivalent fractions on a number line', 'A number line from 0 to 1 is split into 8 equal parts. A point is at $\frac{4}{8}$. If the number line is split into halves instead, which fraction names the same point?', '["$\\frac{4}{2}$","$\\frac{1}{2}$","$\\frac{1}{4}$","$\\frac{1}{8}$"]', '$\frac{1}{2}$', NULL, '4 of 8 equal parts is half of the way from 0 to 1. So $\frac{4}{8}$ = $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 is halfway, which is 1/2.","run_id":"claude-code","at":"2026-10-24T03:15:26.400Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50111dae-08d2-41ef-909e-5e54786c5f7b', 'NC17.3.NF.3', 2, 'choice', 'Identify equivalent fractions', 'Which pair of fractions is equal?', '["$\\frac{2}{3}$ and $\\frac{3}{4}$","$\\frac{2}{3}$ and $\\frac{4}{6}$","$\\frac{1}{3}$ and $\\frac{1}{6}$","$\\frac{2}{4}$ and $\\frac{2}{8}$"]', '$\frac{2}{3}$ and $\frac{4}{6}$', NULL, 'Cutting each third in half gives 2 thirds = 4 sixths. In the other pairs, the fractions name different amounts: for example, 1 third is more than 1 sixth.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$ and $\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6. 2/3 vs 3/4 differ, 1/3 vs 1/6 differ, 2/4 vs 2/8 differ.","run_id":"claude-code","at":"2026-10-24T03:15:26.400Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('018c6406-6810-4f55-aa88-7f53b9780deb', 'NC17.3.NF.3', 3, 'choice', 'Identify equivalent fractions', 'Which list shows only fractions that are equal to $\frac{1}{2}$?', '["$\\frac{2}{4}$, $\\frac{2}{6}$, $\\frac{4}{8}$","$\\frac{1}{4}$, $\\frac{3}{6}$, $\\frac{4}{8}$","$\\frac{2}{4}$, $\\frac{3}{6}$, $\\frac{4}{8}$","$\\frac{2}{4}$, $\\frac{3}{6}$, $\\frac{5}{8}$"]', '$\frac{2}{4}$, $\frac{3}{6}$, $\frac{4}{8}$', NULL, 'Half of 4 is 2, half of 6 is 3 and half of 8 is 4. So $\frac{2}{4}$, $\frac{3}{6}$ and $\frac{4}{8}$ are all equal to $\frac{1}{2}$. The other lists each have a fraction that is not: $\frac{2}{6}$, $\frac{1}{4}$ or $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{4}$, $\\frac{3}{6}$, $\\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/4, 3/6, 4/8 are all 1/2. Others contain 5/8, 1/4 or 2/6.","run_id":"claude-code","at":"2026-10-24T03:15:26.400Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('006bac06-f5e3-4d34-88cf-5a2d35e45b73', 'NC17.3.NF.3', 3, 'choice', 'Explain why fractions are equivalent', 'Ravi says $\frac{3}{4}$ = $\frac{3}{8}$ because both fractions have 3 on top. Which statement shows his mistake?', '["3 of 8 equal parts covers more of a bar than 3 of 4 equal parts","Both fractions are equal to 1 whole, so they are not equal to each other","3 of 8 equal parts covers less of a bar than 3 of 4 equal parts","A fraction can only be equal to one with the same denominator"]', '3 of 8 equal parts covers less of a bar than 3 of 4 equal parts', NULL, 'Eighths are smaller parts than fourths. So 3 eighths covers less of the bar than 3 fourths, and the fractions are not equal. Equal fractions need the same amount of the whole, not the same numerator.', 'checked', '{"lint":[],"solve":{"answer":"3 of 8 equal parts covers less of a bar than 3 of 4 equal parts","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Eighths are smaller than fourths, so 3/8 covers less than 3/4. Other options are false.","run_id":"claude-code","at":"2026-10-24T03:15:26.400Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e14228e-ab6b-4025-8f53-91781c8d34e9', 'NC17.3.NF.4', 1, 'choice', 'Choose the symbols >, < and = that make a comparison true', 'Which two symbols make both sentences true? $\frac{1}{4}$ ? $\frac{3}{4}$ and $\frac{1}{4}$ ? $\frac{1}{8}$', '["$>$ and $<$","$<$ and $<$","$>$ and $>$","$<$ and $>$"]', '$<$ and $>$', NULL, 'In the first sentence the denominators are the same, and 1 is less than 3, so $\frac{1}{4} < \frac{3}{4}$. In the second the numerators are the same, and fourths are bigger than eighths, so $\frac{1}{4} > \frac{1}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$<$ and $>$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 < 3/4 (same denominator); 1/4 > 1/8 (fourths bigger). So < and >.","run_id":"claude-code","at":"2026-10-24T03:17:09.805Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bcf0500-d6b9-41a6-9a38-b45750cfd94d', 'NC17.3.NF.4', 1, 'choice', 'Know the wholes must be the same size', 'When we compare two fractions, what must be true about their wholes?', '["The wholes must be the same size.","The wholes must be different sizes.","The wholes must both be circles.","The wholes must both be cut into 4 parts."]', 'The wholes must be the same size.', NULL, 'Half of a big pizza and half of a tiny pizza are not the same amount. To compare fractions fairly, both must be fractions of the same whole, or wholes that are the same size.', 'checked', '{"lint":[],"solve":{"answer":"The wholes must be the same size.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fractions compare only when they are of the same whole (same size).","run_id":"claude-code","at":"2026-10-24T03:17:09.805Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21859acb-8092-4157-9cba-1a332f688477', 'NC17.3.NF.4', 1, 'choice', 'Compare fractions with the same numerator', 'Four wholes are the same size. Each fraction below is the size of one equal part of a different whole. Which fraction shows the biggest part?', '["$\\frac{1}{8}$","$\\frac{1}{6}$","$\\frac{1}{4}$","$\\frac{1}{3}$"]', '$\frac{1}{3}$', NULL, 'All four fractions have 1 part. The fewer parts a whole is cut into, the bigger each part is. The whole cut into 3 parts has the biggest parts.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-size wholes, unit fractions: fewer parts means bigger parts. 3 is the fewest, so 1/3 is biggest.","run_id":"claude-code","at":"2026-10-24T08:45:12.325Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f9b6789-36a3-4c12-b026-b0e375277a4b', 'NC17.3.NF.4', 2, 'numeric', 'Compare fractions with the same numerator', 'Compare $\frac{3}{4}$ and $\frac{3}{8}$. Write the lesser fraction.', '[]', '3/8', '3/8', 'Both fractions have 3 parts. Eighths are smaller pieces than fourths, so 3 eighths is less than 3 fourths. The lesser fraction is $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator; eighths smaller than fourths, so 3/8 is lesser.","run_id":"claude-code","at":"2026-10-24T03:17:09.805Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19451588-4e1d-46cd-8594-fc0b5532a300', 'NC17.3.NF.4', 2, 'choice', 'Order three or more fractions', 'Mia puts three number cards in a row, with the least fraction on the left and the greatest on the right. The cards are $\frac{5}{6}$, $\frac{2}{6}$ and $\frac{3}{6}$. Which row is right?', '["$\\frac{5}{6}$, $\\frac{3}{6}$, $\\frac{2}{6}$","$\\frac{3}{6}$, $\\frac{2}{6}$, $\\frac{5}{6}$","$\\frac{2}{6}$, $\\frac{3}{6}$, $\\frac{5}{6}$","$\\frac{2}{6}$, $\\frac{5}{6}$, $\\frac{3}{6}$"]', '$\frac{2}{6}$, $\frac{3}{6}$, $\frac{5}{6}$', NULL, 'All are sixths, so put the numerators in order: 2, 3, 5. The list is $\frac{2}{6}$, $\frac{3}{6}$, $\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{6}$, $\\frac{3}{6}$, $\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Least to greatest: 2/6, 3/6, 5/6.","run_id":"claude-code","at":"2026-10-24T03:17:09.805Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a3ff705-d9c5-4a6a-afd3-d3c6f6d0a07d', 'NC17.3.NF.4', 2, 'choice', 'Compare fractions in a story about the same whole', 'Pia filled $\frac{1}{3}$ of a jar with sand. Quinn filled $\frac{1}{4}$ of an identical jar with sand. Whose jar has more sand?', '["Quinn''s jar has more sand.","Both jars have the same amount of sand.","It is impossible to tell.","Pia''s jar has more sand."]', 'Pia''s jar has more sand.', NULL, 'The jars are identical, so we can compare. Each person filled 1 part, and thirds are bigger than fourths. So Pia''s jar has more sand.', 'checked', '{"lint":[],"solve":{"answer":"Pia''s jar has more sand.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Identical jars; thirds bigger than fourths: 1/3 > 1/4. Pia.","run_id":"claude-code","at":"2026-10-24T03:17:09.805Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ef59bae-5c1f-4463-8868-4d6185dd9cf8', 'NC17.3.NF.4', 3, 'numeric', 'Find a missing numerator or denominator that makes a comparison true', 'The ? in $\frac{1}{?}$ can be 2, 3, 4, 6 or 8. For how many of these numbers is $\frac{1}{?}$ greater than $\frac{1}{6}$?', '[]', '3', '3', 'Each fraction has 1 part, so a fraction is greater than $\frac{1}{6}$ when its pieces are bigger than sixths. That happens when the denominator is less than 6: 2, 3 and 4. That is 3 numbers. A denominator of 6 gives an equal fraction, and 8 gives a lesser one.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/? > 1/6 needs ? < 6: 2, 3, 4. That is 3.","run_id":"claude-code","at":"2026-10-24T03:17:09.805Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ddf0de0-0a0f-4724-a765-1fe9c92fc706', 'NC17.3.NF.4', 3, 'choice', 'Find a missing numerator or denominator that makes a comparison true', 'Which fraction could go in the ? to make this true? $\frac{1}{4} < ? < \frac{3}{4}$', '["$\\frac{2}{4}$","$\\frac{1}{4}$","$\\frac{3}{4}$","$\\frac{4}{4}$"]', '$\frac{2}{4}$', NULL, 'All are fourths, so the numerator in the ? must be greater than 1 and less than 3. The only choice is 2, so the fraction is $\frac{2}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strictly between 1/4 and 3/4: only 2/4.","run_id":"claude-code","at":"2026-10-24T03:17:09.805Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46701ef3-1d93-44cf-a19e-0527e7ef54aa', 'NC17.3.MD.1', 1, 'numeric', 'Read the time from the clock hands', 'On a clock, the hour hand is just past the 3. The minute hand points at the 4. Each number on the clock stands for 5 minutes: the 1 is 5 minutes, the 2 is 10, and so on. How many minutes after 3 o''clock is it?', '[]', '20', '4*5', 'The 4 stands for 4 x 5 = 20 minutes. It is 20 minutes after 3 o''clock, or 3:20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Minute hand at 4 -> 4 x 5 = 20 minutes after 3.","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3079f925-a218-4dc5-94ad-8e3334c913bc', 'NC17.3.MD.1', 1, 'choice', 'Write a time in different ways', 'A digital clock shows 5:40. Which tells the same time?', '["20 minutes to 6","20 minutes after 5","40 minutes to 6","20 minutes to 5"]', '20 minutes to 6', NULL, 'From 5:40 to 6:00 is 20 minutes. So 5:40 is 20 minutes to 6.', 'checked', '{"lint":[],"solve":{"answer":"20 minutes to 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5:40 is 20 minutes before 6:00.","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
