INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42bdda0f-ab94-477b-abd5-1b1b7b395903', 'NC17.3.MD.1', 1, 'choice', 'Find the start time', 'A play ended at 6:40 after lasting 25 minutes. What time did it start?', '["6:15","7:05","6:25","5:55"]', '6:15', NULL, 'Go back 25 minutes from 6:40. 40 - 25 = 15, so it started at 6:15.', 'checked', '{"lint":[],"solve":{"answer":"6:15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6:40 - 25 minutes = 6:15.","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
