INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79830e5a-8633-4d0a-bb51-8bec54d20ec2', 'NC17.3.MD.1', 2, 'numeric', 'Find elapsed time within one hour', 'Choir practice starts at 7:42 and ends at 8:05. How many minutes does practice last?', '[]', '23', '18+5', 'From 7:42 to 8:00 is 18 minutes. From 8:00 to 8:05 is 5 more minutes. 18 + 5 = 23 minutes.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7:42 to 8:00 = 18 min; 8:00 to 8:05 = 5 min; total 23.","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
