INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34e72661-ecdb-411d-90e8-2f336f10dd89', 'NC17.3.MD.1', 2, 'choice', 'Find the end time', 'Sam eats lunch at 12:20. His soccer game starts 40 minutes later. What time does the game start?', '["1:00","12:40","1:20","12:30"]', '1:00', NULL, 'From 12:20 to 1:00 is 40 minutes. The game starts at 1:00.', 'checked', '{"lint":[],"solve":{"answer":"1:00","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12:20 + 40 = 1:00.","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
