INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28b023c6-c76a-4753-8da4-f52a2723ae84', 'NC17.3.MD.1', 2, 'numeric', 'Find elapsed time within one hour', 'At 2:30 Ken sets a timer for 45 minutes. At 2:50, how many minutes are left on the timer?', '[]', '25', '45-20', 'From 2:30 to 2:50 is 20 minutes gone. 45 - 20 = 25 minutes are left.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Timer ends at 2:30 + 45 = 3:15. From 2:50 to 3:15 = 25 minutes. (Or 45 - 20 elapsed = 25.)","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
