INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cfb601d-a9c1-48ee-b49b-1fafba7860df', 'NC17.3.MD.1', 3, 'choice', 'Find the end time', 'A concert starts at 7:48 and lasts 38 minutes. What time does it end?', '["8:36","8:16","8:26","8:46"]', '8:26', NULL, 'From 7:48 to 8:00 is 12 minutes. There are 38 - 12 = 26 minutes left to add. The concert ends at 8:26.', 'checked', '{"lint":[],"solve":{"answer":"8:26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7:48 + 12 = 8:00; 38 - 12 = 26 more -> 8:26.","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
