INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('049d0ede-8025-4d38-9215-0f485f86f714', 'NC17.3.MD.1', 3, 'numeric', 'Read the time from the clock hands', 'On a clock, the minute hand is 3 small marks before the 10. Each number on the clock stands for 5 minutes: the 1 is 5 minutes, the 2 is 10, and so on. How many minutes after the hour is it?', '[]', '47', '10*5-3', 'The 10 stands for 50 minutes. Three small marks before it is 50 - 3 = 47 minutes after the hour.', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The 10 is 50 minutes; 3 small marks before = 47.","run_id":"claude-code","at":"2026-10-24T08:19:44.207Z"}}', 'ai', NULL, NULL)
