INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('484d5a04-6e22-47f6-b6c5-129e56366eb0', 'NC17.3.MD.2', 1, 'choice', 'Choose the best customary unit', 'Which unit is best for measuring the length of a postage stamp?', '["inches","pounds","feet","yards"]', 'inches', NULL, 'A stamp is tiny, and length is measured in inches, feet or yards. Of these, an inch is the smallest, so inches fit best. Pounds measure weight.', 'checked', '{"lint":[],"solve":{"answer":"inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A stamp is about 1 inch long. Inches.","run_id":"claude-code","at":"2026-10-24T08:22:27.762Z"}}', 'ai', NULL, NULL)
