INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21ae0d08-f22a-4081-8df5-f8dd5939b989', 'NC17.3.MD.2', 1, 'numeric', 'Measure a length with a ruler', 'A ribbon lies along a ruler. One end is at the 0-inch mark and the other end is at the 8-inch mark. How many inches long is the ribbon?', '[]', '8', '8-0', 'The ribbon starts at 0, so the mark where it ends tells its length. It is 8 inches long.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 - 0 = 8 inches.","run_id":"claude-code","at":"2026-10-24T08:22:27.762Z"}}', 'ai', NULL, NULL)
