INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ead0ce5-9e07-4918-b6a6-4d090c2dfd71', 'NC17.3.MD.2', 1, 'choice', 'Choose a reasonable estimate of a length, capacity or weight', 'Which is the most reasonable amount of water in a full kitchen sink?', '["10 cups","1 cup","10 gallons","100 gallons"]', '10 gallons', NULL, 'A full sink holds a good amount of water, around 10 gallons. 1 cup and 10 cups would barely cover the bottom, and 100 gallons would fill a bathtub twice over.', 'checked', '{"lint":[],"solve":{"answer":"10 gallons","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A full kitchen sink holds several gallons, about 10. 1 or 10 cups (under a gallon) is too little, 100 gallons too much.","run_id":"claude-code","at":"2026-10-24T08:22:27.762Z"}}', 'ai', NULL, NULL)
