INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73932f70-cb52-49d4-adfc-2dc0e2bb421c', 'NC17.3.MD.2', 2, 'numeric', 'Solve a one-step length problem', 'A track is 36 yards long. A runner has already run 14 yards of it. How many more yards does the runner have to go?', '[]', '22', '36-14', 'Take what is already run from the whole track: 36 - 14 = 22. The runner has 22 yards to go.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 - 14 = 22 yards.","run_id":"claude-code","at":"2026-10-24T08:22:27.762Z"}}', 'ai', NULL, NULL)
