INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b785052-13f1-4c0e-b418-ee052234dd43', 'NC17.3.MD.3', 2, 'choice', 'Choose the true statement about a graph', 'A bar graph counts by 5s. The bars end at: Pop 30, Rock 15, Jazz 20. Which statement is true?', '["Jazz has 10 more votes than Rock","Rock has 10 fewer votes than Pop","Pop has 15 more votes than Rock","Pop has 5 more votes than Jazz"]', 'Pop has 15 more votes than Rock', NULL, 'Pop minus Rock is 30 - 15 = 15, so the first statement is true. Jazz minus Rock is 5, Pop minus Rock is 15 (not 10) and Pop minus Jazz is 10 (not 5).', 'checked', '{"lint":[],"solve":{"answer":"Pop has 15 more votes than Rock","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pop-Rock = 15 (not 10); Jazz-Rock = 5 (not 10); Pop-Rock = 15 true; Pop-Jazz = 10 (not 5).","run_id":"claude-code","at":"2026-10-24T08:22:27.688Z"}}', 'ai', NULL, NULL)
