VALUES ('33c511c9-dcbe-408b-b301-c24d981d0e85', 'NC17.3.MD.3', 3, 'numeric', 'How many more or fewer (two steps)', 'A bar graph counts by 10s. The bars end at: Cats 50, Dogs 80, Birds 30, Fish 20. How many more pets are cats and dogs together than birds and fish together?', '[]', '80', '(50+80)-(30+20)', 'Cats and dogs: 50 + 80 = 130. Birds and fish: 30 + 20 = 50. 130 - 50 = 80 more pets.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cats+Dogs = 130, Birds+Fish = 50. 130 - 50 = 80.","run_id":"claude-code","at":"2026-10-24T08:22:27.688Z"}}', 'ai', NULL, NULL)
