VALUES ('55512bed-2590-4cd4-8e27-174f72b1f5ea', 'NC17.3.MD.5', 2, 'numeric', 'Find the missing number of rows or squares per row', 'A rectangle is covered by 28 unit squares. Each row has 7 squares. How many rows are there?', '[]', '4', '28/7', 'Each row has 7 squares, so the number of rows is 28 / 7 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 7 = 4 rows.","run_id":"claude-code","at":"2026-10-24T08:22:02.603Z"}}', 'ai', NULL, NULL)
