INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6695828-0ecb-4fc9-b6cd-85097f45a455', 'NC17.3.MD.7', 1, 'choice', 'Area from the side lengths', 'Which rectangle has an area of 18 square units?', '["4 units long and 5 units wide","2 units long and 8 units wide","3 units long and 6 units wide","3 units long and 9 units wide"]', '3 units long and 6 units wide', NULL, '$3 \times 6 = 18$. The others have areas $4 \times 5 = 20$, $2 \times 8 = 16$ and $3 \times 9 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"3 units long and 6 units wide","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x9=27, 2x8=16, 4x5=20, 3x6=18.","run_id":"claude-code","at":"2026-10-24T08:27:34.212Z"}}', 'ai', NULL, NULL)
