INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10e0fdf6-3489-4a26-b204-308fceca0a40', 'NC17.3.MD.7', 1, 'numeric', 'Area as repeated addition of rows', 'Lena finds the area of a rectangle by adding the squares in each row: $8 + 8 + 8$. How many rows of squares does the rectangle have?', '[]', '3', '3', 'She added 8 three times, once for each row. So the rectangle has 3 rows, and its area is $8 \times 3 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 is added three times, so 3 rows of 8.","run_id":"claude-code","at":"2026-10-24T08:27:34.212Z"}}', 'ai', NULL, NULL)
