INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7530a7e6-1cf7-4506-bc5f-4b029a078fb5', 'NC17.3.MD.7', 1, 'numeric', 'Adding the areas of non-overlapping rectangles', 'An L-shaped floor is made of two rectangles that do not overlap. One rectangle is 5 feet by 2 feet. The other is 3 feet by 2 feet. What is the area of the L-shaped floor in square feet?', '[]', '16', '5*2+3*2', 'The first rectangle has area $5 \times 2 = 10$ and the second has area $3 \times 2 = 6$. Together: $10 + 6 = 16$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x2=10, 3x2=6, total 16.","run_id":"claude-code","at":"2026-10-24T08:27:34.212Z"}}', 'ai', NULL, NULL)
