INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22826532-065c-4c52-a964-fee4b3801026', 'NC17.3.MD.7', 2, 'choice', 'Adding the areas of non-overlapping rectangles', 'A shape is made of a 6 by 3 rectangle and a 2 by 3 rectangle that touch along a side and do not overlap. Which expression gives the area of the shape?', '["$6 \\times 3 + 2 \\times 3$","$6 \\times 3 + 2$","$6 + 3 + 2 + 3$","$6 \\times 2 + 3 \\times 3$"]', '$6 \times 3 + 2 \times 3$', NULL, 'Find the area of each rectangle and add: $6 \times 3 + 2 \times 3 = 18 + 6 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 3 + 2 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 6x3 + 2x3 = 18+6 = 24.","run_id":"claude-code","at":"2026-10-24T08:27:34.212Z"}}', 'ai', NULL, NULL)
