INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3496c460-e0f6-4745-89a9-da6e85961364', 'NC17.3.MD.7', 2, 'choice', 'Area from the side lengths', 'Which rectangle has the greatest area?', '["6 units by 5 units","3 units by 9 units","4 units by 8 units","7 units by 4 units"]', '4 units by 8 units', NULL, 'The areas are $4 \times 8 = 32$, $6 \times 5 = 30$, $3 \times 9 = 27$ and $7 \times 4 = 28$. The greatest is 32.', 'checked', '{"lint":[],"solve":{"answer":"4 units by 8 units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27, 32, 30, 28. Greatest 32.","run_id":"claude-code","at":"2026-10-24T08:27:34.212Z"}}', 'ai', NULL, NULL)
