INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('094c1e38-4371-4250-96f3-6de29527e21c', 'NC17.3.MD.7', 2, 'numeric', 'Split a rectangle into two smaller rectangles', 'Ana covers a board with sticky notes, with no gaps and no overlaps. Each note is 1 square unit. The top part has 4 rows with 9 notes in each row. The bottom part has 3 rows with 9 notes in each row. What is the area of the board in square units?', '[]', '63', '4*9+3*9', 'The top part has $4 \times 9 = 36$ notes. The bottom part has $3 \times 9 = 27$ notes. The area is $36 + 27 = 63$ square units. This is the same as 7 rows of 9.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top 4 x 9 = 36, bottom 3 x 9 = 27, total 36 + 27 = 63 (= 7 x 9).","run_id":"claude-code","at":"2026-10-24T08:45:12.325Z"}}', 'ai', NULL, NULL)
