VALUES ('0b3331c4-5d83-43a6-8329-2db6184f4353', 'NC17.4.OA.3', 1, 'choice', 'Checking an answer by estimation', 'Which is the best estimate of $62 + 39 + 18$ when each number is rounded to the nearest ten?', '["100","150","80","120"]', '120', '60+40+20', '62 rounds to 60, 39 rounds to 40 and 18 rounds to 20. 60 + 40 + 20 = 120.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"62 -> 60, 39 -> 40, 18 -> 20; 60+40+20 = 120.","run_id":"claude-code","at":"2026-10-28T18:48:28.309Z"}}', 'ai', NULL, NULL)
