INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f58aaac-fa3f-4e01-9e4e-9d2b7bbf1741', 'NC17.4.OA.4', 3, 'choice', 'Factor pairs and factors of a number', 'Which list shows all the factors of 48?', '["1, 2, 3, 4, 6, 8, 12, 16, 18, 24, 48","1, 2, 3, 4, 6, 8, 12, 16, 24, 48","1, 2, 3, 4, 6, 8, 12, 24, 48","1, 2, 4, 6, 8, 12, 16, 24, 48"]', '1, 2, 3, 4, 6, 8, 12, 16, 24, 48', NULL, 'The factor pairs are $1 \times 48$, $2 \times 24$, $3 \times 16$, $4 \times 12$ and $6 \times 8$. 18 is not a factor of 48. The other lists leave out 16 or 3.', 'checked', '{"lint":[],"solve":{"answer":"1, 2, 3, 4, 6, 8, 12, 16, 24, 48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 = 1x48, 2x24, 3x16, 4x12, 6x8: 1,2,3,4,6,8,12,16,24,48. Option 1 misses 3, option 2 misses 16, option 3 adds 18.","run_id":"claude-code","at":"2026-10-24T02:59:33.807Z"}}', 'ai', NULL, NULL)
