VALUES ('0eda4310-297a-4481-82f9-f822b1d241bc', 'NC17.4.NBT.2', 1, 'choice', 'Match words, numerals and expanded form', 'Which expanded form shows twenty-four thousand, one hundred fifty-three?', '["$20{,}000 + 4{,}000 + 100 + 50 + 3$","$20{,}000 + 4{,}000 + 100 + 5 + 3$","$2{,}000 + 400 + 100 + 50 + 3$","$20{,}000 + 400 + 100 + 50 + 3$"]', '$20{,}000 + 4{,}000 + 100 + 50 + 3$', NULL, 'Twenty-four thousand is 20,000 + 4,000. One hundred fifty-three is 100 + 50 + 3.', 'checked', '{"lint":[],"solve":{"answer":"$20{,}000 + 4{,}000 + 100 + 50 + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24,153 = 20,000 + 4,000 + 100 + 50 + 3.","run_id":"claude-code","at":"2026-10-24T03:03:44.219Z"}}', 'ai', NULL, NULL)
