INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e9dd5fc-a0fb-4117-a032-f219768a9aaa', 'NC17.4.NBT.2', 2, 'choice', 'Find the mistake in a written number', 'Rita''s step counter shows $35{,}070$. She reads it as thirty-five thousand, seven hundred. What is her mistake?', '["She said thirty-five thousand, but the 3 stands for only 3,000.","She said seven hundred, but the 7 stands for 70.","She should have said the 5 stands for 500.","She should have said there are no thousands."]', 'She said seven hundred, but the 7 stands for 70.', NULL, 'In 35,070 the 7 is in the tens place, so it is seventy. The number is thirty-five thousand, seventy.', 'checked', '{"lint":[],"solve":{"answer":"She said seven hundred, but the 7 stands for 70.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35,070: the 7 is in the tens place, 70, not 700.","run_id":"claude-code","at":"2026-10-28T19:24:07.962Z"}}', 'ai', NULL, NULL)
