INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01ac570c-d58f-4b1b-aa43-ab9874b39b60', 'NC17.4.NBT.2', 3, 'choice', 'Write a number in words', 'A prize is worth $10{,}500$ dollars. Which tells the prize in words?', '["ten thousand, fifty","ten thousand, five hundred","one thousand, five hundred","fifteen thousand"]', 'ten thousand, five hundred', NULL, 'Say the thousands first, then the rest. $10{,}500$ is ten thousand, five hundred. The other choices name different numbers because a digit was moved, dropped or put in the wrong place.', 'checked', '{"lint":[],"solve":{"answer":"ten thousand, five hundred","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10,500 = ten thousand, five hundred.","run_id":"claude-code","at":"2026-10-28T19:24:07.940Z"}}', 'ai', NULL, NULL)
