INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0428635d-a161-42d1-8e73-850898b54694', 'NC17.4.NBT.7', 1, 'choice', 'Choose or check a comparison with >, = or <', 'Dan compares $6{,}120$ and $6{,}210$. Which comparison is true?', '["$6{,}120 > 6{,}210$","$6{,}120 = 6{,}210$","$6{,}210 < 6{,}120$","$6{,}120 < 6{,}210$"]', '$6{,}120 < 6{,}210$', NULL, 'Both numbers have 6 thousands. Compare the hundreds: 1 hundred is less than 2 hundreds. So $6{,}120$ is less than $6{,}210$, and $6{,}120 < 6{,}210$.', 'checked', '{"lint":[],"solve":{"answer":"$6{,}120 < 6{,}210$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds 1 < 2, so 6,120 < 6,210.","run_id":"claude-code","at":"2026-10-24T03:05:24.280Z"}}', 'ai', NULL, NULL)
