INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02e2328e-e6e8-4e2f-bf65-4357e2d15b43', 'NC17.4.NBT.7', 1, 'choice', 'Choose or check a comparison with >, = or <', 'Which number can go in the ? to make $? > 5{,}640$ true?', '["$5{,}648$","$5{,}604$","$5{,}046$","$5{,}640$"]', '$5{,}648$', NULL, 'The number must be greater than $5{,}640$. Only $5{,}648$ is: its tens match but its ones are 8, which is more than 0.', 'checked', '{"lint":[],"solve":{"answer":"$5{,}648$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 5,648 > 5,640; 5,640 is equal, 5,604 and 5,046 are less.","run_id":"claude-code","at":"2026-10-28T19:28:58.439Z"}}', 'ai', NULL, NULL)
