VALUES ('0610cc61-6369-4542-baec-f577ad1e4618', 'NC17.4.NBT.7', 1, 'numeric', 'Compare by the first place where the digits differ', 'Both numbers have 3 ten thousands and 2 thousands: $32{,}640$ and $32{,}460$. Which number is greater? Write it.', '[]', '32640', '32640', 'The ten thousands and thousands match. Hundreds: 6 is more than 4, so $32{,}640$ is greater.', 'checked', '{"lint":[],"solve":{"answer":"32640","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Compare hundreds: 6>4, so 32,640.","run_id":"claude-code","at":"2026-10-28T19:29:58.932Z"}}', 'ai', NULL, NULL)
