INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08b5aaac-1430-4173-b17c-c4b39716d6ef', 'NC17.4.NBT.7', 2, 'numeric', 'Choose or check a comparison with >, = or <', 'How many of these four comparisons are true? $7{,}008 < 7{,}080$; $51{,}000 > 5{,}100$; $23{,}456 = 23{,}546$; $9{,}999 > 10{,}000$.', '[]', '2', NULL, '7,008 < 7,080 is true (0 tens is less than 8 tens). 51,000 > 5,100 is true (5 digits is more than 4). 23,456 and 23,546 are not equal (4 hundreds is not 5 hundreds). 9,999 is less than 10,000, so the last is false. Two are true.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7,008<7,080 true; 51,000>5,100 true; 23,456=23,546 false; 9,999>10,000 false. 2 true.","run_id":"claude-code","at":"2026-10-24T03:05:24.280Z"}}', 'ai', NULL, NULL)
