INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f0e410-99e8-4317-8925-7be63f277c0f', 'NC17.4.NBT.7', 2, 'numeric', 'Order numbers from least to greatest or greatest to least', 'Five towns have these populations: $23{,}540$, $23{,}045$, $23{,}504$, $22{,}990$, $23{,}450$. Put them in order from least to greatest. What is the middle population?', '[]', '23450', '23450', 'Least to greatest: $22{,}990$, $23{,}045$, $23{,}450$, $23{,}504$, $23{,}540$. The middle one is $23{,}450$.', 'checked', '{"lint":[],"solve":{"answer":"23450","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order: 22,990; 23,045; 23,450; 23,504; 23,540. Middle 23,450.","run_id":"claude-code","at":"2026-10-28T19:29:58.858Z"}}', 'ai', NULL, NULL)
