INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b42c158-e555-4c51-b36d-d25399501cb7', 'NC17.4.NBT.7', 2, 'numeric', 'Compare numbers in a story', 'A stadium had $45{,}080$ fans on Friday, $45{,}800$ fans on Saturday and $45{,}008$ fans on Sunday. How many fans were there on the day with the fewest fans?', '[]', '45008', '45008', 'All three have 45 thousands. Hundreds: 0, 8, 0. Tens: 8 and 0 for the two with 0 hundreds. $45{,}008$ is least.', 'checked', '{"lint":[],"solve":{"answer":"45008","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45,008 < 45,080 < 45,800. Fewest 45,008.","run_id":"claude-code","at":"2026-10-28T19:29:59.034Z"}}', 'ai', NULL, NULL)
