INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03ddcc06-a2f8-430f-8d17-6c9fc88d4cf3', 'NC17.4.NBT.7', 3, 'numeric', 'Find a digit that makes a comparison true', 'The ? is a digit. How many different digits can the ? be so that $3{,}?40 < 3{,}640$ is true?', '[]', '6', NULL, 'The thousands and the last two digits match, so compare the hundreds digit ? with 6. The ? must be less than 6, so it can be 0, 1, 2, 3, 4 or 5. That is 6 digits.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds digit must be less than 6: 0,1,2,3,4,5, i.e. 6 digits.","run_id":"claude-code","at":"2026-10-24T03:05:24.280Z"}}', 'ai', NULL, NULL)
