INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('028f0c77-600b-488f-9b7c-8e2d0943dc77', 'NC17.4.NBT.7', 3, 'choice', 'Find a digit that makes a comparison true', 'Which digit makes both comparisons true? $48{,}?15 > 48{,}715$ and $48{,}?15 < 48{,}915$', '["7","9","6","8"]', '8', NULL, 'The ? is in the hundreds place. It must be more than 7 and less than 9, so it is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48,?15 > 48,715 needs ? > 7 (7 gives equality); < 48,915 needs ? < 9. So ? = 8.","run_id":"claude-code","at":"2026-10-28T19:28:58.384Z"}}', 'ai', NULL, NULL)
