INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b2b4564-7951-42bf-b721-35566dec7903', 'NC17.4.NBT.4', 1, 'choice', 'Add whole numbers with the standard algorithm', 'Which is the sum of $25{,}300$ and $14{,}200$?', '["38500","39400","39500","11100"]', '39500', '25300+14200', 'Add the places: 300 + 200 = 500, 5 thousands + 4 thousands = 9 thousands, 2 ten thousands + 1 ten thousand = 3 ten thousands. The sum is $39{,}500$. The other choices come from adding a place wrongly or subtracting.', 'checked', '{"lint":[],"solve":{"answer":"39500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25300+14200=39500.","run_id":"claude-code","at":"2026-10-24T03:07:13.185Z"}}', 'ai', NULL, NULL)
