INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f9750e6-024e-46ac-a671-1d6415e88c9a', 'NC17.4.NBT.4', 1, 'choice', 'Estimate sums and differences by rounding', 'Rounding each number to the nearest thousand, what is the best estimate of $4{,}912$ + $3{,}087$?', '["7000","9000","7900","8000"]', '8000', '5000+3000', '$4{,}912$ rounds to $5{,}000$ and $3{,}087$ rounds to $3{,}000$. Then $5{,}000$ + $3{,}000$ = $8{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"8000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4912 rounds to 5000, 3087 rounds to 3000; 5000+3000=8000.","run_id":"claude-code","at":"2026-10-24T03:07:13.185Z"}}', 'ai', NULL, NULL)
