INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26be1847-9cee-41de-b8df-862f32a14cd3', 'NC17.4.NBT.4', 1, 'choice', 'Use place value to regroup', 'Which number is $10{,}000$ less than $73{,}456$?', '["72456","63456","73446","83456"]', '63456', '73456-10000', 'Ten thousand less changes only the ten thousands digit: 7 becomes 6. So $73{,}456$ - $10{,}000$ = $63{,}456$.', 'checked', '{"lint":[],"solve":{"answer":"63456","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"73456-10000=63456.","run_id":"claude-code","at":"2026-10-24T03:07:13.185Z"}}', 'ai', NULL, NULL)
