INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('760d5c43-3cf2-4714-858c-e9c3bf588327', 'NC17.4.NBT.4', 2, 'numeric', 'Subtract whole numbers with the standard algorithm', 'Find the difference: $63{,}205$ - $28{,}417$', '[]', '34788', '63205-28417', 'Regroup to subtract each place from the right. The ones, tens and hundreds each need regrouping, and in the end $63{,}205$ - $28{,}417$ = $34{,}788$. Check: $34{,}788$ + $28{,}417$ = $63{,}205$.', 'checked', '{"lint":[],"solve":{"answer":"34788","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"63205-28417=34788. Check: 28417+34788=63205.","run_id":"claude-code","at":"2026-10-24T03:07:13.185Z"}}', 'ai', NULL, NULL)
