INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6044f3eb-9132-4654-bbf7-34a1f83aa6e0', 'NC17.4.NBT.4', 2, 'numeric', 'Find a missing number with the inverse operation', 'What number makes this equation true? $? + 24{,}856 = 61{,}030$', '[]', '36174', '61030-24856', 'To find the missing addend, subtract the known addend from the sum: $61{,}030$ - $24{,}856$ = $36{,}174$.', 'checked', '{"lint":[],"solve":{"answer":"36174","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"?=61030-24856=36174. Check 24856+36174=61030.","run_id":"claude-code","at":"2026-10-24T03:07:13.185Z"}}', 'ai', NULL, NULL)
