INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71e04bdc-4184-4fa2-994f-185fe11b6841', 'NC17.4.NBT.4', 2, 'choice', 'Find and explain a mistake in a calculation', 'Dana works out $61{,}240$ - $38{,}760$ and gets $37{,}520$. What mistake did she make?', '["She rounded both numbers before she subtracted","She subtracted the smaller digit from the larger in each place","She subtracted only the ten thousands and ignored the rest","She added the two numbers together instead of subtracting"]', 'She subtracted the smaller digit from the larger in each place', NULL, 'In each place she took the smaller digit from the larger one (for example 6 - 4 = 2 in the tens place) instead of regrouping. The correct difference is $22{,}480$.', 'checked', '{"lint":[],"solve":{"answer":"She subtracted the smaller digit from the larger in each place","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct difference 22480. Taking smaller from larger digit in each place: |6-3|=3, |1-8|=7, |2-7|=5, |4-6|=2, 0 -> 37520, matching Dana. Sum would be 100000.","run_id":"claude-code","at":"2026-10-24T03:07:13.185Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
