VALUES ('346fc073-2326-4e24-ae6d-7fce198b403b', 'NC17.4.NBT.5', 1, 'numeric', 'Word problem with multi-digit multiplication', 'A box has 12 pencils. How many pencils are in 8 boxes?', '[]', '96', '8*12', '$8 \times 10 = 80$ and $8 \times 2 = 16$. Then $80 + 16 = 96$ pencils.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 8 = 80 + 16 = 96.","run_id":"claude-code","at":"2026-10-24T03:07:42.830Z"}}', 'ai', NULL, NULL)
