VALUES ('3393919e-89e2-4dec-af99-8baba205ccd2', 'NC17.4.NBT.6', 1, 'choice', 'The remainder is less than the divisor', 'A number is divided by 5. Which of these could be the remainder?', '["4","5","6","9"]', '4', '4', 'A remainder must be less than the number you divide by. Only 4 is less than 5.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A remainder when dividing by 5 must be 0 to 4: only 4.","run_id":"claude-code","at":"2026-10-24T03:13:29.745Z"}}', 'ai', NULL, NULL)
