INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c5d9dc8-61f9-43b0-88ab-cd69ef393a49', 'NC17.4.NBT.6', 1, 'numeric', 'Partial quotients', 'To find $78 \div 3$, Ana uses partial quotients. She subtracts $20 \times 3 = 60$, which leaves 18. She then finds how many 3s are in 18. What is the whole quotient of $78 \div 3$?', '[]', '26', '20+18/3', 'There are 20 threes in the first step and $18 \div 3 = 6$ threes in the next. $20 + 6 = 26$.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/3 = 6, so 20 + 6 = 26.","run_id":"claude-code","at":"2026-10-24T03:13:29.745Z"}}', 'ai', NULL, NULL)
