INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cfb2a44-e3e2-4224-bb73-801bce70de79', 'NC17.4.NBT.6', 2, 'choice', 'Find the quotient and remainder', 'What is $75 \div 8$?', '["3 R 9","9 R 4","9 R 3","8 R 11"]', '9 R 3', NULL, '$8 \times 9 = 72$ and $75 - 72 = 3$. So $75 \div 8 = 9$ with a remainder of 3.', 'checked', '{"lint":[],"solve":{"answer":"9 R 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 9 = 72, 75 - 72 = 3: 9 R 3.","run_id":"claude-code","at":"2026-10-24T03:13:29.745Z"}}', 'ai', NULL, NULL)
