INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57aad4e5-7485-473f-b972-a7a905b33273', 'NC17.4.NBT.6', 2, 'choice', 'Interpret a quotient and remainder in a story', 'Mr. Lee has 31 muffins and puts 4 muffins in each bag. He fills 7 bags, and $31 \div 4 = 7$ with a remainder of 3. What does the remainder 3 mean?', '["There are 3 bags left over","Each bag holds 3 muffins","There are 3 more bags needed","There are 3 muffins left over"]', 'There are 3 muffins left over', NULL, '7 bags use $7 \times 4 = 28$ muffins. The remainder is the $31 - 28 = 3$ muffins that did not fill a bag.', 'checked', '{"lint":[],"solve":{"answer":"There are 3 muffins left over","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The remainder counts muffins not filling a bag: 3 muffins left over.","run_id":"claude-code","at":"2026-10-24T03:13:29.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45ac9ef2-9488-4b6e-aa68-2d846a8e3aaf', 'NC17.4.NBT.6', 2, 'numeric', 'Check division by multiplying and adding the remainder', 'When a number is divided by 6, the quotient is 17 and the remainder is 5. What is the number?', '[]', '107', '17*6+5', 'The number is the quotient times the divisor plus the remainder: $17 \times 6 + 5 = 102 + 5 = 107$.', 'checked', '{"lint":[],"solve":{"answer":"107","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 17 + 5 = 102 + 5 = 107.","run_id":"claude-code","at":"2026-10-24T03:13:29.745Z"}}', 'ai', NULL, NULL)
