INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11f3b9d4-782a-4428-839d-963298860067', 'NC17.4.NBT.6', 3, 'choice', 'Find the quotient and remainder', 'What is $632 \div 6$?', '["15 R 2","105 R 32","105 R 2","150 R 2"]', '105 R 2', NULL, '$6 \times 100 = 600$ leaves 32. $6 \times 5 = 30$ leaves 2. There are no tens in the quotient, so $632 \div 6 = 105$ with a remainder of 2.', 'checked', '{"lint":[],"solve":{"answer":"105 R 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 105 = 630, 632 - 630 = 2: 105 R 2.","run_id":"claude-code","at":"2026-10-24T03:13:29.745Z"}}', 'ai', NULL, NULL)
