INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16ea24db-4760-44c8-a0da-08bbcb8054a1', 'NC17.4.NBT.6', 3, 'choice', 'Interpret a quotient and remainder in a story', 'Seven friends share 100 stickers equally, and the stickers that cannot be shared evenly are kept. Which statement is true?', '["Each friend gets 15 stickers and 2 are left over","Each friend gets 14 stickers and 7 are left over","Each friend gets 14 stickers and 2 are left over","Each friend gets 2 stickers and 14 are left over"]', 'Each friend gets 14 stickers and 2 are left over', NULL, '$7 \times 14 = 98$ and $100 - 98 = 2$. Each friend gets 14 stickers and 2 are left over.', 'checked', '{"lint":[],"solve":{"answer":"Each friend gets 14 stickers and 2 are left over","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 = 7 x 14 + 2: 14 each, 2 left over.","run_id":"claude-code","at":"2026-10-24T03:13:29.745Z"}}', 'ai', NULL, NULL)
