INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a9b63c3-05a7-4390-94af-5324fe8b329b', 'NC17.4.NF.1', 1, 'choice', 'Recognize equivalent fractions', 'Which fraction is equal to $\frac{1}{2}$?', '["$\\frac{2}{3}$","$\\frac{1}{4}$","$\\frac{3}{6}$","$\\frac{2}{6}$"]', '$\frac{3}{6}$', NULL, 'Multiply the top and the bottom of $\frac{1}{2}$ by 3 to get $\frac{3}{6}$. Adding 1 to both numbers, or changing only one of them, does not keep the amount the same.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/6: 3 is half of 6. 1/4, 2/3, 2/6 are not halves.","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05b8c044-e64a-4631-a680-909cd1b3595a', 'NC17.4.NF.1', 1, 'numeric', 'Equivalent fractions in context', 'A pizza is cut into 8 equal slices, and Ben eats 4 slices. A second pizza of the same size is cut into 2 equal slices. How many slices of the second pizza are the same amount as Ben''s 4 slices?', '[]', '1', '4/8*2', 'Ben ate $\frac{4}{8}$ of a pizza, which is half. One slice of the pizza cut into 2 slices is half, so the answer is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 = 1/2, which is 1 slice of a pizza cut into 2.","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('445627ff-3c7f-4431-86d2-236c4d382290', 'NC17.4.NF.1', 1, 'numeric', 'Divide to make an equivalent fraction', 'Find the ? that makes the fractions equal: $\frac{4}{6}=\frac{?}{3}$.', '[]', '2', '4/2', 'Divide the top and the bottom by 2: $\frac{4\div 2}{6\div 2}=\frac{2}{3}$. Pairs of sixths make thirds. The ? is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/2=3, 4/2=2: 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11f4529b-c1db-4b38-9a91-560c4308f00d', 'NC17.4.NF.1', 2, 'numeric', 'Find a missing numerator or denominator', 'Find the ? that makes the fractions equal: $\frac{3}{4}=\frac{?}{12}$.', '[]', '9', '3*12/4', 'Fourths become twelfths when the top and the bottom are multiplied by 3: $\frac{3\times 3}{4\times 3}=\frac{9}{12}$. The ? is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x3=12, 3x3=9.","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
