INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4219e330-76d6-4f72-a446-b3a98203c86c', 'NC17.4.NF.1', 2, 'numeric', 'Find a missing numerator or denominator', 'Find the ? that makes the fractions equal: $\frac{5}{6}=\frac{20}{?}$.', '[]', '24', '6*20/5', 'The top went from 5 to 20, which is multiplying by 4. Multiply the bottom by 4 too: $6\times 4=24$. The ? is 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x4=20, so 6x4=24.","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('449feb93-fb96-4673-bfdb-25195b3f7838', 'NC17.4.NF.1', 2, 'choice', 'Recognize equivalent fractions', 'Which fraction is NOT equal to $\frac{3}{5}$?', '["$\\frac{6}{10}$","$\\frac{9}{20}$","$\\frac{9}{15}$","$\\frac{12}{20}$"]', '$\frac{9}{20}$', NULL, '$\frac{6}{10}$ (times 2), $\frac{9}{15}$ (times 3) and $\frac{12}{20}$ (times 4) all multiply the top and the bottom by the same number. In $\frac{9}{20}$ the top is multiplied by 3 but the bottom by 4, so it is not equal.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 = 6/10 = 9/15 = 12/20; 9/20 is not (would be 12/20).","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25f532a2-f2e4-4739-bfe4-004f2f998aff', 'NC17.4.NF.1', 3, 'choice', 'Explain why fractions are equivalent', 'A fraction of a bar is renamed using smaller equal parts, and the shaded amount stays the same. Which sentence is true?', '["Only the total number of parts is multiplied, so the fraction stays the same.","Both the shaded parts and all the parts are multiplied by the same number.","The size of each part stays the same, but there are more of them.","Each part gets smaller, so the amount that is shaded gets smaller too."]', 'Both the shaded parts and all the parts are multiplied by the same number.', NULL, 'When every part is cut into the same number of smaller pieces, both the shaded parts and all the parts are multiplied by that number. The pieces are smaller, but the shaded amount does not change.', 'checked', '{"lint":[],"solve":{"answer":"Both the shaded parts and all the parts are multiplied by the same number.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Renaming with smaller parts multiplies both shaded and total parts by the same number; other statements are false.","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c782501-0d7d-46e6-9fcb-c4a6d9cbde03', 'NC17.4.NF.1', 3, 'choice', 'Divide to make an equivalent fraction', 'Which fraction is equal to $\frac{18}{24}$ and has the smallest numerator?', '["$\\frac{3}{4}$","$\\frac{6}{8}$","$\\frac{9}{12}$","$\\frac{2}{3}$"]', '$\frac{3}{4}$', NULL, 'Divide the top and the bottom of $\frac{18}{24}$ by 6 to get $\frac{3}{4}$. $\frac{6}{8}$ and $\frac{9}{12}$ are equal but have larger numerators, and $\frac{2}{3}$ is not equal.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/24 = 9/12 = 6/8 = 3/4; 2/3 is not equal. Smallest numerator among equal ones: 3/4.","run_id":"claude-code","at":"2026-10-24T03:12:41.681Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d127f72-c7b6-4e24-810c-3c1e9890da35', 'NC17.4.NF.2', 1, 'numeric', 'Compare using a common denominator', 'To compare $\frac{1}{2}$ and $\frac{3}{4}$, Sam rewrites $\frac{1}{2}$ with a denominator of 4: $\frac{1}{2}$ = $\frac{?}{4}$. What number is the ?', '[]', '2', '1*4/2', 'Each half is 2 fourths, so 1 half is 2 fourths. The ? is 2. Since 2 fourths is less than 3 fourths, $\frac{1}{2}$ is less than $\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 2/4.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
