VALUES ('006a0177-a1a1-4153-86b0-9189de601425', 'NC17.4.NF.2', 1, 'choice', 'Find the fraction closest to a benchmark or between two fractions', 'Which fraction is closest to 1?', '["$\\frac{1}{8}$","$\\frac{3}{8}$","$\\frac{7}{8}$","$\\frac{4}{8}$"]', '$\frac{7}{8}$', NULL, '7 eighths is only 1 eighth away from 1 whole. The other fractions are farther away.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 is 1/8 from 1; others farther.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
