INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('593824fc-d063-4541-8f37-17859e641309', 'NC17.4.NF.2', 1, 'numeric', 'Compare using a common denominator', 'To compare $\frac{2}{3}$ and $\frac{5}{6}$, rewrite $\frac{2}{3}$ as sixths: $\frac{2}{3}$ = $\frac{?}{6}$. What number is the ?', '[]', '4', '2*6/3', 'Each third is 2 sixths, so 2 thirds is 4 sixths. The ? is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
