INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a0c16b6-16f8-4e75-b176-871da1e24f45', 'NC17.4.NF.2', 2, 'numeric', 'Compare using a common denominator', 'Rewrite $\frac{3}{4}$ as twelfths: $\frac{3}{4}$ = $\frac{?}{12}$. What number is the ?', '[]', '9', '3*12/4', 'Each fourth is 3 twelfths, so 3 fourths is 3 x 3 = 9 twelfths. The ? is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 9/12.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
