INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('225a5657-a41a-4f37-9458-9185027a2405', 'NC17.4.NF.2', 2, 'choice', 'Order fractions', 'Which list is in order from least to greatest?', '["$\\frac{1}{3}$, $\\frac{1}{4}$, $\\frac{1}{6}$","$\\frac{1}{6}$, $\\frac{1}{4}$, $\\frac{1}{3}$","$\\frac{1}{4}$, $\\frac{1}{6}$, $\\frac{1}{3}$","$\\frac{1}{4}$, $\\frac{1}{3}$, $\\frac{1}{6}$"]', '$\frac{1}{6}$, $\frac{1}{4}$, $\frac{1}{3}$', NULL, 'With 1 on top, the more parts a whole has, the smaller each part is. So $\frac{1}{6}$ is the least, then $\frac{1}{4}$, then $\frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$, $\\frac{1}{4}$, $\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit fractions: larger denominator, smaller. 1/6 < 1/4 < 1/3.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10cfbec0-90ab-4fd7-9a79-d6004b34fa54', 'NC17.4.NF.2', 2, 'numeric', 'Compare a fraction with the benchmark one half', 'How many of the fractions $\frac{1}{8}$, $\frac{5}{6}$, $\frac{3}{5}$ and $\frac{7}{12}$ are greater than $\frac{1}{2}$?', '[]', '3', NULL, 'Half of 6 is 3, so 5 sixths is greater. Half of 5 is 2.5, so 3 fifths is greater. Half of 12 is 6, so 7 twelfths is greater. Half of 8 is 4, and 1 is less than 4, so $\frac{1}{8}$ is less. So 3 fractions are greater than one half.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/8 < 1/2; 5/6 > 3/6; 3/5 > 2.5/5; 7/12 > 6/12. Count 3.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dd9a5f6-4df7-4e41-b5a0-bab812200126', 'NC17.4.NF.2', 3, 'numeric', 'Compare fractions in a story', 'One string is $\frac{3}{5}$ meter long and another string is $\frac{58}{100}$ meter long. Enter the fraction that shows the longer string.', '[]', '3/5', '3/5', '3/5 = 60/100. Since 60 hundredths is more than 58 hundredths, the longer string is $\frac{3}{5}$ meter.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 = 60/100 > 58/100.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
