INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66f6a549-073e-497e-a140-e84971b76330', 'NC17.4.NF.2', 3, 'choice', 'Choose a true comparison statement', 'Which comparison is NOT true?', '["$\\frac{7}{12}$ $>$ $\\frac{1}{2}$","$\\frac{5}{6}$ $>$ $\\frac{3}{4}$","$\\frac{3}{8}$ $>$ $\\frac{1}{2}$","$\\frac{3}{4}$ $>$ $\\frac{5}{8}$"]', '$\frac{3}{8}$ $>$ $\frac{1}{2}$', NULL, '1/2 = 4/8, and 3 eighths is less than 4 eighths, so 3/8 > 1/2 is false. The others are true: 7/12 > 6/12; 5/6 = 10/12 > 9/12 = 3/4; 3/4 = 6/8 > 5/8.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$ $>$ $\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 < 4/8 = 1/2, so \"3/8 > 1/2\" is NOT true. 7/12>6/12, 10/12>9/12, 6/8>5/8 are true.","run_id":"claude-code","at":"2026-10-24T03:15:26.437Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18965d83-ed6c-411a-831e-91f9025e0421', 'NC17.4.NF.3', 1, 'numeric', 'Decompose a fraction into a sum of fractions', '$\frac{5}{8} = \frac{2}{8} + \frac{?}{8}$. What number is the ?', '[]', '3', '5-2', 'Fractions with the same denominator can be split by splitting the numerator. 5 eighths is 2 eighths and 3 eighths, so the ? is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 = 2 + 3, so 3.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
