INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a098c4e-ef76-4f55-b870-21ec38df7803', 'NC17.4.NF.3', 1, 'numeric', 'Decompose a fraction into a sum of fractions', '$1 = \frac{2}{5} + \frac{?}{5}$. What number is the ?', '[]', '3', '5-2', 'One whole is $\frac{5}{5}$, so we need 2 fifths and some more fifths to make 5 fifths. 5 - 2 = 3, so the ? is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 = 5/5 = 2/5 + 3/5. So 3.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
