INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43513212-654b-4f86-8010-dd4c616e03b9', 'NC17.4.NF.3', 1, 'choice', 'Solve a story problem with like fractions', 'Maya ate $\frac{2}{8}$ of a pizza. Noor ate $\frac{3}{8}$ of the same pizza. What fraction of the pizza did they eat in all?', '["$\\frac{5}{16}$","$\\frac{1}{8}$","$\\frac{5}{8}$","$\\frac{6}{8}$"]', '$\frac{5}{8}$', NULL, 'Put the amounts together: $\frac{2}{8} + \frac{3}{8}$. Add the numerators: 2 + 3 = 5. They ate $\frac{5}{8}$ of the pizza.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/8 + 3/8 = 5/8.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
