INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3894a709-c1c6-447b-9ba9-2374dd173a1e', 'NC17.4.NF.3', 2, 'choice', 'Add fractions with like denominators', 'What is $\frac{3}{4} + \frac{3}{4}$?', '["$\\frac{6}{8}$","$1\\frac{1}{4}$","$1\\frac{2}{4}$","$2\\frac{1}{4}$"]', '$1\frac{2}{4}$', NULL, 'Add the numerators and keep the denominator: 3 + 3 = 6, so the sum is $\frac{6}{4}$. 4 fourths make 1 whole, so $\frac{6}{4} = 1\frac{2}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{2}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 + 3/4 = 6/4 = 1 2/4.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
