INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('130da281-cb9c-4f6f-9283-8bb7d12e5af2', 'NC17.4.NF.3', 2, 'choice', 'Add mixed numbers with like denominators', 'What is $4\frac{2}{6} + 2\frac{3}{6}$?', '["$6\\frac{5}{12}$","$2\\frac{5}{6}$","$6\\frac{1}{6}$","$6\\frac{5}{6}$"]', '$6\frac{5}{6}$', NULL, 'Add the whole numbers: 4 + 2 = 6. Add the fractions: $\frac{2}{6} + \frac{3}{6} = \frac{5}{6}$. The sum is $6\frac{5}{6}$. The denominator stays 6.', 'checked', '{"lint":[],"solve":{"answer":"$6\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+2 = 6, 2/6+3/6 = 5/6: 6 5/6.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
