INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ca6c9a6-ee75-4b35-9f87-04bb33e7f255', 'NC17.4.NF.3', 2, 'choice', 'Solve a story problem with like fractions', 'A recipe uses $\frac{3}{8}$ cup of oil and $\frac{5}{8}$ cup of vinegar. How much liquid is that in all?', '["$\\frac{2}{8}$ cup","$\\frac{8}{16}$ cup","$\\frac{8}{8}$ cup","$\\frac{15}{8}$ cup"]', '$\frac{8}{8}$ cup', NULL, 'Add the amounts: $\frac{3}{8} + \frac{5}{8}$. 3 + 5 = 8, so the sum is $\frac{8}{8}$ cup, which is 1 whole cup.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{8}{8}$ cup","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 + 5/8 = 8/8 cup.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
