INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e34c8f7-b32b-4e1e-8f30-18b71495c87b', 'NC17.4.NF.3', 3, 'numeric', 'Subtract mixed numbers with like denominators', 'What is $7\frac{2}{10} - 3\frac{6}{10}$? Write the difference as a mixed number.', '[]', '3 6/10', '72/10-36/10', '$\frac{2}{10}$ is less than $\frac{6}{10}$, so write the numbers as fractions: $7\frac{2}{10} = \frac{72}{10}$ and $3\frac{6}{10} = \frac{36}{10}$. Then 72 - 36 = 36, so the answer is $\frac{36}{10} = 3\frac{6}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3 6/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72/10 - 36/10 = 36/10 = 3 6/10.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
