INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54017bd0-77f5-43d0-a4e0-394f959c5eed', 'NC17.4.NF.3', 3, 'numeric', 'Solve a story problem with like fractions', 'A board is $5\frac{3}{8}$ feet long. Dan cuts off $1\frac{5}{8}$ feet to make a shelf. How many feet long is the rest of the board? Write the answer as a mixed number.', '[]', '3 6/8', '43/8-13/8', 'Subtract: $5\frac{3}{8} - 1\frac{5}{8}$. Write them as $\frac{43}{8}$ and $\frac{13}{8}$. Then 43 - 13 = 30, so the rest is $\frac{30}{8} = 3\frac{6}{8}$ feet.', 'checked', '{"lint":[],"solve":{"answer":"3 6/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"43/8 - 13/8 = 30/8 = 3 6/8 (= 3 3/4) feet.","run_id":"claude-code","at":"2026-10-24T03:17:09.845Z"}}', 'ai', NULL, NULL)
