INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0981ec8d-1e8a-4f51-8c4c-3ddb1a8ae890', 'NC17.4.NF.4', 1, 'choice', 'Word problem: total of equal fractional amounts', 'Ana drinks $\frac{1}{4}$ liter of milk each day for 3 days. How many liters of milk does she drink in all?', '["$\\frac{3}{12}$","$\\frac{3}{4}$","$\\frac{1}{12}$","$\\frac{4}{3}$"]', '$\frac{3}{4}$', NULL, 'Three days of $\frac{1}{4}$ liter is $3 \times \frac{1}{4}$ = $\frac{3}{4}$ liter. Only the top number is multiplied. The bottom number stays the same.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 1/4 = 3/4 liter.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
