INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15353b4b-96ed-428b-8baf-89014779f80f', 'NC17.4.NF.4', 1, 'numeric', 'Word problem: total of equal fractional amounts', 'A recipe uses 1/2 cup of flour for one batch. How many cups of flour do 4 batches use?', '[]', '2', '4*1/2', 'Four batches use 1/2 + 1/2 + 1/2 + 1/2 = 4/2 cups. 4/2 is 2 whole cups.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 1/2 = 4/2 = 2 cups.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
