INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fae176b-8ac0-40f4-a1ff-c2c801f2d6ff', 'NC17.4.NF.4', 1, 'choice', 'Word problem: choose the expression or story', 'Each bag holds $\frac{3}{4}$ pound of nuts. Mia has 5 bags. Which expression shows how many pounds of nuts she has in all?', '["$5 + \\frac{3}{4}$","$5 - \\frac{3}{4}$","$5 \\times \\frac{3}{4}$","$4 \\times \\frac{3}{5}$"]', '$5 \times \frac{3}{4}$', NULL, 'There are 5 equal bags of $\frac{3}{4}$ pound, so multiply: $5 \times \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times \\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 bags of 3/4 pound -> 5 x 3/4.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
