INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dc262e8-20d6-498c-883b-cdf1d97a68b2', 'NC17.4.NF.4', 2, 'choice', 'Compare, unknown factor and error checking', 'Dee says that $3 \times \frac{2}{5} = \frac{6}{15}$. What is her mistake?', '["She should have added 3 to the top number, so the answer is $\\frac{5}{5}$.","She made no mistake, because the bottom number is multiplied too.","She should have multiplied 3 by 5, so the answer is $\\frac{2}{15}$.","She also multiplied the bottom number. It stays 5, so the answer is $\\frac{6}{5}$."]', 'She also multiplied the bottom number. It stays 5, so the answer is $\frac{6}{5}$.', NULL, 'Three pieces of $\frac{2}{5}$ are $\frac{6}{5}$. The pieces are still fifths, so only the top number is multiplied.', 'checked', '{"lint":[],"solve":{"answer":"She also multiplied the bottom number. It stays 5, so the answer is $\\frac{6}{5}$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 2/5 = 6/5; she multiplied the denominator too.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
