INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a983f83-3d53-4bf7-af85-040583582961', 'NC17.4.NF.4', 2, 'numeric', 'Multiply and write the product as a mixed number', 'What is $5 \times \frac{7}{10}$? Write the answer as a mixed number.', '[]', '3 1/2', '35/10', '$5 \times \frac{7}{10}$ = $\frac{35}{10}$. Ten tenths make 1 whole, so 35 tenths is 3 wholes and 5 tenths, or 3 5/10. That is the same as 3 1/2.', 'checked', '{"lint":[],"solve":{"answer":"3 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Mixed number not required in simplest form: 3 5/10 and 3 1/2 both right; marker must accept equivalents.","work":"5 x 7/10 = 35/10 = 3 5/10 = 3 1/2.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20cb6f14-e3e1-4184-82c7-5fe6ec70d7cc', 'NC17.4.NF.4', 2, 'choice', 'A fraction as a multiple of a unit fraction', 'Which shows $\frac{8}{5}$ as a multiple of $\frac{2}{5}$?', '["$8 \\times \\frac{2}{5}$","$4 \\times \\frac{2}{5}$","$5 \\times \\frac{2}{5}$","$3 \\times \\frac{2}{5}$"]', '$4 \times \frac{2}{5}$', NULL, '$\frac{8}{5}$ is 8 fifths. Each $\frac{2}{5}$ is 2 fifths, so 8 fifths is 4 of them: $4 \times \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times \\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/5 = 4 x 2/5.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
