INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ebd2bd0-f91f-4000-a265-068822d6ea5e', 'NC17.4.NF.4', 3, 'numeric', 'Word problem: total of equal fractional amounts', 'A machine uses 5/6 gallon of fuel each hour. How many gallons of fuel does it use in 9 hours? Write the answer as a mixed number.', '[]', '7 1/2', '45/6', '9 x 5/6 = 45/6. Six sixths make 1 whole, so 45/6 is 7 wholes and 3/6 left over, or 7 3/6. That is the same as 7 1/2.', 'checked', '{"lint":[],"solve":{"answer":"7 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Mixed number not required in simplest form: 7 3/6 and 7 1/2 both right; marker must accept equivalents.","work":"9 x 5/6 = 45/6 = 7 3/6 = 7 1/2.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
