INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24d4a027-c496-4496-8893-88bf01603dde', 'NC17.4.NF.4', 3, 'choice', 'Compare, unknown factor and error checking', 'Which of these is NOT equal to $\frac{9}{5}$?', '["$4 \\times \\frac{2}{5}$","$9 \\times \\frac{1}{5}$","$3 \\times \\frac{3}{5}$","$1\\frac{4}{5}$"]', '$4 \times \frac{2}{5}$', NULL, '$4 \times \frac{2}{5}$ = $\frac{8}{5}$, not $\frac{9}{5}$. The others are each $\frac{9}{5}$: 9 fifths, 3 groups of 3 fifths, and 1 whole plus 4 fifths.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times \\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 4/5 = 9/5; 4 x 2/5 = 8/5 (not 9/5); 3 x 3/5 = 9/5; 9 x 1/5 = 9/5.","run_id":"claude-code","at":"2026-10-24T08:19:44.244Z"}}', 'ai', NULL, NULL)
