VALUES ('3ed0e117-e89b-4638-9238-ffc9d8f1b556', 'NC17.4.NF.6', 2, 'choice', 'Write a fraction with denominator 10 or 100 as a decimal', 'Which decimal is the same as $\frac{70}{100}$?', '["0.07","7.0","0.17","0.7"]', '0.7', NULL, '70 hundredths is 7 tenths, which is 0.7. 0.07 is only 7 hundredths, and 7.0 is seven wholes.', 'checked', '{"lint":[],"solve":{"answer":"0.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70/100 = 7/10 = 0.7.","run_id":"claude-code","at":"2026-10-24T08:22:27.798Z"}}', 'ai', NULL, NULL)
