INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54a17dab-6790-4e8b-bf52-2e6f488753de', 'NC17.4.NF.7', 3, 'choice', 'Explain or correct reasoning about decimal size', 'Dan says $0.3 < 0.28$ because 3 is less than 28. What is his mistake?', '["He should have said $0.3 = 0.28$, because both begin with a zero before the point","He compared 3 and 28 as whole numbers, but $0.3$ is 30 hundredths, which is more than 28 hundredths","He compared the tenths digits, but the hundredths digits decide","He should have compared the number of digits, because $0.28$ has more digits"]', 'He compared 3 and 28 as whole numbers, but $0.3$ is 30 hundredths, which is more than 28 hundredths', NULL, '$0.3$ is 3 tenths, which is 30 hundredths. 30 hundredths is more than 28 hundredths, so $0.3 > 0.28$. Dan treated 3 and 28 like whole numbers.', 'checked', '{"lint":[],"solve":{"answer":"He compared 3 and 28 as whole numbers, but $0.3$ is 30 hundredths, which is more than 28 hundredths","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3 = 30 hundredths > 28 hundredths; he compared 3 and 28 as whole numbers.","run_id":"claude-code","at":"2026-10-24T08:22:22.534Z"}}', 'ai', NULL, NULL)
