VALUES ('2989776b-0763-4803-8f2b-318b5c12e054', 'NC17.4.MD.8', 3, 'choice', 'Add time intervals', 'Leo starts a task at 4:50 p.m. He works for 40 minutes, takes a 15-minute break, and then works for 25 more minutes. What time does he finish?', '["6:00 p.m.","6:20 p.m.","5:45 p.m.","6:10 p.m."]', '6:10 p.m.', NULL, 'The whole time is 40 + 15 + 25 = 80 minutes, or 1 hour 20 minutes. 4:50 plus 1 hour is 5:50. 5:50 plus 20 minutes is 6:10 p.m.', 'checked', '{"lint":[],"solve":{"answer":"6:10 p.m.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:50 + 40 min = 5:30; + 15 = 5:45; + 25 = 6:10 p.m.","run_id":"claude-code","at":"2026-10-28T18:48:28.285Z"}}', 'ai', NULL, NULL)
