VALUES ('0b539566-e100-4db1-9b4e-0c0c2c606e30', 'NC17.4.MD.8', 3, 'choice', 'Find the elapsed time', 'Which pair of start and end times has exactly 2 hours 45 minutes between them?', '["3:35 p.m. to 6:20 p.m.","3:35 p.m. to 6:10 p.m.","3:35 p.m. to 5:50 p.m.","3:35 p.m. to 6:35 p.m."]', '3:35 p.m. to 6:20 p.m.', NULL, '3:35 plus 2 hours is 5:35. 5:35 plus 25 minutes is 6:00, and 20 more minutes is 6:20. So 3:35 p.m. to 6:20 p.m. is 2 hours 45 minutes.', 'checked', '{"lint":[],"solve":{"answer":"3:35 p.m. to 6:20 p.m.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3:35 + 2h45m = 6:20 p.m. Others: 2h35, 2h15, 3h.","run_id":"claude-code","at":"2026-10-28T18:48:28.461Z"}}', 'ai', NULL, NULL)
