INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('662ee558-fede-45f9-ae95-1815c0bce0cb', 'NC17.4.MD.3', 3, 'choice', 'Fixed area: compare rectangles with the same area', 'Rectangle A is 3 feet by 20 feet. Rectangle B is 12 feet by 5 feet. Which statement is true?', '["Rectangle B has the smaller perimeter.","Rectangle A has the smaller perimeter.","They have the same perimeter because the areas are the same.","Rectangle A has the greater area."]', 'Rectangle B has the smaller perimeter.', NULL, 'Both areas are 60 square feet. The perimeter of A is 2 x (3 + 20) = 46 feet and of B is 2 x (12 + 5) = 34 feet. So B has the smaller perimeter.', 'checked', '{"lint":[],"solve":{"answer":"Rectangle B has the smaller perimeter.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both areas 60. Perimeters A=46, B=34. B smaller.","run_id":"claude-code","at":"2026-10-24T08:30:46.120Z"}}', 'ai', NULL, NULL)
