INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d027a34-15da-494e-9256-a236d6e40973', 'NC17.4.MD.4', 3, 'numeric', 'Read bar graphs and choose a display', 'A bar graph shows how many students chose each weekend activity. Movies: 13. Park: 9. Games: 15. Swimming: 11. Each student chose one activity. How many students were asked?', '[]', '48', '13+9+15+11', 'Add the four bars: 13 + 9 = 22, 22 + 15 = 37, 37 + 11 = 48 students.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13 + 9 + 15 + 11 = 48.","run_id":"claude-code","at":"2026-10-24T08:29:13.707Z"}}', 'ai', NULL, NULL)
