VALUES ('2a91c77e-caea-46ea-95e0-bc09c1875b18', 'NC17.4.MD.6', 3, 'numeric', 'Find an unknown angle', 'A right angle is split into three angles. Two of them are $25^\circ$ and $38^\circ$. How many degrees is the third angle?', '[]', '27', '90-25-38', 'A right angle is 90 degrees. 25 + 38 = 63, and 90 - 63 = 27 degrees.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 - 25 - 38 = 27.","run_id":"claude-code","at":"2026-10-24T08:32:29.433Z"}}', 'ai', NULL, NULL)
