INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03544e72-41cd-48ab-8543-62bf5b69669b', 'NC17.4.G.1', 3, 'choice', 'Classify angles as right, acute or obtuse', 'Angle P is smaller than a square corner. Angle Q is wider than a square corner but is not a straight line. Angle R is exactly a square corner. Which list names the angles P, Q and R in that order?', '["obtuse, acute, right","right, obtuse, acute","acute, right, obtuse","acute, obtuse, right"]', 'acute, obtuse, right', NULL, 'Smaller than a square corner is acute, wider than a square corner (but not straight) is obtuse, and exactly a square corner is right. So P, Q, R are acute, obtuse, right.', 'checked', '{"lint":[],"solve":{"answer":"acute, obtuse, right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P smaller than right: acute; Q wider but not straight: obtuse; R exactly right: right.","run_id":"claude-code","at":"2026-10-24T08:35:45.762Z"}}', 'ai', NULL, NULL)
