INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48e518e7-bc9f-43f9-a7ad-8d70ed4dc228', 'NC17.4.G.2', 2, 'choice', 'Parallel and perpendicular lines and sides', 'Which statement about every rectangle is true?', '["It has no parallel sides","All four of its sides are equal in length","It has four right angles","It has exactly one pair of parallel sides"]', 'It has four right angles', NULL, 'A rectangle has four square corners, so it has four right angles. Its opposite sides are parallel (two pairs), and its sides need not all be equal.', 'checked', '{"lint":[],"solve":{"answer":"It has four right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every rectangle has four right angles; the others are false in general.","run_id":"claude-code","at":"2026-10-24T08:37:47.477Z"}}', 'ai', NULL, NULL)
