INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('420778e6-fd2c-4aa5-92aa-104bad38134d', 'NC17.4.G.2', 2, 'choice', 'Classify a triangle by its angles', 'Which set of angle measures belongs to an acute triangle?', '["$60^\\circ$, $60^\\circ$, $60^\\circ$","$90^\\circ$, $45^\\circ$, $45^\\circ$","$100^\\circ$, $40^\\circ$, $40^\\circ$","$120^\\circ$, $30^\\circ$, $30^\\circ$"]', '$60^\circ$, $60^\circ$, $60^\circ$', NULL, 'An acute triangle has all three angles smaller than $90^\circ$. Only $60^\circ$, $60^\circ$, $60^\circ$ qualifies; the others have a right angle or an obtuse angle.', 'checked', '{"lint":[],"solve":{"answer":"$60^\\circ$, $60^\\circ$, $60^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60,60,60 all under 90: acute. Others have 90, 100 or 120.","run_id":"claude-code","at":"2026-10-24T08:37:47.477Z"}}', 'ai', NULL, NULL)
