INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1be26bf4-b7cb-4ac7-95b0-ec3a52fd158e', 'NC17.4.G.2', 2, 'numeric', 'Sort or count shapes by a property', 'Here are five shapes: a square; a trapezoid with exactly one pair of parallel sides; a triangle; a rhombus; a four-sided shape with no parallel sides. How many of these shapes have at least one pair of parallel sides?', '[]', '3', '3', 'The square, the trapezoid and the rhombus each have at least one pair of parallel sides. A triangle has no parallel sides, and neither does the last shape. So the answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square, trapezoid, rhombus have parallel sides; triangle and the no-parallel quad do not. 3.","run_id":"claude-code","at":"2026-10-24T08:37:47.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('042c1a88-09b0-4c2f-9de0-875e076e4dc6', 'NC17.4.G.2', 3, 'numeric', 'Sort or count shapes by a property', 'Here are six shapes: a rectangle; a square; a rhombus with no right angles; a right triangle; a triangle with angles of $50^\circ$, $60^\circ$ and $70^\circ$; a trapezoid with two right angles. How many of these shapes have at least one right angle?', '[]', '4', '4', 'The rectangle, the square, the right triangle and the trapezoid with two right angles each have a right angle. The rhombus has none and the $50^\circ$, $60^\circ$, $70^\circ$ triangle has none. So 4 shapes qualify.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right angles: rectangle, square, right triangle, trapezoid with two right angles. Not the rhombus or the 50-60-70 triangle. 4.","run_id":"claude-code","at":"2026-10-24T08:37:47.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ed4c70d-72fa-48b5-aa55-4df75c729afb', 'NC17.4.G.2', 3, 'choice', 'Understand how quadrilateral classes overlap', 'Sam says, "Every square is a rectangle." Maria says, "Every rectangle is a square." Who is correct?', '["Both are correct","Only Maria is correct","Only Sam is correct","Neither is correct"]', 'Only Sam is correct', NULL, 'A square has 4 right angles and its opposite sides are equal and parallel, so it is a rectangle. A rectangle that is 3 cm by 5 cm has 4 right angles but sides of different lengths, so it is not a square. Only Sam is correct.', 'checked', '{"lint":[],"solve":{"answer":"Only Sam is correct","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has four right angles, so it is a rectangle. A rectangle need not have equal sides, so not every rectangle is a square. Only Sam.","run_id":"claude-code","at":"2026-10-24T08:46:20.286Z"}}', 'ai', NULL, NULL)
