INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('028e3403-9f5e-4255-9340-71efc969e5ef', 'NC17.4.G.3', 1, 'choice', 'Recognise a figure or letter with line symmetry', 'Which of these flat shapes has no line of symmetry?', '["a square with 4 equal sides and 4 square corners","a triangle with 3 sides of different lengths","a rectangle with two long sides and two short sides","a triangle with 3 sides that are all equal"]', 'a triangle with 3 sides of different lengths', NULL, 'A triangle whose 3 sides are all different cannot be folded so that its two halves match. The other shapes can be folded to match.', 'checked', '{"lint":[],"solve":{"answer":"a triangle with 3 sides of different lengths","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scalene triangle has no line of symmetry; rectangle 2, equilateral 3, square 4.","run_id":"claude-code","at":"2026-10-28T18:48:28.190Z"}}', 'ai', NULL, NULL)
