INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4299e28a-6dff-4984-b882-d2c336d1e6dc', 'NC17.4.G.3', 1, 'numeric', 'Recognise a figure or letter with line symmetry', 'A triangle has sides of 6 cm, 6 cm and 4 cm. How many lines of symmetry does it have?', '[]', '1', '1', 'Two sides are equal, so the triangle can be folded from the corner between them to the middle of the 4 cm side. It has 1 line of symmetry.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Isosceles but not equilateral: 1 line of symmetry (through the apex and the middle of the 4 cm base).","run_id":"claude-code","at":"2026-10-28T18:48:28.292Z"}}', 'ai', NULL, NULL)
