INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a6defde-b433-420c-b0ec-debfc8e34527', 'NC17.4.G.3', 2, 'choice', 'Place and describe lines of symmetry', 'Which statement about a rectangle that is not a square is true?', '["It has 2 lines of symmetry, and both go through the corners","It has 2 lines of symmetry, and neither goes through a corner","It has 4 lines of symmetry, and two go through the corners","It has 1 line of symmetry, and it goes down the middle"]', 'It has 2 lines of symmetry, and neither goes through a corner', NULL, 'The two lines join the middles of opposite sides. A fold along a diagonal does not make the halves match, so no line goes through a corner.', 'checked', '{"lint":[],"solve":{"answer":"It has 2 lines of symmetry, and neither goes through a corner","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-square rectangle: 2 lines of symmetry through midpoints of opposite sides, none through corners.","run_id":"claude-code","at":"2026-10-28T18:48:28.115Z"}}', 'ai', NULL, NULL)
