INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('605f034a-af38-4d35-89ce-9504d69c23dd', 'NC17.4.G.3', 3, 'choice', 'Complete a figure that is symmetric about a line', 'A row has 6 squares, numbered 1 to 6 from the left. A line of symmetry runs down the middle, between squares 3 and 4. Squares 1 and 3 are shaded. Which squares must be shaded for the whole row to be symmetric?', '["1, 3, 5 and 6","1, 2, 5 and 6","1, 3, 4 and 5","1, 3, 4 and 6"]', '1, 3, 4 and 6', NULL, 'Square 1 matches 6 and square 3 matches 4, so squares 1, 3, 4 and 6 are shaded.', 'checked', '{"lint":[],"solve":{"answer":"1, 3, 4 and 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mirror pairs across the line: 1-6, 2-5, 3-4. Shaded 1 and 3 need 6 and 4. Answer 1, 3, 4, 6.","run_id":"claude-code","at":"2026-10-28T18:48:28.342Z"}}', 'ai', NULL, NULL)
