INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135d19d7-4929-42f1-b779-13d9c835b3a0', 'NC17.5.OA.2', 1, 'choice', 'Write an expression for a described calculation', 'Three notebooks cost 4 dollars each and one pen costs 2 dollars. Which expression shows the total cost in dollars?', '["$3 + 4 \\times 2$","$3 \\times 4 + 2$","$3 \\times (4 + 2)$","$(3 + 4) \\times 2$"]', '$3 \times 4 + 2$', NULL, 'The notebooks cost $3 \times 4$ and the pen adds 2.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 4 + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 4 + 2 = 14","run_id":"claude-code","at":"2026-10-24T08:52:41.584Z"}}', 'ai', NULL, NULL)
