VALUES ('1531a3be-76c7-4f03-8218-9a776651938a', 'NC17.5.OA.2', 2, 'numeric', 'Use properties of operations', 'Use the properties of operations to find the value of $2 \times 17 \times 5$.', '[]', '170', '2*17*5', 'Multiply 2 and 5 first: $2 \times 5 = 10$. Then $10 \times 17 = 170$.', 'checked', '{"lint":[],"solve":{"answer":"170","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2 x 5) x 17 = 170","run_id":"claude-code","at":"2026-10-24T08:52:41.584Z"}}', 'ai', NULL, NULL)
