VALUES ('01fe7ee6-8b44-4577-b318-fe25f0daf5db', 'NC17.5.OA.2', 2, 'numeric', 'Use properties of operations', 'Use the distributive property, writing 103 as $100 + 3$, to find $6 \times 103$.', '[]', '618', '6*100+6*3', '$6 \times 100 + 6 \times 3 = 600 + 18 = 618$.', 'checked', '{"lint":[],"solve":{"answer":"618","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 + 18 = 618","run_id":"claude-code","at":"2026-10-24T08:52:41.584Z"}}', 'ai', NULL, NULL)
