INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09d1248c-cc88-4ec9-b22b-a92c9e68ab67', 'NC17.5.OA.2', 2, 'choice', 'Write an expression for a described calculation', 'Jill has 50 dollars and buys 2 books that cost 12 dollars each. Which expression shows how many dollars she has left?', '["$50 - (2 \\times 12)$","$(50 - 2) \\times 12$","$50 - 2 + 12$","$(50 - 2) \\div 12$"]', '$50 - (2 \times 12)$', NULL, 'The books cost $2 \times 12 = 24$ dollars. Subtract that from 50: 26 dollars left.', 'checked', '{"lint":[],"solve":{"answer":"$50 - (2 \\times 12)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 24 = 26","run_id":"claude-code","at":"2026-10-24T08:52:41.584Z"}}', 'ai', NULL, NULL)
