INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12261e25-0820-4352-ab0c-4bb52e627d0c', 'NC17.5.OA.2', 3, 'choice', 'Write an expression for a described calculation', 'Dana buys 3 shirts for 12 dollars each and 2 hats for 9 dollars each. She pays with a 100 dollar bill. Which expression gives her change in dollars?', '["$100 - (3 \\times 12) + (2 \\times 9)$","$100 - (3 + 12 + 2 + 9)$","$100 - (3 + 2) \\times (12 + 9)$","$100 - (3 \\times 12 + 2 \\times 9)$"]', '$100 - (3 \times 12 + 2 \times 9)$', NULL, 'The shirts cost $3 \times 12$ and the hats cost $2 \times 9$. Both costs are taken from 100, so the sum goes in parentheses: $100 - (36 + 18) = 46$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"$100 - (3 \\times 12 + 2 \\times 9)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost = 3 x 12 + 2 x 9 = 36 + 18 = 54; change = 100 - (3 x 12 + 2 x 9) = 46. Option D gives 100 - 36 + 18 = 82, wrong.","run_id":"claude-code","at":"2026-10-24T02:57:19.695Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f4e39b4-5cf7-485e-ac48-e2ca4c7383af', 'NC17.5.OA.2', 3, 'choice', 'Equivalent expressions', 'Which expression equals $12 \times 25$ when 12 is written as $3 \times 4$?', '["$3 \\times (4 \\times 25)$","$3 \\times 4 + 25$","$(3 + 4) \\times 25$","$4 \\times 25 + 3$"]', '$3 \times (4 \times 25)$', NULL, '$3 \times (4 \times 25) = 3 \times 100 = 300 = 12 \times 25$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times (4 \\times 25)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x(4x25) = 300","run_id":"claude-code","at":"2026-10-24T08:52:41.584Z"}}', 'ai', NULL, NULL)
