INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f84588a-6942-4ffe-b2fd-242b925da2f0', 'NC17.5.OA.3', 1, 'choice', 'Find or choose the rule of a pattern', 'Which rule makes the pattern 2, 6, 10, 14?', '["Start at 2 and add 4.","Start at 2 and add 2.","Start at 4 and add 2.","Start at 2 and multiply by 3."]', 'Start at 2 and add 4.', NULL, 'The pattern starts at 2. The terms go up by 6 - 2 = 4, 10 - 6 = 4, and 14 - 10 = 4. The rule is to start at 2 and add 4.', 'checked', '{"lint":[],"solve":{"answer":"Start at 2 and add 4.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 6, 10, 14: starts at 2, differences 4. Multiply by 3 gives 2, 6, 18.","run_id":"claude-code","at":"2026-10-24T02:58:26.498Z"}}', 'ai', NULL, NULL)
