INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07aea12f-0acc-4a46-b4da-d54700771ae2', 'NC17.5.OA.3', 2, 'choice', 'Find or choose the rule of a pattern', 'Which pair of rules makes every term of pattern B 5 more than the matching term of pattern A?', '["A: start at 0, add 2. B: start at 0, add 7.","A: start at 0, add 2. B: start at 5, add 2.","A: start at 0, add 2. B: start at 0, add 10.","A: start at 5, add 2. B: start at 0, add 2."]', 'A: start at 0, add 2. B: start at 5, add 2.', NULL, 'Pattern B must go up by the same amount as A and begin 5 higher. A: 0, 2, 4, ... and B: 5, 7, 9, ... Each B term is 5 more than the A term.', 'checked', '{"lint":[],"solve":{"answer":"A: start at 0, add 2. B: start at 5, add 2.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 0,2,4…; B: 5,7,9… each 5 more.","run_id":"claude-code","at":"2026-10-28T18:47:12.749Z"}}', 'ai', NULL, NULL)
