INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('039479e5-59b7-4c2d-9df6-a76cfb563314', 'NC17.5.NBT.5', 3, 'choice', 'Estimate to check a product', 'Marco finds that $623 \times 47 = 2{,}928$. Which statement shows his answer is not reasonable?', '["It should be about 3,000, because $600 \\times 5 = 3{,}000$","It should be about 300,000, because $600 \\times 500 = 300{,}000$","It is reasonable, because $623 \\times 47$ is less than 3,000","It should be about 30,000, because $600 \\times 50 = 30{,}000$"]', 'It should be about 30,000, because $600 \times 50 = 30{,}000$', NULL, '623 is about 600 and 47 is about 50. 600 x 50 = 30,000, so the product should be near 30,000, not 2,928. (The exact product is 29,281.)', 'checked', '{"lint":[],"solve":{"answer":"It should be about 30,000, because $600 \\times 50 = 30{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"623 x 47 ~ 600 x 50 = 30,000; 2,928 is far too small.","run_id":"claude-code","at":"2026-10-24T03:03:53.757Z"}}', 'ai', NULL, NULL)
