VALUES ('0e93d7cd-3451-4b8b-becb-4ba2e37b7813', 'NC17.5.NBT.6', 2, 'numeric', 'Divide by a multiple of ten', 'A ranch has $4{,}800$ pounds of feed to pack into sacks of 60 pounds each. How many sacks does it fill?', '[]', '80', '4800/60', '$480 \div 6 = 80$, so $4{,}800 \div 60 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4800/60=80.","run_id":"claude-code","at":"2026-10-28T19:24:07.719Z"}}', 'ai', NULL, NULL)
