INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27fab3f1-6e90-4091-a3ef-a30aeba5211e', 'NC17.5.NBT.6', 2, 'numeric', 'Find the remainder', 'What is the remainder when $1{,}000$ is divided by $48$?', '[]', '40', '1000-48*20', '$48 \times 20 = 960$ and $1{,}000 - 960 = 40$. Since 40 is less than 48, the remainder is 40.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48x20=960; 1000-960=40.","run_id":"claude-code","at":"2026-10-28T19:24:07.729Z"}}', 'ai', NULL, NULL)
