INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad8ef90-61b1-4cbf-8043-96ad210ec032', 'NC17.5.NBT.6', 3, 'numeric', 'Divide by a two-digit number', 'What is $9{,}261 \div 21$?', '[]', '441', '9261/21', '21 x 400 = 8,400 and 9,261 - 8,400 = 861. 21 x 40 = 840 and 861 - 840 = 21, which is 1 more group. So 400 + 40 + 1 = 441.', 'checked', '{"lint":[],"solve":{"answer":"441","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21 x 400 = 8,400, remaining 861 = 21 x 41; total 441.","run_id":"claude-code","at":"2026-10-24T03:05:34.581Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08bc7438-54d2-49e5-8323-b06163ff39ce', 'NC17.5.NBT.6', 3, 'choice', 'Find the quotient and the remainder', 'What are the quotient and the remainder of $8{,}429 \div 45$?', '["187 R 14","14 R 187","188 R 31","186 R 59"]', '187 R 14', NULL, '$45 \times 187 = 8{,}415$ and $8{,}429 - 8{,}415 = 14$, so the quotient is 187 and the remainder is 14. A remainder is always less than 45.', 'checked', '{"lint":[],"solve":{"answer":"187 R 14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45x187 = 8415; 8429-8415 = 14 < 45. 187 R 14. (188 R 31: 45x188=8460>8429; 186 R 59: remainder > divisor.)","run_id":"claude-code","at":"2026-10-28T19:24:07.804Z"}}', 'ai', NULL, NULL)
