INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0abbdf2b-da9b-4e89-84d3-320b48e4fcfe', 'NC17.5.NBT.7', 1, 'choice', 'Add decimals', 'What is $0.45 + 0.3$?', '["0.48","0.15","0.075","0.75"]', '0.75', '0.45+0.3', 'Line up the decimal points: 0.45 + 0.30 = 0.75. Be careful: the 3 is 3 tenths, not 3 hundredths.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.45 + 0.30 = 0.75.","run_id":"claude-code","at":"2026-10-24T03:05:24.317Z"}}', 'ai', NULL, NULL)
