INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07af6e10-7f9f-4f2f-89b6-3dac64464130', 'NC17.5.NBT.7', 1, 'choice', 'Divide a decimal by a whole number', 'What is $0.8 \div 4$?', '["2","0.2","0.02","3.2"]', '0.2', '0.8/4', '8 tenths divided into 4 equal groups is 2 tenths, which is 0.2.', 'checked', '{"lint":[],"solve":{"answer":"0.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8 / 4: 8 tenths / 4 = 2 tenths = 0.2.","run_id":"claude-code","at":"2026-10-28T19:28:58.332Z"}}', 'ai', NULL, NULL)
