INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09f91538-352e-41ff-9885-d64233776acb', 'NC17.5.NBT.7', 1, 'numeric', 'Use place value or a model to explain a decimal operation', 'Think of tenths: 0.6 + 0.5 is 6 tenths + 5 tenths, which is 11 tenths. What is 0.6 + 0.5 written as a decimal?', '[]', '1.1', '0.6+0.5', '11 tenths is 10 tenths + 1 tenth. 10 tenths make 1 whole, so the sum is 1.1.', 'checked', '{"lint":[],"solve":{"answer":"1.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 tenths = 1.1.","run_id":"claude-code","at":"2026-10-28T19:29:58.796Z"}}', 'ai', NULL, NULL)
