INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3731adcf-3e07-4cb3-b391-b338a2de2652', 'NC17.5.NBT.7', 2, 'numeric', 'Multiply a decimal by a decimal', 'A rectangle is 0.6 meter wide and 0.4 meter long. What is its area in square meters?', '[]', '0.24', '0.6*0.4', '6 tenths times 4 tenths: $6 \times 4 = 24$, and tenths times tenths gives hundredths. So the area is 0.24 square meter.', 'checked', '{"lint":[],"solve":{"answer":"0.24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6 x 0.4 = 0.24.","run_id":"claude-code","at":"2026-10-24T03:05:24.317Z"}}', 'ai', NULL, NULL)
