VALUES ('1836d809-7bf2-46f4-83ae-32c8ccfbc769', 'NC17.5.NBT.7', 2, 'choice', 'Estimate to check a decimal answer', 'Which is the best estimate of $19.8 - 7.2$?', '["13","27","17","3"]', '13', '13', '19.8 is about 20 and 7.2 is about 7. 20 - 7 = 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"19.8~20, 7.2~7; 20-7=13 (exact 12.6).","run_id":"claude-code","at":"2026-10-28T19:29:58.945Z"}}', 'ai', NULL, NULL)
