INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09595d7f-c4de-4d76-a104-43023aaa2c8a', 'NC17.5.NBT.7', 2, 'choice', 'Decimal problems with two steps', 'A runner runs 2.4 kilometers on each of 3 days and 1.5 kilometers on a fourth day. How many kilometers does the runner run in all?', '["3.9","7.2","8.7","10.8"]', '8.7', '3*2.4+1.5', '3 x 2.4 = 7.2. Then 7.2 + 1.5 = 8.7 kilometers.', 'checked', '{"lint":[],"solve":{"answer":"8.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 2.4 = 7.2; 7.2 + 1.5 = 8.7.","run_id":"claude-code","at":"2026-10-28T19:29:58.973Z"}}', 'ai', NULL, NULL)
