INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07833f51-e6d4-4115-9ef5-9562add476f6', 'NC17.5.NBT.7', 3, 'numeric', 'Multiply a decimal by a decimal', 'A rectangular garden is 2.4 meters long and 1.5 meters wide. What is its area in square meters?', '[]', '3.6', '2.4*1.5', '$24 \times 15 = 360$. Each factor has 1 decimal place, so the product has 2 decimal places: 3.60. The area is 3.6 square meters.', 'checked', '{"lint":[],"solve":{"answer":"3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4 x 1.5 = 3.6.","run_id":"claude-code","at":"2026-10-24T03:05:24.317Z"}}', 'ai', NULL, NULL)
