INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b22eed4-1872-4924-ae67-11b6e894d7a4', 'NC17.5.NBT.7', 3, 'choice', 'Multiply a decimal by a decimal', 'What is $3.2 \times 0.15$?', '["4.8","0.48","0.048","0.5"]', '0.48', '3.2*0.15', '32 x 15 = 480. The factors have 3 decimal places in all, so the product is 0.480, or 0.48.', 'checked', '{"lint":[],"solve":{"answer":"0.48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32 x 15 = 480; three decimal places -> 0.480 = 0.48.","run_id":"claude-code","at":"2026-10-28T19:29:58.740Z"}}', 'ai', NULL, NULL)
