INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57475ec8-90fe-4f8f-bf75-96ff4f5eed20', 'NC17.5.NF.1', 1, 'numeric', 'Add fractions with unlike denominators', 'Add: $\frac{1}{2} + \frac{1}{4}$', '[]', '3/4', '1/2+1/4', 'Rename $\frac{1}{2}$ as $\frac{2}{4}$. Then $\frac{2}{4} + \frac{1}{4} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2=2/4; 2/4+1/4=3/4.","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
