INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63641553-2848-4e64-a8e0-59cb36f8305c', 'NC17.5.NF.1', 1, 'numeric', 'Solve fraction addition word problems', 'Mia ate $\frac{1}{3}$ of a pizza and Leo ate $\frac{1}{6}$ of the same pizza. What fraction of the pizza did they eat in all? Write the answer in simplest form.', '[]', '1/2', '1/3+1/6', 'Rename $\frac{1}{3}$ as $\frac{2}{6}$. Then $\frac{2}{6} + \frac{1}{6} = \frac{3}{6}$, which is $\frac{1}{2}$ in simplest form.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3=2/6; 2/6+1/6=3/6=1/2.","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
