INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4627834c-d2d5-4236-ade6-4ae961af3e2e', 'NC17.5.NF.1', 1, 'numeric', 'Rename fractions with a common denominator', 'What number makes this true? $\frac{2}{3} = \frac{?}{6}$', '[]', '4', '2*2', 'To change thirds to sixths, multiply the top and bottom by 2: $\frac{2}{3} = \frac{2 \times 2}{3 \times 2} = \frac{4}{6}$. The ? is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6 (multiply top and bottom by 2).","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
