INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6deb84b3-1acb-42d1-9063-9fa7443b3fef', 'NC17.5.NF.1', 2, 'numeric', 'Add mixed numbers with unlike denominators', 'One strip of tape is $2\frac{1}{3}$ inches long and another is $1\frac{1}{6}$ inches long. Put end to end, how many inches long are they? Write the answer as a mixed number in simplest form.', '[]', '3 1/2', '(2+1/3)+(1+1/6)', 'Add the wholes: 2 + 1 = 3. Add the fractions: $\frac{1}{3} + \frac{1}{6} = \frac{2}{6} + \frac{1}{6} = \frac{3}{6} = \frac{1}{2}$. The total is $3\frac{1}{2}$ inches.', 'checked', '{"lint":[],"solve":{"answer":"3 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 1/3 = 2 2/6; 2 2/6+1 1/6=3 3/6=3 1/2.","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a154ceb-6947-487c-a51b-9f18a4c32110', 'NC17.5.NF.1', 2, 'choice', 'Estimate sums and differences with benchmark numbers', 'Round each mixed number to the nearest whole number to estimate $4\frac{7}{8} + 2\frac{1}{10}$. What is the estimate?', '["6","7","8","5"]', '7', '5+2', '$4\frac{7}{8}$ is close to 5 and $2\frac{1}{10}$ is close to 2. The estimate is 5 + 2 = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 7/8 rounds to 5, 2 1/10 rounds to 2; 5+2=7.","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
