INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31634ef9-caf8-4f9e-8484-5827c8064919', 'NC17.5.NF.1', 2, 'choice', 'Solve fraction subtraction word problems', 'A ribbon is $\frac{5}{8}$ yard long. Sam cuts off $\frac{1}{4}$ yard. How long is the ribbon now?', '["$\\frac{3}{8}$","$\\frac{1}{2}$","$\\frac{4}{4}$","$\\frac{7}{8}$"]', '$\frac{3}{8}$', NULL, 'Rename $\frac{1}{4}$ as $\frac{2}{8}$. Then $\frac{5}{8} - \frac{2}{8} = \frac{3}{8}$ yard.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4=2/8; 5/8-2/8=3/8.","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40c74155-b106-4700-9926-af8643ec2cf6', 'NC17.5.NF.1', 3, 'numeric', 'Solve fraction addition word problems', 'A trail has three parts. The parts are $\frac{1}{2}$ mile, $\frac{1}{4}$ mile and $\frac{3}{8}$ mile long. How many miles long is the whole trail? Write the answer as a mixed number.', '[]', '1 1/8', '1/2+1/4+3/8', 'Rename each part in eighths: $\frac{4}{8} + \frac{2}{8} + \frac{3}{8} = \frac{9}{8}$, which is $1\frac{1}{8}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"1 1/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8+2/8+3/8=9/8=1 1/8.","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bc4af3e-f0d5-44f5-b003-3ad78168bcdc', 'NC17.5.NF.1', 3, 'choice', 'Find a missing fraction or starting amount', 'Ben drinks $\frac{3}{8}$ liter of water from a bottle. Then $1\frac{1}{4}$ liters are left. How many liters were in the bottle at first?', '["$\\frac{7}{8}$","$1\\frac{1}{3}$","$1\\frac{5}{8}$","$1\\frac{1}{2}$"]', '$1\frac{5}{8}$', NULL, 'Add what he drank to what is left: $1\frac{1}{4} + \frac{3}{8} = 1\frac{2}{8} + \frac{3}{8} = 1\frac{5}{8}$ liters.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8+1 1/4=3/8+10/8=13/8=1 5/8.","run_id":"claude-code","at":"2026-10-24T03:07:13.222Z"}}', 'ai', NULL, NULL)
