INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38b9246f-ca91-48f4-8074-c83582b702d0', 'NC17.5.NF.3', 1, 'numeric', 'Share equally: the share is less than 1', '1 pound of cheese is shared equally by 4 people. What fraction of a pound does each person get?', '[]', '1/4', '1/4', 'Sharing 1 pound equally among 4 people is 1 ÷ 4. As a fraction, 1 ÷ 4 = 1/4 of a pound.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 pound shared by 4: 1 / 4 = 1/4 pound each.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
