INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7da210f7-20ee-4a66-bb4b-c00239b01fa0', 'NC17.5.NF.3', 1, 'numeric', 'A fraction is the numerator divided by the denominator', '$7 \div 9 = \frac{?}{9}$. What number is the ?', '[]', '7', '7', 'A division like 7 ÷ 9 is the fraction with 7 on top and 9 on the bottom: 7/9. So the ? is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 / 9 = 7/9, so the missing numerator is 7.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
