INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('229c8bd4-2768-4338-8f39-b3619ec4dd30', 'NC17.5.NF.3', 1, 'choice', 'A fraction is the numerator divided by the denominator', 'Which sentence about $\frac{5}{6}$ is true?', '["It is the same as 6 divided by 5","It is the same as 5 times 6","It is the same as 5 divided by 6","It is the same as 6 take away 5"]', 'It is the same as 5 divided by 6', NULL, 'A fraction is its numerator divided by its denominator. So 5/6 is 5 divided by 6.', 'checked', '{"lint":[],"solve":{"answer":"It is the same as 5 divided by 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 = 5 divided by 6.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
