INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('470e4d66-3a56-4e21-9c6b-cecf9e5bef8c', 'NC17.5.NF.3', 2, 'choice', 'Size of a quotient: between which whole numbers', 'Between which two whole numbers is $17 \div 5$?', '["2 and 3","4 and 5","5 and 6","3 and 4"]', '3 and 4', NULL, '5 × 3 = 15 and 5 × 4 = 20. 17 is between 15 and 20, so 17 ÷ 5 is between 3 and 4. (It equals 3 2/5.)', 'checked', '{"lint":[],"solve":{"answer":"3 and 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 / 5 = 3 2/5 = 3.4, between 3 and 4.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
