VALUES ('153c3c4d-0f3c-497c-9a03-2f792fd0c44c', 'NC17.5.NF.3', 2, 'numeric', 'Share equally: the share is less than 1', 'A teacher cuts 6 yards of cloth equally for 8 students. How many yards of cloth does each student get?', '[]', '3/4', '6/8', 'Each student gets 6 ÷ 8 = 6/8 yard. Dividing the top and bottom by 2, 6/8 = 3/4 yard.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / 8 = 6/8 = 3/4 yard each.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
