INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1459b177-0d15-4b0c-ae32-77a5374dafb2', 'NC17.5.NF.3', 2, 'choice', 'Match a sharing story to a division', 'Mia shares 8 crackers equally among 5 friends. Which number sentence shows how many crackers each friend gets?', '["$5 \\div 8 = \\frac{5}{8}$","$8 \\div 5 = \\frac{8}{5}$","$8 \\times 5 = 40$","$8 - 5 = 3$"]', '$8 \div 5 = \frac{8}{5}$', NULL, 'Sharing 8 crackers equally among 5 friends is 8 ÷ 5. As a fraction, 8 ÷ 5 = 8/5, so each friend gets 8/5 = 1 3/5 crackers.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\div 5 = \\frac{8}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 crackers among 5 friends: 8 / 5 = 8/5 each.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
