INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e459239-8f53-462f-9a9b-ef12bdc419bc', 'NC17.5.NF.3', 3, 'choice', 'A fraction is the numerator divided by the denominator', 'Which division is equal to $5\frac{2}{3}$?', '["$17 \\div 5$","$13 \\div 3$","$17 \\div 3$","$5 \\div 3$"]', '$17 \div 3$', NULL, '5 2/3 = (5 × 3 + 2)/3 = 17/3, and 17/3 means 17 ÷ 3.', 'checked', '{"lint":[],"solve":{"answer":"$17 \\div 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 2/3 = (15+2)/3 = 17/3 = 17 / 3. Others: 5/3 = 1 2/3, 17/5 = 3 2/5, 13/3 = 4 1/3.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
