INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59365954-4481-4f1a-ab75-54038d2dd393', 'NC17.5.NF.3', 3, 'choice', 'Find the error in a sharing problem', 'Dev says that 3 pizzas shared equally among 8 people gives each person $\frac{8}{3}$ of a pizza. What mistake did he make?', '["He divided the number of pizzas by the number of people","He added the number of pizzas and the number of people","He divided the number of people by the number of pizzas","He multiplied the number of pizzas by the number of people"]', 'He divided the number of people by the number of pizzas', NULL, 'The pizzas are shared among the people, so each person gets 3 ÷ 8 = 3/8 of a pizza. Dev wrote 8/3, which is 8 ÷ 3, so he divided the people by the pizzas.', 'checked', '{"lint":[],"solve":{"answer":"He divided the number of people by the number of pizzas","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct: 3 / 8 = 3/8. Dev wrote 8/3 = 8 / 3, i.e. people divided by pizzas.","run_id":"claude-code","at":"2026-10-24T03:06:56.197Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
