INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('154b06e6-f897-492d-870c-612b4ab0b24c', 'NC17.5.MD.4', 1, 'choice', 'Recognizing volume and cubic units', 'What does the volume of a solid measure?', '["The length of its longest edge","The distance around its base","The amount of space inside the solid","The amount of flat surface it covers"]', 'The amount of space inside the solid', NULL, 'Volume is the amount of space a solid takes up. Edge length and the distance around are lengths, and flat surface is area.', 'checked', '{"lint":[],"solve":{"answer":"The amount of space inside the solid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume is the amount of space a solid occupies/encloses.","run_id":"claude-code","at":"2026-10-24T03:17:18.725Z"}}', 'ai', NULL, NULL)
