INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20836894-61e8-4b42-9f16-5fa18ec3b1ea', 'NC17.5.MD.4', 2, 'choice', 'Counting cubes in layers', 'A box is filled with 3 layers of unit cubes. Each layer has 4 rows of 6 cubes. Which expression gives the number of unit cubes in the box?', '["$3 + 4 + 6$","$3 \\times 4 \\times 6$","$3 \\times 4 + 6$","$4 \\times 6$"]', '$3 \times 4 \times 6$', NULL, 'Each layer has $4 \times 6$ cubes and there are 3 layers, so the total is $3 \times 4 \times 6$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 4 \\times 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each layer 4 x 6 cubes, 3 layers: 3 x 4 x 6 = 72.","run_id":"claude-code","at":"2026-10-24T03:17:18.725Z"}}', 'ai', NULL, NULL)
