INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1919ff6d-3710-4590-967c-4c0ecf6339c5', 'NC17.5.MD.4', 3, 'numeric', 'Volume of a figure built from cube towers', 'A solid sits on a square base of 3 by 3 towers. The 4 corner towers are each 1 cube high, the 4 edge towers are each 2 cubes high, and the center tower is 4 cubes high. What is the volume of the solid in cubic units?', '[]', '16', '4*1+4*2+4', 'Corners: $4 \times 1 = 4$ cubes. Edges: $4 \times 2 = 8$ cubes. Center: 4 cubes. The total is $4 + 8 + 4 = 16$ cubic units.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corners 4 x 1 = 4, edges 4 x 2 = 8, center 4: total 16.","run_id":"claude-code","at":"2026-10-24T03:17:18.725Z"}}', 'ai', NULL, NULL)
