INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0512fa7c-ac36-4909-a159-fee2c2e4e364', 'NC17.5.MD.4', 3, 'numeric', 'Measuring with improvised units', 'Ella fills a bin exactly with 150 identical blocks. The bin has a volume of 1,200 cubic centimeters. What is the volume of one block, in cubic centimeters?', '[]', '8', '1200/150', 'The 150 blocks share the 1,200 cubic centimeters equally. $1200 \div 150 = 8$ cubic centimeters for each block.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 blocks fill 1,200 cubic cm, so each is 1200 / 150 = 8 cubic cm.","run_id":"claude-code","at":"2026-10-24T03:17:18.725Z"}}', 'ai', NULL, NULL)
