INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6fd05941-b9e6-42e6-b8fa-6bb509398e3f', 'NC17.5.MD.5', 1, 'choice', 'Volume of a cube', 'A cube has edges that are each 3 inches long. What is its volume in cubic inches?', '["9","12","18","27"]', '27', '3*3*3', 'A cube is a rectangular prism whose length, width and height are all 3 inches, so its volume is $3 \times 3 \times 3 = 27$ cubic inches. The answer 9 is the area of one face.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 3 x 3 = 27.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
