INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d8f6e25-0f15-4adb-aedd-e983d0a568c5', 'NC17.5.MD.5', 1, 'numeric', 'Volume in a real situation', 'A sandbox is shaped like a rectangular prism. It is 6 feet long, 5 feet wide, and 2 feet deep. How many cubic feet of sand will fill it?', '[]', '60', '6*5*2', 'The volume is $6 \times 5 \times 2 = 60$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 5 x 2 = 60 cubic feet.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
