INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dfd9d25-9879-43c6-b55f-6cfd102aaf06', 'NC17.5.MD.5', 1, 'choice', 'Volume of two joined prisms', 'A shape is made of two prisms joined together. The prisms have volumes of 15 cubic centimeters and 9 cubic centimeters. What is the volume of the whole shape?', '["6 cubic centimeters","24 cubic centimeters","135 cubic centimeters","15 cubic centimeters"]', '24 cubic centimeters', NULL, 'The volume of the whole shape is the sum of the volumes of its two parts: $15 + 9 = 24$ cubic centimeters. Subtracting or multiplying the volumes does not fit joining two solids.', 'checked', '{"lint":[],"solve":{"answer":"24 cubic centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 9 = 24 cubic centimeters.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
