INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f20c49f-b9f9-43cb-b3da-7da3d80b0a02', 'NC17.5.MD.5', 2, 'numeric', 'Volume by layers', 'A packing box holds unit cubes. The bottom layer is 7 cubes by 3 cubes, and the box is filled to 4 layers. How many unit cubes are in the box?', '[]', '84', '7*3*4', 'One layer has $7 \times 3 = 21$ cubes. Four layers have $21 \times 4 = 84$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Layer 7 x 3 = 21; 4 layers = 84.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
