INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a737555-fb65-4f89-b87f-565542f4d564', 'NC17.5.MD.5', 2, 'choice', 'Volume formula base area x height', 'A rectangular prism has a base with area $B$ and a height $h$. Which formula gives its volume $V$?', '["$V = B \\times h$","$V = B + h$","$V = B \\div h$","$V = 2 \\times B \\times h$"]', '$V = B \times h$', NULL, 'The volume of a prism is the area of its base times its height, so $V = B \times h$.', 'checked', '{"lint":[],"solve":{"answer":"$V = B \\times h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume = base area x height.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62b078ce-2580-4407-84cd-08ca7862e184', 'NC17.5.MD.5', 2, 'numeric', 'Missing dimension from the volume', 'A rectangular prism has a volume of 48 cubic units. Its bottom layer has 12 unit cubes. How many layers tall is the prism?', '[]', '4', '48/12', 'Each layer has 12 cubes, and all the layers together make 48. So the number of layers is $48 \div 12 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 / 12 = 4 layers.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('221b2398-62ec-4fb1-8880-1857998fcb33', 'NC17.5.MD.5', 3, 'choice', 'Volume of two joined prisms', 'A solid is made of two prisms joined along a face. The first is 4 by 5 by 6 and the second is 3 by 5 by 6, where the 5 by 6 faces are joined. Which expression gives the volume of the whole solid?', '["$(4 + 3) \\times 5 \\times 6$","$4 \\times 3 \\times 5 \\times 6$","$(4 + 3) \\times (5 + 5) \\times 6$","$4 + 3 + 5 + 6$"]', '$(4 + 3) \times 5 \times 6$', NULL, 'The two prisms share the same 5 by 6 face, so together they are one prism that is $4 + 3 = 7$ long, 5 wide and 6 tall. Its volume is $(4 + 3) \times 5 \times 6$, which is the same as $4 \times 5 \times 6 + 3 \times 5 \times 6$.', 'checked', '{"lint":[],"solve":{"answer":"$(4 + 3) \\times 5 \\times 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x5x6 + 3x5x6 = (4+3) x 5 x 6 = 210 by the distributive property.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12792af8-4a6e-4f01-b8c3-8aa9b79e358d', 'NC17.5.MD.5', 3, 'choice', 'Volume as addition', 'A solid is built in two layers of unit cubes. The bottom layer is 6 cubes by 5 cubes. The top layer is 6 cubes by 2 cubes. How many unit cubes are in the solid?', '["42","60","19","72"]', '42', '6*5+6*2', 'The bottom layer has $6 \times 5 = 30$ cubes and the top layer has $6 \times 2 = 12$ cubes. Together: $30 + 12 = 42$. Treating both layers as the bottom layer would give 60.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom 6 x 5 = 30; top 6 x 2 = 12; total 42.","run_id":"claude-code","at":"2026-10-24T08:22:16.922Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3907e539-2d0b-4b60-b5fb-b0c803938871', 'NC17.5.G.1', 1, 'choice', 'Name a point as an ordered pair', 'Point $P$ is 4 units to the right of the origin and 7 units up. Which ordered pair names $P$?', '["$(7, 4)$","$(0, 11)$","$(4, 7)$","$(11, 0)$"]', '$(4, 7)$', NULL, 'The first number says how far to go right and the second how far to go up. Right 4 and up 7 is $(4, 7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 4 (right), y = 7 (up): (4, 7).","run_id":"claude-code","at":"2026-10-24T08:22:22.570Z"}}', 'ai', NULL, NULL)
