INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('391c2659-77b6-41fd-b356-dc53750b1c37', 'NC17.5.G.1', 2, 'choice', 'Name a point as an ordered pair', 'Dev plots a point by moving 5 units up from the origin and then 2 units to the right. Which ordered pair names the point?', '["$(2, 5)$","$(5, 2)$","$(7, 0)$","$(0, 7)$"]', '$(2, 5)$', NULL, 'The ordered pair always lists right first, then up. Dev went 2 right and 5 up, so the point is $(2, 5)$, even though he moved up first.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 right, 5 up: (2, 5).","run_id":"claude-code","at":"2026-10-24T08:22:22.570Z"}}', 'ai', NULL, NULL)
