INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03cdcef0-3882-4197-a5e8-89aa7b1c3fc6', 'NC17.5.G.1', 2, 'choice', 'Axes and the origin', 'Which of these points lies on the y-axis?', '["$(6, 0)$","$(6, 6)$","$(1, 6)$","$(0, 6)$"]', '$(0, 6)$', NULL, 'Every point on the y-axis has x-coordinate 0, since it has not moved right. Only $(0, 6)$ fits.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"On the y-axis x = 0: (0, 6).","run_id":"claude-code","at":"2026-10-24T08:22:22.570Z"}}', 'ai', NULL, NULL)
