INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bda4933-aa0a-421d-ac09-9240c09d0757', 'NC17.5.G.1', 2, 'numeric', 'Missing corner of a rectangle or square', 'Three corners of a rectangle are $(1, 1)$, $(6, 1)$ and $(6, 4)$. What is the x-coordinate of the fourth corner?', '[]', '1', '1', 'The fourth corner is directly above $(1, 1)$ and level with $(6, 4)$, so it is $(1, 4)$. Its x-coordinate is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle with sides on x = 1, x = 6, y = 1, y = 4; missing corner (1, 4); x = 1.","run_id":"claude-code","at":"2026-10-24T08:22:22.570Z"}}', 'ai', NULL, NULL)
