INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('319e85de-4fd0-42ec-959f-8a5919527d4d', 'NC17.5.G.1', 3, 'numeric', 'Move from a point', 'A point at $(3, 5)$ is moved to the right and then up until it is at $(9, 12)$. How many units did it move in all?', '[]', '13', '(9-3)+(12-5)', 'It moved right $9 - 3 = 6$ units and up $12 - 5 = 7$ units. In all that is $6 + 7 = 13$ units.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right 9 - 3 = 6, up 12 - 5 = 7, total 13.","run_id":"claude-code","at":"2026-10-24T08:22:22.570Z"}}', 'ai', NULL, NULL)
