INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('081f3a08-9547-40de-9149-a0ec9eaf0cb1', 'NC17.5.G.1', 3, 'numeric', 'Distance between points on a grid line', 'A rectangular garden has corners at $(2, 1)$, $(8, 1)$, $(8, 5)$ and $(2, 5)$. Each unit on the grid is 1 meter. What is the distance around the garden, in meters?', '[]', '20', '2*((8-2)+(5-1))', 'The bottom side runs from x = 2 to x = 8, so it is 6 meters. The side runs from y = 1 to y = 5, so it is 4 meters. The distance around is $2 \times (6 + 4) = 20$ meters.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 8 - 2 = 6, width 5 - 1 = 4; perimeter 2(6 + 4) = 20 m.","run_id":"claude-code","at":"2026-10-24T08:22:22.570Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e6e9539-147a-4968-9d66-a2b663fd0989', 'NC17.5.G.3', 1, 'choice', 'Attributes pass down to subcategories', 'Which attribute do ALL parallelograms have, so that every rectangle has it too?', '["All four sides are equal","All four angles are right angles","Exactly one pair of parallel sides","Opposite sides are parallel"]', 'Opposite sides are parallel', NULL, 'Every parallelogram has opposite sides that are parallel, and a rectangle is a parallelogram. Equal sides and right angles are not true of all parallelograms.', 'checked', '{"lint":[],"solve":{"answer":"Opposite sides are parallel","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All parallelograms have opposite sides parallel, inherited by rectangles. Others are not true of all parallelograms.","run_id":"claude-code","at":"2026-10-28T18:48:28.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5648b15-7074-4a91-9443-5fd0e5593b27', 'NC17.5.G.3', 1, 'numeric', 'Attributes pass down to subcategories', 'Every parallelogram has 2 pairs of parallel sides. A rectangle is a parallelogram. How many pairs of parallel sides does every rectangle have?', '[]', '2', '2', 'A rectangle is a parallelogram, so it has every attribute of a parallelogram. It has 2 pairs of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle is a parallelogram, so it inherits 2 pairs of parallel sides.","run_id":"claude-code","at":"2026-10-28T18:48:28.354Z"}}', 'ai', NULL, NULL)
