INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3aa58559-edfa-45bc-882a-268cc4e6415b', 'NC17.5.G.3', 1, 'choice', 'True and false statements about the hierarchy', 'Which statement is NOT always true?', '["A square is a rhombus","A rectangle is a rhombus","A square is a parallelogram","A rhombus is a parallelogram"]', 'A rectangle is a rhombus', NULL, 'A rectangle can have sides of different lengths, but a rhombus has 4 equal sides. The other three statements are always true.', 'checked', '{"lint":[],"solve":{"answer":"A rectangle is a rhombus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rectangle need not have equal sides, so it is not always a rhombus; the others are always true.","run_id":"claude-code","at":"2026-10-28T18:48:28.446Z"}}', 'ai', NULL, NULL)
