INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('095883db-5bc1-43b1-8c62-b85516106d7a', 'NC17.5.G.3', 2, 'choice', 'Classify a shape from its attributes', 'A quadrilateral has 4 equal sides, but its corners are not square corners. Which is the most specific name that fits?', '["square","rectangle","rhombus","parallelogram"]', 'rhombus', NULL, 'Four equal sides make it a rhombus. Because its corners are not square corners, it is not a square or a rectangle. "Parallelogram" is true but less specific.', 'checked', '{"lint":[],"solve":{"answer":"rhombus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides makes it a rhombus; no right angles so not a square (or rectangle). Most specific: rhombus.","run_id":"claude-code","at":"2026-10-28T18:48:27.830Z"}}', 'ai', NULL, NULL)
