INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c4a68e1-97e3-47bd-bd76-5926c4049b00', 'NC17.5.G.3', 2, 'choice', 'True and false statements about the hierarchy', 'Maya says, "A rectangle can never be a rhombus." Which fact shows she is wrong?', '["A rectangle has four right angles but may have unequal sides","A rhombus has four equal sides but may have unequal angles","A square has four right angles and four equal sides","Every parallelogram has two pairs of parallel sides"]', 'A square has four right angles and four equal sides', NULL, 'A square has four right angles, so it is a rectangle. It also has four equal sides, so it is a rhombus. One shape that is both shows that a rectangle can be a rhombus.', 'checked', '{"lint":[],"solve":{"answer":"A square has four right angles and four equal sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square is a rectangle with four equal sides, so it is a rhombus too: a rectangle can be a rhombus.","run_id":"claude-code","at":"2026-10-28T18:48:28.181Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b1f4272-355f-4107-aaa2-3edf4b21a770', 'NC17.5.G.3', 2, 'choice', 'Attributes pass down to subcategories', 'All parallelograms have opposite sides that are equal in length. Which shapes must also have opposite sides equal in length?', '["Rectangles, rhombuses, and squares","Rectangles and squares only","Rhombuses and squares only","Every kind of quadrilateral"]', 'Rectangles, rhombuses, and squares', NULL, 'Rectangles, rhombuses and squares are all parallelograms, so they all have this attribute. A quadrilateral that is not a parallelogram may not have it.', 'checked', '{"lint":[],"solve":{"answer":"Rectangles, rhombuses, and squares","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles, rhombuses and squares are all parallelograms, so all have opposite sides equal.","run_id":"claude-code","at":"2026-10-28T18:48:28.596Z"}}', 'ai', NULL, NULL)
