INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0719d8bf-59fa-4397-98f4-0a2a3e5e92db', 'NC17.5.G.3', 3, 'choice', 'True and false statements about the hierarchy', 'Which statement is true?', '["Some rhombuses are rectangles","No rhombus is a rectangle","Every rhombus is a rectangle","Every rectangle is a rhombus"]', 'Some rhombuses are rectangles', NULL, 'A square is a rhombus and also a rectangle, so some rhombuses are rectangles. A rhombus with angles that are not right angles is not a rectangle, and a rectangle with unequal sides is not a rhombus.', 'checked', '{"lint":[],"solve":{"answer":"Some rhombuses are rectangles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square is both a rhombus and a rectangle, so some rhombuses are rectangles.","run_id":"claude-code","at":"2026-10-28T18:47:12.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23c42a2c-bf25-4c43-92de-2be2bb104f92', 'NC17.5.G.3', 3, 'choice', 'Order and nest the categories', 'What is the most specific category that includes all rectangles, all rhombuses, and all squares?', '["quadrilaterals","parallelograms","rectangles","rhombuses"]', 'parallelograms', NULL, 'All three kinds have 2 pairs of parallel sides, so all are parallelograms. Quadrilaterals include them too, but that category is broader. Rectangles do not include every rhombus, and rhombuses do not include every rectangle.', 'checked', '{"lint":[],"solve":{"answer":"parallelograms","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles, rhombuses and squares are all parallelograms; rhombuses are not all rectangles and vice versa. Most specific: parallelograms.","run_id":"claude-code","at":"2026-10-28T18:48:27.836Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('015022ac-05b3-4ef8-b80d-ec3c34a4e6dc', 'NC17.6.RP.1', 1, 'numeric', 'Part-to-part and part-to-whole ratios', 'A bowl has 4 apples and 6 oranges. The ratio of apples to all the fruit is 4 to ?. What is the ?', '[]', '10', '4+6', 'All the fruit is $4 + 6 = 10$ pieces, so the ratio of apples to all the fruit is 4 to 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All fruit = 4+6 = 10, so apples to all fruit is 4 to 10.","run_id":"claude-code","at":"2026-10-24T02:58:36.389Z"}}', 'ai', NULL, NULL)
