INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28cf0c27-5b39-4fc9-b9ed-4c01954d2a7e', 'NC17.6.RP.1', 1, 'numeric', 'Find a missing quantity from a ratio', 'A zoo has 3 lions for every 2 tigers. The zoo has 10 tigers. How many lions does it have?', '[]', '15', '10/2*3', '10 tigers is 5 groups of 2 tigers. Each group goes with 3 lions, so there are 5 x 3 = 15 lions.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/2=5 groups; 5*3=15 lions.","run_id":"claude-code","at":"2026-10-28T18:48:28.495Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f267655-0162-4250-b4d5-ad66fe177eb7', 'NC17.6.RP.1', 1, 'choice', 'Tape diagrams', 'A tape diagram has 2 equal boxes for Jo''s marbles and 5 equal boxes of the same size for Sam''s marbles. Which is the ratio of Jo''s marbles to Sam''s marbles?', '["5 to 2","2 to 7","7 to 5","2 to 5"]', '2 to 5', NULL, 'Jo has 2 boxes and Sam has 5 boxes of the same size, so the ratio of Jo''s marbles to Sam''s marbles is 2 to 5.', 'checked', '{"lint":[],"solve":{"answer":"2 to 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 boxes to 5 boxes: 2 to 5.","run_id":"claude-code","at":"2026-10-28T18:48:28.537Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08e7544c-ef33-4a51-8f23-2f3f9abc1b0d', 'NC17.6.RP.1', 2, 'choice', 'Tape diagrams', 'Which tape diagram matches the ratio 3 to 2 of apples to pears?', '["2 equal boxes for apples and 3 equal boxes of the same size for pears","3 equal boxes for apples and 2 equal boxes of the same size for pears","3 equal boxes for apples and 5 equal boxes of the same size for pears","5 equal boxes for apples and 2 equal boxes of the same size for pears"]', '3 equal boxes for apples and 2 equal boxes of the same size for pears', NULL, 'The ratio 3 to 2 is shown by 3 boxes for apples and 2 boxes for pears, all the same size. Swapping the counts, or using the total of 5, shows a different ratio.', 'checked', '{"lint":[],"solve":{"answer":"3 equal boxes for apples and 2 equal boxes of the same size for pears","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Apples 3 boxes, pears 2 boxes of same size.","run_id":"claude-code","at":"2026-10-24T02:58:36.389Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07ed7c15-4bce-4df1-81b5-9a6b194d5cfa', 'NC17.6.RP.1', 2, 'choice', 'Multiplicative, not additive, reasoning', 'A recipe uses 2 cups of oats with 3 cups of milk. A bigger batch uses 6 cups of oats. Zoe says it needs 7 cups of milk, because 6 is 4 more than 2. Which statement is correct?', '["It needs 7 cups of milk, because both amounts go up by the same number","It needs 8 cups of milk, because the amount of milk doubles","It needs 12 cups of milk, because the amount of milk is multiplied by 4","It needs 9 cups of milk, because both amounts are multiplied by 3"]', 'It needs 9 cups of milk, because both amounts are multiplied by 3', NULL, 'To keep the ratio, multiply both amounts by the same number. 2 x 3 = 6, so 3 x 3 = 9 cups of milk. Adding 4 to both amounts does not keep the ratio.', 'checked', '{"lint":[],"solve":{"answer":"It needs 9 cups of milk, because both amounts are multiplied by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/2 = 3, so milk is 3×3 = 9 cups (multiplicative, not additive).","run_id":"claude-code","at":"2026-10-28T18:47:12.699Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05483030-7342-4531-bf1b-cbe49c3c4cd8', 'NC17.6.RP.1', 2, 'choice', 'Multiplicative, not additive, reasoning', 'Which statement about ratios is true?', '["Multiplying both numbers of a ratio by 4 gives an equivalent ratio","Adding 4 to both numbers of a ratio gives an equivalent ratio","Reversing the order of the two numbers gives an equivalent ratio","Subtracting 4 from both numbers of a ratio gives an equivalent ratio"]', 'Multiplying both numbers of a ratio by 4 gives an equivalent ratio', NULL, 'An equivalent ratio comes from multiplying or dividing both numbers by the same number. Adding or subtracting does not keep the ratio, and reversing the order changes what is compared.', 'checked', '{"lint":[],"solve":{"answer":"Multiplying both numbers of a ratio by 4 gives an equivalent ratio","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equivalent ratios come from multiplying (or dividing) both numbers by the same nonzero number. Adding/subtracting or reversing does not (e.g. 1:2 vs 5:6, 2:1).","run_id":"claude-code","at":"2026-10-28T18:48:28.093Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cc19ca7-ea34-4d45-a221-b590de07208a', 'NC17.6.RP.1', 3, 'numeric', 'Solving ratio problems by scaling', 'The ratio of Lee''s marbles to Kai''s marbles is 5 to 3. Lee gives 6 marbles to Kai, and then they have the same number. How many marbles did Lee have at first?', '[]', '30', '(6+6)/2*5', 'Lee has 2 more parts than Kai, and giving away 6 evens them out, so the 2 parts are $6 + 6 = 12$ marbles and 1 part is 6 marbles. Lee started with $5 \times 6 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lee 5k, Kai 3k. 5k-6 = 3k+6 -> k = 6. Lee had 30 (Kai 18; both 24 after).","run_id":"claude-code","at":"2026-10-24T02:58:36.389Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09109650-1fa7-4524-8575-c1fe1f61dbaf', 'NC17.6.RP.1', 3, 'choice', 'Equivalent ratios', 'Which ratio is equivalent to 18 to 30 and has 21 as its first number?', '["21 to 33","21 to 35","21 to 30","21 to 50"]', '21 to 35', NULL, '18 to 30 simplifies to 3 to 5. Multiplying by 7 gives 21 to 35. Adding 3 to both numbers gives 21 to 33, and the others do not keep the ratio.', 'checked', '{"lint":[],"solve":{"answer":"21 to 35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18:30 = 3:5; 21 = 3*7, so 5*7 = 35: 21 to 35.","run_id":"claude-code","at":"2026-10-24T02:58:36.389Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04acb5d6-dc14-4435-902e-fbddc2cd36d8', 'NC17.6.RP.2', 1, 'choice', 'Interpret a unit rate in context', 'A worker earns 90 dollars in 6 hours. Which sentence gives the unit rate in dollars per hour?', '["The worker works 15 hours for each dollar.","The worker earns 84 dollars each hour.","The worker earns 15 dollars each hour.","The worker earns 540 dollars each hour."]', 'The worker earns 15 dollars each hour.', NULL, 'Divide the dollars by the hours: 90 / 6 = 15. The worker earns 15 dollars each hour.', 'checked', '{"lint":[],"solve":{"answer":"The worker earns 15 dollars each hour.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 / 6 = 15 dollars per hour.","run_id":"claude-code","at":"2026-10-24T02:58:26.536Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0296f13c-44dd-4a55-97b5-34e57e224e46', 'NC17.6.RP.2', 1, 'choice', 'Find both unit rates of a ratio', 'A turtle walks 10 feet in 5 minutes. Which pair gives both unit rates?', '["0.5 foot per minute and 2 minutes per foot","5 feet per minute and 2 minutes per foot","2 feet per minute and 0.5 minute per foot","2 feet per minute and 2 minutes per foot"]', '2 feet per minute and 0.5 minute per foot', NULL, '$10 \div 5 = 2$ feet per minute, and $5 \div 10 = 0.5$ minute per foot.', 'checked', '{"lint":[],"solve":{"answer":"2 feet per minute and 0.5 minute per foot","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/5 = 2 ft per minute; 5/10 = 0.5 minute per foot.","run_id":"claude-code","at":"2026-10-28T19:04:15.392Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('000ba727-b339-4246-9678-aaf9377c6ab2', 'NC17.6.RP.2', 1, 'choice', 'Interpret a unit rate in context', 'A cyclist rides 30 miles in 2 hours, which is a unit rate of 15 miles per hour. What does this unit rate mean?', '["The cyclist rides 15 miles in each hour.","The cyclist rides 15 hours for each mile.","The cyclist rides 2 miles in each hour.","The cyclist rides 30 miles in each hour."]', 'The cyclist rides 15 miles in each hour.', NULL, 'A rate of 15 miles per hour means 15 miles for each 1 hour: $30 \div 2 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"The cyclist rides 15 miles in each hour.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 miles per hour means 15 miles in each hour.","run_id":"claude-code","at":"2026-10-28T19:04:15.579Z"}}', 'ai', NULL, NULL)
