INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1985b6-28c8-4f9c-a687-4c6516e5a8ea', 'NC17.6.RP.2', 2, 'numeric', 'Write a ratio as an equivalent unit ratio', 'In a drink, 3 cups of juice are mixed with 12 cups of water. How many cups of water are there for each cup of juice?', '[]', '4', '12/3', 'Divide both amounts by 3: 12 / 3 = 4 cups of water for each 3 / 3 = 1 cup of juice.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 3 = 4 cups of water per cup of juice.","run_id":"claude-code","at":"2026-10-24T02:58:26.536Z"}}', 'ai', NULL, NULL)
