INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a5921a8-f5e3-4a1d-b12e-1868d3f66d40', 'NC17.6.RP.2', 2, 'choice', 'Use a unit rate to find an amount', 'A machine makes 18 parts every 4 minutes. How many parts does it make in 10 minutes at the same rate?', '["72","180","2.2","45"]', '45', '18/4*10', 'The unit rate is $18 \div 4 = 4.5$ parts per minute, so 10 minutes gives $4.5 \times 10 = 45$ parts.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/4 = 4.5 parts per minute; x10 = 45.","run_id":"claude-code","at":"2026-10-28T19:04:15.594Z"}}', 'ai', NULL, NULL)
