INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0385b615-1091-4688-b7bb-5cfdbafe05b9', 'NC17.6.RP.2', 2, 'numeric', 'Find a unit rate', 'A printer prints 135 pages in 9 minutes at a steady rate. How many pages does it print in 1 minute?', '[]', '15', '135/9', 'Divide the pages by the minutes: $135 \div 9 = 15$ pages per minute.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"135/9 = 15.","run_id":"claude-code","at":"2026-10-28T19:04:15.611Z"}}', 'ai', NULL, NULL)
