INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('120cf4c1-4042-49fa-9b93-b90709394b0b', 'NC17.6.RP.2', 3, 'choice', 'Write a ratio as an equivalent unit ratio', 'Which pair gives both unit ratios for the ratio 15 to 20?', '["$\\frac{4}{3}$ to 1 and 1 to $\\frac{3}{4}$","$\\frac{3}{4}$ to 1 and 1 to $\\frac{4}{3}$","15 to 1 and 1 to 20","3 to 1 and 1 to 4"]', '$\frac{3}{4}$ to 1 and 1 to $\frac{4}{3}$', NULL, 'Divide by 20 to make the second number 1: 15/20 = 3/4, so 3/4 to 1. Divide by 15 to make the first number 1: 20/15 = 4/3, so 1 to 4/3.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$ to 1 and 1 to $\\frac{4}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/20 = 3/4, so 3/4 to 1; 20/15 = 4/3, so 1 to 4/3.","run_id":"claude-code","at":"2026-10-24T02:58:26.536Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('038a4ba3-b21a-4feb-9e45-ea431e9c2e9a', 'NC17.6.RP.2', 3, 'choice', 'Find both unit rates of a ratio', 'A bakery sells 3 loaves of bread for 7.50 dollars. Which statement gives both unit rates?', '["Each loaf costs 0.4 dollar, and 2.50 loaves are sold for each dollar.","Each loaf costs 2.50 dollars, and 2.50 loaves are sold for each dollar.","Each loaf costs 22.50 dollars, and 0.4 loaf is sold for each dollar.","Each loaf costs 2.50 dollars, and 0.4 loaf is sold for each dollar."]', 'Each loaf costs 2.50 dollars, and 0.4 loaf is sold for each dollar.', NULL, '$7.50 \div 3 = 2.50$ dollars for each loaf, and $3 \div 7.50 = 0.4$ loaf for each dollar.', 'checked', '{"lint":[],"solve":{"answer":"Each loaf costs 2.50 dollars, and 0.4 loaf is sold for each dollar.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.50/3 = 2.50 dollars per loaf; 3/7.50 = 0.4 loaf per dollar.","run_id":"claude-code","at":"2026-10-28T19:04:15.477Z"}}', 'ai', NULL, NULL)
