VALUES ('075a8e21-2d75-447c-89af-400abacd198b', 'NC17.6.RP.3', 1, 'choice', 'Measurement conversions with ratios', 'There are 12 inches in 1 foot. How many inches are in 5 feet?', '["60","17","7","2.4"]', '60', '5*12', 'Each foot is 12 inches, so 5 feet is $5 \times 12 = 60$ inches.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 12 = 60.","run_id":"claude-code","at":"2026-10-24T02:57:08.318Z"}}', 'ai', NULL, NULL)
