INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05beab25-5915-44cf-8440-1bb27b7f26dc', 'NC17.6.RP.3', 2, 'choice', 'Ratio tables and equivalent ratios', 'A ratio table has the rows 4 to 10 and 6 to 15. Which pair could be another row of the same table?', '["8 to 14","9 to 20","10 to 25","12 to 24"]', '10 to 25', NULL, 'In both rows the second number is 2.5 times the first: $10 \div 4 = 2.5$ and $15 \div 6 = 2.5$. For 10 to 25, $25 \div 10 = 2.5$ too, so it fits. The other pairs do not have a ratio of 2.5.', 'checked', '{"lint":[],"solve":{"answer":"10 to 25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 2:5. 10 to 25 = 2:5. 12:24 = 1:2, 9:20 no, 8:14 = 4:7.","run_id":"claude-code","at":"2026-10-24T02:57:08.318Z"}}', 'ai', NULL, NULL)
