VALUES ('00a03f09-1bb8-4c4b-a8b7-048625b60570', 'NC17.6.RP.4', 2, 'choice', 'percent of a quantity', 'Which expression gives 20% of 35?', '["$\\frac{100}{20} \\times 35$","$20 \\times 35$","$\\frac{20}{100} \\times 35$","$\\frac{20}{35} \\times 100$"]', '$\frac{20}{100} \times 35$', NULL, '20% means 20 out of 100, which is $\frac{20}{100}$. Taking 20% of 35 means multiplying: $\frac{20}{100} \times 35 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{20}{100} \\times 35$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20% = 20/100, so 20% of 35 = (20/100) x 35 = 7.","run_id":"claude-code","at":"2026-10-24T02:56:51.406Z"}}', 'ai', NULL, NULL)
