INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1c06f4-d6be-4430-b9d7-e36c65939e57', 'NC17.6.NS.1', 1, 'choice', 'Interpret a quotient of fractions', 'Which division has a quotient of 10?', '["$10 \\div \\frac{1}{2}$","$5 \\div 2$","$\\frac{1}{2} \\div 5$","$5 \\div \\frac{1}{2}$"]', '$5 \div \frac{1}{2}$', NULL, '$5 \div \frac{1}{2}$ asks how many halves are in 5, and there are 2 halves in each whole, so the quotient is 10. The others give 20, $\frac{5}{2}$ and $\frac{1}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\div \\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 / 5 = 1/10; 5/2=2.5; 5 / (1/2)=10; 10 / (1/2)=20.","run_id":"claude-code","at":"2026-10-28T19:24:07.679Z"}}', 'ai', NULL, NULL)
