INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('075760a2-437a-48b2-96ae-fb56df11cbeb', 'NC17.6.NS.1', 2, 'choice', 'Divide fractions with common denominators', 'Which shows $\frac{2}{3} \div \frac{3}{4}$ rewritten with common denominators?', '["$\\frac{2}{12} \\div \\frac{3}{12}$","$\\frac{8}{12} \\div \\frac{3}{12}$","$\\frac{3}{12} \\div \\frac{4}{12}$","$\\frac{8}{12} \\div \\frac{9}{12}$"]', '$\frac{8}{12} \div \frac{9}{12}$', NULL, 'The least common denominator of 3 and 4 is 12. $\frac{2}{3} = \frac{8}{12}$ and $\frac{3}{4} = \frac{9}{12}$, so the problem becomes $\frac{8}{12} \div \frac{9}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{8}{12} \\div \\frac{9}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3=8/12, 3/4=9/12.","run_id":"claude-code","at":"2026-10-28T19:24:07.724Z"}}', 'ai', NULL, NULL)
