INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0535b1cc-369c-46ad-a81a-858e390d950f', 'NC17.6.NS.1', 2, 'choice', 'Interpret a quotient of fractions', 'Which story is modeled by $\frac{3}{4} \div \frac{1}{8}$?', '["How many $\\frac{1}{8}$-cup scoops fit in $\\frac{3}{4}$ cup of flour?","What is $\\frac{1}{8}$ of $\\frac{3}{4}$ cup of flour?","What is $\\frac{3}{4}$ cup of flour shared equally by 8 people?","How much flour is in $\\frac{1}{8}$ cup plus $\\frac{3}{4}$ cup?"]', 'How many $\frac{1}{8}$-cup scoops fit in $\frac{3}{4}$ cup of flour?', NULL, '$\frac{3}{4} \div \frac{1}{8}$ asks how many pieces of size $\frac{1}{8}$ fit in $\frac{3}{4}$, which is the scoop question.', 'checked', '{"lint":[],"solve":{"answer":"How many $\\frac{1}{8}$-cup scoops fit in $\\frac{3}{4}$ cup of flour?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Division by 1/8 asks how many 1/8s fit in 3/4 (6 scoops).","run_id":"claude-code","at":"2026-10-28T19:24:08.015Z"}}', 'ai', NULL, NULL)
