INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08cdb4e8-6e80-484b-a4a0-3187640b26d5', 'NC17.6.NS.1', 3, 'numeric', 'Interpret a quotient of fractions', 'Dan divides a number by $\frac{5}{8}$ and gets 4. What is the number?', '[]', '5/2', '4*5/8', 'Division can be undone by multiplication: the number is $4 \times \frac{5}{8} = \frac{20}{8} = \frac{5}{2}$, or $2\frac{1}{2}$. Check: $\frac{5}{2} \div \frac{5}{8} = \frac{20}{8} \div \frac{5}{8} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"5/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 4 x 5/8 = 20/8 = 5/2.","run_id":"claude-code","at":"2026-10-24T03:03:53.794Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ed255cf-3a3e-4a1e-a04d-843a4c49090a', 'NC17.6.NS.1', 3, 'numeric', 'Fraction division word problem', 'A 6 meter ribbon is cut into pieces that are each $\frac{3}{4}$ meter long. Then every piece is cut in half. How many small pieces are there?', '[]', '16', '6/(3/4)*2', '$6 \div \frac{3}{4} = 8$ pieces. Cutting each in half doubles the count: $8 \times 2 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 ÷ 3/4 = 8 pieces; each cut in half → 16.","run_id":"claude-code","at":"2026-10-28T19:24:07.660Z"}}', 'ai', NULL, NULL)
