VALUES ('238d814c-3ed5-4d33-a80c-03d4e352bc6a', 'NC17.6.NS.2', 1, 'choice', 'Use multiplication to check or reverse a division', 'A number is divided by $24$. The quotient is $150$ and the remainder is $11$. What is the number?', '["$3{,}611$","$3{,}600$","$185$","$3{,}589$"]', '$3{,}611$', NULL, 'Dividend = divisor $\times$ quotient + remainder = $24 \times 150 + 11 = 3{,}611$.', 'checked', '{"lint":[],"solve":{"answer":"$3{,}611$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 x 150 + 11 = 3600 + 11 = 3611.","run_id":"claude-code","at":"2026-10-28T19:34:46.054Z"}}', 'ai', NULL, NULL)
