VALUES ('4b6d373c-9bcf-4958-97f1-340b57b272d8', 'NC17.6.NS.3', 2, 'choice', 'Add decimals', 'At a store, Ravi buys items that cost 12.49 dollars, 7.80 dollars and 3.05 dollars. What is the total cost in dollars?', '["22.34","23.44","22.44","23.34"]', '23.34', '12.49+7.8+3.05', '12.49 + 7.80 = 20.29. Then 20.29 + 3.05 = 23.34.', 'checked', '{"lint":[],"solve":{"answer":"23.34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12.49 + 7.80 = 20.29; 20.29 + 3.05 = 23.34.","run_id":"claude-code","at":"2026-10-24T03:05:55.350Z"}}', 'ai', NULL, NULL)
