INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0df07bb3-a0a3-45b2-bffc-3e7b0f230f4b', 'NC17.6.NS.3', 3, 'choice', 'Divide whole numbers to get a decimal quotient', 'What is $27 \div 8$?', '["3.35","3.375","3.75","3.125"]', '3.375', '27/8', '8 goes into 27 three times with 3 left over. 3 is 30 tenths, and 8 goes into 30 three times with 6 left. 60 hundredths gives 7 with 4 left, then 40 thousandths gives 5. The quotient is 3.375.', 'checked', '{"lint":[],"solve":{"answer":"3.375","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27 / 8 = 3 remainder 3; 3/8 = 0.375; so 3.375.","run_id":"claude-code","at":"2026-10-24T03:05:55.350Z"}}', 'ai', NULL, NULL)
