INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36ef32a0-4477-4370-acbb-720b479461b6', 'NC17.6.NS.4', 1, 'numeric', 'Find a least common multiple', 'What is the least common multiple of 4 and 6?', '[]', '12', NULL, 'Multiples of 4: 4, 8, 12, 16. Multiples of 6: 6, 12, 18. The smallest multiple in both lists is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 4: 4,8,12; of 6: 6,12. LCM 12.","run_id":"claude-code","at":"2026-10-24T03:07:13.259Z"}}', 'ai', NULL, NULL)
