INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16c4e96b-fc0c-48c3-96ea-70a19a761256', 'NC17.6.NS.4', 1, 'choice', 'Prime factorization', 'Which is the prime factorization of 18?', '["$2 \\times 9$","$3 \\times 6$","$1 \\times 18$","$2 \\times 3 \\times 3$"]', '$2 \times 3 \times 3$', NULL, '$18 = 2 \times 9$, and 9 is not prime, so break it up: $9 = 3 \times 3$. The prime factorization is $2 \times 3 \times 3$. The other choices still contain numbers that are not prime.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times 3 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18=2x3x3; the others contain non-primes (9, 6, 1, 18).","run_id":"claude-code","at":"2026-10-24T03:07:13.259Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1702d865-5bcb-4245-94ae-193e69142039', 'NC17.6.NS.4', 1, 'choice', 'Find a greatest common factor', 'What is the greatest common factor of 8 and 20?', '["2","4","8","40"]', '4', NULL, 'Factors of 8: 1, 2, 4, 8. Factors of 20: 1, 2, 4, 5, 10, 20. The greatest factor in both lists is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8=2^3, 20=2^2x5; GCF 4.","run_id":"claude-code","at":"2026-10-24T03:07:13.259Z"}}', 'ai', NULL, NULL)
