INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3db5f1c6-2d1d-41e3-85fd-acc74eccc772', 'NC17.6.NS.4', 2, 'numeric', 'Prime factorization', 'How many times does the prime factor 2 appear in the prime factorization of 72?', '[]', '3', NULL, '$72 = 8 \times 9 = (2 \times 2 \times 2) \times (3 \times 3)$. The prime factor 2 appears 3 times.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72=2^3x3^2; 2 appears 3 times.","run_id":"claude-code","at":"2026-10-24T03:07:13.259Z"}}', 'ai', NULL, NULL)
