INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('363cee4d-3723-4ff9-a7a8-d17cfcd589af', 'NC17.6.NS.4', 2, 'choice', 'Prime factorization', 'Which shows the prime factorization of 60?', '["$2 \\times 3 \\times 10$","$4 \\times 3 \\times 5$","$2^2 \\times 3 \\times 5$","$2^2 \\times 3^2 \\times 5$"]', '$2^2 \times 3 \times 5$', NULL, '$60 = 4 \times 15 = (2 \times 2) \times (3 \times 5)$, so the prime factorization is $2^2 \times 3 \times 5$. The other choices contain numbers that are not prime, or multiply to a different number.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 3 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60=2^2x3x5=4x3x5. Options B and C contain non-primes; A is 180.","run_id":"claude-code","at":"2026-10-24T03:07:13.259Z"}}', 'ai', NULL, NULL)
