INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d8c4105-2698-4492-bf14-63c0a09f5710', 'NC17.6.NS.4', 3, 'numeric', 'Prime factorization', 'What number has the prime factorization $2^3 \times 3^2 \times 5$?', '[]', '360', '2^3*3^2*5', '$2^3 = 8$ and $3^2 = 9$. Then $8 \times 9 = 72$ and $72 \times 5 = 360$.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x9x5=360.","run_id":"claude-code","at":"2026-10-24T03:07:13.259Z"}}', 'ai', NULL, NULL)
