INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ee30700-01c7-4094-9333-d2961008fa57', 'NC17.6.NS.4', 3, 'numeric', 'Solve word problems with the greatest common factor', 'Mr. Chen has 48 pencils and 72 erasers. He makes as many identical packs as he can, using every pencil and every eraser. How many pencils are in each pack?', '[]', '2', '48/24', 'The greatest number of identical packs is the GCF of 48 and 72, which is 24. Each pack then has $48 \div 24 = 2$ pencils (and $72 \div 24 = 3$ erasers).', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(48,72)=24 packs; 48/24=2 pencils per pack (3 erasers).","run_id":"claude-code","at":"2026-10-24T03:07:13.259Z"}}', 'ai', NULL, NULL)
