INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bee991c-dd7c-4c97-995b-d258dd4b06e1', 'NC17.6.NS.6', 1, 'choice', 'Locating points by their coordinates', 'Which statement about the point $(0, -3)$ is true?', '["It is on the $x$-axis, 3 units to the left of the origin","It is on the $y$-axis, 3 units below the origin","It is on the $y$-axis, 3 units above the origin","It is in Quadrant III"]', 'It is on the $y$-axis, 3 units below the origin', NULL, 'The $x$-coordinate is $0$, so the point is on the $y$-axis. The $y$-coordinate is $-3$, so it is 3 units below the origin. A point on an axis is not in any quadrant.', 'checked', '{"lint":[],"solve":{"answer":"It is on the $y$-axis, 3 units below the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0 so it lies on the y-axis; y=-3 so 3 units below the origin.","run_id":"claude-code","at":"2026-10-24T03:11:51.341Z"}}', 'ai', NULL, NULL)
