INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b66cf1f-b3e7-48e6-98c3-ae56002cea6f', 'NC17.6.NS.6', 1, 'numeric', 'Position on a number line', 'On a number line, what number is exactly halfway between $-4$ and $0$?', '[]', '-2', '-4/2', 'The distance from $-4$ to $0$ is 4 units. Halfway is 2 units from each end, which is at $-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midpoint of -4 and 0 is (-4+0)/2 = -2.","run_id":"claude-code","at":"2026-10-24T03:11:51.341Z"}}', 'ai', NULL, NULL)
