VALUES ('01904dbd-29a7-45bb-968d-ec0669553755', 'NC17.6.NS.6', 2, 'choice', 'Opposite of a number', 'What is the opposite of the opposite of $-6.2$?', '["$-6.2$","$6.2$","$-12.4$","$0$"]', '$-6.2$', '-6.2', 'Taking the opposite twice returns to the starting number. The opposite of $-6.2$ is $6.2$, and the opposite of $6.2$ is $-6.2$.', 'checked', '{"lint":[],"solve":{"answer":"$-6.2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite of -6.2 is 6.2; opposite of 6.2 is -6.2.","run_id":"claude-code","at":"2026-10-24T03:11:51.341Z"}}', 'ai', NULL, NULL)
