INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('245766a2-5600-4878-959e-09099634476e', 'NC17.6.NS.6', 3, 'choice', 'Describing a reflection from coordinates', 'Points $(a, b)$ and $(a, -b)$ are plotted, and $b$ is not $0$. Which statement is true?', '["They are reflections of each other across the $y$-axis","They are the same point on the grid","They are reflections of each other across the $x$-axis","They are on the same horizontal line"]', 'They are reflections of each other across the $x$-axis', NULL, 'The $x$-coordinates match and the $y$-coordinates are opposites. That is a reflection across the $x$-axis. Because $b$ is not $0$, the points are different and have different heights, so they are not on one horizontal line.', 'checked', '{"lint":[],"solve":{"answer":"They are reflections of each other across the $x$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x, opposite y (b nonzero): reflections across the x-axis. Not on the same horizontal line, not the same point.","run_id":"claude-code","at":"2026-10-24T03:11:51.341Z"}}', 'ai', NULL, NULL)
