INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('008360ef-c503-4b80-a177-2dd23107a756', 'NC17.6.NS.7', 2, 'choice', 'Absolute value and order', 'Sam says $-9$ is greater than $-4$ because 9 is greater than 4. Which response is correct?', '["Yes. $-9$ is farther from 0, so $-9 > -4$.","No. $-9$ is closer to 0, so $-9 < -4$.","No. $-9$ is farther left on the number line, so $-9 < -4$.","Yes. A negative number with a larger digit is a greater number."]', 'No. $-9$ is farther left on the number line, so $-9 < -4$.', NULL, '$-9$ lies to the left of $-4$, so $-9<-4$. Distance from 0 does not tell which negative number is greater.', 'checked', '{"lint":[],"solve":{"answer":"No. $-9$ is farther left on the number line, so $-9 < -4$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9 is left of -4, so -9 < -4.","run_id":"claude-code","at":"2026-10-24T03:12:41.757Z"}}', 'ai', NULL, NULL)
