VALUES ('3d00bc1d-8d32-47d0-9f75-d73c27a0e39d', 'NC17.6.NS.7', 2, 'choice', 'Order rational numbers', 'Which list of fractions and decimals is in order from least to greatest?', '["$-0.6$, $-\\frac{1}{2}$, $\\frac{1}{4}$, $0.3$","$-\\frac{1}{2}$, $-0.6$, $\\frac{1}{4}$, $0.3$","$-0.6$, $-\\frac{1}{2}$, $0.3$, $\\frac{1}{4}$","$\\frac{1}{4}$, $0.3$, $-\\frac{1}{2}$, $-0.6$"]', '$-0.6$, $-\frac{1}{2}$, $\frac{1}{4}$, $0.3$', NULL, 'As decimals the numbers are $-0.6$, $-0.5$, $0.25$ and $0.3$. In order from least to greatest, that is $-0.6$, $-\frac{1}{2}$, $\frac{1}{4}$, $0.3$.', 'checked', '{"lint":[],"solve":{"answer":"$-0.6$, $-\\frac{1}{2}$, $\\frac{1}{4}$, $0.3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-0.6 < -0.5 < 0.25 < 0.3.","run_id":"claude-code","at":"2026-10-24T03:12:41.757Z"}}', 'ai', NULL, NULL)
