INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c83e2ae-4357-47aa-be57-45ac44007fe7', 'NC17.6.NS.8', 2, 'numeric', 'Vertical distance between points', 'On a treasure map, one unit is one step. A tree is at $(-7, -2)$ and a rock is at $(-7, 4)$. How many steps is it from the tree straight to the rock?', '[]', '6', '4-(-2)', 'The x-coordinates are the same, so the walk is straight up. The tree is 2 units below the x-axis and the rock is 4 units above it, so the walk is 2 + 4 = 6 steps.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x = -7; |4 - (-2)| = 6 steps.","run_id":"claude-code","at":"2026-10-24T03:16:02.977Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('075dbe1f-4aeb-4e07-9bbd-9e48a43989ee', 'NC17.6.NS.8', 2, 'choice', 'Signs of coordinates in each quadrant', 'A point is in Quadrant II. Which statement about its coordinates is true?', '["Its x-coordinate is positive and its y-coordinate is negative","Its x-coordinate is positive and its y-coordinate is positive","Both of its coordinates are negative","Its x-coordinate is negative and its y-coordinate is positive"]', 'Its x-coordinate is negative and its y-coordinate is positive', NULL, 'Quadrant II is to the left of the y-axis and above the x-axis, so x is negative and y is positive.', 'checked', '{"lint":[],"solve":{"answer":"Its x-coordinate is negative and its y-coordinate is positive","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrant II is left of the y-axis (x < 0) and above the x-axis (y > 0).","run_id":"claude-code","at":"2026-10-24T03:16:02.977Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e79075f-ecef-41ae-b30e-2bca0a3bdbca', 'NC17.6.NS.8', 2, 'choice', 'Move along the grid', 'A robot starts at $(-2, 3)$. It moves 5 units right and then 7 units down. Where does it stop?', '["$(-7, -4)$","$(3, 10)$","$(3, -4)$","$(-7, 10)$"]', '$(3, -4)$', NULL, 'Moving 5 right adds 5 to x: $-2 + 5 = 3$. Moving 7 down subtracts 7 from y: $3 - 7 = -4$. The robot stops at $(3, -4)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, -4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: -2 + 5 = 3; y: 3 - 7 = -4. Stops at (3, -4).","run_id":"claude-code","at":"2026-10-24T03:16:02.977Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f83abec-eb40-406f-bf56-d4663c5040ea', 'NC17.6.NS.8', 3, 'numeric', 'Distance between points on one line', 'The points $(6, -4)$ and $(6, k)$ are 10 units apart, and $k$ is positive. What is $k$?', '[]', '6', '-4+10', 'The points are on the same vertical line. Going up 10 units from $-4$ gives $-4 + 10 = 6$. (Going down would give $-14$, which is not positive.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x = 6; |k - (-4)| = 10 gives k = 6 or k = -14; positive, so k = 6.","run_id":"claude-code","at":"2026-10-24T03:16:02.977Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('273d957b-5bbd-49b0-8d55-08695e98d158', 'NC17.6.NS.8', 3, 'choice', 'Find a point from a distance on the coordinate plane', 'Two points are on the same horizontal line and are 13 units apart. One point is at $(-8, 3)$. The other point is in Quadrant I. What are its coordinates?', '["$(21, 3)$","$(5, 3)$","$(-21, 3)$","$(3, 5)$"]', '$(5, 3)$', NULL, 'The other point has y-coordinate 3 and an x-coordinate 13 units from $-8$, so it is $(5, 3)$ or $(-21, 3)$. Only $(5, 3)$ is in Quadrant I, because $-8 + 13 = 5$ is positive.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same y=3; x = -8 +/- 13 = 5 or -21. Quadrant I needs x>0: (5,3).","run_id":"claude-code","at":"2026-10-24T08:46:20.286Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad6665a-7ff6-4756-b0d6-17f7cda286ec', 'NC17.6.NS.9', 1, 'choice', 'Subtraction as adding the opposite', 'Which expression has the same value as $5 - 3$?', '["$5 + (-3)$","$5 + 3$","$-5 + 3$","$-5 + (-3)$"]', '$5 + (-3)$', NULL, 'Subtracting a number is the same as adding its opposite. The opposite of 3 is $-3$, so $5 - 3 = 5 + (-3)$.', 'checked', '{"lint":[],"solve":{"answer":"$5 + (-3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 3 = 5 + (-3) = 2. Others: 8, -8, -2.","run_id":"claude-code","at":"2026-10-24T03:14:57.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21befe91-2aaf-4ea4-870f-cd91a60a53fe', 'NC17.6.NS.9', 1, 'choice', 'Zero pairs and counter models', 'A model has 5 negative counters and 2 positive counters. What is the greatest number of zero pairs that can be made?', '["3","5","2","7"]', '2', '2', 'Each zero pair needs one positive and one negative counter. There are only 2 positive counters, so at most 2 zero pairs can be made.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each zero pair needs one positive; only 2 positives, so 2 pairs.","run_id":"claude-code","at":"2026-10-24T03:14:57.447Z"}}', 'ai', NULL, NULL)
