INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b048b92-e7b9-4f62-9a5c-bc6cb3ca5ee2', 'NC17.6.NS.9', 1, 'numeric', 'Subtraction as adding the opposite', 'Subtracting 9 is the same as adding its opposite. Fill in the ?: $4 - 9 = 4 + ?$', '[]', '-9', '-9', 'The opposite of 9 is $-9$, so $4 - 9 = 4 + (-9)$. The ? is $-9$.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 - 9 = 4 + (-9); the ? is -9.","run_id":"claude-code","at":"2026-10-24T03:14:57.447Z"}}', 'ai', NULL, NULL)
