INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56d0b759-1d32-4ede-9378-d82dfd65d738', 'NC17.6.NS.9', 2, 'choice', 'Zero pairs and counter models', 'Dee models $2 - 5$ with counters. She starts with 2 positive counters, adds 3 zero pairs, and takes away 5 positive counters. Which counters are left?', '["3 positive counters","5 negative counters","2 positive counters","3 negative counters"]', '3 negative counters', NULL, 'After adding 3 zero pairs she has 5 positive and 3 negative counters. Taking away 5 positive counters leaves 3 negative counters, which is $-3$. So $2 - 5 = -3$.', 'checked', '{"lint":[],"solve":{"answer":"3 negative counters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 positives + 3 zero pairs = 5 positives and 3 negatives; remove 5 positives leaves 3 negatives (value -3 = 2 - 5).","run_id":"claude-code","at":"2026-10-24T03:14:57.447Z"}}', 'ai', NULL, NULL)
