INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3324204a-9851-4f4e-8819-eaae5060d9f0', 'NC17.6.NS.9', 2, 'choice', 'Subtract integers', 'Which of these has the greatest value?', '["$4 - 9$","$-2 - 6$","$5 + (-1)$","$-3 + 10$"]', '$-3 + 10$', NULL, '$-3 + 10 = 7$, $4 - 9 = -5$, $-2 - 6 = -8$ and $5 + (-1) = 4$. The greatest is 7, from $-3 + 10$.', 'checked', '{"lint":[],"solve":{"answer":"$-3 + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values: 4, 7, -5, -8. Greatest is 7.","run_id":"claude-code","at":"2026-10-24T03:14:57.447Z"}}', 'ai', NULL, NULL)
