VALUES ('4996b596-a700-4dea-875b-d81758aab0d6', 'NC17.6.NS.9', 2, 'numeric', 'Integers in context', 'At dawn the temperature was $-7$ degrees. By noon it had risen 15 degrees. What was the temperature at noon, in degrees?', '[]', '8', '-7+15', 'A rise means add. $-7 + 15 = 8$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-7 + 15 = 8.","run_id":"claude-code","at":"2026-10-24T03:14:57.447Z"}}', 'ai', NULL, NULL)
