INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01613983-c2d7-443c-95fd-753f262c6e69', 'NC17.6.NS.9', 3, 'choice', 'Subtraction as adding the opposite', 'Which statement about $-5 - (-8)$ and $-5 + 8$ is true?', '["$-5 - (-8)$ equals $3$, and $-5 + 8$ equals $3$.","$-5 - (-8)$ equals $-13$, and $-5 + 8$ equals $3$.","$-5 - (-8)$ equals $-3$, and $-5 + 8$ equals $3$.","$-5 - (-8)$ equals $13$, and $-5 + 8$ equals $3$."]', '$-5 - (-8)$ equals $3$, and $-5 + 8$ equals $3$.', NULL, 'Subtracting $-8$ is the same as adding 8, so $-5 - (-8) = -5 + 8 = 3$. Both expressions equal 3.', 'checked', '{"lint":[],"solve":{"answer":"$-5 - (-8)$ equals $3$, and $-5 + 8$ equals $3$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5 - (-8) = -5 + 8 = 3; -5 + 8 = 3.","run_id":"claude-code","at":"2026-10-24T03:14:57.447Z"}}', 'ai', NULL, NULL)
