INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41483687-ef18-427f-b177-03556b381160', 'NC17.6.EE.1', 1, 'numeric', 'Finding an unknown exponent', 'Sara writes 8 as a power of 2, like $2^{n}$, where $n$ is a whole number. What is the value of $n$?', '[]', '3', NULL, '$2 \times 2 = 4$ and $4 \times 2 = 8$, so 2 is used as a factor 3 times. So $8 = 2^3$ and $n = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8, so n = 3.","run_id":"claude-code","at":"2026-10-24T03:17:18.765Z"}}', 'ai', NULL, NULL)
