INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66375322-6d40-46e2-b1c7-ee044c3e70a5', 'NC17.6.EE.1', 2, 'choice', 'Exponents in a context', 'A colony of bacteria starts as 1 cell on a plate and triples every hour. The number of cells after 4 hours is $3^4$. How many cells are there after 4 hours?', '["12","64","243","81"]', '81', '3^4', '$3^4 = 3 \times 3 \times 3 \times 3 = 81$. The number 12 is $3 \times 4$ and 64 is $4^3$.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^4 = 81.","run_id":"claude-code","at":"2026-10-24T03:17:18.765Z"}}', 'ai', NULL, NULL)
