INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08af0b78-2363-479d-a71b-27d290c623ba', 'NC17.6.EE.1', 2, 'choice', 'Writing an expression with an exponent from words', 'Which expression means "the sum of 4 and 3, squared"?', '["$4 + 3^2$","$(4 + 3)^2$","$4^2 + 3^2$","$(4 + 3) \\times 2$"]', '$(4 + 3)^2$', NULL, 'The sum is found first and then squared, so the sum goes in parentheses with the exponent 2 outside: $(4 + 3)^2$.', 'checked', '{"lint":[],"solve":{"answer":"$(4 + 3)^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of 4 and 3 = (4+3), then squared: (4+3)^2.","run_id":"claude-code","at":"2026-10-24T03:17:18.765Z"}}', 'ai', NULL, NULL)
