VALUES ('16791d50-1ea8-4b8d-9ee7-04a2a20178aa', 'NC17.6.EE.1', 2, 'numeric', 'Order of operations with exponents', 'Find the value of $10^3 \div 5^2$.', '[]', '40', '10^3/5^2', 'Evaluate both powers: $10^3 = 1000$ and $5^2 = 25$. Then divide: $1000 \div 25 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1000 / 25 = 40.","run_id":"claude-code","at":"2026-10-24T03:17:18.765Z"}}', 'ai', NULL, NULL)
