VALUES ('0e53cff1-30fa-4d16-bb1f-08514c08ea2f', 'NC17.6.EE.1', 3, 'numeric', 'Order of operations with exponents', 'What is the value of $(2 + 3)^2 - 2^2 \times 3$?', '[]', '13', '(2+3)^2-2^2*3', 'Parentheses first: $(2 + 3)^2 = 25$. Then $2^2 \times 3 = 4 \times 3 = 12$. Subtract: $25 - 12 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5)^2 = 25; 2^2 x 3 = 12; 25 - 12 = 13.","run_id":"claude-code","at":"2026-10-24T03:17:18.765Z"}}', 'ai', NULL, NULL)
