INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0da097f3-12fe-4254-b547-48990df545a3', 'NC17.6.EE.1', 3, 'choice', 'Exponents in a context', 'The number of viewers of a video doubles every day. On day 0 there are 5 viewers, so after 3 days there are $5 \times 2^3$ viewers. How many viewers are there after 3 days?', '["40","30","45","1000"]', '40', '5*2^3', 'Do the power first: $2^3 = 8$. Then $5 \times 8 = 40$. Multiplying 5 by 2 first would wrongly give $10^3 = 1000$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8; 5 x 8 = 40.","run_id":"claude-code","at":"2026-10-24T03:17:18.765Z"}}', 'ai', NULL, NULL)
