INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d72f5b9-2091-4f41-9f15-c2c2d1a1a6a0', 'NC17.6.EE.2', 3, 'numeric', 'Substitute into a formula', 'The area of a triangle is $A = \frac{1}{2}bh$. Find $A$ when $b = 12$ and $h = 7$.', '[]', '42', '1/2*12*7', '$A = \frac{1}{2} \times 12 \times 7 = 6 \times 7 = 42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)(12)(7) = 42.","run_id":"claude-code","at":"2026-10-24T08:22:16.958Z"}}', 'ai', NULL, NULL)
