INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19478835-50be-4899-b032-9a691798c72a', 'NC17.6.EE.2', 3, 'numeric', 'Evaluate with an exponent', 'Evaluate $x^2 + 3y$ when $x = 5$ and $y = 4$.', '[]', '37', '5^2+3*4', '$x^2 = 5 \times 5 = 25$ and $3y = 3 \times 4 = 12$. Then $25 + 12 = 37$.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^2 + 3(4) = 25 + 12 = 37.","run_id":"claude-code","at":"2026-10-24T08:22:16.958Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ee4db89-3191-496a-b17a-021b92c950ff', 'NC17.6.EE.3', 1, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $5(y + 2)$?', '["$5y + 2$","$5y + 10$","$y + 10$","$7y$"]', '$5y + 10$', NULL, 'Multiply both terms in the parentheses by 5: $5 \cdot y + 5 \cdot 2 = 5y + 10$. Multiplying only the first term gives $5y + 2$, which is a common mistake.', 'checked', '{"lint":[],"solve":{"answer":"$5y + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(y + 2) = 5y + 10.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('002762fb-51bb-4248-bed6-d2384afb9402', 'NC17.6.EE.3', 1, 'numeric', 'Combine like terms', '$3x + 4x = ?x$. What number is the ?', '[]', '7', '3+4', 'Both terms have x, so add the numbers in front: $3 + 4 = 7$. So $3x + 4x = 7x$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 4x = 7x.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
