INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c718929-461b-4868-9fc0-2ab84fd205eb', 'NC17.6.EE.3', 1, 'choice', 'Name the property of operations', 'Which property lets you write $2(5 + x)$ as $2 \cdot 5 + 2 \cdot x$?', '["Commutative property of multiplication","Distributive property","Associative property of multiplication","Identity property of multiplication"]', 'Distributive property', NULL, 'Multiplying a sum by a number by multiplying each part of the sum is the distributive property.', 'checked', '{"lint":[],"solve":{"answer":"Distributive property","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying each addend: distributive property.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
