INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cf96de4-6230-44c3-9e3d-a87f495d7ce8', 'NC17.6.EE.3', 2, 'choice', 'Decide whether expressions are equivalent', 'Which expression is NOT equivalent to $4x + 8$?', '["$4(x + 2)$","$2(2x + 4)$","$x + x + x + x + 8$","$4(x + 8)$"]', '$4(x + 8)$', NULL, '$4(x + 2) = 4x + 8$, $2(2x + 4) = 4x + 8$ and $x + x + x + x + 8 = 4x + 8$. But $4(x + 8) = 4x + 32$.', 'checked', '{"lint":[],"solve":{"answer":"$4(x + 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 8) = 4x + 32, not 4x + 8. 2(2x+4)=4x+8, 4(x+2)=4x+8, x+x+x+x+8=4x+8.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31cc35ca-9ffe-491d-aa89-446748c78c7e', 'NC17.6.EE.3', 2, 'choice', 'Name the property of operations', 'Which property shows that $(3 + x) + 7 = 3 + (x + 7)$?', '["Associative property of addition","Commutative property of addition","Distributive property","Identity property of addition"]', 'Associative property of addition', NULL, 'The numbers stay in the same order and only the grouping changes. That is the associative property of addition.', 'checked', '{"lint":[],"solve":{"answer":"Associative property of addition","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grouping changes, order stays: associative property of addition.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
