INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22dec2b8-4a8b-4335-be41-cba3309771bd', 'NC17.6.EE.3', 2, 'numeric', 'Write an equivalent expression for a story', 'Each of 5 friends buys a ticket that costs $t$ dollars and a snack that costs 3 dollars. The total cost is $5(t + 3)$ dollars. Written without parentheses, the total is $5t + ?$ dollars. What number is the ?', '[]', '15', '5*3', 'Multiply both terms by 5: $5(t + 3) = 5t + 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(t + 3) = 5t + 15.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
