INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19056b18-0ed3-4637-b903-9b0436626929', 'NC17.6.EE.3', 3, 'choice', 'Factor out a common factor', 'Which shows $20x + 30y$ with its greatest common factor taken out?', '["$5(4x + 6y)$","$10(2x + 3y)$","$2(10x + 15y)$","$10(2x + 30y)$"]', '$10(2x + 3y)$', NULL, 'The greatest common factor of 20 and 30 is 10. $20x \div 10 = 2x$ and $30y \div 10 = 3y$, so the answer is $10(2x + 3y)$. The forms with 5 or 2 taken out are equivalent but do not use the greatest factor.', 'checked', '{"lint":[],"solve":{"answer":"$10(2x + 3y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(20, 30) = 10: 10(2x + 3y). 5(4x+6y) and 2(10x+15y) are equivalent but not the GCF; 10(2x+30y) is wrong.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cb8531e-5940-40a4-9a8f-f4d0c20692b7', 'NC17.6.EE.3', 3, 'numeric', 'Combine like terms', '$3x + 2y + 5x - y = ax + by$. What is $a + b$?', '[]', '9', '(3+5)+(2-1)', 'Combine the x-terms: $3x + 5x = 8x$. Combine the y-terms: $2y - y = 1y$. So $a = 8$ and $b = 1$, and $a + b = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x + y; a = 8, b = 1; a + b = 9.","run_id":"claude-code","at":"2026-10-24T08:22:22.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('468466b5-4aab-422f-a16f-4ab36f67ecb4', 'NC17.6.EE.4', 1, 'numeric', 'Test equivalence by substituting values', 'Sam wants to test whether $3x$ and $x+x+x$ are equivalent. What is the value of $x+x+x$ when $x=4$?', '[]', '12', '4+4+4', 'Put 4 in for $x$: $4+4+4=12$. Also $3x = 3 \cdot 4 = 12$, so the two expressions agree for this value.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 4 + 4 = 12.","run_id":"claude-code","at":"2026-10-28T18:48:27.859Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30d8a1bd-af4f-4d8a-ac28-c37790a39152', 'NC17.6.EE.4', 1, 'choice', 'Spot expressions that are not equivalent', 'Which pair of expressions is equivalent?', '["$x+x$ and $2x$","$x+x$ and $x^2$","$3 \\cdot x$ and $x+3$","$5+x$ and $5x$"]', '$x+x$ and $2x$', NULL, 'Adding $x$ to itself gives 2 groups of $x$, so $x+x=2x$. Try $x=4$ in the others: $4+4=8$ but $4^2=16$; $3 \cdot 4=12$ but $4+3=7$; $5+4=9$ but $5 \cdot 4=20$.', 'checked', '{"lint":[],"solve":{"answer":"$x+x$ and $2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x = 2x for every x. x^2, 5x and x+3 differ (e.g. x=3: 6 vs 9; 8 vs 15; 9 vs 6).","run_id":"claude-code","at":"2026-10-28T18:48:28.080Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16fe8809-4ffe-43fe-af47-536a75229ad8', 'NC17.6.EE.4', 1, 'choice', 'Justify equivalence with a property', 'Which property shows that $4+n$ is equivalent to $n+4$?', '["associative property of addition","identity property of addition","distributive property of addition","commutative property of addition"]', 'commutative property of addition', NULL, 'Changing the order of the numbers being added does not change the sum. That is the commutative property of addition.', 'checked', '{"lint":[],"solve":{"answer":"commutative property of addition","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order swapped: commutative property of addition.","run_id":"claude-code","at":"2026-10-28T18:48:28.452Z"}}', 'ai', NULL, NULL)
