INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('322e4772-30e7-4e92-b5b2-a53d3a52f3d3', 'NC17.6.EE.4', 2, 'choice', 'Equivalent expressions using the distributive property', 'Which expression is equivalent to $5(2x-3)$?', '["$10x-3$","$7x-8$","$10x+15$","$10x-15$"]', '$10x-15$', NULL, 'The 5 multiplies both terms: $5 \cdot 2x = 10x$ and $5 \cdot 3 = 15$. Keeping the subtraction gives $10x-15$.', 'checked', '{"lint":[],"solve":{"answer":"$10x-15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*2x - 5*3 = 10x - 15.","run_id":"claude-code","at":"2026-10-28T18:48:28.071Z"}}', 'ai', NULL, NULL)
