INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ae34d3a-4352-49f9-bf70-62adff0f3dd6', 'NC17.6.EE.4', 2, 'numeric', 'Test equivalence by substituting values', 'Dev checks that $3(x+1)$ and $3x+3$ are equivalent by using $x=7$. What value do both expressions have when $x=7$?', '[]', '24', '3*(7+1)', '$3(7+1)=3 \cdot 8=24$ and $3 \cdot 7+3=21+3=24$. Both are 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(7+1) = 24; 3(7)+3 = 24.","run_id":"claude-code","at":"2026-10-28T18:48:28.086Z"}}', 'ai', NULL, NULL)
