INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b8b8465-fe6c-4d2f-b167-8735d7861580', 'NC17.6.EE.4', 2, 'choice', 'Equivalent expressions in a context', 'Four friends each buy one ticket that costs $t$ dollars and one snack that costs 3 dollars. The total cost in dollars is $4(t+3)$. Which expression is equivalent?', '["$4t+3$","$12t+4$","$4t+12$","$4t+7$"]', '$4t+12$', NULL, 'Each of the 4 friends pays for a ticket and a snack: 4 tickets cost $4t$ and 4 snacks cost $4 \cdot 3=12$. The total is $4t+12$.', 'checked', '{"lint":[],"solve":{"answer":"$4t+12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(t+3) = 4t + 12.","run_id":"claude-code","at":"2026-10-28T18:48:28.261Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('043ee9ae-bf9c-4262-8ea1-4f0db96585ff', 'NC17.6.EE.4', 3, 'choice', 'Equivalent expressions in a context', 'Ana pays a fee of 6 dollars plus 3 dollars for each of $g$ games, a total of $6+3g$ dollars. Ben writes the same total as $3(g+2)$. Which statement is correct?', '["They are equivalent because $3(g+2)=3g+6$","They are not equivalent because $3(g+2)=3g+2$","They are not equivalent: $3(g+2)=g+6$","They are not equivalent because $3(g+2)=3g+5$"]', 'They are equivalent because $3(g+2)=3g+6$', NULL, '$3(g+2)=3g+3 \cdot 2=3g+6$, and $6+3g$ is the same as $3g+6$ by the commutative property. So the expressions are equivalent.', 'checked', '{"lint":[],"solve":{"answer":"They are equivalent because $3(g+2)=3g+6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(g+2)=3g+6=6+3g, so equivalent.","run_id":"claude-code","at":"2026-10-28T18:48:27.932Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('054c07aa-1e27-4e5d-b720-3013bd1516ac', 'NC17.6.EE.4', 3, 'numeric', 'Spot expressions that are not equivalent', 'How many of these four expressions are equivalent to $6x+12$? The expressions are $6(x+2)$, $2(3x+6)$, $6x+2$ and $3(2x+4)$.', '[]', '3', '3', '$6(x+2)=6x+12$, $2(3x+6)=6x+12$ and $3(2x+4)=6x+12$ are all equivalent. $6x+2$ is not. So 3 of them are equivalent.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(x+2)=6x+12, 2(3x+6)=6x+12, 3(2x+4)=6x+12; 6x+2 is not. 3.","run_id":"claude-code","at":"2026-10-28T18:48:28.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10d73769-657c-4ffe-81e6-b29a77b7cd6c', 'NC17.6.EE.5', 1, 'choice', 'Decide whether a given value is a solution', 'Is $x = 5$ a solution of the equation $x + 9 = 14$?', '["No, the left side becomes $13$","No, the left side becomes $4$","Yes, the left side becomes $14$","No, the left side becomes $45$"]', 'Yes, the left side becomes $14$', NULL, 'Put $5$ in place of $x$: $5 + 9 = 14$. The left side is $14$, which equals the right side, so $x = 5$ is a solution.', 'checked', '{"lint":[],"solve":{"answer":"Yes, the left side becomes $14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 9 = 14, equal to the right side, so yes.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6fcab6af-8fd9-4d83-92f5-1b422eead3e8', 'NC17.6.EE.5', 1, 'choice', 'Test values in an equation from a context', 'Tom had 6 marbles. A friend gave him some more, and now he has 11. If $m$ is the number of marbles his friend gave him, then $6 + m = 11$. Which value of $m$ makes this equation true?', '["$17$","$6$","$4$","$5$"]', '$5$', '11-6', 'Put each value in place of $m$. $6 + 5 = 11$ is true. $6 + 17 = 23$, $6 + 6 = 12$ and $6 + 4 = 10$ are not $11$. So $m = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + m = 11 gives m = 5; check 6+5=11.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c8812f9-13c6-4cb4-841b-090761808a2f', 'NC17.6.EE.5', 1, 'numeric', 'Test whole numbers in a one-step equation', 'Which of the numbers 9, 12, 15 and 18 makes the equation $q - 7 = 8$ true?', '[]', '15', '8+7', 'Try each number: $9 - 7 = 2$, $12 - 7 = 5$, $15 - 7 = 8$, $18 - 7 = 11$. Only $15$ gives $8$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-7=2, 12-7=5, 15-7=8, 18-7=11. Only 15.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ebc4220-924c-4ed8-83c8-ab45657da24a', 'NC17.6.EE.5', 2, 'numeric', 'Find all the values in a set that make an equation true', 'How many of the whole numbers 1, 2, 3, 4 and 5 make the equation $4m - 3 = 10$ true?', '[]', '0', '0', 'Try each number: $4 \times 1 - 3 = 1$, $4 \times 2 - 3 = 5$, $4 \times 3 - 3 = 9$, $4 \times 4 - 3 = 13$, $4 \times 5 - 3 = 17$. None gives $10$, so the answer is $0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4m-3: 1,5,9,13,17 for m=1..5. None equals 10 (would need m=3.25). Count is 0.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e634795-052e-4d8b-92f3-c5b57538b320', 'NC17.6.EE.5', 2, 'choice', 'Choose the equation that a given value makes true', 'Which equation is true when $z = 1.5$?', '["$2z = 1.5$","$z \\div 2 = 3$","$2z = 3$","$z + 2 = 3$"]', '$2z = 3$', NULL, 'Put $1.5$ in place of $z$. $2 \times 1.5 = 3$ is true. $2 \times 1.5 = 3$, not $1.5$; $1.5 \div 2 = 0.75$, not $3$; and $1.5 + 2 = 3.5$, not $3$.', 'checked', '{"lint":[],"solve":{"answer":"$2z = 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=1.5: 2z=3 true; z/2=0.75; 2z=3 not 1.5; z+2=3.5.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1687b629-4ba4-44f5-a3b7-15d01af9c405', 'NC17.6.EE.5', 2, 'numeric', 'Test values in an equation from a context', 'A taxi ride costs 3 dollars plus 2 dollars for each mile. For $m$ miles, a ride that costs 11 dollars fits the equation $2m + 3 = 11$. Which number from the set 2, 3, 4 and 5 makes this equation true?', '[]', '4', '(11-3)/2', 'Try each number of miles: $2 \times 2 + 3 = 7$, $2 \times 3 + 3 = 9$, $2 \times 4 + 3 = 11$, $2 \times 5 + 3 = 13$. Only $m = 4$ gives $11$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2m+3: 7, 9, 11, 13 for m=2..5. m=4 gives 11.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
