INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e7b92a3-1a6a-4650-b525-9da5135a2162', 'NC17.6.EE.5', 3, 'numeric', 'Test values in a two-step equation', 'Which number from the set 3, 6, 9, 12 and 15 makes the equation $2(x + 4) = 26$ true?', '[]', '9', '26/2-4', 'Add $4$ first, then double. $x = 3$: $2 \times 7 = 14$. $x = 6$: $2 \times 10 = 20$. $x = 9$: $2 \times 13 = 26$. $x = 12$: $2 \times 16 = 32$. $x = 15$: $2 \times 19 = 38$. Only $9$ works.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x+4)=26 so x+4=13, x=9. Check 2*13=26; others give 14, 20, 32, 38.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('185decd6-1d61-4caa-8d0d-9ddda3941baf', 'NC17.6.EE.5', 3, 'choice', 'Choose the equation that a given value makes true', 'Exactly three of these equations are true when $n = 6$. Which one is NOT true when $n = 6$?', '["$5n - 4 = 24$","$3n - 8 = 10$","$\\frac{n}{2} + 4 = 7$","$n^2 - 6 = 30$"]', '$5n - 4 = 24$', NULL, 'Put $6$ in place of $n$. $3 \times 6 - 8 = 10$ is true. $6 \div 2 + 4 = 7$ is true. $6^2 - 6 = 30$ is true. $5 \times 6 - 4 = 26$, not $24$, so that equation is the one that is not true.', 'checked', '{"lint":[],"solve":{"answer":"$5n - 4 = 24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n=6: 18-8=10 true; 36-6=30 true; 30-4=26 not 24; 3+4=7 true.","run_id":"claude-code","at":"2026-10-24T08:33:09.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('089fb343-549b-4eb8-a935-155f02c8ba59', 'NC17.6.EE.6', 1, 'choice', 'write an expression for a phrase', 'Which expression means "the product of 8 and a number $y$"?', '["$8y$","$8 + y$","$y - 8$","$8 \\div y$"]', '$8y$', NULL, '"Product" means multiply. The product of 8 and $y$ is $8y$.', 'checked', '{"lint":[],"solve":{"answer":"$8y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product of 8 and y = 8y.","run_id":"claude-code","at":"2026-10-28T18:48:28.102Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12fcd0b2-72b7-499d-920c-111f79ffc7c0', 'NC17.6.EE.6', 1, 'choice', 'write an expression for a story', 'Lena had $m$ dollars and spent 9 dollars. Which expression gives how many dollars she has left?', '["$9 - m$","$m + 9$","$m - 9$","$9m$"]', '$m - 9$', NULL, 'Spending takes away from what she had. Start with $m$ and subtract 9: $m - 9$. The order matters, so $9 - m$ is not the same.', 'checked', '{"lint":[],"solve":{"answer":"$m - 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She has m - 9 dollars left.","run_id":"claude-code","at":"2026-10-28T18:48:28.527Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('148aca85-af35-4715-92b7-f657717f2feb', 'NC17.6.EE.6', 1, 'choice', 'choose what a variable stands for', 'Maya is saving money. She does not yet know how many dollars she will have saved by June. Which is the best way to define a variable for this?', '["Let $d$ be the number of dollars Maya has saved","Let $d$ be the name of the person who is saving","Let $d$ be the fixed amount of 20 dollars Maya started with","Let $d$ be the month in which Maya stops saving"]', 'Let $d$ be the number of dollars Maya has saved', NULL, 'A variable stands for an amount that is unknown or can change. The number of dollars saved is that amount. A name, a month, or a fixed known amount is not.', 'checked', '{"lint":[],"solve":{"answer":"Let $d$ be the number of dollars Maya has saved","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The unknown quantity is the dollars saved, so d = number of dollars Maya has saved. Others are a known amount, a name, or a month.","run_id":"claude-code","at":"2026-10-28T18:48:28.560Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3418d064-1168-4ee0-bc86-359cc2a08164', 'NC17.6.EE.6', 2, 'numeric', 'use a variable to find an amount in a story (two operations)', 'Jada reads $p$ pages each day for 6 days. On the 7th day she reads 14 more pages. How many pages has she read in all if $p$ is 9?', '[]', '68', '6*9+14', 'For the first 6 days she reads $6p$ pages, then 14 more: $6p + 14$. With $p = 9$: $6 \times 9 + 14 = 54 + 14 = 68$ pages.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6p + 14 = 54 + 14 = 68.","run_id":"claude-code","at":"2026-10-28T18:48:27.981Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d2ab359-4c16-4dd4-8149-4267ec15fcac', 'NC17.6.EE.6', 2, 'numeric', 'use two variables to find an amount in a story', 'A store sells notebooks for 3 dollars each and pens for 2 dollars each. Mia buys $n$ notebooks and $p$ pens. How many dollars does she pay when $n$ is 4 and $p$ is 5?', '[]', '22', '3*4+2*5', 'The cost is $3n + 2p$ dollars. With $n = 4$ and $p = 5$: $3 \times 4 + 2 \times 5 = 12 + 10 = 22$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3n + 2p = 3(4) + 2(5) = 12 + 10 = 22.","run_id":"claude-code","at":"2026-10-28T18:48:28.114Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52061fe8-2757-4ce4-84b3-5e20e0aa635f', 'NC17.6.EE.6', 2, 'choice', 'say what a part of an expression means in the story', 'Carlos earns 9 dollars for each hour he works, plus a 10 dollar bonus. His pay for $h$ hours is $9h + 10$ dollars. What does $9h$ stand for?', '["the number of hours Carlos worked","the amount of the bonus in dollars","his pay for the hours worked, without the bonus","his total pay with the bonus included"]', 'his pay for the hours worked, without the bonus', NULL, 'Each hour pays 9 dollars, so $9h$ is the pay for $h$ hours. The bonus is the separate $+ 10$, and the sum is the total pay.', 'checked', '{"lint":[],"solve":{"answer":"his pay for the hours worked, without the bonus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9h is 9 dollars times hours: pay for hours worked, without bonus.","run_id":"claude-code","at":"2026-10-28T18:48:28.366Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17f3b16b-610a-4767-a767-ea4dee4df184', 'NC17.6.EE.6', 3, 'numeric', 'use a variable to find an amount in a story (two operations)', 'A tank holds 120 liters of water. Water drains out at $d$ liters per minute for 8 minutes. How many liters are left in the tank when $d$ is 9?', '[]', '48', '120-8*9', 'In 8 minutes, $8d$ liters drain out, so $120 - 8d$ liters are left. With $d = 9$: $120 - 8 \times 9 = 120 - 72 = 48$ liters.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 - 8d = 120 - 72 = 48.","run_id":"claude-code","at":"2026-10-28T18:48:27.991Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31797585-a5d0-4e5c-826f-96827e9ace40', 'NC17.6.EE.6', 3, 'choice', 'say what a part of an expression means in the story', 'Adult tickets cost $a$ dollars each and child tickets cost $c$ dollars each. What does the expression $2a + 3c$ stand for?', '["the cost of 3 adult tickets and 2 child tickets","the cost of 2 adult tickets and 3 child tickets","the cost of 5 tickets that all cost the same","the number of adult and child tickets bought"]', 'the cost of 2 adult tickets and 3 child tickets', NULL, '$2a$ is the cost of 2 adult tickets and $3c$ is the cost of 3 child tickets. Adding them gives the cost of both groups together.', 'checked', '{"lint":[],"solve":{"answer":"the cost of 2 adult tickets and 3 child tickets","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2a is the cost of 2 adult tickets, 3c of 3 child tickets; sum is total cost.","run_id":"claude-code","at":"2026-10-28T18:48:28.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
