INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37363b51-d341-481a-8e1e-1af164001525', 'NC17.6.EE.8', 1, 'choice', 'Test whether a value is a solution of an inequality', 'Which value of $x$ makes $x > 6$ true?', '["$x = 4$","$x = 6$","$x = 2$","$x = 9$"]', '$x = 9$', NULL, '9 is greater than 6, so it makes the inequality true. 4 and 2 are less than 6, and 6 is not greater than 6.', 'checked', '{"lint":[],"solve":{"answer":"$x = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 9 > 6; 2, 4 are less and 6 equals 6.","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
