INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f730fa7-b13c-44c1-8d61-8fea431f9c70', 'NC17.6.EE.8', 1, 'numeric', 'Write an inequality for a constraint', 'A store sells a toy for less than 12 dollars. The inequality $t < c$ shows the price $t$ in dollars. What number is $c$?', '[]', '12', '12', '"Less than 12 dollars" is written $t < 12$, so $c = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Price less than 12: t < 12, c = 12.","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
