INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21d6ed4b-e935-4269-a2e3-020934fc62b4', 'NC17.6.EE.8', 1, 'choice', 'Write an inequality for a constraint', 'Which sentence matches $x < 30$, where $x$ is the number of students on a bus?', '["The bus carries exactly 30 students.","The bus carries more than 30 students.","The bus carries fewer than 30 students.","The bus carries 30 fewer students than last week."]', 'The bus carries fewer than 30 students.', NULL, '$x < 30$ says the number of students is less than 30, which means fewer than 30.', 'checked', '{"lint":[],"solve":{"answer":"The bus carries fewer than 30 students.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x < 30 means fewer than 30 students.","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
