INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10492009-4ec5-4571-9ac9-135eade7a95a', 'NC17.6.EE.8', 2, 'choice', 'Test whether a value is a solution of an inequality', 'Which number is a solution of $x < -2$?', '["$-2$","$-1$","$-5$","$2$"]', '$-5$', NULL, 'On the number line, $-5$ is to the left of $-2$, so $-5 < -2$. The numbers $-2$, $-1$ and $2$ are not less than $-2$.', 'checked', '{"lint":[],"solve":{"answer":"$-5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5 < -2 true; -1, -2, 2 are not less than -2.","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
