INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10e9ddcf-4aac-46d0-a83e-d73e8610e7d9', 'NC17.6.EE.8', 2, 'numeric', 'Match an inequality with its number line graph', 'The graph of $x < c$ has an open circle at the point 4 units to the left of 3 on the number line, with shading to the left. What is $c$?', '[]', '-1', '3-4', 'Four units to the left of 3 is 3 - 4 = $-1$. So the graph shows $x < -1$ and $c = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 units left of 3 is 3 - 4 = -1. c = -1.","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
