INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e150862-f28f-4c3e-8e12-0666b787f65c', 'NC17.6.EE.8', 2, 'choice', 'Match an inequality with its number line graph', 'Which statement about the number line graph of $x > 4$ is true?', '["The circle at 4 is open, because 4 is not a solution.","The circle at 4 is closed, because 4 is a solution.","The circle at 4 is open, because the shading goes to the left.","The circle at 4 is closed, because the shading goes to the right."]', 'The circle at 4 is open, because 4 is not a solution.', NULL, '4 is not greater than 4, so it is not a solution and the circle is open. The shading goes right, toward larger numbers.', 'checked', '{"lint":[],"solve":{"answer":"The circle at 4 is open, because 4 is not a solution.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 is not a solution of x > 4, so the circle is open.","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
