INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09f28cda-4494-462b-b172-61d016c675d9', 'NC17.6.EE.8', 3, 'numeric', 'Test whether a value is a solution of an inequality', 'What is the greatest integer that is NOT a solution of $x > -4.5$?', '[]', '-5', '-5', 'The numbers greater than $-4.5$ include $-4$, $-3$, and so on. The integers that are not solutions are $-5$, $-6$, and so on, and the greatest of these is $-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-solutions: x <= -4.5; integers -5, -6, ... Greatest is -5 (-4 > -4.5 is a solution).","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
