INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0996a4a1-bc11-4b6b-b751-87542ebf9a7d', 'NC17.6.EE.8', 3, 'numeric', 'Write an inequality for a constraint', 'A bus holds 48 students. The principal says more than three-fourths of its seats must be filled. Let $s$ be the number of students, so $s > c$. What is $c$?', '[]', '36', '3/4*48', 'Three-fourths of 48 is 36. "More than three-fourths" gives $s > 36$, so $c = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 of 48 = 36; s > 36, c = 36.","run_id":"claude-code","at":"2026-10-24T08:29:13.748Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00bf8ca4-fd74-4ac9-979a-b80abfc7c9bc', 'NC17.6.EE.9', 1, 'numeric', 'Use an equation to find a value', 'A bakery sells muffins for 3 dollars each. The cost $c$, in dollars, of $n$ muffins is $c = 3n$. What is $c$ when $n = 7$?', '[]', '21', '3*7', 'Replace $n$ with 7: $c = 3 \times 7 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c = 3*7 = 21.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e98fc5c-4198-4ddc-b945-29465391145c', 'NC17.6.EE.9', 1, 'choice', 'Use a table of values', 'A table shows $x$: 1, 2, 3, 4 and $y$: 6, 7, 8, 9. Which equation matches the table?', '["$y = x + 5$","$y = 5x$","$y = x + 6$","$y = 6x$"]', '$y = x + 5$', NULL, 'Each $y$ is 5 more than $x$ (1 + 5 = 6, 2 + 5 = 7, and so on), so $y = x + 5$.', 'checked', '{"lint":[],"solve":{"answer":"$y = x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y - x = 5 for every pair: 6-1, 7-2, 8-3, 9-4. y = x + 5.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e5cf9d5-7947-416d-b299-27c2d6345205', 'NC17.6.EE.9', 1, 'choice', 'Use a graph or points on a graph', 'The points $(1, 2)$, $(2, 4)$, $(3, 6)$ and $(4, 8)$ are on a graph. Which equation matches these points?', '["$y = x + 2$","$y = \\frac{x}{2}$","$y = 2x$","$y = 8x$"]', '$y = 2x$', NULL, 'In every point, $y$ is 2 times $x$. So the equation is $y = 2x$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each y is twice x: y = 2x.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ea613b7-01e5-45f1-8cf0-bd2eb7ddbe27', 'NC17.6.EE.9', 2, 'numeric', 'Use a table of values', 'A table shows $x$: 2, 4, 6, 8 and $y$: 5, 10, 15, 20. What is $y$ when $x$ is 10?', '[]', '25', '2.5*10', 'Each $y$ is 2.5 times $x$ (5 is 2.5 times 2). So when $x = 10$, $y = 2.5 \times 10 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 2.5x; x = 10 gives 25.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('273be460-ecdc-4a1b-b776-0779dcb3a6b1', 'NC17.6.EE.9', 2, 'choice', 'Describe how the two quantities change together', 'Every time $x$ goes up by 1, $y$ goes up by 3. Also, $y = 0$ when $x = 0$. Which equation matches?', '["$y = 3x$","$y = x + 3$","$y = \\frac{x}{3}$","$y = 3x + 3$"]', '$y = 3x$', NULL, 'Because $y$ starts at 0 and grows by 3 for each 1 in $x$, $y$ is 3 times $x$: $y = 3x$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 3 through origin: y = 3x.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('675ffc84-85ca-44b9-8cc9-253ebe669bd2', 'NC17.6.EE.9', 2, 'choice', 'Describe how the two quantities change together', 'In the equation $s = 4p$, $s$ is the number of pizza slices and $p$ is the number of pizzas. When $p$ goes up by 1, what happens to $s$?', '["$s$ goes up by 1","$s$ is multiplied by 4","$s$ goes up by 4","$s$ goes down by 4"]', '$s$ goes up by 4', NULL, 'Each extra pizza adds 4 slices, so $s$ goes up by 4. It does not get multiplied by 4.', 'checked', '{"lint":[],"solve":{"answer":"$s$ goes up by 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s = 4(p+1) = 4p + 4: s goes up by 4.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01a283e7-ad54-4dc7-9af7-f3475cbc343e', 'NC17.6.EE.9', 3, 'choice', 'Use a graph or points on a graph', 'A straight line on a graph passes through $(1, 7)$, $(2, 11)$ and $(3, 15)$. Which equation matches the line?', '["$y = 3x + 4$","$y = 7x$","$y = 4x + 3$","$y = 4x$"]', '$y = 4x + 3$', NULL, '$y$ goes up by 4 each time $x$ goes up by 1, so the equation starts $y = 4x$. At $x = 1$ that gives 4, and 7 is 3 more, so $y = 4x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (11-7)/1 = 4; 7 = 4 + b, b = 3. y = 4x + 3; check 4*3+3 = 15.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('074c89b2-ac78-43e1-ad13-e1ac7848b339', 'NC17.6.EE.9', 3, 'choice', 'Identify the independent and dependent variables', 'Priya wants an equation that gives the number of pages she has read, $p$, from the number of minutes she has been reading, $m$. Which statement is correct?', '["The pages $p$ are independent, and the minutes $m$ depend on them","The minutes $m$ are independent, and the pages $p$ depend on them","Both are independent, because both can be measured","Both are dependent, because both change as she reads"]', 'The minutes $m$ are independent, and the pages $p$ depend on them', NULL, 'The equation gives $p$ from $m$, and the number of pages read depends on the time spent. So $m$ is independent and $p$ is dependent.', 'checked', '{"lint":[],"solve":{"answer":"The minutes $m$ are independent, and the pages $p$ depend on them","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pages read depend on minutes; minutes are independent.","run_id":"claude-code","at":"2026-10-24T08:31:33.563Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ce5860d-eadf-4605-a999-5648c88162a0', 'NC17.6.G.1', 1, 'numeric', 'Area of a triangle', 'A triangle has a base of 10 centimeters and a height of 6 centimeters. What is its area in square centimeters?', '[]', '30', '1/2*10*6', 'Area of a triangle = $\frac{1}{2} \times \text{base} \times \text{height} = \frac{1}{2} \times 10 \times 6 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 10 x 6 = 30.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d5026a5-44b1-4781-9d79-188d50ea96d9', 'NC17.6.G.1', 1, 'choice', 'Compose and decompose triangles and rectangles', 'A rectangle is 6 units long and 8 units wide. It is cut along a diagonal into two identical triangles. What is the area of each triangle in square units?', '["24","48","14","12"]', '24', '6*8/2', 'The rectangle has area 6 × 8 = 48 square units. Two identical triangles share it equally, so each has 48 ÷ 2 = 24 square units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 6 x 8 = 48; half is 24.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('000e0882-7a8d-4b97-9864-55ca24d081c7', 'NC17.6.G.1', 1, 'numeric', 'Area of a polygon made of parts', 'An L-shaped figure is made of two rectangles that do not overlap. One is 6 units by 4 units and the other is 3 units by 2 units. What is the area of the figure in square units?', '[]', '30', '6*4+3*2', 'Add the areas of the two rectangles: 6 × 4 = 24 and 3 × 2 = 6. Then 24 + 6 = 30 square units.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 = 24, 3 x 2 = 6, total 30.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07292c13-5507-46f2-a5bc-0f94f5e71935', 'NC17.6.G.1', 2, 'numeric', 'Area of a polygon with a piece removed', 'A rectangle is 10 units long and 8 units wide. A rectangle 4 units by 3 units is cut out of one corner. What is the area of the remaining shape in square units?', '[]', '68', '10*8-4*3', 'Whole rectangle: 10 × 8 = 80. Piece cut out: 4 × 3 = 12. Remaining: 80 − 12 = 68 square units.', 'checked', '{"lint":[],"solve":{"answer":"68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 8 = 80; minus 4 x 3 = 12; 68.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2853a4d7-3dcd-4e3c-a474-bf2a2a977459', 'NC17.6.G.1', 2, 'numeric', 'Area of a triangle', 'A triangular wall has a base of 4 meters and a height of 3 meters. One can of paint covers 3 square meters. How many cans are needed to cover the wall once?', '[]', '2', '(4*3/2)/3', 'Area of the wall = $\frac{1}{2} \times 4 \times 3 = 6$ square meters. Each can covers 3 square meters, so 6 ÷ 3 = 2 cans.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 1/2 x 4 x 3 = 6; 6 / 3 = 2 cans.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5659837b-2fa3-4450-8feb-7cbce7a3fd89', 'NC17.6.G.1', 2, 'choice', 'Area of a polygon made of parts', 'A rectangle is 6 units wide and 5 units tall. A right triangle with legs of 6 units and 8 units is attached along the rectangle’s bottom edge, so the 6-unit leg lies along that edge. Which expression gives the area of the whole shape?', '["$6 \\times 5 + 6 \\times 8$","$\\frac{1}{2} \\times (6 \\times 5 + 6 \\times 8)$","$6 \\times 5 + \\frac{1}{2} \\times 6 \\times 8$","$6 \\times 5 + \\frac{1}{2} \\times 5 \\times 8$"]', '$6 \times 5 + \frac{1}{2} \times 6 \times 8$', NULL, 'Rectangle: 6 × 5. Triangle: half of base times height, with base 6 and height 8, so $\frac{1}{2} \times 6 \times 8$. Add the two areas.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 5 + \\frac{1}{2} \\times 6 \\times 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 6 x 5; triangle 1/2 x 6 x 8; total 6 x 5 + 1/2 x 6 x 8.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68dc048b-b458-4e3d-9909-4a9a9b92faf1', 'NC17.6.G.1', 3, 'numeric', 'Area of a trapezoid', 'A diagonal cuts a trapezoid into two triangles. One triangle has a base of 7 centimeters (the shorter parallel side) and the other has a base of 13 centimeters (the longer parallel side). Both triangles have the same height. The trapezoid has an area of 80 square centimeters. What is the height in centimeters?', '[]', '8', '80*2/(7+13)', 'The areas add: $\frac{1}{2} \times 7 \times h + \frac{1}{2} \times 13 \times h = \frac{1}{2} \times 20 \times h = 10h$. So 10h = 80 and h = 8 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 7 x h + 1/2 x 13 x h = 10h = 80, h = 8.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d76cf5e-333e-418e-a3cb-2290450a8c64', 'NC17.6.G.1', 3, 'numeric', 'Area of a triangle', 'A triangle has a base of 2.5 meters and a height of 3.2 meters. What is its area in square meters?', '[]', '4', '2.5*3.2/2', 'Area = $\frac{1}{2} \times 2.5 \times 3.2 = \frac{8}{2} = 4$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 2.5 x 3.2 = 4.","run_id":"claude-code","at":"2026-10-24T08:35:45.800Z"}}', 'ai', NULL, NULL)
