INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14f0258e-316a-4665-8503-241d380ca22e', 'NC17.6.G.2', 1, 'choice', 'Volume of a prism from its fractional edges', 'A small box is $\frac{1}{2}$ inch long, $\frac{1}{3}$ inch wide and $\frac{1}{5}$ inch high. What is its volume?', '["$\\frac{1}{15}$ cubic inch","$\\frac{1}{10}$ cubic inch","$\\frac{1}{30}$ cubic inch","$\\frac{31}{30}$ cubic inch"]', '$\frac{1}{30}$ cubic inch', NULL, 'Multiply the three edges: $\frac{1}{2} \times \frac{1}{3} \times \frac{1}{5} = \frac{1}{30}$ cubic inch.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{30}$ cubic inch","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2*1/3*1/5=1/30.","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
