INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d57810f-8588-4e57-b3b8-1d20848c77c7', 'NC17.6.G.2', 1, 'numeric', 'Volume of a prism from its fractional edges', 'A gift box is $\frac{1}{2}$ foot long, $\frac{1}{2}$ foot wide and 3 feet tall. What is its volume in cubic feet?', '[]', '3/4', '1/2*1/2*3', 'Multiply the edges: $\frac{1}{2} \times \frac{1}{2} \times 3 = \frac{3}{4}$ cubic foot.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2*1/2*3=3/4.","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
