INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('552dd287-46cc-4f45-8f67-14cddbddf9f7', 'NC17.6.G.2', 1, 'choice', 'Fill a prism with unit cubes of fractional edge', 'Jada fills a prism that is 1 unit long, 1 unit wide and $\frac{1}{2}$ unit high with cubes whose edges are $\frac{1}{2}$ unit. How many cubes does she use?', '["2 cubes","8 cubes","16 cubes","4 cubes"]', '4 cubes', NULL, 'Along the length there are 2 cubes, along the width 2 cubes and along the height 1 cube: $2 \times 2 \times 1 = 4$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"4 cubes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*2*1=4 cubes (or (1/2)/(1/8)=4).","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e320778-8e17-40a0-bc1c-91096f1fcf75', 'NC17.6.G.2', 2, 'numeric', 'Find a missing edge from the volume', 'A rectangular prism has a volume of $\frac{3}{4}$ cubic foot. It is $\frac{3}{2}$ feet long and $\frac{1}{4}$ foot wide. How many feet high is it?', '[]', '2', '(3/4)/(3/2*1/4)', 'The base area is $\frac{3}{2} \times \frac{1}{4} = \frac{3}{8}$ square foot. Height = volume $\div$ base area $= \frac{3}{4} \div \frac{3}{8} = 2$ feet.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/2*1/4=3/8; (3/4)/(3/8)=2.","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('382b0d02-456a-4133-9a04-7e5a6d68a4e8', 'NC17.6.G.2', 2, 'choice', 'Find a missing edge from the volume', 'A rectangular prism has a volume of 6 cubic units. Its length is 4 units and its width is $\frac{3}{2}$ units. Which expression gives its height?', '["$6 \\times 4 \\times \\frac{3}{2}$","$6 - 4 - \\frac{3}{2}$","$6 \\div \\left( 4 \\times \\frac{3}{2} \\right)$","$\\left( 4 \\times \\frac{3}{2} \\right) \\div 6$"]', '$6 \div \left( 4 \times \frac{3}{2} \right)$', NULL, 'Volume = length $\times$ width $\times$ height, so height = volume $\div$ (length $\times$ width) $= 6 \div \left( 4 \times \frac{3}{2} \right) = 1$ unit.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\div \\left( 4 \\times \\frac{3}{2} \\right)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = V/(l*w) = 6/(4*3/2)=1.","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23948d14-f493-4e4d-b29b-dc1ba41a6499', 'NC17.6.G.2', 2, 'choice', 'Fill a prism with unit cubes of fractional edge', 'A box is 3 inches long, 2 inches wide and 1 inch tall. How many cubes with edges of $\frac{1}{2}$ inch does it take to fill it?', '["6 cubes","12 cubes","48 cubes","24 cubes"]', '48 cubes', NULL, 'Each inch holds 2 cubes along an edge, so the box takes $6 \times 4 \times 2 = 48$ cubes. (Each small cube has volume $\frac{1}{8}$ cubic inch, and $6 \div \frac{1}{8} = 48$.)', 'checked', '{"lint":[],"solve":{"answer":"48 cubes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*4*2=48 half-inch cubes.","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035e9782-b57f-48d4-97f9-5087f6a091a7', 'NC17.6.G.2', 3, 'numeric', 'Volume of a prism from its fractional edges', 'A rectangular prism is $2\frac{1}{2}$ feet long, $1\frac{1}{2}$ feet wide and $\frac{2}{3}$ foot high. What is its volume in cubic feet?', '[]', '5/2', '5/2*3/2*2/3', 'Write the mixed numbers as fractions: $\frac{5}{2} \times \frac{3}{2} \times \frac{2}{3} = \frac{30}{12} = \frac{5}{2}$, or $2\frac{1}{2}$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"5/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/2*3/2=15/4; 15/4*2/3=5/2.","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
