INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04c277ab-7cb3-4d1b-bcc1-45200a91d774', 'NC17.6.G.2', 3, 'numeric', 'Find a missing edge from the volume', 'A rectangular prism has a volume of $7\frac{1}{2}$ cubic centimeters. Its length is $2\frac{1}{2}$ cm and its width is $1\frac{1}{2}$ cm. How many centimeters high is it?', '[]', '2', '(15/2)/(5/2*3/2)', 'The base area is $\frac{5}{2} \times \frac{3}{2} = \frac{15}{4}$ square cm. Height = $\frac{15}{2} \div \frac{15}{4} = 2$ cm.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 5/2*3/2=15/4; (15/2)/(15/4)=2.","run_id":"claude-code","at":"2026-10-24T08:37:47.515Z"}}', 'ai', NULL, NULL)
