INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35a24acc-3e5f-49f2-8a06-bd8bdc8066f8', 'NC17.6.G.3', 1, 'choice', 'Recognize horizontal and vertical segments', 'Which pair of points can be joined to make a horizontal segment?', '["$(2, 6)$ and $(2, 9)$","$(2, 6)$ and $(9, 6)$","$(2, 6)$ and $(9, 9)$","$(6, 2)$ and $(6, 9)$"]', '$(2, 6)$ and $(9, 6)$', NULL, 'A horizontal segment is flat, so both points have the same y-coordinate. Only $(2, 6)$ and $(9, 6)$ both have y-coordinate 6.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 6)$ and $(9, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal segment: same y-coordinate. (2,6) and (9,6).","run_id":"claude-code","at":"2026-10-28T18:48:27.831Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17934a25-9f86-4753-9379-24bda4ce63b3', 'NC17.6.G.3', 1, 'numeric', 'Perimeter from the vertices', 'A rectangle has vertices $(0, 0)$, $(6, 0)$, $(6, 3)$ and $(0, 3)$. What is its perimeter in units?', '[]', '18', '2*(6+3)', 'The bottom side runs from x = 0 to x = 6, so it is 6 units long. The left side runs from y = 0 to y = 3, so it is 3 units long. Perimeter = 6 + 3 + 6 + 3 = 18 units.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 6 and 3; perimeter 2(6+3) = 18.","run_id":"claude-code","at":"2026-10-28T18:48:28.029Z"}}', 'ai', NULL, NULL)
