INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4183aeaf-8e4b-45ac-86bb-9220019809bd', 'NC17.6.G.3', 1, 'numeric', 'Length of a side that shares a coordinate', 'A square has vertices $(1, 2)$, $(9, 2)$, $(9, 10)$ and $(1, 10)$. How many units long is one side?', '[]', '8', '9-1', 'The bottom side runs from $(1, 2)$ to $(9, 2)$ at the same height, so its length is 9 - 1 = 8 units. All sides of a square are equal.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,2) to (9,2): |9-1| = 8.","run_id":"claude-code","at":"2026-10-28T18:48:28.133Z"}}', 'ai', NULL, NULL)
