INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28864db3-361c-4b6e-933f-31f4894fb93a', 'NC17.6.G.3', 2, 'numeric', 'Area of a rectangle from the vertices', 'A rectangle has vertices $(2, 1)$, $(2, 9)$, $(7, 9)$ and $(7, 1)$. What is its area in square units?', '[]', '40', '(9-1)*(7-2)', 'The left side is 9 - 1 = 8 units long and the top side is 7 - 2 = 5 units long. Area = 8 x 5 = 40 square units.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 7-2 = 5, height 9-1 = 8; area 40.","run_id":"claude-code","at":"2026-10-28T18:48:28.071Z"}}', 'ai', NULL, NULL)
