INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b3574d2-54d3-4127-8eb5-896cd28f4071', 'NC17.6.G.3', 2, 'numeric', 'Perimeter from the vertices', 'A rectangle has vertices $(-3, -2)$, $(4, -2)$, $(4, 3)$ and $(-3, 3)$. What is its perimeter in units?', '[]', '24', '2*((3+4)+(2+3))', 'The bottom side runs from x = -3 to x = 4, so it is 3 + 4 = 7 units long. The right side runs from y = -2 to y = 3, so it is 2 + 3 = 5 units long. Perimeter = 2 x (7 + 5) = 24 units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 4 - (-3) = 7, height 3 - (-2) = 5. Perimeter 2(7+5) = 24.","run_id":"claude-code","at":"2026-10-28T18:48:28.332Z"}}', 'ai', NULL, NULL)
