INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0853e9cb-212b-4308-91b2-a5767f27cbed', 'NC17.6.G.3', 2, 'choice', 'Find a missing vertex', 'Three vertices of a rectangle are $(-5, 2)$, $(1, 2)$ and $(1, -4)$. What is the fourth vertex?', '["$(-5, 4)$","$(5, -4)$","$(-5, -4)$","$(-4, -5)$"]', '$(-5, -4)$', NULL, 'The fourth vertex is directly below $(-5, 2)$ and level with $(1, -4)$. So its x-coordinate is -5 and its y-coordinate is -4.', 'checked', '{"lint":[],"solve":{"answer":"$(-5, -4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-5,2) and (1,2) share y=2; (1,2) and (1,-4) share x=1. Fourth: (-5,-4).","run_id":"claude-code","at":"2026-10-28T18:48:28.538Z"}}', 'ai', NULL, NULL)
