INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cdbf148-3679-4ab4-b048-fb4c03753982', 'NC17.6.G.3', 3, 'numeric', 'Perimeter from the vertices', 'A square has one side from $(-1, 4)$ to $(-1, -5)$. What is the perimeter of the square in units?', '[]', '36', '4*(4+5)', 'The side is vertical and crosses the x-axis, so its length is 4 + 5 = 9 units. A square has four equal sides: 4 x 9 = 36 units.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side length |4 - (-5)| = 9. Perimeter 4 x 9 = 36.","run_id":"claude-code","at":"2026-10-28T18:48:28.087Z"}}', 'ai', NULL, NULL)
