INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17ddbc9b-9ddb-4216-b6b0-992b92120dff', 'NC17.6.G.3', 3, 'choice', 'Side length across the axes', 'Mara says the segment from $(-8, 3)$ to $(5, 3)$ is 3 units long because 8 - 5 = 3. What is her mistake?', '["The segment is vertical, so she should use the y-coordinates","The points are on opposite sides of the y-axis, so she should add 8 and 5","She should add 8 and 5 and then double the result","She should subtract 5 - 8 and write the result as -3"]', 'The points are on opposite sides of the y-axis, so she should add 8 and 5', NULL, 'Both y-coordinates are 3, so the segment is horizontal and the x-coordinates are used. -8 and 5 are on opposite sides of the y-axis, so the length is 8 + 5 = 13 units.', 'checked', '{"lint":[],"solve":{"answer":"The points are on opposite sides of the y-axis, so she should add 8 and 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal segment from x=-8 to x=5: length 8 + 5 = 13, since the points are on opposite sides of the y-axis.","run_id":"claude-code","at":"2026-10-28T18:48:28.339Z"}}', 'ai', NULL, NULL)
