INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('370fef69-5fc4-418f-af4a-5518196ebe49', 'NC17.6.G.4', 1, 'choice', 'Name a solid from the faces of its net', 'A net is made of 2 triangles and 3 rectangles. Which solid does it fold into?', '["a triangular pyramid","a triangular prism","a rectangular prism","a square pyramid"]', 'a triangular prism', NULL, 'A prism has two matching bases joined by rectangles. Two triangle bases and 3 rectangles make a triangular prism.', 'checked', '{"lint":[],"solve":{"answer":"a triangular prism","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 triangular ends + 3 rectangular sides = triangular prism.","run_id":"claude-code","at":"2026-10-24T08:38:28.546Z"}}', 'ai', NULL, NULL)
