INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('394cb9f6-2c85-4355-985c-345c05988443', 'NC17.6.G.4', 1, 'numeric', 'Surface area of a rectangular prism or cube', 'A rectangular prism is 5 cm long, 3 cm wide and 2 cm tall. What is its surface area, in square centimeters?', '[]', '62', '2*(5*3+5*2+3*2)', 'The faces come in three matching pairs: $5 \times 3 = 15$, $5 \times 2 = 10$ and $3 \times 2 = 6$. Adding all six: $2 \times (15 + 10 + 6) = 62$.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5*3 + 5*2 + 3*2) = 2(15+10+6) = 62.","run_id":"claude-code","at":"2026-10-24T08:38:28.546Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1123f79d-4d28-4b20-8de0-c61e2e935b92', 'NC17.6.G.4', 1, 'choice', 'Name a solid from the faces of its net', 'A net is made of 1 square and 4 triangles. Which solid does it fold into?', '["a square pyramid","a cube","a triangular prism","a triangular pyramid"]', 'a square pyramid', NULL, 'The square is the base and the 4 triangles are the sides that meet at the top point. This is a square pyramid.', 'checked', '{"lint":[],"solve":{"answer":"a square pyramid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square base + 4 triangles = square pyramid.","run_id":"claude-code","at":"2026-10-24T08:38:28.546Z"}}', 'ai', NULL, NULL)
