INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ae8cee2-6eba-4e8c-9c77-8f7b354a7e0d', 'NC17.6.SP.1', 3, 'choice', 'Turn a question into a statistical question', 'Which question changes "How many points did the team score in Friday''s game?" into a statistical question?', '["How many points did the team score in the first half on Friday?","How many points did the other team score on Friday?","How many players on the team scored on Friday?","How many points did the team score in each game this season?"]', 'How many points did the team score in each game this season?', NULL, 'A statistical question is one where you expect the answers to vary, so you need to collect data from many people, things or times. Over a whole season the scores will differ from game to game. The other questions are still about the single Friday game and have one answer.', 'checked', '{"lint":[],"solve":{"answer":"How many points did the team score in each game this season?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each game this season gives many varying scores.","run_id":"claude-code","at":"2026-10-24T08:38:57.073Z"}}', 'ai', NULL, NULL)
