INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0daf2f1b-025c-477a-8ae4-6256873defe7', 'NC17.6.SP.2', 1, 'numeric', 'Find the mean as the center', 'Four friends have 36 stickers altogether. If the stickers were shared out evenly, each friend would get the mean number. What is the mean?', '[]', '9', '36/4', 'The mean is the total shared evenly: 36 / 4 = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36/4 = 9.","run_id":"claude-code","at":"2026-10-24T08:40:09.166Z"}}', 'ai', NULL, NULL)
