INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26c86dea-eb6e-4d0c-bac2-3aca31547cda', 'NC17.6.SP.2', 1, 'choice', 'Describe the shape of a distribution', 'Students counted their pets: 1 pet: 2 students, 2 pets: 5 students, 3 pets: 8 students, 4 pets: 5 students, 5 pets: 2 students. Which best describes the shape of this distribution?', '["Skewed right, with the peak at 1 pet","Skewed left, with the peak at 5 pets","Two peaks, at 1 pet and 5 pets","Symmetric, with the peak at 3 pets"]', 'Symmetric, with the peak at 3 pets', NULL, 'The counts rise to 8 at 3 pets and fall back the same way (2, 5, 8, 5, 2), so the shape is symmetric with one peak at 3 pets.', 'checked', '{"lint":[],"solve":{"answer":"Symmetric, with the peak at 3 pets","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 2, 5, 8, 5, 2 are symmetric about 3 pets, the peak.","run_id":"claude-code","at":"2026-10-24T08:40:09.166Z"}}', 'ai', NULL, NULL)
