INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a2bf8b9-8718-4397-8c7a-d2a3268d5138', 'NC17.6.SP.2', 2, 'choice', 'Find the median as the center', 'Which data set has a median of 6?', '["$2, 4, 5, 8, 11$","$6, 2, 3, 4, 20$","$1, 4, 6, 8, 20$","$3, 4, 8, 9, 10$"]', '$1, 4, 6, 8, 20$', NULL, 'In order, the middle value of 1, 4, 6, 8, 20 is 6. The second set has mean 6 but median 5. The third set in order is 2, 3, 4, 6, 20, so its median is 4. The last set has median 8.', 'checked', '{"lint":[],"solve":{"answer":"$1, 4, 6, 8, 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted medians: 2,3,4,6,20 -> 4; 2,4,5,8,11 -> 5; 3,4,8,9,10 -> 8; 1,4,6,8,20 -> 6.","run_id":"claude-code","at":"2026-10-24T08:40:09.166Z"}}', 'ai', NULL, NULL)
