INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06e48243-0f16-4cf3-add6-f13b7f9a6663', 'NC17.6.SP.2', 2, 'choice', 'Describe the shape of a distribution', 'On a quiz out of 10, the 20 students scored: 10 points: 8 students, 9 points: 6 students, 8 points: 3 students, 7 points: 2 students, 6 points: 1 student. Which best describes the shape?', '["Skewed left, with the peak at 10 points","Skewed right, with the peak at 10 points","Symmetric, with the peak at 8 points","Two peaks, at 10 points and 6 points"]', 'Skewed left, with the peak at 10 points', NULL, 'The most common score is 10, and the counts trail off toward the low scores on the left, so the shape is skewed left.', 'checked', '{"lint":[],"solve":{"answer":"Skewed left, with the peak at 10 points","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 8, 6, 3, 2, 1 for 10..6 (total 20): peak at 10, tail toward low scores -> skewed left.","run_id":"claude-code","at":"2026-10-24T08:40:09.166Z"}}', 'ai', NULL, NULL)
