INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe7568a-14f4-4fd3-a1d0-a1d45ff43d37', 'NC17.6.SP.2', 2, 'choice', 'Compare the spread of two distributions', 'Team A scored 20, 22, 21, 19 and 23 points in five games. Team B scored 5, 40, 22, 38 and 10 points. Which statement is true?', '["Team A''s scores are more spread out; its range is 4, compared with 35","Team A''s scores are more spread out, because its mean is lower","Team B''s scores are more spread out; its range is 35, compared with 4","The spreads are equal, because each team played five games"]', 'Team B''s scores are more spread out; its range is 35, compared with 4', NULL, 'Team A''s range is 23 - 19 = 4. Team B''s range is 40 - 5 = 35. A larger range means more spread, so Team B is more spread out.', 'checked', '{"lint":[],"solve":{"answer":"Team B''s scores are more spread out; its range is 35, compared with 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: range 23-19 = 4. B: range 40-5 = 35. B more spread out.","run_id":"claude-code","at":"2026-10-24T08:40:09.166Z"}}', 'ai', NULL, NULL)
