INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ac2a4e7-13bf-4170-8935-7a0cb758b882', 'NC17.6.SP.2', 3, 'numeric', 'See the effect of an unusual value', 'The values 10, 12, 14 and 16 have a mean of 13. A fifth value, 60, is added. What is the mean of all five values?', '[]', '22.4', '(10+12+14+16+60)/5', 'The total is 10 + 12 + 14 + 16 + 60 = 112. Divide by 5: 112 / 5 = 22.4.', 'checked', '{"lint":[],"solve":{"answer":"22.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10+12+14+16 = 52; 52+60 = 112; 112/5 = 22.4.","run_id":"claude-code","at":"2026-10-24T08:40:09.166Z"}}', 'ai', NULL, NULL)
