INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11f8c47a-ed04-4d2d-9347-8a71cd67d0fd', 'NC17.6.SP.2', 3, 'choice', 'Tell center, spread and shape apart', 'Which statement describes the spread of a distribution, and not its center or its shape?', '["The scores range from 62 to 98","Half of the scores are above 80","The scores pile up on the high side with a tail to the left","A typical score is about 82"]', 'The scores range from 62 to 98', NULL, 'Saying how far the scores run from lowest to highest describes spread. Half above 80 and a typical score of 82 describe the center. A pile-up with a tail describes the shape.', 'checked', '{"lint":[],"solve":{"answer":"The scores range from 62 to 98","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A range of values (62 to 98) describes spread; typical score and half above 80 describe center; piling up with a tail describes shape.","run_id":"claude-code","at":"2026-10-24T08:40:09.166Z"}}', 'ai', NULL, NULL)
