VALUES ('5bb46038-ce19-4a39-a11f-e27cbccd5ce8', 'NC17.6.SP.3', 1, 'numeric', 'Find the mean', 'Ben scored 12, 16, 9 and 15 points in four games. What is the mean number of points he scored per game?', '[]', '13', '(12+16+9+15)/4', 'Add: $12 + 16 + 9 + 15 = 52$. Divide by 4 games: $52 \div 4 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 12+16+9+15 = 52; 52/4 = 13.","run_id":"claude-code","at":"2026-10-24T08:42:31.746Z"}}', 'ai', NULL, NULL)
