INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45652c24-e524-4422-9a61-43162d971b85', 'NC17.6.SP.3', 1, 'choice', 'Describe a data set with its center and spread', 'Class A''s test scores have a mean of 80 and a range of 5. Class B''s test scores have a mean of 80 and a range of 30. Which statement is true?', '["Class A''s scores are more spread out than Class B''s","Class B did better on average than Class A","Class A did better on average than Class B","Class B''s scores are more spread out than Class A''s"]', 'Class B''s scores are more spread out than Class A''s', NULL, 'The means are equal, so the classes did equally well on average. The range tells the spread, and Class B''s range of 30 is larger than Class A''s range of 5, so its scores are more spread out.', 'checked', '{"lint":[],"solve":{"answer":"Class B''s scores are more spread out than Class A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal means, so neither did better on average. Class B''s range (30) is larger, so its scores are more spread out.","run_id":"claude-code","at":"2026-10-24T08:42:31.746Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3732bd7c-d7db-4ac2-a895-e4abadf81530', 'NC17.6.SP.3', 2, 'numeric', 'Find the mean absolute deviation', 'The data set 6, 8, 12, 14 has a mean of 10. The mean absolute deviation is the mean of the distances of the values from the mean. What is the mean absolute deviation of this data set?', '[]', '3', '(4+2+2+4)/4', 'The distances from 10 are 4, 2, 2 and 4. Their mean is $\frac{4 + 2 + 2 + 4}{4} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 10: 4, 2, 2, 4. Sum 12; 12/4 = 3.","run_id":"claude-code","at":"2026-10-24T08:42:31.746Z"}}', 'ai', NULL, NULL)
