INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c0dfb40-d6bb-48d1-9f59-d6d758bf66ee', 'NC17.6.SP.3', 2, 'choice', 'Describe a data set with its center and spread', 'Two bus routes were timed on five days. Route A took 10, 11, 10, 12 and 12 minutes. Route B took 5, 8, 12, 14 and 16 minutes. Both routes have a mean of 11 minutes. Which statement is correct?', '["Route B is more predictable because its range is larger","Route A is more predictable because its range is smaller","Route A is more predictable because its mean is smaller","Both routes are equally predictable because the means are equal"]', 'Route A is more predictable because its range is smaller', NULL, 'Route A''s range is $12 - 10 = 2$ minutes and Route B''s range is $16 - 5 = 11$ minutes. The times for Route A vary less, so it is more predictable. The means are equal, so they do not separate the routes.', 'checked', '{"lint":[],"solve":{"answer":"Route A is more predictable because its range is smaller","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Route A range 12 - 10 = 2; Route B range 16 - 5 = 11. Smaller spread means more predictable: Route A. Means are equal, so the mean-based option is false.","run_id":"claude-code","at":"2026-10-24T08:42:31.746Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
