INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a88d359-bcdc-4e44-a8f6-37c46bd74e73', 'NC17.6.SP.3', 3, 'numeric', 'Use the mean to find a missing value', 'Maya wants a mean of 90 on her 5 tests. Her first four scores are 88, 92, 85 and 91. What score does she need on the fifth test?', '[]', '94', '5*90-88-92-85-91', 'Five tests with a mean of 90 need a total of $5 \cdot 90 = 450$. Her first four scores add to $88 + 92 + 85 + 91 = 356$. She needs $450 - 356 = 94$.', 'checked', '{"lint":[],"solve":{"answer":"94","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Needed total 5 x 90 = 450. 88+92+85+91 = 356. 450 - 356 = 94.","run_id":"claude-code","at":"2026-10-24T08:42:31.746Z"}}', 'ai', NULL, NULL)
