INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2326ccb9-c6ec-42a7-928c-1edf30b8401c', 'NC17.6.SP.3', 3, 'numeric', 'Use the mean to find a missing value', 'Four numbers are 5, 9, 12 and $x$, and their mean is 10. What is the median of the four numbers?', '[]', '10.5', '(9+12)/2', 'The total must be $4 \cdot 10 = 40$, so $x = 40 - 26 = 14$. In order the numbers are 5, 9, 12, 14. The median is the mean of the middle two: $\frac{9 + 12}{2} = 10.5$.', 'checked', '{"lint":[],"solve":{"answer":"10.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 40; x = 40 - 26 = 14. Ordered 5, 9, 12, 14; median (9+12)/2 = 10.5.","run_id":"claude-code","at":"2026-10-24T08:42:31.746Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
