INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('453b4a28-9036-4123-adce-cf1ed6b25f32', 'NC17.6.SP.4', 2, 'choice', 'Comparing box plots', 'Two box plots show test scores. Class A: minimum 40, lower quartile 55, median 70, upper quartile 85, maximum 100. Class B: minimum 50, lower quartile 60, median 70, upper quartile 80, maximum 90. Which statement is true?', '["Class B has the higher median score of the two classes.","Class A''s middle half is more spread out than Class B''s.","Class B has the larger range of scores of the two classes.","Class A has the lower maximum score of the two classes."]', 'Class A''s middle half is more spread out than Class B''s.', NULL, 'The medians are equal. The interquartile range is $85 - 55 = 30$ for Class A and $80 - 60 = 20$ for Class B, so the middle half of Class A is more spread out. Class A also has the larger range and the higher maximum.', 'checked', '{"lint":[],"solve":{"answer":"Class A''s middle half is more spread out than Class B''s.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR A = 30, B = 20, so A middle half more spread. A max 100 > 90; B range 40 < 60; medians equal 70.","run_id":"claude-code","at":"2026-10-24T08:42:06.062Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
