INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bea1d67-aa52-4f21-b9f5-7fb12046f2a1', 'NC17.6.SP.4', 3, 'choice', 'Choosing and comparing displays', 'A set of 12 values is shown in a histogram with intervals 0-9, 10-19 and 20-29. What can you NOT find from the histogram?', '["How many values are in each interval","Which interval has the most values","Which interval holds the largest value","The exact value of each data point"]', 'The exact value of each data point', NULL, 'A histogram shows how many values fall in each interval, so the counts, the tallest bar and the interval holding the largest value can all be found. The exact values inside an interval are not shown.', 'checked', '{"lint":[],"solve":{"answer":"The exact value of each data point","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A histogram groups values; exact values are lost.","run_id":"claude-code","at":"2026-10-24T08:42:06.062Z"}}', 'ai', NULL, NULL)
