INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d8accbf-7523-443f-ba52-7d4f1cf605ff', 'NC17.7.RP.2', 2, 'numeric', 'Interpret the constant and points in context', 'The graph of the cost $y$, in dollars, of $x$ pounds of flour is a straight line through the origin and the point $(8, 6)$. What is the cost of 1 pound of flour, in dollars?', '[]', '0.75', '6/8', 'The cost of 1 pound is the constant $6 \div 8 = 0.75$ dollar.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line through origin: k = 6/8 = 0.75 dollars per pound.","run_id":"claude-code","at":"2026-10-28T19:04:15.567Z"}}', 'ai', NULL, NULL)
