INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06c76963-7805-4ac4-baaa-0902c613a152', 'NC17.7.RP.2', 3, 'choice', 'Write an equation y = kx', 'A proportional relationship has $y = 18$ when $x = 24$. Which equation represents it?', '["$y = \\frac{4}{3}x$","$y = \\frac{3}{4}x$","$y = x - 6$","$y = 24x$"]', '$y = \frac{3}{4}x$', NULL, '$k = \frac{y}{x} = \frac{18}{24} = \frac{3}{4}$, so $y = \frac{3}{4}x$. The fraction $\frac{4}{3}$ is $\frac{x}{y}$, which is upside down.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{3}{4}x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 18/24 = 3/4, y = (3/4)x.","run_id":"claude-code","at":"2026-10-24T02:59:10.464Z"}}', 'ai', NULL, NULL)
