INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca25457-2411-4bad-94e5-a3fcfdeca764', 'NC17.7.RP.2', 3, 'choice', 'Use a proportional equation to find a value', 'The equation $y = 4.5x$ is proportional. Which value of $x$ makes $y$ equal to 36?', '["162","0.125","31.5","8"]', '8', '36/4.5', 'Solve $36 = 4.5x$: $x = 36 \div 4.5 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 / 4.5 = 8. Check 4.5 x 8 = 36.","run_id":"claude-code","at":"2026-10-28T19:04:15.586Z"}}', 'ai', NULL, NULL)
