INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16be71e8-0a01-4eae-bb94-b62e7844c006', 'NC17.7.RP.3', 1, 'choice', 'Percent of a quantity (tax, tip, discount, markup, commission)', 'A bike costs 150 dollars. This week it is 10 percent off. How many dollars is the discount?', '["135","15","1.5","160"]', '15', '150*10/100', '10 percent of 150 is 15 dollars. The sale price would be 135 dollars, but the question asks for the discount.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10% of 150 = 15.","run_id":"claude-code","at":"2026-10-28T19:12:24.845Z"}}', 'ai', NULL, NULL)
