INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c0b894d-85a9-4ae7-968f-f1a052169dcb', 'NC17.7.RP.3', 1, 'choice', 'Find the whole from a percent', 'A team won 12 games, which is 75 percent of the games it played. How many games did it play?', '["9","16","15","90"]', '16', '12*100/75', '75 percent is $\frac{3}{4}$. If 3 parts are 12 games, each part is 4, so all 4 parts are 16 games.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 0.75 = 16.","run_id":"claude-code","at":"2026-10-28T19:12:24.911Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1850729a-9e3e-46ed-8e11-10b3175fea1e', 'NC17.7.RP.3', 1, 'choice', 'Unit rates, including fractions', '5 apples cost 4 dollars. Let x be the cost, in dollars, of 15 apples at the same price. Which proportion is correct?', '["$\\frac{5}{4} = \\frac{x}{15}$","$\\frac{5}{4} = \\frac{15}{x}$","$\\frac{5}{x} = \\frac{15}{4}$","$\\frac{4}{5} = \\frac{15}{x}$"]', '$\frac{5}{4} = \frac{15}{x}$', NULL, 'Both sides must compare apples to dollars in the same order: 5 apples to 4 dollars equals 15 apples to x dollars.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{4} = \\frac{15}{x}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"apples/dollars: 5/4 = 15/x gives x = 12. Others give 18.75 or 4/3.","run_id":"claude-code","at":"2026-10-28T19:12:24.914Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e4b0568-c483-4584-92e0-e8efce569976', 'NC17.7.RP.3', 2, 'numeric', 'Find the whole from a percent', 'Maria paid 27 dollars for a sweater after a 25 percent discount. What was the price before the discount, in dollars?', '[]', '36', '27/0.75', 'After a 25 percent discount she pays 75 percent of the price. So 75 percent of the price is 27, and the price is $27 \div 0.75 = 36$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27 = 0.75 x P, P = 36.","run_id":"claude-code","at":"2026-10-24T02:57:08.355Z"}}', 'ai', NULL, NULL)
