INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14bdda72-3a8b-4d3f-bb6e-0e2889981309', 'NC17.7.RP.3', 2, 'choice', 'Percent of a quantity (tax, tip, discount, markup, commission)', 'A store buys a coat for 50 dollars and sells it for 40 percent more. What is the selling price, in dollars?', '["70","20","90","55"]', '70', '50*1.4', '40 percent of 50 is 20, so the selling price is 50 + 20 = 70 dollars.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40% of 50 = 20; 50 + 20 = 70.","run_id":"claude-code","at":"2026-10-28T19:12:24.942Z"}}', 'ai', NULL, NULL)
