INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d7fe74e-6727-4e74-aadd-c67b480ab163', 'NC17.7.RP.3', 2, 'choice', 'Percent error', 'A cup is measured to hold 260 milliliters. It truly holds 250 milliliters. What is the percent error?', '["4","10","3.8","96"]', '4', '10/250*100', 'The error is 10 milliliters. 10 divided by the true amount 250 = 0.04, which is 4 percent.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|260-250|/250 = 10/250 = 4%.","run_id":"claude-code","at":"2026-10-28T19:12:42.266Z"}}', 'ai', NULL, NULL)
