INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0eb4c604-7eab-44eb-a51d-212ae9edbb0d', 'NC17.7.RP.3', 3, 'choice', 'Percent increase and decrease', 'A ticket cost 40 dollars and then rose to 50 dollars. Later it fell from 50 dollars back to 40 dollars. Which statement is true?', '["The increase and the decrease were both 20 percent","The increase was 25 percent and the decrease was 20 percent","The increase and the decrease were both 25 percent","The increase was 20 percent and the decrease was 25 percent"]', 'The increase was 25 percent and the decrease was 20 percent', NULL, 'Increase: $10 \div 40 = 0.25$, which is 25 percent. Decrease: $10 \div 50 = 0.20$, which is 20 percent. Each change is measured against the price before it.', 'checked', '{"lint":[],"solve":{"answer":"The increase was 25 percent and the decrease was 20 percent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 10/40 = 25%; decrease 10/50 = 20%.","run_id":"claude-code","at":"2026-10-24T02:57:08.355Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02a10834-cd64-461d-849d-02744cb4b3de', 'NC17.7.RP.3', 3, 'choice', 'Find the whole from a percent', 'A town''s population fell by 8 percent and is now 4,600. What was the population before the fall?', '["4,968","4,232","5,152","5,000"]', '5,000', '4600/0.92', 'The new population is 92 percent of the old one. 4,600 divided by 0.92 = 5,000.', 'checked', '{"lint":[],"solve":{"answer":"5,000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.92 x P = 4600, P = 5000.","run_id":"claude-code","at":"2026-10-28T19:12:42.279Z"}}', 'ai', NULL, NULL)
