INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03e0976f-bf6f-4ec0-bbbc-10ef13127203', 'NC17.7.NS.1', 2, 'choice', 'properties of operations', 'Which equation is an example of the associative property of addition?', '["$-2 + 5 = 5 + (-2)$","$-2 + 2 = 0$","$(-2 + 5) + 7 = -2 + (5 + 7)$","$(-2 - 5) - 7 = -2 - (5 - 7)$"]', '$(-2 + 5) + 7 = -2 + (5 + 7)$', NULL, 'The associative property regroups addition without changing the order. Subtraction is not associative, and the other two equations show the commutative and inverse properties.', 'checked', '{"lint":[],"solve":{"answer":"$(-2 + 5) + 7 = -2 + (5 + 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative: regrouping sums, (-2+5)+7 = -2+(5+7). The subtraction one is false (-14 vs 0).","run_id":"claude-code","at":"2026-10-28T19:16:32.246Z"}}', 'ai', NULL, NULL)
