INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0212b0d6-f0b6-47bc-9f64-37ceea03180f', 'NC17.7.NS.2', 2, 'choice', 'Multiply fractions and mixed numbers', 'What is $\frac{5}{8} \times \left(-\frac{4}{15}\right)$?', '["$\\frac{1}{6}$","$-\\frac{1}{6}$","$-\\frac{75}{32}$","$-\\frac{9}{23}$"]', '$-\frac{1}{6}$', NULL, '$-\frac{20}{120} = -\frac{1}{6}$. The factors have different signs, so the product is negative.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 x -4/15 = -20/120 = -1/6.","run_id":"claude-code","at":"2026-10-28T19:24:07.730Z"}}', 'ai', NULL, NULL)
