INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('008d890e-22ee-4f68-817e-a0f0fe83ed5d', 'NC17.7.NS.2', 3, 'choice', 'Fraction to a repeating decimal by long division', 'Which fraction is equal to a repeating decimal?', '["$\\frac{3}{8}$","$\\frac{7}{20}$","$\\frac{4}{11}$","$\\frac{9}{25}$"]', '$\frac{4}{11}$', NULL, 'Dividing 4 by 11 gives $0.363636\ldots$, which repeats. The others end: $\frac{3}{8} = 0.375$, $\frac{7}{20} = 0.35$ and $\frac{9}{25} = 0.36$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{11}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8=0.375, 9/25=0.36, 7/20=0.35 terminate (denominators 2s and 5s); 4/11=0.3636... repeats.","run_id":"claude-code","at":"2026-10-24T03:04:03.077Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('025c12b7-2c36-479f-9313-70d3417c385c', 'NC17.7.NS.2', 3, 'numeric', 'Multiply or divide rational numbers in context', 'A drone''s height changes by a total of $-\frac{15}{4}$ meters in $\frac{5}{8}$ minute at a steady rate. What is the change in its height per minute, in meters?', '[]', '-6', '(-15/4)/(5/8)', '$-\frac{15}{4} \div \frac{5}{8} = -\frac{15}{4} \times \frac{8}{5} = -6$ meters per minute.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-15/4 / 5/8 = -15/4 x 8/5 = -6.","run_id":"claude-code","at":"2026-10-28T19:24:07.844Z"}}', 'ai', NULL, NULL)
