INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0de3eb4c-b863-419d-adf2-7d05a6b2103f', 'NC17.7.NS.3', 1, 'choice', 'Find an equal expression or true statement', 'Which expression is equal to $-9 + 4$?', '["$9 - 4$","$4 - 9$","$-9 - 4$","$9 + 4$"]', '$4 - 9$', NULL, '$-9 + 4 = -5$ and $4 - 9 = -5$. The others equal 5, $-13$ and 13.', 'checked', '{"lint":[],"solve":{"answer":"$4 - 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9 + 4 = -5 = 4 - 9.","run_id":"claude-code","at":"2026-10-28T19:32:34.377Z"}}', 'ai', NULL, NULL)
