INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1088d577-403a-4071-881d-81bf51d69ba4', 'NC17.7.NS.3', 2, 'choice', 'Find a missing number in an equation', 'What number makes this true? $-12.6 + ? = 5.4$', '["$-18$","$18$","$7.2$","$-7.2$"]', '$18$', '5.4+12.6', 'Add 12.6 to both sides: $? = 5.4 + 12.6 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"$18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? = 5.4 + 12.6 = 18.","run_id":"claude-code","at":"2026-10-28T19:34:46.277Z"}}', 'ai', NULL, NULL)
