INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12c7c189-089c-4c72-8028-644ef33c8304', 'NC17.7.NS.3', 2, 'numeric', 'Add and subtract rational numbers', 'Find $-\frac{5}{6} + \frac{3}{4}$.', '[]', '-1/12', NULL, 'Use a common denominator of 12: $-\frac{10}{12} + \frac{9}{12} = -\frac{1}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"-1/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-10/12 + 9/12 = -1/12.","run_id":"claude-code","at":"2026-10-28T19:34:46.322Z"}}', 'ai', NULL, NULL)
