INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a693d20-fa7c-41e9-b026-cd3d175e6f86', 'NC17.7.NS.3', 2, 'choice', 'Use the order of operations with rational numbers', 'Evaluate $-4 + 6 \div (-3)$.', '["$-2$","$-6$","$-\\frac{2}{3}$","$2$"]', '$-6$', '-4-2', 'Divide first: $6 \div (-3) = -2$. Then $-4 + (-2) = -6$.', 'checked', '{"lint":[],"solve":{"answer":"$-6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/(-3)=-2; -4-2=-6.","run_id":"claude-code","at":"2026-10-28T19:34:46.402Z"}}', 'ai', NULL, NULL)
