INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('092134f8-4c93-4de0-bea0-c2aaea4ba2ad', 'NC17.7.NS.3', 3, 'choice', 'Solve a problem with decimals and money', 'Sofia''s account balance is $-42.50$ dollars. She deposits $120$ dollars and then pays three bills of $18.75$ dollars each. What is her balance now, in dollars?', '["106.25","58.75","-21.25","21.25"]', '21.25', '-42.5+120-3*18.75', 'The three bills total 3 x 18.75 = 56.25. Then -42.50 + 120 = 77.50, and 77.50 - 56.25 = 21.25 dollars.', 'checked', '{"lint":[],"solve":{"answer":"21.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-42.50 + 120 = 77.50; 3 x 18.75 = 56.25; 77.50 - 56.25 = 21.25.","run_id":"claude-code","at":"2026-10-24T03:05:34.658Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08bf20d1-9d43-46bb-9df0-2323cd4c06b7', 'NC17.7.NS.3', 3, 'numeric', 'Find the mean of rational numbers', 'In four tests, Jon''s scores compared with the class average were $+5$, $-8$, $+3.5$ and $-1.5$ points. What was his mean difference from the average, in points?', '[]', '-0.25', '(5-8+3.5-1.5)/4', 'Add the differences: 5 - 8 + 3.5 - 1.5 = -1. Divide by 4 tests: -1 / 4 = -0.25 points.', 'checked', '{"lint":[],"solve":{"answer":"-0.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 8 + 3.5 - 1.5 = -1; -1 / 4 = -0.25.","run_id":"claude-code","at":"2026-10-24T03:05:34.658Z"}}', 'ai', NULL, NULL)
