INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('187dbf39-11a0-49e0-a6e8-f0e93b5668a0', 'NC17.7.EE.1', 1, 'numeric', 'Subtract linear expressions', 'When $(8x + 5) - (3x + 9)$ is simplified, what is the number part (the constant term)?', '[]', '-4', '5-9', 'Subtract the numbers: $5 - 9 = -4$. (The x-terms give $5x$, so the result is $5x - 4$.)', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x + 5 - 3x - 9 = 5x - 4. Constant -4.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
