INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b8cf609-29e2-48a2-a27c-d44ec8d7fbff', 'NC17.7.EE.1', 1, 'numeric', 'Factor linear expressions', 'The expression $10x + 15$ equals $5(2x + k)$. What is $k$?', '[]', '3', '15/5', 'Factor 5 out of each term: $10x = 5 \cdot 2x$ and $15 = 5 \cdot 3$. So $k = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(2x + k) = 10x + 5k = 10x + 15, so k = 3.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
