INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('005c35df-2310-4d58-ba71-76815ba2bf5e', 'NC17.7.EE.1', 1, 'numeric', 'Operations with rational coefficients', 'What is the coefficient of $x$ when $0.3x + 0.5x$ is simplified?', '[]', '0.8', '0.3+0.5', 'Add the coefficients: $0.3 + 0.5 = 0.8$, so $0.3x + 0.5x = 0.8x$.', 'checked', '{"lint":[],"solve":{"answer":"0.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3x + 0.5x = 0.8x. Coefficient 0.8.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
