INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10cb23aa-00b1-4e9a-aa13-5d2c62a1bcce', 'NC17.7.EE.1', 2, 'numeric', 'Add linear expressions', 'The expression $(2.5x - 4) + (1.5x + 9)$ is simplified. What is its value when $x = 2$?', '[]', '13', '4*2+5', 'Add: $2.5x + 1.5x = 4x$ and $-4 + 9 = 5$, so the expression is $4x + 5$. When $x = 2$ it is $4(2) + 5 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5x + 1.5x = 4x; -4 + 9 = 5: 4x + 5. At x = 2: 8 + 5 = 13.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
