INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d9bd55d-39ca-44af-bc74-9e5561869652', 'NC17.7.EE.1', 2, 'numeric', 'Operations with rational coefficients', 'The expression $\left(\frac{3}{4}x + 2\right) - \left(\frac{1}{4}x - 5\right)$ is simplified. What is its value when $x = 4$?', '[]', '9', '1/2*4+7', 'The x-terms give $\frac{3}{4}x - \frac{1}{4}x = \frac{1}{2}x$. The numbers give $2 - (-5) = 7$. So the expression is $\frac{1}{2}x + 7$, which is $2 + 7 = 9$ when $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 x - 1/4 x = 1/2 x; 2 + 5 = 7: x/2 + 7. At x = 4: 2 + 7 = 9.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09b49f43-34bb-4a45-94ff-51d62f840208', 'NC17.7.EE.1', 2, 'choice', 'Expand with rational coefficients', 'Which expression is equal to $\frac{1}{2}(6x - 8)$?', '["$3x - 4$","$3x - 8$","$12x - 16$","$6x - 4$"]', '$3x - 4$', NULL, 'Multiply each term by $\frac{1}{2}$: $\frac{1}{2} \cdot 6x = 3x$ and $\frac{1}{2} \cdot (-8) = -4$. The result is $3x - 4$.', 'checked', '{"lint":[],"solve":{"answer":"$3x - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 6x = 3x; 1/2 x (-8) = -4: 3x - 4.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f731f9-d9ae-4b53-9d67-f84d63e66ec4', 'NC17.7.EE.1', 3, 'choice', 'Operations with rational coefficients', 'Which expression is equal to $\frac{2}{3}(9x - 6) + \frac{1}{2}(4x + 10)$?', '["$8x + 6$","$8x + 1$","$8x - 9$","$8x - 1$"]', '$8x + 1$', NULL, 'Expand: $\frac{2}{3}(9x - 6) = 6x - 4$ and $\frac{1}{2}(4x + 10) = 2x + 5$. Combine: $6x + 2x = 8x$ and $-4 + 5 = 1$. The result is $8x + 1$.', 'checked', '{"lint":[],"solve":{"answer":"$8x + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3(9x - 6) = 6x - 4; 1/2(4x + 10) = 2x + 5; sum 8x + 1.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0eafdb8a-32b9-40af-8000-eb04773c66fd', 'NC17.7.EE.1', 3, 'numeric', 'Operations with rational coefficients', 'The expression $0.4(5x - 10) - 0.3(10x - 20)$ is simplified. What is its value when $x = 5$?', '[]', '-3', '-5+2', 'Expand: $0.4(5x - 10) = 2x - 4$ and $-0.3(10x - 20) = -3x + 6$. Combine to get $-x + 2$. When $x = 5$ it is $-5 + 2 = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4(5x - 10) = 2x - 4; -0.3(10x - 20) = -3x + 6; total -x + 2. At x = 5: -3.","run_id":"claude-code","at":"2026-10-24T03:05:55.387Z"}}', 'ai', NULL, NULL)
