INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0858e4ef-bc13-4be1-86b2-aa365714c19e', 'NC17.7.EE.2', 1, 'choice', 'Write a percent change as a multiplier', 'A jacket costs $j$ dollars. It is on sale for 25% off. Which expression gives the sale price in dollars?', '["$0.25j$","$0.75j$","$1.25j$","$j - 25$"]', '$0.75j$', NULL, 'Taking 25% off leaves 75% of the price, so the sale price is $0.75j$. The expression $0.25j$ is only the amount taken off.', 'checked', '{"lint":[],"solve":{"answer":"$0.75j$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% off leaves 75% of the price: j - 0.25j = 0.75j.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
