INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09df4405-1c89-42df-a382-8b17bb5babd0', 'NC17.7.EE.2', 1, 'numeric', 'Expand and combine like terms in context', 'Ben buys 3 notebooks that cost $n$ dollars each. Then he buys 5 more of the same notebooks. His total cost is $3n + 5n$ dollars, which can be written $kn$. What is $k$?', '[]', '8', '3+5', 'Like terms combine: $3n + 5n = 8n$, so $k = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3n + 5n = 8n, so k = 8.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
