INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c12a548-4def-4e7f-992b-01f1302d7750', 'NC17.7.EE.2', 1, 'choice', 'Distribute or factor to see another relationship', 'A rectangle has length $l$ and width $w$. Its perimeter is $2(l + w)$. Which expression also gives the perimeter?', '["$2l + 2w$","$2l + w$","$l + 2w$","$2lw$"]', '$2l + 2w$', NULL, 'Distribute the 2 to both terms: $2(l + w) = 2l + 2w$. Each of the two lengths and the two widths is counted.', 'checked', '{"lint":[],"solve":{"answer":"$2l + 2w$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distribute: 2(l + w) = 2l + 2w.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
