INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51fd4982-0983-4734-960a-16fb55646c75', 'NC17.7.EE.2', 2, 'choice', 'Distribute or factor to see another relationship', 'Mr. Cho has $8x + 12$ marbles to share equally among 4 bags. Which expression shows how many marbles go in each bag?', '["$2x + 12$","$2x + 3$","$8x + 3$","$8x + 8$"]', '$2x + 3$', NULL, 'Divide each term by 4: $8x \div 4 = 2x$ and $12 \div 4 = 3$. Each bag gets $2x + 3$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"$2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8x + 12)/4 = 2x + 3.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
