INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1efbc599-f91f-48cb-9686-3cc33878641d', 'NC17.7.EE.2', 2, 'numeric', 'Expand and combine like terms in context', 'A garden has two long sides of $3x + 2$ feet each and two short sides of $x + 5$ feet each. What is its perimeter, in feet, when $x = 3$?', '[]', '38', '2*(3*3+2)+2*(3+5)', 'The perimeter is $2(3x + 2) + 2(x + 5) = 8x + 14$. When $x = 3$ it is $24 + 14 = 38$ feet.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 2(3x + 2) + 2(x + 5) = 8x + 14; at x = 3: 24 + 14 = 38.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f1f725e-6afc-475a-88b8-e04c3827a312', 'NC17.7.EE.2', 2, 'numeric', 'Use a multiplier to find a price or a percent', 'The total cost of an item with 6% sales tax is $1.06p$ dollars, where $p$ is the price before tax in dollars. An item''s total cost is 53 dollars. What is its price before tax, in dollars?', '[]', '50', '53/(106/100)', 'Solve $1.06p = 53$. Dividing by 1.06 gives $p = 50$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.06p = 53, p = 53/1.06 = 50.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d374355-48a0-4519-9373-e2065f78830a', 'NC17.7.EE.2', 3, 'choice', 'Write a percent change as a multiplier', 'A store raises the price $p$ of a toy by 20%. Later it takes 10% off the new price. Which single expression gives the final price?', '["$1.1p$","$1.3p$","$1.08p$","$1.18p$"]', '$1.08p$', NULL, 'After the 20% raise the price is $1.2p$. Taking 10% off leaves 90% of that: $0.9 \times 1.2p = 1.08p$.', 'checked', '{"lint":[],"solve":{"answer":"$1.08p$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Raise 20%: 1.2p; then 10% off: 0.9(1.2p) = 1.08p.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d251cf7-5749-4290-97d9-c82fd28e4cde', 'NC17.7.EE.2', 3, 'choice', 'Interpret a term or factor in context', 'A group buys 6 tickets that cost $t$ dollars each. Each ticket also has a 2 dollar fee. Maria writes the total cost as $6t + 12$ and Jon writes it as $6(t + 2)$. Which statement is correct?', '["Only Maria''s is correct, because the 12 is the total of the fees","Only Jon''s is correct, because $6t + 12$ has too many terms","Both are correct; in Jon''s, $t + 2$ is the cost of one ticket with its fee","Neither is correct, because each fee should be multiplied by $t$"]', 'Both are correct; in Jon''s, $t + 2$ is the cost of one ticket with its fee', NULL, 'Distributing gives $6(t + 2) = 6t + 12$, so they are equivalent. Jon''s form shows 6 tickets that each cost $t + 2$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"Both are correct; in Jon''s, $t + 2$ is the cost of one ticket with its fee","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(t + 2) = 6t + 12; both correct, and t + 2 is one ticket with its fee.","run_id":"claude-code","at":"2026-10-24T03:08:14.912Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
