VALUES ('1bf8c412-898f-4c85-bef6-ed467f37ef7f', 'NC17.7.EE.3', 1, 'numeric', 'Multi-step percent problems (discount, tax, tip)', 'A jacket costs 40 dollars. It is on sale for $25\%$ off. What is the sale price, in dollars?', '[]', '30', '40-0.25*40', '$25\%$ of 40 is 10, so the discount is 10 dollars. The sale price is 40 - 10 = 30 dollars.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% of 40 = 10; 40 - 10 = 30.","run_id":"claude-code","at":"2026-10-24T03:06:56.272Z"}}', 'ai', NULL, NULL)
