INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19db6e50-cacb-435f-b3e5-dbba958def73', 'NC17.7.EE.3', 1, 'numeric', 'Multi-step problems with unit prices and rates', 'Pens cost 1.50 dollars each. How many dollars do 6 pens and one 2-dollar notebook cost altogether?', '[]', '11', '6*1.5+2', '6 pens cost 6 × 1.50 = 9 dollars. Adding the notebook gives 9 + 2 = 11 dollars.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 1.50 = 9; 9 + 2 = 11.","run_id":"claude-code","at":"2026-10-24T03:06:56.272Z"}}', 'ai', NULL, NULL)
