INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47a2881f-5502-400d-a1ef-d8dbbc69d591', 'NC17.7.EE.3', 2, 'numeric', 'Multi-step problems with negative numbers', 'A submarine is at $-150$ meters. It rises 12.5 meters each minute for 6 minutes. What is its position then, in meters?', '[]', '-75', '-150+12.5*6', 'It rises 12.5 × 6 = 75 meters. Then $-150 + 75 = -75$ meters.', 'checked', '{"lint":[],"solve":{"answer":"-75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rises 12.5 x 6 = 75 m; -150 + 75 = -75.","run_id":"claude-code","at":"2026-10-24T03:06:56.272Z"}}', 'ai', NULL, NULL)
