INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2844496d-9349-4908-a9ce-3624b979b257', 'NC17.7.EE.3', 2, 'numeric', 'Multi-step problems with negative numbers', 'In four hours the temperature changed by $-3.5$, $+1.25$, $-2$ and $+0.5$ degrees. What was the total change, in degrees?', '[]', '-3.75', '-3.5+1.25-2+0.5', '-3.5 + 1.25 = -2.25. Then -2.25 - 2 = -4.25. Then -4.25 + 0.5 = -3.75 degrees.', 'checked', '{"lint":[],"solve":{"answer":"-3.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3.5 + 1.25 = -2.25; -2.25 - 2 = -4.25; -4.25 + 0.5 = -3.75.","run_id":"claude-code","at":"2026-10-24T03:06:56.272Z"}}', 'ai', NULL, NULL)
