INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1207e181-9a2d-49c3-81e8-3729788e57ae', 'NC17.7.EE.3', 2, 'choice', 'Convert between fractions, decimals and percents to solve', 'What is $2.4 \times \frac{5}{8}$?', '["$1.5$","$3.84$","$15$","$0.15$"]', '$1.5$', '2.4*5/8', 'Write 5/8 as 0.625. Then 2.4 × 0.625 = 1.5. (Or 2.4 × 5 = 12, and 12 ÷ 8 = 1.5.)', 'checked', '{"lint":[],"solve":{"answer":"$1.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 = 0.625; 2.4 x 0.625 = 1.5 (or 2.4 x 5 / 8 = 12/8 = 1.5).","run_id":"claude-code","at":"2026-10-24T03:06:56.272Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31460166-35ed-4e83-b31a-307c35b71ffd', 'NC17.7.EE.3', 3, 'choice', 'Convert between fractions, decimals and percents to solve', 'Of 240 students, $\frac{5}{8}$ ride the bus and $0.15$ walk. The rest are driven by a family member. How many students are driven?', '["$126$","$54$","$36$","$204$"]', '$54$', '240-5/8*240-0.15*240', '$\frac{5}{8}$ of 240 is 150 and $0.15$ of 240 is 36. 240 - 150 - 36 = 54 students.', 'checked', '{"lint":[],"solve":{"answer":"$54$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bus 5/8 x 240 = 150; walk 0.15 x 240 = 36; driven 240 - 150 - 36 = 54.","run_id":"claude-code","at":"2026-10-24T03:06:56.272Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0704dd09-80ba-4a8c-9967-5b325dfe43bd', 'NC17.7.EE.3', 3, 'choice', 'Multi-step problems with negative numbers', 'An account has a balance of $-42.50$ dollars. Then half of an 80-dollar paycheck is deposited and a 3.75-dollar fee is charged. What is the new balance, in dollars?', '["$-2.5$","$1.25$","$-86.25$","$-6.25$"]', '$-6.25$', '-42.5+80/2-3.75', 'Half of 80 is 40. -42.50 + 40 = -2.50. The fee lowers it by 3.75: -2.50 - 3.75 = -6.25 dollars.', 'checked', '{"lint":[],"solve":{"answer":"$-6.25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half of 80 = 40. -42.50 + 40 = -2.50; -2.50 - 3.75 = -6.25.","run_id":"claude-code","at":"2026-10-24T03:06:56.272Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('154abe76-3af1-4158-b7ed-e2f630230a6a', 'NC17.7.EE.4', 1, 'choice', 'Solve px + q > r', 'Which value of $x$ makes $2x + 1 > 9$ true?', '["5","2","3","4"]', '5', '5', 'Try each value. $x = 4$ gives $2(4) + 1 = 9$, which is not greater than 9. $x = 5$ gives $11$, which is greater than 9. The values 2 and 3 give 5 and 7.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x>8, x>4. Only 5 among 2,4,5,3.","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05433c3f-1fc7-4506-9a6b-34bd5fa94ade', 'NC17.7.EE.4', 1, 'numeric', 'Solve an equation in a story', 'Mia buys 4 notebooks that cost the same amount each and one pen that costs 3 dollars. She pays 19 dollars in all. How many dollars does one notebook cost?', '[]', '4', '(19-3)/4', 'The notebooks cost $19 - 3 = 16$ dollars together. Four notebooks cost 16 dollars, so one costs $16 \div 4 = 4$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4n+3=19, 4n=16, n=4.","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('378f75c9-9105-4434-9eb0-49189929de45', 'NC17.7.EE.4', 1, 'numeric', 'Solve p(x + q) = r', 'Three times the sum of a number and 4 is 21. What is the number?', '[]', '3', '21/3-4', 'Write $3(n + 4) = 21$. Divide both sides by 3: $n + 4 = 7$. Subtract 4: $n = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(n+4)=21, n+4=7, n=3.","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05e8ef86-7e85-4a11-9316-90e6cd3cab0b', 'NC17.7.EE.4', 2, 'numeric', 'Solve an equation in a story', 'A rectangle has a length of 9 centimeters and a perimeter of 40 centimeters. What is its width, in centimeters?', '[]', '11', '40/2-9', 'The perimeter is $2(w + 9) = 40$. Divide by 2: $w + 9 = 20$. Subtract 9: $w = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(9+w)=40, 9+w=20, w=11.","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
