VALUES ('32acf9b9-3f6a-4a36-b733-e6296c7ea19b', 'NC17.7.EE.4', 2, 'choice', 'Solve px + q > r', 'Which inequality shows the solution of $4x - 5 \ge 11$?', '["$x \\ge 4$","$x \\le 4$","$x \\ge 1.5$","$x \\ge 16$"]', '$x \ge 4$', NULL, 'Add 5 to both sides: $4x \ge 16$. Divide both sides by 4: $x \ge 4$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x>=16, x>=4.","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
