INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05e527aa-a32c-4711-9dfe-3b55c96737c3', 'NC17.7.EE.4', 2, 'choice', 'Interpret a solution in context', 'Lena has 40 dollars. Each ticket costs 6 dollars, and she also pays a 4 dollar fee. Solving $6t + 4 \le 40$ gives $t \le 6$. What does this tell Lena?', '["She must buy at least 6 tickets","She must buy exactly 6 tickets","She can buy 6 tickets or fewer","She can buy up to 36 tickets"]', 'She can buy 6 tickets or fewer', NULL, 'The inequality $t \le 6$ says the number of tickets is 6 or less. Check: 6 tickets cost $36 + 4 = 40$ dollars, which is all she has.', 'checked', '{"lint":[],"solve":{"answer":"She can buy 6 tickets or fewer","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t<=6 means 6 tickets or fewer.","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
