VALUES ('11aa69ef-0504-4f79-94bb-ce3a1815e511', 'NC17.7.EE.4', 3, 'numeric', 'Solve px + q = r', 'Solve $-3x - 4 = 11$.', '[]', '-5', '(11+4)/(-3)', 'Add 4 to both sides: $-3x = 15$. Divide both sides by $-3$: $x = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x=15, x=-5.","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
