INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1de12c24-5073-43c3-8c52-2c73dfd97fae', 'NC17.7.EE.4', 3, 'choice', 'Interpret a solution in context', 'A phone plan costs 25 dollars a month plus 0.10 dollars for each text. Ravi wants to pay less than 40 dollars in a month. Which statement describes the number of texts $n$ he can send?', '["He must send more than 150 texts","He can send fewer than 150 texts","He can send fewer than 15 texts","He can send at most 150 texts"]', 'He can send fewer than 150 texts', NULL, 'The cost is $25 + 0.10n$, so $25 + 0.10n < 40$. Then $0.10n < 15$ and $n < 150$. At 150 texts the cost is exactly 40 dollars, not less, so 150 is not allowed.', 'checked', '{"lint":[],"solve":{"answer":"He can send fewer than 150 texts","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25+0.10n<40, 0.10n<15, n<150. Strict, so fewer than 150 (150 texts costs exactly 40).","run_id":"claude-code","at":"2026-10-24T03:11:51.381Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca5c7a1-0cab-4d52-9e42-7492a033e5f3', 'NC17.7.G.1', 1, 'numeric', 'Find an actual length from a scale drawing', 'On a map, 1 cm represents 8 km. Two towns are 5 cm apart on the map. How many kilometers apart are the towns in real life?', '[]', '40', '5*8', 'Each centimeter on the map is 8 km. 5 cm is $5 \times 8 = 40$ km.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 cm x 8 km/cm = 40 km.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
