INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77904cc2-d2bb-45bb-ba1a-33ee53e3464c', 'NC17.7.G.1', 1, 'choice', 'Find or use the scale', 'A scale drawing uses the scale 1 cm : 2 m. Which statement is true?', '["2 cm on the drawing is 2 m in real life","2 cm on the drawing is 1 m in real life","2 cm on the drawing is 4 m in real life","2 cm on the drawing is 3 m in real life"]', '2 cm on the drawing is 4 m in real life', NULL, 'Each 1 cm stands for 2 m, so 2 cm stands for $2 \times 2 = 4$ m.', 'checked', '{"lint":[],"solve":{"answer":"2 cm on the drawing is 4 m in real life","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 cm = 2 m, so 2 cm = 4 m. Only that option is correct.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d1ac82b-ce9b-41d4-a764-1eec0ffa3fed', 'NC17.7.G.1', 1, 'choice', 'Create a scale drawing: choose the drawing dimensions', 'A rectangle that is 8 m by 4 m is drawn with the scale 1 cm : 2 m. What are the dimensions of the rectangle in the drawing?', '["4 cm by 2 cm","16 cm by 8 cm","6 cm by 2 cm","8 cm by 4 cm"]', '4 cm by 2 cm', NULL, 'Divide each length by 2 m per cm: $8 \div 2 = 4$ and $4 \div 2 = 2$. The drawing is 4 cm by 2 cm.', 'checked', '{"lint":[],"solve":{"answer":"4 cm by 2 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/2 = 4 cm, 4/2 = 2 cm: 4 cm by 2 cm.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('490bbbc2-0d20-4774-8706-b85e264866b0', 'NC17.7.G.1', 2, 'numeric', 'Find an actual length from a scale drawing', 'A scale drawing has the scale 1 cm : 2.5 m. A line in the drawing is 6 cm long. How many meters long is the real object?', '[]', '15', '6*2.5', 'Each centimeter is 2.5 m. $6 \times 2.5 = 15$ m.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2.5 = 15 m.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
