INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37c2ea3f-6c52-4bf3-94f1-a223f486fbfa', 'NC17.7.G.1', 2, 'numeric', 'Find a drawing length from an actual length', 'A floor plan uses the scale 1 inch : 6 feet. A room is 15 feet long. How many inches long is the room on the floor plan?', '[]', '2.5', '15/6', 'Each inch stands for 6 feet. $15 \div 6 = 2.5$ inches.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 / 6 = 2.5 inches.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
