INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('050e98c5-dfb8-4d86-891f-3aad0487bbd7', 'NC17.7.G.1', 2, 'numeric', 'Find or use the scale', 'On a map, a road that is 28 km long is drawn 4 cm long. How many kilometers does 1 cm on the map represent?', '[]', '7', '28/4', 'Divide the real length by the drawing length: $28 \div 4 = 7$ km for each centimeter.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 4 = 7 km per cm.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
