INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11dfb54a-f64d-433c-badf-01951e0ad5d0', 'NC17.7.G.1', 3, 'numeric', 'Find or use the scale', 'On a plan, a wall that is 12 m long is drawn 3 cm long. How many centimeters long should a 20 m wall be drawn on the same plan?', '[]', '5', '20/(12/3)', '$12 \div 3 = 4$, so 1 cm stands for 4 m. A 20 m wall is $20 \div 4 = 5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 cm = 4 m; 20/4 = 5 cm.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
