INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0999b60a-5cca-41d2-96f4-3396d77a0f02', 'NC17.7.G.1', 3, 'numeric', 'Compare areas on a drawing and in real life', 'A scale drawing uses the scale 1 inch : 4 feet. A rectangular room is 10 feet by 6 feet. What is the area of the room in the drawing, in square inches?', '[]', '3.75', '(10/4)*(6/4)', 'In the drawing the room is $10 \div 4 = 2.5$ inches by $6 \div 4 = 1.5$ inches. The area is $2.5 \times 1.5 = 3.75$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"3.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawing 10/4 = 2.5 in by 6/4 = 1.5 in; area 3.75 square inches.","run_id":"claude-code","at":"2026-10-24T03:12:50.767Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('263ebd85-7d5f-4427-9d43-61506443c16b', 'NC17.7.G.2', 1, 'choice', 'Side lengths that make a triangle', 'Which sentence about the side lengths 4 cm, 4 cm and 9 cm is true?', '["They cannot form a triangle because 4 + 4 is less than 9","They can form a triangle because two of the sides are equal","They can form a triangle because 4 + 9 is greater than 4","They cannot form a triangle because the sides are not all equal"]', 'They cannot form a triangle because 4 + 4 is less than 9', NULL, 'The two shorter sides must add to more than the longest side. 4 + 4 = 8, which is less than 9, so the two short sides cannot reach each other.', 'checked', '{"lint":[],"solve":{"answer":"They cannot form a triangle because 4 + 4 is less than 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 4 = 8 < 9, so no triangle. The first option is correct; the others give wrong conclusions or wrong reasons.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c5bc96d-4f30-4385-aa30-761135b15f6e', 'NC17.7.G.2', 1, 'choice', 'Build a triangle from measures', 'Mia draws a segment 6 cm long. She wants a triangle whose other two sides are 4 cm and 5 cm. She sets her compass to 4 cm and draws an arc from one end of the segment. What should she do next?', '["Set the compass to 5 cm, draw an arc from the other end, and join the point where the arcs cross to both ends","Set the compass to 4 cm, draw an arc from the other end, and join the point where the arcs cross to both ends","Set the compass to 6 cm, draw an arc from the other end, and join the point where the arcs cross to both ends","Set the compass to 5 cm, draw an arc from the same end, and join the point where the arcs cross to both ends"]', 'Set the compass to 5 cm, draw an arc from the other end, and join the point where the arcs cross to both ends', NULL, 'The 4 cm arc is the set of points 4 cm from one end. The third point must also be 5 cm from the other end, so draw a 5 cm arc from the other end. Where the arcs cross is the third corner.', 'checked', '{"lint":[],"solve":{"answer":"Set the compass to 5 cm, draw an arc from the other end, and join the point where the arcs cross to both ends","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One end gets the 4 cm side; the other end must get the 5 cm side: set compass to 5 cm, arc from the other end, join the crossing point to both ends.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28803b31-45fb-4338-b56c-ba20051d905f', 'NC17.7.G.2', 1, 'numeric', 'Build a triangle from measures', 'A triangle is drawn on a 7 cm segment, with a $50^\circ$ angle at one end and a $60^\circ$ angle at the other end. How many degrees is the angle where the other two sides meet?', '[]', '70', '180-50-60', 'The three angles add to 180. 50 + 60 = 110, and 180 - 110 = 70.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 50 - 60 = 70.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('162c42eb-9c3b-4985-9bdf-7af98f78996a', 'NC17.7.G.2', 2, 'choice', 'Side lengths that make a triangle', 'Which set of side lengths cannot form a triangle?', '["4 cm, 6 cm, 9 cm","4 cm, 6 cm, 10 cm","5 cm, 7 cm, 11 cm","3 cm, 3 cm, 5 cm"]', '4 cm, 6 cm, 10 cm', NULL, 'Check that the two shorter sides add to more than the longest. For 4, 6 and 10, 4 + 6 = 10, which is not more than 10, so the sides lie flat. The other sets pass: 10 > 9, 12 > 11 and 6 > 5.', 'checked', '{"lint":[],"solve":{"answer":"4 cm, 6 cm, 10 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5+7=12>11 ok; 3+3=6>5 ok; 4+6=10>9 ok; 4+6=10 not >10, so 4, 6, 10 cannot.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
