INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13fa3d60-de0a-43b6-bdd1-b123e0cbc135', 'NC17.7.G.2', 2, 'choice', 'Three angles: many triangles', 'Maria knows only that the angles of a triangle are $40^\circ$, $60^\circ$ and $80^\circ$. How many different triangles could she draw?', '["Many triangles of different sizes","Exactly one triangle, of one size","No triangle, because the angles are too small","Exactly two triangles, one large and one small"]', 'Many triangles of different sizes', NULL, 'The angles add to 180, so a triangle is possible. But angles alone do not fix the size: a small and a large triangle can have the same angles. So there are many.', 'checked', '{"lint":[],"solve":{"answer":"Many triangles of different sizes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles sum to 180 so triangles exist, but angles alone fix only the shape; any size works: many triangles.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b682bb2-a531-4ebb-8b68-d6db0ba524d1', 'NC17.7.G.2', 2, 'choice', 'Build a triangle from measures', 'Ravi wants to draw exactly one triangle with a ruler and a protractor. Which set of measures is enough?', '["All three angles, but no side lengths","Two angles, but no side lengths","One side and one angle next to it","Two sides and the angle between them"]', 'Two sides and the angle between them', NULL, 'Draw one side, use the protractor to draw the angle at its end, then measure the second side along the new ray. Joining the ends finishes the one triangle. Angles alone, or one side with one angle, leave many possibilities.', 'checked', '{"lint":[],"solve":{"answer":"Two sides and the angle between them","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SAS fixes a unique triangle. Angles alone give many; one side and one angle leaves the rest free.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39bda1aa-1183-4ef1-94c5-0ec12ea80b0c', 'NC17.7.G.2', 3, 'choice', 'Range of the third side', 'Two sides of a triangle are 5 cm and 9 cm. The third side is $x$ cm. Which statement shows all possible values of $x$?', '["$4 < x < 14$","$5 < x < 9$","$9 < x < 14$","$x > 14$"]', '$4 < x < 14$', NULL, 'The third side must be more than 9 - 5 = 4 and less than 9 + 5 = 14. So $4 < x < 14$.', 'checked', '{"lint":[],"solve":{"answer":"$4 < x < 14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 5 < x < 9 + 5: 4 < x < 14.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f77c233-96f4-40c1-aae3-90e7e6ad5c4b', 'NC17.7.G.2', 3, 'choice', 'Side lengths that make a triangle', 'Which set of measures cannot make any triangle?', '["Sides of 5 cm, 5 cm and 9 cm","Sides of 3 cm, 4 cm and 8 cm","Angles of $100^\\circ$, $40^\\circ$ and $40^\\circ$","Sides of 6 cm and 6 cm with a $100^\\circ$ angle between them"]', 'Sides of 3 cm, 4 cm and 8 cm', NULL, 'For 3, 4 and 8, 3 + 4 = 7 is less than 8, so no triangle. The others work: 5 + 5 > 9; the angles add to 180; and two sides with the angle between them always make a triangle.', 'checked', '{"lint":[],"solve":{"answer":"Sides of 3 cm, 4 cm and 8 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+4=7<8: none. 100+40+40=180: possible. 5+5=10>9: possible. SAS 6, 6, 100: possible.","run_id":"claude-code","at":"2026-10-24T03:16:03.015Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('514a6893-e861-4f8e-9aa0-1362d993b2e5', 'NC17.7.G.4', 1, 'numeric', 'Area from a radius or diameter', 'A circle has a radius of 5 centimeters. Use 3.14 for $\pi$. What is its area, in square centimeters?', '[]', '78.5', '3.14*5^2', '$A = \pi r^2 = 3.14 \times 5^2 = 3.14 \times 25 = 78.5$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"78.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x 25 = 78.5.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ab3b1fc-3238-4fe2-80bd-3a776852178e', 'NC17.7.G.4', 1, 'choice', 'Know the circle formulas and pi', 'For any circle, the circumference divided by the diameter is equal to which number?', '["$2 \\pi$, about 6.28","$\\pi^2$, about 9.87","$\\pi$, about 3.14","$\\frac{\\pi}{2}$, about 1.57"]', '$\pi$, about 3.14', NULL, 'Since $C = \pi d$, dividing the circumference by the diameter gives $\pi$, which is about 3.14.', 'checked', '{"lint":[],"solve":{"answer":"$\\pi$, about 3.14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C/d = pi, about 3.14.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b9e66cb-e4dd-4f72-983f-ae116026637a', 'NC17.7.G.4', 1, 'choice', 'Circumference from a radius or diameter', 'A circle has a radius of 4 centimeters. What is its circumference?', '["$8 \\pi$ centimeters","$16 \\pi$ centimeters","$4 \\pi$ centimeters","$2 \\pi$ centimeters"]', '$8 \pi$ centimeters', NULL, '$C = 2 \pi r = 2 \times \pi \times 4 = 8 \pi$ centimeters. The number $16 \pi$ is the area.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\pi$ centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 pi r = 8 pi.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
