INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8159de65-aaec-40b1-bf09-0687de4d22cb', 'NC17.7.G.4', 2, 'choice', 'Area from a radius or diameter', 'A round rug has a radius of 6 feet. What is its area?', '["$12 \\pi$ square feet","$6 \\pi$ square feet","$36 \\pi$ square feet","$72 \\pi$ square feet"]', '$36 \pi$ square feet', NULL, '$A = \pi r^2 = \pi \times 6^2 = 36 \pi$ square feet. The number $12 \pi$ is the circumference.', 'checked', '{"lint":[],"solve":{"answer":"$36 \\pi$ square feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi x 6^2 = 36 pi.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
