INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6291d966-f330-4ede-a293-619fdf4ad40e', 'NC17.7.G.4', 2, 'choice', 'Area from a radius or diameter', 'A circle has a diameter of 30 millimeters. Use 3.14 for $\pi$. What is its area?', '["2826 square millimeters","706.5 square millimeters","94.2 square millimeters","47.1 square millimeters"]', '706.5 square millimeters', NULL, 'The radius is 15 mm. $A = 3.14 \times 15^2 = 3.14 \times 225 = 706.5$ square millimeters. Using 30 as the radius gives 2826.', 'checked', '{"lint":[],"solve":{"answer":"706.5 square millimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 15; 3.14 x 225 = 706.5.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
