INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a57df94-14b0-4cb4-bc40-121b9e692638', 'NC17.7.G.4', 2, 'choice', 'Area from a radius or diameter', 'The diameter of a circle is 14 centimeters. Which expression gives its area in square centimeters?', '["$\\pi \\times 14^2$","$2 \\times \\pi \\times 7$","$\\pi \\times 14$","$\\pi \\times 7^2$"]', '$\pi \times 7^2$', NULL, 'The radius is 14 / 2 = 7 centimeters, and $A = \pi r^2 = \pi \times 7^2$.', 'checked', '{"lint":[],"solve":{"answer":"$\\pi \\times 7^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 7; A = pi x 7^2.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
