INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4099f64b-2196-4f2c-92ad-ae199be914d2', 'NC17.7.G.4', 3, 'choice', 'Compare circles and how they scale', 'The radius of Circle B is 3 times the radius of Circle A. How many times as large as the area of Circle A is the area of Circle B?', '["3 times","6 times","9 times","27 times"]', '9 times', NULL, 'Area is pi times the radius squared. If the radius is 3 times as long, the area is $3^2 = 9$ times as large.', 'checked', '{"lint":[],"solve":{"answer":"9 times","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area scales with r^2: 3^2 = 9.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a938bf9-8316-4055-acb7-4eda9fe09012', 'NC17.7.G.4', 3, 'numeric', 'Circle problems in context', 'A round pizza has a diameter of 14 inches. It is cut into 8 equal slices. Use $\frac{22}{7}$ for $\pi$. What is the area of one slice, in square inches?', '[]', '19.25', '22/7*7^2/8', 'The radius is 7 inches. The whole pizza is $\frac{22}{7} \times 49 = 154$ square inches. One slice is 154 / 8 = 19.25 square inches.', 'checked', '{"lint":[],"solve":{"answer":"19.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 7; A = 22/7 x 49 = 154; 154 / 8 = 19.25.","run_id":"claude-code","at":"2026-10-24T03:14:57.486Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40a5a55c-5284-4927-98f7-4db534ecd08e', 'NC17.7.G.5', 1, 'numeric', 'Finding a complementary angle', 'Two angles are complementary. One angle measures $35^\circ$. What is the measure of the other angle, in degrees?', '[]', '55', '90-35', 'Complementary angles add up to $90^\circ$. $90 - 35 = 55$, so the other angle measures $55^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 - 35 = 55.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66d72f71-8180-426b-b56c-d3134a21e225', 'NC17.7.G.5', 1, 'numeric', 'Vertical angles', 'Two lines cross. One of the angles formed measures $70^\circ$. What is the measure of its vertical angle, in degrees?', '[]', '70', NULL, 'Vertical angles are across from each other where two lines cross, and they have equal measures. The vertical angle also measures $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles are equal: 70.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
