INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f358375-7b7a-4192-a56b-a55dc6019e04', 'NC17.7.G.5', 1, 'numeric', 'Finding a supplementary angle', 'A ray starts on a straight line and splits the straight angle into two angles. One of them measures $64^\circ$. What does the other measure, in degrees?', '[]', '116', '180-64', 'A straight angle measures $180^\circ$, so the two angles are supplementary. $180 - 64 = 116$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"116","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 64 = 116.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
