INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bbd12a3-65f2-40a2-adbf-0083a40e8fe3', 'NC17.7.G.5', 2, 'numeric', 'Solving for an unknown angle with an equation', 'Two complementary angles measure $x^\circ$ and $2x^\circ$. What is the value of $x$?', '[]', '30', '90/3', 'Complementary angles add up to $90^\circ$, so $x + 2x = 90$. Then $3x = 90$ and $x = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x = 90, 3x = 90, x = 30.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10e9104f-0d57-4ce7-aa68-cd4df6076fd8', 'NC17.7.G.5', 2, 'choice', 'Writing an equation for an angle relationship', 'Two angles are supplementary. One measures $(2x + 10)^\circ$ and the other measures $50^\circ$. Which equation can be used to find $x$?', '["$(2x + 10) + 50 = 180$","$(2x + 10) + 50 = 90$","$(2x + 10) = 50$","$2x + 10 + 50 + 180 = 0$"]', '$(2x + 10) + 50 = 180$', NULL, 'Supplementary angles add up to $180^\circ$, so the sum of the two measures is 180: $(2x + 10) + 50 = 180$.', 'checked', '{"lint":[],"solve":{"answer":"$(2x + 10) + 50 = 180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Supplementary: (2x+10) + 50 = 180.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00ce5e59-3205-4dc6-9d6e-f35e83980c69', 'NC17.7.G.5', 2, 'choice', 'Reasoning about angle pairs', 'Angles 1 and 2 are vertical angles. Angles 2 and 3 are adjacent angles on a straight line. Angle 1 measures $50^\circ$. What does angle 3 measure?', '["$40^\\circ$","$50^\\circ$","$130^\\circ$","$310^\\circ$"]', '$130^\circ$', NULL, 'Vertical angles are equal, so angle 2 measures $50^\circ$. Angle 3 and angle 2 add to $180^\circ$, so angle 3 is $180 - 50 = 130^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$130^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle 2 = angle 1 = 50 (vertical). Angle 3 = 180 - 50 = 130.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07e24017-af6b-44e4-8480-ef0199a6ef60', 'NC17.7.G.5', 3, 'numeric', 'Adjacent angles on a line', 'Two lines cross. Two adjacent angles measure $(4x + 8)^\circ$ and $(2x + 22)^\circ$. What is the measure of the larger of the two angles, in degrees?', '[]', '108', '4*25+8', 'Adjacent angles from crossing lines add to $180^\circ$: $6x + 30 = 180$, so $x = 25$. The angles are $4(25) + 8 = 108$ and $2(25) + 22 = 72$. The larger is 108 degrees.', 'checked', '{"lint":[],"solve":{"answer":"108","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Linear pair: 4x + 8 + 2x + 22 = 180, 6x = 150, x = 25. Angles 108 and 72; larger 108.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1083b58f-9121-4ece-9bae-33d8733f6e80', 'NC17.7.G.5', 3, 'numeric', 'Solving for an unknown angle with an equation', 'Two angles are complementary. One measures $(4x + 6)^\circ$ and the other measures $(2x - 12)^\circ$. What is the measure of the smaller angle, in degrees?', '[]', '20', '2*16-12', 'The sum is 90: $(4x + 6) + (2x - 12) = 90$, so $6x - 6 = 90$ and $x = 16$. The angles are $4(16) + 6 = 70$ and $2(16) - 12 = 20$. The smaller is 20 degrees.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 6 + 2x - 12 = 90, 6x - 6 = 90, x = 16. Angles 70 and 20; smaller 20.","run_id":"claude-code","at":"2026-10-24T03:17:18.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a91b2b8-0f1d-4a63-96f0-cc9db6a07875', 'NC17.7.G.6', 1, 'choice', 'Volume of a pyramid', 'A pyramid has a base with an area of 18 square centimeters and a height of 5 centimeters. What is its volume?', '["90 cubic centimeters","45 cubic centimeters","23 cubic centimeters","30 cubic centimeters"]', '30 cubic centimeters', NULL, 'The volume of a pyramid is one third of the base area times the height: $\frac{1}{3} \times 18 \times 5 = 30$ cubic centimeters. Leaving out the one third gives 90.', 'checked', '{"lint":[],"solve":{"answer":"30 cubic centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)Bh = (1/3)(18)(5) = 30.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cbe5f84-c753-4adb-ae2a-1e9743fd85c2', 'NC17.7.G.6', 1, 'choice', 'Area of a composite figure', 'A square 10 meters on each side has a square 3 meters on each side cut out of one corner. What is the area of the figure that is left?', '["109 square meters","91 square meters","97 square meters","70 square meters"]', '91 square meters', NULL, 'The big square has area $10 \times 10 = 100$ and the piece cut out has area $3 \times 3 = 9$. What is left has area $100 - 9 = 91$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"91 square meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 9 = 91.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fb2e694-0d6c-4014-842b-bb3d99c80273', 'NC17.7.G.6', 1, 'choice', 'Perimeter of a composite figure', 'A rectangle 4 centimeters long and 3 centimeters wide is joined to a square with 3-centimeter sides, along a 3-centimeter side, to make one larger rectangle. What is the perimeter of the larger rectangle?', '["26 centimeters","10 centimeters","20 centimeters","14 centimeters"]', '20 centimeters', NULL, 'The larger rectangle is $4 + 3 = 7$ centimeters long and 3 centimeters wide. Its perimeter is $7 + 3 + 7 + 3 = 20$ centimeters. Adding the two separate perimeters gives 26, which counts the joined side twice.', 'checked', '{"lint":[],"solve":{"answer":"20 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger rectangle 7 by 3; perimeter 2(7+3) = 20.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ee26367-f163-45e3-b928-4b49bcd74eb8', 'NC17.7.G.6', 2, 'numeric', 'Surface area of a prism', 'A box is 10 inches long, 6 inches wide, and 4 inches tall. What is its surface area in square inches?', '[]', '248', '2*(10*6+10*4+6*4)', 'The faces come in three pairs: $10 \times 6 = 60$, $10 \times 4 = 40$ and $6 \times 4 = 24$. Doubling the sum gives $2 \times (60 + 40 + 24) = 248$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"248","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(10x6 + 10x4 + 6x4) = 2(60+40+24) = 248.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43e694f6-2656-4995-9a84-f0faa9da1d80', 'NC17.7.G.6', 2, 'choice', 'Perimeter of a composite figure', 'An L-shaped figure has only right angles. Going around it, its sides measure 10, 3, 6, 5, 4 and 8 centimeters. What is its perimeter?', '["18 centimeters","50 centimeters","36 centimeters","72 centimeters"]', '36 centimeters', NULL, 'The perimeter is the sum of all the sides: $10 + 3 + 6 + 5 + 4 + 8 = 36$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"36 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides consistent (10 = 6+4, 8 = 3+5). Perimeter 10+3+6+5+4+8 = 36.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
