INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52f57199-4237-43b3-b6d5-ffa2de8dbe8b', 'NC17.7.G.6', 2, 'numeric', 'Surface area of a pyramid', 'A square pyramid has a square base 10 centimeters on each side. Each of its four triangular faces has a base of 10 centimeters and a height of 8 centimeters. What is the surface area of the pyramid in square centimeters?', '[]', '260', '10*10+4*(1/2*10*8)', 'The base has area $10 \times 10 = 100$. Each triangle has area $\frac{1}{2} \times 10 \times 8 = 40$, so the four have area 160. The total is $100 + 160 = 260$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"260","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 100; faces 4 x (1/2)(10)(8) = 160; total 260.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a5c1b38-b411-41c9-913e-630720cd576a', 'NC17.7.G.6', 3, 'choice', 'Surface area of a prism', 'A triangular prism has triangular ends with sides of 3, 4 and 5 centimeters (a right triangle with legs 3 and 4). The prism is 10 centimeters long. What is its surface area?', '["132 square centimeters","120 square centimeters","60 square centimeters","126 square centimeters"]', '132 square centimeters', NULL, 'Each triangular end has area $\frac{1}{2} \times 3 \times 4 = 6$, so the two ends have area 12. The three rectangles have a combined width of $3 + 4 + 5 = 12$ and length 10, so area 120. The total is $12 + 120 = 132$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"132 square centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two ends 2 x (1/2)(3)(4) = 12; sides (3+4+5) x 10 = 120; total 132.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1458fcf9-9575-47fb-a6ec-d9a1d67f6106', 'NC17.7.G.6', 3, 'numeric', 'Volume of a prism', 'A triangular prism has a volume of 180 cubic centimeters. Its triangular base has a base of 9 centimeters and a height of 5 centimeters. How many centimeters long is the prism?', '[]', '8', '180/(1/2*9*5)', 'The triangle has area $\frac{1}{2} \times 9 \times 5 = 22.5$ square centimeters. Since volume is base area times length, the length is $180 \div 22.5 = 8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area (1/2)(9)(5) = 22.5; 180 / 22.5 = 8.","run_id":"claude-code","at":"2026-10-24T08:22:16.996Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38ae93d2-fccf-462f-8124-985e55f15235', 'NC17.7.SP.1', 1, 'numeric', 'Tell the population from the sample', 'A factory makes 1,000 light bulbs in a day and tests 25 of them. How many bulbs are in the sample?', '[]', '25', '25', 'The sample is the part of the group that is actually tested. Here 25 bulbs are tested, so the sample has 25 bulbs. (The population is all 1,000 bulbs.)', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample is the bulbs actually tested: 25.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d4550b3-a1ec-4e39-904b-229ef1d1e2f1', 'NC17.7.SP.1', 1, 'choice', 'Spot why a sample is biased', 'Mina wants to know the favorite pet of the students in her school. She asks only students in the pet club. Why might this sample not represent the whole school?', '["Pet club members are not typical of the school","Too many students in the school were asked this question","The students were picked by a fair random drawing","Students cannot be asked about their favorite pets"]', 'Pet club members are not typical of the school', NULL, 'Pet club members may feel differently about pets than other students, so the sample leaves out the views of many. A sample should be a fair picture of the whole group.', 'checked', '{"lint":[],"solve":{"answer":"Pet club members are not typical of the school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pet club members likely like pets/particular pets more than typical students, so the sample is biased.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c67f974-cf46-48d5-bdac-2cb865d13d02', 'NC17.7.SP.1', 1, 'choice', 'Sample size', 'A school has 2,000 students. Which random sample would best represent the whole school?', '["A random sample of 20 students","A random sample of ten students","A random sample of 200 students","A random sample of two students"]', 'A random sample of 200 students', NULL, 'A larger random sample is more likely to be close to the whole population. 200 is the largest of these samples.', 'checked', '{"lint":[],"solve":{"answer":"A random sample of 200 students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples give more reliable estimates; 200 is the largest.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5309c7a8-c135-455a-bb60-bb05775e261c', 'NC17.7.SP.1', 2, 'choice', 'Choose a random, representative sampling method', 'A city wants to know how residents feel about a new bus route. Which is the best way to choose the sample?', '["Survey 400 people who are waiting at the bus station","Survey 400 people who live along the new bus route","Survey the first 400 people who answer an online post","Randomly choose 400 homes from a list of all homes"]', 'Randomly choose 400 homes from a list of all homes', NULL, 'Choosing addresses at random gives every resident a chance to be included. People at the bus station, along the route, or who answer an online post are not typical of all residents.', 'checked', '{"lint":[],"solve":{"answer":"Randomly choose 400 homes from a list of all homes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random choice from a list of all homes gives every household a chance; others are self-selected or biased by location/use.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cc0d82b-c162-4509-9425-e2cc3453e59a', 'NC17.7.SP.1', 2, 'numeric', 'Use a sample to estimate for the population', 'In a random sample of 50 phones from a day''s production of 2,000 phones, 3 are faulty. Based on the sample, how many of the 2,000 phones would you predict are faulty?', '[]', '120', '2000*3/50', '3 out of 50 is $\frac{3}{50}$. Of 2,000 phones, $\frac{3}{50} \cdot 2000 = 120$.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/50 x 2000 = 120.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53a8e98f-d0f8-4ee6-ac39-9312452d6988', 'NC17.7.SP.1', 2, 'choice', 'Judge whether a generalization is valid', 'A survey of the 30 players on a school''s basketball team finds that all of them like basketball. Which conclusion about all students is valid?', '["All students at the school like basketball","Most students at the school like basketball","Half of the students at the school like basketball","This group cannot tell us about all students"]', 'This group cannot tell us about all students', NULL, 'The team members were not chosen at random and are likely to like basketball more than other students. No valid conclusion about all students can be drawn from them.', 'checked', '{"lint":[],"solve":{"answer":"This group cannot tell us about all students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Basketball team players are not representative of all students; no valid conclusion about the school.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e7e2ae0-a374-4c59-98f1-f252194f79c5', 'NC17.7.SP.1', 3, 'choice', 'Choose a random, representative sampling method', 'Which of these does NOT give every student in a school an equal chance of being chosen?', '["Drawing 40 names from a bag after mixing all the names","Using a computer to pick 40 student ID numbers at random","Asking for volunteers who raise their hands","Shuffling a card for every student and drawing 40 cards"]', 'Asking for volunteers who raise their hands', NULL, 'With volunteers, only students who choose to raise their hands can be in the sample. The other methods give every student the same chance.', 'checked', '{"lint":[],"solve":{"answer":"Asking for volunteers who raise their hands","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volunteers self-select, so not every student has an equal chance; the other three are random.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16fcd40a-0902-4d25-b944-d6a4ea9b3d2f', 'NC17.7.SP.1', 3, 'choice', 'Spot why a sample is biased', 'A manager emails a survey to all 400 employees. Only 30 reply, and most are upset. Why can''t the results be trusted for all employees?', '["Employees who replied chose themselves, unlike the rest","Surveys sent by email to employees are never allowed","A survey needs exactly half of the group to send a reply","Thirty replies are more than the whole company has staff"]', 'Employees who replied chose themselves, unlike the rest', NULL, 'The 30 who replied picked themselves, and people who are upset are often more likely to reply. They may not represent the other 370 employees.', 'checked', '{"lint":[],"solve":{"answer":"Employees who replied chose themselves, unlike the rest","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The 30 who replied chose to reply (voluntary response), so may differ from the rest.","run_id":"claude-code","at":"2026-10-24T08:22:44.525Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca7f2a1-78ea-40b3-9593-0e3edfbd05ca', 'NC17.7.SP.2', 1, 'numeric', 'Estimate a population count from a random sample', 'A factory tests a random sample of 200 light bulbs and finds that 6 are defective. About how many defective bulbs would you expect in a batch of 5,000 bulbs?', '[]', '150', '6/200*5000', '6 out of 200 is 3%. Three percent of 5,000 is 150 bulbs.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/200 = 0.03; 0.03 × 5000 = 150.","run_id":"claude-code","at":"2026-10-28T18:47:12.731Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bf32562-520d-41f7-9e52-809e20e90ffc', 'NC17.7.SP.2', 1, 'choice', 'Sample size and variation in estimates', 'Mia asks random students how many pets they have, using a sample of 15 students or a sample of 150 students. She could repeat either sample many times. Which sample would give estimates that vary less?', '["The sample of 15 students","The sample of 150 students","Both would vary by the same amount","Neither; random samples always give the same value"]', 'The sample of 150 students', NULL, 'Larger random samples give estimates that are closer together from sample to sample.', 'checked', '{"lint":[],"solve":{"answer":"The sample of 150 students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger samples vary less: 150.","run_id":"claude-code","at":"2026-10-28T18:48:28.235Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d72476-234d-477d-9690-d5eec31654cb', 'NC17.7.SP.2', 1, 'choice', 'Estimate a population percent from a random sample', 'In a random sample of 80 library visitors, 20 borrowed a book. Which is the best estimate of the percent of all visitors who borrow a book?', '["25%","20%","75%","80%"]', '25%', NULL, '20 out of 80 is 1/4, which is 25%.', 'checked', '{"lint":[],"solve":{"answer":"25%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/80 = 1/4 = 25%.","run_id":"claude-code","at":"2026-10-28T18:48:28.248Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d572d38-eb10-43a9-ba81-eaaca1c671ac', 'NC17.7.SP.2', 2, 'choice', 'Explain why random samples give different results', 'Nina takes a random sample of 30 students and finds that 18 prefer red. She says that exactly 60% of all students in the school prefer red. What is wrong with her statement?', '["Nothing is wrong, because a random sample shows the exact percent of all students","A new random sample could give a different percent, so 60% is an estimate","A percent cannot be found from a sample of only 30 students at all","The percent should be found by adding 18 and 30 and then halving it"]', 'A new random sample could give a different percent, so 60% is an estimate', NULL, 'A sample gives an estimate. A different random sample would probably give a slightly different percent.', 'checked', '{"lint":[],"solve":{"answer":"A new random sample could give a different percent, so 60% is an estimate","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/30 = 60% is a sample estimate; another random sample would vary, so it is not exact.","run_id":"claude-code","at":"2026-10-28T18:48:28.302Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('062bfb7e-4d4c-4c7e-b2a2-ea016c181f7c', 'NC17.7.SP.2', 2, 'numeric', 'Combine several random samples into one estimate', 'Four random samples of 50 students each found that 21, 24, 18 and 25 students walk to school. Use all four samples together to estimate how many of the 1,200 students in the school walk to school.', '[]', '528', '88/200*1200', 'In all, 21 + 24 + 18 + 25 = 88 of the 200 students sampled walk. That is 44%, and 44% of 1,200 is 528.', 'checked', '{"lint":[],"solve":{"answer":"528","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(21+24+18+25)/200 = 88/200 = 0.44; 0.44*1200 = 528.","run_id":"claude-code","at":"2026-10-28T18:48:28.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ec98f69-a09a-4a52-bcce-287fcc9cd27b', 'NC17.7.SP.2', 2, 'choice', 'Sample size and variation in estimates', 'Lina takes random samples of the same size to estimate a mean, and her estimates vary a lot. What could she do to make the estimates vary less?', '["Use a smaller random sample each time","Ask only students she knows well","Use a larger random sample each time","Ask the same student again and again"]', 'Use a larger random sample each time', NULL, 'Larger random samples vary less. Asking only friends, or the same student, would not be a random sample.', 'checked', '{"lint":[],"solve":{"answer":"Use a larger random sample each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples reduce variability.","run_id":"claude-code","at":"2026-10-28T18:48:28.402Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('158381ea-35f2-4061-b1cc-7dce27e6819a', 'NC17.7.SP.2', 3, 'numeric', 'Combine several random samples into one estimate', 'A random sample of 80 items had 5 defective items, and another random sample of 120 items had 9 defective items. Treat the two samples as one combined sample. Estimate how many defective items are in a shipment of 4,000 items.', '[]', '280', '14/200*4000', 'In all, 14 of the 200 sampled items are defective, which is 7%. Seven percent of 4,000 is 280 items.', 'checked', '{"lint":[],"solve":{"answer":"280","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 defective in 200 = 0.07; 0.07*4000 = 280.","run_id":"claude-code","at":"2026-10-28T18:48:28.067Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d716650-8a57-4cab-ba5c-bdc9bd472964', 'NC17.7.SP.2', 3, 'choice', 'Compare estimates from several random samples', 'Five random samples gave estimates of 12%, 18%, 15%, 14% and 16% for the percent of students who use a library card. Which statement is best supported?', '["The percent for all students is exactly 15%, the mean of the estimates","The percent for all students is probably above 18%, the largest estimate","The percent for all students is probably between 12% and 18%, near 15%","The estimates differ, so sampling cannot give useful information"]', 'The percent for all students is probably between 12% and 18%, near 15%', NULL, 'The five estimates run from 12% to 18% and their mean is 75 / 5 = 15%. They suggest a value near 15%, not an exact one.', 'checked', '{"lint":[],"solve":{"answer":"The percent for all students is probably between 12% and 18%, near 15%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Estimates vary around 15% within 12-18%; best supported: probably between 12% and 18%, near 15%.","run_id":"claude-code","at":"2026-10-28T18:48:28.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aca932c-0be1-4414-9806-e52feddd20e8', 'NC17.7.SP.3', 1, 'numeric', 'Find the range of a data set', 'The high temperatures, in degrees Fahrenheit, on 7 days in Town A were 62, 65, 68, 64, 70, 66, 67. What is the range of these temperatures?', '[]', '8', '70-62', 'The range is the greatest value minus the least value. The greatest is 70 and the least is 62, so the range is $70 - 62 = 8$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max 70, min 62, range 8.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00a15768-deef-4d56-994d-aab2c8d8480f', 'NC17.7.SP.3', 1, 'choice', 'Interpret a measure of variability', 'A data set has a small mean absolute deviation. What does that tell you?', '["The values are far from the mean on average","The mean of the data set is a small number","There are only a few values in the data set","The values are close to the mean on average"]', 'The values are close to the mean on average', NULL, 'The MAD is the average distance of the values from the mean. A small MAD means the values are, on average, close to the mean. It says nothing about how large the mean is or how many values there are.', 'checked', '{"lint":[],"solve":{"answer":"The values are close to the mean on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD is average distance from mean; small means values are close to the mean.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ac8caea-6c42-42c6-bf58-cacb6d100080', 'NC17.7.SP.3', 1, 'numeric', 'Find the interquartile range', 'Six students practiced for 3, 5, 6, 9, 11 and 14 minutes. Find the interquartile range. (The lower quartile is the median of the lowest three values and the upper quartile is the median of the highest three.)', '[]', '6', '11-5', 'The lowest three values are 3, 5, 6, with median 5, so the lower quartile is 5. The highest three are 9, 11, 14, with median 11, so the upper quartile is 11. The IQR is $11 - 5 = 6$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower three 3,5,6: Q1=5. Upper three 9,11,14: Q3=11. IQR 6.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13d00d03-69ce-4a78-9837-6441cc4eefe8', 'NC17.7.SP.3', 2, 'numeric', 'Express the difference between centers as a multiple of the variability', 'Team A''s median score is 52 and Team B''s median score is 64. The IQR of each team''s scores is 6. The difference between the medians is how many times the IQR?', '[]', '2', '(64-52)/6', 'The difference between the medians is $64 - 52 = 12$. Dividing by the IQR, $12 \div 6 = 2$. The medians are 2 IQRs apart.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64-52=12; 12/6=2.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ca6198e-81b9-4f24-9f65-8aaf5a997390', 'NC17.7.SP.3', 2, 'choice', 'Judge the visual overlap of two data sets', 'Plot A has values from 4 to 12. Plot B has values from 10 to 18. Which statement about the overlap of the two sets is true?', '["They overlap for values from 4 to 18","They overlap for values from 10 to 12","They do not overlap at all","They overlap for values from 12 to 18"]', 'They overlap for values from 10 to 12', NULL, 'Plot A covers 4 to 12 and plot B covers 10 to 18. Values that are in both ranges run from 10 (where B starts) to 12 (where A ends).', 'checked', '{"lint":[],"solve":{"answer":"They overlap for values from 10 to 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 4-12, B 10-18: common values 10 to 12.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e964fb2-aec0-4760-9854-8b0b2d11565d', 'NC17.7.SP.3', 2, 'numeric', 'Find the range of a data set', 'The range of set P is 24. Set Q has a smallest value of 11 and a largest value of 41. How much greater is the range of set Q than the range of set P?', '[]', '6', '(41-11)-24', 'The range of Q is $41 - 11 = 30$. It is greater than the range of P by $30 - 24 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q range 41-11=30; 30-24=6.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
