INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0901a449-25e4-4cbe-b361-1ec2e12d4cc6', 'NC17.7.SP.3', 3, 'numeric', 'Express the difference between centers as a multiple of the variability', 'Group B''s mean is 3 MADs greater than Group A''s mean. Both groups have a MAD of 4, and Group B''s mean is 78. What is Group A''s mean?', '[]', '66', '78-3*4', 'The means are 3 MADs apart, and one MAD is 4, so the difference between the means is $3 \times 4 = 12$. Group A''s mean is less, so it is $78 - 12 = 66$.', 'checked', '{"lint":[],"solve":{"answer":"66","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 MADs = 12. A mean = 78-12 = 66.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29e4aa20-1f7c-44fe-8c52-93e2c6689cf3', 'NC17.7.SP.3', 3, 'choice', 'Express the difference between centers as a multiple of the variability', 'Classes X and Y have means 70 and 76, and each has a MAD of 3. Classes Z and W have means 70 and 72, and each has a MAD of 8. Which statement is true?', '["The means of X and Y are 6 MADs apart, and those of Z and W are 2 MADs apart","The means of X and Y are 2 MADs apart, and those of Z and W are 0.25 MADs apart","The means of X and Y are 2 MADs apart, and those of Z and W are 4 MADs apart","The means of X and Y are 0.5 MADs apart, and those of Z and W are 4 MADs apart"]', 'The means of X and Y are 2 MADs apart, and those of Z and W are 0.25 MADs apart', NULL, 'Divide each difference between means by the MAD. X and Y: $(76 - 70) \div 3 = 2$ MADs. Z and W: $(72 - 70) \div 8 = 0.25$ MADs. The first pair of classes is much further apart compared with its variability.', 'checked', '{"lint":[],"solve":{"answer":"The means of X and Y are 2 MADs apart, and those of Z and W are 0.25 MADs apart","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X,Y: 6/3=2 MADs. Z,W: 2/8=0.25 MADs.","run_id":"claude-code","at":"2026-10-24T08:33:09.847Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ea0a7fa-0b60-42da-87dd-1edb45cf745d', 'NC17.7.SP.4', 1, 'choice', 'Compare the medians of two samples', 'Random samples of students in two groups recorded their daily reading time. The median for Group P''s sample is 25 minutes, and the median for Group Q''s sample is 18 minutes. Which statement best compares the groups'' typical reading times?', '["Group P''s typical time is greater, by 43 minutes.","Group Q''s typical time is greater, by 7 minutes.","Group P''s typical time is greater, by 7 minutes.","Group P''s typical time is greater, by 3.5 minutes."]', 'Group P''s typical time is greater, by 7 minutes.', NULL, 'The median is the typical value. 25 is greater than 18, so Group P is higher, and 25 - 18 = 7 minutes.', 'checked', '{"lint":[],"solve":{"answer":"Group P''s typical time is greater, by 7 minutes.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians 25 and 18; P greater by 25-18=7.","run_id":"claude-code","at":"2026-10-24T08:31:18.454Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26e76a01-399c-4b81-b5c8-63c95479e725', 'NC17.7.SP.4', 1, 'choice', 'Compare the variability of two samples', 'Two random samples show the points a player scored in 5 games. Player A: 10, 10, 11, 10, 9. Player B: 2, 18, 10, 6, 14. Both samples have a mean of 10. Which statement is true?', '["Player B''s scores vary more, because they are farther from 10.","Player A''s scores vary more, because they are farther from 10.","The scores vary equally, because both means are 10.","Player A''s scores vary more, because 10 appears most often."]', 'Player B''s scores vary more, because they are farther from 10.', NULL, 'Player A''s scores are all within 1 of 10. Player B''s scores are as far as 8 from 10. Equal means do not mean equal spread. Player B varies more.', 'checked', '{"lint":[],"solve":{"answer":"Player B''s scores vary more, because they are farther from 10.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A deviations from 10: 0,0,1,0,1. B: 8,8,0,4,4. B is more spread.","run_id":"claude-code","at":"2026-10-24T08:31:18.454Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('317f7d24-4fe8-48e5-acf2-000f69af1b0a', 'NC17.7.SP.4', 1, 'choice', 'Draw an informal inference about two populations', 'A random sample of 30 seventh graders from School X had a mean of 8.5 hours of sleep a night. A random sample of 30 seventh graders from School Y had a mean of 7.5 hours. Which statement is best supported?', '["Every seventh grader at School X sleeps 1 hour more than every seventh grader at School Y.","Seventh graders at School X probably sleep about 1 hour more, on average, than those at School Y.","Seventh graders at School Y probably sleep about 1 hour more, on average, than those at School X.","Seventh graders at School X probably sleep about 16 hours more, on average, than those at School Y."]', 'Seventh graders at School X probably sleep about 1 hour more, on average, than those at School Y.', NULL, 'The sample means differ by 8.5 - 7.5 = 1 hour, with School X higher. Random samples support a statement about the averages of the populations, not about every student.', 'checked', '{"lint":[],"solve":{"answer":"Seventh graders at School X probably sleep about 1 hour more, on average, than those at School Y.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sample means differ by 8.5-7.5=1; random samples support a probable difference of about 1 hour on average, not every student.","run_id":"claude-code","at":"2026-10-24T08:31:18.454Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35eba1d6-039d-4e35-9369-27cbe7cfba27', 'NC17.7.SP.4', 2, 'numeric', 'Compare the means of two samples', 'Random samples of plant heights in centimeters. Plant food A: 14, 18, 16, 20, 19, 21. Plant food B: 12, 15, 11, 16, 13, 17. How many centimeters taller is the mean height in the sample for food A than in the sample for food B?', '[]', '4', '(14+18+16+20+19+21)/6-(12+15+11+16+13+17)/6', 'Food A: 108 / 6 = 18. Food B: 84 / 6 = 14. The difference is 18 - 14 = 4 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 14+18+16+20+19+21=108, mean 18. B: 12+15+11+16+13+17=84, mean 14. 18-14=4.","run_id":"claude-code","at":"2026-10-24T08:31:18.454Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33c7b707-7b70-47f0-beed-b72e0c121a87', 'NC17.7.SP.4', 2, 'numeric', 'Compare the medians of two samples', 'Random samples of the number of sit-ups students did in one minute. Class A: 23, 18, 27, 21, 25, 19, 24. Class B: 15, 22, 17, 20, 14, 19, 21. How many more sit-ups is the median of Class A''s sample than the median of Class B''s sample?', '[]', '4', '23-19', 'In order, Class A: 18, 19, 21, 23, 24, 25, 27, so the median is 23. Class B: 14, 15, 17, 19, 20, 21, 22, so the median is 19. The difference is 23 - 19 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sorted 18,19,21,23,24,25,27: median 23. B sorted 14,15,17,19,20,21,22: median 19. 23-19=4.","run_id":"claude-code","at":"2026-10-24T08:31:18.454Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2adff2f0-5183-4022-bef5-d9faf8ba77be', 'NC17.7.SP.4', 2, 'numeric', 'Compare the IQRs of two samples', 'Random samples of the minutes students spent on a game one evening. Sample 1: 2, 6, 8, 10, 14, 18, 22, 30. Sample 2: 9, 10, 12, 13, 15, 16, 18, 19. Find each quartile as the median of the lower half or the upper half of the 8 values. How much greater is the IQR of Sample 1 than the IQR of Sample 2?', '[]', '7', '13-6', 'Sample 1: the lower half is 2, 6, 8, 10 with median 7, and the upper half is 14, 18, 22, 30 with median 20, so the IQR is $20 - 7 = 13$. Sample 2: the lower half is 9, 10, 12, 13 with median 11, and the upper half is 15, 16, 18, 19 with median 17, so the IQR is $17 - 11 = 6$. The difference is $13 - 6 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sample 1: lower 2,6,8,10 Q1=7; upper 14,18,22,30 Q3=20; IQR 13. Sample 2: lower 9,10,12,13 Q1=11; upper 15,16,18,19 Q3=17; IQR 6. 13 - 6 = 7.","run_id":"claude-code","at":"2026-10-24T08:46:20.286Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28ba11fe-52fe-4d93-9373-559952dab11e', 'NC17.7.SP.4', 3, 'numeric', 'Compare the difference in means with the MAD', 'Sample A: 5, 7, 9, 11. Sample B: 13, 15, 17, 19. The two samples have the same MAD. The difference between the means is how many times that MAD?', '[]', '4', '(16-8)/((3+1+1+3)/4)', 'Mean of A: 32 / 4 = 8. Mean of B: 64 / 4 = 16. Distances from the mean in A: 3, 1, 1, 3, so the MAD is 8 / 4 = 2. The difference in means is 16 - 8 = 8, and 8 / 2 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A mean 8, distances 3,1,1,3, MAD 2. B mean 16, MAD 2. Difference 8; 8/2=4.","run_id":"claude-code","at":"2026-10-24T08:31:18.454Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('261c240c-2004-407f-957a-c64fad4d59ea', 'NC17.7.SP.4', 3, 'numeric', 'Compare the means of two samples', 'Random samples of 5 daily step counts, in thousands, for two people. Person A: 20, 18, 22, 19, 21. Person B: 15, 17, 16, 18, 19. The value 32 is added to Person B''s sample. How much greater is the mean of Person A''s sample than the mean of Person B''s new sample?', '[]', '0.5', '(20+18+22+19+21)/5-(15+17+16+18+19+32)/6', 'Person A: 100 / 5 = 20. Person B with 32 added: 85 + 32 = 117, and 117 / 6 = 19.5. The difference is 20 - 19.5 = 0.5.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 20+18+22+19+21=100, mean 20. B new: 15+17+16+18+19+32=117 over 6 values, mean 19.5. 20-19.5=0.5.","run_id":"claude-code","at":"2026-10-24T08:31:18.454Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b2a867c-1b44-4a5c-bcc9-366be15e6b03', 'NC17.7.SP.5', 1, 'choice', 'Describe an event from its probability', 'Which word describes an event with a probability of 0?', '["certain","unlikely","likely","impossible"]', 'impossible', NULL, 'A probability of 0 means the event can never happen. That is impossible.', 'checked', '{"lint":[],"solve":{"answer":"impossible","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Probability 0 means impossible.","run_id":"claude-code","at":"2026-10-24T08:30:46.199Z"}}', 'ai', NULL, NULL)
