INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('567ec5c9-9f48-4f16-9a93-2bb38e0b4b6a', 'NC17.7.SP.5', 1, 'numeric', 'Find a probability from equally likely outcomes', 'A spinner has 5 equal sections. 2 of the sections are shaded. What is the probability that the spinner lands on a shaded section?', '[]', '2/5', '2/5', 'All 5 sections are equally likely and 2 are shaded, so the probability is $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 of 5 equal sections: 2/5.","run_id":"claude-code","at":"2026-10-24T08:30:46.199Z"}}', 'ai', NULL, NULL)
