INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60e2f184-b8cc-43c4-bf0e-2bf09e67467c', 'NC17.7.SP.5', 2, 'numeric', 'Choose a number that can be a probability', 'How many of these numbers could be the probability of an event? $0.4$, $1.2$, $-0.3$, $\frac{7}{5}$, $\frac{1}{8}$, $1$, $0$', '[]', '4', '4', 'A probability is from 0 to 1, including 0 and 1. These fit: 0.4, $\frac{1}{8}$, 1 and 0. The numbers 1.2 and $\frac{7}{5}$ are greater than 1, and -0.3 is less than 0. So 4 numbers could be probabilities.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Valid: 0.4, 1/8, 1, 0. Invalid: 1.2, -0.3, 7/5. Count 4.","run_id":"claude-code","at":"2026-10-24T08:30:46.199Z"}}', 'ai', NULL, NULL)
