INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('595abef8-0546-43f1-b27d-a6d5e241a7a0', 'NC17.7.SP.5', 2, 'choice', 'Find a probability from equally likely outcomes', 'A spinner has 8 equal sections. 7 of them are shaded. Which description of landing on a shaded section is correct?', '["Likely, with probability $\\frac{7}{8}$","Unlikely, with probability $\\frac{1}{8}$","Certain, with probability $1$","Neither likely nor unlikely, with probability $\\frac{1}{2}$"]', 'Likely, with probability $\frac{7}{8}$', NULL, 'The probability is $\frac{7}{8}$, which is close to 1. So landing on a shaded section is likely but not certain.', 'checked', '{"lint":[],"solve":{"answer":"Likely, with probability $\\frac{7}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 near 1: likely.","run_id":"claude-code","at":"2026-10-24T08:30:46.199Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d039989-9431-4cea-ba2e-6e38beeb86e0', 'NC17.7.SP.5', 2, 'numeric', 'Choose a number that can be a probability', 'The number $\frac{n}{6}$ is the probability of an event, where n is a whole number. What is the greatest possible value of n?', '[]', '6', '6', 'A probability cannot be greater than 1. $\frac{n}{6}$ is at most 1 when n is at most 6. So the greatest n is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n/6 <= 1 so n <= 6; greatest 6.","run_id":"claude-code","at":"2026-10-24T08:30:46.199Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('184858a9-92b9-46be-b35d-1e0f7c9bbaf6', 'NC17.7.SP.5', 3, 'choice', 'Compare and order probabilities', 'Which of these probabilities belongs to the most likely event?', '["$0.6$","$\\frac{7}{12}$","$0.62$","$\\frac{5}{8}$"]', '$\frac{5}{8}$', NULL, 'As decimals the numbers are 0.625, 0.6, about 0.583 and 0.62. The greatest is 0.625, which is $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.62, 5/8=0.625, 7/12~0.583, 0.6. Largest 5/8.","run_id":"claude-code","at":"2026-10-24T08:30:46.199Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aa6dfb3-6142-4e6e-9b3a-5f1fa914c52e', 'NC17.7.SP.5', 3, 'numeric', 'Compare and order probabilities', 'How many of these probabilities are greater than $\frac{1}{2}$? $0.55$, $\frac{3}{8}$, $\frac{7}{10}$, $0.5$, $\frac{4}{9}$, $0.99$', '[]', '3', '3', 'Compare each with 0.5. 0.55, 0.7 and 0.99 are greater. $\frac{3}{8}$ = 0.375 and $\frac{4}{9}$ is about 0.44 are less, and 0.5 is equal. So 3 are greater.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.55 yes, 3/8 no, 0.7 yes, 0.5 no, 4/9 no, 0.99 yes: 3.","run_id":"claude-code","at":"2026-10-24T08:30:46.199Z"}}', 'ai', NULL, NULL)
