INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21b8b616-2db9-445d-aaa4-28c3ce2a49f5', 'NC17.7.SP.6', 1, 'numeric', 'predicting a count from experimental probability', 'In a long experiment, a spinner landed on blue $\frac{1}{4}$ of the time. If the spinner is spun 80 more times, about how many times would you predict it to land on blue?', '[]', '20', '1/4*80', 'Predicted number = 1/4 of 80 = 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 of 80 = 20.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
