INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31f25cd6-d615-41c6-a466-9d0f9c55e268', 'NC17.7.SP.6', 1, 'numeric', 'experimental probability from a table or list of outcomes', 'A paper cup was tossed 25 times. It landed on its side 15 times, upside down 6 times and upright 4 times. What is the experimental probability that the cup lands upright? Write your answer as a decimal.', '[]', '0.16', '4/25', 'The cup landed upright 4 times out of 25: 4/25 = 0.16.', 'checked', '{"lint":[],"solve":{"answer":"0.16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Upright 4 of 25: 4/25 = 0.16.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
