INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28a00249-865f-4255-b304-231d8ea55f6d', 'NC17.7.SP.6', 1, 'numeric', 'experimental probability from a count', 'A coin was flipped 8 times. The results, in order, were H, T, T, H, T, H, T, T. What is the experimental probability of getting heads? Write your answer as a fraction.', '[]', '3/8', '3/8', 'Heads came up 3 times in 8 flips, so the experimental probability is 3/8.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heads at flips 1, 4, 6: 3 of 8, so 3/8.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
