INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d3e2374-267b-4fad-81f9-49f475667064', 'NC17.7.SP.6', 2, 'numeric', 'working backward to find trials or successes', 'A spinner landed on yellow 18 times. This was an experimental probability of 0.3 for yellow. How many times was the spinner spun?', '[]', '60', '18/0.3', 'Number of spins x 0.3 = 18, so the number of spins is 18 / 0.3 = 60.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 / 0.3 = 60 spins.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
