INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6faf38de-f859-47d7-94b9-399940e185c4', 'NC17.7.SP.6', 2, 'numeric', 'experimental probability from a table or list of outcomes', 'A spinner with three colors was spun 40 times. It landed on red 14 times, on blue 18 times and on green 8 times. What is the experimental probability that it lands on red or green? Write your answer as a fraction.', '[]', '11/20', '22/40', 'Red or green happened 14 + 8 = 22 times in 40 spins: 22/40 = 11/20.', 'checked', '{"lint":[],"solve":{"answer":"11/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red or green = 14 + 8 = 22 of 40 = 11/20.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
