INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82f13ee7-e010-440f-83a1-879efcec4f10', 'NC17.7.SP.6', 2, 'choice', 'predicting a count from experimental probability', 'In a survey, 20 of 80 students said they walk to school. At a school with 600 students, about how many students would you predict walk to school?', '["150","450","30","2,400"]', '150', '20/80*600', 'The experimental probability is 20/80 = 1/4. Then 1/4 of 600 = 150.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/80 = 1/4; 600/4 = 150.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16b2af7f-51f4-4104-bdbd-c396e242f67c', 'NC17.7.SP.6', 3, 'numeric', 'predicting in a multi-step problem', 'A spinner has sections A, B and C. In 60 spins it landed on A 24 times and on B 15 times; all the other spins landed on C. Based on these results, how many times would you predict the spinner to land on C in 200 spins?', '[]', '70', '(60-24-15)/60*200', 'C came up 60 - 24 - 15 = 21 times in 60 spins, so its experimental probability is 21/60 = 7/20. Then 7/20 of 200 = 70.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 60 - 24 - 15 = 21; 21/60 = 0.35; 0.35 x 200 = 70.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0915c86b-94d0-4451-9b38-e391dfe025f7', 'NC17.7.SP.6', 3, 'choice', 'comparing and matching experimental probabilities', 'Which set of results gives an experimental probability of $\frac{2}{5}$?', '["The event happened 15 times in 25 trials.","The event happened 14 times in 21 trials.","The event happened 14 times in 35 trials.","The event happened 25 times in 40 trials."]', 'The event happened 14 times in 35 trials.', NULL, '14/35 = 2/5. The others give 15/25 = 3/5, 14/21 = 2/3 and 25/40 = 5/8.', 'checked', '{"lint":[],"solve":{"answer":"The event happened 14 times in 35 trials.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/35 = 2/5. Others: 14/21 = 2/3, 15/25 = 3/5, 25/40 = 5/8.","run_id":"claude-code","at":"2026-10-24T08:32:51.864Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28331c84-9d45-4d37-a934-9cc555154ce8', 'NC17.7.SP.7', 1, 'numeric', 'Find a missing probability in a model', 'A spinner can land on red, blue or green. The probability of red is 0.3 and the probability of blue is 0.5. What is the probability of green?', '[]', '0.2', '1-0.3-0.5', 'The probabilities in a model add up to 1. So green is $1 - 0.3 - 0.5 = 0.2$.', 'checked', '{"lint":[],"solve":{"answer":"0.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 0.3 - 0.5 = 0.2.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
