INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a32bff4-300a-4f74-8236-7b89fe0abe7f', 'NC17.7.SP.7', 1, 'numeric', 'Find a relative frequency', 'Sam flips a coin 20 times and gets 12 heads. What is the relative frequency of heads?', '[]', '3/5', '12/20', 'The relative frequency is the number of heads divided by the number of flips: $\frac{12}{20} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"0.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/20 = 0.6.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2960ecd0-02e4-4afa-8bfd-f54fa4547080', 'NC17.7.SP.7', 1, 'choice', 'Recognize a uniform or valid probability model', 'Which list of numbers could be the probabilities of outcomes A, B, C and D in a probability model?', '["0.2, 0.3, 0.4, 0.5","0.1, 0.2, 0.3, 0.4","0.4, 0.3, 0.3, 0.1","0.6, 0.3, 0.2, -0.1"]', '0.1, 0.2, 0.3, 0.4', NULL, 'The probabilities must each be between 0 and 1 and add up to 1. Only 0.1 + 0.2 + 0.3 + 0.4 = 1 with no negative number. The others add to more than 1, or include a negative probability.', 'checked', '{"lint":[],"solve":{"answer":"0.1, 0.2, 0.3, 0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sums: 1.1, 1.4, has a negative, 1.0. Only 0.1, 0.2, 0.3, 0.4 is valid.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44cf3431-bb93-418e-b70e-0415b5adcb7e', 'NC17.7.SP.7', 2, 'choice', 'Compare an observed frequency with the model probability', 'A fair number cube is rolled 60 times, and a 4 lands 14 times. How does the relative frequency of a 4 compare with the model probability of a 4?', '["The relative frequency is $\\frac{14}{60}$, which is lower than the model probability of $\\frac{1}{6}$","The relative frequency is $\\frac{14}{6}$, which is higher than the model probability of $\\frac{1}{6}$","The relative frequency is $\\frac{14}{60}$, which is equal to the model probability of $\\frac{1}{6}$","The relative frequency is $\\frac{14}{60}$, which is higher than the model probability of $\\frac{1}{6}$"]', 'The relative frequency is $\frac{14}{60}$, which is higher than the model probability of $\frac{1}{6}$', NULL, 'The relative frequency is $\frac{14}{60} \approx 0.233$. The model probability is $\frac{1}{6} \approx 0.167$. So the relative frequency is higher.', 'checked', '{"lint":[],"solve":{"answer":"The relative frequency is $\\frac{14}{60}$, which is higher than the model probability of $\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/60 vs 1/6 = 10/60: 14/60 is higher.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0541e8ce-71cd-4fe1-9850-dd4c75befa8d', 'NC17.7.SP.7', 2, 'numeric', 'Predict how often an outcome will occur', 'A weighted coin lands heads with probability 0.6. How many heads should you predict in 150 flips?', '[]', '90', '0.6*150', 'Predict the probability times the number of flips: $0.6 \times 150 = 90$ heads.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6 * 150 = 90.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
