INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a9aa337-b176-46f5-b78e-28f3598b848f', 'NC17.7.SP.7', 2, 'numeric', 'Predict how often an outcome will occur', 'A fair number cube is rolled 90 times. How many times should you predict a 5 or a 6?', '[]', '30', '90*2/6', 'The probability of a 5 or a 6 is $\frac{2}{6} = \frac{1}{3}$. So predict $\frac{1}{3} \times 90 = 30$ times.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(5 or 6) = 1/3; 90/3 = 30.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
