INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2985e046-eb75-46ef-b081-ed3e8d55c0da', 'NC17.7.SP.7', 3, 'numeric', 'Estimate a probability from observed frequencies', 'In 50 draws with replacement from a bag of 20 marbles, a red marble was drawn 15 times. Use the relative frequency to estimate how many of the 20 marbles are red.', '[]', '6', '15/50*20', 'The estimated probability of red is $\frac{15}{50} = 0.3$. So about $0.3 \times 20 = 6$ marbles are red.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/50 = 0.3; 0.3 * 20 = 6.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
