INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1efacac3-459c-4442-abc4-8562864939d8', 'NC17.7.SP.7', 3, 'numeric', 'Compare an observed frequency with the model probability', 'A spinner has 5 equal sections. It is spun 120 times and section 3 lands 36 times. By how much does the relative frequency of section 3 exceed the model probability of section 3? Write a decimal.', '[]', '0.1', '36/120-1/5', 'The relative frequency is $\frac{36}{120} = 0.3$. The model probability is $\frac{1}{5} = 0.2$. The difference is $0.3 - 0.2 = 0.1$.', 'checked', '{"lint":[],"solve":{"answer":"0.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36/120 = 0.3; model 1/5 = 0.2; difference 0.1.","run_id":"claude-code","at":"2026-10-24T08:31:33.600Z"}}', 'ai', NULL, NULL)
