VALUES ('3c1fb693-810b-4e74-aacc-2e0591273752', 'NC17.7.SP.8', 1, 'numeric', 'Count the outcomes of a compound event', 'A coin is flipped two times. How many different outcomes are possible?', '[]', '4', '2*2', 'List them: heads-heads, heads-tails, tails-heads, tails-tails. That is 4 outcomes.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HH, HT, TH, TT: 4.","run_id":"claude-code","at":"2026-10-24T08:35:45.836Z"}}', 'ai', NULL, NULL)
