INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('300dbeb9-9bb8-4ac0-8674-88fa417abc72', 'NC17.7.SP.8', 1, 'numeric', 'Probability from a list of coin outcomes', 'A coin is flipped two times. What is the probability that it lands heads both times?', '[]', '1/4', '1/4', 'The 4 equally likely outcomes are HH, HT, TH and TT. Only HH is heads both times, so the probability is $\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 1/2 = 1/4.","run_id":"claude-code","at":"2026-10-24T08:35:45.836Z"}}', 'ai', NULL, NULL)
