INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72decd07-b62e-49e0-b8fb-148989e5ee69', 'NC17.7.SP.8', 2, 'choice', 'Probability from a table of two spinners', 'A fair spinner has 4 equal sections numbered 1 to 4. It is spun two times and the numbers are added. What is the probability that the sum is 5?', '["$\\frac{3}{16}$","$\\frac{1}{4}$","$\\frac{5}{16}$","$\\frac{7}{16}$"]', '$\frac{1}{4}$', NULL, 'There are 4 × 4 = 16 equally likely outcomes. The sums of 5 are 1+4, 2+3, 3+2 and 4+1, which is 4 outcomes. The probability is $\frac{4}{16} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 5: (1,4),(2,3),(3,2),(4,1) = 4/16 = 1/4.","run_id":"claude-code","at":"2026-10-24T08:35:45.836Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('966193ba-5950-4ea6-8767-e149626dd9e1', 'NC17.7.SP.8', 2, 'numeric', 'Probability from a list of coin outcomes', 'A fair coin is flipped three times. What is the probability that at least one flip is tails?', '[]', '7/8', '1-1/8', 'Of the 8 equally likely outcomes, only HHH has no tails. So 7 of the 8 outcomes have at least one tail, and the probability is $\frac{7}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"7/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - P(HHH) = 1 - 1/8 = 7/8.","run_id":"claude-code","at":"2026-10-24T08:35:45.836Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('246bfeba-ae60-4193-be4a-a5914d30d8df', 'NC17.7.SP.8', 2, 'numeric', 'Probability from a table of two spinners', 'Spinner A has three equal sections numbered 1, 2 and 3. Spinner B also has three equal sections numbered 1, 2 and 3. Each is spun once and the two numbers are added. What is the probability that the sum is even?', '[]', '5/9', '5/9', 'There are 9 equally likely pairs. An even sum comes from 1+1, 1+3, 2+2, 3+1 and 3+3, which is 5 pairs. The probability is $\frac{5}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"5/9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 outcomes; even sums: (1,1),(1,3),(2,2),(3,1),(3,3) = 5. 5/9.","run_id":"claude-code","at":"2026-10-24T08:35:45.836Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29e0b5c1-4e7a-4df9-9417-d89321fa9eff', 'NC17.7.SP.8', 3, 'choice', 'Probability of stages in a tree diagram', 'A bag has 3 green marbles and 2 yellow marbles. Two marbles are drawn one after the other, without putting the first one back. What is the probability that the two marbles are different colors?', '["$\\frac{3}{5}$","$\\frac{12}{25}$","$\\frac{3}{10}$","$\\frac{6}{25}$"]', '$\frac{3}{5}$', NULL, 'Green then yellow: $\frac{3}{5} \times \frac{2}{4} = \frac{3}{10}$. Yellow then green: $\frac{2}{5} \times \frac{3}{4} = \frac{3}{10}$. Add the two paths: $\frac{3}{10} + \frac{3}{10} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GY: 3/5 x 2/4 = 6/20; YG: 2/5 x 3/4 = 6/20; total 12/20 = 3/5.","run_id":"claude-code","at":"2026-10-24T08:35:45.836Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c7b4d28-1edf-43ca-92c2-fb153facabc4', 'NC17.7.SP.8', 3, 'numeric', 'Count the outcomes of a compound event', 'A code has one letter chosen from A, B, C or D, followed by two digits. Each digit is chosen from 1, 2 or 3, and a digit may be used twice. How many different codes are possible?', '[]', '36', '4*3*3', 'There are 4 choices for the letter, 3 for the first digit and 3 for the second digit: 4 × 3 × 3 = 36 codes.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 letters x 3 x 3 digits = 36.","run_id":"claude-code","at":"2026-10-24T08:35:45.836Z"}}', 'ai', NULL, NULL)
