VALUES ('12364302-1d7a-486a-b15c-7d735df03eea', 'NC17.8.NS.1', 1, 'numeric', 'Writing a fraction as a decimal', 'Write $\frac{3}{4}$ as a decimal.', '[]', '0.75', '3/4', 'Divide 3 by 4: $3 \div 4 = 0.75$.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 0.75.","run_id":"claude-code","at":"2026-10-24T02:58:36.464Z"}}', 'ai', NULL, NULL)
