VALUES ('008cc9f5-d13d-479c-b179-ed5b2bc2ea4d', 'NC17.8.NS.1', 1, 'numeric', 'Square roots: perfect squares and irrational roots', 'The square root of 144 is a rational number. What whole number is $\sqrt{144}$?', '[]', '12', '12', '$12 \times 12 = 144$, so $\sqrt{144} = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 × 12 = 144, so √144 = 12.","run_id":"claude-code","at":"2026-10-28T18:48:28.012Z"}}', 'ai', NULL, NULL)
