INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0269c07b-8814-4705-a6bd-99e544644d3f', 'NC17.8.NS.1', 1, 'choice', 'Telling rational from irrational numbers', 'Which statement about $\sqrt{36}$ is correct?', '["It is irrational, because it has a square root sign","It is rational, because $\\sqrt{36} = 6$","It is irrational, because 36 is even","It is rational, because 36 is not a perfect square"]', 'It is rational, because $\sqrt{36} = 6$', NULL, '36 is a perfect square, $6 \times 6 = 36$, so $\sqrt{36} = 6$, a whole number. Whole numbers are rational.', 'checked', '{"lint":[],"solve":{"answer":"It is rational, because $\\sqrt{36} = 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(36) = 6 = 6/1, rational.","run_id":"claude-code","at":"2026-10-28T18:48:28.525Z"}}', 'ai', NULL, NULL)
