INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b7e41e5-fa98-45c6-80ea-bf246602d8fa', 'NC17.8.NS.1', 2, 'numeric', 'Method for converting a repeating decimal', 'Let $x = 0.1818...$ with the digits 18 repeating forever. What is the value of $100x - x$?', '[]', '18', '18', 'Here $100x = 18.1818...$ and $x = 0.1818...$. Subtracting, the repeating parts cancel and $99x = 18$, so $100x - x = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100x = 18.1818..., x = 0.1818..., 100x - x = 18.","run_id":"claude-code","at":"2026-10-24T02:58:36.464Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10b1679b-3c5c-4739-94dd-04f6309b96f9', 'NC17.8.NS.1', 2, 'choice', 'Terminating or repeating decimals', 'Marcus says $\frac{3}{12}$ has a repeating decimal because 12 has a factor of 3. Is he right?', '["No, since $\\frac{3}{12} = \\frac{1}{4} = 0.25$, which ends","Yes, since 12 has a factor of 3, every fraction with 12 on the bottom repeats","No, since every fraction with an even number on the bottom ends","Yes, since $3 \\div 12 = 0.333\\ldots$"]', 'No, since $\frac{3}{12} = \frac{1}{4} = 0.25$, which ends', NULL, '$\frac{3}{12}$ simplifies to $\frac{1}{4}$, and $1 \div 4 = 0.25$ ends. Simplify first before deciding.', 'checked', '{"lint":[],"solve":{"answer":"No, since $\\frac{3}{12} = \\frac{1}{4} = 0.25$, which ends","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/12 = 1/4 = 0.25, terminates. Option D is false (1/6 repeats).","run_id":"claude-code","at":"2026-10-28T18:48:27.863Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
