INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14781c46-06f3-4bb9-a709-375a7fef4db3', 'NC17.8.NS.1', 3, 'choice', 'Square roots: perfect squares and irrational roots', 'A square has an area of exactly 50 square units. Mia says its side length is exactly 7.07 units. Which is correct?', '["Yes, because 7.07 times 7.07 equals exactly 50","Yes, because every side length can be written as a decimal","No, because the side length is exactly 7.5 units","No, the side length is irrational, so 7.07 is only close to it"]', 'No, the side length is irrational, so 7.07 is only close to it', NULL, 'The side is $\sqrt{50}$, which is irrational because 50 is not a perfect square, so no decimal that ends is exactly equal to it. Also $7.07 \times 7.07 = 49.9849$, not 50, and $7.5 \times 7.5 = 56.25$.', 'checked', '{"lint":[],"solve":{"answer":"No, the side length is irrational, so 7.07 is only close to it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side = sqrt50, irrational; 7.07^2 = 49.9849, not 50. 7.5^2 = 56.25. So D.","run_id":"claude-code","at":"2026-10-24T02:58:36.464Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0953d7cb-de24-4bfd-ae6d-77aa3dac5045', 'NC17.8.NS.1', 3, 'numeric', 'Writing a repeating decimal as a fraction', 'Write $0.0888\ldots$, where only the digit 8 repeats forever, as a fraction in lowest terms.', '[]', '4/45', '8/90', 'Let $x = 0.0888\ldots$. Then $100x - 10x = 8.888\ldots - 0.888\ldots = 8$, so $90x = 8$ and $x = \frac{8}{90} = \frac{4}{45}$.', 'checked', '{"lint":[],"solve":{"answer":"4/45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 0.0888…; 10x = 0.888… = 8/9, so x = 8/90 = 4/45.","run_id":"claude-code","at":"2026-10-28T18:47:12.766Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('077eb86f-6d21-4a1d-963b-6ff085edb28a', 'NC17.8.NS.2', 1, 'numeric', 'Locate an irrational number on the number line', 'A number line has a mark at every whole number. Which mark is closest to the point for $-\sqrt{8}$?', '[]', '-3', NULL, '$\sqrt{8}$ is about 2.83, so $-\sqrt{8}$ is about $-2.83$. The closest whole-number mark is $-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt8 ~ 2.83 (2.8^2 = 7.84, 2.9^2 = 8.41), so -sqrt8 ~ -2.83; nearest mark -3.","run_id":"claude-code","at":"2026-10-28T19:16:32.232Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02578299-7ae8-4eaf-b824-6771663a8663', 'NC17.8.NS.2', 1, 'numeric', 'Estimate a square root to the nearest whole number', 'Rounded to the nearest whole number, what is $\sqrt{37}$?', '[]', '6', NULL, '$6^2 = 36$ and $7^2 = 49$. 37 is very close to 36, so $\sqrt{37}$ is about 6.1, which rounds to 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 < 37 < 49; sqrt37 ~ 6.08, rounds to 6.","run_id":"claude-code","at":"2026-10-28T19:16:32.290Z"}}', 'ai', NULL, NULL)
