INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ecc554f-6d0f-461c-92d7-dd7f45bfc9cb', 'NC17.8.NS.2', 1, 'numeric', 'Estimate cube roots', 'The cube root of 20 is between two consecutive whole numbers. What is the larger of the two?', '[]', '3', NULL, '$2^3 = 8$ and $3^3 = 27$. Since 20 is between 8 and 27, its cube root is between 2 and 3. The larger is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8 < 20 < 27 = 3^3, so between 2 and 3; larger is 3.","run_id":"claude-code","at":"2026-10-28T19:16:32.413Z"}}', 'ai', NULL, NULL)
