INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe22017-61b0-47d7-aaff-3013fbb7e4f9', 'NC17.8.NS.2', 2, 'choice', 'Estimate a root to the nearest tenth', 'Which decimal is the best approximation of $\sqrt{40}$?', '["6.3","6.1","6.5","6.7"]', '6.3', NULL, '$6.3^2 = 39.69$, which is very close to 40. $6.1^2 = 37.21$, $6.5^2 = 42.25$ and $6.7^2 = 44.89$ are farther away.', 'checked', '{"lint":[],"solve":{"answer":"6.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6.3^2 = 39.69, 6.35^2 = 40.32; sqrt40 ~ 6.32, best is 6.3.","run_id":"claude-code","at":"2026-10-24T02:59:10.503Z"}}', 'ai', NULL, NULL)
