INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e32aea2-c30a-452f-a47a-727669d50639', 'NC17.8.NS.2', 2, 'numeric', 'Estimate pi and compare approximations of pi', 'A circular pizza has a diameter of 12 inches. Using 3.14 for $\pi$, how many inches is the distance around its edge? (The distance around is $\pi$ times the diameter.)', '[]', '37.68', '3.14*12', '$3.14 \times 12 = 37.68$ inches.', 'checked', '{"lint":[],"solve":{"answer":"37.68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x 12 = 37.68.","run_id":"claude-code","at":"2026-10-28T19:16:32.076Z"}}', 'ai', NULL, NULL)
