INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d4e05be-d7d8-441c-b2c8-486544a6794a', 'NC17.8.NS.2', 2, 'choice', 'Estimate cube roots', 'Between which two consecutive whole numbers is the cube root of 400?', '["7 and 8","6 and 7","8 and 9","133 and 134"]', '7 and 8', NULL, '$7^3 = 343$ and $8^3 = 512$. Since 400 is between them, its cube root is between 7 and 8.', 'checked', '{"lint":[],"solve":{"answer":"7 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^3=343 < 400 < 512=8^3.","run_id":"claude-code","at":"2026-10-28T19:16:32.308Z"}}', 'ai', NULL, NULL)
