INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('017dbddd-2588-46f7-8815-1e560bcfba81', 'NC17.8.NS.2', 3, 'choice', 'Estimate pi and compare approximations of pi', 'Which list puts $\sqrt{10}$, $3.14$, $\frac{22}{7}$ and $\pi$ in order from least to greatest?', '["$3.14$, $\\frac{22}{7}$, $\\pi$, $\\sqrt{10}$","$\\pi$, $3.14$, $\\frac{22}{7}$, $\\sqrt{10}$","$3.14$, $\\pi$, $\\frac{22}{7}$, $\\sqrt{10}$","$3.14$, $\\pi$, $\\sqrt{10}$, $\\frac{22}{7}$"]', '$3.14$, $\pi$, $\frac{22}{7}$, $\sqrt{10}$', NULL, '$3.14 = 3.14$, $\pi \approx 3.1416$, $\frac{22}{7} \approx 3.1429$ and $\sqrt{10} \approx 3.1623$. That is the order from least to greatest.', 'checked', '{"lint":[],"solve":{"answer":"$3.14$, $\\pi$, $\\frac{22}{7}$, $\\sqrt{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 < pi (3.14159) < 22/7 (3.142857) < sqrt10 (3.1623).","run_id":"claude-code","at":"2026-10-28T19:16:32.147Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16192df5-0814-482c-a1d8-88ffd283c3cd', 'NC17.8.NS.2', 3, 'choice', 'Order numbers that include roots', 'Which list puts $\sqrt{10}$, $3.1$ and $\frac{19}{6}$ in order from least to greatest?', '["$3.1$, $\\frac{19}{6}$, $\\sqrt{10}$","$\\sqrt{10}$, $3.1$, $\\frac{19}{6}$","$\\frac{19}{6}$, $\\sqrt{10}$, $3.1$","$3.1$, $\\sqrt{10}$, $\\frac{19}{6}$"]', '$3.1$, $\sqrt{10}$, $\frac{19}{6}$', NULL, '$\sqrt{10}$ is about 3.162, $3.1$ is 3.1 and $\frac{19}{6}$ is about 3.167. Order: 3.1, $\sqrt{10}$, $\frac{19}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$3.1$, $\\sqrt{10}$, $\\frac{19}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.1; sqrt(10) is about 3.1623; 19/6 is about 3.1667. Least to greatest: 3.1, sqrt(10), 19/6.","run_id":"claude-code","at":"2026-10-28T19:16:32.489Z"}}', 'ai', NULL, NULL)
