INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1663c2a1-124a-4d47-b5a0-61206d3d3555', 'NC17.8.EE.1', 1, 'choice', 'product of powers', 'Which is equal to $2^3 \cdot 2^4$?', '["$2^{12}$","$4^7$","$2^7$","$2^1$"]', '$2^7$', NULL, 'Same base, so add the exponents: $2^3 \cdot 2^4 = 2^{3+4} = 2^7$. Multiplying the exponents (12), multiplying the bases (4) or subtracting (1) are common mistakes.', 'checked', '{"lint":[],"solve":{"answer":"$2^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 x 2^4 = 2^(3+4) = 2^7.","run_id":"claude-code","at":"2026-10-28T19:16:32.121Z"}}', 'ai', NULL, NULL)
