VALUES ('0bf79125-903e-4583-9f7a-db9e34b6e157', 'NC17.8.EE.1', 2, 'choice', 'negative exponent', 'Which expression is equal to $\frac{1}{4^3}$?', '["$4^3$","$3^{-4}$","$(-4)^3$","$4^{-3}$"]', '$4^{-3}$', NULL, 'The reciprocal of $4^3$ is $4^{-3}$, since $4^{-3} = \frac{1}{4^3}$.', 'checked', '{"lint":[],"solve":{"answer":"$4^{-3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4^3 = 4^-3.","run_id":"claude-code","at":"2026-10-24T02:58:26.596Z"}}', 'ai', NULL, NULL)
