INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a4d1c23-6c15-4d24-b6e2-6f68ff80b984', 'NC17.8.EE.1', 2, 'numeric', 'power of a product or quotient', 'Find the value of $\frac{2^{3} \cdot 5^{2}}{10^{2}}$.', '[]', '2', '2^3*5^2/10^2', 'Since $10^2 = 2^2 \cdot 5^2$, the fraction is $\frac{2^3 \cdot 5^2}{2^2 \cdot 5^2} = 2^{1} = 2$. (Or: $\frac{8 \cdot 25}{100} = 2$.)', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 x 5^2 = 8 x 25 = 200; 10^2 = 100; 200/100 = 2.","run_id":"claude-code","at":"2026-10-28T19:16:32.107Z"}}', 'ai', NULL, NULL)
