INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('055a081c-e466-440a-93b4-3ed256794738', 'NC17.8.EE.1', 2, 'choice', 'compare numbers with exponents', 'Which statement is true?', '["$2^{-3} > 2^{-2}$","$3^{-1} < 3^{-2}$","$4^{-1} < 4^{0}$","$5^{0} = 5$"]', '$4^{-1} < 4^{0}$', NULL, '$4^{-1} = \frac{1}{4}$ and $4^0 = 1$, so $4^{-1} < 4^0$. The others are false: $\frac{1}{8} < \frac{1}{4}$, $\frac{1}{3} > \frac{1}{9}$ and $5^0 = 1$.', 'checked', '{"lint":[],"solve":{"answer":"$4^{-1} < 4^{0}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^{-1} = 1/4 < 1 true. 1/8 > 1/4 false; 5^0 = 1 not 5; 1/3 < 1/9 false.","run_id":"claude-code","at":"2026-10-28T19:16:32.247Z"}}', 'ai', NULL, NULL)
