INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16a0ef38-c3aa-4414-a816-4338a357b5b5', 'NC17.8.EE.1', 3, 'numeric', 'missing exponent', '$\frac{2^n}{2^{-3}} = 2^{7}$. What is $n$?', '[]', '4', '7-3', 'Dividing subtracts the exponents: $n - (-3) = 7$, so $n + 3 = 7$ and $n = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n - (-3) = 7, so n + 3 = 7, n = 4.","run_id":"claude-code","at":"2026-10-24T02:58:26.596Z"}}', 'ai', NULL, NULL)
