VALUES ('2502bc40-5010-49ca-b115-d23816a7c762', 'NC17.8.EE.1', 3, 'numeric', 'simplify a numerical expression with integer exponents', 'Write $\frac{9^{2} \cdot 27}{3^{4}}$ as a whole number.', '[]', '27', '9^2*27/3^4', '$9^2 = 3^4$, so the $3^4$ cancels and what is left is $27$. (Check: $\frac{81 \cdot 27}{81} = 27$.)', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9^2 = 3^4, so 3^4 x 27 / 3^4 = 27.","run_id":"claude-code","at":"2026-10-28T19:16:32.254Z"}}', 'ai', NULL, NULL)
