INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00a05bd0-7b46-40cb-ab86-2edc994b3675', 'NC17.8.EE.2', 1, 'choice', 'Solve x^2 = p using a square root symbol', 'Which equation has $x = \sqrt{7}$ as a solution?', '["$x^2 = 49$","$x^3 = 7$","$2x = 7$","$x^2 = 7$"]', '$x^2 = 7$', NULL, 'The square root of 7 is the number that gives 7 when squared: $(\sqrt{7})^2 = 7$. So $x^2 = 7$ has $\sqrt{7}$ as a solution.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 = 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(sqrt7)^2 = 7, so x^2 = 7. Others: (sqrt7)^3 = 7sqrt7, x^2=49 needs 7, 2x=7 needs 3.5.","run_id":"claude-code","at":"2026-10-28T19:20:44.237Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07aeefaa-9dde-4e64-a7ae-b1f7d95c735f', 'NC17.8.EE.2', 1, 'choice', 'Use square and cube roots in a context', 'A square has an area of 36 square units. Which expression gives the length of one side?', '["$36^2$","$36 \\div 2$","$36 \\div 4$","$\\sqrt{36}$"]', '$\sqrt{36}$', NULL, 'The side length is the number that gives 36 when multiplied by itself, which is $\sqrt{36} = 6$. Dividing 36 by 2 or by 4 does not undo a multiplication of the side by itself.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{36}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side s with s^2 = 36: s = sqrt36 = 6.","run_id":"claude-code","at":"2026-10-28T19:20:44.359Z"}}', 'ai', NULL, NULL)
