VALUES ('052eac79-b825-4feb-9acd-a23891cc10fa', 'NC17.8.EE.2', 1, 'numeric', 'Solve x^2 = p using a square root symbol', 'Find the positive value of $x$ that solves $x^2 = 400$.', '[]', '20', '20', '$20 \times 20 = 400$, so the positive solution is $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = sqrt400 = 20.","run_id":"claude-code","at":"2026-10-28T19:20:44.363Z"}}', 'ai', NULL, NULL)
