INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4c6ea4-36ae-48fb-b024-035becba3bc1', 'NC17.8.EE.2', 2, 'choice', 'Solve x^2 = p using a square root symbol', 'Maya solves $x^2 = 13$. Which statement describes her solutions?', '["Two solutions, $\\sqrt{13}$ and $-\\sqrt{13}$","Only one solution, $\\sqrt{13}$","Two solutions, $\\frac{13}{2}$ and $-\\frac{13}{2}$","Two solutions, $169$ and $-169$"]', 'Two solutions, $\sqrt{13}$ and $-\sqrt{13}$', NULL, 'Both $\sqrt{13}$ and $-\sqrt{13}$ give 13 when squared, and 13 is not a perfect square, so the exact solutions are $\sqrt{13}$ and $-\sqrt{13}$.', 'checked', '{"lint":[],"solve":{"answer":"Two solutions, $\\sqrt{13}$ and $-\\sqrt{13}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = 13 gives x = sqrt(13) or x = -sqrt(13).","run_id":"claude-code","at":"2026-10-28T19:20:44.209Z"}}', 'ai', NULL, NULL)
