INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('034879a3-f12b-4222-84dd-ceca625a0cbb', 'NC17.8.EE.2', 3, 'choice', 'Roots undo squaring and cubing', 'Which equation is true for every positive number $a$?', '["$\\sqrt{a} = a^2$","$\\sqrt{a^2} = 2a$","$\\sqrt{a} = \\frac{a}{2}$","$(\\sqrt{a})^2 = a$"]', '$(\sqrt{a})^2 = a$', NULL, 'The square root of $a$ is the number that gives $a$ when squared, so $(\sqrt{a})^2 = a$. Try $a = 9$ in the others: $\sqrt{9} = 3$ is not $9^2$, and $\sqrt{9^2} = 9$ is not 18, and $\frac{9}{2}$ is not 3.', 'checked', '{"lint":[],"solve":{"answer":"$(\\sqrt{a})^2 = a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(sqrt a)^2 = a for a>0. Others fail e.g. a=4: sqrt4=2≠16; sqrt16=4≠8; 2≠2? a=4: sqrt4=2=4/2 holds but fails for a=9.","run_id":"claude-code","at":"2026-10-28T19:20:44.390Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09cd6a14-08ec-4183-9798-2f741c5abce4', 'NC17.8.EE.3', 1, 'numeric', 'Write a small number in scientific notation', 'The number 0.0003 can be written as $3 \times 10^{n}$. What is $n$?', '[]', '-4', NULL, 'The 3 is in the fourth place after the decimal point, so 0.0003 is $3 \times 10^{-4}$ and $n = -4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.0003 = 3*10^-4.","run_id":"claude-code","at":"2026-10-24T03:04:03.116Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05cd70a7-50a7-43e9-80cc-9ba35179562d', 'NC17.8.EE.3', 1, 'numeric', 'Write a large number in scientific notation', 'A city has about $2 \times 10^{6}$ people. Write this number of people as a whole number with no commas.', '[]', '2000000', '2*10^6', '$10^{6}$ is 1,000,000, so $2 \times 10^{6} = 2{,}000{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"2000000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*10^6 = 2000000.","run_id":"claude-code","at":"2026-10-24T03:04:03.116Z"}}', 'ai', NULL, NULL)
