INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0afdb9f4-c48a-4622-82ce-8f1aa3014e45', 'NC17.8.EE.3', 1, 'choice', 'Compare two quantities: how many times as large', 'Planet A is about $3 \times 10^{8}$ meters across. Planet B is about $3 \times 10^{6}$ meters across. Which statement is true?', '["Planet B is about 100 times as wide as Planet A.","Planet A is about 2 times as wide as Planet B.","Planet A is about 10 times as wide as Planet B.","Planet A is about 100 times as wide as Planet B."]', 'Planet A is about 100 times as wide as Planet B.', NULL, 'The digits match, so compare the powers of ten: $\frac{10^{8}}{10^{6}} = 10^{2} = 100$. Planet A is 100 times as wide.', 'checked', '{"lint":[],"solve":{"answer":"Planet A is about 100 times as wide as Planet B.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x10^8 / 3x10^6 = 100.","run_id":"claude-code","at":"2026-10-28T19:24:07.727Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b4e6d4f-1750-492c-b2bc-7adfb3831d7e', 'NC17.8.EE.3', 2, 'numeric', 'Solve a problem about a very large quantity', 'A hard drive stores $4 \times 10^{12}$ bytes. One song uses about $4 \times 10^{6}$ bytes. The drive can hold about $1 \times 10^{n}$ songs. What is $n$?', '[]', '6', '12-6', 'Divide: $\frac{4 \times 10^{12}}{4 \times 10^{6}} = 10^{6}$. So $n = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4×10^12 ÷ 4×10^6 = 1×10^6; n = 6.","run_id":"claude-code","at":"2026-10-28T19:24:07.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d57c4c4-0528-40ea-b1d1-87a78fd211d8', 'NC17.8.EE.3', 2, 'numeric', 'Compare two quantities: how many times as large', 'A grain of sand has a mass of about $6 \times 10^{-4}$ gram. A pebble has a mass of about $3 \times 10^{-1}$ gram. How many times as heavy as the sand grain is the pebble?', '[]', '500', '3*10^-1/(6*10^-4)', 'Divide: $\frac{3 \times 10^{-1}}{6 \times 10^{-4}} = 0.5 \times 10^{3} = 500$.', 'checked', '{"lint":[],"solve":{"answer":"500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3×10^-1 ÷ 6×10^-4 = 0.5 × 10^3 = 500.","run_id":"claude-code","at":"2026-10-28T19:24:07.665Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09af1f0e-cc51-4736-b5db-9f1d077c7583', 'NC17.8.EE.3', 2, 'choice', 'Estimate a quantity as one digit times a power of ten', 'A county has 3,862,000 residents. A city in it has 41,500 residents. Rounding each number to one digit times a power of ten, about how many times as many residents does the county have as the city?', '["10","1000","100","1"]', '100', '4*10^6/(4*10^4)', 'Round: $3{,}862{,}000 \approx 4 \times 10^{6}$ and $41{,}500 \approx 4 \times 10^{4}$. Then $\frac{4 \times 10^{6}}{4 \times 10^{4}} = 10^{2} = 100$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,862,000 about 4x10^6; 41,500 about 4x10^4; ratio 10^2=100.","run_id":"claude-code","at":"2026-10-28T19:24:07.726Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09123f99-5e7d-431c-bc10-57a70abe7dfc', 'NC17.8.EE.3', 3, 'choice', 'Compare two quantities: how many times as large', 'Town A has about $2.9 \times 10^{5}$ people. Town B has about $6.1 \times 10^{3}$ people. About how many times as many people live in Town A as in Town B?', '["5","500","5000","50"]', '50', NULL, 'Estimate with $3 \times 10^{5}$ and $6 \times 10^{3}$: $\frac{3 \times 10^{5}}{6 \times 10^{3}} = 0.5 \times 10^{2} = 50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"290,000/6,100 ~ 47.5, about 50 (or 3*10^5/6*10^3 = 50).","run_id":"claude-code","at":"2026-10-24T03:04:03.116Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b7fc7a5-e448-4cee-a0d2-a0968545c138', 'NC17.8.EE.3', 3, 'choice', 'Estimate a quantity as one digit times a power of ten', 'A day has 24 hours, an hour has 60 minutes and a minute has 60 seconds. Which is the best estimate, in scientific notation, of the number of seconds in one day?', '["$4 \\times 10^{3}$","$9 \\times 10^{4}$","$9 \\times 10^{5}$","$1 \\times 10^{3}$"]', '$9 \times 10^{4}$', NULL, '$24 \times 60 \times 60 = 86{,}400$, which is close to 90,000, or $9 \times 10^{4}$. ($4 \times 10^{3}$ is about the seconds in one hour and $1 \times 10^{3}$ is about the minutes in a day.)', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 10^{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24*3600=86,400 ~ 9*10^4.","run_id":"claude-code","at":"2026-10-24T03:04:03.116Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3283e254-f1f2-469a-ab9a-21a4d0ded9fb', 'NC17.8.EE.4', 1, 'choice', 'Multiply in scientific notation', 'What is $(2 \times 10^{3})(3 \times 10^{4})$ in scientific notation?', '["$6 \\times 10^{12}$","$5 \\times 10^{7}$","$6 \\times 10^{7}$","$6 \\times 10^{1}$"]', '$6 \times 10^{7}$', NULL, 'Multiply the coefficients: $2 \times 3 = 6$. Add the exponents of 10: $3 + 4 = 7$. The product is $6 \times 10^{7}$. Multiplying the exponents (12), adding the coefficients (5) or subtracting the exponents (1) are the common slips.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 10^{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*3=6; 10^(3+4)=10^7. Product 6 x 10^7.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d29cf96-9358-4e9c-9f27-bdddc89cb686', 'NC17.8.EE.4', 1, 'numeric', 'Mix decimal and scientific forms', 'Multiply $(3 \times 10^{2})(2 \times 10^{3})$. Write the answer as a whole number in standard form, with no commas.', '[]', '600000', '(3*10^2)*(2*10^3)', '$3 \times 2 = 6$ and $10^2 \times 10^3 = 10^5$, so the product is $6 \times 10^5 = 600000$.', 'checked', '{"lint":[],"solve":{"answer":"600000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*2=6; 10^(2+3)=10^5. 6 x 10^5 = 600000.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2895a748-1cee-4f90-a6c9-83c13b62ac99', 'NC17.8.EE.4', 1, 'choice', 'Multiply in scientific notation', 'Which product is equal to $6 \times 10^8$?', '["$(2 \\times 10^{4})(3 \\times 10^{2})$","$(2 \\times 10^{5})(3 \\times 10^{4})$","$(2 \\times 10^{4})(3 \\times 10^{4})$","$(2 \\times 10^{2})(3 \\times 10^{2})$"]', '$(2 \times 10^{4})(3 \times 10^{4})$', NULL, 'Each product has coefficient $2 \times 3 = 6$. The exponents must add to 8, and only $4 + 4$ does. The others give $10^6$, $10^9$ and $10^4$.', 'checked', '{"lint":[],"solve":{"answer":"$(2 \\times 10^{4})(3 \\times 10^{4})$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6 x 10^9. B: 6 x 10^8. C: 6 x 10^6. D: 6 x 10^4. Only B equals 6 x 10^8.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('221246ce-1c5c-4411-98c2-8b9c58d3ddc7', 'NC17.8.EE.4', 2, 'numeric', 'Mix decimal and scientific forms', 'What is $0.05 \times (4 \times 10^6)$? Write the answer as a whole number in standard form, with no commas.', '[]', '200000', '0.05*4*10^6', '$4 \times 10^6 = 4000000$, and $0.05 \times 4000000 = 200000$. Or: $0.05 = 5 \times 10^{-2}$, so the product is $20 \times 10^4 = 200000$.', 'checked', '{"lint":[],"solve":{"answer":"200000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.05*4=0.2; 0.2 x 10^6 = 200000.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d56d748-0592-4dd1-83f9-4a2fe0efd964', 'NC17.8.EE.4', 2, 'choice', 'Solve a multiplication problem with scientific notation', 'A computer does $2.5 \times 10^9$ operations every second. How many operations does it do in $4 \times 10^2$ seconds? Give the answer in scientific notation.', '["$1 \\times 10^{12}$","$1 \\times 10^{11}$","$6.5 \\times 10^{11}$","$1 \\times 10^{18}$"]', '$1 \times 10^{12}$', NULL, '$2.5 \times 4 = 10$ and $9 + 2 = 11$, so the product is $10 \times 10^{11}$. Rewrite with a coefficient between 1 and 10: $1 \times 10^{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$1 \\times 10^{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5*4=10; 10^(9+2)=10^11. 10 x 10^11 = 1 x 10^12.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16fcac5d-16ee-493a-861f-12e917f3b768', 'NC17.8.EE.4', 2, 'numeric', 'Multiply in scientific notation', '$(6 \times 10^{-3})(4 \times 10^{-5})$ = $2.4 \times 10^n$. What is $n$?', '[]', '-7', '-3+-5+1', '$6 \times 4 = 24$ and $-3 + (-5) = -8$, so the product is $24 \times 10^{-8}$. Rewrite as $2.4 \times 10^{-7}$. So $n = -7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*4=24; 10^(-3-5)=10^-8. 24 x 10^-8 = 2.4 x 10^-7. n=-7.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44fda981-e441-49ac-b12e-bae7d882154d', 'NC17.8.EE.4', 3, 'numeric', 'Mix decimal and scientific forms', 'Find $(2.5 \times 10^{-3})$ $\times$ $40000$. Write the answer as a whole number.', '[]', '100', '2.5*10^(-3)*40000', '$40000 = 4 \times 10^4$. Then $2.5 \times 4 = 10$ and $-3 + 4 = 1$, so the product is $10 \times 10^1 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40000 = 4 x 10^4. 2.5*4 = 10; 10^(-3+4)=10^1. 10 x 10 = 100.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
