INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1be52d91-e6e8-42bc-8afe-c64c843c50aa', 'NC17.8.EE.4', 3, 'choice', 'Solve a multiplication problem with scientific notation', 'A country has $3 \times 10^8$ people. Each person uses $1.5 \times 10^2$ liters of water a day. How many liters does the whole country use in a day, in scientific notation?', '["$4.5 \\times 10^{10}$","$4.5 \\times 10^{6}$","$4.5 \\times 10^{16}$","$4.5 \\times 10^{9}$"]', '$4.5 \times 10^{10}$', NULL, '$3 \times 1.5 = 4.5$ and $8 + 2 = 10$, so the total is $4.5 \times 10^{10}$ liters.', 'checked', '{"lint":[],"solve":{"answer":"$4.5 \\times 10^{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*1.5=4.5; 10^(8+2)=10^10. 4.5 x 10^10 liters.","run_id":"claude-code","at":"2026-10-24T03:06:48.963Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1978b8d6-77b5-47df-a0ee-b7c14acf0aa4', 'NC17.8.EE.7', 1, 'numeric', 'Solve equations with variables on both sides', 'Solve $5x + 3 = 2x + 12$. What is $x$?', '[]', '3', '(12-3)/(5-2)', 'Subtract $2x$ from both sides: $3x + 3 = 12$. Subtract 3: $3x = 9$. Divide by 3: $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 2x = 12 - 3, 3x = 9, x = 3.","run_id":"claude-code","at":"2026-10-24T03:05:55.424Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('419a4199-22e5-4380-9e03-1d30952723d5', 'NC17.8.EE.7', 1, 'choice', 'Solve equations with variables on both sides', 'What is the solution of $4x - 7 = x + 8$?', '["$x = 3$","$x = \\frac{1}{3}$","$x = -5$","$x = 5$"]', '$x = 5$', NULL, 'Subtract $x$ from both sides: $3x - 7 = 8$. Add 7: $3x = 15$. Divide by 3: $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - x = 8 + 7, 3x = 15, x = 5.","run_id":"claude-code","at":"2026-10-24T03:05:55.424Z"}}', 'ai', NULL, NULL)
