VALUES ('32a3d00d-7625-409d-9d83-49191281b30f', 'NC17.8.EE.7', 2, 'choice', 'Solve equations with parentheses', 'What is the solution of $3(2x - 1) = 4x + 9$?', '["$x = 5$","$x = 3$","$x = 6$","$x = 12$"]', '$x = 6$', NULL, 'Expand: $6x - 3 = 4x + 9$. Subtract $4x$: $2x - 3 = 9$. Add 3: $2x = 12$. Divide by 2: $x = 6$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 3 = 4x + 9, 2x = 12, x = 6.","run_id":"claude-code","at":"2026-10-24T03:05:55.424Z"}}', 'ai', NULL, NULL)
