INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a8e7517-29d4-442f-b831-52a7fbff7295', 'NC17.8.EE.7', 2, 'choice', 'Number of solutions of an equation', 'Which equation is true for every value of $x$?', '["$3(x + 2) = 3x + 5$","$3(x + 2) = x + 6$","$3(x + 2) = 3x + 2$","$3(x + 2) = 3x + 6$"]', '$3(x + 2) = 3x + 6$', NULL, 'Expand: $3(x + 2) = 3x + 6$, so the first equation is the same on both sides. The others reduce to a false statement or to one value of $x$ only.', 'checked', '{"lint":[],"solve":{"answer":"$3(x + 2) = 3x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 2) = 3x + 6, identity.","run_id":"claude-code","at":"2026-10-24T03:05:55.424Z"}}', 'ai', NULL, NULL)
