VALUES ('1551f405-ed5f-4153-bfa0-bdb4e624e35b', 'NC17.8.EE.7', 2, 'numeric', 'Solve inequalities', 'What is the greatest whole number $x$ that satisfies $5x + 3 \le 2x + 18$?', '[]', '5', '(18-3)/(5-2)', 'Subtract $2x$: $3x + 3 \le 18$. Subtract 3: $3x \le 15$. Divide by 3: $x \le 5$. The greatest whole number is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x <= 15, x <= 5; greatest whole number 5.","run_id":"claude-code","at":"2026-10-24T03:05:55.424Z"}}', 'ai', NULL, NULL)
