INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('282d8e67-0ddb-41e3-9523-e561fe4aa130', 'NC17.8.EE.7', 3, 'choice', 'Solve equations with parentheses', 'What is the solution of $5(2x - 1) = 3(3x + 4) - 2$?', '["$x = 5$","$x = 17$","$x = 15$","$x = -15$"]', '$x = 15$', NULL, 'Expand: $10x - 5 = 9x + 12 - 2$, which is $10x - 5 = 9x + 10$. Subtract $9x$: $x - 5 = 10$. Add 5: $x = 15$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x - 5 = 9x + 12 - 2 = 9x + 10, x = 15.","run_id":"claude-code","at":"2026-10-24T03:05:55.424Z"}}', 'ai', NULL, NULL)
