INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11d22723-fb83-4734-b5b1-ce50a8b043bc', 'NC17.8.F.2', 3, 'numeric', 'Comparing rates of change', 'The graph of Function A passes through $(-2, 1)$ and $(4, -8)$. Function B is $y = -0.5x + 3$. By how much is the rate of change of Function A less than the rate of change of Function B?', '[]', '1', '-0.5-(-1.5)', 'Function A''s rate is $\frac{-8 - 1}{4 - (-2)} = \frac{-9}{6} = -1.5$. Function B''s rate is $-0.5$. Then $-0.5 - (-1.5) = 1$, so A''s rate is 1 less than B''s.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A slope (-8-1)/(4+2)=-9/6=-1.5. B -0.5. -0.5-(-1.5)=1.","run_id":"claude-code","at":"2026-10-24T03:11:51.420Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04864f75-32e7-4c05-ba52-1b53066ef424', 'NC17.8.F.2', 3, 'choice', 'Rate of change from a table, points or equation', 'Which function has the same rate of change as the line through $(1, 4)$ and $(3, 10)$?', '["$y = 6x - 11$","$y = 2x - 11$","$y = \\frac{1}{3}x - 11$","$y = 3x - 11$"]', '$y = 3x - 11$', NULL, 'The rate of change is $\frac{10 - 4}{3 - 1} = 3$. Only $y = 3x - 11$ has rate of change 3. The numbers 6 and 2 are the changes in $y$ and in $x$, and $\frac{1}{3}$ is the ratio upside down.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x - 11$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (10-4)/(3-1)=3: y=3x-11.","run_id":"claude-code","at":"2026-10-24T03:11:51.420Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15b44e63-5694-4a0b-9bc0-161b18560b81', 'NC17.8.F.3', 1, 'choice', 'Identify a linear function from its equation', 'Which equation defines a linear function?', '["$y = x^2 + 2$","$y = 3x + 2$","$y = \\frac{2}{x}$","$y = x^3$"]', '$y = 3x + 2$', NULL, 'A linear function has the form $y = mx + b$. Only $y = 3x + 2$ has this form, with $m = 3$ and $b = 2$. The others have $x^2$, $x^3$ or $x$ in a denominator.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 3x + 2 is of form mx+b; others are quadratic, reciprocal, cubic.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8bd79d-4596-4694-a441-aa424e859121', 'NC17.8.F.3', 1, 'choice', 'Identify a linear function from its graph', 'The graph of a linear function is which of these?', '["A straight line","A curve shaped like a U","A curve that gets steeper","A closed loop"]', 'A straight line', NULL, 'The graph of $y = mx + b$ is always a straight line. The other shapes are graphs of functions that are not linear.', 'checked', '{"lint":[],"solve":{"answer":"A straight line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Linear function graphs as a straight line.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13979866-3564-4815-af85-ff16f0ac8148', 'NC17.8.F.3', 1, 'numeric', 'Identify a linear function from its graph', 'The points (0, 1), (1, 3) and (2, 5) lie on a straight line. What is y when x is 3?', '[]', '7', '5+2', 'Each step of 1 in x raises y by 2: 1, 3, 5, then $5 + 2 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rises 2 per unit; at x = 3, y = 7.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0121a58f-9706-430a-8068-51399a5c177e', 'NC17.8.F.3', 2, 'choice', 'Identify a linear function from its equation', 'Which equation does NOT define a linear function?', '["$y = 3(x - 2) + 1$","$y = \\frac{x}{2} + 3$","$y = 7x$","$y = x(x + 1)$"]', '$y = x(x + 1)$', NULL, 'Multiplying out, $x(x + 1) = x^2 + x$, which has an $x^2$ term. The others simplify to $y = 3x - 5$, $y = \frac{1}{2}x + 3$ and $y = 7x$, which are all of the form $y = mx + b$.', 'checked', '{"lint":[],"solve":{"answer":"$y = x(x + 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x+1) = x^2 + x, quadratic. Others linear.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22a73a15-6426-4d44-9319-636e18384922', 'NC17.8.F.3', 2, 'choice', 'Identify a linear function from a table', 'Which table shows a linear function?', '["x: 1, 2, 4, 7 and y: 5, 7, 9, 11","x: 1, 2, 4, 7 and y: 5, 7, 11, 17","x: 1, 2, 4, 7 and y: 1, 4, 16, 49","x: 1, 2, 4, 7 and y: 5, 8, 14, 20"]', 'x: 1, 2, 4, 7 and y: 5, 7, 11, 17', NULL, 'Find the change in y for each change of 1 in x. In the first table: 2 for 1 step, 4 for 2 steps, 6 for 3 steps, so y goes up 2 per step every time. In the others the rate is not constant.', 'checked', '{"lint":[],"solve":{"answer":"x: 1, 2, 4, 7 and y: 5, 7, 11, 17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unequal x steps; check rate: A: 2/1, 4/2, 6/3 all 2 -> linear. B: 2, 1, 2/3 no. C: 3, 3, 2 no. D: squares no.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bcbe93d-48c9-43a6-8a26-29280db8d4eb', 'NC17.8.F.3', 2, 'numeric', 'Identify a linear function from its graph', 'The points (1, 3), (3, 9) and (5, 15) lie on a straight line. What is y when x is 6?', '[]', '18', '3*6', 'From (1, 3) to (3, 9), y rises 6 when x rises 2, so the slope is 3. The line is $y = 3x$, and $y = 3 \times 6 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (9-3)/2 = 3; y = 3x; at x = 6, y = 18.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('221b4a34-a402-4eb2-8dba-639f2575c2c7', 'NC17.8.F.3', 3, 'choice', 'Identify a linear function from its equation', 'Which equation does NOT define a linear function of x?', '["$y = (x + 1)^2 - x^2$","$3x + 2y = 12$","$y = x(x - 3) - x^2$","$y = (x + 2)^2 - 4$"]', '$y = (x + 2)^2 - 4$', NULL, 'Expand each one. $(x + 2)^2 - 4 = x^2 + 4x$ has an $x^2$ term. But $(x + 1)^2 - x^2 = 2x + 1$ and $x(x - 3) - x^2 = -3x$ are linear, and $3x + 2y = 12$ gives $y = -1.5x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$y = (x + 2)^2 - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: y = 6 - 1.5x linear. B: 2x + 1 linear. C: x^2 + 4x not linear. D: -3x linear.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b778b7a-9fe9-4a31-8995-46f01e9b2ffd', 'NC17.8.F.3', 3, 'numeric', 'Identify a linear function from a table', 'A table for a linear function y = mx + b has x values 2, 4, 6 and 8, and y values 7, 10, 13 and 16. What is b?', '[]', '4', '7-2*(3/2)', 'y goes up 3 when x goes up 2, so $m = 1.5$. Then $7 = 1.5(2) + b$, so $b = 7 - 3 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 3/2 = 1.5; 7 = 1.5(2) + b, b = 4.","run_id":"claude-code","at":"2026-10-24T03:12:50.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('125c89a4-d4d5-4c5b-848b-0c073bc171de', 'NC17.8.F.4', 1, 'numeric', 'Interpret the y-intercept', 'A tank holds $y$ liters of water after $x$ minutes, where $y = 80 - 4x$. How many liters were in the tank at the start?', '[]', '80', '80', 'At the start, $x = 0$, so $y = 80 - 4(0) = 80$. The y-intercept 80 is the starting amount.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 0, y = 80.","run_id":"claude-code","at":"2026-10-24T03:16:03.051Z"}}', 'ai', NULL, NULL)
