INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('146c7fdb-35bf-4c7c-824c-62218c2207e1', 'NC17.8.F.4', 1, 'numeric', 'Find the rate of change from data', 'A seedling is 4 cm tall at 0 weeks and 10 cm tall at 2 weeks. If it grows at a steady rate, how many centimeters does it grow each week?', '[]', '3', '(10-4)/2', 'It grows 10 - 4 = 6 cm in 2 weeks. The rate is 6 divided by 2 = 3 cm per week.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(10 - 4)/2 = 3 cm per week.","run_id":"claude-code","at":"2026-10-24T03:16:03.051Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('097cc836-f7bb-48b5-b5e0-d3eb390d3521', 'NC17.8.F.4', 1, 'numeric', 'Solve for the input of a linear model', 'A tub has 2 liters of water. A tap adds 5 liters each minute, so $y = 5x + 2$ gives the liters after $x$ minutes. After how many minutes are there 27 liters?', '[]', '5', '(27-2)/5', 'Set $5x + 2 = 27$. Subtract 2 to get $5x = 25$, so $x = 5$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 2 = 27, 5x = 25, x = 5.","run_id":"claude-code","at":"2026-10-24T03:16:03.051Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0798a9c4-002f-4807-b132-b65d5ff6964d', 'NC17.8.F.4', 2, 'numeric', 'Predict with a linear model', 'A phone plan costs $y = 0.05x + 12$ dollars in a month with $x$ text messages. What is the cost in dollars for a month with 300 text messages?', '[]', '27', '0.05*300+12', 'Put $x = 300$ into the equation: $y = 0.05(300) + 12 = 15 + 12 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.05(300) + 12 = 15 + 12 = 27.","run_id":"claude-code","at":"2026-10-24T03:16:03.051Z"}}', 'ai', NULL, NULL)
