INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01a9cfe2-9c96-4d69-ae55-6ea484d01586', 'NC17.8.F.4', 2, 'numeric', 'Solve for the input of a linear model', 'The height of a candle is $y = 20 - 1.5x$ centimeters after $x$ hours. After how many hours is the candle 8 cm tall?', '[]', '8', '(20-8)/1.5', 'Set $20 - 1.5x = 8$. Then $1.5x = 12$, so $x = 8$ hours.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 - 1.5x = 8, 1.5x = 12, x = 8.","run_id":"claude-code","at":"2026-10-24T03:16:03.051Z"}}', 'ai', NULL, NULL)
