INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d5971e7-6847-424e-939f-b1fe9c0e85f3', 'NC17.8.F.4', 2, 'numeric', 'Find the rate of change from data', 'A bamboo plant is 18 cm tall after 2 days and 42 cm tall after 6 days. It grows at a steady rate. How many centimeters does it grow each day?', '[]', '6', '(42-18)/(6-2)', 'In $6 - 2 = 4$ days the plant grows $42 - 18 = 24$ cm. Each day it grows $24 \div 4 = 6$ cm.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate = (42 - 18)/(6 - 2) = 24/4 = 6 cm per day.","run_id":"claude-code","at":"2026-10-24T08:47:21.369Z"}}', 'ai', NULL, NULL)
