INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('237ac29c-f815-4739-a41c-bd45e0d9288b', 'NC17.8.F.4', 3, 'numeric', 'Predict with a linear model', 'The height of a sunflower seedling is modeled by $y = 0.8x + 14.5$, where $y$ is the height in centimeters and $x$ is the number of days after it was first measured. What is the height in centimeters at $x = 10$?', '[]', '22.5', '0.8*10+14.5', 'Put $x = 10$ in: $0.8(10) + 14.5 = 8 + 14.5 = 22.5$.', 'checked', '{"lint":[],"solve":{"answer":"22.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8(10) + 14.5 = 8 + 14.5 = 22.5.","run_id":"claude-code","at":"2026-10-24T03:16:03.051Z"}}', 'ai', NULL, NULL)
