INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('105fd751-bcec-4e15-8160-57d84c4b05fb', 'NC17.8.F.4', 3, 'choice', 'Write an equation from two points', 'A line crosses the y-axis at $(0, -3)$ and passes through $(2, 5)$. Which equation is the equation of the line?', '["$y = 4x + 3$","$y = 4x - 3$","$y = 5x - 3$","$y = 8x - 3$"]', '$y = 4x - 3$', NULL, 'The y-intercept is $-3$. The slope is (5 - (-3)) / (2 - 0) = 8 / 2 = 4. So $y = 4x - 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (5 - (-3))/2 = 4, intercept -3: y = 4x - 3.","run_id":"claude-code","at":"2026-10-24T03:16:03.051Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13c4e715-2474-44ae-abde-a913a578443b', 'NC17.8.F.5', 1, 'choice', 'Increasing, decreasing or constant', 'A balloon''s height is measured each minute: 2 m, 5 m, 8 m, 11 m, 14 m. How does the height change over this time?', '["It is decreasing","It is constant","It is increasing","It increases and then decreases"]', 'It is increasing', NULL, 'Each height is bigger than the one before, so the height keeps going up. It is increasing.', 'checked', '{"lint":[],"solve":{"answer":"It is increasing","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences are +3 each minute (2,5,8,11,14), so the height keeps going up.","run_id":"claude-code","at":"2026-10-24T08:19:44.028Z"}}', 'ai', NULL, NULL)
