INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04771d81-cce9-46fc-94d7-76a3e2e28f62', 'NC17.8.F.5', 1, 'choice', 'Match a story to the shape of a graph', 'Which situation is best described by a function that increases and then decreases?', '["The cost of buying more apples at one price","The pages read while reading at a steady pace","The distance covered while walking steadily","The height of a ball thrown up, until it lands"]', 'The height of a ball thrown up, until it lands', NULL, 'A ball goes up and then comes down, so its height rises and then falls. The other three keep going up the whole time.', 'checked', '{"lint":[],"solve":{"answer":"The height of a ball thrown up, until it lands","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A ball thrown up rises, then falls until it lands: increases then decreases. Others increase steadily.","run_id":"claude-code","at":"2026-10-24T08:19:44.028Z"}}', 'ai', NULL, NULL)
