INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b559e74-c3f8-46a6-89e1-a97e881298ce', 'NC17.8.F.5', 1, 'choice', 'Describe a graph as increasing, decreasing, linear or not', 'A graph is a straight line segment. It starts at height 8 on the left and ends at height 2 on the right. Which words describe the function?', '["increasing and linear","decreasing and linear","decreasing but not linear","increasing but not linear"]', 'decreasing and linear', NULL, 'The heights go down as you move to the right, so the function is decreasing. The graph is a straight line, so it is linear.', 'checked', '{"lint":[],"solve":{"answer":"decreasing and linear","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Straight segment: linear. Height goes from 8 (left) to 2 (right): decreasing.","run_id":"claude-code","at":"2026-10-24T08:47:21.369Z"}}', 'ai', NULL, NULL)
