INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('259142d6-6d26-4837-8fab-9c8daae64d6a', 'NC17.8.F.5', 2, 'choice', 'Linear or not linear from values', 'A table gives $y = 1, 5, 9, 13$ when $x = 0, 2, 4, 6$. Which statement is true?', '["Not linear: y goes up by 4 but x goes up by only 2","Not linear: x does not go up by 1 each time","Linear: y goes up by 4 every time x goes up by 2","Linear: y goes up by 4 every time x goes up by 1"]', 'Linear: y goes up by 4 every time x goes up by 2', NULL, 'Both $x$ and $y$ change by the same amount every step ($x$ by 2, $y$ by 4), so $y$ changes 2 for each 1 of $x$ all the way along. The function is linear.', 'checked', '{"lint":[],"solve":{"answer":"Linear: y goes up by 4 every time x goes up by 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y: 1,5,9,13 rises by 4 each time x rises by 2 (x-steps equal), so linear with rate 2.","run_id":"claude-code","at":"2026-10-24T08:19:44.028Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ebaebed-d31e-4ed1-9251-06cfcf921f9c', 'NC17.8.F.5', 2, 'choice', 'Match a story to the shape of a graph', 'Ben walks from home to a store at a steady pace, waits at the store, then walks home at the same steady pace. Which describes the graph of his distance from home against time?', '["It rises steadily, stays flat, then rises steadily again","It rises steadily, stays flat, then falls steadily","It rises steadily, then falls steadily, then stays flat","It stays flat, then rises steadily, then falls steadily"]', 'It rises steadily, stays flat, then falls steadily', NULL, 'Walking away: the distance rises steadily. Waiting: the distance stays the same, so the graph is flat. Walking home: the distance falls steadily.', 'checked', '{"lint":[],"solve":{"answer":"It rises steadily, stays flat, then falls steadily","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walking away steadily: distance rises steadily; waiting: flat; walking home: falls steadily back.","run_id":"claude-code","at":"2026-10-24T08:19:44.028Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('520f82c3-b57c-4c32-87ee-f8ef26708973', 'NC17.8.F.5', 2, 'choice', 'Highest point of a function', 'A function is increasing for $x$ from 0 to 4 and decreasing for $x$ from 4 to 9. Which statement about its graph is true?', '["It has its highest point at x = 4","It has its lowest point at x = 4","It is a straight line from x = 0 to x = 9","It is constant from x = 4 to x = 9"]', 'It has its highest point at x = 4', NULL, 'The graph climbs up to $x = 4$ and then goes down, so $x = 4$ is the top of the graph.', 'checked', '{"lint":[],"solve":{"answer":"It has its highest point at x = 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increasing then decreasing means the greatest value is at the turn, x=4.","run_id":"claude-code","at":"2026-10-24T08:19:44.028Z"}}', 'ai', NULL, NULL)
