INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ba8bf7d-8006-408a-9db8-cb7d2eb8ca5f', 'NC17.8.F.5', 3, 'choice', 'Match a story to the shape of a graph', 'A pool''s water level falls at a steady rate for 20 minutes, stays the same for 10 minutes, then rises at a steady rate twice as fast as the fall, for 10 minutes. Which describes the graph of water level against time?', '["A line that falls, a flat piece, then a line that rises less steeply","A line that rises, a flat piece, then a line that falls more steeply","A line that falls, a flat piece, then a line that rises more steeply","A line that falls, a line that rises more steeply, then a flat piece"]', 'A line that falls, a flat piece, then a line that rises more steeply', NULL, 'Falling: a line sloping down. Same level: a flat piece. Rising twice as fast: a line sloping up that is steeper than the first one sloped down.', 'checked', '{"lint":[],"solve":{"answer":"A line that falls, a flat piece, then a line that rises more steeply","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Falls steadily, flat for 10 min, then rises twice as fast (steeper).","run_id":"claude-code","at":"2026-10-24T08:19:44.028Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3defb0a5-7c37-42fa-b9ab-2018fc687df1', 'NC17.8.F.5', 3, 'choice', 'Compare two graphs', 'Tank A holds 10 liters and gains 5 liters every minute. Tank B holds 40 liters and loses 3 liters every minute. Which statement about the graphs of liters against minutes is true?', '["Both are straight lines that rise, but A rises faster","A is a straight line and B is a curve that falls","Both are straight lines; A rises and B falls, so they cross","Both are straight lines that fall and never cross"]', 'Both are straight lines; A rises and B falls, so they cross', NULL, 'Constant rates give straight lines. A gains water, so its line rises; B loses water, so its line falls. A starts lower and ends up higher, so the lines must cross (after 3.75 minutes).', 'checked', '{"lint":[],"solve":{"answer":"Both are straight lines; A rises and B falls, so they cross","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 10+5t, rising line; B: 40-3t, falling line. Equal at t=3.75, so they cross.","run_id":"claude-code","at":"2026-10-24T08:19:44.028Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('322a8dd7-969d-4a53-9ddf-78cf20419abe', 'NC17.8.G.2', 1, 'numeric', 'Translate a point', 'The point $(3, 4)$ is translated 2 units to the right and 5 units up. What is the y-coordinate of the image?', '[]', '9', '4+5', 'Moving 5 units up adds 5 to the y-coordinate: $4 + 5 = 9$. Moving right changes only the x-coordinate.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y: 4 + 5 = 9 (x: 3 + 2 = 5).","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05d11d28-dc49-4933-9f6e-5b695841e2a2', 'NC17.8.G.2', 1, 'numeric', 'Rotate a point', 'The point $(2, -5)$ is rotated $180^\circ$ about the origin. What is the y-coordinate of the image?', '[]', '5', '5', 'A $180^\circ$ rotation about the origin changes both signs: $(2, -5)$ becomes $(-2, 5)$. The y-coordinate is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 degrees about the origin: (x, y) -> (-x, -y), so (2, -5) -> (-2, 5). y = 5.","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bf33e5b-7b14-45aa-ba03-6b9bd3e71234', 'NC17.8.G.2', 1, 'choice', 'Lengths and angles are preserved', 'A triangle has angles of $30^\circ$, $60^\circ$ and $90^\circ$. It is translated 6 units up. What are the angles of the image?', '["$30^\\circ$, $60^\\circ$ and $90^\\circ$","$36^\\circ$, $66^\\circ$ and $96^\\circ$","$15^\\circ$, $30^\\circ$ and $45^\\circ$","$60^\\circ$, $120^\\circ$ and $180^\\circ$"]', '$30^\circ$, $60^\circ$ and $90^\circ$', NULL, 'A translation keeps every angle the same, so the image has the same angles as the original.', 'checked', '{"lint":[],"solve":{"answer":"$30^\\circ$, $60^\\circ$ and $90^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation preserves angle measures: 30, 60, 90.","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3465aa4b-3ebf-492f-a24b-ef71d4ce4e7a', 'NC17.8.G.2', 2, 'choice', 'What congruence means', 'Triangle $ABC$ is reflected across a line and then translated 6 units to the right to form triangle $DEF$. Which statement is true?', '["The triangles are not congruent, because the reflection changes the shape of the triangle.","The triangles are not congruent, because the translation moves the triangle to a new place.","The triangles are similar but not congruent, because the sizes of the triangles differ.","The triangles are congruent, because reflections and translations keep lengths and angles."]', 'The triangles are congruent, because reflections and translations keep lengths and angles.', NULL, 'Reflections and translations keep every side length and angle. The triangle only changes position and direction, so the two triangles are congruent.', 'checked', '{"lint":[],"solve":{"answer":"The triangles are congruent, because reflections and translations keep lengths and angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflections and translations are rigid motions, so DEF is congruent to ABC.","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21899334-5798-45e7-a37c-8b42c38869eb', 'NC17.8.G.2', 2, 'choice', 'Lengths and angles are preserved', 'Which of these can change when a figure is reflected across a line?', '["The length of each side of the original figure","Clockwise or counterclockwise vertex order","The measure of each angle of the original figure","The total area enclosed by the original figure"]', 'Clockwise or counterclockwise vertex order', NULL, 'A reflection keeps lengths, angles and area. It does reverse the direction in which the vertices go around the figure.', 'checked', '{"lint":[],"solve":{"answer":"Clockwise or counterclockwise vertex order","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A reflection preserves angles, area and lengths but reverses orientation (vertex order clockwise vs counterclockwise).","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ec944ef-7841-4304-a4c7-a5ec11aaa912', 'NC17.8.G.2', 2, 'choice', 'What congruence means', 'Triangle $P$ has angles of $40^\circ$, $60^\circ$ and $80^\circ$. Triangle $Q$ has the same three angles, but every side of $Q$ is twice as long as the matching side of $P$. Which statement is true?', '["They are congruent, because all three of their angles are equal, so the shapes match.","They are congruent, because the triangles have exactly the same shape as each other.","They are not congruent, because no rotation, reflection or translation changes lengths.","They are not congruent, because the angles of the two triangles are different."]', 'They are not congruent, because no rotation, reflection or translation changes lengths.', NULL, 'Rotations, reflections and translations keep side lengths, so no sequence of them can turn $P$ into the larger triangle $Q$. The triangles are not congruent.', 'checked', '{"lint":[],"solve":{"answer":"They are not congruent, because no rotation, reflection or translation changes lengths.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q has sides twice as long, so lengths differ; rigid motions preserve length, so not congruent. Angles are the same, so option D is false; A is correct.","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c8537f-ddb9-422f-827a-5e935dd67716', 'NC17.8.G.2', 3, 'choice', 'Describe a sequence that maps one figure onto another', 'Triangle $ABC$ has vertices $A(1, 1)$, $B(4, 1)$ and $C(1, 3)$. Triangle $A''B''C''$ has vertices $A''(4, 1)$, $B''(4, 4)$ and $C''(2, 1)$. Which sequence maps $ABC$ onto $A''B''C''$?', '["Rotate $90^\\circ$ counterclockwise about the origin, then translate 5 units right.","Rotate $90^\\circ$ clockwise about the origin, then translate 5 units right.","Reflect across the y-axis, then translate 5 units right.","Translate 5 units right, then rotate $90^\\circ$ counterclockwise about the origin."]', 'Rotate $90^\circ$ counterclockwise about the origin, then translate 5 units right.', NULL, 'A $90^\circ$ counterclockwise rotation sends $(x, y)$ to $(-y, x)$, giving $(-1, 1)$, $(-1, 4)$, $(-3, 1)$. Translating 5 units right gives $(4, 1)$, $(4, 4)$, $(2, 1)$. The other sequences do not give all three image vertices.', 'checked', '{"lint":[],"solve":{"answer":"Rotate $90^\\circ$ counterclockwise about the origin, then translate 5 units right.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Option C: CCW 90: (x,y)->(-y,x): A(-1,1), B(-1,4), C(-3,1); right 5: (4,1),(4,4),(2,1). Matches. B: CW gives A(1,-1)->(6,-1) no. A: B->(1,1) no. D: translate then rotate gives A(6,1)->(-1,6) no.","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c973638-7d3e-4f42-a263-93d581d4655b', 'NC17.8.G.2', 3, 'numeric', 'Translate a point', 'A translation maps $A(2, -1)$ to $A''(-3, 4)$. The same translation maps $B(0, 5)$ to $B''$. What is the y-coordinate of $B''$?', '[]', '10', '5+(4-(-1))', 'The translation moves each point 5 units left ($2$ to $-3$) and 5 units up ($-1$ to $4$). So $B(0, 5)$ becomes $B''(-5, 10)$. The y-coordinate is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation vector: (-3 - 2, 4 - (-1)) = (-5, 5). B'' = (0 - 5, 5 + 5) = (-5, 10). y = 10.","run_id":"claude-code","at":"2026-10-24T08:22:44.635Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20029471-9a2b-458d-9fc6-5d68e0737413', 'NC17.8.G.3', 1, 'choice', 'Translate a point or figure', 'The point $(5, 1)$ is translated 3 units down. What are the coordinates of the new point?', '["$(8, 1)$","$(5, 4)$","$(5, -2)$","$(2, 1)$"]', '$(5, -2)$', NULL, 'Moving down subtracts from the y-coordinate and leaves the x-coordinate alone: $(5, 1 - 3) = (5, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Down 3 subtracts 3 from y: (5, 1-3) = (5, -2).","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
