INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41f582a9-5f67-4ff7-a786-1fe31998d1ec', 'NC17.8.G.3', 1, 'choice', 'Reflect across an axis', 'The point $(3, 5)$ is reflected across the x-axis. What are the coordinates of its image?', '["$(-3, 5)$","$(-3, -5)$","$(5, 3)$","$(3, -5)$"]', '$(3, -5)$', NULL, 'A reflection across the x-axis keeps the x-coordinate and changes the sign of the y-coordinate: $(3, -5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, -5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across x-axis: (x,y)->(x,-y): (3,-5).","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
