INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42f2d2f4-cc93-490f-acf1-19b897940c31', 'NC17.8.G.3', 1, 'choice', 'Describe a transformation from coordinates', 'A point moves from $(2, 3)$ to $(2, -3)$. Which transformation does this?', '["A reflection across the y-axis","A translation 3 units down","A rotation of 90$^\\circ$ counterclockwise about the origin","A reflection across the x-axis"]', 'A reflection across the x-axis', NULL, 'The x-coordinate stayed the same and the y-coordinate changed sign, which is a reflection across the x-axis. Moving 3 units down would give $(2, 0)$.', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the x-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x same, y negated: reflection across x-axis. Check others: y-axis gives (-2,3); 90 ccw gives (-3,2); down 3 gives (2,0).","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
