INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50ac5e15-aeda-44b5-9cbf-ee40842a2f1a', 'NC17.8.G.3', 2, 'numeric', 'Translate a point or figure', 'A rectangle has vertices $(1, 1)$, $(5, 1)$, $(5, 3)$ and $(1, 3)$. It is translated 6 units left and 2 units up. What is the x-coordinate of the image of $(5, 1)$?', '[]', '-1', '5-6', 'Moving left subtracts from x: $5 - 6 = -1$. (The image of that vertex is $(-1, 3)$.)', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5,1) -> (5-6, 1+2) = (-1,3). x = -1.","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
