INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14d85a74-7ecf-4ea0-a65d-ad363161e765', 'NC17.8.G.3', 2, 'choice', 'Reflect across an axis', 'A figure is reflected across the y-axis. Which statement is true about the coordinates of every point?', '["Both coordinates change sign","The y-coordinate changes sign and the x-coordinate stays the same","The x- and y-coordinates swap places","The x-coordinate changes sign and the y-coordinate stays the same"]', 'The x-coordinate changes sign and the y-coordinate stays the same', NULL, 'Across the y-axis, a point $(x, y)$ goes to $(-x, y)$: only the x-coordinate changes sign.', 'checked', '{"lint":[],"solve":{"answer":"The x-coordinate changes sign and the y-coordinate stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across y-axis: (x,y)->(-x,y).","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
