INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('374d1aaf-5b84-40de-ad4d-dad99cff70cd', 'NC17.8.G.3', 2, 'choice', 'Dilate from the origin', 'A triangle is dilated by a scale factor of 2 with the origin as the center. Which statement is true about the image?', '["Each side is 2 times as long and the angle measures stay the same","Each side stays the same length and the angle measures are doubled","Each side is 2 times as long and the angle measures are doubled","Each side and each angle measure stays the same"]', 'Each side is 2 times as long and the angle measures stay the same', NULL, 'A dilation changes the size of a figure by the scale factor but keeps its shape, so lengths are multiplied by 2 and angle measures do not change.', 'checked', '{"lint":[],"solve":{"answer":"Each side is 2 times as long and the angle measures stay the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilation scales lengths by 2, preserves angles.","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e7f53f0-5b51-4a97-a574-99454d0a14ce', 'NC17.8.G.3', 3, 'choice', 'Describe a transformation from coordinates', 'A rotation about the origin maps $(-4, 1)$ to $(-1, -4)$. Which rotation is it?', '["A rotation of 90$^\\circ$ clockwise","A rotation of 90$^\\circ$ counterclockwise","A rotation of 180$^\\circ$","A reflection across the x-axis"]', 'A rotation of 90$^\circ$ counterclockwise', NULL, 'A 90$^\circ$ counterclockwise rotation sends $(x, y)$ to $(-y, x)$, and $(-4, 1)$ goes to $(-1, -4)$. A clockwise rotation would give $(1, 4)$; 180$^\circ$ would give $(4, -1)$.', 'checked', '{"lint":[],"solve":{"answer":"A rotation of 90$^\\circ$ counterclockwise","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 ccw: (x,y)->(-y,x): (-4,1)->(-1,-4). Matches. 90 cw gives (1,4); 180 gives (4,-1); x-axis reflection gives (-4,-1).","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('588e66c9-10b5-4917-88d7-38615c06e7cf', 'NC17.8.G.3', 3, 'numeric', 'Rotate about the origin', 'A rotation of 90$^\circ$ counterclockwise about the origin maps point P to $(-3, 8)$. What is the x-coordinate of P?', '[]', '8', '8', 'The rotation sends $(x, y)$ to $(-y, x)$. So $-y = -3$ and $x = 8$, which means $y = 3$. P is $(8, 3)$ and its x-coordinate is $8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 ccw: (x,y)->(-y,x) = (-3,8), so -y=-3, x=8. P=(8,3). x = 8.","run_id":"claude-code","at":"2026-10-24T08:22:44.414Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('090ec098-6edd-4022-8136-cb6bb88b0180', 'NC17.8.G.4', 1, 'numeric', 'Find or use a scale factor', 'A triangle has a side that is 4 centimeters long. The triangle is dilated by a scale factor of 3. How long, in centimeters, is the matching side of the image?', '[]', '12', '4*3', 'Each length is multiplied by the scale factor: $4 \cdot 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3 = 12.","run_id":"claude-code","at":"2026-10-24T08:22:44.561Z"}}', 'ai', NULL, NULL)
