INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aff6afb-586d-4687-ad22-a322b9fbd4eb', 'NC17.8.G.4', 1, 'numeric', 'Lengths in a dilated figure', 'A square has sides 3 units long. It is dilated by a scale factor of 2 about the origin. What is the perimeter of the image, in units?', '[]', '24', '4*3*2', 'Each side of the image is $3 \cdot 2 = 6$ units long. A square has 4 sides, so the perimeter is $4 \cdot 6 = 24$ units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image side 6; perimeter 4 x 6 = 24.","run_id":"claude-code","at":"2026-10-24T08:22:44.561Z"}}', 'ai', NULL, NULL)
