INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b12ca91-af7b-4fa9-b07e-68eb3eb8c7dc', 'NC17.8.G.7', 1, 'numeric', 'Find a leg in a real-world problem', 'A rectangular picture frame has a diagonal of 17 inches and a short side of 8 inches. How long is the long side, in inches?', '[]', '15', '(17^2-8^2)/15', 'The diagonal splits the rectangle into right triangles with the diagonal as the hypotenuse. Long side squared = 17^2 - 8^2 = 289 - 64 = 225, so the long side is 15 inches.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(289-64)=sqrt225=15.","run_id":"claude-code","at":"2026-10-24T08:31:18.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('063219a7-a879-42a4-852b-bfb64fadcaac', 'NC17.8.G.7', 1, 'choice', 'Find a hypotenuse in a real-world problem', 'Nia walks 3 blocks east and then 4 blocks north. How many blocks is she from where she started, in a straight line?', '["7","12","5","25"]', '5', '(3^2+4^2)/5', 'The two walks are the legs of a right triangle and the straight line is the hypotenuse. 3^2 + 4^2 = 9 + 16 = 25, and the square root of 25 is 5 blocks.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(9+16)=5.","run_id":"claude-code","at":"2026-10-24T08:31:18.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56ec4c8c-d833-4cea-93c0-3aa55518e7c3', 'NC17.8.G.7', 2, 'numeric', 'Find a hypotenuse in a real-world problem', 'A rectangular TV screen is 24 inches wide and 18 inches tall. A screen''s size is the length of its diagonal. What is this screen''s size, in inches?', '[]', '30', '(24^2+18^2)/30', 'The diagonal is the hypotenuse of a right triangle with legs 24 and 18. 24^2 + 18^2 = 576 + 324 = 900, and the square root of 900 is 30 inches.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(576+324)=sqrt900=30.","run_id":"claude-code","at":"2026-10-24T08:31:18.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ceac82f-a854-447a-8daf-d64a1b966734', 'NC17.8.G.7', 2, 'choice', 'Find a leg in a real-world problem', 'A 17-meter wire runs from the top of a vertical pole to the level ground, 8 meters from the base of the pole. How tall is the pole, in meters?', '["9","15","225","25"]', '15', '(17^2-8^2)/15', 'The wire is the hypotenuse. Height squared = 17^2 - 8^2 = 289 - 64 = 225, so the height is 15 meters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(289-64)=15.","run_id":"claude-code","at":"2026-10-24T08:31:18.491Z"}}', 'ai', NULL, NULL)
