INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0339c862-cfed-4edc-abb2-4b6e0743ad8f', 'NC17.8.G.7', 2, 'numeric', 'Find a missing leg', 'The hypotenuse of a right triangle is 9 centimeters, and one leg is 6 centimeters. How long is the other leg, to the nearest tenth of a centimeter?', '[]', '6.7', NULL, 'Leg squared = 9^2 - 6^2 = 81 - 36 = 45. Since 6.7^2 = 44.89, and 6.8^2 = 46.24, the square root of 45 is about 6.7 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(81-36)=sqrt45~6.708, 6.7.","run_id":"claude-code","at":"2026-10-24T08:31:18.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a2dab1f-ec2f-4642-9520-b34959865a7e', 'NC17.8.G.7', 3, 'choice', 'Use the converse to test for a right triangle', 'A triangle has sides of 8 cm, 11 cm and 14 cm. Pita finds that $8^2 + 11^2 = 185$ and $14^2 = 196$. She says, "These are close, so it is a right triangle." Which statement is correct?', '["It is not a right triangle, because 185 does not equal 196.","It is a right triangle, because 185 is close to 196.","It is a right triangle, because 14 is the longest side.","It is not a right triangle, because 8 + 11 is greater than 14."]', 'It is not a right triangle, because 185 does not equal 196.', NULL, 'The converse of the Pythagorean Theorem needs the squares of the shorter sides to add up exactly to the square of the longest side. 185 is not equal to 196, so the triangle is not a right triangle, however close the numbers are.', 'checked', '{"lint":[],"solve":{"answer":"It is not a right triangle, because 185 does not equal 196.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"185 != 196, so not right (converse needs equality).","run_id":"claude-code","at":"2026-10-24T08:31:18.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d59bc0e-63ef-4d37-acf0-8d29022236cb', 'NC17.8.G.7', 3, 'numeric', 'Use the theorem inside another figure', 'A rectangle has an area of 300 square centimeters and one side of 15 centimeters. How long is its diagonal, in centimeters?', '[]', '25', '(15^2+(300/15)^2)/25', 'The other side is 300 / 15 = 20 cm. The diagonal is the hypotenuse: 15^2 + 20^2 = 225 + 400 = 625, so the diagonal is 25 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other side 300/15=20; diagonal sqrt(225+400)=25.","run_id":"claude-code","at":"2026-10-24T08:31:18.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0374ef86-548b-4763-8f75-350a09555e4b', 'NC17.8.G.8', 1, 'numeric', 'distance from a whole-number triple', 'On a coordinate grid, point $P$ is at $(0, 0)$ and point $Q$ is at $(3, 4)$. Use the Pythagorean Theorem to find the distance from $P$ to $Q$.', '[]', '5', '((3^2+4^2)/5)', 'The legs are 3 and 4. The distance is $\sqrt{3^2 + 4^2} = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 3 and 4; d^2 = 9 + 16 = 25, d = 5.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a6299f2-51a5-4c15-9379-ea1b99d2506f', 'NC17.8.G.8', 1, 'choice', 'legs of the right triangle', 'To find the distance from $(2, 1)$ to $(7, 13)$, you make a right triangle with a horizontal leg and a vertical leg. What are the lengths of the two legs?', '["5 and 12","9 and 3","7 and 13","5 and 14"]', '5 and 12', NULL, 'The horizontal leg is $7 - 2 = 5$ and the vertical leg is $13 - 1 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"5 and 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal leg 7 - 2 = 5, vertical leg 13 - 1 = 12.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
