INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('081f2b6a-0197-4d29-8eed-57bd45f90ee0', 'NC17.8.G.8', 1, 'choice', 'distance from a whole-number triple', 'What is the distance from $(0, 0)$ to $(5, 12)$?', '["17","13","7","169"]', '13', '13', 'The legs are 5 and 12. The distance is $\sqrt{5^2 + 12^2} = \sqrt{169} = 13$. Adding the legs gives 17, subtracting gives 7, and 169 is the distance squared.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 25 + 144 = 169, d = 13.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
