INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eb65236-bf40-48f0-97eb-dc61ffa0f3d0', 'NC17.8.G.8', 2, 'numeric', 'perimeter on the grid', 'A triangle has vertices at $(0, 0)$, $(6, 0)$ and $(6, 8)$. What is its perimeter?', '[]', '24', '6+8+10', 'The sides along the grid lines are 6 and 8. The third side is $\sqrt{6^2 + 8^2} = 10$. The perimeter is $6 + 8 + 10 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 6, 8 and hypotenuse sqrt(36+64) = 10; perimeter 24.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
