INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bd0a728-2fdf-4cf7-823c-be81c94f77b8', 'NC17.8.G.8', 2, 'numeric', 'distance from a whole-number triple', 'Find the distance between $(-5, -7)$ and $(7, 2)$.', '[]', '15', '((12^2+9^2)/15)', 'The legs are $7 - (-5) = 12$ and $2 - (-7) = 9$. The distance is $\sqrt{12^2 + 9^2} = \sqrt{225} = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 12 and 9; d^2 = 144 + 81 = 225, d = 15.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
