INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f99b4ba-00bc-4732-8a61-575c40dc541e', 'NC17.8.G.8', 2, 'numeric', 'distance in context', 'A drone takes off at the point $(0, 0)$ of a map grid and flies in a straight line to the point $(24, 7)$. One grid unit is 1 kilometer. How many kilometers does it fly?', '[]', '25', '((24^2+7^2)/25)', 'The legs are 24 and 7. The distance is $\sqrt{24^2 + 7^2} = \sqrt{625} = 25$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 576 + 49 = 625, d = 25.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
