INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d84694-efa1-4382-b1e7-a2cc05a9defd', 'NC17.8.G.8', 3, 'numeric', 'perimeter on the grid', 'A triangle has vertices $A(0, 0)$, $B(4, 3)$ and $C(8, 0)$. What is its perimeter?', '[]', '18', '5+5+8', '$AB = \sqrt{4^2 + 3^2} = 5$. $BC$ has legs $8 - 4 = 4$ and 3, so $BC = 5$. $AC$ lies along the $x$-axis and has length 8. The perimeter is $5 + 5 + 8 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = sqrt(16+9) = 5, BC = sqrt(16+9) = 5, AC = 8; perimeter 18.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
