INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bab65d2-44fa-495d-8294-e3163ef74c07', 'NC17.8.G.8', 3, 'choice', 'distance in context', 'In a game, a character stands at the pixel position $(40, 30)$ and a target is at $(160, 190)$. One grid unit is one pixel. How far is the target from the character?', '["280 pixels","140 pixels","200 pixels","160 pixels"]', '200 pixels', NULL, 'The legs are $160 - 40 = 120$ and $190 - 30 = 160$. The distance is $\sqrt{120^2 + 160^2} = \sqrt{40000} = 200$ pixels.', 'checked', '{"lint":[],"solve":{"answer":"200 pixels","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 120 and 160; d^2 = 14400 + 25600 = 40000, d = 200.","run_id":"claude-code","at":"2026-10-24T08:29:24.489Z"}}', 'ai', NULL, NULL)
