INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03d2dde7-a862-42d5-8c01-c44d0750b3e5', 'NC17.8.G.9', 1, 'numeric', 'volume of a sphere', 'A sphere has a radius of 3 inches. Use 3.14 for $\pi$. What is the volume of the sphere, in cubic inches?', '[]', '113.04', '4/3*3.14*3^3', '$V = \frac{4}{3}\pi r^3 = \frac{4}{3} \times 3.14 \times 27 = 4 \times 3.14 \times 9 = 113.04$.', 'checked', '{"lint":[],"solve":{"answer":"113.04","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)(3.14)(27) = 36 x 3.14 = 113.04.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
