INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68577e74-63c6-48bb-bd26-51bce134b991', 'NC17.8.G.9', 1, 'numeric', 'volume of a cone', 'A cone has a radius of 3 centimeters and a height of 10 centimeters. Use 3.14 for $\pi$. What is the volume of the cone, in cubic centimeters?', '[]', '94.2', '1/3*3.14*3^2*10', '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3} \times 3.14 \times 9 \times 10 = 3.14 \times 30 = 94.2$.', 'checked', '{"lint":[],"solve":{"answer":"94.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/3)(3.14)(9)(10) = 94.2.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
