INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55bbef87-f65f-4009-92aa-af0414334c0e', 'NC17.8.G.9', 1, 'choice', 'relating the volumes of cones, cylinders and spheres', 'A cone and a cylinder have the same radius and the same height. Which statement is true?', '["The volume of the cone is one half of the volume of the cylinder.","The volume of the cone is three times the volume of the cylinder.","The volume of the cone is equal to the volume of the cylinder.","The volume of the cone is one third of the volume of the cylinder."]', 'The volume of the cone is one third of the volume of the cylinder.', NULL, 'The cone has $\frac{1}{3}\pi r^2 h$ and the cylinder has $\pi r^2 h$, so the cone is one third of the cylinder.', 'checked', '{"lint":[],"solve":{"answer":"The volume of the cone is one third of the volume of the cylinder.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone volume (1/3) pi r^2 h, cylinder pi r^2 h: one third.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37a2e1aa-65ed-4fa5-bc27-b2d36098074e', 'NC17.8.G.9', 2, 'numeric', 'volume of a cylinder', 'A cylindrical water bottle has a diameter of 8 inches and a height of 5 inches. Use 3.14 for $\pi$. What is the volume of the bottle, in cubic inches?', '[]', '251.2', '3.14*4^2*5', 'The radius is half the diameter: 4 inches. $V = 3.14 \times 4^2 \times 5 = 3.14 \times 80 = 251.2$.', 'checked', '{"lint":[],"solve":{"answer":"251.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 4: 3.14 x 16 x 5 = 251.2.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3891c7e1-82b7-4933-bfea-b75fdb335199', 'NC17.8.G.9', 2, 'choice', 'volume of a cone', 'A cone-shaped tent has a base with a diameter of 6 feet and a height of 9 feet. What is the volume of the tent, in cubic feet?', '["$27\\pi$","$81\\pi$","$108\\pi$","$9\\pi$"]', '$27\pi$', NULL, 'The radius is 3 feet. $V = \frac{1}{3}\pi (3^2)(9) = 27\pi$. Using 6 as the radius gives $108\pi$, and leaving out the $\frac{1}{3}$ gives $81\pi$.', 'checked', '{"lint":[],"solve":{"answer":"$27\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 3: (1/3) pi 9 x 9 = 27 pi.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40796ba7-c056-45b4-ae3a-32eb05f5147e', 'NC17.8.G.9', 2, 'numeric', 'finding a missing dimension from a volume', 'A cylinder has a volume of 314 cubic centimeters and a radius of 5 centimeters. Use 3.14 for $\pi$. What is the height of the cylinder, in centimeters?', '[]', '4', '314/(3.14*5^2)', '$314 = 3.14 \times 5^2 \times h = 78.5\,h$, so $h = 314 \div 78.5 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"314 = 3.14 x 25 x h = 78.5h, h = 4.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47e4e46b-0bcf-48e4-b2c6-d88a93da4138', 'NC17.8.G.9', 3, 'numeric', 'volume of a composite solid', 'An ice cream cone is a cone with a radius of 3 centimeters and a height of 9 centimeters. A scoop of ice cream in the shape of a half sphere (a hemisphere) with the same radius sits on top of the cone. Use 3.14 for $\pi$. What is the total volume of the cone and the scoop, in cubic centimeters?', '[]', '141.3', '1/3*3.14*3^2*9+1/2*4/3*3.14*3^3', 'Cone: $\frac{1}{3} \times 3.14 \times 9 \times 9 = 3.14 \times 27 = 84.78$. Half sphere: $\frac{1}{2} \times \frac{4}{3} \times 3.14 \times 27 = 3.14 \times 18 = 56.52$. Total: $84.78 + 56.52 = 141.3$.', 'checked', '{"lint":[],"solve":{"answer":"141.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone (1/3)(3.14)(9)(9) = 84.78; hemisphere (2/3)(3.14)(27) = 56.52; total 141.3.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a75e819-5e05-45e4-87d6-0e262a3e39ba', 'NC17.8.G.9', 3, 'choice', 'how volume changes when a dimension changes', 'A cone''s radius is cut in half and its height is multiplied by 3. The volume of the new cone is how many times the volume of the original cone?', '["$\\frac{3}{2}$","$\\frac{1}{4}$","$\\frac{3}{4}$","$3$"]', '$\frac{3}{4}$', NULL, 'Halving the radius multiplies the volume by $\left(\frac{1}{2}\right)^2 = \frac{1}{4}$, and tripling the height multiplies it by 3, so the volume is $\frac{3}{4}$ of the original.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)^2 x 3 = 3/4.","run_id":"claude-code","at":"2026-10-24T08:32:51.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d473b0f-718b-4019-8353-c16c96386ed8', 'NC17.8.SP.1', 1, 'choice', 'Recognize the association from a described situation', 'A scatter plot compares the age of used cars with their selling prices. Older cars tend to sell for less. What type of association is this?', '["Negative association","Positive association","No association","A cluster"]', 'Negative association', NULL, 'As the age goes up, the price tends to go down. That is a negative association.', 'checked', '{"lint":[],"solve":{"answer":"Negative association","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Older, lower price: negative.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
