INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('261b9b65-f888-47c4-b02b-d1a211698d88', 'NC17.8.SP.1', 1, 'numeric', 'Plot and read the points of a scatter plot', 'A student slept 8 hours and scored 85 on a test. The scatter plot has hours of sleep on the $x$-axis and test score on the $y$-axis. A point is plotted for this student. What is the $y$-coordinate of the point?', '[]', '85', NULL, 'The $x$-coordinate is the hours of sleep, 8, and the $y$-coordinate is the test score, 85. The point is $(8, 85)$.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Point (8, 85); y-coordinate 85.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
