INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33906989-9fc0-4a06-9dd8-2f32485f1405', 'NC17.8.SP.1', 1, 'numeric', 'Describe the association from data points', 'A scatter plot has the points $(1, 3)$, $(2, 5)$, $(3, 7)$, $(4, 9)$ and $(5, 11)$. They lie on a straight line. Each time $x$ increases by 1, by how much does $y$ increase?', '[]', '2', '5-3', 'From $(1, 3)$ to $(2, 5)$, $y$ goes from 3 to 5, which is an increase of 2. The same is true for every step.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y goes 3, 5, 7, 9, 11: up by 2.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('244d61e5-082f-42bb-8754-23ec506299ed', 'NC17.8.SP.1', 2, 'numeric', 'Find and interpret outliers', 'The points $(1, 4)$, $(2, 5)$, $(3, 6)$, $(4, 7)$, $(5, 18)$ and $(6, 9)$ are plotted. One point is an outlier. What is the $x$-coordinate of the outlier?', '[]', '5', NULL, 'Without the outlier, $y$ is $x + 3$. At $x = 5$ that would be 8, but the point has $y = 18$. The outlier is $(5, 18)$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pattern y = x + 3: (5, 8) expected, (5, 18) is the outlier. x = 5.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20e9818a-f451-4449-88f4-0e74397c7323', 'NC17.8.SP.1', 2, 'choice', 'Recognize the association from a described situation', 'Which pair of variables would most likely show a negative association in a scatter plot?', '["The height of a child and the length of the child''s foot","The age of a tree and the width of its trunk","The length of a book and the weight of the book","The speed of a car and the time it takes to go 100 miles"]', 'The speed of a car and the time it takes to go 100 miles', NULL, 'A faster car takes less time to go 100 miles, so one goes up while the other goes down. The other pairs both tend to go up together.', 'checked', '{"lint":[],"solve":{"answer":"The speed of a car and the time it takes to go 100 miles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Faster speed means less time for a fixed distance: negative.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26f20c72-2909-4284-8789-8e37b5b7a481', 'NC17.8.SP.1', 2, 'choice', 'Find and interpret outliers', 'Which describes an outlier in a scatter plot?', '["A point far from the overall pattern of the other points","The point with the greatest $x$-value in the whole plot","The point with the least $y$-value in the whole plot","A point that lies exactly on the pattern of the others"]', 'A point far from the overall pattern of the other points', NULL, 'An outlier is a point that does not fit the overall pattern. It is far from the other points.', 'checked', '{"lint":[],"solve":{"answer":"A point far from the overall pattern of the other points","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outlier: far from the overall pattern.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16cb2938-b6eb-414f-8a64-bf1800745bbd', 'NC17.8.SP.1', 3, 'numeric', 'Find and interpret outliers', 'The points $(1, 3)$, $(2, 4)$, $(3, 5)$, $(4, 6)$, $(5, 7)$, $(6, 8)$, $(7, 2)$ and $(8, 10)$ are plotted. What is the $x$-coordinate of the one outlier?', '[]', '7', NULL, 'The other points follow $y = x + 2$. At $x = 7$ the pattern gives 9, but the point is $(7, 2)$. So the outlier has $x = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pattern y = x + 2; at x = 7 expect 9, got 2. x = 7.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0880f303-19c7-41ec-a5b9-8786e966688d', 'NC17.8.SP.1', 3, 'numeric', 'Plot and read the points of a scatter plot', 'These points are plotted: $(2, 3)$, $(5, 8)$, $(6, 5)$, $(7, 9)$, $(4, 7)$, $(8, 10)$ and $(9, 4)$. How many points have both $x > 4$ and $y > 6$?', '[]', '3', NULL, 'Check each point. $(5, 8)$, $(7, 9)$ and $(8, 10)$ have $x > 4$ and $y > 6$. The others fail one condition. So there are 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x > 4 and y > 6: (5,8) yes, (6,5) no, (7,9) yes, (4,7) no (x=4), (8,10) yes, (9,4) no. Count 3.","run_id":"claude-code","at":"2026-10-24T08:31:33.638Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56d6946b-901c-4929-abbe-a9c9009b9eea', 'NC17.8.SP.2', 1, 'choice', 'Decide when a straight line is a reasonable fit', 'Nine points lie close to a rising path, and one point lies far above it. A student draws a line of best fit. Which is the best choice?', '["Make the line pass through all ten points, even if it bends.","Follow the pattern of the nine points, even if the far point is missed.","Make the line pass through the far point, even if the nine are missed.","Draw no line, since one point is far from the others."]', 'Follow the pattern of the nine points, even if the far point is missed.', NULL, 'The line should show the pattern of most of the points. One far point should not pull the line away from the other nine.', 'checked', '{"lint":[],"solve":{"answer":"Follow the pattern of the nine points, even if the far point is missed.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An outlier should not pull the line; follow the trend of the nine points.","run_id":"claude-code","at":"2026-10-24T08:36:05.521Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62083a75-1b0a-4751-ad7d-865273e3e97b', 'NC17.8.SP.2', 1, 'choice', 'Compare two lines for fit', 'Two lines are drawn on the same scatter plot. Most points lie on or very near Line 1. Most points lie far from Line 2. Which statement is true?', '["Line 2 is the better fit.","Line 1 is the better fit.","Both lines fit equally well.","Neither line can be judged without more points."]', 'Line 1 is the better fit.', NULL, 'A line fits better when the points are closer to it. The points are closer to Line 1, so it is the better fit.', 'checked', '{"lint":[],"solve":{"answer":"Line 1 is the better fit.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Points near Line 1, far from Line 2, so Line 1 fits better.","run_id":"claude-code","at":"2026-10-24T08:36:05.521Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('366c8da2-02e9-4968-b210-f7d45aa6c331', 'NC17.8.SP.2', 1, 'choice', 'Decide when a straight line is a reasonable fit', 'Two sets of points are listed. Set P: (1, 14), (2, 11), (3, 9), (4, 5), (5, 2). Set Q: (1, 3), (2, 12), (3, 4), (4, 11), (5, 2). Which set is better fit by a straight line?', '["Set Q, because its points go up and down by about the same amount","Set P, because its points fall along a nearly straight path","Both sets, because a line can be drawn through any points","Neither set, because a line can only go through rising points"]', 'Set P, because its points fall along a nearly straight path', NULL, 'In Set P the $y$-values fall steadily (14, 11, 9, 5, 2), close to a straight path that slopes down. In Set Q the $y$-values jump up and down, so no line is close to most of the points.', 'checked', '{"lint":[],"solve":{"answer":"Set P, because its points fall along a nearly straight path","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: y drops 3,2,4,3 each step, nearly straight downward trend. Q: zigzags 3,12,4,11,2 with no linear trend. P is better fit.","run_id":"claude-code","at":"2026-10-24T08:47:21.369Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aec821d-cb36-4efe-bdfb-44e104eb813c', 'NC17.8.SP.2', 2, 'numeric', 'Vertical distance of a point from a line', 'A line is $y = \frac{1}{2}x + 2$. The data points are $(2, 3)$, $(4, 5)$, $(6, 4)$ and $(8, 7)$. What is the total of the four vertical distances from the points to the line?', '[]', '3', '0+1+1+1', 'The line has $y = 3, 4, 5, 6$ at $x = 2, 4, 6, 8$. The distances are $0, 1, 1, 1$. The total is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line values: x=2:3 (dist 0), x=4:4 (dist 1), x=6:5 (dist 1), x=8:6 (dist 1). Total 3.","run_id":"claude-code","at":"2026-10-24T08:36:05.521Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('219109ab-91a7-4438-a519-0731d2cd0695', 'NC17.8.SP.2', 2, 'choice', 'Find the equation of a line drawn through two points', 'A line of best fit is drawn through the points $(0, 3)$ and $(5, 13)$. Which equation describes it?', '["$y = \\frac{1}{2}x + 3$","$y = 2x + 3$","$y = 2x + 13$","$y = 3x + 2$"]', '$y = 2x + 3$', NULL, 'The slope is $(13 - 3) \div (5 - 0) = 2$. The line crosses the $y$-axis at $(0, 3)$, so the intercept is 3. The equation is $y = 2x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (13-3)/5 = 2, intercept 3: y = 2x + 3.","run_id":"claude-code","at":"2026-10-24T08:36:05.521Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b4b5dc6-2ca0-47fd-b564-d8432dda3f52', 'NC17.8.SP.2', 2, 'numeric', 'Judge how well a line fits', 'Maya measured how far five data points are from her line. The distances are 0, 2, 1, 3 and 4 units. What is the mean distance of the points from the line?', '[]', '2', '(0+2+1+3+4)/5', 'Add the distances: $0 + 2 + 1 + 3 + 4 = 10$. Divide by 5: $10 \div 5 = 2$ units.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0+2+1+3+4)/5 = 10/5 = 2.","run_id":"claude-code","at":"2026-10-24T08:36:05.521Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2801497e-6ea7-41d9-b51f-0e30d1995dc5', 'NC17.8.SP.2', 3, 'numeric', 'Vertical distance of a point from a line', 'A line is $y = 1.5x + 2$. The data points are $(2, 6)$, $(4, 7)$, $(6, 14)$ and $(8, 12)$. How many units is the farthest point from the line, measured straight up or down?', '[]', '3', '14-(1.5*6+2)', 'The line has $y = 5, 8, 11, 14$ at $x = 2, 4, 6, 8$. The distances are $1, 1, 3, 2$. The farthest is 3 units, at $(6, 14)$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line: x=2:5 (dist 1), x=4:8 (dist 1), x=6:11 (dist 3), x=8:14 (dist 2). Farthest 3.","run_id":"claude-code","at":"2026-10-24T08:36:05.521Z"}}', 'ai', NULL, NULL)
