INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0209ce3c-48bd-4250-b0e5-04801f4ca6e9', 'NC17.8.SP.2', 3, 'choice', 'Decide when a straight line is a reasonable fit', 'A scatter plot has the points $(1, 3)$, $(2, 7)$, $(3, 9)$, $(4, 7)$ and $(5, 3)$. Why is a straight line a poor fit?', '["The points are all at different heights, so no line can be drawn.","The points rise and then fall, so no single line stays near them.","The $x$-values are too small for a line to be drawn.","The points only fall, so a line would have to slope up."]', 'The points rise and then fall, so no single line stays near them.', NULL, 'The points go up to $(3, 9)$ and then come back down. Any straight line is far from some of the points, so no line fits well.', 'checked', '{"lint":[],"solve":{"answer":"The points rise and then fall, so no single line stays near them.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 3,7,9,7,3 rise then fall; no single line stays near them.","run_id":"claude-code","at":"2026-10-24T08:36:05.521Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0299ca9a-eb24-43c6-972a-b18aaddf341a', 'NC17.8.SP.3', 1, 'choice', 'Interpret the slope', 'The cost $y$, in dollars, of renting a bike for $x$ hours is modeled by $y = 3x + 10$. What does the 3 tell you?', '["The rental has a starting charge of 3 dollars.","Each extra hour adds 3 dollars to the cost.","Each extra hour adds 10 dollars to the cost.","Renting for 10 hours costs 3 dollars."]', 'Each extra hour adds 3 dollars to the cost.', NULL, 'The number multiplying $x$ is the slope. It is the change in cost for each 1 hour more: 3 dollars per hour. The 10 is the cost at 0 hours.', 'checked', '{"lint":[],"solve":{"answer":"Each extra hour adds 3 dollars to the cost.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 is the slope: dollars per hour.","run_id":"claude-code","at":"2026-10-24T08:36:28.914Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('583ec9ec-879c-4867-adaf-8ba65ec6389e', 'NC17.8.SP.3', 1, 'choice', 'Predict with the model', 'The model $y = 6x + 4$ gives the total points $y$ a player has scored after $x$ games. How many points does the model predict after 5 games?', '["$34$","$30$","$20$","$50$"]', '$34$', '34', '$6 \times 5 + 4 = 30 + 4 = 34$ points.', 'checked', '{"lint":[],"solve":{"answer":"$34$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(5)+4 = 34.","run_id":"claude-code","at":"2026-10-24T08:36:28.914Z"}}', 'ai', NULL, NULL)
