INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25558fc4-0096-46ce-b4c7-fdedc93bb7b6', 'NC17.8.SP.3', 1, 'choice', 'Find the input for a given prediction', 'A model is $y = 4x + 2$. For which value of $x$ does the model predict $y = 18$?', '["$16$","$20$","$4$","$72$"]', '$4$', '(18-2)/4', 'Solve $4x + 2 = 18$. Subtract 2: $4x = 16$. Divide by 4: $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+2=18, 4x=16, x=4.","run_id":"claude-code","at":"2026-10-24T08:36:28.914Z"}}', 'ai', NULL, NULL)
