INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eb94b05-e2e5-4d1f-90a5-2779611ad439', 'NC17.8.SP.3', 2, 'choice', 'Interpret the intercept', 'A line of fit for a puppy''s weight $y$, in kilograms, at age $x$ weeks is $y = 0.9x + 2.5$. What does the 2.5 tell you?', '["It predicts the puppy gains 2.5 kilograms each week.","It predicts a weight of 0.9 kilograms at age 2.5 weeks.","It predicts the puppy stops growing at 2.5 kilograms.","It predicts a weight of 2.5 kilograms at age 0 weeks."]', 'It predicts a weight of 2.5 kilograms at age 0 weeks.', NULL, 'The intercept is the predicted $y$ when $x = 0$: a weight of 2.5 kilograms at age 0 weeks.', 'checked', '{"lint":[],"solve":{"answer":"It predicts a weight of 2.5 kilograms at age 0 weeks.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intercept: x=0 gives y=2.5.","run_id":"claude-code","at":"2026-10-24T08:36:28.914Z"}}', 'ai', NULL, NULL)
