INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68b8a2f1-c58a-4b46-98e0-58d8d562ee03', 'NC17.8.SP.3', 2, 'numeric', 'Find the input for a given prediction', 'A phone''s battery level is modeled by $y = -4x + 100$, where $y$ is the percent left after $x$ hours of use. After how many hours does the model predict 40 percent left?', '[]', '15', '(40-100)/-4', 'Solve $-4x + 100 = 40$. Subtract 100: $-4x = -60$. Divide by $-4$: $x = 15$ hours.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4x+100=40, 4x=60, x=15.","run_id":"claude-code","at":"2026-10-24T08:36:28.914Z"}}', 'ai', NULL, NULL)
