INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05143f0c-c210-449d-82b6-61cb26b2fe01', 'NC17.8.SP.3', 2, 'choice', 'Predict with the model', 'The model $y = -1.5x + 30$ gives the liters $y$ of fuel left in a boat after $x$ hours. How many liters does it predict are left after 8 hours?', '["$42$","$18$","$28.5$","$3.75$"]', '$18$', '-1.5*8+30', '$-1.5 \times 8 = -12$, and $-12 + 30 = 18$ liters.', 'checked', '{"lint":[],"solve":{"answer":"$18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-1.5(8)+30 = -12+30 = 18.","run_id":"claude-code","at":"2026-10-24T08:36:28.914Z"}}', 'ai', NULL, NULL)
