INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08157457-8ee6-4cd1-bbe1-92cb6e38d95c', 'NC17.8.SP.3', 3, 'choice', 'Find the input for a given prediction', 'The model $y = -2.4x + 96$ gives the gallons $y$ in a tank after $x$ hours of draining. After how many hours does the model predict the tank is empty?', '["$96$","$230.4$","$93.6$","$40$"]', '$40$', '96/2.4', 'The tank is empty when $y = 0$. Solve $-2.4x + 96 = 0$: $2.4x = 96$, so $x = 40$ hours.', 'checked', '{"lint":[],"solve":{"answer":"$40$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2.4x+96=0, x=96/2.4=40.","run_id":"claude-code","at":"2026-10-24T08:36:28.914Z"}}', 'ai', NULL, NULL)
