INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c98ed93-5aa4-4137-ab9b-fc480df06412', 'NC17.8.SP.4', 1, 'numeric', 'Relative frequency from a two-way table', 'In a survey, 25 Grade 7 students were asked which pet they prefer. 15 of them prefer dogs and 10 prefer cats. What fraction of the Grade 7 students prefer dogs? Write your answer as a decimal.', '[]', '0.6', '15/25', 'The relative frequency is 15 out of the 25 Grade 7 students: 15/25 = 3/5 = 0.6.', 'checked', '{"lint":[],"solve":{"answer":"0.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 of 25 prefer dogs: 15/25 = 0.6.","run_id":"claude-code","at":"2026-10-24T08:37:23.262Z"}}', 'ai', NULL, NULL)
