INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09ff3741-ed3c-44c7-a82b-52061ce2ec9c', 'NC17.8.SP.4', 1, 'choice', 'Construct a two-way table from data', 'A survey records each student''s grade (7 or 8) and favorite season. How should these data be organized in a two-way table?', '["Put one category in the rows and the other in the columns, and add the ages of the students.","Put the students'' names in the rows and leave the columns empty, with no counts.","Put each category on its own number line and mark one dot for each student.","Put one category in the rows and the other in the columns, and count the students in each pair."]', 'Put one category in the rows and the other in the columns, and count the students in each pair.', NULL, 'A two-way table has one categorical variable in the rows and the other in the columns. Each cell counts the students who fall in both categories.', 'checked', '{"lint":[],"solve":{"answer":"Put one category in the rows and the other in the columns, and count the students in each pair.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A two-way table puts one categorical variable in rows, the other in columns, and counts each pair.","run_id":"claude-code","at":"2026-10-24T08:37:23.262Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03c3eb89-d46d-401c-92e1-2fd7946402fb', 'NC17.8.SP.4', 2, 'numeric', 'Complete a two-way table', 'A survey of 100 students sorted the answers by grade and by whether the student likes music. There are 55 students in Grade 7, and 28 of them like music. In all, 60 students like music. How many Grade 8 students like music?', '[]', '32', '60-28', 'The 60 students who like music are split between the grades. Grade 7 has 28 of them, so Grade 8 has 60 - 28 = 32.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Music total 60, Grade 7 music 28; Grade 8 music = 60 - 28 = 32.","run_id":"claude-code","at":"2026-10-24T08:37:23.262Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('315793d6-0070-421e-9597-3dfab1479da3', 'NC17.8.SP.4', 2, 'choice', 'Relative frequency from a two-way table', 'Students were asked how they get to school. Bus: 24 in Grade 7 and 16 in Grade 8. Walk: 6 in Grade 7 and 14 in Grade 8. Of the students who walk, what fraction are in Grade 7?', '["$\\frac{1}{10}$","$\\frac{3}{10}$","$\\frac{1}{5}$","$\\frac{7}{10}$"]', '$\frac{3}{10}$', NULL, 'The walk column has 6 + 14 = 20 students, and 6 of them are in Grade 7: 6/20 = 3/10. The other fractions use the wrong total: 6/60, 6/30, and the Grade 8 share 14/20.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walk total 6 + 14 = 20; Grade 7 walkers 6; 6/20 = 3/10.","run_id":"claude-code","at":"2026-10-24T08:37:23.262Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('098bbed5-25db-4693-bc91-42f9bd010d81', 'NC17.8.SP.4', 2, 'choice', 'Describe association using relative frequencies', 'Students who study with music: 24 passed a test and 6 failed. Students who study without music: 30 passed and 70 failed. Which statement describes the association?', '["Students who study without music pass more often, because 30 of them passed and only 24 of the others did.","There is no association, because some students in each group passed and some failed the test.","Students who study with music pass more often: 80% of them passed, compared with 30% of the others.","Students who study with music pass more often because they are the smaller group of the two."]', 'Students who study with music pass more often: 80% of them passed, compared with 30% of the others.', NULL, 'With music: 24 of 30 passed, which is 80%. Without music: 30 of 100 passed, which is 30%. Comparing percents, not counts, shows the association. The groups differ in size, so counts are misleading.', 'checked', '{"lint":[],"solve":{"answer":"Students who study with music pass more often: 80% of them passed, compared with 30% of the others.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With music: 24/30 = 80% pass. Without: 30/100 = 30% pass. Option with 80% vs 30%.","run_id":"claude-code","at":"2026-10-24T08:37:23.262Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('393df748-f996-43d8-94a4-fbc06cec3c59', 'NC17.8.SP.4', 3, 'numeric', 'Relative frequency from a two-way table', 'In a survey of 250 people, the relative frequency of people who are over 40 and prefer tea is 0.18. How many people are over 40 and prefer tea?', '[]', '45', '18/100*250', 'A relative frequency is the count divided by the total, so the count is 0.18 x 250 = 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.18 * 250 = 45.","run_id":"claude-code","at":"2026-10-24T08:37:23.262Z"}}', 'ai', NULL, NULL)
