INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11f1dee4-8c97-442c-a5e1-e08b84dd41cb', 'NC17.M1.N-RN.2', 1, 'choice', 'Spot and explain a mistake', 'Nina says $5^0 = 0$. Which statement shows her mistake?', '["$5^0 = 5$, because the exponent 0 leaves the base unchanged","$5^0 = 1$, because any nonzero number to the power 0 equals 1","$5^0 = -5$, because the exponent 0 changes the sign of the base","$5^0 = \\frac{1}{5}$, because the exponent 0 flips the base upside down"]', '$5^0 = 1$, because any nonzero number to the power 0 equals 1', NULL, 'Any nonzero number to the power 0 is 1. For example, $\frac{5^2}{5^2} = 5^{2-2} = 5^0$, and a number divided by itself is 1.', 'checked', '{"lint":[],"solve":{"answer":"$5^0 = 1$, because any nonzero number to the power 0 equals 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any nonzero base to the 0 power is 1.","run_id":"claude-code","at":"2026-10-28T18:47:12.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('033943ab-28bc-43d8-90c2-81aa69f129c6', 'NC17.M1.N-RN.2', 1, 'choice', 'Power of a product or quotient', 'Which expression is equivalent to $\left(\frac{x}{3}\right)^2$?', '["$\\frac{x^2}{3}$","$\\frac{x}{9}$","$\\frac{x^2}{6}$","$\\frac{x^2}{9}$"]', '$\frac{x^2}{9}$', NULL, 'The exponent applies to both the top and the bottom: $\frac{x^2}{3^2} = \frac{x^2}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{x^2}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x/3)^2=x^2/9.","run_id":"claude-code","at":"2026-10-28T18:48:27.937Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01bf0be8-b9a7-463b-9820-52433fe84e95', 'NC17.M1.N-RN.2', 2, 'choice', 'Product of powers', 'Simplify $x^{-3} \cdot x^5$, for $x \ne 0$.', '["$x^2$","$x^{-15}$","$x^{-2}$","$x^8$"]', '$x^2$', NULL, 'Add the exponents: $-3 + 5 = 2$, so the result is $x^2$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^-3 * x^5 = x^(-3+5) = x^2.","run_id":"claude-code","at":"2026-10-24T02:58:26.321Z"}}', 'ai', NULL, NULL)
