INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02ec2fb0-f12a-4178-b3b0-b9eaf8108b78', 'NC17.M1.N-RN.2', 2, 'choice', 'Negative exponents', 'Which expression is equivalent to $(2x)^{-3}$, for $x \ne 0$?', '["$\\frac{1}{8x^3}$","$\\frac{1}{2x^3}$","$-8x^3$","$\\frac{8}{x^3}$"]', '$\frac{1}{8x^3}$', NULL, '$(2x)^{-3} = \frac{1}{(2x)^3} = \frac{1}{2^3x^3} = \frac{1}{8x^3}$. The exponent applies to the 2 as well as the $x$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8x^3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x)^-3 = 1/(2x)^3 = 1/(8x^3).","run_id":"claude-code","at":"2026-10-28T18:48:27.935Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1842c7-1524-4b37-b605-68744261a555', 'NC17.M1.N-RN.2', 2, 'numeric', 'Find a missing exponent', 'For $x \ne 0$, $\frac{x^{?}}{x^{5}} = x^{-3}$. What number is the ?', '[]', '2', '5-3', 'Subtract the exponents: ? $- 5 = -3$, so ? $= 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^{?-5} = x^{-3}, so ? - 5 = -3, ? = 2.","run_id":"claude-code","at":"2026-10-28T18:48:28.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0af7c60d-a139-4969-9d1f-6fa060d64610', 'NC17.M1.N-RN.2', 3, 'numeric', 'Find a missing exponent', 'For $x \ne 0$, $\frac{x^{n} \cdot x^{-3}}{x^{4}} = x^{-1}$. What is $n$?', '[]', '6', '-1+3+4', 'The exponent on the left is $n + (-3) - 4 = n - 7$. Setting $n - 7 = -1$ gives $n = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^n x^-3 / x^4 = x^(n-7) = x^-1, so n - 7 = -1, n = 6.","run_id":"claude-code","at":"2026-10-28T18:48:28.082Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066c5b63-55d2-4b59-8d61-2823bdf4c861', 'NC17.M1.N-RN.2', 3, 'numeric', 'Combine product, quotient and power rules', 'For $x \ne 0$, $\left(\frac{2x^{-3}}{x^{-5}}\right)^{3} = kx^{n}$. What is $k + n$?', '[]', '14', '8+6', 'Inside: $2x^{-3-(-5)} = 2x^2$. Cube it: $2^3x^{6} = 8x^6$. So $k = 8$, $n = 6$ and $k + n = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^{-3}/x^{-5}=2x^2; cubed: 8x^6. k=8, n=6, sum 14.","run_id":"claude-code","at":"2026-10-28T18:48:28.472Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19e10939-8160-4c49-8b8d-c24369a6277b', 'NC17.M1.A-SSE.1', 1, 'numeric', 'Interpret rates and starting values in a linear expression', 'A plant''s height, in centimeters, after $w$ weeks is $12 + 3w$. What was its height, in centimeters, at the start, when $w = 0$?', '[]', '12', '12+3*0', 'When $w = 0$ the term $3w$ is 0, so the height is $12 + 0 = 12$ centimeters. The constant term 12 is the starting height.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 3*0 = 12.","run_id":"claude-code","at":"2026-10-24T02:59:10.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0961b43c-e49b-4b37-93d6-253602545187', 'NC17.M1.A-SSE.1', 1, 'choice', 'Interpret the base, exponent and starting value of an exponential expression', 'The number of bacteria after $n$ hours is $100 \cdot 3^n$. What does the exponent $n$ tell you?', '["How many times the amount has been multiplied by 3","How many bacteria there were at the very start, before any growth","What number the amount is multiplied by each time","How many bacteria are added every hour"]', 'How many times the amount has been multiplied by 3', NULL, 'The exponent counts the repeated multiplications by 3, one for each hour. The starting amount is 100 and the multiplier is 3.', 'checked', '{"lint":[],"solve":{"answer":"How many times the amount has been multiplied by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^n means multiplying by 3, n times; n counts how many times the amount has been multiplied by 3.","run_id":"claude-code","at":"2026-10-24T02:59:10.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('049ed39a-2be7-4624-b665-50e0c07ce5ac', 'NC17.M1.A-SSE.1', 1, 'numeric', 'Interpret rates and starting values in a linear expression', 'The amount of money in a jar after $w$ weeks is $30 + 5w$ dollars. How many dollars are added to the jar each week?', '[]', '5', NULL, 'The amount grows by 5 dollars for each week, so 5 dollars are added each week.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 + 5w: 5 dollars added each week.","run_id":"claude-code","at":"2026-10-28T19:16:32.543Z"}}', 'ai', NULL, NULL)
