INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4422b9-4f29-430c-8827-9949194aa533', 'NC17.M1.A-SSE.1', 2, 'numeric', 'Interpret a part of an expression in context', 'A theater sells child tickets for 7 dollars and adult tickets for 12 dollars. The money from $a$ adult tickets and $c$ child tickets is $12a + 7c$ dollars. How much money, in dollars, do 5 child tickets bring in? (This is the value of the part $7c$ when $c = 5$.)', '[]', '35', '7*5', 'The part $7c$ is the money from child tickets. With $c = 5$ it is $7 \times 5 = 35$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7*5 = 35.","run_id":"claude-code","at":"2026-10-24T02:59:10.540Z"}}', 'ai', NULL, NULL)
