INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05749531-aa48-4297-9ae5-87abb77659f6', 'NC17.M1.A-SSE.1', 2, 'choice', 'Interpret rates and starting values in a linear expression', 'A pool holds $5000 - 200m$ liters of water after it has drained for $m$ minutes. What does the number 5000 represent?', '["The amount of water that drains out each minute","The number of minutes that it takes to completely empty the pool","The amount of water in the pool before draining starts","The amount of water left after 200 minutes"]', 'The amount of water in the pool before draining starts', NULL, 'When $m = 0$, the term $200m$ is 0, so the pool holds 5000 liters. That is the starting amount. The 200 is the rate of draining.', 'checked', '{"lint":[],"solve":{"answer":"The amount of water in the pool before draining starts","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At m = 0 the pool holds 5000 L: water before draining starts.","run_id":"claude-code","at":"2026-10-24T02:59:10.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06d3600e-9d3f-4cad-8cce-5f62bf260697', 'NC17.M1.A-SSE.1', 2, 'choice', 'Compare what two expressions say about change', 'Gym X charges $30 + 20m$ dollars for $m$ months and gym Y charges $50 + 15m$ dollars. Which statement is true?', '["X has the smaller joining fee, but Y adds less each month","X has the larger joining fee, and Y adds less each month","X has the smaller joining fee, and Y adds more each month","Y has the smaller joining fee, and X adds less each month"]', 'X has the smaller joining fee, but Y adds less each month', NULL, 'X starts at 30 and Y at 50, so X has the smaller joining fee. X adds 20 a month and Y adds 15, so Y adds less.', 'checked', '{"lint":[],"solve":{"answer":"X has the smaller joining fee, but Y adds less each month","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: fee 30, +20/month. Y: fee 50, +15/month. X smaller fee, Y adds less.","run_id":"claude-code","at":"2026-10-28T19:16:32.269Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c39ba7-8a82-404a-ac49-3e344620f049', 'NC17.M1.A-SSE.1', 3, 'numeric', 'Identify coefficients, factors and constants', 'The expression $2(3x - 1) + 4x$ is simplified to have one $x$ term and one constant term. What is the coefficient of $x$?', '[]', '10', '2*3+4', 'Distribute: $2(3x - 1) = 6x - 2$. Then $6x - 2 + 4x = 10x - 2$. The coefficient of $x$ is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 2 + 4x = 10x - 2; coefficient 10.","run_id":"claude-code","at":"2026-10-24T02:59:10.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e5dcf2a-c318-4e67-b91b-5355fe5a3ee8', 'NC17.M1.A-SSE.1', 3, 'numeric', 'Interpret the parts of a quadratic expression', 'The height of a ball, in feet, after $t$ seconds is $-16t^2 + 32t + 5$. What is the value of the term $-16t^2$ when $t = 2$?', '[]', '-64', '-16*2^2', '$-16 \cdot 2^2 = -16 \cdot 4 = -64$.', 'checked', '{"lint":[],"solve":{"answer":"-64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-16 x 2^2 = -64.","run_id":"claude-code","at":"2026-10-28T19:16:32.177Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04a9ca53-892c-40b3-ae33-3e857dcf9b18', 'NC17.M1.A-SSE.3', 1, 'choice', 'factor a monic quadratic', 'Which expression is equal to $x^2 + 5x + 6$?', '["$(x+2)(x+3)$","$(x+1)(x+6)$","$(x-2)(x-3)$","$(x+5)(x+6)$"]', '$(x+2)(x+3)$', NULL, 'Find two numbers with product 6 and sum 5: they are 2 and 3. So $x^2 + 5x + 6 = (x+2)(x+3)$. Check: $(x+2)(x+3) = x^2 + 3x + 2x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$(x+2)(x+3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*3 = 6, 2+3 = 5: (x+2)(x+3).","run_id":"claude-code","at":"2026-10-24T02:58:26.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b72d6e-1d1d-4b55-a519-e19e5c31304b', 'NC17.M1.A-SSE.3', 1, 'numeric', 'zeros of a quadratic function', 'The graph of $y = x^2 - 4$ crosses the x-axis at two points. What is the positive x-coordinate?', '[]', '2', '2', 'The graph crosses the x-axis where $y = 0$: $x^2 - 4 = 0$, so $(x-2)(x+2) = 0$ and $x = 2$ or $x = -2$. The positive one is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 4 = (x-2)(x+2) = 0, x = 2 or -2; positive 2.","run_id":"claude-code","at":"2026-10-24T02:58:26.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02ea610d-ec48-4d4a-b539-08001a6c5e8c', 'NC17.M1.A-SSE.3', 1, 'numeric', 'zeros of a quadratic function', 'The function $f(x) = x^2 - 81$ has two zeros. What is their product?', '[]', '-81', '-81', '$x^2 - 81 = (x-9)(x+9)$, so the zeros are 9 and $-9$. Their product is $9 \cdot (-9) = -81$.', 'checked', '{"lint":[],"solve":{"answer":"-81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros 9 and -9; product -81.","run_id":"claude-code","at":"2026-10-28T19:16:32.510Z"}}', 'ai', NULL, NULL)
