INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('131c05af-4bf5-4978-aae0-12baa81396ab', 'NC17.M1.A-SSE.3', 2, 'numeric', 'solve a quadratic equation by factoring', 'Solve $x^2 = 5x + 14$. What is the smaller solution?', '[]', '-2', '-2', 'Move everything to one side: $x^2 - 5x - 14 = 0$. Factor: $(x-7)(x+2) = 0$, so $x = 7$ or $x = -2$. The smaller solution is $-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 5x - 14 = 0, (x-7)(x+2) = 0, x = 7 or -2; smaller -2.","run_id":"claude-code","at":"2026-10-24T02:58:26.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06671d13-d729-4136-8bc0-f2814176f6e5', 'NC17.M1.A-SSE.3', 2, 'choice', 'build a quadratic from its zeros', 'The graph of a quadratic function with integer coefficients crosses the x-axis at $x = \frac{2}{3}$ and at $x = -1$. Which equation could define the function?', '["$f(x) = 3x^2 - x - 2$","$f(x) = 3x^2 + x - 2$","$f(x) = 2x^2 + x - 3$","$f(x) = 3x^2 + 5x + 2$"]', '$f(x) = 3x^2 + x - 2$', NULL, 'The zero $x = \frac{2}{3}$ comes from the factor $(3x - 2)$ and $x = -1$ from $(x + 1)$. Then $(3x-2)(x+1) = 3x^2 + x - 2$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = 3x^2 + x - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x-2)(x+1) = 3x^2 + x - 2. Check: A=(2x+3)(x-1), C=(3x+2)(x-1), D=(3x+2)(x+1).","run_id":"claude-code","at":"2026-10-28T19:16:32.147Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ac69adb-025c-4466-997c-f2ffa5ca8153', 'NC17.M1.A-SSE.3', 2, 'numeric', 'solve a quadratic equation by factoring', 'Solve $x^2 + 5x = 24$. What is the negative solution?', '[]', '-8', '-8', 'Rewrite as $x^2 + 5x - 24 = 0$. Factor: $(x+8)(x-3) = 0$, so $x = -8$ or $x = 3$. The negative solution is $-8$.', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+5x-24=0 -> (x+8)(x-3)=0 -> x=-8 or 3; negative -8.","run_id":"claude-code","at":"2026-10-28T19:16:32.306Z"}}', 'ai', NULL, NULL)
