INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12da988b-cb8c-4f5d-9af1-018d65870d58', 'NC17.M1.A-SSE.3', 3, 'choice', 'solve a quadratic equation by factoring', 'Solve $x^2 - 6x = 3x - 14$. What is the larger solution?', '["$2$","$7$","$9$","$14$"]', '$7$', '7', 'Collect terms: $x^2 - 9x + 14 = 0$. Factor: $(x-2)(x-7) = 0$. The solutions are 2 and 7; the larger is 7.', 'checked', '{"lint":[],"solve":{"answer":"$7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 9x + 14 = 0 = (x-2)(x-7). Larger 7.","run_id":"claude-code","at":"2026-10-28T19:16:32.265Z"}}', 'ai', NULL, NULL)
