INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b592029-2753-41e6-84bf-1f32bf168675', 'NC17.M1.A-SSE.3', 3, 'numeric', 'build a quadratic from its zeros', 'A quadratic function $f$ has integer coefficients, leading coefficient 2, and zeros at $x = -3$ and $x = \frac{1}{2}$. What is $f(2)$?', '[]', '15', '2*(2+3)*(2-1/2)', '$f(x) = 2(x+3)\left(x - \frac{1}{2}\right) = (x+3)(2x-1) = 2x^2 + 5x - 3$. Then $f(2) = 8 + 10 - 3 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leading 2, zeros -3 and 1/2: f = 2(x+3)(x-1/2) = (x+3)(2x-1) = 2x^2+5x-3 (integer coefficients). f(2) = 5*3 = 15.","run_id":"claude-code","at":"2026-10-28T19:16:32.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0232e297-b801-4c50-8c8d-e5d650f9efea', 'NC17.M1.A-APR.1', 1, 'choice', 'Polynomial arithmetic in a geometry context', 'A square has sides of length $x + 3$. Which expression gives the distance around the square?', '["$4x + 3$","$2x + 6$","$x^2 + 6x + 9$","$4x + 12$"]', '$4x + 12$', NULL, 'The distance around is 4 sides: $4(x + 3) = 4x + 12$. Doing $4 \cdot x$ but not $4 \cdot 3$ gives the wrong constant, and $x^2 + 6x + 9$ is the area.', 'checked', '{"lint":[],"solve":{"answer":"$4x + 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 4(x+3) = 4x+12.","run_id":"claude-code","at":"2026-10-28T19:20:44.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12965996-b6d2-4eaa-b9b7-891b66ecf31b', 'NC17.M1.A-APR.1', 1, 'choice', 'Subtract quadratic expressions', 'Subtract: $(7x^2 + 4x) - (3x^2 + x)$.', '["$4x^2 + 5x$","$10x^2 + 5x$","$4x^2 + 4x$","$4x^2 + 3x$"]', '$4x^2 + 3x$', NULL, 'Subtract like terms: $7x^2 - 3x^2 = 4x^2$ and $4x - x = 3x$. The result is $4x^2 + 3x$.', 'checked', '{"lint":[],"solve":{"answer":"$4x^2 + 3x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x^2-3x^2=4x^2; 4x-x=3x. Result 4x^2+3x.","run_id":"claude-code","at":"2026-10-28T19:20:44.433Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a050245-e8e9-4441-aafc-fc895a12d137', 'NC17.M1.A-APR.1', 1, 'choice', 'Polynomial arithmetic compared with integer arithmetic', 'When $x = 10$, the expression $2x + 5$ stands for 25 and $x + 3$ stands for 13. Which expression stands for $25 + 13$?', '["$2x + 8$","$3x + 8$","$3x + 15$","$3x + 53$"]', '$3x + 8$', NULL, 'Add like terms: $2x + x = 3x$ and $5 + 3 = 8$, so the sum is $3x + 8$. Check at $x = 10$: $3(10) + 8 = 38$, and $25 + 13 = 38$.', 'checked', '{"lint":[],"solve":{"answer":"$3x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+5)+(x+3)=3x+8; at x=10, 38=25+13.","run_id":"claude-code","at":"2026-10-28T19:20:44.702Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11829dbb-07f8-40a9-b79e-b838f99f667c', 'NC17.M1.A-APR.1', 2, 'numeric', 'Subtract polynomials', 'Subtract $(4x^2 - 5x + 1)$ from $(9x^2 + 2x - 7)$. What is the coefficient of $x$ in the result?', '[]', '7', '2+5', '$(9x^2 + 2x - 7) - (4x^2 - 5x + 1) = 5x^2 + 7x - 8$, because $2x - (-5x) = 7x$. The coefficient of $x$ is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9x^2+2x-7)-(4x^2-5x+1)=5x^2+7x-8; x-coefficient 7.","run_id":"claude-code","at":"2026-10-24T02:59:33.866Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ec6cb81-e005-4697-88b6-9f2d02d60e5a', 'NC17.M1.A-APR.1', 2, 'numeric', 'Multiply two linear expressions', 'When $(3x - 2)(2x + 5)$ is multiplied out, what is the coefficient of $x$?', '[]', '11', '15-4', '$(3x - 2)(2x + 5) = 6x^2 + 15x - 4x - 10 = 6x^2 + 11x - 10$. The coefficient of $x$ is 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x^2+15x-4x-10=6x^2+11x-10; coefficient 11.","run_id":"claude-code","at":"2026-10-24T02:59:33.866Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('026cfd44-6f45-4b70-acc2-e7d33fc5aaf0', 'NC17.M1.A-APR.1', 2, 'numeric', 'Add and subtract linear expressions', 'The sum $(3x + 5) + (-3x + 8)$ is a constant. What is that constant?', '[]', '13', '5+8', 'The $x$ terms cancel: $3x - 3x = 0$. What is left is $5 + 8 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 3x + 5 + 8 = 13.","run_id":"claude-code","at":"2026-10-28T19:20:44.312Z"}}', 'ai', NULL, NULL)
