INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('051ef12a-0fee-4679-a046-f734fabaa1ef', 'NC17.M1.A-APR.1', 3, 'numeric', 'Multiply a monomial by a linear expression', 'Simplify $2x(3x - 1) - 5(x + 2)$. What is the coefficient of $x$ in the result?', '[]', '-7', '-2-5', '$2x(3x - 1) = 6x^2 - 2x$ and $5(x + 2) = 5x + 10$. Then $6x^2 - 2x - 5x - 10 = 6x^2 - 7x - 10$. The coefficient of $x$ is $-7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x^2-2x-5x-10=6x^2-7x-10; coefficient -7.","run_id":"claude-code","at":"2026-10-24T02:59:33.866Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1b93e8-2009-43a0-a1a0-2c025339cb53', 'NC17.M1.A-APR.1', 3, 'choice', 'Polynomial arithmetic compared with integer arithmetic', 'Which expression, added to $x^2 + 3x - 2$, gives 0?', '["$-x^2 + 3x + 2$","$x^2 - 3x + 2$","$-x^2 - 3x + 2$","$-x^2 - 3x - 2$"]', '$-x^2 - 3x + 2$', NULL, 'Like an integer and its opposite, a polynomial and the polynomial with every sign changed add to 0: $-(x^2 + 3x - 2) = -x^2 - 3x + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$-x^2 - 3x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Additive inverse: -(x^2+3x-2) = -x^2 - 3x + 2.","run_id":"claude-code","at":"2026-10-28T19:20:44.735Z"}}', 'ai', NULL, NULL)
