INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066c8aeb-0c57-4caa-a7e0-72fdcddfae92', 'NC17.M1.A-APR.3', 1, 'numeric', 'Zeros of a function in factored form', 'For $f(x) = (x + 4)(x - 1)$, what is $f(1)$?', '[]', '0', '(1+4)*(1-1)', '$f(1) = (1 + 4)(1 - 1) = 5 \cdot 0 = 0$. Because $f(1) = 0$, the number 1 is a zero of $f$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(1) = 5×0 = 0.","run_id":"claude-code","at":"2026-10-28T19:24:07.781Z"}}', 'ai', NULL, NULL)
