INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1581375a-8509-484e-a057-11a4f25acef8', 'NC17.M1.A-APR.3', 1, 'choice', 'Zeros are the x-intercepts of the graph', 'A function has zeros $x = 2$ and $x = -3$. At which points does its graph cross the x-axis?', '["$(0, 2)$ and $(0, -3)$","$(-2, 0)$ and $(3, 0)$","$(2, 0)$ and $(3, 0)$","$(2, 0)$ and $(-3, 0)$"]', '$(2, 0)$ and $(-3, 0)$', NULL, 'A zero is an x-value where the function equals 0, so the graph crosses the x-axis at $(2, 0)$ and $(-3, 0)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 0)$ and $(-3, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros x=2, x=-3 give x-intercepts (2,0) and (-3,0).","run_id":"claude-code","at":"2026-10-28T19:24:07.834Z"}}', 'ai', NULL, NULL)
