INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07cbca68-a196-4d36-a98b-23a2ecac36c9', 'NC17.M1.A-APR.3', 2, 'choice', 'Connect a factor, a zero and a solution', 'The expression $x + 6$ is a factor of the expression that defines a quadratic function $f$. Which must be true?', '["$f(6) = 0$","$f(0) = 6$","$f(0) = -6$","$f(-6) = 0$"]', '$f(-6) = 0$', NULL, 'If $x + 6$ is a factor, then $f(x) = (x + 6)(\text{something})$. At $x = -6$ the factor $x + 6$ is 0, so $f(-6) = 0$.', 'checked', '{"lint":[],"solve":{"answer":"$f(-6) = 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor x+6 means x=-6 is a zero: f(-6)=0.","run_id":"claude-code","at":"2026-10-24T03:04:03.154Z"}}', 'ai', NULL, NULL)
