INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0231c692-18bc-41c3-9f7e-d6e9ba98173f', 'NC17.M1.A-APR.3', 2, 'choice', 'Solve a quadratic equation in factored form', 'What are the solutions of $(3x - 9)(x + 2) = 0$?', '["$x = 9$ and $x = -2$","$x = 3$ and $x = -2$","$x = -3$ and $x = 2$","$x = 3$ and $x = 2$"]', '$x = 3$ and $x = -2$', NULL, '$3x - 9 = 0$ gives $3x = 9$, so $x = 3$. $x + 2 = 0$ gives $x = -2$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 3$ and $x = -2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-9=0 gives 3; x+2=0 gives -2.","run_id":"claude-code","at":"2026-10-28T19:24:07.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f7a528-f159-4cb4-a945-3d519ef09b3f', 'NC17.M1.A-APR.3', 2, 'numeric', 'Connect a factor, a zero and a solution', 'The equation $x^2 - 8x + c = 0$ has the solution $x = 6$. What is $c$?', '[]', '12', '-(36-48)', 'Substitute $x = 6$: $36 - 48 + c = 0$, so $c = 12$. (Check: $x^2 - 8x + 12 = (x - 6)(x - 2)$.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36-48+c=0 → c=12.","run_id":"claude-code","at":"2026-10-28T19:24:07.786Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03697776-84bb-43c4-a920-ad2b5c564c86', 'NC17.M1.A-APR.3', 3, 'numeric', 'Solve a quadratic equation by factoring', 'What is the greater solution of $2x^2 + 7x + 3 = 0$?', '[]', '-1/2', '-1/2', 'Factor: $2x^2 + 7x + 3 = (2x + 1)(x + 3)$. Then $2x + 1 = 0$ gives $x = -\frac{1}{2}$, and $x + 3 = 0$ gives $x = -3$. The greater solution is $-\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"-1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+1)(x+3)=0, x=-1/2 or -3; greater -1/2.","run_id":"claude-code","at":"2026-10-28T19:24:07.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04121366-cfe0-46b1-8fdf-c9a394d86181', 'NC17.M1.A-APR.3', 3, 'numeric', 'Write the factors or equation from given solutions', 'The solutions of $x^2 + bx + c = 0$ are $x = 4$ and $x = -9$. What is $b - c$?', '[]', '41', '5-(-36)', '$(x - 4)(x + 9) = x^2 + 5x - 36$, so $b = 5$ and $c = -36$. Then $b - c = 5 - (-36) = 41$.', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-4)(x+9) = x^2 + 5x - 36, b = 5, c = -36, b - c = 41.","run_id":"claude-code","at":"2026-10-28T19:24:07.886Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('236a974d-e78e-4abb-8efd-2603f7c499fc', 'NC17.M1.A-CED.1', 1, 'numeric', 'Solve a linear equation from a situation', 'A gym charges a sign-up fee of 20 dollars plus 15 dollars each month. Dev has paid 110 dollars in total. For how many months has he been a member?', '[]', '6', '(110-20)/15', 'Let $m$ be the number of months: $20 + 15m = 110$. Subtract 20: $15m = 90$. Divide by 15: $m = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 15m = 110, 15m = 90, m = 6.","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('460bbcda-74a3-4130-b3d1-4892ba263407', 'NC17.M1.A-CED.1', 1, 'numeric', 'Solve a linear inequality from a situation', 'Tickets to a show cost 6 dollars each. Nia has 40 dollars. What is the greatest number of tickets she can buy?', '[]', '6', '36/6', 'The inequality is $6t \le 40$, so $t \le 6.67$. She can only buy a whole number of tickets, so the greatest number is 6. (6 tickets cost 36 dollars; 7 would cost 42.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6t <= 40, t <= 6.67, greatest whole number 6.","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('188ae212-f40e-4b86-97ad-008387998258', 'NC17.M1.A-CED.1', 1, 'numeric', 'Solve a linear equation from a situation', 'The sum of 3 times a number and 7 is 31. What is the number?', '[]', '8', '(31-7)/3', 'Let $n$ be the number: $3n + 7 = 31$. Subtract 7: $3n = 24$. Divide by 3: $n = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 7 = 31, 3x = 24, x = 8.","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45df5379-a5cb-4ee0-bf8d-cd68b8887ac5', 'NC17.M1.A-CED.1', 2, 'numeric', 'Solve a linear equation from a situation', 'A tank holds 120 gallons of water and drains 8 gallons each minute. After how many minutes will 40 gallons remain?', '[]', '10', '(120-40)/8', 'The amount left after $m$ minutes is $120 - 8m$. Solve $120 - 8m = 40$: $-8m = -80$, so $m = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 - 8t = 40, 8t = 80, t = 10.","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('543270a6-bfbe-4624-acb1-7f65ec0f9922', 'NC17.M1.A-CED.1', 2, 'choice', 'Write an exponential equation from a situation', 'A car is worth $20{,}000$ dollars and loses 10 percent of its value each year. Which equation can be used to find the number of years, $t$, until the car is worth $12{,}000$ dollars?', '["$20{,}000(0.1)^{t} = 12{,}000$","$20{,}000 - 0.1t = 12{,}000$","$20{,}000(0.9)^{t} = 12{,}000$","$20{,}000(1.1)^{t} = 12{,}000$"]', '$20{,}000(0.9)^{t} = 12{,}000$', NULL, 'Losing 10 percent each year leaves 90 percent, so the value is multiplied by 0.9 each year: $20{,}000(0.9)^{t}$. Setting it equal to $12{,}000$ gives the equation. Using 0.1 keeps only 10 percent, 1.1 is growth, and subtracting is linear decay.', 'checked', '{"lint":[],"solve":{"answer":"$20{,}000(0.9)^{t} = 12{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Keeps 90% each year: 20000(0.9)^t = 12000.","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22a398bd-5536-47c4-b7ca-5e980bfaded6', 'NC17.M1.A-CED.1', 2, 'numeric', 'Solve an exponential equation from a situation', 'A 640 gram sample of a substance loses half of its mass every hour. After how many hours will 20 grams remain?', '[]', '5', NULL, 'The mass after $h$ hours is $640\left(\dfrac{1}{2}\right)^{h}$. Solve $640\left(\dfrac{1}{2}\right)^{h} = 20$. Divide by 640: $\left(\dfrac{1}{2}\right)^{h} = \dfrac{1}{32}$, so $h = 5$. (Check: 640, 320, 160, 80, 40, 20.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"640(1/2)^t = 20, 2^t = 32, t = 5.","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('285cd0a4-d361-45e8-9ac7-807498beee09', 'NC17.M1.A-CED.1', 3, 'numeric', 'Solve a linear equation from a situation', 'The length of a rectangle is 3 centimeters more than twice its width. The perimeter is 54 centimeters. What is the width, in centimeters?', '[]', '8', '(54-6)/6', 'Let $w$ be the width, so the length is $2w + 3$. The perimeter is $2w + 2(2w + 3) = 54$, which is $6w + 6 = 54$. Then $6w = 48$ and $w = 8$. (The length is 19, and $2(8 + 19) = 54$.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 2w + 3; 2(w + 2w + 3) = 54, 3w + 3 = 27, w = 8 (L = 19, P = 54).","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('199afa5e-bd87-439c-8ab8-ed71016170d9', 'NC17.M1.A-CED.1', 3, 'choice', 'Write an exponential equation from a situation', 'Which situation can be modeled by the equation $50(0.8)^{t} = 20$, where $t$ is the number of years and the money is in thousands of dollars?', '["A machine worth 50 gains 20 percent of its value each year and is worth 20 after $t$ years","A machine worth 50 loses 0.8 of its value each year and is worth 20 after $t$ years","A machine worth 20 loses 20 percent of its value each year and is worth 50 after $t$ years","A machine worth 50 loses 20 percent of its value each year and is worth 20 after $t$ years"]', 'A machine worth 50 loses 20 percent of its value each year and is worth 20 after $t$ years', NULL, 'The number 50 is the starting amount, and 0.8 means 80 percent is kept each year, which is a loss of 20 percent. The result after $t$ years is 20. So the machine starts at 50, loses 20 percent a year, and ends at 20. A gain would use 1.2, and losing 0.8 each year would be the linear $50 - 0.8t$.', 'checked', '{"lint":[],"solve":{"answer":"A machine worth 50 loses 20 percent of its value each year and is worth 20 after $t$ years","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 0.8 means keeps 80%, loses 20%; starts at 50, worth 20 after t years. D.","run_id":"claude-code","at":"2026-10-24T03:06:49.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b29c2dc-8d97-4ede-b11e-ea5217ed7168', 'NC17.M1.A-CED.2', 1, 'choice', 'Write an exponential equation from a situation', 'A colony starts with 100 bacteria, and the number doubles every hour. Let $P$ be the number of bacteria after $t$ hours. Which equation models this?', '["$P = 100 + 2t$","$P = 100 \\cdot 2^t$","$P = 200t$","$P = 100 \\cdot t^2$"]', '$P = 100 \cdot 2^t$', NULL, 'The starting amount is 100 and it is multiplied by 2 once for each hour, so after $t$ hours it is $100 \cdot 2^t$. Repeated multiplication is an exponent on the growth factor.', 'checked', '{"lint":[],"solve":{"answer":"$P = 100 \\cdot 2^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 100, doubling each hour: P = 100*2^t.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cba7b10-8d82-4ce9-b0db-3d019624a8a5', 'NC17.M1.A-CED.2', 1, 'choice', 'Write a quadratic equation from a situation', 'A square garden has side length $s$ meters and area $A$ square meters. Which equation relates $A$ to $s$?', '["$A = 2s$","$A = 4s$","$A = \\frac{s}{2}$","$A = s^2$"]', '$A = s^2$', NULL, 'The area of a square is its side length times itself, so $A = s \cdot s = s^2$. The equation $A = 4s$ would be the perimeter.', 'checked', '{"lint":[],"solve":{"answer":"$A = s^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area of a square = side squared: A = s^2.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('549ab8e8-6e12-4eb7-94f6-5dbd2bb6526b', 'NC17.M1.A-CED.2', 1, 'choice', 'Read features of a graph from its equation', 'Which statement about the graph of $y = -3x + 4$ is true?', '["It slants upward and crosses the $y$-axis at 4.","It slants downward and crosses the $y$-axis at 4.","It slants downward and crosses the $y$-axis at $-3$.","It slants upward and crosses the $y$-axis at $-3$."]', 'It slants downward and crosses the $y$-axis at 4.', NULL, 'The slope is $-3$, which is negative, so the graph slants downward. The constant term is 4, so it crosses the $y$-axis at 4.', 'checked', '{"lint":[],"solve":{"answer":"It slants downward and crosses the $y$-axis at 4.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope -3 is negative so it slants downward; y-intercept 4.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24f68eb7-7374-49ea-9fc1-285f7b01537d', 'NC17.M1.A-CED.2', 2, 'numeric', 'Write a linear equation from a situation', 'A hiker walks along a straight trail at a steady pace. She is 14 miles from the trailhead after 2 hours and 26 miles from it after 4 hours. Her distance $y$ in miles after $x$ hours is $y = mx + b$. What is $m + b$?', '[]', '8', '(26-14)/(4-2)+(14-(26-14)/(4-2)*2)', 'The rate is $m = \frac{26 - 14}{4 - 2} = 6$ miles per hour. Then $14 = 6(2) + b$, so $b = 2$. The answer is $m + b = 6 + 2 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m = (26-14)/(4-2) = 6; 14 = 6*2 + b so b = 2; m + b = 8.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('053e848d-8ed8-4448-854a-11c7e07b2c56', 'NC17.M1.A-CED.2', 2, 'numeric', 'Match an equation to a table of values', 'A table gives $y$ for each $x$. When $x$ is 0, 1, 2 and 3, $y$ is $-3$, $-1$, 5 and 15. The equation has the form $y = ax^2 + c$. What is $a + c$?', '[]', '-1', '2-3', 'At $x = 0$, $y = c = -3$. At $x = 1$, $a + c = -1$, so $a = 2$. Check $x = 2$: $2(4) - 3 = 5$, and $x = 3$: $2(9) - 3 = 15$. So $a + c = 2 + (-3) = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0: c = -3. x=1: a - 3 = -1, a = 2. Check x=2: 8-3=5; x=3: 18-3=15. a + c = -1.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2001decc-e140-4cee-954d-39eb45eb793a', 'NC17.M1.A-CED.2', 2, 'numeric', 'Read features of a graph from its equation', 'A tank holds 50 gallons of water, and a pump removes 4 gallons each minute. The number of gallons left after $t$ minutes is $g = 50 - 4t$. The graph crosses the $t$-axis at what value of $t$, in minutes?', '[]', '12.5', '50/4', 'On the $t$-axis, $g = 0$. Solve $50 - 4t = 0$: $t = \frac{50}{4} = 12.5$. The tank is empty after 12.5 minutes.', 'checked', '{"lint":[],"solve":{"answer":"12.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 = 50 - 4t, t = 12.5.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74349dc3-e1a1-4d77-9e4f-97b7d384babf', 'NC17.M1.A-CED.2', 3, 'numeric', 'Read features of a graph from its equation', 'A stone is thrown from the ground and its height in feet after $t$ seconds is $h = -16t^2 + 64t$. The graph is at height 0 when $t = 0$ and again at a later time. What is the later time, in seconds?', '[]', '4', '64/16', 'Set $h = 0$ and factor: $-16t(t - 4) = 0$. So $t = 0$ or $t = 4$. The stone lands at $t = 4$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-16t^2 + 64t = -16t(t - 4) = 0, t = 0 or 4. Later time 4.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b75bc2cb-a969-434d-ae17-4be5e3e6d677', 'NC17.M1.A-CED.2', 3, 'numeric', 'Use an equation to find points on its graph', 'The graph of $3m + 5l = 90$ crosses the $l$-axis at $(0, k)$ and the $m$-axis at $(j, 0)$. What is $j + k$?', '[]', '48', '90/3+90/5', 'At $(0, k)$: $5k = 90$, so $k = 18$. At $(j, 0)$: $3j = 90$, so $j = 30$. Then $j + k = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m = 0: 5l = 90, k = 18. l = 0: 3m = 90, j = 30. j + k = 48.","run_id":"claude-code","at":"2026-10-24T03:07:46.298Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d98cac9-fe90-4853-83a5-8992324bf05d', 'NC17.M1.A-CED.3', 1, 'numeric', 'Solve a system about two related quantities', 'Mia and Jo picked 12 apples in all. Mia picked 4 more apples than Jo. With $m$ for Mia''s apples and $j$ for Jo''s, the system is $m + j = 12$ and $m = j + 4$. How many apples did Mia pick?', '[]', '8', '(12+4)/2', 'Replace $m$ in the first equation: $(j + 4) + j = 12$, so $2j = 8$ and $j = 4$. Then $m = 4 + 4 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(j + 4) + j = 12, j = 4, m = 8.","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('048f1ed0-0db3-41cb-8f56-692e873395df', 'NC17.M1.A-CED.3', 1, 'choice', 'Write a system of inequalities from a story', 'A bus holds at most 50 people. A trip needs at least 2 adults. Let $a$ be the number of adults and $c$ the number of children. Which system models the story?', '["$a + c \\ge 50$ and $a \\ge 2$","$a + c \\le 50$ and $a \\le 2$","$a + c < 50$ and $a > 2$","$a + c \\le 50$ and $a \\ge 2$"]', '$a + c \le 50$ and $a \ge 2$', NULL, '"At most 50 people" is $a + c \le 50$. "At least 2 adults" is $a \ge 2$. The other systems use the wrong direction or leave out "equal to".', 'checked', '{"lint":[],"solve":{"answer":"$a + c \\le 50$ and $a \\ge 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At most 50 people: a + c <= 50; at least 2 adults: a >= 2.","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('599626ee-210e-4f3d-9764-deef72c6fd27', 'NC17.M1.A-CED.3', 1, 'choice', 'Check a pair of values against the constraints', 'Maya spends at most 10 dollars on $x$ pencils that cost 2 dollars each and $y$ erasers that cost 1 dollar each, so $2x + y \le 10$. Which purchase is possible?', '["$x = 4$ and $y = 3$","$x = 3$ and $y = 4$","$x = 5$ and $y = 1$","$x = 2$ and $y = 7$"]', '$x = 3$ and $y = 4$', NULL, 'For $x = 3$ and $y = 4$: $2(3) + 4 = 10$, which is at most 10. The other purchases cost 11 dollars each.', 'checked', '{"lint":[],"solve":{"answer":"$x = 3$ and $y = 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6 + 4 = 10 ok. B: 4 + 7 = 11. C: 10 + 1 = 11. D: 8 + 3 = 11. Only A.","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c7fa767-c403-416e-bc61-fabc753b9095', 'NC17.M1.A-CED.3', 2, 'choice', 'Write a system of equations from a story', 'Jo has 18 coins, all dimes and quarters, worth 3.30 dollars in all. Let $d$ be the number of dimes and $q$ the number of quarters. Which system models the story?', '["$d + q = 18$ and $0.10d + 0.25q = 3.30$","$d + q = 18$ and $0.25d + 0.10q = 3.30$","$d + q = 3.30$ and $0.10d + 0.25q = 18$","$d + q = 18$ and $10d + 25q = 3.30$"]', '$d + q = 18$ and $0.10d + 0.25q = 3.30$', NULL, 'The number of coins is $d + q = 18$. A dime is worth 0.10 dollars and a quarter 0.25 dollars, so the value is $0.10d + 0.25q = 3.30$.', 'checked', '{"lint":[],"solve":{"answer":"$d + q = 18$ and $0.10d + 0.25q = 3.30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count d + q = 18; value 0.10d + 0.25q = 3.30 (d = 8, q = 10).","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('254c7720-bc6b-4011-843b-7519b44cde2f', 'NC17.M1.A-CED.3', 2, 'numeric', 'Find a limit from the constraints', 'A coach picks $x$ forwards and $y$ defenders. The team has at most 12 players, so $x + y \le 12$. There must be at least twice as many defenders as forwards, so $y \ge 2x$. What is the greatest number of forwards possible?', '[]', '4', '12/3', 'Since $y \ge 2x$, we have $x + y \ge 3x$. Together with $x + y \le 12$, this gives $3x \le 12$, so $x \le 4$. With $x = 4$ and $y = 8$ both conditions hold.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y >= 2x and x + y <= 12 give 3x <= x + y <= 12, x <= 4; x = 4, y = 8 works.","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3365acd3-9bf1-4185-b5e7-c8f31a761499', 'NC17.M1.A-CED.3', 2, 'numeric', 'Solve a system about two related quantities', 'Mia is 3 times as old as her cousin. In 4 years, the sum of their ages will be 40. With $m$ for Mia''s age and $c$ for her cousin''s age now, the system is $m = 3c$ and $(m + 4) + (c + 4) = 40$. How old is Mia now?', '[]', '24', '3*((40-8)/4)', 'The second equation gives $m + c = 32$. Replace $m$ with $3c$: $4c = 32$, so $c = 8$ and $m = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3c + c + 8 = 40, 4c = 32, c = 8, m = 24.","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fc746a7-8abb-4888-9639-5f5ad6a7854a', 'NC17.M1.A-CED.3', 3, 'numeric', 'Solve a rates or break-even system', 'A boat travels 30 miles downstream in 3 hours and 30 miles back upstream in 5 hours. With $b$ for the boat''s speed in still water and $c$ for the current, both in miles per hour, the system is $3(b + c) = 30$ and $5(b - c) = 30$. What is $b$?', '[]', '8', '(30/3+30/5)/2', 'The downstream speed is $b + c = 10$ and the upstream speed is $b - c = 6$. Adding the equations gives $2b = 16$, so $b = 8$ miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b + c = 10, b - c = 6, so 2b = 16, b = 8.","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1460da2e-3e7e-4674-95e7-19b9a2093757', 'NC17.M1.A-CED.3', 3, 'choice', 'Translate a phrase into an inequality', 'A box holds $x$ books and $y$ magazines. The number of magazines is at most 3 more than twice the number of books. Which inequality models the story?', '["$y \\le 2x + 3$","$y \\le 2(x + 3)$","$y \\ge 2x + 3$","$x \\le 2y + 3$"]', '$y \le 2x + 3$', NULL, 'Twice the number of books is $2x$, and 3 more than that is $2x + 3$. "At most" means $y \le 2x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y \\le 2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice the books plus 3 is 2x + 3; magazines at most that: y <= 2x + 3.","run_id":"claude-code","at":"2026-10-24T03:08:14.987Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4630dd8d-bf21-483a-be63-c61fa11c5aff', 'NC17.M1.A-CED.4', 1, 'choice', 'Solve a sum or difference formula for a variable', 'Solve the formula $y = mx + b$ for $b$.', '["$b = y + mx$","$b = \\frac{y}{mx}$","$b = y - mx$","$b = mx - y$"]', '$b = y - mx$', NULL, 'Subtract mx from both sides: $b = y - mx$.', 'checked', '{"lint":[],"solve":{"answer":"$b = y - mx$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract mx from both sides: b = y - mx.","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e083467-a440-4676-8b07-27581b6610bf', 'NC17.M1.A-CED.4', 1, 'numeric', 'Solve a formula with a fraction coefficient', 'The area of a triangle is $A = \frac{1}{2}bh$. A triangle has area 24 and base 8. Find its height h.', '[]', '6', '2*24/8', 'Multiply both sides by 2: $2A = bh$. Divide by b: $h = \frac{2A}{b} = \frac{2 \times 24}{8} = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 = (1/2)(8)h = 4h, h = 6.","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ba950f4-f004-46b7-9d33-87c910e63bd1', 'NC17.M1.A-CED.4', 1, 'numeric', 'Solve a formula needing two steps', 'The perimeter of a rectangle is $P = 2l + 2w$. A rectangle has perimeter 36 and length 11. Find its width w.', '[]', '7', '(36-2*11)/2', 'Subtract $2l = 22$ from 36 to get $2w = 14$. Divide by 2: $w = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 22 + 2w, 2w = 14, w = 7.","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b730727-9a2b-48c5-879e-408ef1acfead', 'NC17.M1.A-CED.4', 2, 'choice', 'Solve a formula with a fraction coefficient', 'The area of a triangle is $A = \frac{1}{2}bh$. Solve for $b$.', '["$b = \\frac{A}{2h}$","$b = 2Ah$","$b = \\frac{h}{2A}$","$b = \\frac{2A}{h}$"]', '$b = \frac{2A}{h}$', NULL, 'Multiply both sides by 2: $2A = bh$. Divide both sides by h: $b = \frac{2A}{h}$.', 'checked', '{"lint":[],"solve":{"answer":"$b = \\frac{2A}{h}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply by 2: 2A = bh, divide by h: b = 2A/h.","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('288c767d-4f26-4ae9-9f43-37e5db1a1e6a', 'NC17.M1.A-CED.4', 2, 'choice', 'Solve a formula with a fraction coefficient', 'The formula $C = \frac{5}{9}(F - 32)$ changes Fahrenheit F to Celsius C. Solve for $F$.', '["$F = \\frac{9}{5}C + 32$","$F = \\frac{9}{5}(C + 32)$","$F = \\frac{5}{9}C + 32$","$F = \\frac{9}{5}C - 32$"]', '$F = \frac{9}{5}C + 32$', NULL, 'Multiply both sides by $\frac{9}{5}$: $\frac{9}{5}C = F - 32$. Add 32 to both sides: $F = \frac{9}{5}C + 32$.', 'checked', '{"lint":[],"solve":{"answer":"$F = \\frac{9}{5}C + 32$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply by 9/5: (9/5)C = F - 32, add 32: F = (9/5)C + 32.","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cf1b862-69d6-4e11-bd46-0c3b347f535c', 'NC17.M1.A-CED.4', 2, 'choice', 'Solve a formula needing two steps', 'The line $ax + by = c$ is written in standard form. Solve the equation for $y$.', '["$y = \\frac{c + ax}{b}$","$y = \\frac{c}{b} - ax$","$y = \\frac{c - ax}{b}$","$y = c - ax$"]', '$y = \frac{c - ax}{b}$', NULL, 'Subtract ax from both sides: $by = c - ax$. Divide both sides by b: $y = \frac{c - ax}{b}$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{c - ax}{b}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"by = c - ax, y = (c - ax)/b.","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca28115-95a5-4c43-ad12-1714856ce784', 'NC17.M1.A-CED.4', 3, 'choice', 'Solve a formula where the variable appears in a sum or group', 'The surface area of a cylinder is $S = 2\pi r^2 + 2\pi r h$. Solve for $h$.', '["$h = \\frac{S}{2\\pi r} - 2\\pi r^2$","$h = S - 2\\pi r^2 - 2\\pi r$","$h = \\frac{S - 2\\pi r^2}{2\\pi r}$","$h = \\frac{S - 2\\pi r^2}{2\\pi}$"]', '$h = \frac{S - 2\pi r^2}{2\pi r}$', NULL, 'Subtract $2\pi r^2$ from both sides: $S - 2\pi r^2 = 2\pi r h$. Divide both sides by $2\pi r$: $h = \frac{S - 2\pi r^2}{2\pi r}$.', 'checked', '{"lint":[],"solve":{"answer":"$h = \\frac{S - 2\\pi r^2}{2\\pi r}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S - 2 pi r^2 = 2 pi r h, h = (S - 2 pi r^2)/(2 pi r).","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a768f05-8afb-4532-8fbe-ff840e088eca', 'NC17.M1.A-CED.4', 3, 'numeric', 'Rearrange a formula from a context', 'Simple interest gives $A = P(1 + rt)$. Solve for $r$, then find r (as a decimal) when $A = 1260$, $P = 1000$ and $t = 4$.', '[]', '0.065', '(1260-1000)/(1000*4)', 'Divide by P: $\frac{A}{P} = 1 + rt$. Subtract 1: $\frac{A}{P} - 1 = rt$. Divide by t: $r = \frac{A - P}{Pt}$. Then $r = \frac{260}{4000} = 0.065$.', 'checked', '{"lint":[],"solve":{"answer":"0.065","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A/P = 1 + rt, r = (A/P - 1)/t = (1.26 - 1)/4 = 0.26/4 = 0.065.","run_id":"claude-code","at":"2026-10-24T03:10:38.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f15d022-e498-4c8f-8565-bb805a9c3af8', 'NC17.M1.A-REI.1', 1, 'choice', 'Name the step that was done', 'Solving $3x + 5 = 20$, a student writes $3x = 15$. What was done to both sides?', '["Added 5 to both sides.","Divided both sides by 5.","Subtracted 5 from both sides.","Subtracted 20 from both sides."]', 'Subtracted 5 from both sides.', NULL, 'The 5 on the left was removed by subtracting 5. To keep the sides equal, 5 is also subtracted from 20, giving 15. So 5 was subtracted from both sides.', 'checked', '{"lint":[],"solve":{"answer":"Subtracted 5 from both sides.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+5-5=20-5 gives 3x=15: 5 subtracted from both sides.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f092359-60b3-4726-8432-e12015bd29e8', 'NC17.M1.A-REI.1', 1, 'choice', 'Justify a step with a property', 'A student changes $x + 9 = 15$ into $x = 6$. Which property of equality justifies this step?', '["Subtraction Property of Equality","Addition Property of Equality","Multiplication Property of Equality","Division Property of Equality"]', 'Subtraction Property of Equality', NULL, 'Subtracting 9 from both sides gives $x = 6$, and the property that allows subtracting the same number from both sides is the Subtraction Property of Equality.', 'checked', '{"lint":[],"solve":{"answer":"Subtraction Property of Equality","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15-9=6: 9 subtracted from both sides.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48a0731f-c738-47b4-8ff9-d5628cb2d1c0', 'NC17.M1.A-REI.1', 1, 'choice', 'Explain why a method works', 'A student solves $x^2 = 49$ and writes $x = 7$ or $x = -7$. Which statement explains why both values are written?', '["Only 7 works, and $-7$ is written to show the opposite value.","Both 7 and $-7$ square to 49, so each one makes the equation true.","Dividing both sides by 2 undoes the square, so $x = 24.5$.","A square root of 49 is 7, and the second value is written for checking."]', 'Both 7 and $-7$ square to 49, so each one makes the equation true.', NULL, 'Since $7^2 = 49$ and $(-7)^2 = 49$, both numbers satisfy the equation. Taking the square root of both sides therefore gives two solutions.', 'checked', '{"lint":[],"solve":{"answer":"Both 7 and $-7$ square to 49, so each one makes the equation true.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^2=49 and (-7)^2=49, so both satisfy the equation.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ba36af7-d1bb-4c81-aef3-66b8afce241a', 'NC17.M1.A-REI.1', 2, 'numeric', 'Justify a step with a property', 'A student combines like terms to change $4x + 2x = 18$ into $6x = 18$, then divides both sides by 6. What is $x$?', '[]', '3', '18/6', '$4x + 2x = 6x$ by combining like terms. Dividing both sides of $6x = 18$ by 6 gives $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x=18, x=3.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('569021e6-be69-4612-a75e-782a8c2dd983', 'NC17.M1.A-REI.1', 2, 'choice', 'Square roots and the Zero Product Property', 'A student factors $x^2 - 5x + 6 = 0$ as $(x - 2)(x - 3) = 0$ and concludes $x = 2$ or $x = 3$. Which fact justifies the conclusion?', '["If a product is 0, both of its factors are 0.","If a sum is 0, at least one of its terms is 0.","If a product is 6, at least one of its factors is 6.","If a product is 0, at least one of its factors is 0."]', 'If a product is 0, at least one of its factors is 0.', NULL, 'This is the Zero Product Property. Because the product equals 0, either $x - 2 = 0$ or $x - 3 = 0$.', 'checked', '{"lint":[],"solve":{"answer":"If a product is 0, at least one of its factors is 0.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zero Product Property: if ab=0 then a=0 or b=0.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b38925f-e173-47f4-bd4e-6e6f9f10239b', 'NC17.M1.A-REI.1', 2, 'choice', 'Name the step that was done', 'Which equation results from adding 6 to both sides of $3x - 6 = 12$?', '["$3x - 6 + 6 = 12 - 6$","$3x - 6 + 6 = 12 + 6$","$3x - 6 + 6 = 12$","$3x - 6 - 6 = 12 + 6$"]', '$3x - 6 + 6 = 12 + 6$', NULL, 'Adding 6 to both sides means writing $+ 6$ on each side: $3x - 6 + 6 = 12 + 6$. This simplifies to $3x = 18$.', 'checked', '{"lint":[],"solve":{"answer":"$3x - 6 + 6 = 12 + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 6 to both sides: 3x-6+6=12+6.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0737728c-98c9-4aab-943a-171c9e9570ea', 'NC17.M1.A-REI.1', 3, 'choice', 'Justify a step with a property', 'To solve $\frac{x}{2} + 3 = 7$, a student writes $\frac{x}{2} = 4$ and then $x = 8$. Which reasons justify the two steps, in order?', '["Subtract 3 from both sides, then multiply both sides by 2.","Subtract 3 from both sides, then divide both sides by 2.","Add 3 to both sides, then multiply both sides by 2.","Subtract 7 from both sides, then multiply both sides by 2."]', 'Subtract 3 from both sides, then multiply both sides by 2.', NULL, 'Subtracting 3 from both sides gives $\frac{x}{2} = 4$. Multiplying both sides by 2 undoes the division and gives $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"Subtract 3 from both sides, then multiply both sides by 2.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract 3: x/2=4. Multiply by 2: x=8.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1db3e14d-83a5-4249-b138-dea1fef27291', 'NC17.M1.A-REI.1', 3, 'choice', 'Square roots and the Zero Product Property', 'A student solves $(x - 1)(x - 2) = 6$ by writing $x - 1 = 6$ or $x - 2 = 6$. Why is this not justified?', '["The Zero Product Property only applies when the factors are equal.","Equations with factors can only be solved after dividing by $x - 2$.","The Zero Product Property only applies when the product equals 0.","A factor that is subtracted cannot be set equal to a number."]', 'The Zero Product Property only applies when the product equals 0.', NULL, 'A product of 6 does not force a factor to be 6, since $2 \cdot 3$ and $1 \cdot 6$ both make 6. First rewrite as $x^2 - 3x - 4 = 0$, so $(x - 4)(x + 1) = 0$.', 'checked', '{"lint":[],"solve":{"answer":"The Zero Product Property only applies when the product equals 0.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zero Product Property needs product 0; product 6 can arise from many factor pairs.","run_id":"claude-code","at":"2026-10-24T03:12:28.707Z"}}', 'ai', NULL, NULL)
