VALUES ('40617408-9ba9-489a-af61-f18b210bf417', 'NC17.M1.A-REI.3', 2, 'numeric', 'Solve an equation that needs the distributive property or like terms', 'Solve $4x + 2(x - 5) = 20$.', '[]', '5', '(20+10)/6', 'Distribute: $4x + 2x - 10 = 20$. Combine: $6x - 10 = 20$. Add 10: $6x = 30$. Divide by 6: $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 10 = 20, x = 5.","run_id":"claude-code","at":"2026-10-24T03:12:50.842Z"}}', 'ai', NULL, NULL)
