VALUES ('547a8903-e646-439d-8b38-f6459f6b7821', 'NC17.M1.A-REI.3', 2, 'choice', 'Solve an equation with fractions or decimals', 'Solve $\frac{2}{3}x = 8$.', '["$x = 24$","$x = 12$","$x = \\frac{16}{3}$","$x = 10$"]', '$x = 12$', NULL, 'Multiply both sides by $\frac{3}{2}$: $x = 8 \times \frac{3}{2} = 12$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 8 x 3/2 = 12.","run_id":"claude-code","at":"2026-10-24T03:12:50.842Z"}}', 'ai', NULL, NULL)
