VALUES ('5cf61780-1cb8-44e1-8c99-c7bfda17b041', 'NC17.M1.A-REI.3', 3, 'choice', 'Decide how many solutions an equation has', 'For which value of $k$ does $3(x - 2) = 3x + k$ have infinitely many solutions?', '["$k = 6$","$k = 0$","$k = 3$","$k = -6$"]', '$k = -6$', NULL, 'Distribute: $3x - 6 = 3x + k$. The two sides are the same expression for every $x$ exactly when $k = -6$.', 'checked', '{"lint":[],"solve":{"answer":"$k = -6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 6 = 3x + k for all x iff k = -6.","run_id":"claude-code","at":"2026-10-24T03:12:50.842Z"}}', 'ai', NULL, NULL)
