VALUES ('3b8488c6-141a-4216-8a0a-2f3a102a6d36', 'NC17.M1.A-REI.3', 3, 'choice', 'Solve a compound inequality', 'Solve $-4 < 2x - 2 \le 8$.', '["$-3 < x \\le 3$","$-1 < x \\le 5$","$-1 \\le x < 5$","$-2 < x \\le 10$"]', '$-1 < x \le 5$', NULL, 'Add 2 to all three parts: $-2 < 2x \le 10$. Divide all parts by 2: $-1 < x \le 5$.', 'checked', '{"lint":[],"solve":{"answer":"$-1 < x \\le 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 2: -2 < 2x <= 10; halve: -1 < x <= 5.","run_id":"claude-code","at":"2026-10-24T03:12:50.842Z"}}', 'ai', NULL, NULL)
