INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16f4f897-e246-4131-ba73-3510860e6a40', 'NC17.M1.A-REI.4', 1, 'choice', 'Solve by factoring: leading coefficient 1', 'Which gives all the solutions of $x^2 + 7x + 12 = 0$?', '["$x = 3$ or $x = 4$","$x = -2$ or $x = -6$","$x = -3$ or $x = -4$","$x = -7$ or $x = -12$"]', '$x = -3$ or $x = -4$', NULL, 'Find two numbers with product 12 and sum 7: they are 3 and 4. So $(x + 3)(x + 4) = 0$, which gives $x = -3$ or $x = -4$.', 'checked', '{"lint":[],"solve":{"answer":"$x = -3$ or $x = -4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+3)(x+4)=0, x=-3 or -4.","run_id":"claude-code","at":"2026-10-24T03:17:06.130Z"}}', 'ai', NULL, NULL)
