INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('012038a9-7111-4d2e-b864-4ce331a81665', 'NC17.M1.A-REI.4', 1, 'numeric', 'Zero product property and checking solutions', 'Solve $(x - 4)(x + 7) = 0$. What is the positive solution?', '[]', '4', '4', 'A product is 0 only when one factor is 0. So $x - 4 = 0$ or $x + 7 = 0$, giving $x = 4$ or $x = -7$. The positive solution is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=4 or -7; positive 4.","run_id":"claude-code","at":"2026-10-24T03:17:06.130Z"}}', 'ai', NULL, NULL)
