INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01ed3e13-8be3-4ba9-bfee-fe4cb005409a', 'NC17.M1.A-REI.4', 2, 'numeric', 'Solve by factoring: leading coefficient 1', 'Solve $x^2 + 2x - 24 = 0$. What is the positive solution?', '[]', '4', '4', 'Two numbers with product $-24$ and sum 2 are 6 and $-4$. So $(x + 6)(x - 4) = 0$, giving $x = -6$ or $x = 4$. The positive solution is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+6)(x-4)=0, x=-6 or 4; positive 4.","run_id":"claude-code","at":"2026-10-24T03:17:06.130Z"}}', 'ai', NULL, NULL)
