INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3277fb04-f9fa-4d33-8cb6-0197139dc5bf', 'NC17.M1.A-REI.4', 2, 'numeric', 'Solve by factoring: common factor, difference of squares, leading coefficient above 1', 'Use the difference of squares to solve $4x^2 - 49 = 0$. What is the positive solution?', '[]', '7/2', '7/2', 'Since $4x^2 - 49 = (2x - 7)(2x + 7)$, the solutions come from $2x - 7 = 0$ and $2x + 7 = 0$. They are $x = \frac{7}{2}$ and $x = -\frac{7}{2}$. The positive one is $\frac{7}{2}$, or 3.5.', 'checked', '{"lint":[],"solve":{"answer":"7/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x-7)(2x+7)=0, x=±7/2; positive 7/2.","run_id":"claude-code","at":"2026-10-24T03:17:06.130Z"}}', 'ai', NULL, NULL)
