INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ba7d952-ee51-4ac7-88dd-64f32b1697bd', 'NC17.M1.A-REI.4', 2, 'numeric', 'Rewrite in standard form, then factor', 'Solve $x^2 = 3x + 10$. What is the positive solution?', '[]', '5', '5', 'Write it with 0 on one side: $x^2 - 3x - 10 = 0$. Factor: $(x - 5)(x + 2) = 0$. So $x = 5$ or $x = -2$. The positive solution is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-3x-10=0, (x-5)(x+2)=0; positive 5.","run_id":"claude-code","at":"2026-10-24T03:17:06.130Z"}}', 'ai', NULL, NULL)
