INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1ec946-d5ac-47cd-a8d5-0572a52ec49f', 'NC17.M1.A-REI.4', 3, 'numeric', 'Solve by taking square roots', 'Solve $4(x + 1)^2 = 36$. What is the larger of the two solutions?', '[]', '2', '3-1', 'Divide both sides by 4: $(x + 1)^2 = 9$. Then $x + 1 = 3$ or $x + 1 = -3$, so $x = 2$ or $x = -4$. The larger is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)^2=9, x+1=±3, x=2 or -4; larger 2.","run_id":"claude-code","at":"2026-10-24T03:17:06.130Z"}}', 'ai', NULL, NULL)
