INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('031f874f-99ed-452f-90e6-fbd43d68684d', 'NC17.M1.A-REI.4', 3, 'choice', 'Rewrite in standard form, then factor', 'Solve $(x + 2)(x + 3) = 12$.', '["$x = 10$ or $x = 9$","$x = -2$ or $x = -3$","$x = 6$ or $x = -1$","$x = 1$ or $x = -6$"]', '$x = 1$ or $x = -6$', NULL, 'The product equals 12, not 0, so first multiply out: $x^2 + 5x + 6 = 12$. Then $x^2 + 5x - 6 = 0$, which factors as $(x + 6)(x - 1) = 0$. So $x = -6$ or $x = 1$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 1$ or $x = -6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+5x+6=12, x^2+5x-6=0, (x+6)(x-1)=0, x=1 or -6.","run_id":"claude-code","at":"2026-10-24T03:17:06.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28e09c04-773b-44c6-8299-098f880d8100', 'NC17.M1.A-REI.5', 1, 'choice', 'Add two equations', 'Which equation is the sum of $2x + y = 5$ and $x - y = 1$?', '["$3x + 2y = 6$","$3x = 6$","$x + 2y = 4$","$3x = 4$"]', '$3x = 6$', NULL, 'Add the left sides: $2x + x = 3x$ and $y + (-y) = 0$. Add the right sides: $5 + 1 = 6$. The sum is $3x = 6$.', 'checked', '{"lint":[],"solve":{"answer":"$3x = 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+y)+(x-y)=5+1 gives 3x=6.","run_id":"claude-code","at":"2026-10-24T08:19:44.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fb9ce41-8a34-47c7-95e6-fcf8bdac4996', 'NC17.M1.A-REI.5', 1, 'choice', 'A solution still fits the new equation', 'The solution of a system is $x = 2$, $y = 3$. The equations are $x + y = 5$ and $x - y = -1$. Which equation does $x = 2$, $y = 3$ also satisfy?', '["$2x = 4$","$2x = 6$","$2y = 4$","$x + 2y = 7$"]', '$2x = 4$', NULL, 'Adding the equations gives $2x = 4$, and $2 \times 2 = 4$ is true. In the other equations, $2x$ is 4 (not 6), $2y$ is 6 (not 4), and $x + 2y$ is 8 (not 7).', 'checked', '{"lint":[],"solve":{"answer":"$2x = 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of the equations: 2x=4; check 2(2)=4 true. 2x=6, 2y=4 false; x+2y=8 not 7.","run_id":"claude-code","at":"2026-10-24T08:19:44.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33f0251e-509a-4a71-a222-a82d00b0f159', 'NC17.M1.A-REI.5', 1, 'choice', 'Why replacing an equation by a sum keeps the solutions', 'The system $x + y = 8$ and $x - y = 2$ has the solution $(5, 3)$. Dev replaces the first equation with its sum with 4 times the second equation, getting $5x - 3y = 16$. What is true of $(5, 3)$ in the new system?', '["It no longer makes the new equation true, since the equation was changed","It makes the new equation true only if the multiple used is exactly 1","It still makes the new equation true, since it made both old ones true","Nothing can be said about it until the second equation is replaced too"]', 'It still makes the new equation true, since it made both old ones true', NULL, 'The pair $(5, 3)$ makes $x + y = 8$ and $x - y = 2$ true, so it makes the sum $(x + y) + 4(x - y) = 8 + 4 \cdot 2$ true. Adding equal amounts to equal amounts keeps the equation true, so the solution stays. Check: $5 \cdot 5 - 3 \cdot 3 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"It still makes the new equation true, since it made both old ones true","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+y) + 4(x-y) = 5x - 3y and 8 + 4*2 = 16, so the new equation is 5x - 3y = 16. Check (5,3): 25 - 9 = 16, true. Any point satisfying both old equations satisfies their combination.","run_id":"claude-code","at":"2026-10-24T08:47:25.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02bf5175-1199-49b5-88b8-fa7fa59bcd64', 'NC17.M1.A-REI.5', 2, 'numeric', 'Multiply an equation by a number', 'A student multiplies both sides of $2x + 5y = 9$ by $-3$ and gets $-6x - 15y = k$. Find the k.', '[]', '-27', '-3*9', 'Every term is multiplied by $-3$. The right side becomes $-3 \times 9 = -27$.', 'checked', '{"lint":[],"solve":{"answer":"-27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9(-3)=-27.","run_id":"claude-code","at":"2026-10-24T08:19:44.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09c42fc4-bc93-4306-825a-709ea8c77f97', 'NC17.M1.A-REI.5', 2, 'numeric', 'Add a multiple of one equation to the other', 'Multiply $x + 2y = 4$ by $-3$ and add the result to $3x + y = 7$. The sum has no $x$ term. What is $y$?', '[]', '1', '(7-12)/(1-6)', 'Multiplying gives $-3x - 6y = -12$. Adding to $3x + y = 7$: $-5y = -5$, so $y = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x-6y=-12 plus 3x+y=7 gives -5y=-5, y=1.","run_id":"claude-code","at":"2026-10-24T08:19:44.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ef45191-1969-43d7-b84e-5f19530ed7f9', 'NC17.M1.A-REI.5', 2, 'choice', 'Multiply an equation by a number', 'Why can an equation be multiplied by 5 without changing its solutions, but not by 0?', '["Multiplying by 5 makes the numbers bigger, but multiplying by 0 makes them smaller","Both are fine, because multiplying by any number keeps the solutions","Multiplying by 0 is fine, but 5 changes the solution because it is not 1","Multiplying by 5 can be undone by dividing by 5, but multiplying by 0 cannot be undone"]', 'Multiplying by 5 can be undone by dividing by 5, but multiplying by 0 cannot be undone', NULL, 'Multiplying by 5 and dividing by 5 take the equation back and forth, so the solutions stay the same. Multiplying by 0 turns every equation into $0 = 0$, and the original cannot be found again.', 'checked', '{"lint":[],"solve":{"answer":"Multiplying by 5 can be undone by dividing by 5, but multiplying by 0 cannot be undone","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying by 5 is undone by dividing by 5; multiplying by 0 gives 0=0, which cannot be undone.","run_id":"claude-code","at":"2026-10-24T08:19:44.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0565a7ac-cfea-42aa-bed2-4a886d80f24c', 'NC17.M1.A-REI.5', 3, 'choice', 'Which replacements are allowed', 'A student replaces both equations of a system with their sum, so the system has two copies of the sum. What goes wrong?', '["Both original equations are lost, and many extra solutions can appear","Nothing goes wrong, since the sum has the same solutions as each equation","Nothing goes wrong, since each original can be recovered from the sum","The new system has no solutions, since the equations are the same"]', 'Both original equations are lost, and many extra solutions can appear', NULL, 'A system with two copies of one equation is the same as the single sum equation, which a whole line of points satisfies. Neither original equation can be rebuilt from the sum alone, so the solution is no longer the only one.', 'checked', '{"lint":[],"solve":{"answer":"Both original equations are lost, and many extra solutions can appear","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two copies of one equation: one line, infinitely many solutions; originals cannot be recovered.","run_id":"claude-code","at":"2026-10-24T08:19:44.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('056aec08-4939-49f5-845b-072de64b0da3', 'NC17.M1.A-REI.5', 3, 'numeric', 'Recover the old equation', 'The sum of equations A and B is $5x = 20$. B is $x - y = 1$, and A has the form $4x + y = c$. Find the c.', '[]', '19', '20-1', 'A is the sum minus B. Subtract B from the sum: left sides $5x - (x - y) = 4x + y$ and right sides $20 - 1 = 19$. So $c = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4x+y)+(x-y)=5x and c+1=20, so c=19.","run_id":"claude-code","at":"2026-10-24T08:19:44.066Z"}}', 'ai', NULL, NULL)
