INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b6a3f02-5e3c-401b-8590-ff5a2b778387', 'NC17.M1.A-REI.6', 1, 'choice', 'Solve a system by substitution', 'You substitute $y = x + 3$ into $2x + y = 12$. Which equation do you get?', '["$2x + 3 = 12$","$2x + x + 3 = 12$","$2(x + 3) + y = 12$","$x + 3 + y = 12$"]', '$2x + x + 3 = 12$', NULL, 'Replace $y$ in $2x + y = 12$ with $x + 3$. This gives $2x + x + 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"$2x + x + 3 = 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Replace y: 2x + (x + 3) = 12, i.e. 2x + x + 3 = 12.","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
