INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('126b65a9-174d-4b34-9941-407d4626b24c', 'NC17.M1.A-REI.6', 1, 'numeric', 'Solve a system by elimination', 'Add the equations $x + y = 10$ and $x - y = 4$ to eliminate $y$. What is the value of $x$?', '[]', '7', '(10+4)/2', 'Adding gives $2x = 14$, because $y$ and $-y$ cancel. So $x = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x = 14, x = 7.","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00fda1ce-93d5-417b-a7e6-e3d089eb7c9e', 'NC17.M1.A-REI.6', 1, 'choice', 'Solve a system by graphing', 'On a graph, the lines $y = x + 1$ and $y = -x + 5$ cross at which point?', '["$(0, 1)$","$(0, 5)$","$(3, 2)$","$(2, 3)$"]', '$(2, 3)$', NULL, 'At the crossing point the y-values are equal: $x + 1 = -x + 5$, so $2x = 4$ and $x = 2$. Then $y = 2 + 1 = 3$. The point is $(2, 3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 1 = -x + 5, 2x = 4, x = 2, y = 3.","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('401a617c-7fae-431f-a184-4f9806a2b13f', 'NC17.M1.A-REI.6', 2, 'choice', 'Solve a system with tables of values', 'Two linear equations give these values. When $x$ is 1, 2, 3, 4, 5, the first equation gives $y$ = 4, 7, 10, 13, 16 and the second equation gives $y$ = 16, 13, 10, 7, 4. Which point is the solution of the system?', '["$(10, 3)$","$(2, 13)$","$(3, 10)$","$(4, 7)$"]', '$(3, 10)$', NULL, 'The solution is the point where the two equations give the same y-value for the same x. At $x = 3$ both give 10, so the solution is $(3, 10)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 10)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both give 10 at x = 3: (3, 10).","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1546eac5-1a22-4fe6-8fc0-2bf4ae344dd3', 'NC17.M1.A-REI.6', 2, 'choice', 'Solve a system with tables of values', 'Two linear equations give these values. When $x$ is 0, 1, 2, 3, the first equation gives $y$ = 1, 4, 7, 10 and the second equation gives $y$ = 10, 8, 6, 4. Where is the solution of the system?', '["Between $x = 0$ and $x = 1$","Between $x = 2$ and $x = 3$","At exactly $x = 2$","Between $x = 1$ and $x = 2$"]', 'Between $x = 1$ and $x = 2$', NULL, 'At $x = 1$ the first equation is below the second (4 and 8). At $x = 2$ it is above (7 and 6). The lines must cross between $x = 1$ and $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"Between $x = 1$ and $x = 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences first - second: x=0: -9, x=1: -4, x=2: 1. Sign changes between 1 and 2. Exactly: 1 + 3x = 10 - 2x, x = 9/5 = 1.8.","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45e20cde-eb31-469d-80d9-3018113d0a1a', 'NC17.M1.A-REI.6', 2, 'numeric', 'Write and solve a system for a word problem', 'Adult tickets cost 8 dollars and child tickets cost 5 dollars. A group buys 40 tickets for 230 dollars in all. How many adult tickets did they buy?', '[]', '10', '(230-5*40)/(8-5)', 'Let $a$ be adult tickets and $c$ be child tickets. Then $a + c = 40$ and $8a + 5c = 230$. Replace $c$ with $40 - a$: $8a + 200 - 5a = 230$, so $3a = 30$ and $a = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a + c = 40, 8a + 5c = 230: 8a + 200 - 5a = 230, 3a = 30, a = 10.","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c5b714-7413-4ec4-9a39-dcd54b6b876a', 'NC17.M1.A-REI.6', 3, 'numeric', 'Write and solve a system for a word problem', '3 small bags and 2 large bags of rice cost 17 dollars. 1 small bag and 4 large bags cost 19 dollars. How much does one large bag cost, in dollars?', '[]', '4', '(3*19-17)/10', 'Let $s$ and $l$ be the prices. Then $3s + 2l = 17$ and $s + 4l = 19$. Multiply the second by 3: $3s + 12l = 57$. Subtract the first: $10l = 40$, so $l = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3s + 2L = 17, s + 4L = 19: s = 19 - 4L; 57 - 12L + 2L = 17, 10L = 40, L = 4 (s = 3).","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1081d89e-3ee9-4c55-872e-ccd317382e03', 'NC17.M1.A-REI.6', 3, 'choice', 'Interpret the solution of a system in context', 'Car A is already 30 miles from the start and drives at 10 miles per hour: $d = 30 + 10t$. Car B starts at 0 miles and drives at 25 miles per hour: $d = 25t$. The solution is $(2, 50)$. What does it mean?', '["After 2 hours, Car B catches up to Car A, and both are 50 miles from the start.","After 50 hours, Car B catches up to Car A, and both are 2 miles from the start.","After 2 hours, Car A is 50 miles ahead of Car B.","Car B drives 2 miles farther than Car A during the trip."]', 'After 2 hours, Car B catches up to Car A, and both are 50 miles from the start.', NULL, 'The first number is time in hours and the second is distance in miles. At $t = 2$, Car A is at $30 + 20 = 50$ miles and Car B is at $25(2) = 50$ miles, so they are together.', 'checked', '{"lint":[],"solve":{"answer":"After 2 hours, Car B catches up to Car A, and both are 50 miles from the start.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t = 2, d = 50: 30 + 20 = 50, 25*2 = 50. Car B catches up after 2 hours, both 50 miles from start.","run_id":"claude-code","at":"2026-10-24T08:22:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ff105c6-28e1-4a54-b81c-06a8f402fa5e', 'NC17.M1.A-REI.10', 1, 'numeric', 'Find a missing coordinate of a point on a graph', 'The point $(3, k)$ is on the graph of $y = 2x - 1$. What is $k$?', '[]', '5', '2*3-1', 'A point on the graph satisfies the equation, so $k = 2(3) - 1 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 2(3)-1 = 5.","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
