INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69734066-051c-45dc-bf7f-cdc505e818d7', 'NC17.M1.A-REI.10', 1, 'choice', 'Find an equation whose graph contains given points', 'The graph of which equation contains the point $(0, 3)$?', '["$y = x + 3$","$y = 3x$","$y = x - 3$","$y = 3x + 1$"]', '$y = x + 3$', NULL, 'Put $x = 0$ into each equation. Only $y = x + 3$ gives $y = 3$. The others give $0$, $-3$ and $1$.', 'checked', '{"lint":[],"solve":{"answer":"$y = x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0: 3x+1=1, x-3=-3, 3x=0, x+3=3. y=x+3.","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
