INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11c8c32c-af2a-49b5-8430-598f8495f8fc', 'NC17.M1.A-REI.10', 1, 'choice', 'Explain what it means for a point to be on a graph', 'Which statement about the graph of an equation in two variables is true?', '["Only the points where the graph crosses an axis are solutions","The graph shows exactly three solutions of the equation","Every point on the graph is a solution of the equation","A point can be on the graph without being a solution"]', 'Every point on the graph is a solution of the equation', NULL, 'The graph of an equation is the set of all of its solutions: each point on it makes the equation true, and each solution is a point on it.', 'checked', '{"lint":[],"solve":{"answer":"Every point on the graph is a solution of the equation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The graph is exactly the set of solutions, so every point on it is a solution.","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51b371c3-039d-446d-ae45-4c1a88b05e8b', 'NC17.M1.A-REI.10', 2, 'choice', 'Test whether a point is on a graph', 'Which ordered pair is NOT a solution of $3x - 2y = 12$?', '["$(4, 0)$","$(5, 1)$","$(2, -3)$","$(0, -6)$"]', '$(5, 1)$', NULL, 'For $(5, 1)$: $3(5) - 2(1) = 13$, not $12$. The other three give $12$: $12 - 0$, $6 + 6$ and $0 + 12$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x-2y: (5,1)=13 (not 12); (2,-3)=12; (0,-6)=12; (4,0)=12. NOT: (5,1).","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b99e090-2baf-43d2-9f75-86e1ab467488', 'NC17.M1.A-REI.10', 2, 'choice', 'Test whether a point is on a graph', 'Which point is on the graph of $y = |x - 2| + 1$?', '["$(-1, -2)$","$(-1, 3)$","$(-1, 4)$","$(-1, 2)$"]', '$(-1, 4)$', NULL, 'At $x = -1$: $|-1 - 2| + 1 = |-3| + 1 = 3 + 1 = 4$. The other points have the same x-coordinate but do not match.', 'checked', '{"lint":[],"solve":{"answer":"$(-1, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-1-2|+1 = 3+1 = 4. (-1,4).","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
