INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1083330f-fc72-4ab9-90d8-e9512fe0b4ac', 'NC17.M1.A-REI.10', 2, 'numeric', 'Use the graph of an equation in a real situation', 'A plant is 3 centimeters tall and grows 2 centimeters each week, so its height $y$ after $x$ weeks is given by $y = 3 + 2x$. The graph of this equation contains the point $(k, 15)$. What is $k$?', '[]', '6', '(15-3)/2', 'Replace $y$ with $15$: $15 = 3 + 2k$, so $2k = 12$ and $k = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 = 3+2k, k = 6.","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
