INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1300af34-42c9-4b5e-8284-fdd7c54dcdd3', 'NC17.M1.A-REI.10', 3, 'numeric', 'Count the solutions that are points of a graph', 'How many points with both coordinates positive whole numbers are on the graph of $y = \frac{12}{x}$?', '[]', '6', '6', 'We need whole numbers $x$ that divide 12: $1, 2, 3, 4, 6, 12$. Each gives a whole-number $y$, so there are 6 such points: $(1, 12)$, $(2, 6)$, $(3, 4)$, $(4, 3)$, $(6, 2)$, $(12, 1)$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Positive integer x dividing 12: 1,2,3,4,6,12 -> 6 points.","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
