INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4880e63f-cb23-43ba-bca2-1a9b45bf14c0', 'NC17.M1.A-REI.10', 3, 'numeric', 'Find an unknown constant from a point on the graph', 'The graph of $y = ax^2$ contains the point $(2, 12)$. What is $y$ on this graph when $x = -3$?', '[]', '27', '12/4*(-3)^2', 'From $12 = a \cdot 4$ we get $a = 3$. Then at $x = -3$: $y = 3 \cdot 9 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = 4a, a=3. y = 3(9) = 27.","run_id":"claude-code","at":"2026-10-24T08:22:44.450Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3735288b-69c3-44bf-beb5-dcb276cc4692', 'NC17.M1.A-REI.11', 1, 'choice', 'The common output at a solution', 'The graphs of $y = f(x)$ and $y = g(x)$ cross at $(2, 9)$. What does the 9 tell you?', '["The solution of $f(x) = g(x)$ is 9","Both $f(9)$ and $g(9)$ equal 2","Both $f(2)$ and $g(2)$ equal 9","The graphs cross when $x$ is 9"]', 'Both $f(2)$ and $g(2)$ equal 9', NULL, 'The point $(2, 9)$ is on both graphs, so $f(2) = 9$ and $g(2) = 9$. The solution of $f(x) = g(x)$ is the $x$-coordinate, 2.', 'checked', '{"lint":[],"solve":{"answer":"Both $f(2)$ and $g(2)$ equal 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The y-coordinate is the common output: f(2) = g(2) = 9.","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b636508-1e9d-4167-9bd0-0a4116b13209', 'NC17.M1.A-REI.11', 1, 'numeric', 'Solve f(x) = g(x) for linear functions', 'The graphs of $y = x + 3$ and $y = 2x - 1$ cross at one point. What is the $x$-coordinate of that point?', '[]', '4', '3+1', 'Set the functions equal: $x + 3 = 2x - 1$. Subtract $x$ from both sides: $3 = x - 1$, so $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 3 = 2x - 1 gives x = 4.","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17a32039-34e8-4506-bdac-2fb51b8298a8', 'NC17.M1.A-REI.11', 1, 'numeric', 'Use a table of values to find or bracket a solution', 'A table gives values of two functions. For $x = 1, 2, 3, 4$, the values of $f(x)$ are $5, 7, 9, 11$ and the values of $g(x)$ are $13, 11, 9, 7$. For which value of $x$ does $f(x) = g(x)$?', '[]', '3', '3', 'Compare the two lists. At $x = 3$ both $f(x)$ and $g(x)$ equal 9, and at no other listed value are they equal.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 3 both are 9.","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a58ee65-f980-4b0a-bf97-cac97d2aa53c', 'NC17.M1.A-REI.11', 2, 'choice', 'Use a table of values to find or bracket a solution', 'A table gives $f(x) = 2^x$ and $g(x) = 4x$. For $x = 0, 1, 2, 3, 4$ the values of $f(x)$ are $1, 2, 4, 8, 16$ and the values of $g(x)$ are $0, 4, 8, 12, 16$. Which statement about $f(x) = g(x)$ is true?', '["$x = 4$ is the only solution","$x = 4$ is a solution, and there is another solution between $x = 0$ and $x = 1$","$x = 4$ is a solution, and there is another solution between $x = 2$ and $x = 3$","$x = 3$ is a solution, and there are no others"]', '$x = 4$ is a solution, and there is another solution between $x = 0$ and $x = 1$', NULL, 'At $x = 4$ both values are 16. At $x = 0$, $f$ is greater than $g$ ($1 > 0$), but at $x = 1$, $f$ is less than $g$ ($2 < 4$). So the graphs cross between $x = 0$ and $x = 1$. Between $x = 2$ and $x = 3$, $f$ stays below $g$, so there is no crossing there.', 'checked', '{"lint":[],"solve":{"answer":"$x = 4$ is a solution, and there is another solution between $x = 0$ and $x = 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=4: 16=16 solution. At x=0 f>g (1>0), at x=1 f<g (2<4): another root between 0 and 1. Between 2 and 3 f<g at both ends.","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa83d3c-cfaa-433e-9f65-45fd6ea2cb9f', 'NC17.M1.A-REI.11', 2, 'numeric', 'Solve f(x) = g(x) with an exponential function', 'A table gives $f(x) = 3^x$ and $g(x) = 2x + 1$ for $x = -1, 0, 1, 2$. The values of $f(x)$ are $\frac{1}{3}, 1, 3, 9$ and the values of $g(x)$ are $-1, 1, 3, 5$. The equation $f(x) = g(x)$ has two solutions in the table. What is their sum?', '[]', '1', '0+1', 'The values match at $x = 0$ (both 1) and at $x = 1$ (both 3). The sum of the solutions is $0 + 1 = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal at x = 0 (1=1) and x = 1 (3=3); sum 1.","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04a980d9-52dd-4ed7-9c3b-cabe4b82d84a', 'NC17.M1.A-REI.11', 2, 'numeric', 'Solve f(x) = g(x) for linear functions', 'The graph of $f$ is a line through $(0, 2)$ with slope 3. The graph of $g$ is a line through $(0, 10)$ with slope 1. At what $x$-value do the graphs cross?', '[]', '4', '(10-2)/(3-1)', 'The functions are $f(x) = 3x + 2$ and $g(x) = x + 10$. Setting them equal gives $2x = 8$, so $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2 = x + 10; x = 4.","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
