INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2628d2ca-d8dc-4ce5-b8fb-410ed9688c91', 'NC17.M1.A-REI.11', 3, 'numeric', 'Solve f(x) = g(x) for linear functions', 'The graphs of $f(x) = 2x + k$ and $g(x) = -x + 11$ cross at $x = 3$. What is the value of $k$?', '[]', '2', '(-3+11)-6', 'At $x = 3$, $g(3) = -3 + 11 = 8$. Since the graphs cross there, $f(3) = 8$: $2(3) + k = 8$, so $k = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(3) = 8; 6 + k = 8; k = 2.","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f265457-00e2-4056-a503-0e87b6b94121', 'NC17.M1.A-REI.11', 3, 'choice', 'Write the equation that two graphs represent', 'Which equation is solved by the $x$-coordinates of the points where the graphs of $y = 2x^2 - 3$ and $y = x + 4$ cross?', '["$2x^2 - 3 + x + 4 = 0$","$2x^2 - 3 = 4$","$2x^2 - 3 = x + 4$","$2x^2 + x = 7$"]', '$2x^2 - 3 = x + 4$', NULL, 'The graphs cross where the two outputs are equal, so set the two expressions equal: $2x^2 - 3 = x + 4$. The option $2x^2 + x = 7$ changes the sign of $x$ when moving it across the equals sign.', 'checked', '{"lint":[],"solve":{"answer":"$2x^2 - 3 = x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set the two expressions equal: 2x^2 - 3 = x + 4 (equivalent to 2x^2 - x = 7, not 2x^2 + x = 7).","run_id":"claude-code","at":"2026-10-24T08:22:44.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('569c450c-9818-411d-9564-e20a1595d440', 'NC17.M1.A-REI.12', 1, 'choice', 'Test a point in a linear inequality', 'Which point is a solution of $y > 2x + 1$?', '["$(1, 3)$","$(2, 4)$","$(-1, -3)$","$(0, 2)$"]', '$(0, 2)$', NULL, 'Put each point into the inequality. For $(0, 2)$: $2 > 1$ is true. For $(1, 3)$: $3 > 3$ is false. For $(2, 4)$: $4 > 5$ is false. For $(-1, -3)$: $-3 > -1$ is false. Only $(0, 2)$ works.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,3): 3>3 no; (2,4): 4>5 no; (0,2): 2>1 yes; (-1,-3): -3>-1 no.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c0086b3-8d5e-4bad-915a-013a688d7a6d', 'NC17.M1.A-REI.12', 1, 'choice', 'Write an inequality from a graph description', 'A graph shows a solid boundary line $y = 2x + 1$ with the region below the line shaded. Which inequality does it show?', '["$y \\ge 2x + 1$","$y < 2x + 1$","$y > 2x + 1$","$y \\le 2x + 1$"]', '$y \le 2x + 1$', NULL, 'A solid line means the symbol includes "equal to". Shading below means y is less than the line. So the inequality is $y \le 2x + 1$.', 'checked', '{"lint":[],"solve":{"answer":"$y \\le 2x + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solid means included; below means <=.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53a541b1-e51d-4a4b-ad1c-075013faeaff', 'NC17.M1.A-REI.12', 1, 'choice', 'Use a test point to choose the side to shade', 'Mia tests the point $(0, 0)$ in $y > x + 2$ and gets $0 > 2$, which is false. What should she do?', '["shade the side of the line that contains $(0, 0)$","shade the side of the line that does not contain $(0, 0)$","shade neither side of the line","shade both sides of the line"]', 'shade the side of the line that does not contain $(0, 0)$', NULL, 'A false test point means the side it lies on is not part of the solution. So Mia shades the other side of the line.', 'checked', '{"lint":[],"solve":{"answer":"shade the side of the line that does not contain $(0, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Test point fails, so shade the other side.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4991eb39-40a6-42dd-b424-fce9da52242a', 'NC17.M1.A-REI.12', 2, 'numeric', 'Test a point in a linear inequality', 'What is the greatest whole number $y$ for which the point $(4, y)$ is a solution of $3x - 2y \ge 8$?', '[]', '2', '(3*4-8)/2', 'Put $x = 4$ in: $12 - 2y \ge 8$. Then $-2y \ge -4$, and dividing by $-2$ flips the symbol: $y \le 2$. The greatest whole number is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12-2y>=8, y<=2; greatest 2.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b6ad2fd-0b83-47cc-b0be-7db9941546af', 'NC17.M1.A-REI.12', 2, 'numeric', 'Rewrite an inequality in slope-intercept form', 'Solving $2x + y < 6$ for $y$ gives $y < mx + b$. What is $m$?', '[]', '-2', '-2', 'Subtract $2x$ from both sides: $y < -2x + 6$. So $m = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y < -2x+6, m=-2.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
