INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39b4b112-9344-415c-b6a8-c046d4e9ac44', 'NC17.M1.A-REI.12', 2, 'numeric', 'Corner of a region defined by a system', 'The boundary lines of the system $x \ge 2$ and $y \le 5$ cross at a corner of the solution region. What is the sum of the coordinates of that corner?', '[]', '7', '2+5', 'The boundary lines are $x = 2$ and $y = 5$. They cross at $(2, 5)$, and $2 + 5 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corner (2,5); sum 7.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
