INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('265422da-472a-49f4-968f-5536a6e8ce84', 'NC17.M1.A-REI.12', 3, 'choice', 'Test a point in a linear inequality', 'Which point is NOT a solution of $5x - 3y < 15$?', '["$(0, 0)$","$(1, 2)$","$(3, 0)$","$(-3, -4)$"]', '$(3, 0)$', NULL, 'Test each point. $(0, 0)$: $0 < 15$ true. $(1, 2)$: $5 - 6 = -1 < 15$ true. $(-3, -4)$: $-15 + 12 = -3 < 15$ true. $(3, 0)$: $15 < 15$ is false, because the symbol is $<$, not $\le$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3,-4): -3<15 yes; (0,0) yes; (1,2): -1<15 yes; (3,0): 15<15 no.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22b955fd-841a-40cf-a0f8-9b56daaa80c5', 'NC17.M1.A-REI.12', 3, 'numeric', 'Solutions that are whole-number points', 'How many points $(x, y)$ with whole-number coordinates, $x \ge 1$ and $y \ge 1$, satisfy $x + y \le 4$?', '[]', '6', '6', 'List them by x: for $x = 1$, y can be 1, 2 or 3. For $x = 2$, y can be 1 or 2. For $x = 3$, y can be 1. That is $3 + 2 + 1 = 6$ points.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,1),(1,2),(1,3),(2,1),(2,2),(3,1): 6.","run_id":"claude-code","at":"2026-10-24T08:28:35.839Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03b8f571-a95f-49d6-bbf4-f9733dda6294', 'NC17.M1.F-IF.1', 1, 'choice', 'Recognize a function from ordered pairs', 'Each ordered pair is (input, output). Which set of ordered pairs is a function?', '["$(1,4), (2,5), (3,6), (4,7)$","$(1,5), (2,6), (2,7), (3,8)$","$(0,3), (1,4), (0,5), (2,6)$","$(4,1), (5,2), (4,3), (6,4)$"]', '$(1,4), (2,5), (3,6), (4,7)$', NULL, 'In a function every input has exactly one output. In the first set the inputs 1, 2, 3 and 4 each appear once. In each other set one input (2, 0 or 4) appears twice with different outputs, so it is not a function.', 'checked', '{"lint":[],"solve":{"answer":"$(1,4), (2,5), (3,6), (4,7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Option 1 repeats input 0; option 3 repeats 2; option 4 repeats 4. Option 2 has distinct inputs.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('050259ca-f072-43fe-8ebc-8df18862faa6', 'NC17.M1.F-IF.1', 1, 'numeric', 'Link f(x) to the graph of y = f(x)', 'The graph of $y = f(x)$ passes through the point $(5, 11)$. What is $f(5)$?', '[]', '11', '11', 'A point $(x, y)$ on the graph of $y = f(x)$ has $y = f(x)$. For $(5, 11)$ the input is 5 and the output is 11, so $f(5) = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Point (5,11) on y=f(x) means f(5)=11.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('043ae7d7-32f1-4301-8641-3e11df7dc1da', 'NC17.M1.F-IF.1', 1, 'choice', 'Function from an equation, graph or situation', 'Which relation is a function? Each one pairs an input with an output.', '["Input a person, output that person''s birth date","Input a birth date, output the people born that day","Input a parent, output that parent''s children","Input a school, output the students who attend it"]', 'Input a person, output that person''s birth date', NULL, 'Each person has exactly one birth date, so every input has one output. A birth date, a parent and a school can each go with several outputs, so those are not functions.', 'checked', '{"lint":[],"solve":{"answer":"Input a person, output that person''s birth date","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A person has exactly one birth date; parents can have several children, schools many students, a date many people.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c055774-f614-4615-8e22-3a9fe930ec85', 'NC17.M1.F-IF.1', 2, 'numeric', 'Find the input for a given output', 'A function $f$ has this table: input 0 gives 3, input 2 gives 7, input 4 gives 11, input 6 gives 15. For which input is the output equal to $f(2) + 4$?', '[]', '4', '4', '$f(2) = 7$, so $f(2) + 4 = 11$. The table shows that the output 11 comes from the input 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(2)=7, so target 11, which is f(4). Input 4.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27b2c30d-cfb9-4afe-98f9-4b2199f51cd0', 'NC17.M1.F-IF.1', 2, 'numeric', 'Output f(x) for a given input', '$f(x) = 3x - 5$. What is $f(4)$?', '[]', '7', '3*4-5', 'Replace $x$ by 4: $f(4) = 3 \cdot 4 - 5 = 12 - 5 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(4) - 5 = 7.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
