INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48c44573-0b88-4ad8-ab58-fb133da28063', 'NC17.M1.F-IF.1', 2, 'choice', 'Function from an equation, graph or situation', 'For one value of x, a vertical line drawn at that x crosses a graph at two different points. What can you conclude?', '["The graph is a function, since the line crosses it","The graph is not a function, since two inputs share an output","The graph is a function, since it has more than one point","The graph is not a function, since one input has two outputs"]', 'The graph is not a function, since one input has two outputs', NULL, 'A vertical line at x meets the graph at the points whose input is x. Two points mean that one input has two outputs, so y is not a function of x.', 'checked', '{"lint":[],"solve":{"answer":"The graph is not a function, since one input has two outputs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical line test: one x-value with two y-values means not a function.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51e7a566-ce51-4c59-aea5-eadf9f91f6be', 'NC17.M1.F-IF.1', 3, 'numeric', 'Output f(x) for a given input', '$f(x) = 2x^2 - x$. What is $f(-3)$?', '[]', '21', '2*(-3)^2-(-3)', '$f(-3) = 2(-3)^2 - (-3) = 2 \cdot 9 + 3 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(9) - (-3) = 18 + 3 = 21.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
