INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('335ae5f7-8081-423c-a603-8b8b0fab6215', 'NC17.M1.F-IF.1', 3, 'choice', 'Domain and range of a function', 'Which number is NOT in the domain of $f(x) = \frac{10}{x - 4}$?', '["0","10","-4","4"]', '4', NULL, 'The rule gives an output only when the denominator is not 0. At $x = 4$ the denominator is 0, so no output is assigned and 4 is not in the domain.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 4 = 0 at x = 4, excluded.","run_id":"claude-code","at":"2026-10-24T08:22:02.640Z"}}', 'ai', NULL, NULL)
