INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54731e5f-aaa5-4cfc-b47b-3edb96547363', 'NC17.M1.F-IF.2', 1, 'choice', 'Evaluate an exponential function', 'Let $h(x) = 2^x$. What is $h(5)$?', '["10","25","7","32"]', '32', '2^5', 'Replace x with 5: h(5) = 2^5 = 2 x 2 x 2 x 2 x 2 = 32. (10 comes from 2 x 5, and 25 from 5^2.)', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^5=32.","run_id":"claude-code","at":"2026-10-24T08:31:18.529Z"}}', 'ai', NULL, NULL)
