INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b10d186-a882-4aac-91ad-81eb2549dae4', 'NC17.M1.F-IF.2', 1, 'choice', 'Interpret a statement in function notation', 'Which statement means the same as "f of 4 equals 9"?', '["$f \\cdot 4 = 9$","$f(9) = 4$","$f(4) = 9$","$f + 4 = 9$"]', '$f(4) = 9$', NULL, 'In f(4) = 9, the number in the brackets is the input and the number after the equals sign is the output. Reading "f of 4 equals 9" gives f(4) = 9.', 'checked', '{"lint":[],"solve":{"answer":"$f(4) = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(4)=9.","run_id":"claude-code","at":"2026-10-24T08:31:18.529Z"}}', 'ai', NULL, NULL)
