INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18dc231b-f766-4f25-96db-8f1e24ea74ab', 'NC17.M1.F-IF.2', 2, 'numeric', 'Evaluate a linear function', 'Let $f(x) = 4x - 6$. What is $f\left(\frac{1}{2}\right)$?', '[]', '-4', '4*(1/2)-6', 'Replace x with 1/2: f(1/2) = 4(1/2) - 6 = 2 - 6 = -4.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*(1/2)-6=2-6=-4.","run_id":"claude-code","at":"2026-10-24T08:31:18.529Z"}}', 'ai', NULL, NULL)
