INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2567fea1-ab0c-477f-8868-3067148dadd8', 'NC17.M1.F-IF.2', 2, 'numeric', 'Evaluate an exponential function', 'A medicine loses half of its strength every hour. Its strength after x hours is $f(x) = 64 \cdot \left(\frac{1}{2}\right)^x$ units. How many units of strength are left after 3 hours, that is, what is $f(3)$?', '[]', '8', '64*(1/2)^3', 'Replace x with 3: f(3) = 64 x (1/2)^3 = 64 x 1/8 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64/8=8.","run_id":"claude-code","at":"2026-10-24T08:31:18.529Z"}}', 'ai', NULL, NULL)
