INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b69062a-7427-44c1-8122-00d824456d76', 'NC17.M1.F-IF.2', 2, 'choice', 'Interpret a statement in function notation', 'A phone plan costs $C(m) = 0.25m + 15$ dollars for m minutes of calls. The statement $C(0) = 15$ is true. What does it mean?', '["The plan costs 15 dollars for each minute used.","The plan costs 15 dollars when 0 minutes are used.","The plan costs 0 dollars when 15 minutes are used.","The plan costs 0.25 dollars when 0 minutes are used."]', 'The plan costs 15 dollars when 0 minutes are used.', NULL, 'The input m is the minutes used, and the output C(m) is the cost. C(0) = 15 says that with 0 minutes used the cost is still 15 dollars, the base charge.', 'checked', '{"lint":[],"solve":{"answer":"The plan costs 15 dollars when 0 minutes are used.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 minutes costs 15 dollars.","run_id":"claude-code","at":"2026-10-24T08:31:18.529Z"}}', 'ai', NULL, NULL)
