INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d9eed08-32a4-4a7b-8842-5513d77c5d93', 'NC17.M1.F-IF.2', 3, 'numeric', 'Evaluate a quadratic function', 'Find the value of $f(-2)$ for the function $f(x) = -x^2 + 4x - 1$.', '[]', '-13', '-((-2)^2)+4*(-2)-1', 'Replace x with -2: f(-2) = -(-2)^2 + 4(-2) - 1 = -4 - 8 - 1 = -13. Square -2 first, then take the opposite.', 'checked', '{"lint":[],"solve":{"answer":"-13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-(4)+4(-2)-1=-4-8-1=-13.","run_id":"claude-code","at":"2026-10-24T08:31:18.529Z"}}', 'ai', NULL, NULL)
