INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('273b6e0d-b6e6-4b1f-bbf0-c5f6e2349e1b', 'NC17.M1.F-IF.2', 3, 'choice', 'Evaluate a quadratic function', 'Evaluate $f(-4)$ when $f(x) = \frac{1}{2}x^2 - 3$.', '["1","-11","5","11"]', '5', '(1/2)*(-4)^2-3', 'Replace x with -4: f(-4) = (1/2)(16) - 3 = 8 - 3 = 5. Square -4 first (16) and then take half.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)(16)-3=5.","run_id":"claude-code","at":"2026-10-24T08:31:18.529Z"}}', 'ai', NULL, NULL)
