INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04d8e839-0c2a-4e30-9721-096725a00fbe', 'NC17.M1.F-IF.3', 1, 'choice', 'classify arithmetic or geometric', 'Look at the sequence $5, 9, 13, 17, \dots$ Which statement describes it?', '["arithmetic, with common difference 4","geometric, with common ratio 4","arithmetic, with common difference 5","neither arithmetic nor geometric"]', 'arithmetic, with common difference 4', NULL, 'Each term is 4 more than the one before it ($9 - 5 = 4$, $13 - 9 = 4$), so the sequence is arithmetic with common difference 4. The ratios $9 \div 5$ and $13 \div 9$ are not equal, so it is not geometric.', 'checked', '{"lint":[],"solve":{"answer":"arithmetic, with common difference 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences 4,4,4; ratios not constant. Arithmetic, d = 4.","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18834836-8ad3-4a27-874d-e1ed66f6eccb', 'NC17.M1.F-IF.3', 1, 'numeric', 'next term of a sequence', 'The sequence $2, 6, 18, 54, \dots$ is geometric. What is the next term?', '[]', '162', '54*3', 'The common ratio is $6 \div 2 = 3$. The next term is $54 \times 3 = 162$.', 'checked', '{"lint":[],"solve":{"answer":"162","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 3; 54 x 3 = 162.","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16156e12-fbd1-4143-b2e8-6387258b4f97', 'NC17.M1.F-IF.3', 1, 'numeric', 'common difference or common ratio', 'What is the common difference of the arithmetic sequence $20, 17, 14, 11, \dots$?', '[]', '-3', '17-20', 'Subtract a term from the next one: $17 - 20 = -3$ and $14 - 17 = -3$. The common difference is $-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 - 20 = -3.","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b034950-ab6b-40d7-93b0-f26656fba66a', 'NC17.M1.F-IF.3', 2, 'choice', 'write an explicit formula', 'Which explicit formula gives the geometric sequence $3, 6, 12, 24, \dots$ for $n = 1, 2, 3, 4, \dots$?', '["$a_n = 3 \\cdot 2^{n}$","$a_n = 3 \\cdot 2^{n-1}$","$a_n = 2 \\cdot 3^{n-1}$","$a_n = 3n$"]', '$a_n = 3 \cdot 2^{n-1}$', NULL, 'The first term is 3 and the common ratio is 2, so $a_n = 3 \cdot 2^{n-1}$. Check: $a_1 = 3$, $a_2 = 6$, $a_3 = 12$. The formula $3 \cdot 2^n$ gives 6 for $n = 1$, and $3n$ gives 9 for $n = 3$.', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 3 \\cdot 2^{n-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a_n = 3*2^(n-1): n=1 gives 3, n=2 gives 6. (3*2^n gives 6 first.)","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07091157-6512-4c3d-804a-f0687c9dc2bc', 'NC17.M1.F-IF.3', 2, 'choice', 'classify arithmetic or geometric', 'Which of these sequences is geometric?', '["$2, 4, 6, 8, \\dots$","$1, 4, 9, 16, \\dots$","$3, 6, 12, 24, \\dots$","$10, 7, 4, 1, \\dots$"]', '$3, 6, 12, 24, \dots$', NULL, 'In $3, 6, 12, 24$ each term is 2 times the one before. The sequences $2, 4, 6, 8$ and $10, 7, 4, 1$ have a common difference (arithmetic), and $1, 4, 9, 16$ has neither a common difference nor a common ratio.', 'checked', '{"lint":[],"solve":{"answer":"$3, 6, 12, 24, \\dots$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,6,12,24 has constant ratio 2. Others: arithmetic, squares, arithmetic.","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01fd64f4-ee0f-46d7-9176-c5156ee992af', 'NC17.M1.F-IF.3', 2, 'numeric', 'sequence in context', 'A culture has 5 thousand bacteria at hour 1, and the number doubles every hour. If $a_n$ is the number of thousands at hour $n$, what is $a_6$?', '[]', '160', '5*2^5', 'The sequence is geometric with $a_1 = 5$ and $r = 2$, so $a_6 = 5 \cdot 2^{5} = 5 \cdot 32 = 160$ thousand.', 'checked', '{"lint":[],"solve":{"answer":"160","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a_n = 5*2^(n-1); a_6 = 5*32 = 160.","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24b24d25-0904-4ce5-ab9a-03981b7a353e', 'NC17.M1.F-IF.3', 3, 'numeric', 'sequence in context', 'A video has 3 views on day 1, and the number of views triples each day: $a_1 = 3$ and $a_n = 3 \cdot a_{n-1}$ is the number of views on day $n$. How many views are there on day 5?', '[]', '243', '3*3^4', 'The sequence is $3, 9, 27, 81, 243$. Equivalently $a_5 = 3 \cdot 3^{4} = 243$.', 'checked', '{"lint":[],"solve":{"answer":"243","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3, 9, 27, 81, 243.","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
