INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0534f4d5-f962-4ab4-a5ff-0ea6ff9d6fb9', 'NC17.M1.F-IF.3', 3, 'numeric', 'terms from given terms', 'An arithmetic sequence has $a_1 = 4$ and $a_5 = 24$. What is $a_{20}$?', '[]', '99', '4+19*(24-4)/4', 'From $a_1$ to $a_5$ there are 4 steps and the change is 20, so $d = 5$. Then $a_{20} = 4 + 19(5) = 99$.', 'checked', '{"lint":[],"solve":{"answer":"99","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4d = 20, d = 5; a_20 = 4 + 19(5) = 99.","run_id":"claude-code","at":"2026-10-24T08:29:24.526Z"}}', 'ai', NULL, NULL)
