INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('244a736d-1fa5-44d7-965b-64d93ff589f5', 'NC17.M1.F-IF.4', 1, 'choice', 'horizontal intercept in context', 'The function $V(t)$ gives the volume of water, in gallons, in a tank $t$ minutes after a drain is opened. The graph of $V$ crosses the horizontal axis at $t = 12$. What does this tell you?', '["The tank holds 12 gallons when the drain is opened.","The tank is draining at a rate of 12 gallons per minute.","The tank holds 12 gallons one minute after the drain is opened.","The tank is empty 12 minutes after the drain is opened."]', 'The tank is empty 12 minutes after the drain is opened.', NULL, 'A point on the horizontal axis has $V = 0$, so at $t = 12$ minutes there are 0 gallons: the tank is empty.', 'checked', '{"lint":[],"solve":{"answer":"The tank is empty 12 minutes after the drain is opened.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V(12) = 0: tank empty at 12 minutes.","run_id":"claude-code","at":"2026-10-24T08:32:51.943Z"}}', 'ai', NULL, NULL)
