INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a146f56-ba15-434b-af6e-f9b236881948', 'NC17.M1.F-IF.4', 1, 'choice', 'positive and negative intervals', 'The graph of $f(x)$ is above the horizontal axis for $x$ between $-1$ and $3$, and below the axis everywhere else. For which values of $x$ is $f(x)$ positive?', '["$-1 < x < 3$","$x < -1$ or $x > 3$","$x > 3$","$x < -1$"]', '$-1 < x < 3$', NULL, '$f(x)$ is positive where the graph is above the horizontal axis: between $-1$ and $3$.', 'checked', '{"lint":[],"solve":{"answer":"$-1 < x < 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Above axis between -1 and 3: -1 < x < 3.","run_id":"claude-code","at":"2026-10-24T08:32:51.943Z"}}', 'ai', NULL, NULL)
