INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f9c08e3-d309-4aa4-9ba6-fe24cd616ca8', 'NC17.M1.F-IF.4', 1, 'numeric', 'horizontal intercept in context', 'A candle is 20 centimeters tall when it is lit and burns down 4 centimeters every hour, so its height is $h(t) = 20 - 4t$. After how many hours does the candle burn out?', '[]', '5', '20/4', 'The candle burns out when $h(t) = 0$: $20 - 4t = 0$, so $t = 5$ hours. This is the horizontal intercept.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 - 4t = 0, t = 5.","run_id":"claude-code","at":"2026-10-24T08:32:51.943Z"}}', 'ai', NULL, NULL)
