INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1531af36-5fc3-4b12-b793-5b9dcb04c67f', 'NC17.M1.F-IF.4', 2, 'numeric', 'horizontal intercept in context', 'Water from a fountain follows the path $h(x) = -2x^2 + 18$, where $h$ is the height in feet and $x$ is the horizontal distance in feet from the center of the fountain. At what positive distance $x$, in feet, does the water land at height 0?', '[]', '3', NULL, 'Set $-2x^2 + 18 = 0$. Then $x^2 = 9$, so $x = 3$ (taking the positive value).', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x^2 + 18 = 0, x^2 = 9, x = 3.","run_id":"claude-code","at":"2026-10-24T08:32:51.943Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a03bdad-fe13-4962-873b-3d1b310141fc', 'NC17.M1.F-IF.4', 2, 'choice', 'maximum and minimum in context', 'The height of a ball, in meters, $t$ seconds after it is thrown is $h(t) = -5(t - 2)^2 + 30$. Which statement is true?', '["The greatest height is 2 meters, reached 30 seconds after the throw.","The ball is on the ground 2 seconds after the throw.","The greatest height is 30 meters, reached 2 seconds after the throw.","The ball starts at a height of 30 meters."]', 'The greatest height is 30 meters, reached 2 seconds after the throw.', NULL, 'In vertex form the highest point is $(2, 30)$: 30 meters at $t = 2$ seconds. At $t = 0$ the height is $-5(4) + 30 = 10$ meters, and at $t = 2$ the ball is at 30 meters, not on the ground.', 'checked', '{"lint":[],"solve":{"answer":"The greatest height is 30 meters, reached 2 seconds after the throw.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex (2, 30): max 30 m at 2 s. h(0) = 10, so not 30; h(2) = 30, not ground.","run_id":"claude-code","at":"2026-10-24T08:32:51.943Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a7c38b3-e79a-454e-b344-67b973b1d55d', 'NC17.M1.F-IF.4', 3, 'numeric', 'maximum and minimum in context', 'The cost, in dollars, of making $n$ items is $C(n) = n^2 - 12n + 50$. What is the lowest cost, in dollars?', '[]', '14', '6^2-12*6+50', 'The graph is a parabola opening upward with its lowest point at $n = -\frac{-12}{2(1)} = 6$. Then $C(6) = 36 - 72 + 50 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex n = 6: 36 - 72 + 50 = 14.","run_id":"claude-code","at":"2026-10-24T08:32:51.943Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46a01a33-9187-4e58-8e4c-70f6d5afcbf2', 'NC17.M1.F-IF.4', 3, 'choice', 'vertical intercept in context', 'A pool has 15 inches of water when it starts to drain. The water level falls at a steady rate, and the pool is empty after 3 hours. Which function gives the depth $W(t)$, in inches, $t$ hours after draining starts?', '["$W(t) = 15 - 3t$","$W(t) = 15 - 5t$","$W(t) = 3 - 5t$","$W(t) = 15 + 5t$"]', '$W(t) = 15 - 5t$', NULL, 'The vertical intercept is 15 inches. The level falls 15 inches in 3 hours, which is 5 inches per hour, so $W(t) = 15 - 5t$. Check: $W(3) = 0$.', 'checked', '{"lint":[],"solve":{"answer":"$W(t) = 15 - 5t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate 15/3 = 5 per hour: W = 15 - 5t.","run_id":"claude-code","at":"2026-10-24T08:32:51.943Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00e6a770-4dac-467e-958e-58908d7c4f0f', 'NC17.M1.F-IF.5', 1, 'choice', 'Domain from the situation', 'Maya walks at a steady 3 miles per hour for at most 4 hours. The function $d = 3t$ gives the distance $d$ in miles she has walked after $t$ hours. Which is the most reasonable domain?', '["$0 \\le t \\le 12$","$t \\ge 0$","$0 \\le t \\le 4$","$0 \\le t \\le 3$"]', '$0 \le t \le 4$', NULL, 'The domain is the set of input values, and the input is the time $t$. Maya walks for at most 4 hours, and time cannot be negative, so $0 \le t \le 4$. The value 12 is the greatest distance (the range), not a time.', 'checked', '{"lint":[],"solve":{"answer":"$0 \\le t \\le 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walking lasts at most 4 hours and time cannot be negative, so 0 <= t <= 4.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02a62a01-5fea-4d57-9676-6b4a689b44a6', 'NC17.M1.F-IF.5', 1, 'choice', 'Discrete or continuous', 'Which situation is best modeled by a function whose domain is only whole numbers?', '["The total cost of boxes of pencils, by the number of boxes bought","The distance a car has driven, by the number of hours of driving","The temperature of a cup of tea, by the number of minutes it cools","The amount of water in a tub, by the number of minutes it fills"]', 'The total cost of boxes of pencils, by the number of boxes bought', NULL, 'You cannot buy part of a box, so the number of boxes must be a whole number. Hours and minutes of driving, cooling or filling can be any value, including fractions, so those domains are continuous.', 'checked', '{"lint":[],"solve":{"answer":"The total cost of boxes of pencils, by the number of boxes bought","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only whole boxes can be bought; hours, minutes of cooling or filling can be fractional.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0abcbd74-c529-4b34-b90c-f08d07d3dcaf', 'NC17.M1.F-IF.5', 1, 'numeric', 'Range from the situation', 'The function $C = 4 + 2m$ gives the cost $C$ in dollars of a taxi ride of $m$ miles, for $0 \le m \le 10$. What is the least value in the range, in dollars?', '[]', '4', '4+2*0', 'The cost is lowest when the ride is shortest, $m = 0$: $C = 4 + 2(0) = 4$. So the least value in the range is 4 dollars. (The 0 is the least value in the domain.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C is increasing in m; least at m = 0: C = 4 + 0 = 4.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11df0c9d-54b0-43a4-a6f7-17024c1c3dad', 'NC17.M1.F-IF.5', 2, 'numeric', 'Domain from the situation', 'A bathtub holds 80 liters and drains at 4 liters per minute until it is empty. The function $V = 80 - 4t$ gives the volume $V$ in liters after $t$ minutes. What is the greatest value in the domain, in minutes?', '[]', '20', '80/4', 'The tub is empty when $V = 0$: $80 - 4t = 0$, so $t = 80 \div 4 = 20$. Time cannot go past that, so the domain is $0 \le t \le 20$ and its greatest value is 20 minutes.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Empty when 80 - 4t = 0, t = 20. Domain 0 <= t <= 20; greatest 20.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a0e9289-5812-4979-99b8-5a330f6293f3', 'NC17.M1.F-IF.5', 2, 'choice', 'Range from the situation', 'A plant is 4 centimeters tall and grows 2 centimeters each week for 6 weeks. The function $h = 4 + 2w$ gives its height $h$ in centimeters after $w$ weeks. Which describes the range?', '["$0 \\le h \\le 6$","$4 \\le h \\le 12$","$4 \\le h \\le 16$","$0 \\le h \\le 16$"]', '$4 \le h \le 16$', NULL, 'The least height is at the start: $4 + 2(0) = 4$. The greatest is at 6 weeks: $4 + 2(6) = 16$. So the range is $4 \le h \le 16$. The values 0 to 6 are the weeks, the domain.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\le h \\le 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w from 0 to 6: h from 4 + 0 = 4 to 4 + 12 = 16. Range 4 <= h <= 16.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
