INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('073566c5-8b8a-46c9-8aae-df432b975974', 'NC17.M1.F-IF.5', 2, 'choice', 'Domain or range from a described graph', 'The number of bacteria $P$ in a dish is graphed against the time $t$ in hours. It starts at 100 bacteria when $t = 0$ and keeps rising, never dropping, for all later times. Which describes the range?', '["$P \\ge 100$","$P \\ge 0$","$P \\le 100$","$0 \\le P \\le 100$"]', '$P \ge 100$', NULL, 'The range is the set of outputs. The population begins at 100 and only grows, so every value is at least 100, with no upper limit: $P \ge 100$. The domain is $t \ge 0$.', 'checked', '{"lint":[],"solve":{"answer":"$P \\ge 100$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Starts at 100 and only rises, so every value is at least 100: P >= 100.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dc7445b-ad96-4745-867e-e4c8a4705cc4', 'NC17.M1.F-IF.5', 3, 'numeric', 'Domain or range from a described graph', 'A ball is thrown straight up. Its height in meters is 0 at 0 seconds, 15 at 1 second, 20 at 2 seconds, 15 at 3 seconds and 0 at 4 seconds. Its graph is a smooth arc from 0 to 4 seconds with its highest point at 2 seconds. What is the greatest value in the range, in meters?', '[]', '20', '20', 'The range is the set of heights. The highest point is at 2 seconds, where the height is 20 meters, so the greatest value in the range is 20. The domain is $0 \le t \le 4$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Highest point is at 2 s with height 20, so greatest range value 20.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6679b6c3-5304-405e-9685-4aa5e304a886', 'NC17.M1.F-IF.5', 3, 'numeric', 'Domain from the situation', 'A tutor earns 15 dollars per hour. The function $E = 15h$ gives her earnings $E$ in dollars for $h$ hours of tutoring, and the range of the function is $0 \le E \le 90$. What is the greatest value in the domain, in hours?', '[]', '6', '90/15', 'The greatest earnings are 90 dollars, so $15h = 90$ and $h = 90 \div 15 = 6$. The domain is $0 \le h \le 6$, and its greatest value is 6 hours.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"E = 90 at h = 90/15 = 6, so the greatest domain value is 6.","run_id":"claude-code","at":"2026-10-24T08:35:51.833Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('300b94d4-f9df-44f0-94d8-cac1c9227957', 'NC17.M1.F-IF.6', 1, 'choice', 'Interpret an average rate of change in context', 'The distance $D(t)$, in miles, a cyclist has traveled after $t$ hours has an average rate of change of 45 from $t = 0$ to $t = 3$. Which statement is true?', '["On average, the cyclist travels 45 miles in each 3 hours.","The cyclist has traveled 45 miles after 3 hours.","On average, the cyclist travels 45 miles each hour.","The cyclist travels for 45 hours in total."]', 'On average, the cyclist travels 45 miles each hour.', NULL, 'An average rate of change is the change in distance per 1 unit of time. Here it is 45 miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"On average, the cyclist travels 45 miles each hour.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate of change 45 miles per hour on average.","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08d306ce-0a15-4f23-8fbb-d9db026ab7ed', 'NC17.M1.F-IF.6', 1, 'choice', 'Average rate of change of a linear function', 'For a linear function, the average rate of change over any interval equals which of these?', '["the slope of the line","the $y$-intercept of the line","the $x$-intercept of the line","the value of the function at $x = 0$"]', 'the slope of the line', NULL, 'A line has the same rate of change everywhere. That constant rate is the slope.', 'checked', '{"lint":[],"solve":{"answer":"the slope of the line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A linear function has constant rate of change equal to its slope.","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a6a95eb-8c1a-4810-81fe-cdf5dd929e02', 'NC17.M1.F-IF.6', 1, 'numeric', 'Average rate of change from points on a graph', 'The graph of a function $D$ passes through $(0, 20)$ and $(3, 170)$, where $x$ is the time in hours and $y$ is the distance in miles. What is the average rate of change from $x = 0$ to $x = 3$, in miles per hour?', '[]', '50', '(170-20)/(3-0)', 'The distance changes by $170 - 20 = 150$ miles in 3 hours. So the average rate of change is $150 \div 3 = 50$ miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(170-20)/3 = 50.","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('366df384-8db3-4fb6-a2f3-f7b4381b8694', 'NC17.M1.F-IF.6', 2, 'numeric', 'Average rate of change from a table or two values', 'A table shows $f(-2) = 10$, $f(0) = 4$ and $f(3) = -5$. What is the average rate of change of $f$ from $x = 0$ to $x = 3$?', '[]', '-3', '(-5-4)/(3-0)', 'The change in $f$ is $-5 - 4 = -9$ and the change in $x$ is $3 - 0 = 3$. So the average rate of change is $-9 \div 3 = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(f(3)-f(0))/3 = (-5-4)/3 = -3.","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4eeaa98b-47ca-4c01-b3c7-8ff2fbae1f4f', 'NC17.M1.F-IF.6', 2, 'choice', 'Average rate of change from a table or two values', 'A table shows $f(1) = 6$, $f(2) = 9$, $f(3) = 14$ and $f(4) = 23$. On which interval is the average rate of change equal to 7?', '["$[3, 4]$","$[1, 3]$","$[2, 3]$","$[2, 4]$"]', '$[2, 4]$', NULL, 'From 2 to 4: $(23 - 9) \div 2 = 7$. The others give 9 for $[3, 4]$, 4 for $[1, 3]$ and 5 for $[2, 3]$.', 'checked', '{"lint":[],"solve":{"answer":"$[2, 4]$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"[3,4]: 9. [2,3]: 5. [1,3]: 8/2=4. [2,4]: 14/2=7. Answer [2,4].","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d90afe9-4be2-4cc9-9eb6-14589a48e49d', 'NC17.M1.F-IF.6', 2, 'choice', 'Interpret an average rate of change in context', 'The volume $V(t)$, in liters, of water in a tank has an average rate of change of 8 from $t = 0$ to $t = 5$, where $t$ is in minutes. Which statement is true?', '["On average, the volume rises 8 liters each minute.","The volume is 8 liters after 5 minutes.","On average, the volume rises 8 liters in all 5 minutes.","On average, the volume rises 40 liters each minute."]', 'On average, the volume rises 8 liters each minute.', NULL, 'The average rate of change is the change in volume per 1 minute. So the volume rises 8 liters each minute on average.', 'checked', '{"lint":[],"solve":{"answer":"On average, the volume rises 8 liters each minute.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate 8 liters per minute.","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('070ac6ad-1d2b-415b-8c0d-b1ffea11f7ec', 'NC17.M1.F-IF.6', 3, 'numeric', 'Compare average rates of change', 'Let $f(x) = x^2$ and $g(x) = 3x + 1$. From $x = 1$ to $x = 4$, how much greater is the average rate of change of $f$ than that of $g$?', '[]', '2', '(16-1)/3-(13-4)/3', 'For $f$: $(16 - 1) \div 3 = 5$. For $g$: $(13 - 4) \div 3 = 3$. The difference is $5 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f: (16-1)/3 = 5. g: slope 3. Difference 2.","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b2abe9-f783-46ee-9097-d3ccfa47d502', 'NC17.M1.F-IF.6', 3, 'numeric', 'Average rate of change from a linear or quadratic formula', 'A ball rolling down a ramp travels $d(t) = 5t^2$ centimeters in $t$ seconds. What is its average speed from $t = 2$ to $t = 6$, in centimeters per second?', '[]', '40', '(5*36-5*4)/(6-2)', '$d(2) = 20$ and $d(6) = 180$. The average speed is $(180 - 20) \div (6 - 2) = 160 \div 4 = 40$ centimeters per second.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d(2)=20, d(6)=180: 160/4 = 40.","run_id":"claude-code","at":"2026-10-24T08:36:05.559Z"}}', 'ai', NULL, NULL)
