INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c439e9a-41e6-4d21-bc80-4fb31f28f8df', 'NC17.M1.F-IF.7', 1, 'numeric', 'Find the y-intercept', 'The graph of $f(x) = 3x - 7$ crosses the $y$-axis at what $y$-value?', '[]', '-7', '3*0-7', 'The graph crosses the $y$-axis where $x = 0$: $f(0) = 3 \times 0 - 7 = -7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = -7.","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
