INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3d2969-e014-46cb-be4a-bfb5b04a9867', 'NC17.M1.F-IF.7', 1, 'choice', 'Find the vertex or the maximum or minimum value', 'What is the vertex of the graph of $f(x) = (x - 2)^2 + 3$?', '["$(-2, 3)$","$(2, 3)$","$(2, -3)$","$(3, 2)$"]', '$(2, 3)$', NULL, 'For $f(x) = (x - h)^2 + k$ the vertex is $(h, k)$. Here $h = 2$ and $k = 3$, so the vertex is $(2, 3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex form (x-h)^2+k: (2,3).","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
