INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d184aea-20d6-4077-b6b8-da414b96723f', 'NC17.M1.F-IF.7', 1, 'choice', 'Give the domain or range', 'The cost of $n$ lessons is $f(n) = 15n + 10$ dollars. Sam books between 1 and 8 lessons. Which is the domain of $f$ in this situation?', '["all real numbers from 1 to 8","the whole numbers from 25 to 130","the whole numbers from 1 to 8","all real numbers"]', 'the whole numbers from 1 to 8', NULL, 'The domain is the set of allowed inputs. Lessons are counted in whole numbers, and Sam books 1 to 8: the whole numbers from 1 to 8. (The outputs 25 to 130 belong to the range.)', 'checked', '{"lint":[],"solve":{"answer":"the whole numbers from 1 to 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number of lessons is a whole number from 1 to 8.","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
