INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6427d02b-5ff9-41dd-85aa-aa399ae89449', 'NC17.M1.F-IF.7', 2, 'numeric', 'Find the vertex or the maximum or minimum value', 'What is the minimum value of $f(x) = x^2 - 6x + 5$?', '[]', '-4', '3^2-6*3+5', 'The vertex is at $x = -\frac{b}{2a} = \frac{6}{2} = 3$. Then $f(3) = 9 - 18 + 5 = -4$, the minimum value.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex x=3: 9-18+5=-4.","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
