INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15ff2fa5-a8e1-4894-86dc-692d2c086ff8', 'NC17.M1.F-IF.7', 2, 'choice', 'Give the domain or range', 'Which is the range of the exponential function $g(x) = 3 \cdot 2^x$?', '["$y \\ge 0$","$y > 0$","$y > 3$","$y < 0$"]', '$y > 0$', NULL, 'A positive number times a power of 2 is always positive, and it gets as close to 0 as we like when $x$ is very negative. It never reaches 0, so the range is $y > 0$.', 'checked', '{"lint":[],"solve":{"answer":"$y > 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*2^x > 0 for all x and approaches 0: y>0.","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30cf3fa5-c12a-47b7-b6a5-ff832879515d', 'NC17.M1.F-IF.7', 2, 'choice', 'Describe end behavior', 'Which describes the end behavior of $f(x) = -2x^2 + x$?', '["It rises on both the left and the right.","It rises on the left and falls on the right.","It falls on both the left and the right.","It falls on the left and rises on the right."]', 'It falls on both the left and the right.', NULL, 'The leading coefficient $-2$ is negative, so the parabola opens down. Both ends point downward.', 'checked', '{"lint":[],"solve":{"answer":"It falls on both the left and the right.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leading coefficient -2 <0, even degree: falls both sides.","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09a8378a-231b-41f0-8b89-283198e5813b', 'NC17.M1.F-IF.7', 3, 'numeric', 'Find the x-intercepts (zeros)', 'At what value of $x$ does the graph of $f(x) = 2^x - 16$ cross the $x$-axis?', '[]', '4', '4', 'Solve $2^x - 16 = 0$, so $2^x = 16$. Since $2^4 = 16$, $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^x=16, x=4.","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('196c4d8d-d5ee-48db-87f4-6cad03e60727', 'NC17.M1.F-IF.7', 3, 'numeric', 'Find the vertex or the maximum or minimum value', 'A ball is thrown so that its height, in feet, after $t$ seconds is $h(t) = -16t^2 + 48t + 4$. What is the greatest height the ball reaches, in feet?', '[]', '40', '-16*1.5^2+48*1.5+4', 'The vertex is at $t = -\frac{48}{2(-16)} = 1.5$ seconds. Then $h(1.5) = -16(2.25) + 72 + 4 = -36 + 76 = 40$ feet.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t = 48/32 = 1.5. h = -16(2.25)+72+4 = -36+76 = 40.","run_id":"claude-code","at":"2026-10-24T08:36:28.953Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19c720fb-af92-45f0-80ee-599628044e03', 'NC17.M1.F-IF.8', 1, 'numeric', 'Vertex and axis from vertex form', 'What is the minimum value of $f(x) = (x + 2)^2 - 9$?', '[]', '-9', '-9', 'A square is never negative, so $(x + 2)^2$ is smallest (0) when $x = -2$. Then $f(-2) = 0 - 9 = -9$.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 2)^2 >= 0, so minimum is -9 at x = -2.","run_id":"claude-code","at":"2026-10-24T08:37:23.302Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dfb3646-e1a0-4d1e-ad25-9d18171f57df', 'NC17.M1.F-IF.8', 1, 'choice', 'Choose the form that shows a feature', 'Which feature of a quadratic function can be read directly from its vertex form $f(x) = a(x - h)^2 + k$?', '["The zeros of the function","The y-intercept of the graph","The slope of the graph","The vertex of the parabola"]', 'The vertex of the parabola', NULL, 'In vertex form the vertex is at the point $(h, k)$, which can be read without any further work. Zeros come from factored form.', 'checked', '{"lint":[],"solve":{"answer":"The vertex of the parabola","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex form shows the vertex (h, k) directly.","run_id":"claude-code","at":"2026-10-24T08:37:23.302Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17e3a663-48b6-4690-ad82-23aec5b18954', 'NC17.M1.F-IF.8', 1, 'numeric', 'Complete the square to vertex form', 'To complete the square for $x^2 + 8x$, what number must be added?', '[]', '16', '(8/2)^2', 'Take half of the coefficient of $x$: $8 \div 2 = 4$. Then square it: $4^2 = 16$. Adding 16 gives $x^2 + 8x + 16 = (x + 4)^2$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8/2)^2 = 16.","run_id":"claude-code","at":"2026-10-24T08:37:23.302Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f76c926-8abb-4c1f-afa7-c8a9a2ee06dd', 'NC17.M1.F-IF.8', 2, 'choice', 'Vertex and axis from vertex form', 'Which statement is true about $f(x) = -(x - 2)^2 + 7$?', '["The parabola opens upward and has a minimum value of 7.","The parabola opens downward and has a maximum value of 2.","The parabola opens upward and has a minimum value of 2.","The parabola opens downward and has a maximum value of 7."]', 'The parabola opens downward and has a maximum value of 7.', NULL, 'The leading coefficient is $-1$, so the parabola opens downward and the vertex $(2, 7)$ is its highest point. The maximum value is the $y$-value of the vertex, which is 7.', 'checked', '{"lint":[],"solve":{"answer":"The parabola opens downward and has a maximum value of 7.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leading coefficient -1: opens downward; vertex (2, 7), maximum 7.","run_id":"claude-code","at":"2026-10-24T08:37:23.302Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a7e6394-eaae-4d9d-a1fc-f526d45d249c', 'NC17.M1.F-IF.8', 2, 'numeric', 'Growth or decay rate of an exponential function', 'A bacteria culture is modeled by $N(t) = 50(2)^t$, where $t$ is in hours. By what percent does the culture grow each hour?', '[]', '100', '(2-1)*100', 'The growth factor is $2 = 1 + 1.00$, so the growth rate is 1.00, which is 100% each hour. The culture doubles.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 2 = 1 + 1: grows 100% per hour.","run_id":"claude-code","at":"2026-10-24T08:37:23.302Z"}}', 'ai', NULL, NULL)
