INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07081a85-391e-44fd-8436-aff66db7fffb', 'NC17.M1.F-BF.2', 1, 'numeric', 'Model a situation with a sequence', 'Ana''s savings at the start of each week form a sequence: 20, 25, 30, 35 dollars, and so on. If the pattern continues, how many dollars will she have at the start of week 7?', '[]', '50', '20+5*6', 'The sequence is arithmetic with first term 20 and common difference 5. Term 7 is 20 + 5(7 - 1) = 50.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Week 1 is 20, add 5 per week: 20 + 5(6) = 50.","run_id":"claude-code","at":"2026-10-24T08:40:09.203Z"}}', 'ai', NULL, NULL)
