VALUES ('431309dd-e3fb-4e62-8fd4-b07c44e8a65f', 'NC17.M1.F-BF.2', 1, 'numeric', 'Find a term from a formula', 'A geometric sequence has the explicit formula $a_n = 2 \cdot 3^{n-1}$. What is $a_4$?', '[]', '54', '2*3^3', 'Put n = 4: 2 x 3^3 = 2 x 27 = 54.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 * 3^3 = 54.","run_id":"claude-code","at":"2026-10-24T08:40:09.203Z"}}', 'ai', NULL, NULL)
