INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cf27891-25c4-4cee-9b95-35d69c00c0a2', 'NC17.M1.F-BF.2', 2, 'numeric', 'Find a term from a formula', 'An arithmetic sequence has a first term of 3 and a common difference of 4. What is the 20th term?', '[]', '79', '3+4*19', 'a_20 = 3 + 4(20 - 1) = 3 + 76 = 79.', 'checked', '{"lint":[],"solve":{"answer":"79","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a_20 = 3 + 4(19) = 79.","run_id":"claude-code","at":"2026-10-24T08:40:09.203Z"}}', 'ai', NULL, NULL)
