INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('009aa784-d6dd-4971-af5f-730f3fd9fea9', 'NC17.M1.F-BF.2', 2, 'choice', 'Write an explicit formula', 'An arithmetic sequence has $a_1 = 4$ and $a_3 = 10$. Which explicit formula gives its terms?', '["$a_n = 4 + 3(n - 1)$","$a_n = 4 + 6(n - 1)$","$a_n = 10 + 3(n - 1)$","$a_n = 4 + 3n$"]', '$a_n = 4 + 3(n - 1)$', NULL, 'From a_1 to a_3 there are 2 steps that add up to 6, so the common difference is 3. Then a_n = 4 + 3(n - 1).', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 4 + 3(n - 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a_3 - a_1 = 2d = 6, d = 3. a_n = 4 + 3(n-1).","run_id":"claude-code","at":"2026-10-24T08:40:09.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3af1203e-1d2b-4eea-ad01-d5de519c92b7', 'NC17.M1.F-BF.2', 3, 'choice', 'Write an explicit formula', 'A geometric sequence has $a_2 = 12$ and $a_5 = 96$. Which explicit formula gives its terms?', '["$a_n = 12 \\cdot 2^{n-1}$","$a_n = 6 \\cdot 4^{n-1}$","$a_n = 6 \\cdot 2^n$","$a_n = 6 \\cdot 2^{n-1}$"]', '$a_n = 6 \cdot 2^{n-1}$', NULL, 'From a_2 to a_5 the terms are multiplied by r three times: r^3 = 96 / 12 = 8, so r = 2. Then a_1 = 12 / 2 = 6, and a_n = 6 x 2^(n-1).', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 6 \\cdot 2^{n-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r^3 = 96/12 = 8, r = 2. a_1 = 12/2 = 6. a_n = 6*2^(n-1). Check: a_2 = 12, a_5 = 96. 6*2^n gives a_2 = 24.","run_id":"claude-code","at":"2026-10-24T08:40:09.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45acfdcb-d97d-4cce-9515-d8a692291ae0', 'NC17.M1.F-BF.2', 3, 'choice', 'Write a recursive rule', 'A tank holds 400 liters at the start of day 1. Each day 5 percent of the water evaporates, so it keeps 95 percent of the previous day''s amount. Which recursive rule gives the liters at the start of day $n$?', '["$a_1 = 400$ and $a_n = 0.95a_{n-1}$","$a_1 = 400$ and $a_n = a_{n-1} - 0.05$","$a_1 = 400$ and $a_n = 1.05a_{n-1}$","$a_1 = 400$ and $a_n = 0.05a_{n-1}$"]', '$a_1 = 400$ and $a_n = 0.95a_{n-1}$', NULL, 'Each day the amount is 95 percent, or 0.95 times, the amount the day before, starting at 400.', 'checked', '{"lint":[],"solve":{"answer":"$a_1 = 400$ and $a_n = 0.95a_{n-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Keeps 95 percent each day: multiply by 0.95.","run_id":"claude-code","at":"2026-10-24T08:40:09.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('460ac5c0-2fdb-456e-9224-755cdcbaefa7', 'NC17.M1.F-LE.1', 1, 'numeric', 'Find the constant change or growth factor', 'An exponential function has $x$-values 0, 1, 2, 3 and $y$-values 2, 6, 18, 54. By what number is $y$ multiplied each time $x$ increases by 1?', '[]', '3', '6/2', 'Divide each $y$-value by the one before: $6 \div 2 = 3$, $18 \div 6 = 3$, $54 \div 18 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/2 = 18/6 = 54/18 = 3.","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
