INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42dd4f28-e775-4ce8-8f6a-4001ad811cf1', 'NC17.M1.F-LE.1', 1, 'choice', 'Classify a situation as linear or exponential', 'A sunflower is 5 cm tall when planted and grows 2 cm each week. Which kind of function models its height after $w$ weeks?', '["Exponential, because the height increases every week","Exponential, because the height is multiplied by 2 each week","Linear, because the plant starts at 5 cm","Linear, because it grows by the same amount each week"]', 'Linear, because it grows by the same amount each week', NULL, 'The height goes up by the same amount, 2 cm, each week, so it is linear. Exponential functions are multiplied by the same number each time.', 'checked', '{"lint":[],"solve":{"answer":"Linear, because it grows by the same amount each week","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same 2 cm added each week: constant change over equal intervals, linear (h = 5 + 2w).","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('375f9307-4ef1-4d24-af71-8e60aff1c5ed', 'NC17.M1.F-LE.1', 1, 'numeric', 'Extend or complete a pattern from its model', 'An exponential function has $x$-values 0, 1, 2, 3 and $y$-values 2, 4, 8, 16. What is the $y$-value when $x = 4$?', '[]', '32', '16*2', 'Each $y$-value is 2 times the one before, so the next is $16 \cdot 2 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 2; next is 16 x 2 = 32.","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
