INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30774f7f-fb14-4af1-995a-1ebf524d8f50', 'NC17.M1.F-LE.1', 2, 'choice', 'Classify a table as linear, exponential or neither', 'A table gives $x$-values 0, 1, 2, 3 and the matching $y$-values 2, 5, 10, 17. Which statement is correct?', '["Linear, because $y$ increases every time $x$ increases","Exponential, because $y$ increases every time $x$ increases","Exponential, because $y$ is multiplied by 2 every time $x$ goes up","Neither, because neither difference nor ratio is constant"]', 'Neither, because neither difference nor ratio is constant', NULL, 'The differences are 3, 5 and 7, so it is not linear. The ratios are 2.5, 2 and 1.7, so it is not exponential. It is neither.', 'checked', '{"lint":[],"solve":{"answer":"Neither, because neither difference nor ratio is constant","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences 3, 5, 7 (not constant); ratios 2.5, 2, 1.7 (not constant). Neither.","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
