INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3413afe3-2311-4f48-a2bd-842b742438be', 'NC17.M1.F-LE.1', 2, 'numeric', 'Extend or complete a pattern from its model', 'A linear function has $x$-values 0, 1, 2, 3 and $y$-values 12, 20, 28, 36. What is the $y$-value when $x = 10$?', '[]', '92', '12+8*10', '$y$ goes up by 8 for each 1 in $x$, starting at 12 when $x = 0$. So when $x = 10$, $y = 12 + 8 \cdot 10 = 92$.', 'checked', '{"lint":[],"solve":{"answer":"92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 8x + 12; at x = 10, y = 92.","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
