INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01ef0b9a-1f88-408a-9efd-c4611f342fc9', 'NC17.M1.F-LE.1', 2, 'numeric', 'Classify a situation as linear or exponential', 'Three situations are described. (i) A library fine is 10 cents for each day a book is late. (ii) A town''s population grows 4 percent each year. (iii) A tank fills at 6 liters each minute. How many of these three situations are modeled by linear functions?', '[]', '2', '2', 'Situations (i) and (iii) add the same amount each time, so they are linear. Situation (ii) multiplies by 1.04 each year, so it is exponential. That makes 2 linear situations.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(i) 10 cents per day: linear. (ii) 4 percent per year: exponential. (iii) 6 L per minute: linear. Two.","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03a27060-ffcd-4133-8d6e-1aef644580b5', 'NC17.M1.F-LE.1', 3, 'choice', 'Classify a table as linear, exponential or neither', 'A table gives $x$-values 0, 1, 2, 3 and the matching $y$-values 81, 54, 36, 24. Which statement is correct?', '["Linear, because $y$ decreases by 27 each time","Exponential, because $y$ is multiplied by $\\frac{3}{2}$ each time","Exponential, because $y$ is multiplied by $\\frac{2}{3}$ each time","Neither, because the differences are not the same"]', 'Exponential, because $y$ is multiplied by $\frac{2}{3}$ each time', NULL, 'The differences are $-27$, $-18$ and $-12$, so it is not linear. The ratios are $54 \div 81 = \frac{2}{3}$, $36 \div 54 = \frac{2}{3}$ and $24 \div 36 = \frac{2}{3}$, so it is exponential.', 'checked', '{"lint":[],"solve":{"answer":"Exponential, because $y$ is multiplied by $\\frac{2}{3}$ each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54/81 = 2/3, 36/54 = 2/3, 24/36 = 2/3. Differences -27, -18, -12 not constant. Exponential, factor 2/3.","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13dd23b5-1c78-4a1c-8250-f6e669b19f75', 'NC17.M1.F-LE.1', 3, 'numeric', 'Find the constant change or growth factor', 'A linear function has $y = 5$ when $x = 2$ and $y = 11$ when $x = 4$. What is the $y$-value when $x = 0$?', '[]', '-1', '5-(11-5)/(4-2)*2', '$y$ rises 6 while $x$ rises 2, so the rate is 3 per unit. Going back 2 units from $x = 2$ to $x = 0$ lowers $y$ by $3 \cdot 2 = 6$, so $y = 5 - 6 = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (11-5)/(4-2) = 3. At x = 0: 5 - 2(3) = -1.","run_id":"claude-code","at":"2026-10-24T08:42:31.784Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('206fece2-ea9f-4eca-8fb5-fff462f0c5c1', 'NC17.M1.F-LE.3', 1, 'numeric', 'Find where an exponential first exceeds a linear function', 'Let $f(x) = x + 10$ and $g(x) = 2^x$. What is the smallest whole number $x$ for which $g(x)$ is greater than $f(x)$?', '[]', '4', '4', 'Try $x = 0, 1, 2, 3$: $g$ is $1, 2, 4, 8$ and $f$ is $10, 11, 12, 13$, so $g$ is still less. At $x = 4$, $g = 16$ and $f = 14$, so $g$ is greater. The answer is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0:1<10; 1:2<11; 2:4<12; 3:8<13; 4:16>14. Smallest is 4.","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('157cd756-f130-46fb-8991-71df195be748', 'NC17.M1.F-LE.3', 1, 'choice', 'Find where an exponential first exceeds a linear function', 'In a table, $f(x) = 2x$ has values $0, 2, 4, 6, 8, 10$ and $g(x) = 2^x$ has values $1, 2, 4, 8, 16, 32$ for $x = 0, 1, 2, 3, 4, 5$. For what positive whole number $x$ is $g(x)$ first greater than $f(x)$?', '["$x = 1$","$x = 2$","$x = 5$","$x = 3$"]', '$x = 3$', NULL, 'At $x = 1$ and $x = 2$ the values are equal (2 and 4). At $x = 3$, $g = 8$ and $f = 6$, so $g$ is first greater at $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=1: 2=2; x=2: 4=4; x=3: 8>6. First positive x is 3.","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4cde0043-2988-4ebc-90d6-8a1bf7a5be47', 'NC17.M1.F-LE.3', 1, 'numeric', 'Find where an exponential first exceeds a quadratic function', 'Let $f(x) = x^2$ and $g(x) = 2^x$. How much greater is $g(6)$ than $f(6)$?', '[]', '28', '2^6-6^2', '$g(6) = 2^6 = 64$ and $f(6) = 6^2 = 36$. The difference is $64 - 36 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(6)=64, f(6)=36; 64-36=28.","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
