INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39862c61-294a-46ec-8f38-0b1e6cd5ba05', 'NC17.M1.F-LE.3', 2, 'choice', 'Recognize which kind of growth wins in the long run', 'Maria says, "The line $y = 1000x$ is so steep that it will always stay above the curve $y = 2^x$." Which response is correct?', '["Yes, because 1000 is a much larger number than 2","No, because $2^x$ will eventually be greater than $1000x$","Yes, because $2^x$ levels off as $x$ grows","No, because $2^x$ is greater than $1000x$ for every $x$"]', 'No, because $2^x$ will eventually be greater than $1000x$', NULL, 'A line adds the same amount each step (1000), but $2^x$ doubles each step. At $x = 10$ the line is at 10,000 and $2^x$ is only 1,024, but at $x = 20$ the line is at 20,000 while $2^x$ is over a million. So $2^x$ is not above the line for small $x$, yet it eventually becomes greater.', 'checked', '{"lint":[],"solve":{"answer":"No, because $2^x$ will eventually be greater than $1000x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exponential eventually exceeds any linear function: 2^14=16384>14000. So no, 2^x eventually greater. Option C false (x=1: 2<1000).","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34786548-a2f5-41f9-825b-deebb24380bc', 'NC17.M1.F-LE.3', 2, 'numeric', 'Find where an exponential first exceeds a linear function', 'Let $f(x) = 10x$ and $g(x) = 2^x$. What is the smallest positive whole number $x$ for which $g(x)$ is greater than $f(x)$?', '[]', '6', '6', 'Check values: $x = 5$ gives $g = 32$ and $f = 50$, so $g$ is still less. At $x = 6$, $g = 64$ and $f = 60$, so $g$ is greater. Smaller $x$ values (1 to 4) also have $g$ less than $f$. The answer is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=5: 32<50; x=6: 64>60; earlier x smaller. Answer 6.","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c414516-4d98-4c70-aba7-7d5c57ab773b', 'NC17.M1.F-LE.3', 2, 'numeric', 'Find where an exponential first exceeds a linear function', 'Let $f(x) = 30x + 50$ and $g(x) = 2^x$. What is the smallest whole number $x$ for which $g(x)$ is greater than $f(x)$?', '[]', '9', '9', 'At $x = 8$, $g = 256$ and $f = 290$, so $g$ is still less. At $x = 9$, $g = 512$ and $f = 320$, so $g$ is greater. Smaller values of $x$ keep $g$ well below $f$. The answer is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=7:128<260; 8:256<290; 9:512>320; smaller x all less. Answer 9.","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c49140e-746a-4a4f-89f4-05755e4d4492', 'NC17.M1.F-LE.3', 3, 'choice', 'Find where an exponential first exceeds a quadratic function', 'Let $f(x) = 10x^2$ and $g(x) = 3^x$. What is the smallest positive whole number $x$ for which $g(x) > f(x)$?', '["$x = 4$","$x = 5$","$x = 6$","$x = 7$"]', '$x = 6$', NULL, 'At $x = 5$, $g = 243$ and $f = 250$, so $g$ is still less. At $x = 6$, $g = 729$ and $f = 360$, so $g$ is greater. Smaller values are also less (for example $3^4 = 81 < 160$).', 'checked', '{"lint":[],"solve":{"answer":"$x = 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=4: 81<160; 5: 243<250; 6: 729>360; x=1..3 also less. Answer 6.","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b5bbb63-0709-4a1b-9d7d-c29af4c6c484', 'NC17.M1.F-LE.3', 3, 'numeric', 'Find where an exponential first exceeds a linear function', 'Let $h(x) = 1000 + 200x$ and $g(x) = 3^x$. What is the smallest whole number $x$ for which $g(x)$ is greater than $h(x)$?', '[]', '8', '8', 'At $x = 7$, $g = 2187$ and $h = 2400$, so $g$ is still less. At $x = 8$, $g = 6561$ and $h = 2600$, so $g$ is greater. The answer is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=6: 729<2200; 7: 2187<2400; 8: 6561>2600. Answer 8.","run_id":"claude-code","at":"2026-10-24T08:43:49.099Z"}}', 'ai', NULL, NULL)
