INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2550c88d-aa07-4476-9090-d7f632397f03', 'NC17.M1.F-LE.5', 1, 'choice', 'Interpret the y-intercept of a linear model', 'The height, in centimeters, of a candle after it has burned for $t$ hours is $h = 20 - 2t$. What does the 20 mean?', '["How much the candle burns down each hour.","The number of hours the candle burns.","The height of the candle after 2 hours.","The height of the candle before it is lit."]', 'The height of the candle before it is lit.', NULL, 'The 20 is the value of $h$ when $t = 0$, which is the height before any time has gone by. The $-2$ is how much the height drops each hour.', 'checked', '{"lint":[],"solve":{"answer":"The height of the candle before it is lit.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At t=0, h=20: the height before burning starts.","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16a818ec-cf42-4f6b-95b9-188f296bcb86', 'NC17.M1.F-LE.5', 1, 'choice', 'Decide between a linear and an exponential model', 'Which situation is best modeled by an exponential function?', '["A plant that grows 3 centimeters each week.","A phone plan that costs 40 dollars plus 10 dollars per gigabyte.","A savings account that earns 4 percent interest each year.","A runner who runs 5 miles each day."]', 'A savings account that earns 4 percent interest each year.', NULL, 'An exponential function multiplies by the same factor each step. Earning 4 percent interest multiplies the balance by 1.04 each year. The others add the same amount each time, so they are linear.', 'checked', '{"lint":[],"solve":{"answer":"A savings account that earns 4 percent interest each year.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A fixed percent growth per year is multiplicative: exponential. The others are constant additive changes.","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
