INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35041b11-9f91-4d93-a418-bd1ec82c8e2e', 'NC17.M1.F-LE.5', 1, 'numeric', 'Interpret the y-intercept of a linear model', 'The amount of money, in dollars, in a savings jar after $w$ weeks is $B = 45 + 8w$. How many dollars were in the jar at the start, when $w = 0$?', '[]', '45', '45', 'When $w = 0$, $B = 45 + 8(0) = 45$. The 45 is the starting amount, and the 8 is how much is added each week.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At w=0, B=45.","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
