INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b089a2c-7eaf-4b86-91dd-2cd0f12b9d98', 'NC17.M1.F-LE.5', 2, 'choice', 'Interpret the base b of an exponential model', 'The number of bacteria in a dish is modeled by $N = 50(1.5)^h$, where $h$ is the number of hours. Which statement is true?', '["The number of bacteria increases by 1.5 percent each hour.","The number of bacteria increases by 1.5 each hour.","The number of bacteria increases by 150 percent each hour.","The number of bacteria increases by 50 percent each hour."]', 'The number of bacteria increases by 50 percent each hour.', NULL, 'Each hour the number is multiplied by 1.5, which is 100 percent plus 50 percent. So it grows by 50 percent each hour. The value 1.5 is a factor, not a percent or an amount added.', 'checked', '{"lint":[],"solve":{"answer":"The number of bacteria increases by 50 percent each hour.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5 = 1 + 0.5: increases 50% each hour.","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b26b957-337b-44b8-bb56-6d61a6ee3faa', 'NC17.M1.F-LE.5', 2, 'choice', 'Interpret the slope of a linear model', 'The amount of gas, in gallons, in a tank after driving $m$ miles is $g = 14 - 0.04m$. What does the $-0.04$ mean?', '["The tank started with 0.04 gallon of gas.","The gas decreases by 0.04 gallon for every mile driven.","The car travels 0.04 mile on each gallon.","The tank is empty after 0.04 mile."]', 'The gas decreases by 0.04 gallon for every mile driven.', NULL, 'The number multiplying $m$ is the rate of change. It is negative, so the amount of gas goes down, by 0.04 gallon for each mile driven. The 14 is the amount of gas at the start.', 'checked', '{"lint":[],"solve":{"answer":"The gas decreases by 0.04 gallon for every mile driven.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope -0.04: gas decreases 0.04 gallon per mile.","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('090fad3c-36c8-4209-a795-9a44fb5b8bb3', 'NC17.M1.F-LE.5', 2, 'numeric', 'Interpret the slope of a linear model', 'The height of a bamboo plant, in centimeters, is modeled by $h = 40 + 3.5d$, where $d$ is the number of days. How many centimeters does the plant grow in 10 days?', '[]', '35', '3.5*10', 'The rate of change is 3.5 centimeters per day. In 10 days the plant grows 3.5 x 10 = 35 centimeters. The 40 is the starting height and does not change the amount of growth.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth rate 3.5 cm per day; 3.5*10 = 35.","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
