INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4126a561-0972-4dea-bdb8-d3393310cf73', 'NC17.M1.F-LE.5', 3, 'choice', 'Compare two models by their parameters', 'Account A is modeled by $A = 1000(1.05)^t$ and account B by $B = 1200(1.03)^t$, where $t$ is in years and both are in dollars. Which statement is true?', '["Account A starts with more money, and also grows by a greater percent each year","Account B starts with more money, but account A grows by a greater percent each year","Account B starts with more money, and also grows by a greater percent each year","Account A starts with more money, but account B grows by a greater percent each year"]', 'Account B starts with more money, but account A grows by a greater percent each year', NULL, 'The starting values are 1000 for A and 1200 for B, so B starts with more. The bases are 1.05 and 1.03, so A grows 5 percent a year and B grows 3 percent a year. A grows by the greater percent.', 'checked', '{"lint":[],"solve":{"answer":"Account B starts with more money, but account A grows by a greater percent each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A starts 1000, B starts 1200 (B more). A grows 5%, B 3% (A greater).","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e9fea6a-5117-4365-8987-d7c1f9ece991', 'NC17.M1.F-LE.5', 3, 'choice', 'Interpret the y-intercept of a linear model', 'The temperature of a cooling cup of tea, in degrees Celsius, is $T = 90 - 2.5m$ after $m$ minutes. Which question is answered by finding $T$ when $m = 0$?', '["What was the temperature when the tea was first measured?","How fast is the tea cooling?","How long until the tea reaches room temperature?","How warm is the tea after 1 minute?"]', 'What was the temperature when the tea was first measured?', NULL, 'When $m = 0$, no time has passed, so $T = 90$ is the starting temperature. How fast the tea cools is the 2.5, and the other questions need other values of $m$.', 'checked', '{"lint":[],"solve":{"answer":"What was the temperature when the tea was first measured?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"T at m=0 is the initial temperature, 90 degrees.","run_id":"claude-code","at":"2026-10-24T08:42:16.346Z"}}', 'ai', NULL, NULL)
