INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('421d19a5-e3c8-4f02-b784-8db3d8a27eff', 'NC17.M1.G-GPE.4', 1, 'numeric', 'Distance between two points', 'What is the distance between the points $A(1, 2)$ and $B(4, 6)$?', '[]', '5', '5', 'Use the distance formula: $\sqrt{(4-1)^2 + (6-2)^2} = \sqrt{9 + 16} = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(3^2+4^2) = 5.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
