INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20716d30-a3c4-4a94-b7e2-c495f0d95e9f', 'NC17.M1.G-GPE.4', 1, 'numeric', 'Perimeter of a polygon from coordinates', 'A rectangle has vertices $(1, 1)$, $(7, 1)$, $(7, 5)$ and $(1, 5)$. What is its perimeter?', '[]', '20', '2*(6+4)', 'The horizontal sides have length $7 - 1 = 6$ and the vertical sides have length $5 - 1 = 4$. The perimeter is $2(6 + 4) = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 6 and 4; perimeter 2(6+4) = 20.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
