INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bdfc58c-f0cd-4ba6-bd91-5e46f71aa944', 'NC17.M1.G-GPE.4', 1, 'choice', 'Area of a triangle from coordinates', 'A triangle has vertices $(0, 0)$, $(6, 0)$ and $(0, 4)$. What is its area?', '["24","12","10","5"]', '12', '6*4/2', 'The base along the x-axis is 6 and the height along the y-axis is 4. The area is $\frac{1}{2} \times 6 \times 4 = 12$. Forgetting the one-half gives 24.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right triangle legs 6 and 4; area 12.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
