INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b34d095-2719-44af-b45a-a7fb1ca4ad62', 'NC17.M1.G-GPE.4', 2, 'choice', 'Perimeter of a polygon from coordinates', 'Find the perimeter of the triangle whose corners are $A(-4, 0)$, $B(4, 0)$ and $C(0, 3)$.', '["13","16","18","14"]', '18', '8+5+5', '$AB = 8$. $AC = \sqrt{4^2 + 3^2} = 5$ and $BC = \sqrt{4^2 + 3^2} = 5$. The perimeter is $8 + 5 + 5 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = 8, AC = BC = sqrt(16+9) = 5; perimeter 18.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1558d784-1948-4b14-acd7-52be6b0e4424', 'NC17.M1.G-GPE.4', 2, 'numeric', 'Area of a rectangle from coordinates', 'A rectangle with sides parallel to the axes has opposite corners at $(-4, -1)$ and $(3, 5)$. What is its area?', '[]', '42', '7*6', 'The width is $3 - (-4) = 7$ and the height is $5 - (-1) = 6$. The area is $7 \times 6 = 42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 7, height 6; area 42.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
