INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5612081c-f0b0-4321-85ef-0041e96dd8ce', 'NC17.M1.G-GPE.4', 2, 'choice', 'Classify a triangle with coordinates', 'Triangle $ABC$ has vertices $A(0, 0)$, $B(4, 2)$ and $C(-1, 2)$. Which is true?', '["It has a right angle at $B$.","It has a right angle at $A$.","It has a right angle at $C$.","It is not a right triangle."]', 'It has a right angle at $A$.', NULL, 'The slope of $\overline{AB}$ is $\frac{2}{4} = \frac{1}{2}$ and the slope of $\overline{AC}$ is $\frac{2}{-1} = -2$. Their product is $-1$, so the sides are perpendicular at $A$. Check: $AB^2 + AC^2 = 20 + 5 = 25 = BC^2$.', 'checked', '{"lint":[],"solve":{"answer":"It has a right angle at $A$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = (4,2), AC = (-1,2): dot = -4+4 = 0, right angle at A.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ac592dc-8bf0-4ff3-8296-7377d210dc55', 'NC17.M1.G-GPE.4', 3, 'numeric', 'Perimeter of a polygon from coordinates', 'Quadrilateral $PQRS$ has vertices $P(0, 0)$, $Q(6, 0)$, $R(9, 4)$ and $S(3, 4)$. What is its perimeter?', '[]', '22', '6+5+6+5', '$PQ = 6$ and $RS = 6$. $QR = \sqrt{3^2 + 4^2} = 5$ and $SP = \sqrt{3^2 + 4^2} = 5$. The perimeter is $6 + 5 + 6 + 5 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PQ = 6, QR = sqrt(9+16) = 5, RS = 6, SP = 5; perimeter 22.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02e3205e-9d37-45ef-ba27-98177aebf431', 'NC17.M1.G-GPE.4', 3, 'choice', 'Classify a quadrilateral with coordinates', 'Quadrilateral $WXYZ$ has vertices $W(0, 0)$, $X(4, 2)$, $Y(2, 6)$ and $Z(-2, 4)$. Which best describes it?', '["A rectangle that is not a square","A square","A rhombus that is not a square","A parallelogram that is not a rectangle"]', 'A square', NULL, 'Each side has length $\sqrt{20}$: for example $WX = \sqrt{4^2 + 2^2}$ and $XY = \sqrt{(-2)^2 + 4^2}$. The slopes of $\overline{WX}$ and $\overline{XY}$ are $\frac{1}{2}$ and $-2$, which multiply to $-1$, so the angle at $X$ is a right angle. Equal sides and right angles make a square.', 'checked', '{"lint":[],"solve":{"answer":"A square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"WX = (4,2), XY = (-2,4), YZ = (-4,-2), ZW = (2,-4): all sqrt20; WX.XY = -8+8 = 0. Square.","run_id":"claude-code","at":"2026-10-24T08:41:07.715Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ee46d43-b0e2-4d96-9bc0-3cd7830a8d59', 'NC17.M1.G-GPE.5', 1, 'choice', 'Parallel lines have equal slopes', 'Which equation has a graph that is parallel to the graph of $y = 4x + 1$?', '["$y = -4x + 1$","$y = 4x - 9$","$y = \\frac{1}{4}x + 1$","$y = x + 4$"]', '$y = 4x - 9$', NULL, 'Parallel lines have equal slopes. Only $y = 4x - 9$ has slope 4 (and a different intercept, so it is a different line). The other slopes are $-4$, $\frac{1}{4}$ and 1.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x - 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 4, different intercept: y = 4x - 9.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('039c3e5d-dca0-4bf7-8e03-72a7cb65dad0', 'NC17.M1.G-GPE.5', 1, 'choice', 'Classify a pair of lines as parallel, perpendicular or neither', 'How are the lines $y = 2x + 1$ and $y = 2x - 6$ related?', '["perpendicular","the same line","parallel","neither parallel nor perpendicular"]', 'parallel', NULL, 'Both have slope 2 but different y-intercepts, so they are parallel and never meet.', 'checked', '{"lint":[],"solve":{"answer":"parallel","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same slope 2, different intercepts: parallel.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5009c181-2e2f-4f94-9cda-cde0524d72ef', 'NC17.M1.G-GPE.5', 1, 'numeric', 'Equation of a line through a point parallel to a given line', 'A line parallel to $y = 5x + 1$ passes through the point $(1, 7)$. What is the y-intercept of this line?', '[]', '2', '7-5*1', 'The parallel line has slope 5, so $y = 5x + b$. Substituting $(1, 7)$: $7 = 5 + b$, so $b = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 5x + b, 7 = 5 + b, b = 2.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24f41db9-5f58-4d13-93b4-368c982f9267', 'NC17.M1.G-GPE.5', 2, 'choice', 'Parallel lines have equal slopes', 'Which equation has a graph that is parallel to the graph of $2x + 3y = 12$?', '["$3x + 2y = 12$","$2x - 3y = 12$","$6x + 4y = 7$","$4x + 6y = 5$"]', '$4x + 6y = 5$', NULL, 'Solving $2x + 3y = 12$ for $y$ gives slope $-\frac{2}{3}$. The equation $4x + 6y = 5$ gives $y = -\frac{2}{3}x + \frac{5}{6}$, the same slope. The others have slopes $-\frac{3}{2}$, $\frac{2}{3}$ and $-\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$4x + 6y = 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+3y=12 slope -2/3. 3x+2y: -3/2; 6x+4y: -3/2; 2x-3y: 2/3; 4x+6y=5: -2/3, distinct line. Parallel.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('451cc8ae-688e-4192-86b0-e9f8518dbd33', 'NC17.M1.G-GPE.5', 2, 'choice', 'Classify a pair of lines as parallel, perpendicular or neither', 'How are the lines $3x + y = 4$ and $y = -3x - 7$ related?', '["perpendicular","parallel","the same line","neither parallel nor perpendicular"]', 'parallel', NULL, 'Rewrite $3x + y = 4$ as $y = -3x + 4$. Both lines have slope $-3$ and different y-intercepts, so they are parallel.', 'checked', '{"lint":[],"solve":{"answer":"parallel","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+y=4 -> y=-3x+4; slope -3 both, intercepts 4 and -7: parallel.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0eb01048-59dd-4b05-9fa3-93c69c19fe9b', 'NC17.M1.G-GPE.5', 2, 'numeric', 'Find an unknown that makes two lines parallel or perpendicular', 'The line through $(2, k)$ and $(5, -1)$ is perpendicular to a line with slope $\frac{3}{2}$. What is $k$?', '[]', '1', '-1-(-2/3)*(5-2)', 'The perpendicular slope is $-\frac{2}{3}$. So $\frac{-1 - k}{5 - 2} = -\frac{2}{3}$, which gives $-1 - k = -2$ and $k = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope must be -2/3: (-1-k)/3 = -2/3, k = 1.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('583f9cd1-89ed-41d2-a635-fc7c0dc053ca', 'NC17.M1.G-GPE.5', 3, 'numeric', 'Slope of a perpendicular line is the negative reciprocal', 'A line has the equation $3x + 4y = 8$. What is the slope of a line perpendicular to it?', '[]', '4/3', '4/3', 'Solve for $y$: $4y = -3x + 8$, so $y = -\frac{3}{4}x + 2$ and the slope is $-\frac{3}{4}$. The negative reciprocal is $\frac{4}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"4/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = -3/4 x + 2, slope -3/4; perpendicular 4/3.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aec011b-5467-4dce-979a-a5ea0a7750d3', 'NC17.M1.G-GPE.5', 3, 'choice', 'Classify a pair of lines as parallel, perpendicular or neither', 'Line P passes through $(2, 1)$ and $(5, 3)$. Line Q passes through $(0, 4)$ and $(2, 1)$. How are lines P and Q related?', '["parallel","the same line","neither parallel nor perpendicular","perpendicular"]', 'perpendicular', NULL, 'Line P has slope $\frac{3 - 1}{5 - 2} = \frac{2}{3}$. Line Q has slope $\frac{1 - 4}{2 - 0} = -\frac{3}{2}$. These are negative reciprocals (product $-1$), so the lines are perpendicular.', 'checked', '{"lint":[],"solve":{"answer":"perpendicular","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P slope 2/3; Q slope (1-4)/2 = -3/2; product -1: perpendicular.","run_id":"claude-code","at":"2026-10-24T08:44:12.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21fbf376-f104-4638-80c6-67a573a35f21', 'NC17.M1.G-GPE.6', 1, 'choice', 'Midpoint in a context (map, circle, number line)', 'On a map grid, a park is at $(2, 6)$ and a school is at $(8, 2)$. A bus stop is exactly halfway between them. What are the coordinates of the bus stop?', '["$(10, 8)$","$(6, -4)$","$(5, 4)$","$(3, 2)$"]', '$(5, 4)$', NULL, 'Average the x-coordinates: (2 + 8) / 2 = 5. Average the y-coordinates: (6 + 2) / 2 = 4. The bus stop is at (5, 4).', 'checked', '{"lint":[],"solve":{"answer":"$(5, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midpoint ((2+8)/2,(6+2)/2)=(5,4).","run_id":"claude-code","at":"2026-10-28T18:48:28.210Z"}}', 'ai', NULL, NULL)
