INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d209509-a64a-4bf8-8876-df060a917c40', 'NC17.M1.G-GPE.6', 1, 'numeric', 'Midpoint from endpoints, whole-number coordinates', 'What is the x-coordinate of the midpoint of the segment with endpoints $(2, 0)$ and $(10, 6)$?', '[]', '6', '(2+10)/2', 'The x-coordinate of the midpoint is the average of 2 and 10: (2 + 10) / 2 = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+10)/2=6.","run_id":"claude-code","at":"2026-10-28T18:48:28.509Z"}}', 'ai', NULL, NULL)
