INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0583f151-f4ed-41b6-9b9b-c069185d9aa3', 'NC17.M1.G-GPE.6', 2, 'choice', 'Midpoint in a context (map, circle, number line)', 'Two drones hover at $(5, -4)$ and $(5, 8)$. A third drone stays exactly halfway between them. Where is it?', '["$(10, 4)$","$(5, 6)$","$(0, 2)$","$(5, 2)$"]', '$(5, 2)$', NULL, 'x: (5 + 5) / 2 = 5. y: (-4 + 8) / 2 = 2. The third drone is at (5, 2).', 'checked', '{"lint":[],"solve":{"answer":"$(5, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midpoint ((5+5)/2, (-4+8)/2) = (5, 2).","run_id":"claude-code","at":"2026-10-28T18:48:28.115Z"}}', 'ai', NULL, NULL)
