INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2543492f-6d42-469f-98a2-682c78cdf3f7', 'NC17.M1.G-GPE.6', 2, 'numeric', 'Find an unknown coordinate from a midpoint', 'M is the midpoint of segment PQ. Point P is $(-6, 4)$ and M is $(-1, 0)$. What is the x-coordinate of Q?', '[]', '4', '2*(-1)-(-6)', 'Solve (-6 + x) / 2 = -1. Then -6 + x = -2, so x = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q_x = 2(-1) - (-6) = -2 + 6 = 4.","run_id":"claude-code","at":"2026-10-28T18:48:28.525Z"}}', 'ai', NULL, NULL)
