INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20714b03-84ad-4d14-9d77-54f817a78fd3', 'NC17.M1.G-GPE.6', 3, 'numeric', 'Midpoint in a context (map, circle, number line)', 'Positions along a hallway are marked in meters like a number line. Mia stands at -7. Sam stands exactly halfway between Mia and Jon, at -2.5. At what position does Jon stand?', '[]', '2', '2*(-2.5)-(-7)', 'C is halfway between A and B, so (-7 + b) / 2 = -2.5. Then -7 + b = -5, and b = 2. (From -7 to -2.5 is 4.5 units; 4.5 more units from -2.5 reaches 2.)', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-7+J)/2=-2.5 -> J=2.","run_id":"claude-code","at":"2026-10-28T18:48:28.492Z"}}', 'ai', NULL, NULL)
