INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c8b283f-a06e-48b4-9ff0-992d92aa0a69', 'NC17.M1.G-GPE.6', 3, 'numeric', 'Find an unknown coordinate from a midpoint', 'The midpoint of the segment from $(2, k)$ to $(10, 8)$ is $(6, 3)$. What is the value of $k$?', '[]', '-2', '2*3-8', 'The y-coordinate of the midpoint is (k + 8) / 2 = 3. So k + 8 = 6, and k = -2.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k + 8)/2 = 3 gives k + 8 = 6, k = -2.","run_id":"claude-code","at":"2026-10-28T18:48:28.577Z"}}', 'ai', NULL, NULL)
