INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b1fdbc8-a522-47e3-882e-b5a34c4bfa89', 'NC17.M1.S-ID.1', 1, 'choice', 'Reading a histogram from its bars', 'In a histogram of test scores, what does the height of a bar show?', '["the highest score in that bar''s interval","the average of the scores in that bar''s interval","how many scores fall in that bar''s interval","the width of that bar''s interval"]', 'how many scores fall in that bar''s interval', NULL, 'The height of a bar is the frequency: the number of data values in the interval under the bar.', 'checked', '{"lint":[],"solve":{"answer":"how many scores fall in that bar''s interval","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bar height is the frequency (count) in the interval.","run_id":"claude-code","at":"2026-10-28T18:48:28.034Z"}}', 'ai', NULL, NULL)
