INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4751a7ab-3274-43ab-bd8b-7bec7b504c40', 'NC17.M1.S-ID.1', 1, 'choice', 'Choosing and comparing histograms and box plots', 'Which data set could be shown in a histogram?', '["the favorite pets of 30 different students","the colors of 30 flowers in a garden","the heights of 30 plants, in centimeters","the cities where 30 students at a school live"]', 'the heights of 30 plants, in centimeters', NULL, 'A histogram groups numerical data into intervals on a number line. Pets, colors and cities are categories, not numbers.', 'checked', '{"lint":[],"solve":{"answer":"the heights of 30 plants, in centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Histograms show numerical data; heights in cm is the only quantitative set.","run_id":"claude-code","at":"2026-10-28T18:48:28.378Z"}}', 'ai', NULL, NULL)
