INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c7d8183-3c2d-433d-ae6b-6687ab25728e', 'NC17.M1.S-ID.1', 2, 'choice', 'Reading a histogram from its bars', 'A histogram shows the ages of 25 people. Bars: 0 to 9 years: 8 people, 10 to 19 years: 7 people, 20 to 29 years: 5 people, 30 to 39 years: 3 people, 40 to 49 years: 2 people. Which interval contains the median age (the 13th age in order)?', '["0 to 9 years","20 to 29 years","10 to 19 years","30 to 39 years"]', '10 to 19 years', NULL, 'Count up the bars: 8 people are 0 to 9, and 8 + 7 = 15 people are 19 or younger. So the 13th age is in the 10 to 19 bar.', 'checked', '{"lint":[],"solve":{"answer":"10 to 19 years","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cumulative: 0-9 holds 1st-8th, 10-19 holds 9th-15th. 13th is in 10-19.","run_id":"claude-code","at":"2026-10-28T18:48:28.128Z"}}', 'ai', NULL, NULL)
