INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e9af078-4c9c-4a8a-8691-bd3533c38bd4', 'NC17.M1.S-ID.1', 2, 'numeric', 'Reading a box plot', 'A box plot of daily high temperatures in degrees Fahrenheit has minimum 31, Q1 40, median 47, Q3 58 and maximum 71. What is the interquartile range?', '[]', '18', '58-40', 'The interquartile range is Q3 - Q1 = 58 - 40 = 18 degrees.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = 58-40 = 18.","run_id":"claude-code","at":"2026-10-28T18:48:28.485Z"}}', 'ai', NULL, NULL)
