INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('086abe10-2e16-4fd2-8a8e-37b2c0b6a02d', 'NC17.M1.S-ID.1', 2, 'numeric', 'Reading a histogram from its bars', 'A histogram of 25 quiz scores has these bars: 50 to 59: 2 scores, 60 to 69: 5 scores, 70 to 79: 9 scores, 80 to 89: 6 scores, 90 to 99: 3 scores. What percent of the scores are below 70?', '[]', '28', '(2+5)/25*100', 'Scores below 70 are in the first two bars: 2 + 5 = 7. Then 7 / 25 = 0.28, which is 28 percent.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Below 70: 2 + 5 = 7 of 25 = 28%.","run_id":"claude-code","at":"2026-10-28T18:48:28.624Z"}}', 'ai', NULL, NULL)
