INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a45cea8-6159-4071-a170-8a8359e9d40c', 'NC17.M1.S-ID.3', 1, 'numeric', 'Effect of an outlier on the range', 'The values 12, 14, 15, 15, 17 and 40 are the ages of people at a small club meeting. What is the range of the six ages?', '[]', '28', '40-12', 'Range = largest - smallest = 40 - 12 = 28. Without the 40 the range would be only 5.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = 40 - 12 = 28.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14b2735a-d6b1-466b-8841-9e614b557ebd', 'NC17.M1.S-ID.3', 1, 'numeric', 'Effect of an outlier on the mean', 'The values 2, 3, 4, 5 and 6 have a mean of 4. The value 34 is added. By how much does the mean increase?', '[]', '5', '(2+3+4+5+6+34)/6-(2+3+4+5+6)/5', 'The new total is 20 + 34 = 54 for 6 values, so the new mean is 9. The mean rises from 4 to 9, an increase of 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 20 + 34 = 54; 54/6 = 9; increase 9 - 4 = 5.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1dba2246-5145-4d68-a6ce-3c1e735f59c1', 'NC17.M1.S-ID.3', 1, 'numeric', 'Finding a missing value or the mean without an outlier', 'Five quiz scores are 0, 80, 90, 85 and 85. The score of 0 is an outlier because the student was absent. What is the mean of the other four scores?', '[]', '85', '(80+90+85+85)/4', 'Without the 0 the scores add to 80 + 90 + 85 + 85 = 340. The mean is 340 / 4 = 85.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(80+90+85+85)/4 = 340/4 = 85.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('238cc075-efae-479d-b033-956b5cfeb896', 'NC17.M1.S-ID.3', 2, 'numeric', 'Effect of an outlier on the IQR and standard deviation', 'Find the interquartile range (IQR) of the data 3, 4, 6, 7, 9, 10, 12 and 80, using the median of each half to find the quartiles.', '[]', '6', '(10+12)/2-(4+6)/2', 'The lower half is 3, 4, 6, 7, so Q1 = (4 + 6) / 2 = 5. The upper half is 9, 10, 12, 80, so Q3 = (10 + 12) / 2 = 11. IQR = 11 - 5 = 6, even though the range is 77.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower half 3,4,6,7: Q1 = 5. Upper half 9,10,12,80: Q3 = 11. IQR = 6.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b009957-7b66-4071-908f-29f63a6cd29b', 'NC17.M1.S-ID.3', 2, 'numeric', 'Effect of an outlier on the range', 'The ages 45, 48, 50, 52 and 55 have a range of 10. A person aged 90 joins the group. By how much does the range increase?', '[]', '35', '(90-45)-(55-45)', 'The new range is 90 - 45 = 45. The old range was 10. The range increases by 45 - 10 = 35.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New range 90 - 45 = 45; increase 45 - 10 = 35.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
