INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34677c44-e301-4973-ac75-a7d9101f07f4', 'NC17.M1.S-ID.3', 2, 'choice', 'Outliers and the shape of a distribution', 'A data set has mean 48 and median 41. Which description of its shape is most likely?', '["Skewed left, with a few unusually low values","Skewed right, with a few unusually high values","Symmetric, with no outliers","Skewed right, with a few unusually low values"]', 'Skewed right, with a few unusually high values', NULL, 'A mean well above the median means some large values pull the mean up. That is a right skew with high outliers.', 'checked', '{"lint":[],"solve":{"answer":"Skewed right, with a few unusually high values","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean > median suggests right skew with some high values.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
