INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('187bedfb-8925-4260-b1c4-80e6258600e0', 'NC17.M1.S-ID.3', 3, 'choice', 'Effect of an outlier on the median', 'The data set 10, 12, 14, 16, 18 has median 14. Which single change leaves the median at 14 but changes the mean?', '["Change 18 to 180","Change 14 to 140","Change 12 to 20","Change 16 to 11"]', 'Change 18 to 180', NULL, 'Changing 18 to 180 gives 10, 12, 14, 16, 180, whose median is still 14 while the mean jumps. Changing 14 to 140 or 12 to 20 makes the median 16, and changing 16 to 11 makes it 12.', 'checked', '{"lint":[],"solve":{"answer":"Change 18 to 180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14->140: median 16. 18->180: 10,12,14,16,180 median 14, mean changes. 16->11: median 12. 12->20: median 16.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ddd124c-0c8d-4669-b10d-1faa7f917d93', 'NC17.M1.S-ID.3', 3, 'numeric', 'Finding a missing value or the mean without an outlier', 'Six test scores, including one outlier of 15, have a mean of 65. What is the mean of the five scores without the outlier?', '[]', '75', '(6*65-15)/5', 'The six scores add to 6 x 65 = 390. Without the 15 the total is 375 for 5 scores, so the mean is 375 / 5 = 75.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 6*65 = 390; minus 15 = 375; 375/5 = 75.","run_id":"claude-code","at":"2026-10-24T08:44:31.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('853b5610-5d69-4dfa-84c1-117ad7db89a6', 'NC17.M1.S-ID.6', 1, 'choice', 'Scatter plots and association', 'In a scatter plot of the age of a used car and its price, the points tend to go down from left to right. Which describes the association?', '["Positive: as age goes up, price tends to go up","Negative: as age goes up, price tends to go down","Negative: as age goes up, price tends to go up","Positive: as age goes up, price tends to go down"]', 'Negative: as age goes up, price tends to go down', NULL, 'Points that go down from left to right show a negative association: a larger age goes with a lower price.', 'checked', '{"lint":[],"solve":{"answer":"Negative: as age goes up, price tends to go down","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Down from left to right: negative association, price falls as age rises.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('691e3a4f-44c6-4626-b61d-0742fc37d420', 'NC17.M1.S-ID.6', 1, 'choice', 'Interpret slope and intercept in context', 'A fitted line $\hat{y} = 2.5x + 40$ predicts the cost $\hat{y}$ in dollars of renting a bike for $x$ hours. What does the 2.5 mean?', '["The rental costs 2.5 dollars when $x$ is 40 hours","Every rental lasts about 2.5 hours, on average","Each extra hour adds about 2.5 dollars to the cost","The predicted cost is always 2.5 times as much as 40"]', 'Each extra hour adds about 2.5 dollars to the cost', NULL, 'The slope is the change in predicted $y$ for each one-unit increase in $x$: 2.5 dollars more for each additional hour.', 'checked', '{"lint":[],"solve":{"answer":"Each extra hour adds about 2.5 dollars to the cost","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 2.5: each additional hour adds about $2.50 to the predicted cost.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6fdc78be-7bb0-417b-a673-e4a298979036', 'NC17.M1.S-ID.6', 1, 'numeric', 'Predict with a fitted line', 'A fitted line $\hat{y} = 3x + 12$ predicts the points $\hat{y}$ a student earns on a quiz after $x$ hours of practice. How many points does the line predict for 6 hours of practice?', '[]', '30', '3*6+12', 'Put $x = 6$ into the line: $3(6) + 12 = 18 + 12 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(6)+12 = 30.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
