INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2686cccf-2964-4e5d-8c9c-1270936bc53d', 'NC17.M1.S-ID.6', 2, 'choice', 'Choose a model type from data', 'A table gives $x$: 0, 1, 2, 3 and $y$: 2, 6, 18, 54. Which type of model fits these data, and why?', '["Exponential, because each $y$ is 3 times the one before it","Linear, because each $y$ is larger than the one before it","Linear, because each $y$ is 4 more than the one before it","Exponential, because each $y$ is 2 more than the one before it"]', 'Exponential, because each $y$ is 3 times the one before it', NULL, 'The $y$-values are multiplied by 3 each time $x$ goes up by 1, which is exponential growth. They do not increase by a constant amount.', 'checked', '{"lint":[],"solve":{"answer":"Exponential, because each $y$ is 3 times the one before it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/2=3, 18/6=3, 54/18=3: constant ratio 3, exponential.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08c960b8-8cd0-461a-98cc-f8941093b897', 'NC17.M1.S-ID.6', 2, 'choice', 'Judge a linear fit with residuals', 'A student fits a line to some data and plots the residuals against $x$. The residuals are scattered above and below zero with no pattern. What does this suggest?', '["A linear model is a poor fit and a curve is needed","The data points must all lie on one line","The fitted line has a slope of zero","A linear model is a reasonable fit for the data"]', 'A linear model is a reasonable fit for the data', NULL, 'Residuals with no pattern mean the line captures the trend. A curved pattern would suggest the line is not appropriate.', 'checked', '{"lint":[],"solve":{"answer":"A linear model is a reasonable fit for the data","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random scatter of residuals around 0 indicates a linear model is appropriate.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('137d078b-a57d-4e84-a0c6-0234569c7229', 'NC17.M1.S-ID.6', 2, 'numeric', 'Predict with a fitted line', 'The points (2, 5), (4, 9) and (6, 13) lie exactly on a line. Use that line to predict $y$ when $x = 10$.', '[]', '21', '5+2*(10-2)', 'The slope is $\frac{9-5}{4-2} = 2$. From (2, 5), moving 8 units right adds $2 \times 8 = 16$, so $y = 5 + 16 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (9-5)/(4-2) = 2; y = 2x + 1; at x=10, y = 21.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f84e0e8-2b22-4600-8062-22b7696a8a51', 'NC17.M1.S-ID.6', 3, 'choice', 'Choose a model type from data', 'A table gives $x$: 0, 1, 2, 3 and $y$: 100, 80, 64, 51.2. Which model type fits these data, and why?', '["Linear with a negative slope, because $y$ decreases each time","Exponential decay, because each $y$ is 0.8 times the last","Exponential growth, because $y$ changes by a constant factor","Linear with a negative slope, because $y$ drops by 20 each time"]', 'Exponential decay, because each $y$ is 0.8 times the last', NULL, 'Each $y$ is 0.8 times the previous one ($100 \times 0.8 = 80$, $80 \times 0.8 = 64$, $64 \times 0.8 = 51.2$). A factor less than 1 is exponential decay. The drops (20, 16, 12.8) are not constant.', 'checked', '{"lint":[],"solve":{"answer":"Exponential decay, because each $y$ is 0.8 times the last","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80/100 = 0.8, 64/80 = 0.8, 51.2/64 = 0.8: decay factor 0.8. Drops are 20, 16, 12.8, not constant.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('118b165e-ef6a-4a6b-b0b6-956d54513db1', 'NC17.M1.S-ID.6', 3, 'numeric', 'Judge a linear fit with residuals', 'The fitted line $\hat{y} = 2x + 1$ is compared with the data points (1, 3), (2, 7), (3, 8) and (5, 13). Find the sum of the squares of the four residuals.', '[]', '9', '(3-3)^2+(7-5)^2+(8-7)^2+(13-11)^2', 'Predictions: 3, 5, 7, 11. Residuals: $3-3 = 0$, $7-5 = 2$, $8-7 = 1$, $13-11 = 2$. Squares: $0 + 4 + 1 + 4 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Predictions 3, 5, 7, 11; residuals 0, 2, 1, 2; squares 0+4+1+4 = 9.","run_id":"claude-code","at":"2026-10-24T08:45:27.477Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('107a2a7b-d1af-43d6-9d4e-d8343e1cd4db', 'NC17.M1.S-ID.7', 1, 'choice', 'Extrapolate with a linear model', 'A model was built from data with $x$ from 1 to 10. Using it to predict $y$ at $x = 30$ is an example of what?', '["Interpolation","A residual","Extrapolation","A correlation"]', 'Extrapolation', NULL, 'Predicting for an input outside the range of the data is extrapolation. Predicting inside the range is interpolation.', 'checked', '{"lint":[],"solve":{"answer":"Extrapolation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outside the data range: extrapolation.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('295dc2aa-4133-4389-b313-2e0f44388621', 'NC17.M1.S-ID.7', 1, 'numeric', 'Extrapolate with a linear model', 'The model $y = 3x + 2$ predicts the height $y$, in centimeters, of a seedling in week $x$. It was built from data for weeks 1 to 5. What height does it predict for week 8?', '[]', '26', '3*8+2', 'Week 8 is outside the data (weeks 1 to 5), so this is an extrapolation. $y = 3(8) + 2 = 26$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*8 + 2 = 26.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('216b43c9-f6a3-4a9d-a4ee-8024907cdc47', 'NC17.M1.S-ID.7', 1, 'choice', 'Judge whether a prediction is valid', 'Which question helps you decide whether a prediction from a linear model is valid?', '["Is the slope of the model a whole number of units?","Is the $x$-value near the $x$-values in the data?","Is the $y$-intercept of the model a positive number?","Is the $x$-value we want a whole number?"]', 'Is the $x$-value near the $x$-values in the data?', NULL, 'A prediction is most trustworthy when the input is within, or close to, the range of the data that built the model. Whether the slope or the numbers are whole does not matter.', 'checked', '{"lint":[],"solve":{"answer":"Is the $x$-value near the $x$-values in the data?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Validity depends on x being near the data range.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38c35f81-0414-436c-8ab8-36bc0a13e19e', 'NC17.M1.S-ID.7', 2, 'choice', 'Interpolate with a linear model', 'The model $y = 5x - 2$ was built from data with $x$ from 4 to 20. Which prediction uses interpolation and is calculated correctly?', '["At $x = 10$, the model predicts $y = 52$","At $x = 2$, the model predicts $y = 8$","At $x = 10$, the model predicts $y = 48$","At $x = 25$, the model predicts $y = 123$"]', 'At $x = 10$, the model predicts $y = 48$', NULL, 'Only $x = 10$ is inside the range 4 to 20. Then $y = 5(10) - 2 = 48$. The value 52 comes from adding 2 instead of subtracting it, and $x = 2$ and $x = 25$ are outside the range, so they are extrapolations.', 'checked', '{"lint":[],"solve":{"answer":"At $x = 10$, the model predicts $y = 48$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=10 inside [4,20]; 5*10-2 = 48. D miscalculated; B and C are extrapolations.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c15cd79-79c7-4b4c-9485-26fd70e71077', 'NC17.M1.S-ID.7', 2, 'choice', 'Extrapolate with a linear model', 'The model $h = 6.2a + 80$ predicts a child''s height $h$, in centimeters, at age $a$, and was built from data on children aged 2 to 10. A student predicts that a 30-year-old is $6.2(30) + 80 = 266$ centimeters tall. Why is this prediction unreasonable?', '["Age 30 is far outside the data, where growth is no longer steady","The slope is positive, so the model cannot be used to predict heights","The intercept is greater than zero, so the model must be wrong","The model can only be used with whole-number ages"]', 'Age 30 is far outside the data, where growth is no longer steady', NULL, 'Age 30 is far beyond the ages 2 to 10 in the data. Children grow at a roughly steady rate, but adults stop growing, so the line does not continue to fit.', 'checked', '{"lint":[],"solve":{"answer":"Age 30 is far outside the data, where growth is no longer steady","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Age 30 far outside 2-10 where growth stops: extrapolation unreasonable.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77b3df8f-c757-40f2-8a7c-cc45d2f8e738', 'NC17.M1.S-ID.7', 2, 'choice', 'Judge whether a prediction is valid', 'The model $F = -12w + 300$ predicts the number $F$ of fish in a pond $w$ weeks after a disease starts. For $w = 30$ it gives $F = -60$. What does this show?', '["The pond is predicted to have 60 fish left at week 30","The model is valid, because the slope of the line is negative","The disease is predicted to stop spreading after week 30","The model fails at week 30, since fish cannot be negative"]', 'The model fails at week 30, since fish cannot be negative', NULL, 'A number of fish cannot be negative, so the prediction $-60$ is impossible. The line only describes the pond for weeks up to the point where $F$ reaches 0.', 'checked', '{"lint":[],"solve":{"answer":"The model fails at week 30, since fish cannot be negative","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fish count cannot be negative; model fails at week 30.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ae86e10-5c85-471b-8be3-8aaded41bf4d', 'NC17.M1.S-ID.7', 3, 'choice', 'Interpret the slope of a linear model', 'The model $P = -1.8a + 22$ predicts the price $P$, in thousands of dollars, of a used car that is $a$ years old. Which statement correctly interprets the slope?', '["Each extra year of age lowers the predicted price by 1.8 dollars","Each extra year of age raises the predicted price by 1.8 thousand dollars","A car that is new is predicted to cost 1.8 thousand dollars","Each extra year of age lowers the predicted price by 1.8 thousand dollars"]', 'Each extra year of age lowers the predicted price by 1.8 thousand dollars', NULL, 'The slope is $-1.8$, and $P$ is in thousands of dollars, so each extra year changes the predicted price by $-1.8$ thousand dollars. The price falls by 1.8 thousand dollars (1,800 dollars) per year.', 'checked', '{"lint":[],"solve":{"answer":"Each extra year of age lowers the predicted price by 1.8 thousand dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope -1.8 thousand dollars per year: lowers by 1.8 thousand each year.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
