INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18a17095-739b-40e9-b76d-d54609c93b4b', 'NC17.M1.S-ID.7', 3, 'choice', 'Judge whether a prediction is valid', 'A plant''s height rose steadily for the first 8 weeks and then leveled off at 40 centimeters. A linear model fitted to the data for weeks 1 to 8 predicts a height of 90 centimeters at week 20. Why should this prediction not be trusted?', '["The growth leveled off, so the line does not describe week 20","The line was fitted to just 8 weeks of data, which is too few","Heights of plants can never be predicted by using any line","Week 20 is a whole number of weeks, so no line can fit it"]', 'The growth leveled off, so the line does not describe week 20', NULL, 'The line only describes the steady growth of weeks 1 to 8. The plant leveled off at 40 centimeters, so a prediction of 90 centimeters at week 20 is not valid.', 'checked', '{"lint":[],"solve":{"answer":"The growth leveled off, so the line does not describe week 20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth leveled off at 40 cm, so linear trend doesn''t hold at week 20.","run_id":"claude-code","at":"2026-10-24T08:47:09.687Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b092986-5da0-4a25-b9b6-77827cd30869', 'NC17.M1.S-ID.8', 1, 'choice', 'Interpret the correlation coefficient', 'Which value of $r$ shows the strongest linear relationship?', '["$r = -0.92$","$r = 0.85$","$r = 0.30$","$r = -0.45$"]', '$r = -0.92$', NULL, 'Strength depends on how close $r$ is to $1$ or $-1$, not on the sign. The value $-0.92$ is closest to $-1$, so it is the strongest.', 'checked', '{"lint":[],"solve":{"answer":"$r = -0.92$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strength = |r|; 0.92 largest.","run_id":"claude-code","at":"2026-10-28T18:48:28.405Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37aab081-d850-451b-bd03-452befaa21c9', 'NC17.M1.S-ID.8', 1, 'choice', 'Judge a linear fit from a residual plot', 'A residual plot for a linear model shows points scattered at random above and below the horizontal axis, with no pattern. What does this suggest?', '["A linear model is a poor fit for the data","The correlation coefficient is exactly $0$","The data set contains no outliers","A linear model is a good fit for the data"]', 'A linear model is a good fit for the data', NULL, 'Residuals scattered at random with no pattern mean a line captures the trend in the data, so a linear model is a good fit.', 'checked', '{"lint":[],"solve":{"answer":"A linear model is a good fit for the data","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random residual scatter with no pattern indicates a linear model fits well.","run_id":"claude-code","at":"2026-10-28T18:48:28.468Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f9e736f-a381-414f-b4db-a4305461fe4f', 'NC17.M1.S-ID.8', 1, 'numeric', 'Compute the correlation coefficient', 'The points $(1, 3)$, $(2, 5)$, $(3, 7)$ and $(4, 9)$ all lie exactly on one line that slopes upward. What is the value of $r$?', '[]', '1', '1', 'Points that lie exactly on a line with a positive slope have a perfect positive correlation, so $r = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Points exactly on an increasing line (y=2x+1): r = 1.","run_id":"claude-code","at":"2026-10-28T18:48:28.646Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ea07d4e-c313-4987-acd6-53664f86915c', 'NC17.M1.S-ID.8', 2, 'choice', 'Describe a relationship from a scatter plot', 'For five points, the $x$-values are $1, 2, 3, 4, 5$ and the $y$-values are $9, 7, 8, 4, 2$. Which statement describes $r$?', '["$r$ is close to $1$","$r$ is close to $0$","$r$ is close to $0.5$","$r$ is close to $-1$"]', '$r$ is close to $-1$', NULL, 'As $x$ goes up, $y$ mostly goes down, and the points follow a line closely. Computing gives $r \approx -0.92$, which is close to $-1$.', 'checked', '{"lint":[],"solve":{"answer":"$r$ is close to $-1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means 3 and 6; Sxy=-17, Sxx=10, Syy=34; r=-17/sqrt(340)~-0.92.","run_id":"claude-code","at":"2026-10-28T18:48:28.397Z"}}', 'ai', NULL, NULL)
