INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25e93ac4-3175-42d9-814f-fa9e90ae177c', 'NC17.M1.S-ID.8', 2, 'choice', 'Correlation versus causation and properties of r', 'A study finds $r = 0.7$ between the number of libraries and the number of restaurants in a city. Which statement is false?', '["Building more libraries will cause more restaurants to open","Cities with more libraries tend to have more restaurants","The relationship is positive and fairly strong","City size may explain both counts"]', 'Building more libraries will cause more restaurants to open', NULL, 'Correlation does not show cause. The false claim says libraries cause restaurants to open; a third factor such as city size may explain both.', 'checked', '{"lint":[],"solve":{"answer":"Building more libraries will cause more restaurants to open","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correlation does not show causation, so \"Building more libraries will cause more restaurants to open\" is false. The others are true/plausible statements.","run_id":"claude-code","at":"2026-10-28T18:48:28.649Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('154ee0d0-6271-4a2c-ba38-a5247077dacb', 'NC17.M1.S-ID.8', 2, 'numeric', 'Correlation versus causation and properties of r', 'The correlation between students'' heights in inches and their weights in pounds is $r = 0.8$. Every height is then converted from inches to centimeters. What is the new correlation coefficient?', '[]', '0.8', '0.8', 'Changing the units of a variable, by multiplying by a positive number, does not change $r$. It stays $0.8$.', 'checked', '{"lint":[],"solve":{"answer":"0.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Converting units is a positive linear change (x2.54), which does not change r: 0.8.","run_id":"claude-code","at":"2026-10-28T18:48:28.651Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04bddf03-edeb-4328-bb6a-df3efc869a3f', 'NC17.M1.S-ID.8', 3, 'choice', 'Correlation versus causation and properties of r', 'Which statement about the correlation coefficient is true?', '["A value of $r$ near $0$ means the two variables are unrelated in every way","The value of $r$ is the slope of the line of best fit","A value of $r$ near $0$ can occur when the points follow a clear curve","A value of $r$ can be greater than $1$ for very steep data"]', 'A value of $r$ near $0$ can occur when the points follow a clear curve', NULL, '$r$ measures only straight-line relationships. Points can follow a clear curve and still have $r$ near $0$. $r$ is not the slope and is always between $-1$ and $1$.', 'checked', '{"lint":[],"solve":{"answer":"A value of $r$ near $0$ can occur when the points follow a clear curve","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r is not the slope, is between -1 and 1, and measures only linear association; points on a clear curve (e.g. a U shape) can give r near 0.","run_id":"claude-code","at":"2026-10-28T18:48:28.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12900b1b-5461-49cc-af49-18c84d1cd5f7', 'NC17.M1.S-ID.8', 3, 'choice', 'Judge a linear fit from a residual plot', 'A data set has $r = 0.97$, but its residual plot shows a clear curved pattern. Which conclusion is best?', '["A line is the best model, because $r$ is close to $1$","A line is not the best model, even though $r$ is high","The residual plot must have been drawn wrongly","The correlation coefficient must be computed again"]', 'A line is not the best model, even though $r$ is high', NULL, 'A high $r$ only says the trend is strongly linear on average. A curved residual pattern shows a line misses a systematic bend, so a curve fits better.', 'checked', '{"lint":[],"solve":{"answer":"A line is not the best model, even though $r$ is high","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A curved residual pattern means a linear model is not appropriate despite high r.","run_id":"claude-code","at":"2026-10-28T18:48:28.439Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('314bf384-baf4-4774-b6ae-949752ecfc86', 'NC17.M1.S-ID.9', 1, 'numeric', 'Tell a causal claim from a statement of association', 'Here are four statements. (1) Taller children tend to read better. (2) Eating breakfast makes children read better. (3) Children who own bicycles tend to be older. (4) Drinking more water causes headaches to go away. How many of these statements say that one variable causes a change in the other?', '[]', '2', NULL, 'Statements (2) and (4) say that one thing makes or causes the other. Statements (1) and (3) only describe what tends to go together. So the answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) association, (2) \"makes\" causal, (3) association, (4) \"causes\" causal. Count 2.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d2b886c-ace5-4fdd-a00b-d48766311443', 'NC17.M1.S-ID.9', 1, 'choice', 'State what it means for two variables to be associated', 'Two variables are associated. Which statement must be true?', '["A change in one variable is always the cause of a change in the other","A third variable has been ruled out as an explanation for the pattern","The values of one variable tend to go along with the values of the other","Every change in one variable is matched exactly by a change in the other"]', 'The values of one variable tend to go along with the values of the other', NULL, 'Association only means the two variables tend to go together in some pattern. It does not say that one causes the other, and it does not rule out a third variable.', 'checked', '{"lint":[],"solve":{"answer":"The values of one variable tend to go along with the values of the other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Association means values tend to go together; nothing about cause.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('033c7bde-40f9-41e6-bf8a-4e4f3b1cbd30', 'NC17.M1.S-ID.9', 1, 'choice', 'Explain two things rising together by a common cause', 'Across a city, fires with more fire trucks at the scene tend to have more damage. A reporter says the trucks cause the damage. Which explanation is more sensible?', '["More trucks cause more damage, because trucks are what arrive at the fire","The damage and the number of trucks are unrelated, since trucks cannot cause damage","Fires with more trucks last longer because of the trucks that are sent to them","Bigger fires cause both more damage and more trucks being sent"]', 'Bigger fires cause both more damage and more trucks being sent', NULL, 'The size of the fire is a third variable. A bigger fire does more damage and also needs more trucks. The trucks do not cause the damage.', 'checked', '{"lint":[],"solve":{"answer":"Bigger fires cause both more damage and more trucks being sent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fire size is the lurking variable causing both damage and trucks.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c9761f0-2492-4840-b09c-63d227444b68', 'NC17.M1.S-ID.9', 2, 'choice', 'Judge which conclusion a study justifies', 'An observational study of 5,000 adults finds that those who eat walnuts weigh less on average. Which conclusion is justified?', '["Eating walnuts causes people to lose weight, since the sample of adults was so large","Walnuts have no effect on weight at all, because the study was not an experiment","Walnut eaters tend to weigh less, but the study cannot show walnuts are the reason","Weighing less causes people to eat walnuts, which the large sample proves"]', 'Walnut eaters tend to weigh less, but the study cannot show walnuts are the reason', NULL, 'An observational study can show an association. A large sample does not turn it into proof of cause, and it does not prove there is no effect either.', 'checked', '{"lint":[],"solve":{"answer":"Walnut eaters tend to weigh less, but the study cannot show walnuts are the reason","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Observational: association only, cannot show walnuts cause it.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d2d8d5a-aeca-4e0a-a850-fcc7974d4743', 'NC17.M1.S-ID.9', 2, 'choice', 'Judge which conclusion a study justifies', 'One hundred students are allowed to choose whether to use a study app. Those who chose it earned higher grades. Which statement is best?', '["Students who chose the app may differ in other ways, so it is not shown to be the cause","The app caused the higher grades, because the grades of both groups were compared","The app has no effect, because the students chose it themselves instead of being assigned","The app caused the higher grades, since 100 students is large enough to prove it"]', 'Students who chose the app may differ in other ways, so it is not shown to be the cause', NULL, 'The students picked the app themselves, so keener students may have chosen it. The study shows an association only.', 'checked', '{"lint":[],"solve":{"answer":"Students who chose the app may differ in other ways, so it is not shown to be the cause","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Self-selection: choosers may differ; not shown to be causal.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f9f7a5f-4175-4377-818b-5750ae1089f7', 'NC17.M1.S-ID.9', 2, 'choice', 'Explain two things rising together by a common cause', 'At beaches, those with more lifeguards also have more drownings. Which explanation is most reasonable?', '["Lifeguards cause drownings by distracting the swimmers who are in the water","Crowded beaches have both more swimmers at risk and more lifeguards hired","Having lifeguards on duty makes swimmers take more risks in the water","Each drowning causes the beach to hire several more lifeguards at once"]', 'Crowded beaches have both more swimmers at risk and more lifeguards hired', NULL, 'Beach crowds are the third variable: more swimmers means more chances of a drowning and more lifeguards hired.', 'checked', '{"lint":[],"solve":{"answer":"Crowded beaches have both more swimmers at risk and more lifeguards hired","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Crowded beaches: more swimmers at risk and more lifeguards.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b975a1e-5532-4839-b1db-0addba9c6954', 'NC17.M1.S-ID.9', 3, 'choice', 'Tell a causal claim from a statement of association', 'Which headline is most appropriate for an observational study that found people who eat more fruit have lower blood pressure?', '["Eating more fruit lowers your blood pressure, new study proves it","Fruit eaters tend to have lower blood pressure, a new study finds","New study shows that fruit is the cure for high blood pressure","Fruit causes blood pressure to drop, researchers have concluded"]', 'Fruit eaters tend to have lower blood pressure, a new study finds', NULL, 'An observational study can report an association. The other headlines claim that fruit causes the drop.', 'checked', '{"lint":[],"solve":{"answer":"Fruit eaters tend to have lower blood pressure, a new study finds","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Observational: association-only headline.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01a60295-a4aa-4c76-adc0-a93dbfefc616', 'NC17.M1.S-ID.9', 3, 'choice', 'Judge which conclusion a study justifies', 'After accounting for age, income and smoking, an observational study still finds that people who garden live longer. Can the researchers conclude that gardening causes longer life?', '["Yes, because accounting for three variables rules out every other explanation","Yes, because any association that remains after adjusting must be causal","No, because other lurking variables that were not measured could still explain it","No, because an observational study can never find any association between two variables"]', 'No, because other lurking variables that were not measured could still explain it', NULL, 'Adjusting for some variables helps, but unmeasured variables may remain. Only a randomized experiment supports a cause-and-effect conclusion.', 'checked', '{"lint":[],"solve":{"answer":"No, because other lurking variables that were not measured could still explain it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unmeasured lurking variables may remain; cannot conclude causation.","run_id":"claude-code","at":"2026-10-24T08:47:58.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03b93e0f-040a-4dc2-857a-b60ff9f6d67a', 'NC17.M2.N-RN.1', 1, 'numeric', 'Simplify with rational exponents', 'Evaluate $9^{\frac{1}{2}} + 16^{\frac{1}{2}}$.', '[]', '7', '3+4', '$9^{\frac{1}{2}} = 3$ and $16^{\frac{1}{2}} = 4$, so the sum is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9^(1/2) = 3, 16^(1/2) = 4; sum 7.","run_id":"claude-code","at":"2026-10-28T18:48:28.308Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a347011-a62d-43e8-8041-07d000eb1213', 'NC17.M2.N-RN.1', 1, 'choice', 'Rational exponent to radical', 'Maya writes $n^{\frac{1}{4}}$ as a radical expression, for $n \ge 0$. Which description is correct?', '["the fourth root of $n$","the square root of $n$","$n$ raised to the fourth power","one fourth of $n$"]', 'the fourth root of $n$', NULL, 'The denominator 4 of the exponent names the root, so $n^{\frac{1}{4}}$ is the fourth root of $n$.', 'checked', '{"lint":[],"solve":{"answer":"the fourth root of $n$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n^(1/4) is the fourth root of n.","run_id":"claude-code","at":"2026-10-28T18:48:28.523Z"}}', 'ai', NULL, NULL)
