INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11c0b917-a52c-4159-a96c-da6c4d6be139', 'NC17.M2.N-RN.1', 1, 'numeric', 'Evaluate a unit-fraction exponent', 'Evaluate $16^{\frac{1}{4}}$.', '[]', '2', '2', '$16^{\frac{1}{4}}$ is the fourth root of 16. Since $2 \cdot 2 \cdot 2 \cdot 2 = 16$, the answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16^(1/4) = fourth root of 16 = 2 since 2^4=16.","run_id":"claude-code","at":"2026-10-28T18:48:28.637Z"}}', 'ai', NULL, NULL)
