INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a2c23f8-7978-4c7f-957c-7f7d940acf4c', 'NC17.M2.N-RN.1', 2, 'choice', 'Simplify with rational exponents', 'Which expression is equivalent to $\left(y^{6}\right)^{\frac{1}{3}}$, for $y \ge 0$?', '["$y^{18}$","$y^{2}$","$y^{3}$","$y^{\\frac{1}{2}}$"]', '$y^{2}$', NULL, 'Multiply the exponents: $6 \cdot \frac{1}{3} = 2$, so the result is $y^2$.', 'checked', '{"lint":[],"solve":{"answer":"$y^{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(y^6)^(1/3) = y^(6/3) = y^2.","run_id":"claude-code","at":"2026-10-24T02:58:26.360Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d8f874f-719b-4823-834f-9aacd7344e9d', 'NC17.M2.N-RN.1', 2, 'numeric', 'Evaluate an m/n exponent', 'In a model, a planet''s orbit takes $T = a^{\frac{3}{2}}$ days, where $a$ is its distance from its star in units. How many days is $T$ when $a = 9$?', '[]', '27', '3^3', '$9^{\frac{3}{2}}$ is the square root of 9, cubed: $3^{3} = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9^{3/2} = (sqrt 9)^3 = 27.","run_id":"claude-code","at":"2026-10-28T18:48:28.054Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('047d745a-8ad9-4f95-8edd-d7473bc14542', 'NC17.M2.N-RN.1', 2, 'numeric', 'Simplify with rational exponents', 'Evaluate $9^{\frac{1}{4}} \cdot 9^{\frac{1}{4}}$.', '[]', '3', '3', 'Add the exponents: $\frac{1}{4} + \frac{1}{4} = \frac{1}{2}$, so the product is $9^{\frac{1}{2}} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9^(1/4)*9^(1/4) = 9^(1/2) = 3.","run_id":"claude-code","at":"2026-10-28T18:48:28.644Z"}}', 'ai', NULL, NULL)
