INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15158a67-ce78-4d3e-963c-1dfba879e1b3', 'NC17.M2.N-RN.1', 3, 'choice', 'Negative rational exponent', 'Which expression is equivalent to $\frac{1}{\sqrt{x^{3}}}$, for $x > 0$?', '["$x^{-\\frac{2}{3}}$","$x^{\\frac{3}{2}}$","$x^{-6}$","$x^{-\\frac{3}{2}}$"]', '$x^{-\frac{3}{2}}$', NULL, '$\sqrt{x^{3}} = x^{\frac{3}{2}}$, and the reciprocal of $x^{\frac{3}{2}}$ is $x^{-\frac{3}{2}}$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{-\\frac{3}{2}}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/sqrt(x^3) = 1/x^(3/2) = x^(-3/2).","run_id":"claude-code","at":"2026-10-28T18:48:28.111Z"}}', 'ai', NULL, NULL)
