INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14084a32-9199-4bea-a26e-b63009f5c94e', 'NC17.M2.N-RN.1', 3, 'numeric', 'Negative rational exponent', 'In a model, the pressure of a gas is $P = V^{-\frac{3}{4}}$, where $V$ is the volume in liters. What is $P$ when $V = 81$?', '[]', '1/27', '1/27', '$81^{-\frac{3}{4}} = \frac{1}{81^{\frac{3}{4}}}$. The fourth root of 81 is 3, and $3^{3} = 27$, so $P = \frac{1}{27}$.', 'checked', '{"lint":[],"solve":{"answer":"1/27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"81^(1/4) = 3, cubed 27, negative exponent: 1/27.","run_id":"claude-code","at":"2026-10-28T18:48:28.599Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0538af0a-90c6-438f-a5ee-a4c9522e024a', 'NC17.M2.N-RN.2', 1, 'choice', 'Power of a power with rational exponents', 'Simplify $\left(x^{2}\right)^{\frac{1}{2}}$, where $x > 0$. What is the result?', '["$x^{4}$","$x^{\\frac{1}{4}}$","$x^{\\frac{3}{2}}$","$x$"]', '$x$', NULL, 'For a power of a power, multiply the exponents: $2 \cdot \frac{1}{2} = 1$, so the result is $x^{1} = x$.', 'checked', '{"lint":[],"solve":{"answer":"$x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^2)^{1/2} = x^{2*1/2} = x^1 = x.","run_id":"claude-code","at":"2026-10-24T02:59:01.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('068b439f-ba92-4531-8ab3-d110109518bf', 'NC17.M2.N-RN.2', 1, 'choice', 'Evaluate a power with a rational exponent', 'Which of these expressions equals 8?', '["$4^{\\frac{3}{2}}$","$64^{\\frac{1}{3}}$","$16^{\\frac{1}{2}}$","$9^{\\frac{3}{2}}$"]', '$4^{\frac{3}{2}}$', NULL, '$4^{\frac{3}{2}} = \left(\sqrt{4}\right)^{3} = 2^{3} = 8$. The others are 4, 4 and 27.', 'checked', '{"lint":[],"solve":{"answer":"$4^{\\frac{3}{2}}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16^{1/2}=4, 9^{3/2}=27, 4^{3/2}=8, 64^{1/3}=4. So 4^{3/2}.","run_id":"claude-code","at":"2026-10-28T19:20:44.505Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f202c5c-5635-4781-9f0b-ef620f618678', 'NC17.M2.N-RN.2', 1, 'numeric', 'Evaluate a power with a unit-fraction exponent', 'A cube has a volume of 216 cubic centimeters. Its edge length is $216^{\frac{1}{3}}$ centimeters. How long is each edge, in centimeters?', '[]', '6', '6', 'An exponent of $\frac{1}{3}$ means the cube root. Since $6 \times 6 \times 6 = 216$, the edge is 6 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"216^{1/3} = 6.","run_id":"claude-code","at":"2026-10-28T19:20:44.550Z"}}', 'ai', NULL, NULL)
