INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c10212-d413-4adf-b741-552f1bc5a6eb', 'NC17.M2.N-RN.2', 2, 'numeric', 'Simplify a radical', 'The number $\sqrt{72}$ can be written as $a\sqrt{2}$, where $a$ is a whole number. What is $a$?', '[]', '6', '6', 'Write $72 = 36 \cdot 2$. Then $\sqrt{72} = \sqrt{36}\cdot\sqrt{2} = 6\sqrt{2}$, so $a = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 36*2, sqrt72 = 6 sqrt2, a = 6.","run_id":"claude-code","at":"2026-10-24T02:59:01.952Z"}}', 'ai', NULL, NULL)
