VALUES ('0046dc2d-246a-4526-8f10-075e5046a43d', 'NC17.M2.N-RN.2', 3, 'numeric', 'Product and quotient of powers with rational exponents', 'Evaluate $\dfrac{2^{\frac{5}{2}}}{2^{\frac{1}{2}}}$.', '[]', '4', '2^2', 'Subtract the exponents: $\frac{5}{2} - \frac{1}{2} = 2$, so the value is $2^{2} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^{5/2 - 1/2} = 2^2 = 4.","run_id":"claude-code","at":"2026-10-24T02:59:01.952Z"}}', 'ai', NULL, NULL)
