INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('030c5db9-0f1f-42d9-a4d3-7c7ef2764764', 'NC17.M2.N-RN.2', 3, 'choice', 'Rewrite a radical expression with a variable', 'For $x > 0$, which is the cube root of $24x^{4}$ in simplest form?', '["$2x$ times the cube root of $3$","$2x$ times the cube root of $3x$","$8x$ times the cube root of $3x$","$2x^{2}$ times the cube root of $3x$"]', '$2x$ times the cube root of $3x$', NULL, '$24x^{4} = 8x^{3} \cdot 3x$. The cube root of $8x^{3}$ is $2x$, and the cube root of $3x$ stays inside the radical.', 'checked', '{"lint":[],"solve":{"answer":"$2x$ times the cube root of $3x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24x^4 = (8x^3)(3x), cube root = 2x·∛(3x).","run_id":"claude-code","at":"2026-10-28T19:20:44.520Z"}}', 'ai', NULL, NULL)
