INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0afe9412-e92f-438c-9066-ae3d74f4f6ab', 'NC17.M2.N-RN.3', 1, 'choice', 'classify a number as rational or irrational', 'Which number is rational?', '["$\\sqrt{9} + \\sqrt{16}$","$\\sqrt{5} \\times \\frac{2}{3}$","$\\pi \\times 3$","$1 + \\sqrt{7}$"]', '$\sqrt{9} + \sqrt{16}$', NULL, '$\sqrt{9} = 3$ and $\sqrt{16} = 4$, so the sum is 7, a rational number. The others are a nonzero rational times an irrational, or a rational plus an irrational, so they are irrational.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{9} + \\sqrt{16}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt9 + sqrt16 = 3 + 4 = 7, rational. Others are irrational.","run_id":"claude-code","at":"2026-10-24T02:58:26.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12d8fbd9-a03a-4465-8671-072f78cea741', 'NC17.M2.N-RN.3', 1, 'numeric', 'Sum of rationals', 'The repeating decimal $0.2222\ldots$ equals $\frac{2}{9}$. Add it to $\frac{1}{2}$. Write the sum as a fraction.', '[]', '13/18', '2/9+1/2', '$\frac{2}{9} + \frac{1}{2} = \frac{4}{18} + \frac{9}{18} = \frac{13}{18}$.', 'checked', '{"lint":[],"solve":{"answer":"13/18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/9 + 1/2 = 4/18 + 9/18 = 13/18.","run_id":"claude-code","at":"2026-10-28T19:20:44.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('062ef44a-429e-4ab3-a180-924fcbb6beee', 'NC17.M2.N-RN.3', 1, 'choice', 'Nonzero rational times irrational', 'The number $\pi$ is irrational. Which product is irrational?', '["$\\frac{3}{5} \\cdot \\frac{10}{3}$","$\\sqrt{16} \\cdot \\frac{1}{2}$","$0 \\cdot \\sqrt{7}$","$\\frac{3}{5} \\cdot \\pi$"]', '$\frac{3}{5} \cdot \pi$', NULL, '$\frac{3}{5}$ is a nonzero rational, so $\frac{3}{5}\pi$ is irrational. The others equal $2$, $2$ and $0$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5} \\cdot \\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/5)pi is a nonzero rational times an irrational: irrational. Others: 2, 2, 0, all rational.","run_id":"claude-code","at":"2026-10-28T19:20:44.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('180e556e-9406-4c84-8655-ecdb014f6440', 'NC17.M2.N-RN.3', 2, 'choice', 'Classify a sum or product as rational or irrational', 'The numbers $\pi$, $\sqrt{2}$ and $\sqrt{5}$ are irrational. Which list contains only irrational numbers?', '["$\\frac{1}{3}\\sqrt{2}$, $0 \\cdot \\pi$, $\\sqrt{5} - 2$","$\\frac{1}{3}\\sqrt{2}$, $4 + \\pi + \\frac{1}{2}$, $\\sqrt{5} - 2$","$\\frac{1}{3}\\sqrt{2}$, $4 + \\pi$, $\\frac{\\sqrt{9}}{2}$","$\\left(\\sqrt{5} + 1\\right) - \\sqrt{5}$, $4 + \\pi$, $\\sqrt{5} - 2$"]', '$\frac{1}{3}\sqrt{2}$, $4 + \pi + \frac{1}{2}$, $\sqrt{5} - 2$', NULL, 'In the first list, each number is a rational plus an irrational or a nonzero rational times an irrational. Each other list has a rational: $0\cdot\pi=0$, $\frac{\sqrt{9}}{2}=\frac{3}{2}$, or $(\sqrt{5}+1)-\sqrt{5}=1$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}\\sqrt{2}$, $4 + \\pi + \\frac{1}{2}$, $\\sqrt{5} - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Option 1: (1/3)sqrt2, 4.5+pi, sqrt5-2 all irrational. Others contain 0*pi=0, sqrt9/2=3/2, (sqrt5+1)-sqrt5=1, which are rational.","run_id":"claude-code","at":"2026-10-28T19:20:44.422Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('139444a3-6c92-442e-917d-9957c551c4a4', 'NC17.M2.N-RN.3', 2, 'numeric', 'Rational plus irrational', 'What is the value of $\left(3 + \sqrt{5}\right) + \left(\frac{1}{2} - \sqrt{5}\right)$? Write it as a fraction.', '[]', '7/2', '3+1/2', 'The $\sqrt{5}$ terms cancel, leaving $3+\frac{1}{2}=\frac{7}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"7/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Irrational parts cancel: 3 + 1/2 = 7/2.","run_id":"claude-code","at":"2026-10-28T19:20:44.520Z"}}', 'ai', NULL, NULL)
