INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12c1a3e9-f3d6-4279-ad4a-b87cbacadf15', 'NC17.M2.N-RN.3', 2, 'numeric', 'Rational plus irrational', 'For how many whole numbers $n$ from 1 to 10 is $\sqrt{n} + \frac{1}{2}$ a rational number?', '[]', '3', NULL, '$\sqrt{n}+\frac{1}{2}$ is rational only when $\sqrt{n}$ is rational, that is, when $n$ is a perfect square. The perfect squares from 1 to 10 are 1, 4 and 9. So 3 numbers work.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt n + 1/2 rational iff n is a perfect square: 1,4,9. Count 3.","run_id":"claude-code","at":"2026-10-28T19:20:44.652Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b31e77b-dedb-40c8-9a81-233b3744890d', 'NC17.M2.N-RN.3', 3, 'numeric', 'Two irrationals', 'What is the value of $\left(\frac{3}{4}\sqrt{8}\right)\left(\frac{2}{3}\sqrt{2}\right)$?', '[]', '2', '3/4*2/3*4', '$\sqrt{8}\cdot\sqrt{2}=\sqrt{16}=4$ and $\frac{3}{4}\cdot\frac{2}{3}=\frac{1}{2}$. So the product is $\frac{1}{2}\cdot 4 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4)(2/3)=1/2; sqrt8*sqrt2=sqrt16=4; product 2.","run_id":"claude-code","at":"2026-10-28T19:20:44.395Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06035493-359e-4f08-a176-0517dfb198ba', 'NC17.M2.N-RN.3', 3, 'choice', 'Rational plus irrational', 'The number $x$ is irrational. Which expression must be irrational?', '["$x - x + \\frac{1}{2}$","$\\frac{x}{x} + 1$","$3x + \\frac{1}{2}$","$x \\cdot x + 1$"]', '$3x + \frac{1}{2}$', NULL, '$3x$ is a nonzero rational times an irrational, so it is irrational, and adding $\frac{1}{2}$ keeps it irrational. $x-x+\frac{1}{2}=\frac{1}{2}$ and $\frac{x}{x}+1=2$ are rational, and $x\cdot x+1$ can be rational (for $x=\sqrt{2}$) or irrational (for $x=\pi$).', 'checked', '{"lint":[],"solve":{"answer":"$3x + \\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+1/2: nonzero rational times irrational plus rational, irrational. x*x+1 can be 3 (x=sqrt2); x-x+1/2=1/2; x/x+1=2.","run_id":"claude-code","at":"2026-10-28T19:20:44.654Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
