INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09020092-4963-4c3f-a61c-fa8c7adcfc57', 'NC17.M2.N-CN.1', 3, 'numeric', 'Classify real and imaginary numbers', 'The number $(2k + 6) + (k + 5)i$ is purely imaginary, meaning its real part is $0$ and its imaginary part is not $0$. What is $k$?', '[]', '-3', '-6/2', 'The real part must be $0$: $2k + 6 = 0$, so $k = -3$. Then the imaginary part is $-3 + 5 = 2 \ne 0$, so the condition holds.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Real part 2k+6=0 -> k=-3; imaginary part -3+5=2, not 0. k=-3.","run_id":"claude-code","at":"2026-10-28T19:20:44.575Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04ad00df-9af4-450a-83ca-b398e2dbe8a6', 'NC17.M2.N-CN.1', 3, 'choice', 'Write a complex number as a + bi', 'Which is $(5i)^2 - 2i^3$ written in the form $a + bi$?', '["$25 + 2i$","$-25 - 2i$","$-25 + 2i$","$25 - 2i$"]', '$-25 + 2i$', NULL, '$(5i)^2 = 25i^2 = -25$. $i^3 = -i$, so $-2i^3 = 2i$. The number is $-25 + 2i$.', 'checked', '{"lint":[],"solve":{"answer":"$-25 + 2i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5i)^2 = -25; i^3 = -i so -2i^3 = 2i. Result -25 + 2i.","run_id":"claude-code","at":"2026-10-28T19:20:44.577Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('079d643e-acb0-4bfd-9bef-fc8696e611c0', 'NC17.M2.A-SSE.1', 1, 'numeric', 'terms and coefficients of a quadratic in context', 'A shop''s profit in dollars from selling $x$ items is $P(x) = -2x^2 + 60x - 150$. The constant term is the profit when no items are sold. What is that profit, in dollars?', '[]', '-150', '-2*0^2+60*0-150', 'With no items sold, $x = 0$, so $P(0) = -150$. The constant term is the profit, a loss of 150 dollars.', 'checked', '{"lint":[],"solve":{"answer":"-150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(0)=-150.","run_id":"claude-code","at":"2026-10-24T03:06:04.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f0022c-3bc1-406d-b8ba-99649d069888', 'NC17.M2.A-SSE.1', 1, 'choice', 'reading a multi-part expression as a single entity', 'A teacher buys 4 identical party packs. Each pack costs $0.25x + 3$ dollars, where $x$ is the number of balloons in the pack. The total cost is $4(0.25x + 3)$ dollars. What does the part $0.25x + 3$ represent?', '["The total cost of all 4 packs","The cost of the balloons in one pack only","The total cost of one pack","The number of balloons in one pack"]', 'The total cost of one pack', NULL, 'The factor 4 counts the packs, so the part inside the parentheses is a single pack''s cost: the balloons, $0.25x$, plus the 3 dollar charge.', 'checked', '{"lint":[],"solve":{"answer":"The total cost of one pack","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.25x+3 is the given cost of each pack: total cost of one pack (0.25x is balloons only).","run_id":"claude-code","at":"2026-10-24T03:06:04.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06e282d0-fdfa-4391-85fa-83e90f944c5b', 'NC17.M2.A-SSE.1', 1, 'numeric', 'square root expression in context', 'A cart rolls down a ramp that is $h$ meters tall. Its speed at the bottom, in meters per second, is about $v = \sqrt{20h}$. What is the speed for a ramp that is 5 meters tall?', '[]', '10', '10', '$v = \sqrt{20 \times 5} = \sqrt{100} = 10$ meters per second.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"v=sqrt(20x5)=sqrt(100)=10.","run_id":"claude-code","at":"2026-10-28T19:29:58.911Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0779436d-6bf3-476d-adb0-9929f0841c3b', 'NC17.M2.A-SSE.1', 2, 'choice', 'reading a multi-part expression as a single entity', 'A rectangle has length $2x + 1$ and width $x + 5$. What does the expression $2[(2x + 1) + (x + 5)]$ represent?', '["The perimeter of the rectangle","The area of the rectangle","Half of the perimeter of the rectangle","The length of a diagonal of the rectangle"]', 'The perimeter of the rectangle', NULL, 'The sum of the length and width is half the way around the rectangle. Doubling it gives the whole distance around: the perimeter.', 'checked', '{"lint":[],"solve":{"answer":"The perimeter of the rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(length+width) is the perimeter.","run_id":"claude-code","at":"2026-10-24T03:06:04.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a7ad2c8-a3fb-49d8-8243-249128bf9473', 'NC17.M2.A-SSE.1', 2, 'numeric', 'vertex form: vertex and greatest or least value', 'A rocket''s height in meters at $t$ seconds is $h(t) = -5(t - 4)^2 + 100$. The rocket is launched from the top of a platform at $t = 0$. How many meters high is the platform?', '[]', '20', '-5*(0-4)^2+100', 'The platform''s height is the rocket''s height at $t = 0$: $h(0) = -5(-4)^2 + 100 = -80 + 100 = 20$ meters.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(0)=-5(16)+100=20.","run_id":"claude-code","at":"2026-10-28T19:29:58.602Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('012ba529-ce74-4c4f-a321-b17da413dab3', 'NC17.M2.A-SSE.1', 2, 'numeric', 'terms and coefficients of a quadratic in context', 'A theater''s revenue in dollars at a ticket price of $p$ dollars is $R(p) = 80p - 2p^2$. The term $2p^2$ is the revenue lost because higher prices drive customers away. How many dollars of revenue are lost to this effect when $p = 15$?', '[]', '450', '2*15^2', 'The lost revenue is the value of $2p^2$ at $p = 15$: $2 \times 15^2 = 2 \times 225 = 450$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"450","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2p^2 = 2 x 225 = 450.","run_id":"claude-code","at":"2026-10-28T19:29:58.888Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0adaec59-26cf-4523-8992-378b3f47a7a2', 'NC17.M2.A-SSE.1', 3, 'numeric', 'terms and coefficients of a quadratic in context', 'A store''s profit in dollars from selling $x$ items is $P(x) = -x^2 + 10x$. The term $10x$ is the money gained, and the term $x^2$ is the money lost to discounts. For a positive number of items, the gain equals the loss at exactly one value of $x$. What is that value?', '[]', '10', '10', 'The gain equals the loss when $10x = x^2$. For $x > 0$, divide both sides by $x$ to get $x = 10$. At 10 items the profit is $-100 + 100 = 0$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x=x^2 -> x(x-10)=0 -> positive x=10.","run_id":"claude-code","at":"2026-10-24T03:06:04.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('096af088-4bfa-451c-be36-16e814bd985e', 'NC17.M2.A-SSE.1', 3, 'numeric', 'square root expression in context', 'The time in seconds for a pendulum of length $L$ meters to swing once back and forth is about $T = 2\sqrt{L}$. A pendulum 4 meters long swings once in 4 seconds. A clockmaker wants a pendulum whose swing takes 3 seconds longer. How long, in meters, must it be?', '[]', '12.25', '((4+3)/2)^2', 'The new time is $4 + 3 = 7$ seconds. Solve $2\sqrt{L} = 7$: $\sqrt{L} = 3.5$, so $L = 3.5^2 = 12.25$ meters.', 'checked', '{"lint":[],"solve":{"answer":"12.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"T=4+3=7 -> sqrt(L)=3.5 -> L=12.25.","run_id":"claude-code","at":"2026-10-24T03:06:04.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08b219c5-598d-4bea-9706-67108bd5caae', 'NC17.M2.A-SSE.3', 1, 'numeric', 'Find the number that completes the square', 'The trinomial $x^2 + 20x + 100$ equals $(x + n)^2$. What is $n$?', '[]', '10', '20/2', 'In $(x + n)^2 = x^2 + 2nx + n^2$, the middle term $2nx$ must be $20x$, so $n = 10$. Check: $n^2 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+n)^2 = x^2 + 2nx + n^2; 2n = 20, n = 10, n^2 = 100.","run_id":"claude-code","at":"2026-10-28T19:34:46.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06a63b2d-75a5-4989-ad54-a7271e2481c6', 'NC17.M2.A-SSE.3', 1, 'numeric', 'Rewrite a quadratic in vertex form (leading coefficient 1)', 'Write $y = x^2 - 6x + 4$ as $y = (x - 3)^2 + k$. What is $k$?', '[]', '-5', '4-9', '$(x - 3)^2 = x^2 - 6x + 9$. To get back to $x^2 - 6x + 4$ we subtract 5, so $k = 4 - 9 = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2 = x^2 - 6x + 9; k = 4 - 9 = -5.","run_id":"claude-code","at":"2026-10-28T19:34:46.089Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29dc3b97-9a8c-482b-a2dc-6c04a02a168e', 'NC17.M2.A-SSE.3', 1, 'numeric', 'Solve a maximum or minimum problem in context', 'A bakery''s daily profit, in dollars, is $P = -(n - 40)^2 + 250$, where $n$ is the number of loaves baked. How many loaves give the greatest profit?', '[]', '40', '40', 'The profit is largest when $(n - 40)^2 = 0$, that is $n = 40$ loaves.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex at n=40.","run_id":"claude-code","at":"2026-10-28T19:34:46.187Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ebd56f1-05cd-4763-b3d6-a2a7da25a068', 'NC17.M2.A-SSE.3', 2, 'numeric', 'Find the minimum or maximum value by completing the square (leading coefficient not 1)', 'What is the minimum value of $f(x) = 2x^2 + 8x + 3$?', '[]', '-5', '3-2*4', 'Factor 2 out of the $x$ terms: $2(x^2 + 4x) + 3 = 2\left((x + 2)^2 - 4\right) + 3 = 2(x + 2)^2 - 8 + 3 = 2(x + 2)^2 - 5$. The minimum value is $-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x^2 + 4x) + 3 = 2(x+2)^2 - 8 + 3 = 2(x+2)^2 - 5. Min -5.","run_id":"claude-code","at":"2026-10-24T03:06:49.040Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b42883-ea67-48a3-8cfc-1af0d7d8fe5d', 'NC17.M2.A-SSE.3', 2, 'numeric', 'Find the minimum or maximum value by completing the square (leading coefficient 1)', 'What is the minimum value of $f(x) = x^2 + 14x + 38$?', '[]', '-11', '38-49', '$x^2 + 14x + 38 = (x + 7)^2 + 38 - 49 = (x + 7)^2 - 11$. The minimum value is $-11$.', 'checked', '{"lint":[],"solve":{"answer":"-11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+14x+38 = (x+7)^2 - 49 + 38 = (x+7)^2 - 11. Minimum -11.","run_id":"claude-code","at":"2026-10-28T19:34:46.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d34283d-4c2b-4166-9602-d190ade9b483', 'NC17.M2.A-SSE.3', 2, 'choice', 'Rewrite a quadratic in vertex form (leading coefficient 1)', 'Which expression is equal to $-x^2 + 6x - 5$?', '["$-(x - 3)^2 - 4$","$-(x - 3)^2 + 4$","$-(x + 3)^2 + 4$","$-(x - 3)^2 + 14$"]', '$-(x - 3)^2 + 4$', NULL, 'Factor out $-1$: $-(x^2 - 6x + 5) = -[(x - 3)^2 - 4] = -(x - 3)^2 + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$-(x - 3)^2 + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-(x^2-6x)-5 = -(x-3)^2+9-5 = -(x-3)^2+4.","run_id":"claude-code","at":"2026-10-28T19:34:46.351Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('085d5535-469b-4a06-b9df-31d5afe9e26c', 'NC17.M2.A-SSE.3', 3, 'choice', 'Rewrite a quadratic in vertex form (leading coefficient not 1)', 'Which expression is equivalent to $-2x^2 + 8x - 3$?', '["$-2(x - 2)^2 + 1$","$-2(x - 2)^2 - 11$","$-2(x - 2)^2 + 5$","$-2(x + 2)^2 + 5$"]', '$-2(x - 2)^2 + 5$', NULL, '$-2x^2 + 8x - 3 = -2(x^2 - 4x + 4) + 8 - 3 = -2(x - 2)^2 + 5$. Note the 4 inside the parentheses is multiplied by $-2$, so it adds 8 outside.', 'checked', '{"lint":[],"solve":{"answer":"$-2(x - 2)^2 + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2(x^2-4x)-3=-2(x-2)^2+8-3=-2(x-2)^2+5.","run_id":"claude-code","at":"2026-10-28T19:34:46.204Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0824b03c-acb4-45bf-95be-5d774aa90432', 'NC17.M2.A-SSE.3', 3, 'numeric', 'Solve a maximum or minimum problem in context', 'The revenue, in dollars, from selling a toy at a price of $x$ dollars is $R(x) = x(60 - 3x)$. What is the greatest possible revenue, in dollars?', '[]', '300', '3*100', '$R(x) = -3x^2 + 60x = -3(x^2 - 20x + 100) + 300 = -3(x - 10)^2 + 300$. The greatest revenue is 300 dollars, at a price of 10 dollars.', 'checked', '{"lint":[],"solve":{"answer":"300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R = -3x^2+60x = -3(x-10)^2+300; max 300.","run_id":"claude-code","at":"2026-10-28T19:34:46.425Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d9cc92-6f54-4de0-86a7-78f29b2a3d9b', 'NC17.M2.A-APR.1', 1, 'numeric', 'Add and subtract polynomials', 'What is the coefficient of $x$ in the sum $(7x^2 + 3x - 1) + (2x^2 - 8x + 5)$?', '[]', '-5', '3-8', 'Add like terms: $3x + (-8x) = -5x$. The whole sum is $9x^2 - 5x + 4$, so the coefficient of $x$ is $-5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + (-8x) = -5x: coefficient -5.","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09989857-d4dc-4a7d-b311-64575cf7db04', 'NC17.M2.A-APR.1', 1, 'numeric', 'Multiply a binomial by a trinomial, or three factors', 'The polynomial $(x + 2)(x^2 + 3x + 4)$ is multiplied out. Before any like terms are combined, how many products of one term by another are there?', '[]', '6', '2*3', 'The first factor has 2 terms and the second has 3, and every term of one multiplies every term of the other: $2 \times 3 = 6$ products.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 terms times 3 terms = 6 products.","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17ee7504-440b-4f97-8f35-023fe62f5423', 'NC17.M2.A-APR.1', 1, 'numeric', 'Find a missing coefficient or factor', '$(x + a)(x + 4) = x^2 + 9x + 20$. What is $a$?', '[]', '5', '9-4', 'The coefficient of $x$ comes from $4x + ax = (4 + a)x$, so $4 + a = 9$ and $a = 5$. Check the constant: $5 \cdot 4 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a + 4 = 9 and 4a = 20: a = 5.","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b0c2bf5-7d44-4a51-a1f8-87e0d817af38', 'NC17.M2.A-APR.1', 2, 'numeric', 'Add and subtract polynomials', 'Let $A = 3x^2 - 5x + 2$ and $B = x^2 + 4x - 7$. What is the coefficient of $x$ in $A - 2B$?', '[]', '-13', '-5-2*4', '$2B = 2x^2 + 8x - 14$. Then $A - 2B = (3 - 2)x^2 + (-5 - 8)x + (2 + 14) = x^2 - 13x + 16$. The coefficient of $x$ is $-13$.', 'checked', '{"lint":[],"solve":{"answer":"-13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-coefficient: -5 - 2*4 = -13.","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2297c50a-a0f1-4e5a-8d76-0f6b38d220c4', 'NC17.M2.A-APR.1', 2, 'choice', 'Multiply two binomials', 'Multiply: $(3x + 2)(2x - 5)$.', '["$6x^2 - 10$","$6x^2 + 11x - 10$","$6x^2 - 11x - 10$","$6x^2 - 19x - 10$"]', '$6x^2 - 11x - 10$', NULL, '$(3x + 2)(2x - 5) = 6x^2 - 15x + 4x - 10 = 6x^2 - 11x - 10$. The middle terms are $-15x$ and $+4x$, which combine to $-11x$.', 'checked', '{"lint":[],"solve":{"answer":"$6x^2 - 11x - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x^2 - 15x + 4x - 10 = 6x^2 - 11x - 10.","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48fdc9e4-af44-4e5d-a6e3-8445b74b609b', 'NC17.M2.A-APR.1', 2, 'numeric', 'Polynomials behave like integers', 'When $x = 10$, the polynomial $2x^2 + x + 4$ equals the number 214, and $x + 3$ equals 13. The product $(2x^2 + x + 4)(x + 3)$ is written $2x^3 + bx^2 + cx + d$. What is $b$?', '[]', '7', '2*3+1*1', '$(2x^2 + x + 4)(x + 3) = 2x^3 + 6x^2 + x^2 + 3x + 4x + 12 = 2x^3 + 7x^2 + 7x + 12$. So $b = 7$. Check at $x = 10$: $2000 + 700 + 70 + 12 = 2782 = 214 \times 13$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 terms: 2x^2*3 = 6x^2 and x*x = x^2: b = 7. (Check: 2,7,7,12 -> 2782 = 214*13.)","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f01481a-1f46-4484-a978-c904e2b9deaa', 'NC17.M2.A-APR.1', 3, 'numeric', 'Polynomials behave like integers', 'When $x = 10$, the polynomial $5x^2 + 2x + 1$ equals 521 and $2x^2 + 6x + 3$ equals 263. Subtract the second polynomial from the first, then replace $x$ with 10 in the difference. What number do you get?', '[]', '258', '521-263', '$(5x^2 + 2x + 1) - (2x^2 + 6x + 3) = 3x^2 - 4x - 2$. At $x = 10$ this is $300 - 40 - 2 = 258$, which is $521 - 263$. Polynomial subtraction matches subtraction of the numbers.', 'checked', '{"lint":[],"solve":{"answer":"258","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference 3x^2 - 4x - 2; at x=10: 300 - 40 - 2 = 258 (= 521 - 263).","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03e0c39a-c005-4d28-8664-e0ff27389491', 'NC17.M2.A-APR.1', 3, 'choice', 'Find a missing coefficient or factor', 'Which polynomial, multiplied by $(x - 2)$, gives $x^3 - 5x^2 + 8x - 4$?', '["$x^2 - 3x + 2$","$x^2 - 3x - 2$","$x^2 + 3x + 2$","$x^2 - 3x + 4$"]', '$x^2 - 3x + 2$', NULL, 'Divide term by term: $x^3 \div x = x^2$, leaving $-3x^2 + 8x - 4$. Then $-3x$, leaving $2x - 4$, then $2$. The factor is $x^2 - 3x + 2$. Check: $(x - 2)(x^2 - 3x + 2) = x^3 - 5x^2 + 8x - 4$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 - 3x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)(x^2 - 3x + 2) = x^3 - 3x^2 + 2x - 2x^2 + 6x - 4 = x^3 - 5x^2 + 8x - 4.","run_id":"claude-code","at":"2026-10-24T03:07:46.336Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b959a26-bc03-4a5a-8c0c-eea2d70edac7', 'NC17.M2.A-CED.1', 1, 'choice', 'Inverse variation equation', 'The variable $y$ varies inversely with $x$, and $y=12$ when $x=3$. Which equation relates $y$ and $x$?', '["$y=4x$","$y=\\frac{4}{x}$","$y=\\frac{12}{x}$","$y=\\frac{36}{x}$"]', '$y=\frac{36}{x}$', NULL, 'Inverse variation has the form $xy=k$. Here $k=3 \cdot 12=36$, so $y=\frac{36}{x}$.', 'checked', '{"lint":[],"solve":{"answer":"$y=\\frac{36}{x}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k=xy=3*12=36, so y=36/x.","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2affaaee-4826-42c8-8e26-4bb80d5891f7', 'NC17.M2.A-CED.1', 1, 'choice', 'Quadratic equation from a projectile', 'A ball is thrown upward, and its height in feet after $t$ seconds is $h=-16t^2+32t$. Which equation can be solved to find when the ball lands on the ground?', '["$-16t^2+32t=32$","$-16t^2+32t=0$","$-16t+32=0$","$-16t^2+32t=16$"]', '$-16t^2+32t=0$', NULL, 'The ball is on the ground when its height is 0, so set $h=0$: $-16t^2+32t=0$.', 'checked', '{"lint":[],"solve":{"answer":"$-16t^2+32t=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lands when h=0: -16t^2+32t=0 (t=0 is the throw, t=2 the landing).","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17db7d95-f63f-4059-9070-237aeac26d67', 'NC17.M2.A-CED.1', 1, 'numeric', 'Right-triangle trigonometry situation', 'A ramp rises 3 feet over a horizontal distance of 12 feet. What is the tangent of the angle the ramp makes with the ground, as a fraction? Use $\tan = \frac{\text{opposite}}{\text{adjacent}}$.', '[]', '1/4', '3/12', 'The rise is opposite the angle and the horizontal distance is adjacent: $\tan=\frac{3}{12}=\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"tan = 3/12 = 1/4.","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c966125-6ba3-4cfb-9c6e-9639e0414e33', 'NC17.M2.A-CED.1', 2, 'numeric', 'Quadratic equation from an area situation', 'The length of a rectangle is 4 meters more than its width $w$, and its area is 60 square meters. Then $w(w+4)=60$. What is the width, in meters?', '[]', '6', '6', 'Expand: $w^2+4w-60=0$, which factors as $(w+10)(w-6)=0$. A width is positive, so $w=6$ meters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w^2+4w-60=0, (w+10)(w-6)=0, w=6 (positive).","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d905c34-d385-473e-a5ff-f2a5ce4540bb', 'NC17.M2.A-CED.1', 2, 'numeric', 'Inverse variation equation', 'The variable $y$ varies inversely with $x$, and $y=8$ when $x=6$. What is $y$ when $x=16$?', '[]', '3', '48/16', '$k=xy=6 \cdot 8=48$, so $y=\frac{48}{16}=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k=8*6=48, y=48/16=3.","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('333c4f88-46e3-4aab-846b-b6c2539a2ee2', 'NC17.M2.A-CED.1', 2, 'numeric', 'Quadratic equation from a number situation', 'The product of two consecutive positive integers is 72. If the smaller is $n$, then $n(n+1)=72$. What is the smaller integer?', '[]', '8', '8', 'Expand: $n^2+n-72=0$, which factors as $(n+9)(n-8)=0$. The positive solution is $n=8$ (and $8 \cdot 9=72$).', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n^2+n-72=0, (n+9)(n-8)=0, n=8 (positive).","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34c19317-4a54-4971-9a45-80288253f704', 'NC17.M2.A-CED.1', 3, 'choice', 'Right-triangle trigonometry situation', 'From a point on level ground 50 meters from the base of a building, the angle of elevation to the top of the building is $40^\circ$. Which expression gives the height of the building in meters?', '["$50\\tan 40^\\circ$","$\\frac{50}{\\tan 40^\\circ}$","$50\\sin 40^\\circ$","$50\\cos 40^\\circ$"]', '$50\tan 40^\circ$', NULL, 'The height is opposite the angle and 50 meters is adjacent, so $\tan 40^\circ=\frac{h}{50}$ and $h=50\tan 40^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$50\\tan 40^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"tan 40 = h/50, h = 50 tan 40.","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a54dff6-2140-4cae-aef2-112b5d9be193', 'NC17.M2.A-CED.1', 3, 'numeric', 'Square root equation', 'The distance $d$ in miles to the horizon from a height of $h$ feet is modeled by $d=\sqrt{\frac{3h}{2}}$. From what height in feet is the horizon 9 miles away?', '[]', '54', '81*2/3', 'Square both sides: $81=\frac{3h}{2}$. Then $h=\frac{81 \cdot 2}{3}=54$ feet.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"81 = 3h/2, h = 54.","run_id":"claude-code","at":"2026-10-24T03:07:50.592Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2df85414-4d53-46a0-adbb-7f363a8f9b94', 'NC17.M2.A-CED.2', 1, 'choice', 'Quadratic: write an equation from a situation', 'A rectangle has length x meters and width $x + 3$ meters. Its area is y square meters. Which equation gives y in terms of x?', '["$y = 4x + 6$","$y = x^2 + 3x$","$y = x^2 + 3$","$y = 2x + 3$"]', '$y = x^2 + 3x$', NULL, 'Area is length times width: $y = x(x + 3) = x^2 + 3x$. The equation $y = 4x + 6$ would be the perimeter.', 'checked', '{"lint":[],"solve":{"answer":"$y = x^2 + 3x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = x(x + 3) = x^2 + 3x.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26e613ad-4e14-44cf-91aa-d7f32bb51b08', 'NC17.M2.A-CED.2', 1, 'numeric', 'Square root: evaluate and domain', 'Find y in the equation $y = \sqrt{x + 5}$ when $x = 20$.', '[]', '5', '5', 'Substitute: $y = \sqrt{20 + 5} = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(25) = 5.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
