INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4aa333-ffa8-4c0d-a5b8-31ca9497c9c4', 'NC17.M2.A-CED.2', 1, 'numeric', 'Quadratic: evaluate and find intercepts', 'The graph of $y = 2x^2 - 5$ crosses the y-axis where $x = 0$. What is the y-coordinate of that point?', '[]', '-5', '-5', 'Substitute $x = 0$: $y = 2(0)^2 - 5 = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 2(0)^2 - 5 = -5.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
