INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68c1734c-c811-4c26-8dc3-e10846ee4ed4', 'NC17.M2.A-CED.2', 2, 'numeric', 'Quadratic: graph features (vertex, direction, width)', 'The graph of $y = (x - 3)^2 + 2$ is a parabola that opens upward. What is the smallest value of y on the graph?', '[]', '2', '2', 'The square $(x - 3)^2$ is at least 0, and it is 0 when $x = 3$. So the smallest y is $0 + 2 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x - 3)^2 >= 0, so minimum y = 2 at x = 3.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('009634da-4a22-48cc-9d4c-30ee3a7f89da', 'NC17.M2.A-CED.2', 2, 'numeric', 'Quadratic: evaluate and find intercepts', 'The graph of $y = x^2 - 2x - 8$ crosses the x-axis at two points. What is the x-coordinate of the one to the right of the y-axis?', '[]', '4', '4', 'Set $y = 0$: $x^2 - 2x - 8 = (x - 4)(x + 2) = 0$. So $x = 4$ or $x = -2$. The one to the right of the y-axis is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 2x - 8 = (x - 4)(x + 2) = 0, x = 4 or -2; right of y-axis: 4.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b70e1ff-f93e-408e-b987-f4523d2db064', 'NC17.M2.A-CED.2', 2, 'choice', 'Square root: evaluate and domain', 'Which describes all the x-values allowed for $y = \sqrt{x - 4}$?', '["$x \\le 4$","$x \\ge -4$","$x > 0$","$x \\ge 4$"]', '$x \ge 4$', NULL, 'The expression under the root must be 0 or more: $x - 4 \ge 0$, so $x \ge 4$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need x - 4 >= 0, so x >= 4.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('099c56b9-0d9e-4d7e-babc-9f69e8755951', 'NC17.M2.A-CED.2', 3, 'numeric', 'Square root: write an equation from a graph or situation', 'The graph of $y = a\sqrt{x}$ passes through the point $(16, 12)$. What is a?', '[]', '3', '12/4', 'Substitute: $12 = a\sqrt{16} = 4a$. So $a = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 = a*sqrt(16) = 4a, a = 3.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07c00a21-464a-458c-a18c-fff4ac607c93', 'NC17.M2.A-CED.2', 3, 'choice', 'Square root: write an equation from a graph or situation', 'A square root graph starts at $(4, 0)$ and passes through $(5, 1)$ and $(8, 2)$. Which equation is it?', '["$y = \\sqrt{x} - 4$","$y = \\sqrt{x + 4}$","$y = \\sqrt{x} + 4$","$y = \\sqrt{x - 4}$"]', '$y = \sqrt{x - 4}$', NULL, 'Shifting $y = \sqrt{x}$ right 4 gives $y = \sqrt{x - 4}$. It starts at $(4, 0)$, and $\sqrt{5 - 4} = 1$ and $\sqrt{8 - 4} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\sqrt{x - 4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(x - 4): x = 4 gives 0, x = 5 gives 1, x = 8 gives 2. Checks all.","run_id":"claude-code","at":"2026-10-24T03:10:38.848Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c4da96d-ff62-4820-935d-6d6f862909df', 'NC17.M2.A-CED.3', 1, 'choice', 'Write a square root system', 'Pipe A fills a tank so that the depth $d$ in feet after $t$ minutes is the square root of $t$. Pipe B fills a second tank so that its depth is half of $t$. Which system models the two depths?', '["$d = \\sqrt{t}$ and $d = 2t$","$d = t^2$ and $d = \\frac{t}{2}$","$d = \\sqrt{t}$ and $d = \\frac{t}{2}$","$d = \\sqrt{2t}$ and $d = \\frac{t}{2}$"]', '$d = \sqrt{t}$ and $d = \frac{t}{2}$', NULL, 'The depth in the first tank is $\sqrt{t}$. The depth in the second tank is half of $t$, which is $\frac{t}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$d = \\sqrt{t}$ and $d = \\frac{t}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square root of t: d=sqrt t; half of t: d=t/2.","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17b82457-4186-44c1-bb6f-48777445a7b1', 'NC17.M2.A-CED.3', 1, 'choice', 'Write a linear system', 'A fruit stand sells apples for 2 dollars each and pears for 3 dollars each. Jin buys 12 pieces of fruit for 29 dollars. Let $a$ be the number of apples and $p$ the number of pears. Which system models this?', '["$a + p = 29$ and $2a + 3p = 12$","$a + p = 12$ and $3a + 2p = 29$","$a + p = 12$ and $2a + 3p = 29$","$a - p = 12$ and $2a + 3p = 29$"]', '$a + p = 12$ and $2a + 3p = 29$', NULL, 'The number of fruits gives $a + p = 12$. The cost gives $2a + 3p = 29$. The other options swap the totals, swap the prices or subtract.', 'checked', '{"lint":[],"solve":{"answer":"$a + p = 12$ and $2a + 3p = 29$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count: a+p=12. Cost: 2a+3p=29.","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c352b92-fcf0-4a42-8159-d53d3d33fa77', 'NC17.M2.A-CED.3', 1, 'choice', 'Write an inverse variation system', 'In the model $y = \frac{k}{x}$ with $k > 0$, what happens to $y$ when $x$ is doubled?', '["It is cut in half.","It is doubled.","It stays the same.","It goes down by 2."]', 'It is cut in half.', NULL, 'If $x$ becomes $2x$, then $y = \frac{k}{2x}$, which is half of $\frac{k}{x}$. So $y$ is cut in half.', 'checked', '{"lint":[],"solve":{"answer":"It is cut in half.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k/(2x)=(1/2)(k/x): halved.","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ea35aad-3a00-45f5-a8f9-c2575b25578b', 'NC17.M2.A-CED.3', 2, 'choice', 'Write a linear-quadratic system', 'A ball is thrown so that its height $h$ in meters after $t$ seconds is $h = -t^2 + 8t$. A drone climbs steadily from the ground and is 8 meters high after 4 seconds. Which system can be used to find when they are at the same height?', '["$h = -t^2 + 8t$ and $h = 4t$","$h = -t^2 + 8t$ and $h = 8t$","$h = -t^2 + 8t$ and $h = t + 8$","$h = -t^2 + 8t$ and $h = 2t$"]', '$h = -t^2 + 8t$ and $h = 2t$', NULL, 'The drone climbs 8 meters in 4 seconds, which is 2 meters per second, so its height is $h = 2t$. The ball is $h = -t^2 + 8t$.', 'checked', '{"lint":[],"solve":{"answer":"$h = -t^2 + 8t$ and $h = 2t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drone from 0, steady, 8 m at 4 s: slope 2, h=2t.","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0747d3a6-2bfb-4078-9a86-475255f4f960', 'NC17.M2.A-CED.3', 2, 'numeric', 'Solve an inverse variation model', 'Friends share a bill of 120 dollars equally. Let $f$ be the number of friends and $p$ the dollars each pays, so $fp = 120$. The dollars each pays is 2 less than the number of friends. How many friends are there?', '[]', '12', NULL, 'Since $p = f - 2$, we get $f(f - 2) = 120$, so $f^2 - 2f - 120 = 0$ and $(f - 12)(f + 10) = 0$. The number of friends is positive, so $f = 12$ and each pays 10 dollars.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p=f-2, f(f-2)=120, f^2-2f-120=0, (f-12)(f+10)=0, f=12 (each pays 10).","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40393f1d-5f40-4c96-b40d-d1147841657a', 'NC17.M2.A-CED.3', 2, 'choice', 'Write an inverse variation system', 'Which situation is modeled by the system $xy = 24$ and $y = x + 2$?', '["Two numbers have a sum of 24, and one is 2 more than the other.","Two numbers have a product of 24, and one is 2 more than the other.","Two numbers have a product of 24, and one is 2 times the other.","Two numbers have a product of 2, and one is 24 more than the other."]', 'Two numbers have a product of 24, and one is 2 more than the other.', NULL, '$xy = 24$ says the product is 24, and $y = x + 2$ says $y$ is 2 more than $x$.', 'checked', '{"lint":[],"solve":{"answer":"Two numbers have a product of 24, and one is 2 more than the other.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"xy=24 is product 24; y=x+2 is 2 more.","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('028456f4-21e2-4a98-a523-153e783dcd41', 'NC17.M2.A-CED.3', 3, 'numeric', 'Solve a square root system', 'Two drones fly so that their heights after $t$ seconds are $h = 4\sqrt{t}$ meters and $h = t$ meters. After takeoff ($t > 0$), at what time are they at the same height?', '[]', '16', '4^2', 'Set $4\sqrt{t} = t$. Divide by $\sqrt{t}$ (which is not 0): $4 = \sqrt{t}$, so $t = 16$. Check: $4 \cdot 4 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 sqrt t=t, 16t=t^2, t=16 (t>0). Check 4*4=16.","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3519123f-3387-4ed6-92c0-41c2e2e0b48c', 'NC17.M2.A-CED.3', 3, 'numeric', 'Solve a linear system from a story', 'Three apples and 2 oranges cost 8.50 dollars. One apple and 4 oranges cost 9.50 dollars. How many dollars does one orange cost?', '[]', '2', '(3*9.5-8.5)/(12-2)', 'Let $a$ and $o$ be the prices: $3a + 2o = 8.5$ and $a + 4o = 9.5$. Multiply the second by 3: $3a + 12o = 28.5$. Subtract the first: $10o = 20$, so $o = 2$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3a+2o=8.50, a+4o=9.50: a=9.50-4o, 28.50-12o+2o=8.50, o=2 (apple 1.50).","run_id":"claude-code","at":"2026-10-24T03:12:28.745Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05598aca-c1ab-4087-98c5-2dabf07becf9', 'NC17.M2.A-REI.1', 1, 'choice', 'Name the property that justifies a step', 'Maya solves $x^2 + 7 = 32$. Her first step is $x^2 = 25$. Which property of equality justifies this step?', '["Addition property: add 7 to both sides.","Division property: divide both sides by 7.","Subtraction property: subtract 7 from both sides.","Multiplication property: multiply both sides by 7."]', 'Subtraction property: subtract 7 from both sides.', NULL, 'Since $x^2 + 7 = 32$, taking away 7 from both sides keeps the equation balanced and leaves $x^2 = 32 - 7 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"Subtraction property: subtract 7 from both sides.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From x^2+7=32 to x^2=25, 7 was subtracted from both sides: subtraction property.","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51f04830-185f-447f-af34-77514c9b37e3', 'NC17.M2.A-REI.1', 1, 'numeric', 'Square root property', 'What is the positive solution of $3x^2 = 75$?', '[]', '5', '75/15', 'Divide both sides by 3 to get $x^2 = 25$. By the square root property, $x = 5$ or $x = -5$. The positive solution is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2=25, x=5 or -5; positive is 5.","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33877985-bd45-4ee4-8d97-5f926d4a0c38', 'NC17.M2.A-REI.1', 1, 'numeric', 'Inverse variation equations', 'The variable $y$ varies inversely with $x$, so $xy = k$ for a constant $k$. When $x = 3$, $y = 12$. What is $k$?', '[]', '36', '12*3', 'Multiply: $k = xy = 3 \cdot 12 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k=xy=3*12=36.","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bc59051-8901-4905-bf53-c034772210c3', 'NC17.M2.A-REI.1', 2, 'choice', 'Complete the square', 'To solve $x^2 + 6x = 7$ by completing the square, Lena adds $9$ to both sides. Why $9$?', '["Because $6 + 3 = 9$, which makes the left side the perfect square $(x + 9)^2$.","Because $7 + 2 = 9$, which makes the right side a perfect square.","Because $6 \\cdot 3 = 18$ and half of $18$ is $9$, which makes the left side $(x + 9)^2$.","Because $\\left(\\frac{6}{2}\\right)^2 = 9$, which makes the left side the perfect square $(x + 3)^2$."]', 'Because $\left(\frac{6}{2}\right)^2 = 9$, which makes the left side the perfect square $(x + 3)^2$.', NULL, 'Half the coefficient of $x$ is $3$, and $3^2 = 9$. Adding $9$ to both sides keeps the equation balanced and gives $x^2 + 6x + 9 = (x + 3)^2 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"Because $\\left(\\frac{6}{2}\\right)^2 = 9$, which makes the left side the perfect square $(x + 3)^2$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half of 6 is 3, squared 9; x^2+6x+9=(x+3)^2.","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35622ec1-e4e5-4196-bdd1-d763d56b84ed', 'NC17.M2.A-REI.1', 2, 'numeric', 'Square root property', 'Solve $2(x - 1)^2 = 18$. What is the larger of the two solutions?', '[]', '4', '1+18/6', 'Divide by 2: $(x - 1)^2 = 9$. Square root property: $x - 1 = \pm 3$. So $x = 4$ or $x = -2$. The larger is $4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-1)^2=9, x-1=+-3, x=4 or -2; larger 4.","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43a20b3c-6439-493d-a817-280746b52747', 'NC17.M2.A-REI.1', 2, 'choice', 'Find the error in a solution', 'Rob solves $x^2 - 4x = 12$ by writing $x(x - 4) = 12$, so $x = 12$ or $x - 4 = 12$. What is his error?', '["He should have divided both sides by $x$ before factoring, to get $x - 4 = 12$.","The zero product property only applies when the product equals $0$, not $12$.","He factored $x^2 - 4x$ wrongly, because $x^2 - 4x$ cannot be factored.","He should have set the product equal to $1$ instead of $12$."]', 'The zero product property only applies when the product equals $0$, not $12$.', NULL, 'A product equal to $12$ does not force a factor to be $12$. Move everything to one side first: $x^2 - 4x - 12 = 0$, so $(x - 6)(x + 2) = 0$ and $x = 6$ or $x = -2$.', 'checked', '{"lint":[],"solve":{"answer":"The zero product property only applies when the product equals $0$, not $12$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zero product property needs product = 0; x(x-4)=12 does not give x=12 or x-4=12. (Correct: x^2-4x-12=0, x=6 or -2.)","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0afdf493-0dcf-4d69-acdc-bf79a327591f', 'NC17.M2.A-REI.1', 3, 'choice', 'Name the property that justifies a step', 'Ben solves $3(x - 2)^2 = 27$. Step 1 gives $(x - 2)^2 = 9$. Step 2 gives $x - 2 = \pm 3$. Step 3 gives $x = 5$ or $x = -1$. Which list names the properties used in Steps 1, 2 and 3?', '["Subtraction property of equality, square root property, addition property of equality.","Division property of equality, zero product property, subtraction property of equality.","Division property of equality, square root property, addition property of equality.","Multiplication property of equality, square root property, addition property of equality."]', 'Division property of equality, square root property, addition property of equality.', NULL, 'Step 1 divides both sides by 3. Step 2 takes square roots of both sides, keeping both signs. Step 3 adds 2 to both sides.', 'checked', '{"lint":[],"solve":{"answer":"Division property of equality, square root property, addition property of equality.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Step1 divide by 3 (division property); Step2 square root property; Step3 add 2 (addition property): x=5 or -1.","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2370c05a-40e2-431e-abcc-305da7576887', 'NC17.M2.A-REI.1', 3, 'numeric', 'Quadratic formula', 'Using the quadratic formula on $2x^2 - 7x + 3 = 0$ gives $x = \frac{7 \pm 5}{4}$. What is the larger solution?', '[]', '3', '(7+5)/4', 'Here $b^2 - 4ac = 49 - 24 = 25$, so $x = \frac{7 \pm 5}{4}$. That gives $\frac{12}{4} = 3$ or $\frac{2}{4} = \frac{1}{2}$. The larger is $3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Discriminant 49-24=25; (7+5)/4=3, (7-5)/4=1/2; larger 3.","run_id":"claude-code","at":"2026-10-24T03:15:22.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15df66dc-cc51-482b-bee3-0d9dff0c7d27', 'NC17.M2.A-REI.2', 1, 'choice', 'Solve a square root equation', 'Solve $\sqrt{x + 3} = 5$.', '["$x = 28$","$x = 2$","$x = 22$","$x = 8$"]', '$x = 22$', NULL, 'Square both sides: $x + 3 = 25$. Subtract 3: $x = 22$. Check: $\sqrt{22 + 3} = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 22$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+3=25, x=22; check √25=5.","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('141f3338-3d05-4a02-aae8-fb279406e313', 'NC17.M2.A-REI.2', 1, 'choice', 'Solve a radical equation with the variable outside the root', 'Which statement about the equation $\sqrt{x} = -5$ is true?', '["The solution is $x = 25$, because $(-5)^2 = 25$","It has no solution, because a square root is never negative","The solution is $x = -25$, because the root is negative","It has two solutions, $x = 5$ and $x = -5$"]', 'It has no solution, because a square root is never negative', NULL, 'The symbol $\sqrt{x}$ means the nonnegative square root, so it cannot equal $-5$. Squaring gives $x = 25$, but then $\sqrt{25} = 5$, not $-5$. So $x = 25$ does not work and there is no solution.', 'checked', '{"lint":[],"solve":{"answer":"It has no solution, because a square root is never negative","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Principal square root is never negative: no solution.","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('199a913f-4a83-40cc-8a36-9c01542aa707', 'NC17.M2.A-REI.2', 1, 'numeric', 'Square root equations in context', 'The side length $s$ of a square is $s = \sqrt{A}$, where $A$ is its area in square centimeters. A square has side length 9 centimeters. What is its area, in square centimeters?', '[]', '81', '9^2', 'Square both sides of $9 = \sqrt{A}$: $A = 81$. Check: $\sqrt{81} = 9$.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9=√A, A=81.","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48c4642a-e6b2-417c-b18b-3dc634648734', 'NC17.M2.A-REI.2', 2, 'numeric', 'Solve a square root equation', 'Solve $3\sqrt{x} - 4 = 8$.', '[]', '16', '((8+4)/3)^2', 'Add 4: $3\sqrt{x} = 12$. Divide by 3: $\sqrt{x} = 4$. Square both sides: $x = 16$. Check: $3 \cdot 4 - 4 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3√x=12, √x=4, x=16.","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
