INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d4130ea-e30f-44bb-a1ad-aa95dceafd5c', 'NC17.M2.A-REI.2', 2, 'choice', 'Inverse variation equations in context', 'Six workers can paint a fence in 10 hours. The time varies inversely with the number of workers, and all work at the same rate. How many hours would 15 workers take?', '["$25$","$1$","$16$","$4$"]', '$4$', '4', 'Six workers for 10 hours is $6 \cdot 10 = 60$ worker-hours. With 15 workers, $15 \cdot t = 60$, so $t = 4$ hours.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k=60 worker-hours, 60/15=4.","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5de33d3e-c297-4bfc-a05c-40b95893df13', 'NC17.M2.A-REI.2', 2, 'choice', 'Inverse variation equations in context', 'The pressure of a gas in a closed container varies inversely with its volume when the temperature stays the same. If the volume is cut to one-third of what it was, what happens to the pressure?', '["It becomes one-third as large","It becomes 3 times as large","It becomes 9 times as large","It stays the same"]', 'It becomes 3 times as large', NULL, 'With $P = \frac{k}{V}$, replacing $V$ by $\frac{V}{3}$ gives $P = \frac{k}{V/3} = 3 \cdot \frac{k}{V}$. The pressure becomes 3 times as large.', 'checked', '{"lint":[],"solve":{"answer":"It becomes 3 times as large","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P=k/V; V/3 gives 3P.","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19a503cb-f165-4b36-bbf4-aca42925c02d', 'NC17.M2.A-REI.2', 3, 'numeric', 'Solve a square root equation', 'Solve $\sqrt{2x + 3} = \sqrt{x + 9}$.', '[]', '6', '9-3', 'Square both sides: $2x + 3 = x + 9$. Subtract $x$ and 3: $x = 6$. Check: both sides equal $\sqrt{15}$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+3=x+9, x=6; check √15=√15.","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14c536b7-257e-4730-957c-162d4127b0e2', 'NC17.M2.A-REI.2', 3, 'numeric', 'Inverse variation equations in context', 'A rectangle has an area of 12 square centimeters, so its length is $l = \frac{12}{w}$, where $w$ is its width in centimeters. The length is 1 centimeter more than the width, so $\frac{12}{w} = w + 1$. What is the width, in centimeters?', '[]', '3', '3', 'Multiply both sides by $w$: $12 = w^2 + w$, so $w^2 + w - 12 = 0$ and $(w + 4)(w - 3) = 0$. A width cannot be negative, so $w = -4$ is rejected. The width is 3 cm. Check: $\frac{12}{3} = 4 = 3 + 1$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w^2+w-12=0, (w+4)(w-3)=0, w=3 (positive).","run_id":"claude-code","at":"2026-10-24T03:17:06.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e09062b-4a17-4241-b50c-c8c0bca45531', 'NC17.M2.A-REI.4', 1, 'numeric', 'Read a, b and c in standard form', 'In the equation $2x^2 - 7x + 3 = 0$, what is $b$?', '[]', '-7', '-7', 'In $ax^2 + bx + c = 0$, $b$ is the number in front of $x$, with its sign. Here $b = -7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b is the coefficient of x: -7.","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1805bbfc-0fc1-482f-819c-db3404559aee', 'NC17.M2.A-REI.4', 1, 'choice', 'Type of solutions from the discriminant', 'The discriminant of a quadratic equation is 0. How many real solutions does the equation have?', '["Exactly one real solution","Exactly two real solutions","No real solutions","Infinitely many real solutions"]', 'Exactly one real solution', NULL, 'The formula has $\pm \sqrt{0}$, and $+0$ and $-0$ give the same number. So there is exactly one real solution.', 'checked', '{"lint":[],"solve":{"answer":"Exactly one real solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Discriminant 0 gives one (repeated) real solution.","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
