VALUES ('1c9874c5-cb76-4622-8d48-1059bbea4e78', 'NC17.M2.A-REI.4', 1, 'numeric', 'The imaginary unit', 'The imaginary unit $i$ satisfies $i^2 = ?$. Find the ?', '[]', '-1', '-1', 'The imaginary unit is defined so that $i^2 = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"i^2=-1.","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
