INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aa1e8bc-b802-4fa0-bb3d-285cc7847aa2', 'NC17.M2.A-REI.4', 2, 'numeric', 'Solve with the quadratic formula (real solutions)', 'Use the quadratic formula to solve $2x^2 - 5x - 3 = 0$. What is the larger solution?', '[]', '3', '(5+7)/4', 'Here $a = 2$, $b = -5$, $c = -3$. The discriminant is $25 + 24 = 49$. So $x = \frac{5 \pm 7}{4}$, which is 3 or $-\frac{1}{2}$. The larger is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5±sqrt(25+24))/4=(5±7)/4: 3 or -1/2. Larger 3.","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
