INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d6ae6cb-b380-4aa5-8ec0-51bc15e30468', 'NC17.M2.A-REI.4', 2, 'choice', 'Solve with complex solutions a ± bi', 'Simplify $\frac{-3 \pm \sqrt{-16}}{2}$ to the form $a \pm bi$.', '["$-3 \\pm 4i$","$-\\frac{3}{2} \\pm 4i$","$-\\frac{3}{2} \\pm 2i$","$\\frac{3}{2} \\pm 2i$"]', '$-\frac{3}{2} \pm 2i$', NULL, '$\sqrt{-16} = 4i$. Dividing both parts by 2: $\frac{-3}{2} \pm \frac{4i}{2} = -\frac{3}{2} \pm 2i$.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{3}{2} \\pm 2i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(-16)=4i; (-3±4i)/2 = -3/2 ± 2i.","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e67492c-deca-4524-a13a-71f6fb4a2f79', 'NC17.M2.A-REI.4', 2, 'numeric', 'Quadratic word problems', 'A ball''s height in feet after $t$ seconds is $-16t^2 + 48t + 64$. It lands when the height is 0. After how many seconds does it land?', '[]', '4', '(-48-80)/(-32)', 'Solve $-16t^2 + 48t + 64 = 0$. The discriminant is $2304 + 4096 = 6400$, with square root 80. So $t = \frac{-48 \pm 80}{-32}$, which is $-1$ or 4. Time cannot be negative, so it lands after 4 seconds.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-16(t^2-3t-4)=0, (t-4)(t+1)=0; t=4 (t=-1 rejected).","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fd85114-27c9-417b-bdc2-4c8b092d0e9b', 'NC17.M2.A-REI.4', 3, 'choice', 'Solve with complex solutions a ± bi', 'What are the solutions of $3x^2 + 2x + 1 = 0$?', '["$\\frac{-1 \\pm 2i\\sqrt{2}}{3}$","$\\frac{-2 \\pm 2i\\sqrt{2}}{3}$","$\\frac{-1 \\pm \\sqrt{2}}{3}$","$\\frac{-1 \\pm i\\sqrt{2}}{3}$"]', '$\frac{-1 \pm i\sqrt{2}}{3}$', NULL, 'The discriminant is $4 - 12 = -8$ and $\sqrt{-8} = 2i\sqrt{2}$. So $x = \frac{-2 \pm 2i\sqrt{2}}{6}$. Divide the top and bottom by 2: $\frac{-1 \pm i\sqrt{2}}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{-1 \\pm i\\sqrt{2}}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2±sqrt(4-12))/6=(-2±2i sqrt2)/6=(-1±i sqrt2)/3.","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d08fc83-de0a-44f6-a748-4c9e7c99b712', 'NC17.M2.A-REI.4', 3, 'choice', 'Type of solutions from the discriminant', 'For which value of $k$ does $x^2 + kx + 4 = 0$ have non-real solutions?', '["$k = 4$","$k = 5$","$k = 3$","$k = -6$"]', '$k = 3$', NULL, 'The discriminant is $k^2 - 16$, which is negative only when $k^2 < 16$. Of the values, only $k = 3$ works: $9 - 16 = -7$. The others give $0$, $9$ and $20$.', 'checked', '{"lint":[],"solve":{"answer":"$k = 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need k^2<16: only k=3 (9<16). k=4 gives 0, 5 gives 25, -6 gives 36.","run_id":"claude-code","at":"2026-10-24T08:19:44.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b988d4-90cf-458e-a113-0a88652bafaf', 'NC17.M2.A-REI.7', 1, 'choice', 'Check a point in both equations', 'Which point is a solution of the system $y = x^2$ and $y = x + 2$?', '["$(2, 4)$","$(-2, 4)$","$(1, 3)$","$(3, 5)$"]', '$(2, 4)$', NULL, 'A solution must fit both equations. For $(2, 4)$: $2^2 = 4$ and $2 + 2 = 4$. The point $(-2, 4)$ fits only the parabola, and $(1, 3)$ and $(3, 5)$ fit only the line.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = x + 2 -> x = 2 or -1: (2,4), (-1,1). (2,4) listed. (-2,4): line 0; (1,3): parabola 1; (3,5): parabola 9.","run_id":"claude-code","at":"2026-10-24T08:22:44.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0915d78e-bc1a-46a3-82ac-03e58c9fcee7', 'NC17.M2.A-REI.7', 1, 'numeric', 'Use the graphs of a line and a parabola', 'A parabola opens upward and its lowest point is $(0, 0)$. The horizontal line $y = -2$ is drawn on the same graph. How many points do the parabola and the line share?', '[]', '0', '0', 'The parabola never goes below $y = 0$, so it never reaches the line $y = -2$. They share 0 points.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parabola y >= 0 everywhere; y = -2 is below: 0 points.","run_id":"claude-code","at":"2026-10-24T08:22:44.707Z"}}', 'ai', NULL, NULL)
