INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07530c8c-4ccc-4fab-9f57-6d6ac1796c81', 'NC17.M2.A-REI.11', 1, 'numeric', 'Solve a square root equation with graphs or tables', 'The graphs of $y = \sqrt{x}$ and $y = 3$ cross at one point. What is its x-coordinate?', '[]', '9', '3^2', 'At the crossing, $\sqrt{x} = 3$, so $x = 3^2 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(x)=3 gives x=9.","run_id":"claude-code","at":"2026-10-24T08:26:47.483Z"}}', 'ai', NULL, NULL)
