INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02fb0ad7-d980-44b8-9e33-9749a16828da', 'NC17.M2.A-REI.11', 1, 'numeric', 'Read a solution or value from an intersection point', 'The graphs of $y = f(x)$ and $y = g(x)$ cross at 3 different points. How many solutions does the equation $f(x) = g(x)$ have?', '[]', '3', '3', 'Each intersection point gives one solution (its x-coordinate), so there are 3 solutions.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each crossing gives one x with f(x)=g(x); 3 different points have 3 different x-values (graphs of functions). 3 solutions.","run_id":"claude-code","at":"2026-10-24T08:26:47.483Z"}}', 'ai', NULL, NULL)
