VALUES ('8516d976-1c43-4461-a98d-342c98d246e0', 'NC17.M2.F-IF.2', 1, 'numeric', 'Reflection in function notation', 'Let $F$ be the reflection over the $y$-axis, so $F(x, y) = (-x, y)$. What is the $x$-coordinate of $F(7, 2)$?', '[]', '-7', '-7', '$F(7, 2) = (-7, 2)$, so the $x$-coordinate is $-7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"F(7,2)=(-7,2). x-coordinate -7.","run_id":"claude-code","at":"2026-10-24T08:27:34.176Z"}}', 'ai', NULL, NULL)
