VALUES ('952cd789-b63b-4848-b168-9e7652c6d2fa', 'NC17.M2.F-IF.2', 1, 'choice', 'Rotation in function notation', 'The rule for a rotation of $90^\circ$ counterclockwise about the origin is $R(x, y) = (-y, x)$. What is $R(3, 1)$?', '["$(1, -3)$","$(-3, -1)$","$(1, 3)$","$(-1, 3)$"]', '$(-1, 3)$', NULL, '$R(3, 1) = (-1, 3)$: the new $x$ is $-y = -1$ and the new $y$ is $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"$(-1, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R(3,1)=(-1,3).","run_id":"claude-code","at":"2026-10-24T08:27:34.176Z"}}', 'ai', NULL, NULL)
