VALUES ('28eb9d34-da43-497a-aa4d-64764689a5a4', 'NC17.M2.F-IF.2', 2, 'choice', 'Reflection in function notation', 'Which rule describes the reflection over the $y$-axis?', '["$F(x, y) = (-x, y)$","$F(x, y) = (x, -y)$","$F(x, y) = (-x, -y)$","$F(x, y) = (y, x)$"]', '$F(x, y) = (-x, y)$', NULL, 'Reflecting over the $y$-axis changes the sign of the $x$-coordinate and keeps $y$.', 'checked', '{"lint":[],"solve":{"answer":"$F(x, y) = (-x, y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection over y-axis negates x: (-x,y).","run_id":"claude-code","at":"2026-10-24T08:27:34.176Z"}}', 'ai', NULL, NULL)
