INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61aae64e-b426-4391-a87b-7d408b052a7f', 'NC17.M2.F-IF.2', 2, 'choice', 'Rotation in function notation', 'A rotation of $270^\circ$ counterclockwise about the origin has the rule $R(x, y) = (y, -x)$. What is $R(2, -3)$?', '["$(3, 2)$","$(-2, 3)$","$(3, -2)$","$(-3, -2)$"]', '$(-3, -2)$', NULL, '$R(2, -3) = (y, -x) = (-3, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-3, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R(2,-3)=(y,-x)=(-3,-2).","run_id":"claude-code","at":"2026-10-24T08:27:34.176Z"}}', 'ai', NULL, NULL)
