INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3011fad7-ed6e-4c2e-a9ad-e8da06f2ff6d', 'NC17.M2.F-IF.2', 3, 'numeric', 'Dilation in function notation', 'A triangle has vertices $(0, 0)$, $(6, 0)$ and $(0, 8)$. It is dilated by $D(x, y) = (\frac{1}{2}x, \frac{1}{2}y)$. What is the area of the image triangle?', '[]', '6', '(3*4)/2', 'The image has vertices $(0, 0)$, $(3, 0)$ and $(0, 4)$, so its area is $\frac{1}{2} \cdot 3 \cdot 4 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image vertices (0,0),(3,0),(0,4): area 3*4/2=6. (Original 24, times 1/4.)","run_id":"claude-code","at":"2026-10-24T08:27:34.176Z"}}', 'ai', NULL, NULL)
