INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f7ef689-e00a-456f-9cae-ded99707e856', 'NC17.M2.F-IF.2', 3, 'choice', 'Dilation in function notation', 'A dilation centered at the origin is $D(x, y) = (\frac{1}{3}x, \frac{1}{3}y)$ and $D(P) = (2, -5)$. What is $P$?', '["$(\\frac{2}{3}, -\\frac{5}{3})$","$(-6, 15)$","$(5, -2)$","$(6, -15)$"]', '$(6, -15)$', NULL, 'Each coordinate of $P$ was divided by 3, so multiply each by 3: $P = (6, -15)$.', 'checked', '{"lint":[],"solve":{"answer":"$(6, -15)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P=(3*2, 3*(-5))=(6,-15).","run_id":"claude-code","at":"2026-10-24T08:27:34.176Z"}}', 'ai', NULL, NULL)
