INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1053781b-e056-4555-b81b-9dab89900605', 'NC17.M2.F-IF.4', 1, 'numeric', 'Interpret the range in context', 'A table shows the height of a toy rocket: at 0 seconds, 0 feet; at 1 second, 30 feet; at 2 seconds, 40 feet; at 3 seconds, 30 feet; at 4 seconds, 0 feet. What is the greatest number in the range of the function given by this table?', '[]', '40', '40', 'The range is the set of heights in the table: 0, 30 and 40 feet. The greatest of these is 40.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range values {0, 30, 40}; greatest is 40.","run_id":"claude-code","at":"2026-10-24T08:27:26.536Z"}}', 'ai', NULL, NULL)
