INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0efc927e-72a6-42d4-a71c-26372477704e', 'NC17.M2.F-IF.4', 1, 'choice', 'Use the symmetry of a function', 'A parabola opens upward and its vertex is the point $(3, -2)$. Which line is its axis of symmetry?', '["$x = -2$","$y = 3$","$y = -2$","$x = 3$"]', '$x = 3$', NULL, 'The axis of symmetry of a parabola is the vertical line through its vertex. The vertex has x-coordinate 3, so the line is $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Axis of symmetry is the vertical line through the vertex: x = 3.","run_id":"claude-code","at":"2026-10-24T08:27:26.536Z"}}', 'ai', NULL, NULL)
