INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ce09afa-a937-4dd0-ab95-37953252733c', 'NC17.M2.F-IF.7', 1, 'numeric', 'Vertex and extreme value of a quadratic', 'The graph of $f(x) = (x - 3)^2 + 5$ is a parabola that opens upward. What is the minimum value of $f(x)$?', '[]', '5', '5', 'The function is in vertex form $f(x) = (x - h)^2 + k$ with vertex $(3, 5)$. Because the parabola opens upward, the vertex is its lowest point, so the minimum value is the $y$-value of the vertex, 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex form, opens up, vertex (3,5): minimum is 5.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32edfe7f-e0f9-41cf-9c2e-26d53482aabc', 'NC17.M2.F-IF.7', 1, 'choice', 'Domain and range', 'What is the domain of $f(x) = x^2 + 3$?', '["$x$ can be any number except 0","$x$ must be 0 or greater","$x$ must be 3 or greater","$x$ can be any real number"]', '$x$ can be any real number', NULL, 'You can square any real number and then add 3, so every real number is allowed. The domain is all real numbers. The restriction "$x \ge 0$" belongs to a square root, and "except 0" to a fraction.', 'checked', '{"lint":[],"solve":{"answer":"$x$ can be any real number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Polynomial: defined for all reals.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('118d7fc1-42c1-4c23-8b9d-e44be4ebdf43', 'NC17.M2.F-IF.7', 1, 'choice', 'Intervals where a function increases or decreases', 'On which interval is $f(x) = (x - 2)^2 + 1$ decreasing?', '["$x < 2$","$x > 2$","$x < 1$","$x > 1$"]', '$x < 2$', NULL, 'The parabola opens upward with its vertex at $(2, 1)$. To the left of the vertex the graph goes down, so $f$ is decreasing for $x < 2$ and increasing for $x > 2$.', 'checked', '{"lint":[],"solve":{"answer":"$x < 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opens up, vertex x=2: decreasing left of vertex, x<2.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8670ad19-5067-4bec-a5a5-01344db3bf63', 'NC17.M2.F-IF.7', 2, 'choice', 'Intercepts of a graph', 'What are the $x$-intercepts of $f(x) = x^2 - 9$?', '["$0$ and $3$","$-9$ and $9$","$-3$ and $3$","$0$ and $9$"]', '$-3$ and $3$', NULL, 'Set $f(x) = 0$: $x^2 - 9 = 0$, so $x^2 = 9$ and $x = 3$ or $x = -3$. The value $-9$ is the $y$-intercept, not an $x$-intercept.', 'checked', '{"lint":[],"solve":{"answer":"$-3$ and $3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2=9 so x=-3, 3.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61241a58-6a2f-4896-b614-50bb7a50c3ab', 'NC17.M2.F-IF.7', 2, 'choice', 'Square root function features', 'What is the range of $f(x) = \sqrt{x} - 3$?', '["$y \\ge 3$","$y \\ge -3$","$y \\le -3$","$x \\ge 0$"]', '$y \ge -3$', NULL, '$\sqrt{x}$ is 0 or greater, so $\sqrt{x} - 3$ is $-3$ or greater: $y \ge -3$. The condition $x \ge 0$ is the domain, not the range.', 'checked', '{"lint":[],"solve":{"answer":"$y \\ge -3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(x)>=0, so sqrt(x)-3>=-3.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a55df80-6916-4d81-8980-ada85d3ae6c8', 'NC17.M2.F-IF.7', 2, 'choice', 'Inverse variation function features', 'Which statement about the graph of $y = \frac{8}{x}$ is true?', '["It has no $x$-intercept and no $y$-intercept","It has a $y$-intercept at $(0, 8)$","It has an $x$-intercept at $(8, 0)$","It crosses both axes at the single point $(0, 0)$"]', 'It has no $x$-intercept and no $y$-intercept', NULL, '$x = 0$ is not allowed, so the graph never touches the $y$-axis. The fraction $\frac{8}{x}$ is never 0, so the graph never touches the $x$-axis. It has no intercepts.', 'checked', '{"lint":[],"solve":{"answer":"It has no $x$-intercept and no $y$-intercept","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0 not in domain; 8/x never 0. No intercepts.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
