INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a0691b6-9dd7-4544-93ae-c760f0fe568b', 'NC17.M2.F-IF.7', 3, 'choice', 'Axis of symmetry of a quadratic', 'A parabola passes through the points $(1, 6)$ and $(7, 6)$. Which line must be its axis of symmetry?', '["$x = 6$","$x = 8$","$x = 4$","$x = 3$"]', '$x = 4$', NULL, 'Two points at the same height are the same distance from the axis, which is halfway between their $x$-values: $(1 + 7) \div 2 = 4$. The line is $x = 4$. The number 6 is a $y$-value.', 'checked', '{"lint":[],"solve":{"answer":"$x = 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal y-values, axis at midpoint (1+7)/2=4.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35df0c0c-630c-44d3-8dc5-cc4e731aa8c2', 'NC17.M2.F-IF.7', 3, 'numeric', 'Square root function features', 'At what $x$-value does the graph of $f(x) = \sqrt{x + 4} - 3$ cross the $x$-axis?', '[]', '5', '3^2-4', 'Set $f(x) = 0$: $\sqrt{x + 4} = 3$. Squaring both sides gives $x + 4 = 9$, so $x = 5$. Check: $\sqrt{9} - 3 = 0$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(x+4)=3, x+4=9, x=5.","run_id":"claude-code","at":"2026-10-24T08:32:47.768Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a5aea4a-18f9-4b5d-9501-b8f4a7c1a6f4', 'NC17.M2.F-IF.8', 1, 'numeric', 'extreme value', 'The quadratic function $f(x) = (x - 2)^2 + 7$ has a minimum value. What is it?', '[]', '7', '7', 'A square is never negative, so $(x - 2)^2$ is smallest (0) when $x = 2$. The minimum value is then $0 + 7 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-2)^2 >= 0, minimum 7 at x = 2.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
