INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44e26132-4bf3-45ff-9faf-d9d806a16087', 'NC17.M2.F-IF.8', 1, 'numeric', 'zeros from vertex form', 'The function $f(x) = (x - 3)^2 - 16$ has two zeros. What is the greater zero?', '[]', '7', '3+4', 'Set $(x - 3)^2 - 16 = 0$, so $(x - 3)^2 = 16$ and $x - 3 = 4$ or $x - 3 = -4$. The zeros are $x = 7$ and $x = -1$, so the greater is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2 = 16, x = 3 +/- 4: -1 and 7. Greater 7.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38135ea8-e844-490f-b56e-fc5855300582', 'NC17.M2.F-IF.8', 1, 'numeric', 'zeros from vertex form', 'What is the smaller zero of $f(x) = (x - 1)^2 - 25$?', '[]', '-4', '1-5', 'Set $(x - 1)^2 = 25$, so $x - 1 = 5$ or $x - 1 = -5$. The zeros are $x = 6$ and $x = -4$, so the smaller is $-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-1)^2 = 25, x = 1 +/- 5: -4 and 6. Smaller -4.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
