INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fe2e6ec-5ce2-4505-af9a-37cae7476df8', 'NC17.M2.F-IF.8', 2, 'numeric', 'solve by completing the square', 'Solve $x^2 + 6x - 7 = 0$ by completing the square. What is the greater solution?', '[]', '1', '-3+4', 'Write $x^2 + 6x = 7$ and add 9 to both sides: $(x + 3)^2 = 16$. Then $x + 3 = 4$ or $x + 3 = -4$, so $x = 1$ or $x = -7$. The greater solution is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 + 6x + 9 = 16, x + 3 = +/-4, x = 1 or -7. Greater 1.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bfff735-259b-4e87-a0cb-e0f7bbfc7ff9', 'NC17.M2.F-IF.8', 2, 'numeric', 'extreme value or zeros in context', 'A ball''s height in meters after $t$ seconds is $h(t) = -(t - 3)^2 + 49$, for $t \ge 0$. After how many seconds does the ball hit the ground, where $h(t) = 0$?', '[]', '10', '3+7', 'Set $-(t - 3)^2 + 49 = 0$, so $(t - 3)^2 = 49$ and $t - 3 = 7$ or $t - 3 = -7$. Then $t = 10$ or $t = -4$. Time cannot be negative, so the ball lands after 10 seconds.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(t-3)^2 = 49, t = 3 +/- 7 = 10 or -4; t >= 0 gives 10.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2962d85c-2c55-4698-86f9-a5ebf9ba02ce', 'NC17.M2.F-IF.8', 2, 'numeric', 'extreme value or zeros in context', 'A rectangular pen is $w$ meters wide and has area $A(w) = -w^2 + 20w$ square meters. What width, in meters, gives the greatest area?', '[]', '10', '20/2', 'Complete the square: $-w^2 + 20w = -(w^2 - 20w) = -(w - 10)^2 + 100$. The area is greatest when $w = 10$, and the greatest area is 100 square meters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-(w^2 - 20w) = -(w-10)^2 + 100; max at w = 10.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f531982-815e-4399-a0b5-015b1a30fa5d', 'NC17.M2.F-IF.8', 3, 'numeric', 'extreme value', 'What is the maximum value of $f(x) = -x^2 + 6x - 5$?', '[]', '4', '-9+9-5+9', 'Factor out $-1$: $-(x^2 - 6x) - 5$. Complete the square: $-(x - 3)^2 + 9 - 5 = -(x - 3)^2 + 4$. The maximum value is 4, at $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-(x^2 - 6x) - 5 = -(x-3)^2 + 9 - 5 = -(x-3)^2 + 4; max 4.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10f0eb64-0726-47a1-84f4-af68bcffd1f0', 'NC17.M2.F-IF.8', 3, 'numeric', 'extreme value or zeros in context', 'A ball is thrown so that its height in meters after $t$ seconds is $h(t) = -5t^2 + 20t + 1$. What is its greatest height, in meters?', '[]', '21', '1+5*4', 'Factor out $-5$: $-5(t^2 - 4t) + 1$. Add and subtract 4 inside: $-5(t - 2)^2 + 20 + 1 = -5(t - 2)^2 + 21$. The greatest height is 21 meters, at $t = 2$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5(t^2 - 4t) + 1 = -5(t-2)^2 + 20 + 1; max 21.","run_id":"claude-code","at":"2026-10-24T08:29:24.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08fc03b9-bbcb-47d6-a602-638c6799f53e', 'NC17.M2.F-IF.9', 1, 'choice', 'Compare y-intercepts and starting values', 'Function $f$ is given by $f(x)=4x+7$. Function $g$ is linear and passes through $(0,10)$ and $(2,16)$. Which function has the greater y-intercept?', '["$f$, because its rate of change 4 is greater than 3","$f$, because the number 7 is greater than 3","Neither, because the y-intercepts are equal","$g$, with y-intercept 10 compared with 7 for $f$"]', '$g$, with y-intercept 10 compared with 7 for $f$', NULL, 'The y-intercept of $f$ is 7. The line $g$ passes through $(0,10)$, so its y-intercept is 10. Since $10>7$, $g$ has the greater y-intercept.', 'checked', '{"lint":[],"solve":{"answer":"$g$, with y-intercept 10 compared with 7 for $f$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g slope (16-10)/2=3, intercept 10; f intercept 7. g greater.","run_id":"claude-code","at":"2026-10-28T18:48:28.475Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ae598f0-1c31-4624-868d-a721ca148081', 'NC17.M2.F-IF.9', 1, 'numeric', 'Compare zeros of quadratic functions', 'Function $f(x)=(x-2)(x-6)$. The graph of function $g$ crosses the x-axis at $x=1$ and $x=4$. How much greater is the largest zero of $f$ than the largest zero of $g$?', '[]', '2', '6-4', 'The zeros of $f$ are 2 and 6, so its largest zero is 6. The largest zero of $g$ is 4. The difference is $6-4=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros of f: 2 and 6; largest 6. Largest zero of g: 4. 6-4=2.","run_id":"claude-code","at":"2026-10-28T18:48:28.508Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a1f9aa2-91b2-4946-81d6-664abe27ac9e', 'NC17.M2.F-IF.9', 1, 'choice', 'Compare maximum or minimum values of quadratic functions', 'Parabola A is the graph of $y=-(x-2)^2+7$. Parabola B opens downward and its highest point is $(1,5)$. Which parabola has the greater maximum value?', '["A, with maximum value 7 compared with 5 for B","B, with maximum value 5 compared with 2 for A","B, because its highest point has x-value 1 and A has 2","Neither, because both maximum values are equal"]', 'A, with maximum value 7 compared with 5 for B', NULL, 'The vertex of A is $(2,7)$ and it opens downward, so its maximum is 7. The maximum of B is 5. Since $7>5$, A has the greater maximum.', 'checked', '{"lint":[],"solve":{"answer":"A, with maximum value 7 compared with 5 for B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: vertex (2,7), opens down, max 7. B max 5. A greater: 7 vs 5.","run_id":"claude-code","at":"2026-10-28T18:48:28.643Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135a5315-70cb-4e1d-9942-db3de2077e04', 'NC17.M2.F-IF.9', 2, 'choice', 'Compare maximum or minimum values of quadratic functions', 'Function $f$ is given by $f(x)=(x-3)^2+2$. Function $g$ is quadratic with the table $x=0,1,2,3,4,5,6$ and $g(x)=7,2,-1,-2,-1,2,7$. Which function has the smaller minimum value?', '["$g$, with minimum $-2$ compared with 2 for $f$","$f$, with minimum 2 compared with $-2$ for $g$","$f$, with minimum 3 compared with $-2$ for $g$","$g$, with minimum 3 compared with 2 for $f$"]', '$g$, with minimum $-2$ compared with 2 for $f$', NULL, 'The vertex of $f$ is $(3,2)$, so its minimum is 2. In the table, the values are symmetric around $x=3$ and the lowest is $-2$, so the minimum of $g$ is $-2$. Since $-2<2$, $g$ has the smaller minimum.', 'checked', '{"lint":[],"solve":{"answer":"$g$, with minimum $-2$ compared with 2 for $f$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f min = 2 at x=3; g min = -2 at x=3. g is smaller.","run_id":"claude-code","at":"2026-10-28T18:48:27.945Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06424deb-5f1d-4a24-9c41-45190a405866', 'NC17.M2.F-IF.9', 2, 'numeric', 'Compare rates of change of linear functions', 'Car A has constant speed, and its distance is 45 miles after 1 hour and 90 miles after 2 hours, starting from 0 miles. The distance of Car B after $t$ hours is $d=50t$ miles. How many miles per hour faster is Car B than Car A?', '[]', '5', '50-(90-45)/(2-1)', 'Car A travels $90-45=45$ miles each hour, so its speed is 45 miles per hour. Car B''s speed is 50 miles per hour. Car B is $50-45=5$ miles per hour faster.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Car A: 45 mph; Car B: 50 mph. 50-45=5.","run_id":"claude-code","at":"2026-10-28T18:48:28.661Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e541e5b-2bd1-4b58-a8fc-184760b09616', 'NC17.M2.F-IF.9', 2, 'numeric', 'Compare maximum values from an equation and a table', 'Function $f$ is given by $f(x)=-x^2+4x+1$. Function $g$ is quadratic, with the table $x=0,1,2,3,4$ and $g(x)=2,5,6,5,2$. How much greater is the maximum value of $g$ than the maximum value of $f$?', '[]', '1', '6-5', 'The vertex of $f$ is at $x=2$, where $f(2)=-4+8+1=5$, so its maximum is 5. In the table, $g$ is highest at $x=2$ with value 6. So the maximum of $g$ is 6 - 5 = 1 greater.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f vertex at x = 2: f(2) = -4+8+1 = 5. g symmetric about x = 2, max g(2) = 6. 6 - 5 = 1.","run_id":"claude-code","at":"2026-10-28T19:12:25.155Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32076c1f-66cc-4354-8bea-c84674b3105a', 'NC17.M2.F-IF.9', 3, 'numeric', 'Compare inverse variation functions', 'Function $f$ has the table $(2,15)$, $(3,10)$, $(5,6)$ and $y$ varies inversely with $x$. For function $g$, $y$ varies inversely with $x$ and $y=6$ when $x=7$. How much greater is $g(6)$ than $f(6)$?', '[]', '2', '42/6-30/6', 'For $f$ the constant is $2 \cdot 15=30$, so $f(6)=\frac{30}{6}=5$. For $g$ the constant is $7 \cdot 6=42$, so $g(6)=\frac{42}{6}=7$. The difference is $7-5=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f: xy = 30 (2*15, 3*10, 5*6), f(6) = 5. g: k = 42, g(6) = 7. 7 - 5 = 2.","run_id":"claude-code","at":"2026-10-28T18:48:27.959Z"}}', 'ai', NULL, NULL)
