INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b71e343-3343-4ab8-a99e-a206d9749f98', 'NC17.M2.F-IF.9', 3, 'numeric', 'Compare inverse variation functions', 'A job takes $w$ workers $d$ days, where $wd=60$ for crew F. For crew G, the number of days is $d=\frac{90}{w}$. With 6 workers, how many more days does crew G need than crew F?', '[]', '5', '90/6-60/6', 'Crew F: $d=\frac{60}{6}=10$ days. Crew G: $d=\frac{90}{6}=15$ days. Crew G needs $15-10=5$ more days.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"F: d = 60/6 = 10. G: d = 90/6 = 15. 15 - 10 = 5.","run_id":"claude-code","at":"2026-10-28T18:48:27.962Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22edea17-ad08-42da-946e-eb2166b7161d', 'NC17.M2.F-BF.1', 1, 'choice', 'Quadratic function from its zeros', 'A quadratic function has a leading coefficient of 1, and its graph crosses the x-axis at $x = 3$ and $x = -1$. Which is the function?', '["$f(x) = (x + 3)(x - 1)$","$f(x) = (x - 3)(x + 1)$","$f(x) = (x - 3)(x - 1)$","$f(x) = (x + 3)(x + 1)$"]', '$f(x) = (x - 3)(x + 1)$', NULL, 'A zero at $x = 3$ comes from the factor $(x - 3)$, and a zero at $x = -1$ comes from $(x + 1)$. With leading coefficient 1, $f(x) = (x - 3)(x + 1)$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = (x - 3)(x + 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros 3 and -1 give factors (x - 3)(x + 1).","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34c667b9-618d-4cdb-a9a6-f3c72b62be88', 'NC17.M2.F-BF.1', 1, 'numeric', 'Constant of an inverse variation', 'The value of $y$ varies inversely with $x$, so $y = \frac{k}{x}$. When $x = 4$, $y = 6$. What is the constant $k$?', '[]', '24', '4*6', 'In $y = \frac{k}{x}$, multiplying both sides by $x$ gives $k = xy = 4 \times 6 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = xy = 4*6 = 24.","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20bccf41-5ac8-4dec-990b-7bacc398a548', 'NC17.M2.F-BF.1', 1, 'numeric', 'Use an inverse variation function', 'The value of $y$ varies inversely with $x$, and the constant of variation is 36. What is $y$ when $x = 9$?', '[]', '4', '36/9', 'The function is $y = \frac{36}{x}$. When $x = 9$, $y = \frac{36}{9} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 36/9 = 4.","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
