INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e93e7af-004b-4b68-8e00-0b72f5e36675', 'NC17.M2.F-BF.1', 2, 'numeric', 'Quadratic function from its zeros and another point', 'The quadratic function $f(x) = a(x - 1)(x - 3)$ has a graph that passes through the point $(0, 6)$. What is the value of $a$?', '[]', '2', '6/3', 'Put in $x = 0$ and $f(0) = 6$: $a(0 - 1)(0 - 3) = 3a = 6$, so $a = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = a(-1)(-3) = 3a = 6, a = 2.","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2541ec23-9375-484a-8edb-7c0ce29c7305', 'NC17.M2.F-BF.1', 2, 'choice', 'Quadratic function from its zeros and another point', 'A parabola crosses the x-axis at $x = -1$ and $x = 5$ and passes through the point $(2, 9)$. Which is its function?', '["$f(x) = (x + 1)(x - 5)$","$f(x) = -(x - 1)(x + 5)$","$f(x) = -(x + 1)(x - 5)$","$f(x) = 9(x + 1)(x - 5)$"]', '$f(x) = -(x + 1)(x - 5)$', NULL, 'Start with $f(x) = a(x + 1)(x - 5)$. At $x = 2$: $a(3)(-3) = -9a = 9$, so $a = -1$ and $f(x) = -(x + 1)(x - 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = -(x + 1)(x - 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f = a(x + 1)(x - 5); f(2) = a(3)(-3) = -9a = 9, a = -1. So -(x + 1)(x - 5).","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ec04b99-f5fc-4ec5-ace7-d6181a09062c', 'NC17.M2.F-BF.1', 2, 'numeric', 'Quadratic function from a description', 'A rectangular garden has width $w$ meters, and its length is 5 meters more than twice its width. Write the area $A$ as a function of $w$, then find the area in square meters when $w = 4$.', '[]', '52', '4*(2*4+5)', 'The length is $2w + 5$, so $A = w(2w + 5)$. When $w = 4$: $A = 4(8 + 5) = 4 \times 13 = 52$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = w(2w + 5); w = 4: 4*(8 + 5) = 52.","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('047fd32c-49e1-40cb-9498-5b5fd94d7f27', 'NC17.M2.F-BF.1', 3, 'choice', 'Quadratic function from its zeros and another point', 'A parabola has x-intercepts at $x = 1$ and $x = 5$, and its highest point is $(3, 8)$. Which is its function?', '["$f(x) = 2(x - 1)(x - 5)$","$f(x) = -2(x - 1)(x - 5)$","$f(x) = -8(x - 1)(x - 5)$","$f(x) = -2(x + 1)(x + 5)$"]', '$f(x) = -2(x - 1)(x - 5)$', NULL, 'Start with $f(x) = a(x - 1)(x - 5)$. At the point $(3, 8)$: $a(2)(-2) = -4a = 8$, so $a = -2$. A highest point also means the parabola opens downward, so $a$ is negative.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = -2(x - 1)(x - 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f = a(x - 1)(x - 5); f(3) = a(2)(-2) = -4a = 8, a = -2.","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00710e1c-369e-46a2-a0d5-a87c8a6189f2', 'NC17.M2.F-BF.1', 3, 'choice', 'Recognize inverse variation', 'In an inverse variation $y = \frac{k}{x}$, what happens to $y$ when $x$ is multiplied by 4?', '["$y$ is multiplied by 4","$y$ is increased by 4","$y$ is decreased by 4","$y$ is divided by 4"]', '$y$ is divided by 4', NULL, 'If $x$ becomes $4x$, the new value is $\frac{k}{4x} = \frac{1}{4} \cdot \frac{k}{x}$. So $y$ is divided by 4.', 'checked', '{"lint":[],"solve":{"answer":"$y$ is divided by 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k/(4x) = (k/x)/4, so y is divided by 4.","run_id":"claude-code","at":"2026-10-24T08:35:51.873Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
