VALUES ('207074eb-9fb3-4e44-adb2-00755ce35e67', 'NC17.M2.F-BF.3', 1, 'numeric', 'Horizontal shift: f(x + k)', 'A table for $f$ shows $f(2) = 6$, $f(3) = 9$ and $f(4) = 12$. Let $g(x) = f(x + 1)$. What is $g(2)$?', '[]', '9', '9', '$g(2) = f(2 + 1) = f(3) = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(2) = f(3) = 9.","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
