VALUES ('20e61de6-fd9f-4caf-bca9-79597f42b7fc', 'NC17.M2.F-BF.3', 1, 'numeric', 'Stretch, compression or reflection: k times f(x)', 'Let $f(x) = x + 3$ and $g(x) = 3f(x)$. What is $g(2)$?', '[]', '15', '3*(2+3)', '$f(2) = 5$, so $g(2) = 3 \times 5 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(2) = 3 f(2) = 3(5) = 15.","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
