INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c9f3ace-28ee-47ad-a240-657d9b9b54a9', 'NC17.M2.F-BF.3', 1, 'choice', 'Effect of a transformation on a table of values', 'A table for $f$ has outputs 2, 4, 6, 8 at $x = 1, 2, 3, 4$. A table for $g(x) = f(x) + 3$ uses the same $x$-values. What are the outputs of $g$?', '["$6, 12, 18, 24$","$5, 7, 9, 11$","$-1, 1, 3, 5$","$2, 4, 6, 8$"]', '$5, 7, 9, 11$', NULL, 'Add 3 to every output of $f$: $2 + 3 = 5$, $4 + 3 = 7$, $6 + 3 = 9$, $8 + 3 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"$5, 7, 9, 11$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 3 to each: 5,7,9,11.","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
