INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('751f0656-75a7-47f8-81c7-3edd16ccf88a', 'NC17.M2.F-BF.3', 2, 'numeric', 'Horizontal shift: f(x + k)', 'Let $f(x) = x^2$ and $g(x) = f(x - 3)$. What is the $x$-coordinate of the vertex of the graph of $g$?', '[]', '3', '3', 'The graph of $f$ has its vertex at $(0, 0)$. Replacing $x$ with $x - 3$ moves the graph right 3 units, so the vertex of $g$ is $(3, 0)$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(x) = (x-3)^2, vertex (3,0).","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
