VALUES ('53c79fc2-c6d4-41af-acf0-8bca6ba03f44', 'NC17.M2.F-BF.3', 2, 'numeric', 'Stretch, compression or reflection: k times f(x)', 'Let $f(x) = \sqrt{x}$ and $g(x) = -2f(x)$. What is $g(9)$?', '[]', '-6', '-2*3', '$f(9) = 3$, so $g(9) = -2 \times 3 = -6$.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(9) = -2(3) = -6.","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
