INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85c531fb-e8db-464d-9ccd-9d4c764547f9', 'NC17.M2.F-BF.3', 2, 'choice', 'Effect of a transformation on a table of values', 'A table for $f(x) = \sqrt{x}$ has $x$: 0, 1, 4, 9 and $f(x)$: 0, 1, 2, 3. Which table is for $g(x) = f(x - 1)$?', '["$x$: $-1$, 0, 3, 8 and $g(x)$: 0, 1, 2, 3","$x$: 0, 1, 4, 9 and $g(x)$: $-1$, 0, 1, 2","$x$: 0, 1, 4, 9 and $g(x)$: 1, 2, 3, 4","$x$: 1, 2, 5, 10 and $g(x)$: 0, 1, 2, 3"]', '$x$: 1, 2, 5, 10 and $g(x)$: 0, 1, 2, 3', NULL, 'The graph moves right 1 unit, so every $x$-value goes up by 1 and the outputs stay the same: $g(1) = f(0) = 0$, $g(2) = f(1) = 1$, $g(5) = f(4) = 2$, $g(10) = f(9) = 3$.', 'checked', '{"lint":[],"solve":{"answer":"$x$: 1, 2, 5, 10 and $g(x)$: 0, 1, 2, 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(x)=sqrt(x-1): x=1,2,5,10 give 0,1,2,3.","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d44a3de-7d65-48ad-b04b-ebc9270ce049', 'NC17.M2.F-BF.3', 3, 'choice', 'Horizontal shift: f(x + k)', 'Let $f(x) = 3x - 1$ and $g(x) = f(x + 2)$. What is the $y$-intercept of the graph of $g$?', '["$1$","$-1$","$5$","$-7$"]', '$5$', '3*2-1', '$g(0) = f(0 + 2) = f(2) = 3(2) - 1 = 5$. Equivalently $g(x) = 3(x + 2) - 1 = 3x + 5$.', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(x) = 3(x+2) - 1 = 3x + 5, y-intercept 5.","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
