INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('049b3aaa-97a5-44e0-b226-bcb3259e05e0', 'NC17.M2.F-BF.3', 3, 'choice', 'Effect of a transformation on key features of a graph', 'Let $f(x) = x^2$. Which change leaves the vertex of the graph at $(0, 0)$?', '["adding 3 to $f(x)$","multiplying $f(x)$ by 3","replacing $x$ with $x - 3$","replacing $x$ with $x + 3$"]', 'multiplying $f(x)$ by 3', NULL, 'Multiplying by 3 stretches the graph away from the $x$-axis but $0 \times 3 = 0$, so the vertex stays at the origin. Adding 3 moves it up, and the other two move it right or left.', 'checked', '{"lint":[],"solve":{"answer":"multiplying $f(x)$ by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x^2 has vertex (0,0); the others move it to (0,3), (3,0), (-3,0).","run_id":"claude-code","at":"2026-10-24T08:36:05.597Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3beaa808-7483-46a0-8c40-6e8094fe2771', 'NC17.M2.G-CO.2', 1, 'numeric', 'Dilate a point about the origin', 'The point $(3, -2)$ is dilated about the origin with scale factor 2. What is the $x$-coordinate of the image?', '[]', '6', '3*2', 'A dilation about the origin with scale factor $k$ sends $(x, y)$ to $(kx, ky)$. So $(3, -2)$ becomes $(6, -4)$ and the $x$-coordinate is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*3 = 6.","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
