INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0da6f5c4-d103-4fdd-b0ae-1351d80f2d86', 'NC17.M2.G-CO.2', 1, 'numeric', 'Rigid motions give congruent figures, dilations similar ones', 'Segment $AB$ is 7 centimeters long. It is reflected across a line to form segment $A''B''$. How long is $A''B''$, in centimeters?', '[]', '7', '7', 'A reflection is a rigid motion, so it keeps lengths. $A''B''$ is also 7 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflections preserve length: 7.","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
