INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('183322a3-be4d-4ee9-9252-2fbb5d26405c', 'NC17.M2.G-CO.2', 1, 'numeric', 'Scale factor and lengths', 'A dilation takes a segment 5 units long to a segment 15 units long. What is the scale factor?', '[]', '3', '15/5', 'The scale factor is the new length divided by the old length: $15 \div 5 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/5 = 3.","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
