INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e9843fa-158c-4490-b757-d0a28c2232fb', 'NC17.M2.G-CO.2', 2, 'choice', 'Tell rigid motions from transformations that change size', 'Triangle $ABC$ has sides of length 3, 4 and 5. A single transformation produces triangle $A''B''C''$ with sides of length 6, 8 and 10. Which transformation was used?', '["a reflection across a line","a rotation of $90^\\circ$ about a point","a dilation with scale factor 2","a translation of 3 units"]', 'a dilation with scale factor 2', NULL, 'Reflections, rotations and translations keep lengths. Here every length doubled, which is a dilation with scale factor 2.', 'checked', '{"lint":[],"solve":{"answer":"a dilation with scale factor 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every side doubled: dilation scale 2.","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27384323-3cbd-46e6-9584-cc19ee075b25', 'NC17.M2.G-CO.2', 2, 'choice', 'Rigid motions give congruent figures, dilations similar ones', 'Triangle $ABC$ is dilated with scale factor 3 to form triangle $A''B''C''$. Which statement is true?', '["The triangles are congruent but not similar.","The triangles are similar but not congruent.","The triangles are both congruent and similar.","The triangles are neither congruent nor similar."]', 'The triangles are similar but not congruent.', NULL, 'A dilation keeps the shape (angles are equal and sides are in proportion), so the triangles are similar. Sides are 3 times as long, so the sizes differ and they are not congruent.', 'checked', '{"lint":[],"solve":{"answer":"The triangles are similar but not congruent.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale 3 changes size, keeps shape: similar not congruent.","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b8ec32-4505-4c86-bfa4-5c0504732d18', 'NC17.M2.G-CO.2', 2, 'numeric', 'Dilation and perimeter or area', 'A triangle with a perimeter of 18 centimeters is dilated with scale factor $\frac{1}{3}$. What is the perimeter of the image, in centimeters?', '[]', '6', '18/3', 'Every side is multiplied by $\frac{1}{3}$, so the perimeter is too: $18 \times \frac{1}{3} = 6$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/3 = 6.","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
