INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13bac6dc-ac22-4238-b8ef-f67235aa0be7', 'NC17.M2.G-CO.2', 3, 'numeric', 'Dilate a point about the origin', 'A dilation about the origin sends the point $(-4, 6)$ to $(-10, 15)$. What is its scale factor?', '[]', '2.5', '15/6', 'The scale factor is the image coordinate divided by the original: $\frac{-10}{-4} = 2.5$ and $\frac{15}{6} = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-10/-4 = 2.5, 15/6 = 2.5.","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40e5078e-00f3-4144-b27d-a8b4bb0df154', 'NC17.M2.G-CO.2', 3, 'choice', 'Rigid motions give congruent figures, dilations similar ones', 'Which sequence of transformations takes a figure to one that is similar to it but not congruent to it?', '["a rotation of $90^\\circ$, then a reflection across the $x$-axis","a translation 3 units right, then a rotation of $180^\\circ$","a rotation of $90^\\circ$, then a dilation with scale factor 3","a reflection across the $y$-axis, then a translation 3 units up"]', 'a rotation of $90^\circ$, then a dilation with scale factor 3', NULL, 'Rigid motions keep lengths and angles, so a sequence of them gives a congruent figure. Only the sequence with a dilation of scale factor 3 changes the size.', 'checked', '{"lint":[],"solve":{"answer":"a rotation of $90^\\circ$, then a dilation with scale factor 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only C includes a size change (scale 3).","run_id":"claude-code","at":"2026-10-24T08:36:28.990Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cf7f723-6758-4182-8b8c-344362669547', 'NC17.M2.G-CO.3', 1, 'choice', 'Match a polygon to its line symmetry', 'Which quadrilateral has exactly 2 lines of symmetry?', '["A parallelogram that is not a rectangle or a rhombus","A kite that is not a rhombus","A rectangle that is not a square","An isosceles trapezoid"]', 'A rectangle that is not a square', NULL, 'A rectangle that is not a square can be reflected across the line joining the midpoints of its long sides and the line joining the midpoints of its short sides: exactly 2. A kite and an isosceles trapezoid have 1 line each, and a plain parallelogram has none.', 'checked', '{"lint":[],"solve":{"answer":"A rectangle that is not a square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kite 1, general parallelogram 0, isosceles trapezoid 1, non-square rectangle 2.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04281439-7245-4f27-ba7f-ff79be7ee706', 'NC17.M2.G-CO.3', 1, 'numeric', 'Order of rotational symmetry', 'How many different turns of 0 degrees or more but less than 360 degrees about its center carry an equilateral triangle onto itself?', '[]', '3', '3', 'The turns are 0, 120 and 240 degrees, so there are 3. This is the order of rotational symmetry, equal to the number of sides.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0, 120, 240 degrees: 3.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
