INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('351524b5-13b9-489d-8da3-507054d1c6ac', 'NC17.M2.G-CO.3', 1, 'choice', 'Angle of rotational symmetry', 'A rectangle that is not a square is turned about its center. Which is the smallest positive angle that turns it onto itself?', '["$90^\\circ$","$360^\\circ$","$45^\\circ$","$180^\\circ$"]', '$180^\circ$', NULL, 'Turning a rectangle by $90^\circ$ would put a long side where a short side was, so that does not work. A turn of $180^\circ$ does carry it onto itself.', 'checked', '{"lint":[],"solve":{"answer":"$180^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-square rectangle: 180 degrees.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
