INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35389d10-e6f4-4a65-a20b-e66d90044b19', 'NC17.M2.G-CO.3', 2, 'choice', 'Angle of rotational symmetry', 'Which angle of turn about its center does NOT carry a regular pentagon onto itself?', '["$72^\\circ$","$144^\\circ$","$216^\\circ$","$120^\\circ$"]', '$120^\circ$', NULL, 'A regular pentagon repeats every $360 \div 5 = 72$ degrees, so only multiples of 72 work: 72, 144 and 216 do. 120 is not a multiple of 72.', 'checked', '{"lint":[],"solve":{"answer":"$120^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pentagon turns are multiples of 72: 72, 144, 216, 288. 120 is not.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
