INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('346b0086-7893-4df4-a181-13ccbd68c773', 'NC17.M2.G-CO.3', 2, 'numeric', 'Order of rotational symmetry', 'A rhombus that is not a square is turned about its center. How many different turns greater than 0 degrees and less than 360 degrees carry it onto itself?', '[]', '1', '1', 'Only a turn of 180 degrees works. A turn of 90 degrees would not, because the angles of a non-square rhombus are not all equal.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-square rhombus: only 180 degrees in (0, 360): 1.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
