INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2859ce82-0c24-4b09-b888-5389bd831b4b', 'NC17.M2.G-CO.3', 2, 'choice', 'Match a polygon to its line symmetry', 'Which polygon has a line of symmetry but no turn between 0 and 360 degrees that carries it onto itself?', '["A parallelogram with unequal sides","A rhombus","An isosceles trapezoid","A rectangle"]', 'An isosceles trapezoid', NULL, 'An isosceles trapezoid can be reflected across the line joining the midpoints of its parallel sides, but no turn works. The rhombus and the rectangle have both kinds of symmetry, and a plain parallelogram has only a 180 degree turn.', 'checked', '{"lint":[],"solve":{"answer":"An isosceles trapezoid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Isosceles trapezoid: 1 line, no nontrivial rotation. Rhombus and rectangle have 180; general parallelogram has no line.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
