INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0722d606-9183-4cda-b6e5-e3578a03665f', 'NC17.M2.G-CO.3', 3, 'numeric', 'Line of symmetry as a coordinate line', 'Points $A(-1, 2)$ and $A''(5, 2)$ are reflections of each other across a vertical line of symmetry $x = k$. What is $k$?', '[]', '2', '(-1+5)/2', 'The line of symmetry is the perpendicular bisector of the segment joining the two points. They have the same $y$-coordinate, so the line is vertical through the midpoint: $x = \frac{-1 + 5}{2} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = (-1 + 5)/2 = 2.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
