INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0afa5aa9-a7e8-452a-923f-50945238e927', 'NC17.M2.G-CO.3', 3, 'numeric', 'Count the symmetries that carry a polygon onto itself', 'Count the turns about its center (including the 0 degree turn) and the reflections that carry a regular hexagon onto itself. How many symmetries are there in all?', '[]', '12', '6+6', 'There are 6 turns (0, 60, 120, 180, 240 and 300 degrees) and 6 reflections, one for each line of symmetry: $6 + 6 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 rotations + 6 reflections = 12.","run_id":"claude-code","at":"2026-10-24T08:37:23.341Z"}}', 'ai', NULL, NULL)
