INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fdd62e9-91da-40f4-8a0e-6fb2d9c3e04d', 'NC17.M2.G-CO.4', 1, 'numeric', 'Rigid motions preserve segment length', 'Segment $AB$ is 9 centimeters long. It is slid (translated) 5 centimeters to the right. How long, in centimeters, is the image of segment $AB$?', '[]', '9', '9', 'A translation is a rigid motion, so it keeps lengths. The image is still 9 centimeters long.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A translation is a rigid motion and preserves length, so the image is still 9 cm.","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
