INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1143d163-c66c-4b82-849f-9431c461a7af', 'NC17.M2.G-CO.4', 1, 'numeric', 'Images of circles under rigid motions', 'A circle has center $C$ and a radius of 5 centimeters. It is translated 8 centimeters to the left. What is the diameter, in centimeters, of the image circle?', '[]', '10', '2*5', 'A translation keeps lengths, so the image circle also has a radius of 5 centimeters. Its diameter is $2 \times 5 = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Radius stays 5, so diameter 10.","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
