INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dba21cb-0a9d-4e82-91cd-6b93e26b7631', 'NC17.M2.G-CO.4', 1, 'numeric', 'Rigid motions preserve segment length', 'A segment has endpoints $(1, 2)$ and $(1, 7)$. It is reflected across the y-axis. How long is the image segment?', '[]', '5', '7-2', 'The original segment is vertical, with length $7 - 2 = 5$. A reflection keeps lengths, so the image is also 5 units long.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original length 7-2 = 5; reflection preserves length: 5.","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
