INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4fa0f0dc-9322-4f92-882b-0d2600fb5c5a', 'NC17.M2.G-CO.4', 2, 'choice', 'Coordinates after a translation, reflection or rotation', 'The point $(-2, 5)$ is reflected across the y-axis. What are the coordinates of the image?', '["$(-2, -5)$","$(2, 5)$","$(2, -5)$","$(5, -2)$"]', '$(2, 5)$', NULL, 'Reflecting across the y-axis changes the sign of the x-coordinate and keeps the y-coordinate. So $(-2, 5)$ becomes $(2, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection over y-axis: (x,y)->(-x,y): (2,5).","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
