INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f00665e-0997-4f9b-93ea-0ea6b3eabe64', 'NC17.M2.G-CO.4', 2, 'choice', 'What a rigid motion keeps and what it changes', 'A triangle with an area of 20 square units is reflected across a line. Which statement about the image is true?', '["Its area is 40 square units, because the image is added to the original","Its area is 10 square units, because the line cuts the triangle in half","Its area is 20 square units, because reflections keep lengths and angles","Its area depends on how far the triangle is from the line"]', 'Its area is 20 square units, because reflections keep lengths and angles', NULL, 'A reflection keeps all lengths and angle measures, so the image is the same size and shape as the original, and it has the same area, 20 square units.', 'checked', '{"lint":[],"solve":{"answer":"Its area is 20 square units, because reflections keep lengths and angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection is a rigid motion; the image is congruent, area 20.","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2717f200-3b92-413f-b7fa-125845a50f56', 'NC17.M2.G-CO.4', 2, 'numeric', 'Rigid motions preserve segment length', 'A segment has endpoints $(1, 1)$ and $(4, 5)$. It is translated 2 units right and 3 units down. How long is the image segment?', '[]', '5', '5', 'A translation keeps lengths. The original segment has horizontal change 3 and vertical change 4, so its length is $\sqrt{3^2 + 4^2} = 5$. The image is 5 units long.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length sqrt(3^2+4^2) = 5, unchanged by translation.","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cbc8c94-8572-421a-803c-57f0bdc87cf3', 'NC17.M2.G-CO.4', 3, 'choice', 'Coordinates after a translation, reflection or rotation', 'Triangle $ABC$ has $A(0, 0)$, $B(4, 0)$ and $C(0, 3)$. Its image has $A(0, 0)$, $B(0, 4)$ and $C(-3, 0)$ in the same order. Which motion maps the triangle to its image?', '["A reflection across the y-axis","A reflection across the line $y = x$","A translation of 4 units up","A rotation of $90^\\circ$ counterclockwise about the origin"]', 'A rotation of $90^\circ$ counterclockwise about the origin', NULL, 'A $90^\circ$ counterclockwise rotation about the origin sends $(x, y)$ to $(-y, x)$: $(4, 0)$ goes to $(0, 4)$ and $(0, 3)$ goes to $(-3, 0)$. A reflection across $y = x$ would send $(0, 3)$ to $(3, 0)$, and the other motions do not keep $A$ at the origin.', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $90^\\circ$ counterclockwise about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotation 90 CCW: (x,y)->(-y,x): B(4,0)->(0,4), C(0,3)->(-3,0), A fixed. Matches. Reflection over y=x sends C to (3,0), not (-3,0).","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('111f1f39-cdb5-4ec8-a27f-2b969f42f8ca', 'NC17.M2.G-CO.4', 3, 'choice', 'What a rigid motion keeps and what it changes', 'Triangle $PQR$ has its vertices in counterclockwise order. It is reflected across a line, and $X$, $Y$ and $Z$ are the images of $P$, $Q$ and $R$. In which order do $X$, $Y$ and $Z$ go around the image?', '["Clockwise, because a reflection reverses the orientation","Counterclockwise, because rigid motions keep the order","Counterclockwise, because a reflection turns the figure by $180^\\circ$","It depends on where the line of reflection is"]', 'Clockwise, because a reflection reverses the orientation', NULL, 'A reflection flips the figure over, like a mirror, so the order of the vertices around it reverses. Counterclockwise becomes clockwise, wherever the line is.', 'checked', '{"lint":[],"solve":{"answer":"Clockwise, because a reflection reverses the orientation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A reflection reverses orientation, so the image runs clockwise.","run_id":"claude-code","at":"2026-10-24T08:38:56.992Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ba955df-01f4-4d16-a6a6-732fe81ae3de', 'NC17.M2.G-CO.5', 1, 'choice', 'Image under a reflection', 'The point $(3, 5)$ is reflected in the $x$-axis. What is its image?', '["$(3, -5)$","$(-3, 5)$","$(-3, -5)$","$(5, 3)$"]', '$(3, -5)$', NULL, 'Reflecting in the $x$-axis keeps the $x$-coordinate and changes the sign of the $y$-coordinate: $(3, -5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, -5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect in x-axis: (x, -y) = (3, -5).","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
