INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2766d0a8-241d-4c34-a863-a5aadff4c742', 'NC17.M2.G-CO.5', 1, 'choice', 'Image under a rotation', 'The point $(2, 5)$ is rotated $180^\circ$ about the origin. What is its image?', '["$(2, -5)$","$(-2, 5)$","$(5, 2)$","$(-2, -5)$"]', '$(-2, -5)$', NULL, 'A $180^\circ$ rotation about the origin changes the sign of both coordinates: $(x, y) \to (-x, -y)$. So $(2, 5)$ becomes $(-2, -5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-2, -5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 deg: (-x, -y) = (-2, -5).","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
