INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c1aec9e-cdaa-4d21-9d6d-2e5fab3faf97', 'NC17.M2.G-CO.5', 1, 'choice', 'Name the rigid motion that maps a figure to its image', 'A figure has points $A(2, 3)$ and $B(5, 3)$. After a rigid motion, they are at $A''(6, 2)$ and $B''(9, 2)$. Which rigid motion was it?', '["a translation 4 units right and 1 unit down","a translation 1 unit right and 4 units down","a reflection in the line $x = 4$","a rotation of $90^\\circ$ about the origin"]', 'a translation 4 units right and 1 unit down', NULL, 'Both points moved from $x$ to $x + 4$ and from $y = 3$ to $y = 2$, so each moved 4 units right and 1 unit down. That is a translation.', 'checked', '{"lint":[],"solve":{"answer":"a translation 4 units right and 1 unit down","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both points move (+4, -1): translation 4 right, 1 down. x = 4 reflection would send A to (6,3).","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('155fa3e3-49c7-4c09-94ce-44cd0e1b33b8', 'NC17.M2.G-CO.5', 2, 'choice', 'Name the rigid motion that maps a figure to its image', 'Triangle $PQR$ has vertices $P(1, 2)$, $Q(4, 2)$ and $R(4, 6)$. Its image has vertices $P''(-1, 2)$, $Q''(-4, 2)$ and $R''(-4, 6)$. Which single rigid motion maps $PQR$ onto its image?', '["a reflection in the $x$-axis","a rotation of $180^\\circ$ about the origin","a translation 2 units left","a reflection in the $y$-axis"]', 'a reflection in the $y$-axis', NULL, 'Each $x$-coordinate changes sign and each $y$-coordinate stays the same. That is a reflection in the $y$-axis.', 'checked', '{"lint":[],"solve":{"answer":"a reflection in the $y$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each (x,y) -> (-x,y): reflection in the y-axis.","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('120188ae-85ba-4c8f-ad29-62f714248e13', 'NC17.M2.G-CO.5', 2, 'choice', 'Image or name for a sequence of rigid motions', 'The point $(2, 3)$ is reflected in the $x$-axis, and then the image is translated 4 units to the right. What is the final image?', '["$(6, 3)$","$(-2, -3)$","$(6, -3)$","$(2, -7)$"]', '$(6, -3)$', NULL, 'The reflection gives $(2, -3)$. Translating 4 units right gives $(6, -3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(6, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3) -> (2,-3) -> (6,-3).","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
