INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('009a5541-9d70-4eac-82e8-a0cbdc02dc77', 'NC17.M2.G-CO.5', 2, 'choice', 'Image or name for a sequence of rigid motions', 'A figure is reflected in the $x$-axis, and then its image is reflected in the $y$-axis. Which single rigid motion does the same thing?', '["a rotation of $90^\\circ$ about the origin","a reflection in the line $y = x$","a translation","a rotation of $180^\\circ$ about the origin"]', 'a rotation of $180^\circ$ about the origin', NULL, 'The two reflections change the sign of $y$ and then the sign of $x$: $(x, y) \to (x, -y) \to (-x, -y)$. That is a $180^\circ$ rotation about the origin.', 'checked', '{"lint":[],"solve":{"answer":"a rotation of $180^\\circ$ about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x,y) -> (x,-y) -> (-x,-y): rotation of 180 about the origin.","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
