INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e72c8b2-d384-4244-a477-58f58380885a', 'NC17.M2.G-CO.5', 3, 'numeric', 'Image under a rotation', 'The point $(5, 3)$ is rotated $180^\circ$ about the point $(2, 1)$. What is the $x$-coordinate of its image?', '[]', '-1', '2*2-5', 'A $180^\circ$ rotation about $(2, 1)$ sends a point to the point on the opposite side of $(2, 1)$, the same distance away. The $x$-coordinate is $2 \cdot 2 - 5 = -1$ (and the $y$-coordinate is $2 \cdot 1 - 3 = -1$).', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x'' = 2*2 - 5 = -1 (y'' = 2*1 - 3 = -1).","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2458ad7b-5616-4dcc-87de-e0798b57bb8c', 'NC17.M2.G-CO.5', 3, 'numeric', 'Image or name for a sequence of rigid motions', 'The point $P(1, 4)$ is translated 3 units right and 2 units down. Then the image is rotated $180^\circ$ about the origin. What is the $y$-coordinate of the final image?', '[]', '-2', '-(4-2)', 'The translation gives $(4, 2)$. A $180^\circ$ rotation about the origin changes both signs, giving $(-4, -2)$. The $y$-coordinate is $-2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,4) -> (4,2) -> (-4,-2); y = -2.","run_id":"claude-code","at":"2026-10-24T08:38:17.130Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64260486-2169-4bb0-bf52-cbefd7ee9f1a', 'NC17.M2.G-CO.6', 1, 'choice', 'Recognize rigid motions', 'Which transformation is NOT a rigid motion?', '["A reflection over the $y$-axis, then a rotation of $90^\\circ$","A translation 3 units right, then 2 units up","A rotation of $90^\\circ$ about the origin","A dilation with scale factor 2 about the origin"]', 'A dilation with scale factor 2 about the origin', NULL, 'Rigid motions (translations, reflections and rotations) keep every distance the same. A dilation with scale factor 2 doubles distances, so it is not a rigid motion.', 'checked', '{"lint":[],"solve":{"answer":"A dilation with scale factor 2 about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A dilation with scale factor 2 changes lengths, so it is not rigid. The others are rigid motions or compositions of them.","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55ae0ce3-36cb-48e5-9abc-acaf8f80980f', 'NC17.M2.G-CO.6', 1, 'numeric', 'Apply a rigid motion to coordinates', 'Point $P(3, 5)$ is translated 4 units to the left and 2 units up. What is the $x$-coordinate of the image of $P$?', '[]', '-1', '3-4', 'Moving 4 units left subtracts 4 from the x-coordinate: 3 - 4 = -1.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: 3 - 4 = -1.","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58028529-e572-452c-b8b2-99bffecf5592', 'NC17.M2.G-CO.6', 1, 'numeric', 'Use matching parts of congruent figures', 'A reflection maps triangle $ABC$ onto triangle $DEF$, with $A$ going to $D$, $B$ to $E$ and $C$ to $F$. If angle $B$ measures $48^\circ$, how many degrees does angle $E$ measure?', '[]', '48', '48', 'A rigid motion keeps angle measures the same, and angle E is the image of angle B, so it measures 48 degrees.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle E corresponds to angle B: 48.","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71046908-9de7-4a93-a9cd-96eff32bacde', 'NC17.M2.G-CO.6', 2, 'choice', 'Apply a rigid motion to coordinates', 'Point $B(3, 1)$ is rotated $90^\circ$ counterclockwise about the origin. What are the coordinates of its image?', '["$(-1, 3)$","$(1, -3)$","$(-3, -1)$","$(3, -1)$"]', '$(-1, 3)$', NULL, 'A 90 degree counterclockwise rotation about the origin sends (x, y) to (-y, x). So (3, 1) goes to (-1, 3).', 'checked', '{"lint":[],"solve":{"answer":"$(-1, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 CCW: (x, y) -> (-y, x): (3, 1) -> (-1, 3).","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95ec1f9f-2766-4456-926f-0348d3cf694c', 'NC17.M2.G-CO.6', 2, 'choice', 'Recognize rigid motions', 'Which rule describes a translation?', '["Each point $(x, y)$ moves to $(-x + 1, y - 2)$","Each point $(x, y)$ moves to $(x + 3, y - 2)$","Each point $(x, y)$ moves to $(-y, x + 3)$","Each point $(x, y)$ moves to $(2x, 2y - 1)$"]', 'Each point $(x, y)$ moves to $(x + 3, y - 2)$', NULL, 'A translation adds the same amounts to every x and y. The rule (-x + 1, y - 2) includes a reflection, (-y, x + 3) includes a rotation, and (2x, 2y - 1) includes a dilation.', 'checked', '{"lint":[],"solve":{"answer":"Each point $(x, y)$ moves to $(x + 3, y - 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation adds constants to x and y: (x+3, y-2). Others involve -x, 2x, or swapping.","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0547c09c-a45e-4316-a563-8bf9b3e08a4f', 'NC17.M2.G-CO.6', 2, 'choice', 'Describe the rigid motions that map one figure onto another', 'Quadrilateral $ABCD$ has vertices $A(1, 2)$, $B(3, 2)$, $C(3, 5)$ and $D(1, 5)$. Quadrilateral $EFGH$ has vertices $E(-1, 2)$, $F(-3, 2)$, $G(-3, 5)$ and $H(-1, 5)$. Which rigid motion maps $ABCD$ onto $EFGH$?', '["A translation 2 units to the left","A rotation of $180^\\circ$ about the origin","A reflection over the $x$-axis","A reflection over the $y$-axis"]', 'A reflection over the $y$-axis', NULL, 'Each point keeps its y-coordinate and has the opposite x-coordinate, which is a reflection over the y-axis. A translation 2 units left would move A to (-1, 2) but B to (1, 2), not (-3, 2).', 'checked', '{"lint":[],"solve":{"answer":"A reflection over the $y$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) -> (-x, y): A(1,2)->(-1,2)=E, B(3,2)->(-3,2)=F, C(3,5)->(-3,5)=G, D(1,5)->(-1,5)=H. Rotation 180 gives negative y; translating 2 left gives x-range -1 to 1, not -3 to -1.","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f4e4bcf-b410-49e6-a14e-204fb17e9715', 'NC17.M2.G-CO.6', 3, 'numeric', 'Use matching parts of congruent figures', 'A rotation maps triangle $ABC$ onto triangle $DEF$, with $A$ going to $D$. The measure of angle $A$ is $(3x + 5)^\circ$ and the measure of angle $D$ is $(5x - 15)^\circ$. What is the measure of angle $A$, in degrees?', '[]', '35', '3*(20/2)+5', 'The angles are equal: 3x + 5 = 5x - 15, so 20 = 2x and x = 10. Angle A is 3(10) + 5 = 35 degrees.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 5 = 5x - 15 -> x = 10. Angle A = 35.","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d6a843b-818a-4f82-b477-ef73c33d17e2', 'NC17.M2.G-CO.6', 3, 'numeric', 'Describe the rigid motions that map one figure onto another', 'A triangle is reflected over the $x$-axis, and then every point is moved by the rule that takes $(x, y)$ to $(x + a, y + b)$. The vertex $A(2, 3)$ ends at $(5, -1)$. What is $a + b$?', '[]', '5', '(5-2)+(3-1)', 'The reflection takes A(2, 3) to (2, -3). Then 2 + a = 5 gives a = 3, and -3 + b = -1 gives b = 2. So a + b = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect: (2, -3). Then (2 + a, -3 + b) = (5, -1): a = 3, b = 2. a + b = 5.","run_id":"claude-code","at":"2026-10-24T08:40:09.240Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d06039a-5991-4019-903c-78785c26bb33', 'NC17.M2.G-CO.7', 1, 'numeric', 'Using congruence to find a missing measure', 'In $\triangle ABC \cong \triangle DEF$, side $\overline{AB}$ is 7 cm long. How long, in centimeters, is $\overline{DE}$?', '[]', '7', '7', 'Congruent triangles have congruent corresponding sides. $\overline{AB}$ corresponds to $\overline{DE}$, so $DE = 7$ cm.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB corresponds to DE in ABC~DEF, so DE = 7.","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07624c16-aa26-404d-a957-4870188ad756', 'NC17.M2.G-CO.7', 1, 'numeric', 'Using congruence to find a missing measure', '$\triangle JKL \cong \triangle MNP$ and $m\angle K = 62^\circ$. What is $m\angle N$, in degrees?', '[]', '62', '62', 'K is the second vertex of $\triangle JKL$ and N is the second vertex of $\triangle MNP$, so $\angle K$ and $\angle N$ correspond and have the same measure, $62^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"K corresponds to N, so m<N = 62.","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24a589ef-e93e-4f90-8cbd-273e515d6364', 'NC17.M2.G-CO.7', 1, 'choice', 'Identifying the rigid motion between two triangles', 'A triangle is turned $90^\circ$ around a point and keeps its size and shape. What is this rigid motion called?', '["Rotation","Reflection","Translation","Dilation"]', 'Rotation', NULL, 'Turning a figure about a point is a rotation. A reflection flips it, a translation slides it, and a dilation changes its size.', 'checked', '{"lint":[],"solve":{"answer":"Rotation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Turning about a point is a rotation.","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b6e73b4-b928-4f13-ad1f-cf7a14f94d2a', 'NC17.M2.G-CO.7', 2, 'numeric', 'Using congruent corresponding parts with algebra', '$\triangle ABC \cong \triangle XYZ$, with $AB = 3x + 2$ and $XY = 14$. What is $x$?', '[]', '4', '(14-2)/3', '$\overline{AB}$ and $\overline{XY}$ correspond, so $3x + 2 = 14$. Then $3x = 12$ and $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = XY: 3x+2 = 14, 3x = 12, x = 4.","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('194abb8e-a0e0-4d12-a3eb-372e2ef732d5', 'NC17.M2.G-CO.7', 2, 'numeric', 'Using congruence to find a missing measure', '$\triangle ABC \cong \triangle DEF$, $m\angle A = 35^\circ$ and $m\angle B = 80^\circ$. What is $m\angle F$, in degrees?', '[]', '65', '180-35-80', 'The angles of $\triangle ABC$ add to $180^\circ$, so $m\angle C = 180 - 35 - 80 = 65^\circ$. $\angle F$ corresponds to $\angle C$, so $m\angle F = 65^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m<C = 180-35-80 = 65; F corresponds to C, so 65.","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f21ccf0-86d8-47f4-803e-7a15dab126ef', 'NC17.M2.G-CO.7', 2, 'choice', 'Identifying the rigid motion between two triangles', 'Triangle ABC has vertices A(1, 1), B(4, 1) and C(1, 5). Its image has vertices A''(6, 2), B''(9, 2) and C''(6, 6). Which translation maps the triangle onto its image?', '["5 units right and 1 unit down","1 unit right and 5 units up","5 units right and 1 unit up","6 units right and 2 units up"]', '5 units right and 1 unit up', NULL, 'A moves from (1, 1) to (6, 2): $6 - 1 = 5$ units right and $2 - 1 = 1$ unit up. B and C move the same way.', 'checked', '{"lint":[],"solve":{"answer":"5 units right and 1 unit up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A(1,1)->A''(6,2): +5 in x, +1 in y. Check B(4,1)->(9,2), C(1,5)->(6,6). 5 right, 1 up.","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('061c74c2-2dbf-470a-8f19-de8573b1d343', 'NC17.M2.G-CO.7', 3, 'numeric', 'Using congruent corresponding parts with algebra', '$\triangle ABC \cong \triangle DEF$. $m\angle A = x^\circ$, $m\angle B = 2x^\circ$ and $m\angle F = 3x^\circ$. What is $m\angle E$, in degrees?', '[]', '60', '2*(180/6)', '$\angle F$ corresponds to $\angle C$, so the angles of $\triangle ABC$ are $x$, $2x$ and $3x$. They add to $180$, so $6x = 180$ and $x = 30$. $\angle E$ corresponds to $\angle B$, so $m\angle E = 2(30) = 60^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m<C = m<F = 3x. x+2x+3x = 180, x = 30. m<E = m<B = 2x = 60.","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0605da57-c3bc-4f5f-bc94-864db580b5ae', 'NC17.M2.G-CO.7', 3, 'choice', 'Showing congruence with a sequence of rigid motions', 'Triangle ABC has vertices A(0, 0), B(4, 0) and C(0, 3). Triangle DEF has vertices D(5, 2), E(5, 6) and F(2, 2). Which sequence of rigid motions maps A to D, B to E and C to F?', '["Rotate $90^\\circ$ counterclockwise about the origin, then translate 5 right and 2 up","Rotate $90^\\circ$ clockwise about the origin, then translate 5 right and 2 up","Translate 5 right and 2 up, then rotate $90^\\circ$ counterclockwise about the origin","Reflect across the y-axis, then translate 5 right and 2 up"]', 'Rotate $90^\circ$ counterclockwise about the origin, then translate 5 right and 2 up', NULL, 'Rotating $90^\circ$ counterclockwise about the origin sends (x, y) to (-y, x): A(0, 0), B(0, 4), C(-3, 0). Translating 5 right and 2 up gives (5, 2), (5, 6), (2, 2), which are D, E and F. The other sequences miss at least one vertex.', 'checked', '{"lint":[],"solve":{"answer":"Rotate $90^\\circ$ counterclockwise about the origin, then translate 5 right and 2 up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotate 90 CCW: (x,y)->(-y,x): A(0,0), B(0,4), C(-3,0); translate (5,2): (5,2),(5,6),(2,2) = D,E,F. Translate-then-rotate sends A to (-2,5); CW sends B to (5,-2); reflect y-axis sends B to (1,2).","run_id":"claude-code","at":"2026-10-24T08:42:05.986Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f6038d0-c1c8-4942-85de-1dada9ec221f', 'NC17.M2.G-CO.8', 1, 'numeric', 'Know what each criterion requires', 'Two right triangles are shown to be congruent by HL. Besides the right angles, how many pairs of equal sides are used?', '[]', '2', '2', 'HL means hypotenuse and leg: the two hypotenuses are equal and one pair of legs is equal. That is 2 pairs of equal sides, plus the right angles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HL uses the hypotenuse and one leg: 2 pairs.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f02b8b8-f4af-4f4d-89fe-351acb295a40', 'NC17.M2.G-CO.8', 1, 'numeric', 'Explain congruence criteria with rigid motions', 'A rotation maps triangle $ABC$ onto triangle $DEF$, with $B$ going to $E$ and $C$ going to $F$. If $BC = 9$ cm, what is $EF$, in centimeters?', '[]', '9', '9', 'A rotation is a rigid motion, so it keeps lengths the same. The image of segment $BC$ is segment $EF$, so $EF = 9$ cm.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotations preserve length: EF=BC=9.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a374bb9-8556-472e-b963-784b6cb3a1ee', 'NC17.M2.G-CO.8', 1, 'choice', 'Say which fact completes a criterion', 'In triangles $ABC$ and $DEF$, $AB = DE$ and $BC = EF$. Which additional fact lets you use SAS?', '["$\\angle A = \\angle D$","$\\angle B = \\angle E$","$\\angle C = \\angle F$","$AC = DF$"]', '$\angle B = \angle E$', NULL, 'For SAS the angle must be between the two equal sides. $\angle B$ is between $AB$ and $BC$, and $\angle E$ is between $DE$ and $EF$, so $\angle B = \angle E$ completes SAS. ($AC = DF$ would give SSS instead.)', 'checked', '{"lint":[],"solve":{"answer":"$\\angle B = \\angle E$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle B is between AB and BC; with angle E between DE and EF gives SAS.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5294242b-e314-4590-aef5-11b65d55521b', 'NC17.M2.G-CO.8', 2, 'choice', 'Explain congruence criteria with rigid motions', 'A reflection maps triangle $ABC$ onto triangle $DEF$, with $A$ to $D$, $B$ to $E$ and $C$ to $F$. Which statement must be true?', '["$AB$ is parallel to $DE$ in every case","$DE$ is exactly twice as long as $AB$","$\\angle F$ is exactly twice as big as $\\angle C$","$AB = DE$ and $\\angle C = \\angle F$"]', '$AB = DE$ and $\angle C = \angle F$', NULL, 'A reflection is a rigid motion: it keeps lengths and angle measures. So $AB = DE$ and $\angle C = \angle F$ always hold. The segments need not be parallel, and nothing is doubled.', 'checked', '{"lint":[],"solve":{"answer":"$AB = DE$ and $\\angle C = \\angle F$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection is rigid: preserves lengths and angles, so AB=DE and angle C=angle F.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b486dca-6e4a-4e61-87d9-ce0c59d6f547', 'NC17.M2.G-CO.8', 2, 'numeric', 'Find the value that makes triangles congruent', 'A right triangle has legs 6 cm and 8 cm. A second right triangle has a hypotenuse of 10 cm and one leg of 6 cm. By HL the triangles are congruent. How long is the other leg of the second triangle, in centimeters?', '[]', '8', '8', 'The first triangle has hypotenuse $\sqrt{6^2 + 8^2} = 10$ cm, so the hypotenuses and one leg match. The triangles are congruent, so the second triangle''s other leg is also 8 cm.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First triangle hypotenuse 10, leg 6 matches; other leg sqrt(100-36)=8.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
