INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76ef17d1-151f-4827-a917-7f3c6bf2c990', 'NC17.M2.G-CO.8', 2, 'choice', 'Explain congruence criteria with rigid motions', 'In the rigid-motion argument for SAS, triangle $ABC$ is moved so that $A$ lands on $D$ and $AB$ lies along $DE$. Because $AB = DE$, $B$ lands on $E$. After a reflection if needed, $C$ is on the same side of $DE$ as $F$. Why does $C$ land on $F$?', '["$\\angle C = \\angle F$, so $C$ must be placed at the point $F$","$\\angle A = \\angle D$ puts $AC$ along $DF$, and $AC = DF$","A dilation then moves $C$ onto $F$ once $B$ is on $E$","$BC = EF$, which makes the two triangles similar to each other"]', '$\angle A = \angle D$ puts $AC$ along $DF$, and $AC = DF$', NULL, 'Since $\angle A = \angle D$, ray $AC$ falls along ray $DF$. Since $AC = DF$, point $C$ lands exactly on $F$. All three vertices match, so the triangles are congruent. A dilation is not a rigid motion, and the angle at $C$ is not given in SAS.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle A = \\angle D$ puts $AC$ along $DF$, and $AC = DF$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rigid motion preserves angle A, so ray AC lies on ray DF; AC=DF puts C on F.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('333b0411-d30c-463c-a630-77bc5eda62d8', 'NC17.M2.G-CO.8', 3, 'choice', 'Decide whether the given facts are enough for congruence', 'Segments $AD$ and $BC$ cross at point $E$, with $AE = DE$ and $BE = CE$. Which criterion shows that triangle $ABE$ is congruent to triangle $DCE$?', '["SAS, using the vertical angles at $E$","SSS, since all three sides are given","ASA, using the vertical angles at $E$","HL, since the segments cross at $E$"]', 'SAS, using the vertical angles at $E$', NULL, '$AE = DE$ and $BE = CE$ are two pairs of equal sides, and $\angle AEB = \angle DEC$ because vertical angles are equal. That angle lies between the two sides, so the criterion is SAS. The third sides $AB$ and $DC$ are not given, and no right angle is given.', 'checked', '{"lint":[],"solve":{"answer":"SAS, using the vertical angles at $E$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AE=DE, BE=CE, angle AEB=angle DEC (vertical, included): SAS.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c95e8de-1035-418c-a2b2-e213724e56c1', 'NC17.M2.G-CO.8', 3, 'numeric', 'Find the value that makes triangles congruent', 'Triangle $ABC$ has $\angle A = (3x + 5)^\circ$, $\angle B = 70^\circ$ and $AB = 12$ cm. Triangle $DEF$ has $\angle D = 50^\circ$, $\angle E = 70^\circ$ and $DE = 12$ cm. The triangles are congruent by ASA, with $A$ matching $D$ and $B$ matching $E$. What is $x$?', '[]', '15', '(50-5)/3', 'Matching angles are equal: $3x + 5 = 50$, so $3x = 45$ and $x = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+5=50, x=15.","run_id":"claude-code","at":"2026-10-24T08:43:49.137Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('137f930c-98b2-45e8-99b9-9d9da86beade', 'NC17.M2.G-CO.9', 1, 'numeric', 'Use angles formed by parallel lines and a transversal', 'Two parallel lines are cut by a transversal. One of two alternate interior angles measures $64^\circ$. What is the measure, in degrees, of the other?', '[]', '64', '64', 'When two parallel lines are cut by a transversal, alternate interior angles are congruent. So the other angle is also $64^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Alternate interior angles are congruent with parallel lines: 64.","run_id":"claude-code","at":"2026-10-24T08:42:16.387Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84862152-79b8-401f-b1c3-85bf779aaff0', 'NC17.M2.G-CO.9', 1, 'numeric', 'Use the angle bisector', 'Ray $BD$ bisects angle $ABC$, and angle $ABC$ measures $74^\circ$. What is the measure, in degrees, of angle $ABD$?', '[]', '37', '74/2', 'An angle bisector splits an angle into two equal angles. So angle $ABD$ is $74 / 2 = 37$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ABD = 74/2 = 37.","run_id":"claude-code","at":"2026-10-24T08:42:16.387Z"}}', 'ai', NULL, NULL)
