INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ebd88b6-9145-4bf9-a0f0-6edb88b02590', 'NC17.M2.G-CO.10', 1, 'numeric', 'Midsegment of a triangle', 'In triangle $ABC$, $D$ is the midpoint of $\overline{AB}$ and $E$ is the midpoint of $\overline{AC}$. If $BC = 18$, what is the length of $\overline{DE}$?', '[]', '9', '18/2', 'A midsegment is half as long as the side it is parallel to, so $DE = 18 \div 2 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midsegment DE = BC/2 = 9.","run_id":"claude-code","at":"2026-10-24T08:41:07.752Z"}}', 'ai', NULL, NULL)
