INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18467ef7-74a8-4f98-a380-80d372210e75', 'NC17.M2.G-CO.10', 2, 'choice', 'Base angles of an isosceles triangle', 'An isosceles triangle has two equal sides that meet at an angle of $48^\circ$. What is the measure of each of the other two angles?', '["$132^\\circ$","$66^\\circ$","$48^\\circ$","$114^\\circ$"]', '$66^\circ$', NULL, 'The other two angles are the base angles, and they are equal. They share $180 - 48 = 132$ degrees, so each is $66^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$66^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex angle 48; base angles (180-48)/2 = 66.","run_id":"claude-code","at":"2026-10-24T08:41:07.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19f52480-5a18-4c07-89e9-0ad570c34aa7', 'NC17.M2.G-CO.10', 2, 'choice', 'Reasons in a triangle proof', 'In a proof, triangle $ABC$ has $AB = AC$, and one step states that $\angle B = \angle C$. Which reason justifies this step?', '["Vertical angles are congruent angles.","Alternate interior angles are congruent.","Base angles of an isosceles triangle are congruent.","The angles of a triangle add up to $180^\\circ$."]', 'Base angles of an isosceles triangle are congruent.', NULL, 'The sides $AB$ and $AC$ are equal, so the angles opposite them, $\angle C$ and $\angle B$, are equal. This is the isosceles triangle (base angles) theorem.', 'checked', '{"lint":[],"solve":{"answer":"Base angles of an isosceles triangle are congruent.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Isosceles triangle theorem.","run_id":"claude-code","at":"2026-10-24T08:41:07.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c92e605-3702-4009-a951-26e8c21d99f5', 'NC17.M2.G-CO.10', 2, 'numeric', 'Midsegment of a triangle', 'A triangle has sides of length 10, 14 and 16. A second triangle is formed by joining the midpoints of the three sides of the first. What is the perimeter of the second triangle?', '[]', '20', '(10+14+16)/2', 'Each side of the second triangle is a midsegment, half as long as the side of the first triangle it is parallel to. So its perimeter is half of $10 + 14 + 16 = 40$, which is 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medial triangle perimeter = half of 40 = 20.","run_id":"claude-code","at":"2026-10-24T08:41:07.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4376022c-6daa-4bcf-baa7-bf7759a920c2', 'NC17.M2.G-CO.10', 3, 'choice', 'Base angles of an isosceles triangle', 'Triangle $ABC$ is isosceles with $AB = AC$. The exterior angle at $B$ measures $130^\circ$. What is the measure of $\angle A$?', '["$50^\\circ$","$80^\\circ$","$100^\\circ$","$130^\\circ$"]', '$80^\circ$', NULL, 'The interior angle at $B$ is $180 - 130 = 50$. Since $AB = AC$, $\angle C = \angle B = 50^\circ$. Then $\angle A = 180 - 50 - 50 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"$80^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle B = 180-130 = 50 = angle C; A = 80.","run_id":"claude-code","at":"2026-10-24T08:41:07.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21cd1e4c-3a47-417a-b833-cfef3be97796', 'NC17.M2.G-CO.10', 3, 'numeric', 'Exterior angle of a triangle', 'In triangle $PQR$, the exterior angle at $R$ measures $125^\circ$, and angle $P$ is $10^\circ$ less than twice angle $Q$. What is the measure of angle $Q$, in degrees?', '[]', '45', '(125+10)/3', 'The exterior angle equals $P + Q$. With $P = 2Q - 10$, $(2Q - 10) + Q = 125$, so $3Q = 135$ and $Q = 45$. Then $P = 80$ and $80 + 45 = 125$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P + Q = 125, P = 2Q-10 -> 3Q = 135 -> Q = 45.","run_id":"claude-code","at":"2026-10-24T08:41:07.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3052de23-e433-4c24-9f83-7833802df399', 'NC17.M2.G-SRT.1', 1, 'choice', 'Lengths are multiplied by the scale factor', 'A dilation has scale factor $\frac{1}{2}$. Segment CD is 30 units long. How long is its image C''D'', in units?', '["60","30","29.5","15"]', '15', '30/2', 'Lengths are multiplied by the scale factor: $30 \cdot \frac{1}{2} = 15$. The result is shorter because the scale factor is less than 1.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/2 = 15.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
