INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01838e26-b533-494d-95c9-33aed4e36b30', 'NC17.M2.G-SRT.1', 1, 'choice', 'A dilation keeps a line parallel, or on itself if it passes through the center', 'A dilation with scale factor 2 maps line m to line n. The center of the dilation is not on line m. How are lines m and n related?', '["line n is perpendicular to line m","line n is the same line as line m","line n is parallel to line m, so the two never meet","line n crosses line m at the center"]', 'line n is parallel to line m, so the two never meet', NULL, 'A dilation with a scale factor other than 1 maps a line that does not pass through the center to a different, parallel line.', 'checked', '{"lint":[],"solve":{"answer":"line n is parallel to line m, so the two never meet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line not through center maps to a parallel line; factor 2 so a different line.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c49a06c-61dc-4778-8b2c-2d9735d6c9e0', 'NC17.M2.G-SRT.1', 1, 'numeric', 'Image of a point under a dilation about the origin', 'A dilation centered at the origin with scale factor 3 maps the point $(2, -5)$ to P''. What is the y-coordinate of P''?', '[]', '-15', '-5*3', 'A dilation centered at the origin multiplies both coordinates by the scale factor, so P'' is $(6, -15)$ and its y-coordinate is $-15$.', 'checked', '{"lint":[],"solve":{"answer":"-15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*(-5) = -15.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41e0dcfc-534b-4cc2-a57c-6a9e6162af67', 'NC17.M2.G-SRT.1', 2, 'choice', 'Lengths are multiplied by the scale factor', 'Triangle ABC has sides AB = 6 cm, BC = 8 cm and CA = 10 cm. It is dilated with scale factor 2.5 to make triangle A''B''C''. Which could be the lengths A''B'', B''C'' and C''A'', in centimeters?', '["8.5, 10.5, 12.5","15, 20, 25","12, 16, 20","2.4, 3.2, 4"]', '15, 20, 25', NULL, 'Each side is multiplied by 2.5: $6 \cdot 2.5 = 15$, $8 \cdot 2.5 = 20$ and $10 \cdot 2.5 = 25$. Adding 2.5, multiplying by 2, or dividing by 2.5 gives the other lists.', 'checked', '{"lint":[],"solve":{"answer":"15, 20, 25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,8,10 times 2.5 = 15, 20, 25.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
