INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b7f2617-79d4-41cc-9b63-671fa59e3223', 'NC17.M2.G-SRT.1', 2, 'numeric', 'Distances from the center are multiplied by the scale factor', 'A dilation with center O and scale factor 3 maps A to A''. The point A'' is 21 units from O. How far from O was A, in units?', '[]', '7', '21/3', 'The image is 3 times as far from O as the original, so the original is $21 \div 3 = 7$ units from O.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21/3 = 7.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45446fe2-3610-4332-8b09-59bbdfeac633', 'NC17.M2.G-SRT.1', 2, 'numeric', 'Find the scale factor from corresponding lengths', 'A dilation has center O. A point A is 12 units from O, and its image A'' is 9 units from O. What is the scale factor?', '[]', '3/4', '9/12', 'The scale factor is OA'' divided by OA: $\frac{9}{12} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/12 = 3/4.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07333114-7462-4744-aa68-74a31149db02', 'NC17.M2.G-SRT.1', 3, 'numeric', 'Angle measures are preserved', 'Triangle ABC has $\angle A = 35^\circ$ and $\angle B = 75^\circ$. A dilation with scale factor 4 maps it to triangle A''B''C''. What is the measure of angle C'', in degrees?', '[]', '70', '180-35-75', 'The angles of ABC add to $180^\circ$, so $\angle C = 180 - 35 - 75 = 70^\circ$. The dilation preserves angles, so angle C'' is also $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 180-35-75 = 70, preserved.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29f17b2d-4ce4-4c3e-a395-a93a33f40f6f', 'NC17.M2.G-SRT.1', 3, 'choice', 'Properties a dilation keeps and changes', 'A dilation has center O and scale factor 3. Which statement is NOT true?', '["Every segment in the image is 3 times as long as its original segment","Every point other than O is mapped to a point 3 times as far from O","Every line through O is mapped onto itself","Every angle in the image is 3 times as large as its original angle"]', 'Every angle in the image is 3 times as large as its original angle', NULL, 'Dilations preserve angle measures, so angles are not tripled. The other three statements are properties of a dilation with scale factor 3.', 'checked', '{"lint":[],"solve":{"answer":"Every angle in the image is 3 times as large as its original angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles are preserved, not tripled; the other three are true.","run_id":"claude-code","at":"2026-10-24T08:44:13.005Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('153cc450-4334-4dad-b3d6-ff3bb42fbdae', 'NC17.M2.G-SRT.2', 1, 'choice', 'side lengths of a figure and its dilation image', 'A rectangle is 4 cm by 6 cm. It is dilated by a scale factor of 2. What are the dimensions of the image?', '["8 cm by 12 cm","6 cm by 8 cm","4 cm by 12 cm","16 cm by 24 cm"]', '8 cm by 12 cm', NULL, 'Both dimensions are multiplied by the scale factor 2: $4 \times 2 = 8$ and $6 \times 2 = 12$. The image is 8 cm by 12 cm.', 'checked', '{"lint":[],"solve":{"answer":"8 cm by 12 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*2 = 8, 6*2 = 12.","run_id":"claude-code","at":"2026-10-28T18:48:28.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('018f03c2-8e5a-4b8b-ae30-afa8ef8eabc4', 'NC17.M2.G-SRT.2', 1, 'choice', 'what a dilation changes and what it keeps', 'Triangle $ABC$ is dilated by a scale factor of 3 about the origin. Which statement about the image is true?', '["Each side is 3 times as long, and each angle is 3 times as large","Each side is 3 units longer, and each angle has the same measure","Each side has the same length, and each angle is 3 times as large","Each side is 3 times as long, and each angle has the same measure"]', 'Each side is 3 times as long, and each angle has the same measure', NULL, 'A dilation multiplies every length by the scale factor but keeps every angle measure the same. That is why the image has the same shape as the original.', 'checked', '{"lint":[],"solve":{"answer":"Each side is 3 times as long, and each angle has the same measure","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilation by 3: lengths times 3, angles preserved.","run_id":"claude-code","at":"2026-10-28T18:48:28.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('211714d9-a95c-4774-9de8-509d8ece33f3', 'NC17.M2.G-SRT.2', 1, 'choice', 'what a dilation changes and what it keeps', 'A dilation has a scale factor of $\frac{1}{2}$. How does the image compare with the original figure?', '["It has the same shape but is larger","It has the same size but is turned","It has the same shape but is smaller","It has the same size but is flipped over"]', 'It has the same shape but is smaller', NULL, 'A scale factor between 0 and 1 shrinks the figure. The shape stays the same, so the image is a smaller copy.', 'checked', '{"lint":[],"solve":{"answer":"It has the same shape but is smaller","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 1/2: same shape, half the size.","run_id":"claude-code","at":"2026-10-28T18:48:28.276Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ffff1a7-5da9-432c-b28e-4a2f170bdc44', 'NC17.M2.G-SRT.2', 2, 'numeric', 'similar triangles have proportional sides', 'Triangle $ABC$ is similar to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$ and $C$ matching $F$. Side $AB$ is 6, side $BC$ is 9 and side $DE$ is 10. How long is side $EF$?', '[]', '15', '9*10/6', 'The scale factor from $ABC$ to $DEF$ is $\frac{DE}{AB} = \frac{10}{6} = \frac{5}{3}$. So $EF = 9 \times \frac{5}{3} = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor DE/AB=10/6=5/3. EF=9x5/3=15.","run_id":"claude-code","at":"2026-10-28T18:48:27.932Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('369eca5c-c221-4f5e-a662-8a3e05b24f69', 'NC17.M2.G-SRT.2', 2, 'numeric', 'corresponding angles of similar figures are congruent', 'Triangles $ABC$ and $DEF$ are similar, with angle $A$ matching angle $D$. Angle $A$ measures $(3x + 5)^\circ$ and angle $D$ measures $41^\circ$. What is the value of $x$?', '[]', '12', '(41-5)/3', 'Matching angles of similar triangles are congruent, so $3x + 5 = 41$. Then $3x = 36$ and $x = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles equal: 3x + 5 = 41, 3x = 36, x = 12.","run_id":"claude-code","at":"2026-10-28T18:48:28.185Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e2b4522-572b-4cc0-989b-1e44dbdc8939', 'NC17.M2.G-SRT.2', 2, 'numeric', 'find a scale factor', 'Triangle $DEF$ is a dilation of triangle $ABC$. Triangle $ABC$ has sides of 6, 8 and 10. Triangle $DEF$ has sides of 9, 12 and 15. What is the scale factor from $ABC$ to $DEF$?', '[]', '3/2', '9/6', 'Divide a side of $DEF$ by the matching side of $ABC$: $9 \div 6 = \frac{3}{2}$. The other sides give the same ratio: $12 \div 8 = \frac{3}{2}$ and $15 \div 10 = \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/6 = 12/8 = 15/10 = 1.5.","run_id":"claude-code","at":"2026-10-28T18:48:28.686Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('096b5d57-342c-49ac-b259-3fd9ef607ca0', 'NC17.M2.G-SRT.2', 3, 'numeric', 'similar triangles have proportional sides', 'A triangular flag has sides of 9 inches, 12 inches and 15 inches. A smaller flag is similar to it, and its shortest side is 6 inches. What is the perimeter of the smaller flag, in inches?', '[]', '24', '(9+12+15)*6/9', 'The scale factor is $6 \div 9 = \frac{2}{3}$. The perimeter of the large flag is $9 + 12 + 15 = 36$ inches, so the smaller flag''s perimeter is $36 \times \frac{2}{3} = 24$ inches.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale 6/9=2/3. Original perimeter 36; smaller 36x2/3=24 (sides 6,8,10).","run_id":"claude-code","at":"2026-10-28T18:48:27.935Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3866197d-575b-44bc-ae87-0ac35077619b', 'NC17.M2.G-SRT.2', 3, 'numeric', 'corresponding angles of similar figures are congruent', 'The angles of triangle $ABC$ measure $x^\circ$, $2x^\circ$ and $3x^\circ$. Triangle $DEF$ is the image of triangle $ABC$ after a dilation and a reflection. What is the measure of the smallest angle of triangle $DEF$, in degrees?', '[]', '30', '180/6', 'The angles of $ABC$ add to $180^\circ$: $x + 2x + 3x = 6x = 180$, so $x = 30$. A dilation and a reflection keep angle measures, so the smallest angle of $DEF$ is also $30^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 180, so x = 30. The smallest angle is 30; similarity keeps it.","run_id":"claude-code","at":"2026-10-28T18:48:28.300Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0008a093-f5f7-4ac7-8efb-9759fc6beea5', 'NC17.M2.G-SRT.3', 1, 'numeric', 'Missing side of similar triangles', 'Two triangles are similar by AA. Two sides of the small triangle are 3 and 5. The matching sides of the larger triangle are 6 and $s$. What is $s$?', '[]', '10', '5*6/3', 'The scale factor from the small to the large triangle is 6 / 3 = 2. So s = 5 x 2 = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 6/3 = 2; s = 5×2 = 10.","run_id":"claude-code","at":"2026-10-28T18:47:12.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25c38ec0-b184-4018-94ad-cfdc864fc7c9', 'NC17.M2.G-SRT.3', 1, 'choice', 'State and apply the AA criterion', 'Triangle $PQR$ has angles of $40^\circ$ and $70^\circ$. Triangle $XYZ$ also has angles of $40^\circ$ and $70^\circ$. Are the triangles similar?', '["Yes, because two pairs of angles match","No, because the side lengths are not known","No, because all three angles must be given","Yes, because the triangles are congruent"]', 'Yes, because two pairs of angles match', NULL, 'Two pairs of congruent angles make the triangles similar by AA. The side lengths are not needed, and the third angles are forced to match. The triangles may be different sizes, so they need not be congruent.', 'checked', '{"lint":[],"solve":{"answer":"Yes, because two pairs of angles match","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two pairs of congruent angles -> similar by AA.","run_id":"claude-code","at":"2026-10-28T18:48:27.978Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c4cb861-f028-4fd8-9f72-5948d6ec4d21', 'NC17.M2.G-SRT.3', 1, 'numeric', 'Angle sum and third angles', 'Triangle $ABC$ has angles of $45^\circ$ and $85^\circ$. Triangle $DEF$ has angles of $45^\circ$ and $85^\circ$, so the triangles are similar by AA. What is the measure of the third angle of triangle $DEF$, in degrees?', '[]', '50', '180-45-85', 'The angles of a triangle add up to 180 degrees. 180 - 45 - 85 = 50 degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third angle = 180 - 45 - 85 = 50 degrees.","run_id":"claude-code","at":"2026-10-28T18:48:28.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c1e648d-8e80-4bc4-bbb6-4e1207c83fec', 'NC17.M2.G-SRT.3', 2, 'numeric', 'Scale factor of a dilation', 'A triangle has side lengths 8, 10 and 12 units. It is dilated by a scale factor of $\frac{3}{2}$. How many units long is the longest side of the image?', '[]', '18', '12*3/2', 'The longest side is 12 units. Multiply by the scale factor: 12 x 3/2 = 18 units.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Longest side 12 x 3/2 = 18.","run_id":"claude-code","at":"2026-10-28T18:48:27.869Z"}}', 'ai', NULL, NULL)
