INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b6c89a4-fda3-464c-afa8-9e1fa7ef247a', 'NC17.M2.G-SRT.3', 2, 'numeric', 'Angle sum and third angles', 'Triangles $ABC$ and $DEF$ are similar by AA, with $\angle A \cong \angle D$ and $\angle B \cong \angle E$. Angle $A$ measures $(3x + 5)^\circ$ and angle $D$ measures $50^\circ$. What is $x$?', '[]', '15', '(50-5)/3', 'Matching angles of similar triangles are equal, so 3x + 5 = 50. Then 3x = 45 and x = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles congruent: 3x + 5 = 50, x = 15.","run_id":"claude-code","at":"2026-10-28T18:48:28.027Z"}}', 'ai', NULL, NULL)
