INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02d65165-a991-4417-9c19-31823d694385', 'NC17.M2.G-SRT.3', 2, 'numeric', 'Shadows and indirect measurement', 'At the same time of day, a pole that is 2 meters tall casts a shadow 3 meters long. A tree casts a shadow 12 meters long. The triangles formed are similar by AA. How many meters tall is the tree?', '[]', '8', '2/3*12', 'The height-to-shadow ratio is the same: 2 / 3 = h / 12. So h = 2 x 12 / 3 = 8 meters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = h/12 -> h = 8.","run_id":"claude-code","at":"2026-10-28T18:48:28.064Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d1287c8-9763-4710-a6e8-e7f35145a733', 'NC17.M2.G-SRT.3', 3, 'numeric', 'Parallel line makes similar triangles', 'In triangle $ABC$, point $D$ is on $\overline{AB}$ and point $E$ is on $\overline{AC}$, with $\overline{DE} \parallel \overline{BC}$, so triangle $ADE$ is similar to triangle $ABC$ by AA. $AD = x$, $AB = x + 4$, $DE = 6$ and $BC = 9$. What is $x$?', '[]', '8', '24/3', 'Matching sides are proportional: x / (x + 4) = 6 / 9. Cross-multiply: 9x = 6x + 24, so 3x = 24 and x = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/(x+4)=6/9=2/3: 3x=2x+8, x=8.","run_id":"claude-code","at":"2026-10-28T18:48:28.210Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00b3a5ed-b089-43d5-8a4e-4a2c8a117e2d', 'NC17.M2.G-SRT.3', 3, 'choice', 'State and apply the AA criterion', 'Triangle $ABC$ is isosceles with $AB = AC$ and $\angle A = 40^\circ$. Triangle $DEF$ is isosceles with $DE = DF$ and $\angle E = 70^\circ$. Are the triangles similar?', '["No, because the side lengths are not given","No, because $\\angle A$ is $40^\\circ$ but $\\angle E$ is $70^\\circ$","Yes, because both are isosceles, whatever their angles","Yes, both have angles of $40^\\circ$, $70^\\circ$ and $70^\\circ$"]', 'Yes, both have angles of $40^\circ$, $70^\circ$ and $70^\circ$', NULL, 'In ABC the base angles are (180 - 40) / 2 = 70 degrees each. In DEF, angle F equals angle E = 70 degrees, so angle D = 40 degrees. Both have angles 40, 70 and 70, so they are similar by AA.', 'checked', '{"lint":[],"solve":{"answer":"Yes, both have angles of $40^\\circ$, $70^\\circ$ and $70^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ABC: B=C=70, angles 40,70,70. DEF: E=F=70, D=40. AA similar.","run_id":"claude-code","at":"2026-10-28T18:48:28.410Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1204024b-3cb4-405b-bc24-b963cee32588', 'NC17.M2.G-SRT.4', 1, 'choice', 'Give reasons in a similarity proof', 'In triangle $ABC$, point $D$ is on side $AB$ and point $E$ is on side $AC$, and $\overline{DE} \parallel \overline{BC}$. Why are triangles $ADE$ and $ABC$ similar?', '["They share angle $A$, and sides $AD$ and $AB$ are equal because $DE$ is parallel to $BC$.","They share side $AD$, and angles $D$ and $B$ are equal because $DE$ is parallel to $BC$.","They share angle $A$, and angles $D$ and $E$ are equal because $DE$ is a straight segment.","They share angle $A$, and angles $D$ and $B$ are equal because $DE$ is parallel to $BC$."]', 'They share angle $A$, and angles $D$ and $B$ are equal because $DE$ is parallel to $BC$.', NULL, 'Corresponding angles at $D$ and $B$ are equal because of the parallel lines, and both triangles contain angle $A$. Two pairs of equal angles make the triangles similar by AA.', 'checked', '{"lint":[],"solve":{"answer":"They share angle $A$, and angles $D$ and $B$ are equal because $DE$ is parallel to $BC$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AA: common angle A, and angle ADE = angle ABC as corresponding angles since DE || BC.","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0db1d62a-714f-4350-bc2e-2c410aef13d5', 'NC17.M2.G-SRT.4', 1, 'choice', 'Use the converse of the side-splitter theorem', 'Which statement is the converse of the side-splitter theorem?', '["If a line divides two sides of a triangle proportionally, then it is parallel to the third side.","If a line is parallel to one side of a triangle, then it divides the other two sides proportionally.","If a line divides two sides of a triangle in half, then it is perpendicular to the third side.","If a line divides two sides of a triangle proportionally, then it is equal in length to the third side."]', 'If a line divides two sides of a triangle proportionally, then it is parallel to the third side.', NULL, 'The converse swaps the "if" part and the "then" part of the theorem. The theorem goes from parallel to proportional, so the converse goes from proportional to parallel.', 'checked', '{"lint":[],"solve":{"answer":"If a line divides two sides of a triangle proportionally, then it is parallel to the third side.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Converse swaps hypothesis and conclusion: if a line divides two sides proportionally, it is parallel to the third side.","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('304873be-188f-442a-b5cb-6e7d0441e754', 'NC17.M2.G-SRT.4', 1, 'choice', 'Pythagorean Theorem and the altitude to the hypotenuse', 'A proof of the Pythagorean Theorem with similar triangles starts with right triangle $ABC$, whose right angle is at $C$. What is its key first step?', '["Draw the median from $C$ to the hypotenuse, forming two triangles that are congruent to each other.","Draw a square on each side of the triangle and show that the two smaller squares cover the larger.","Draw the altitude from $C$ to the hypotenuse, forming two triangles similar to the whole triangle.","Draw the angle bisector from $C$, forming two triangles that are similar to the whole triangle."]', 'Draw the altitude from $C$ to the hypotenuse, forming two triangles similar to the whole triangle.', NULL, 'The altitude from the right angle splits the triangle into two smaller right triangles. Each shares an acute angle with the original, so all three triangles are similar, and the proportions from that give $a^2 + b^2 = c^2$.', 'checked', '{"lint":[],"solve":{"answer":"Draw the altitude from $C$ to the hypotenuse, forming two triangles similar to the whole triangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The similarity proof drops the altitude from C to the hypotenuse, producing two triangles each similar to ABC (AA).","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29cd4d8f-51cc-48c7-b4cf-dcc638424faa', 'NC17.M2.G-SRT.4', 2, 'numeric', 'Find a length with the side-splitter theorem', 'In triangle $ABC$, point $D$ is on side $AB$ and point $E$ is on side $AC$, and $\overline{DE} \parallel \overline{BC}$. $AD = 5$, $AB = 15$ and $AE = 4$. Find $AC$.', '[]', '12', '4*15/5', 'Triangles $ADE$ and $ABC$ are similar, so $\frac{AD}{AB} = \frac{AE}{AC}$. Then $\frac{5}{15} = \frac{4}{AC}$ and $AC = \frac{4 \times 15}{5} = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AD/AB = AE/AC: 5/15 = 4/AC, AC = 12.","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('383ba847-3ba2-47f7-86e8-4c11aa01103a', 'NC17.M2.G-SRT.4', 2, 'numeric', 'Find a length with similar triangles', 'A triangular garden has corners $A$, $B$ and $C$. A fence $DE$ joins point $D$ on side $AB$ to point $E$ on side $AC$, parallel to side $BC$. $AD = 12$ meters, $DB = 8$ meters and $DE = 15$ meters. Find $BC$ in meters.', '[]', '25', '15*20/12', 'Triangles $ADE$ and $ABC$ are similar. $AB = 12 + 8 = 20$, so $\frac{AD}{AB} = \frac{DE}{BC}$ gives $\frac{12}{20} = \frac{15}{BC}$ and $BC = \frac{15 \times 20}{12} = 25$ meters.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = 12 + 8 = 20. DE/BC = AD/AB = 12/20, so BC = 15*20/12 = 25.","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ebc4fae-e9bc-49fb-b7bc-360dd972c58d', 'NC17.M2.G-SRT.4', 2, 'choice', 'Use the converse of the side-splitter theorem', 'In triangle $ABC$, point $D$ is on side $AB$ and point $E$ is on side $AC$. A student finds that $\frac{AD}{AB} = \frac{AE}{AC}$. Which conclusion is justified?', '["$DE$ has the same length as $BC$, by the side-splitter theorem for triangles.","Triangle $ADE$ is congruent to triangle $ABC$, by the SSS congruence theorem.","$DE$ is perpendicular to $BC$, by the Pythagorean Theorem.","$DE$ is parallel to $BC$, by the converse of the side-splitter theorem."]', '$DE$ is parallel to $BC$, by the converse of the side-splitter theorem.', NULL, 'If $\frac{AD}{AB} = \frac{AE}{AC}$, then $\frac{AD}{DB} = \frac{AE}{EC}$ too (subtract each side from the whole). The sides are divided proportionally, so by the converse $DE \parallel BC$. Nothing makes the lengths equal.', 'checked', '{"lint":[],"solve":{"answer":"$DE$ is parallel to $BC$, by the converse of the side-splitter theorem.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AD/AB = AE/AC is equivalent to AD/DB = AE/EC, so DE || BC by the converse of the side-splitter theorem.","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29b25843-f1cb-4809-bf41-13d3b346b123', 'NC17.M2.G-SRT.4', 3, 'choice', 'Use the converse of the side-splitter theorem', 'A proof of the converse of the side-splitter theorem assumes $\frac{AD}{DB} = \frac{AE}{EC}$ in triangle $ABC$. It draws through $D$ the line parallel to $BC$, meeting $AC$ at $F$, and uses the side-splitter theorem to show $\frac{AF}{FC} = \frac{AE}{EC}$. What is the next step?', '["Show that $F$ is the midpoint of $AC$, so $DE$ is half as long as $BC$.","Show that $F$ and $E$ are the same point, so $DE$ is parallel to $BC$.","Show that $AD$ equals $AE$, so triangle $ADE$ is isosceles.","Show that angle $A$ is a right angle, so $DE$ is perpendicular to $AB$."]', 'Show that $F$ and $E$ are the same point, so $DE$ is parallel to $BC$.', NULL, 'Only one point on $AC$ divides it in the ratio $\frac{AE}{EC}$, so $F$ and $E$ must be the same point. Then line $DE$ is the line drawn through $D$ parallel to $BC$, which proves $DE \parallel BC$.', 'checked', '{"lint":[],"solve":{"answer":"Show that $F$ and $E$ are the same point, so $DE$ is parallel to $BC$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AF/FC = AE/EC with F and E on AC means they divide AC in the same ratio, so F = E; hence DE is the parallel line DF.","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4910bbfb-548b-4a46-acc8-22b7cb21919a', 'NC17.M2.G-SRT.4', 3, 'numeric', 'Pythagorean Theorem and the altitude to the hypotenuse', 'In right triangle $ABC$ the right angle is at $C$, $AC = 6$, $BC = 8$ and $AB = 10$. The altitude from $C$ meets the hypotenuse at $D$. Find $CD$.', '[]', '24/5', '6*8/10', 'Triangles $ABC$ and $CBD$ share angle $B$ and each has a right angle, so they are similar. Matching sides give $\frac{CD}{AC} = \frac{BC}{AB}$, so $CD = \frac{6 \times 8}{10} = 4.8$.', 'checked', '{"lint":[],"solve":{"answer":"4.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area: AC*BC = AB*CD, 6*8 = 10*CD, CD = 4.8.","run_id":"claude-code","at":"2026-10-24T08:47:34.461Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2092180f-8e87-4376-a3e3-9c383a90df65', 'NC17.M2.G-SRT.6', 1, 'choice', 'Compute a ratio from side lengths', 'A right triangle has a hypotenuse of 13 and legs of 5 and 12. What is the cosine of the angle that has the leg of length 5 next to it?', '["$\\frac{5}{13}$","$\\frac{12}{13}$","$\\frac{5}{12}$","$\\frac{13}{5}$"]', '$\frac{5}{13}$', NULL, 'Cosine = adjacent / hypotenuse. The leg next to the angle is 5, so cosine = 5/13.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{13}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent leg 5, hypotenuse 13: cos = 5/13.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ac2f711-f006-4b40-a557-1a13c1b9d6f5', 'NC17.M2.G-SRT.6', 1, 'choice', 'Name a ratio from the triangle''s sides', 'In a right triangle, for angle B the side opposite is 15, the side next to it is 8 and the hypotenuse is 17. The ratio $\frac{15}{8}$ is which of these?', '["$\\tan B$","$\\sin B$","$\\cos B$","$\\frac{1}{\\tan B}$"]', '$\tan B$', NULL, 'Opposite / adjacent = 15 / 8, which is the tangent of B.', 'checked', '{"lint":[],"solve":{"answer":"$\\tan B$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"opposite/adjacent = tan B.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28a93f1c-3d20-40e2-b2d6-46b49a65b486', 'NC17.M2.G-SRT.6', 1, 'choice', 'Compute a ratio from side lengths', 'A right triangle has sides 7, 24 and 25. What is the cosine of the angle opposite the side of length 24?', '["$\\frac{24}{25}$","$\\frac{7}{25}$","$\\frac{7}{24}$","$\\frac{25}{7}$"]', '$\frac{7}{25}$', NULL, 'The side next to that angle is the other leg, 7. Cosine = adjacent / hypotenuse = 7/25.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{25}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle opposite 24 has adjacent leg 7: cos = 7/25.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
