INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d839383-b9ff-4027-b50a-006870654e8f', 'NC17.M2.G-SRT.6', 2, 'numeric', 'Find a side of a similar triangle', 'Right triangle ABC has right angle at C, AC = 5, BC = 12 and AB = 13. Right triangle DEF is similar to it, with right angle at F and D corresponding to A. If DF = 15, how long is the hypotenuse DE?', '[]', '39', '15*13/5', 'The triangles are similar, so cos D = cos A = 5/13. Then DF / DE = 5/13, so DE = 15 x 13 / 5 = 39.', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AC corresponds to DF: scale 15/5 = 3; DE = 3*13 = 39.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4656a9d8-367d-45c5-8741-727cb0beb14a', 'NC17.M2.G-SRT.6', 2, 'numeric', 'Equal ratios in similar right triangles', 'A right triangle has sides 5, 12 and 13. A second right triangle has sides 10, 24 and 26. What is the sine of the angle opposite the shortest side in the second triangle?', '[]', '5/13', '10/26', 'Sine = 10 / 26 = 5/13, the same value as in the first triangle, because the triangles are similar.', 'checked', '{"lint":[],"solve":{"answer":"5/13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest side 10, hypotenuse 26: sin = 10/26 = 5/13.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c67bdc4-2aba-43fb-9feb-053e363157a5', 'NC17.M2.G-SRT.6', 2, 'numeric', 'Find a side from a given ratio', 'In a right triangle, the tangent of angle A is $\frac{3}{4}$ and the leg opposite angle A is 15. How long is the leg next to angle A?', '[]', '20', '15*4/3', 'Tangent = opposite / adjacent, so 15 / adjacent = 3/4. The adjacent leg is 15 x 4 / 3 = 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/adj = 3/4 gives adj = 20.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0590fcaa-7d72-4c13-9971-1562541f88f2', 'NC17.M2.G-SRT.6', 3, 'numeric', 'Find a side of a similar triangle', 'A student measures a right triangle and finds that the side opposite a certain acute angle is 6 cm when the hypotenuse is 8 cm. A larger right triangle has the same acute angle and a hypotenuse of 20 cm. How long is the side opposite that angle in the larger triangle, in centimeters?', '[]', '15', '6/8*20', 'The triangles are similar, so opposite / hypotenuse is the same: 6 / 8 = 3/4. Then opposite = 3/4 x 20 = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin = 6/8 = 3/4; 20*3/4 = 15.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('138913c6-8357-4dff-84d6-766d884560b8', 'NC17.M2.G-SRT.6', 3, 'choice', 'Compare the ratios', 'For an acute angle A in a right triangle, how do $\tan A$ and $\sin A$ compare?', '["$\\tan A$ is greater, because the adjacent leg is shorter than the hypotenuse","$\\tan A$ is smaller, because the adjacent leg is shorter than the hypotenuse","$\\tan A$ is equal, because both use the opposite leg","$\\tan A$ is greater, because the adjacent leg is longer than the hypotenuse"]', '$\tan A$ is greater, because the adjacent leg is shorter than the hypotenuse', NULL, 'Both ratios have the opposite leg on top. The tan A denominator is the adjacent leg, and the sin A denominator is the hypotenuse, which is longer. A smaller denominator gives the larger ratio.', 'checked', '{"lint":[],"solve":{"answer":"$\\tan A$ is greater, because the adjacent leg is shorter than the hypotenuse","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"tan = opp/adj, sin = opp/hyp; adj < hyp so tan A > sin A.","run_id":"claude-code","at":"2026-10-24T08:44:31.323Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('337e4ac0-34b7-4fd3-b8de-723ef9511679', 'NC17.M2.G-SRT.8', 1, 'choice', 'Angles of elevation and depression', 'A person looks up at the top of a tree. The angle of elevation is the angle between', '["the horizontal and the line of sight up to the top","the tree and the line of sight to the top","the ground and the shadow of the tree","the line of sight and a line straight down"]', 'the horizontal and the line of sight up to the top', NULL, 'An angle of elevation is measured upward from the horizontal to the line of sight.', 'checked', '{"lint":[],"solve":{"answer":"the horizontal and the line of sight up to the top","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle of elevation: between the horizontal and the line of sight upward.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
