INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bcff832-2b45-4047-a5ac-e2177e12dfda', 'NC17.M2.G-SRT.8', 1, 'choice', 'Find a side with the Pythagorean Theorem', 'A 10-foot ladder leans against a wall with its base 6 feet from the wall. Which expression gives the height in feet that the ladder reaches up the wall?', '["$\\sqrt{10^2 + 6^2}$","$10 - 6$","$\\sqrt{10^2} + \\sqrt{6^2}$","$\\sqrt{10^2 - 6^2}$"]', '$\sqrt{10^2 - 6^2}$', NULL, 'The ladder is the hypotenuse, so $h^2 + 6^2 = 10^2$ and $h = \sqrt{10^2 - 6^2}$ (which is 8). The other options add the squares or subtract the lengths directly.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{10^2 - 6^2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h^2 + 6^2 = 10^2, h = sqrt(10^2 - 6^2) = 8.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1af56cb2-0515-4677-86e4-cc1df4ad9fd1', 'NC17.M2.G-SRT.8', 1, 'numeric', 'Find a side with the Pythagorean Theorem', 'A rectangular field is 9 meters wide and 12 meters long. How long is a straight path across the field from one corner to the opposite corner, in meters?', '[]', '15', '15', 'The path is the hypotenuse: $9^2 + 12^2 = 81 + 144 = 225$, so the length is 15 meters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(81+144) = sqrt(225) = 15.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('184bb65d-9650-4336-9492-5d152fa1b855', 'NC17.M2.G-SRT.8', 2, 'choice', 'Choose the ratio or equation for a problem', 'A 12-meter ramp makes a $20^\circ$ angle with the ground. To find the horizontal distance the ramp covers, which trigonometric ratio should be used?', '["cosine","sine","tangent","the Pythagorean Theorem"]', 'cosine', NULL, 'The horizontal distance is adjacent to the $20^\circ$ angle and the ramp (12) is the hypotenuse. Adjacent over hypotenuse is cosine.', 'checked', '{"lint":[],"solve":{"answer":"cosine","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ramp is the hypotenuse, horizontal distance adjacent to 20 degrees: cosine.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
