INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('096ba6ef-b64d-4b4e-bb7f-f517f83e7ec8', 'NC17.M2.G-SRT.8', 2, 'choice', 'Check an answer for reasonableness', 'A student is finding how high a 10-foot ladder reaches up a wall and gets 12 feet. Why must this answer be wrong?', '["The height must be smaller than the distance from the wall","A ladder can only reach a whole number of feet","The height is a leg, so it must be shorter than the 10-foot hypotenuse","The height must always be exactly half the ladder"]', 'The height is a leg, so it must be shorter than the 10-foot hypotenuse', NULL, 'The ladder is the hypotenuse, the longest side of the right triangle. Any leg, including the height, must be shorter than 10 feet.', 'checked', '{"lint":[],"solve":{"answer":"The height is a leg, so it must be shorter than the 10-foot hypotenuse","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The ladder is the hypotenuse, the longest side; a leg of 12 cannot exceed 10.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05d01949-3ea8-4906-be2b-a2b89bc68393', 'NC17.M2.G-SRT.8', 2, 'numeric', 'Find a side with a trigonometric ratio', 'A kite string is 39 meters long and makes an angle $A$ with the ground, where $\sin A = \frac{5}{13}$. How high is the kite above the ground, in meters?', '[]', '15', '39*5/13', 'The height is opposite $A$ and the string is the hypotenuse, so height $= 39 \times \frac{5}{13} = 15$ meters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 39 x 5/13 = 15.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
