INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0e280ea-4815-4f30-b72b-ace42a7b2493', 'NC17.M2.G-SRT.8', 3, 'choice', 'Special right triangles (30-60-90 and 45-45-90)', 'A square gate has a diagonal brace that is 10 feet long. Exactly how long is each side of the gate, in feet?', '["$10\\sqrt{2}$","$5$","$\\frac{\\sqrt{2}}{10}$","$5\\sqrt{2}$"]', '$5\sqrt{2}$', NULL, 'The diagonal splits the square into a 45-45-90 triangle with the brace as the hypotenuse. Each leg is the hypotenuse divided by $\sqrt{2}$: $\frac{10}{\sqrt{2}} = 5\sqrt{2}$ feet.', 'checked', '{"lint":[],"solve":{"answer":"$5\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s sqrt2 = 10, s = 10/sqrt2 = 5 sqrt2.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f15548c-d76a-4a61-9fb7-eb852461d133', 'NC17.M2.G-SRT.8', 3, 'numeric', 'Find a side with the Pythagorean Theorem', 'A triangular garden has a right angle, and the two sides next to it are 20 feet and 21 feet long. How many feet of fencing are needed to go all the way around the garden?', '[]', '70', '20+21+29', 'The third side is $\sqrt{20^2 + 21^2} = \sqrt{841} = 29$ feet. The fence needs $20 + 21 + 29 = 70$ feet.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hypotenuse sqrt(400+441) = sqrt(841) = 29; perimeter 20+21+29 = 70.","run_id":"claude-code","at":"2026-10-24T08:45:27.516Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aa1522c-84d7-4a56-82ca-0c31cba4da94', 'NC17.M2.G-SRT.12', 1, 'choice', 'Properties and side ratios of the special right triangles', 'In a 30-60-90 triangle, which side is the shortest?', '["The side opposite the 60 degree angle","The side opposite the 30 degree angle","The side opposite the 90 degree angle","None, since all three sides are the same length"]', 'The side opposite the 30 degree angle', NULL, 'The shortest side is opposite the smallest angle, which is 30 degrees. In this triangle it is also half the hypotenuse.', 'checked', '{"lint":[],"solve":{"answer":"The side opposite the 30 degree angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest side is opposite the smallest angle, 30.","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
