INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('178a9747-1f80-44fc-b5b4-3cc5eb223271', 'NC17.M2.G-SRT.12', 1, 'choice', '45-45-90 triangle: find a missing side', 'Each leg of a 45-45-90 triangle is 6 inches long. How long is the hypotenuse, in inches?', '["$12$","$6\\sqrt{3}$","$6\\sqrt{2}$","$36$"]', '$6\sqrt{2}$', NULL, 'The hypotenuse of a 45-45-90 triangle is the leg times $\sqrt{2}$, so it is $6\sqrt{2}$ inches.', 'checked', '{"lint":[],"solve":{"answer":"$6\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hyp = 6sqrt2.","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
