INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d39b0c9-7800-4a15-a140-d15ffae3598e', 'NC17.M2.G-SRT.12', 1, 'numeric', 'Special right triangles in applications', 'A straight ramp makes a 30 degree angle with the ground and rises 3 meters. How long is the ramp, in meters?', '[]', '6', '2*3', 'The rise is opposite the 30 degree angle, so it is the shorter leg of a 30-60-90 triangle. The ramp is the hypotenuse, twice as long: $2 \times 3 = 6$ meters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rise is opposite 30 degrees = shorter leg 3; ramp (hyp) = 6.","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32751120-268e-4639-a310-d6ecad8264cb', 'NC17.M2.G-SRT.12', 2, 'choice', 'Properties and side ratios of the special right triangles', 'Which set of side lengths can be the three sides of a 30-60-90 triangle?', '["$4$, $4\\sqrt{3}$, $8$","$4$, $4$, $4\\sqrt{2}$","$4$, $4\\sqrt{2}$, $8$","$4$, $8$, $8\\sqrt{3}$"]', '$4$, $4\sqrt{3}$, $8$', NULL, 'The sides of a 30-60-90 triangle are in the ratio $1 : \sqrt{3} : 2$. With a short leg of 4, the long leg is $4\sqrt{3}$ and the hypotenuse is 8. The set 4, 4, $4\sqrt{2}$ is a 45-45-90 triangle, and the others do not satisfy the Pythagorean theorem.', 'checked', '{"lint":[],"solve":{"answer":"$4$, $4\\sqrt{3}$, $8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 1 : sqrt3 : 2 -> 4, 4sqrt3, 8.","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('718ffa34-fcaf-43f7-8cd3-008d7b846db2', 'NC17.M2.G-SRT.12', 2, 'choice', 'Properties and side ratios of the special right triangles', 'A student says that a right triangle with one 45 degree angle must have two equal legs. Which reason is correct?', '["The hypotenuse of every right triangle is always equal in length to one leg","The two acute angles add up to 180 degrees, so the legs must be equal","The other acute angle is also 45 degrees, so the opposite sides are equal","Every right triangle has two sides that are equal in length to each other"]', 'The other acute angle is also 45 degrees, so the opposite sides are equal', NULL, 'The acute angles of a right triangle add to 90 degrees, so the other one is 45 degrees too. A triangle with two equal angles has the two opposite sides equal, so the legs are equal.', 'checked', '{"lint":[],"solve":{"answer":"The other acute angle is also 45 degrees, so the opposite sides are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other acute angle 180-90-45 = 45; equal angles have equal opposite sides.","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49c29ee4-17eb-46c9-83f0-fb8271346d1a', 'NC17.M2.G-SRT.12', 2, 'choice', 'Special right triangles in applications', 'Maria walks 50 meters east and then 50 meters north. How far, in meters, is she from where she started?', '["$100$","$50$","$50\\sqrt{3}$","$50\\sqrt{2}$"]', '$50\sqrt{2}$', NULL, 'Her path forms a right triangle with two equal legs of 50, a 45-45-90 triangle. Her distance from the start is the hypotenuse, $50\sqrt{2}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$50\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 50 and 50: distance 50sqrt2.","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('028f4509-a98e-4e40-b25b-c8b239f5fcb3', 'NC17.M2.G-SRT.12', 3, 'numeric', '45-45-90 triangle: find a missing side', 'In a 45-45-90 triangle the hypotenuse is 18. The altitude from the right angle to the hypotenuse splits the triangle into two smaller 45-45-90 triangles. How long is that altitude?', '[]', '9', '18/2', 'Each leg of the big triangle is $9\sqrt{2}$, and that leg is the hypotenuse of a small 45-45-90 triangle. The altitude is a leg of the small triangle: $9\sqrt{2} \div \sqrt{2} = 9$. It is half of the hypotenuse.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Altitude to hypotenuse of isosceles right triangle = half hypotenuse = 9 (legs of small triangles 9).","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('063acb76-bcae-4d26-882a-8e135ec4eb62', 'NC17.M2.G-SRT.12', 3, 'choice', 'Special right triangles in applications', 'A wire 18 meters long runs from the top of a vertical pole to the ground and makes a 60 degree angle with the ground. How tall is the pole, in meters?', '["$9$","$18\\sqrt{3}$","$9\\sqrt{2}$","$9\\sqrt{3}$"]', '$9\sqrt{3}$', NULL, 'The wire is the hypotenuse of a 30-60-90 triangle, so the shorter leg (along the ground) is 9. The pole is the longer leg, $9\sqrt{3}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$9\\sqrt{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pole opposite 60: (18/2)sqrt3 = 9sqrt3.","run_id":"claude-code","at":"2026-10-24T08:47:09.726Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68bcf37e-8c62-43c1-8206-ed5a34a93657', 'NC17.M2.S-IC.2', 1, 'numeric', 'Compare an experimental result with the theoretical probability', 'Two fair coins are tossed. The theoretical probability that both land heads is 1/4. In a simulation of 40 tosses of the pair, how many times would you expect both to land heads?', '[]', '10', '1/4*40', 'One fourth of 40 is 10 times.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 * 1/4 = 10.","run_id":"claude-code","at":"2026-10-28T18:48:28.455Z"}}', 'ai', NULL, NULL)
