INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('262981c8-58a1-4c0c-9122-91c6b9b5f7eb', 'NC17.M2.S-IC.2', 1, 'numeric', 'Compare an experimental result with the theoretical probability', 'A bag has 3 red marbles and 7 blue marbles. One marble is drawn at random. What is the theoretical probability that it is red, as a decimal?', '[]', '0.3', '3/10', 'There are 10 marbles and 3 are red, so the probability is 3/10 = 0.3.', 'checked', '{"lint":[],"solve":{"answer":"0.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/10 = 0.3.","run_id":"claude-code","at":"2026-10-28T18:48:28.492Z"}}', 'ai', NULL, NULL)
