INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02fa283e-ec6b-40bb-b831-7d7c6cd3e638', 'NC17.M2.S-IC.2', 1, 'numeric', 'Experimental probability from a simulation', 'A bag has 1 red marble and 3 blue marbles, so the theoretical probability of red is 0.25. A student simulates drawing a marble 80 times, putting it back each time, and gets red 24 times. What is the experimental probability of red, as a decimal?', '[]', '0.3', '24/80', 'Experimental probability = 24 / 80 = 0.3. It is a little higher than the theoretical 0.25.', 'checked', '{"lint":[],"solve":{"answer":"0.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 / 80 = 0.3.","run_id":"claude-code","at":"2026-10-28T19:12:24.876Z"}}', 'ai', NULL, NULL)
