INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46a857ae-c9bb-44bb-b204-286fea727be0', 'NC17.M2.S-IC.2', 2, 'numeric', 'Judge consistency using two standard deviations', 'A fair coin is flipped 100 times. The expected number of heads is 50 and the standard deviation is 5. A result is consistent if it is within 2 standard deviations of the expected count. What is the greatest number of heads that is consistent with a fair coin?', '[]', '60', '50+2*5', 'Two standard deviations is 2 x 5 = 10. The greatest consistent count is 50 + 10 = 60 heads.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50+2*5=60.","run_id":"claude-code","at":"2026-10-28T18:48:28.219Z"}}', 'ai', NULL, NULL)
