INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a829e98-5ba5-4e9b-aebe-26cb4669d767', 'NC17.M2.S-IC.2', 2, 'choice', 'Set up a simulation with random numbers', 'A student guesses on a question with 4 equally likely answer choices, so the probability of a correct guess is 1/4. Which simulation models one guess?', '["Flip a coin once; heads means a correct answer, tails means wrong","Spin a spinner with 4 equal sections; one section means correct","Roll a fair die; the numbers 1 or 2 mean a correct answer","Roll a fair die; only the number 1 means a correct answer"]', 'Spin a spinner with 4 equal sections; one section means correct', NULL, 'Only the spinner has a 1 in 4 chance. A coin gives 1/2, and the die choices give 1/3 and 1/6.', 'checked', '{"lint":[],"solve":{"answer":"Spin a spinner with 4 equal sections; one section means correct","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need P = 1/4. Die 1 only: 1/6. Die 1 or 2: 1/3. Spinner 4 equal, one correct: 1/4. Coin: 1/2.","run_id":"claude-code","at":"2026-10-28T18:48:28.331Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ade4aed-6616-4fb6-b633-d8c1886de41c', 'NC17.M2.S-IC.2', 2, 'choice', 'Judge consistency using two standard deviations', 'A fair die is rolled 180 times. The expected number of sixes is 30 and the standard deviation is 5. A result is consistent if it is within 2 standard deviations of the expected count. Which number of sixes is NOT consistent with a fair die?', '["24","41","33","38"]', '41', '30+2*5+1', 'The consistent counts run from 30 - 10 = 20 to 30 + 10 = 40. Only 41 is outside that range.', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Consistent range 30 +/- 10 = 20 to 40. 41 is outside.","run_id":"claude-code","at":"2026-10-28T18:48:28.480Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e6ca5fa-10ca-4d12-9868-c9401ab0a613', 'NC17.M2.S-IC.2', 3, 'numeric', 'Compare an experimental result with the theoretical probability', 'The theoretical probability of getting heads on a fair coin is 0.5. A computer simulation of 500 tosses gave an experimental probability of 0.468. How many fewer heads were there than the expected number?', '[]', '16', '0.5*500-0.468*500', 'The expected number of heads is 250. The simulation had 0.468 x 500 = 234 heads. The difference is 250 - 234 = 16.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Expected 0.5×500 = 250; observed 0.468×500 = 234; 250-234 = 16.","run_id":"claude-code","at":"2026-10-28T18:47:12.725Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cc4fd4e-a3f1-4681-b944-c96010573930', 'NC17.M2.S-IC.2', 3, 'numeric', 'Judge consistency using two standard deviations', 'In a set of trials the expected number of successes is 50. Using the rule that a result is consistent if it is within 2 standard deviations of the expected count, the consistent results run from 32 to 68. What is the standard deviation?', '[]', '9', '(68-50)/2', 'The consistent results reach 68 - 50 = 18 above the expected count. That is 2 standard deviations, so one standard deviation is 18 / 2 = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"68-50=18 = 2 SD, SD = 9.","run_id":"claude-code","at":"2026-10-28T18:48:28.505Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1638fce4-1fbd-4400-8f9c-369f3aa685f5', 'NC17.M2.S-CP.1', 1, 'numeric', 'Describe an event as a subset of the sample space', 'A spinner has 8 equal sections numbered 1 to 8. Event B is landing on a number greater than 4. How many outcomes are in B?', '[]', '4', NULL, 'Event B is made up of the outcomes 5, 6, 7 and 8, which is 4 outcomes.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"{5,6,7,8}: 4.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
