INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dfd7362-26de-41be-acdb-6b49dc688a32', 'NC17.M2.S-CP.1', 1, 'choice', 'Find the union of two events (A or B)', 'A card is drawn from cards numbered 1 to 8. Event A is drawing a number less than 3. Event B is drawing a number greater than 6. Which outcomes make up the event "A or B"?', '["The outcomes 3, 4, 5 and 6","The outcomes 1, 2, 3, 6, 7 and 8","The outcomes 1, 2, 7 and 8","No outcomes at all"]', 'The outcomes 1, 2, 7 and 8', NULL, 'A is 1 and 2. B is 7 and 8. "A or B" has every outcome that is in A, in B, or in both: 1, 2, 7 and 8.', 'checked', '{"lint":[],"solve":{"answer":"The outcomes 1, 2, 7 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = {1,2}, B = {7,8}; union {1,2,7,8}.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1608c9c7-58af-4acb-b91d-b7f9d9e99ba3', 'NC17.M2.S-CP.1', 1, 'choice', 'Find the complement of an event', 'A coin is flipped two times. Event E is "at least one flip lands heads". Which event is the complement of E?', '["Neither flip lands heads","Both flips land heads","Exactly one flip lands heads","The first flip lands tails"]', 'Neither flip lands heads', NULL, 'E is every outcome with at least one head: HH, HT and TH. The only outcome left is TT, where neither flip lands heads.', 'checked', '{"lint":[],"solve":{"answer":"Neither flip lands heads","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complement of at least one head is no heads: TT, neither flip heads.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
