INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b144710-d5a0-4daa-9390-fa2e0ea7ea72', 'NC17.M2.S-CP.1', 2, 'numeric', 'Describe an event as a subset of the sample space', 'A red die and a blue die are rolled. An outcome lists the red number and then the blue number, such as (2, 6). Event S is that the two numbers add to 8. How many outcomes are in S?', '[]', '5', NULL, 'The outcomes are (2, 6), (3, 5), (4, 4), (5, 3) and (6, 2), which is 5 outcomes.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,6),(3,5),(4,4),(5,3),(6,2): 5.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
