INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0506f711-1c17-417d-aeb1-a7aa1a21f4b6', 'NC17.M2.S-CP.1', 2, 'numeric', 'Find the union of two events (A or B)', 'A number is chosen from 1 to 20. Event A is choosing a multiple of 4. Event B is choosing a multiple of 5. How many outcomes are in the event "A or B"?', '[]', '8', NULL, 'A is 4, 8, 12, 16 and 20. B is 5, 10, 15 and 20. Together, listing 20 once, they are 4, 5, 8, 10, 12, 15, 16 and 20, which is 8 outcomes.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mult of 4: 5; mult of 5: 4; both (20): 1; 5 + 4 - 1 = 8.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b5ef0ca-8dc2-46a3-871e-b510586c4c5c', 'NC17.M2.S-CP.1', 2, 'numeric', 'Describe an event as a subset of the sample space', 'A coin is flipped three times. Event E is that exactly two of the flips land heads. How many outcomes are in E?', '[]', '3', NULL, 'The outcomes are HHT, HTH and THH, which is 3 outcomes.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"HHT, HTH, THH: 3.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
