INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51ff3120-ce93-4520-9f59-a877f1c7f21d', 'NC17.M2.S-CP.1', 3, 'numeric', 'Describe an event as a subset of the sample space', 'A red die and a blue die are rolled. An outcome lists the red number and then the blue number. Event T is that the sum of the two numbers is less than 5. How many outcomes are in T?', '[]', '6', '1+2+3', 'A sum of 2 can happen 1 way, a sum of 3 can happen 2 ways and a sum of 4 can happen 3 ways. In total 1 + 2 + 3 = 6 outcomes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 2: 1, sum 3: 2, sum 4: 3; total 6.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
