INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59c5d8cc-8d22-451c-8709-ef6824a867c2', 'NC17.M2.S-CP.1', 3, 'choice', 'Combine complements with unions and intersections', 'A and B are events in the same sample space. Which event is the complement of "A or B"?', '["Not A or not B (outside at least one event)","A and B (inside both events)","Not A and not B (outside both events)","A or not B (inside A or outside B)"]', 'Not A and not B (outside both events)', NULL, 'An outcome is outside "A or B" only when it is not in A and also not in B.', 'checked', '{"lint":[],"solve":{"answer":"Not A and not B (outside both events)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"De Morgan: not (A or B) = not A and not B.","run_id":"claude-code","at":"2026-10-24T08:47:58.171Z"}}', 'ai', NULL, NULL)
