INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('112aa1cb-96dc-4d4a-ab49-d9e8263cb100', 'NC17.M2.S-CP.3', 1, 'choice', 'Read P(A | B) as a share of B', 'In a two-way table, $P(A | B)$ is found by looking only at the outcomes in $B$. Which statement describes $P(A | B)$?', '["The share of A''s outcomes that are also in B","The share of all outcomes that are in both A and B","The share of B''s outcomes that are also in A","The share of all outcomes that are in B"]', 'The share of B''s outcomes that are also in A', NULL, '$P(A | B)$ restricts attention to the outcomes in $B$ and asks what share of them are also in $A$. The other statements describe $P(B | A)$, a joint probability and a marginal probability.', 'checked', '{"lint":[],"solve":{"answer":"The share of B''s outcomes that are also in A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(A|B) = share of B outcomes also in A.","run_id":"claude-code","at":"2026-10-24T08:48:47.113Z"}}', 'ai', NULL, NULL)
