INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18912dd2-7192-4f28-b7bc-75f3895ef3cc', 'NC17.M2.S-CP.3', 1, 'numeric', 'Use independence to find an unknown', 'Events $A$ and $B$ are independent and $P(A) = \frac{2}{5}$. What is $P(A | B)$?', '[]', '2/5', '2/5', 'For independent events, $P(A | B) = P(A)$, so the answer is $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Independent so P(A|B)=P(A)=2/5.","run_id":"claude-code","at":"2026-10-24T08:48:47.113Z"}}', 'ai', NULL, NULL)
