INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04a51e73-996d-46b1-ae62-06b33218305c', 'NC17.M2.S-CP.6', 1, 'numeric', 'Conditional probability from a two-way table', 'A shelter has these animals. Dogs: 6 adults and 9 puppies. Cats: 4 adults and 11 kittens. An animal is chosen at random. Given that it is an adult, what is the probability that it is a dog? Answer as a fraction.', '[]', '3/5', '6/10', 'There are $6 + 4 = 10$ adult animals. Of these, 6 are dogs. So the probability is $\frac{6}{10} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adults 6+4=10; adult dogs 6. 6/10 = 3/5.","run_id":"claude-code","at":"2026-10-24T08:49:22.047Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3556c9b3-0a38-4169-b0a1-3ecc6ccaa7d5', 'NC17.M2.S-CP.6', 2, 'numeric', 'Conditional probability from P(A and B) and P(B)', 'For two events, $P(A) = 0.6$, $P(B) = 0.5$ and $P(A \text{ and } B) = 0.24$. What is $P(B | A)$?', '[]', '0.4', '0.24/0.6', '$P(B | A) = \frac{P(A \text{ and } B)}{P(A)} = \frac{0.24}{0.6} = 0.4$. The given group is $A$, so we divide by $P(A)$.', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(B|A) = 0.24/0.6 = 0.4.","run_id":"claude-code","at":"2026-10-24T08:49:22.047Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40b934ac-a6a6-49a8-88fe-e8ecad251365', 'NC17.M2.S-CP.6', 2, 'numeric', 'Conditional probability from P(A and B) and P(B)', 'At a school, 60% of the students play a sport, and 45% of the students play a sport and are in a club. What is the probability that a student is in a club, given that the student plays a sport? Answer as a decimal.', '[]', '0.75', '0.45/0.6', '$P(\text{club} | \text{sport}) = \frac{0.45}{0.6} = 0.75$.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.45/0.60 = 0.75.","run_id":"claude-code","at":"2026-10-24T08:49:22.047Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('050d0874-4e36-4bd3-9dda-672a02a90a32', 'NC17.M2.S-CP.6', 2, 'choice', 'Interpret a conditional probability in context', 'Among 80 people who got a flu shot, 4 got the flu. So $P(\text{flu} | \text{shot}) = \frac{1}{20}$. Which sentence describes this probability?', '["Among all people, 1 in 20 got the shot and the flu","Among the people who got the flu, 1 in 20 got the shot","Among all people, 1 in 20 got the flu","Among the people who got the shot, 1 in 20 got the flu"]', 'Among the people who got the shot, 1 in 20 got the flu', NULL, 'The given group is the people who got the flu shot, and 4 of those 80 people got the flu. So 1 in 20 people in that group got the flu.', 'checked', '{"lint":[],"solve":{"answer":"Among the people who got the shot, 1 in 20 got the flu","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Among those who got the shot, 4/80 = 1/20 got the flu.","run_id":"claude-code","at":"2026-10-24T08:49:22.047Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('265d7591-243d-4b23-9bd5-2a3e7dc1f008', 'NC17.M2.S-CP.6', 3, 'choice', 'Choose which group is the given one', 'Of 100 students, 40 are seniors, 25 have a job, and 15 are seniors with a job. Which statement is correct?', '["$P(\\text{job} | \\text{senior}) = \\frac{3}{5}$, which is larger than $P(\\text{senior} | \\text{job}) = \\frac{3}{8}$","The two are equal, since both count the same 15 students","$P(\\text{senior} | \\text{job}) = \\frac{3}{5}$, which is larger than $P(\\text{job} | \\text{senior}) = \\frac{3}{8}$","$P(\\text{senior} | \\text{job})$ and $P(\\text{job} | \\text{senior})$ both equal $\\frac{3}{20}$"]', '$P(\text{senior} | \text{job}) = \frac{3}{5}$, which is larger than $P(\text{job} | \text{senior}) = \frac{3}{8}$', NULL, '$P(\text{senior} | \text{job}) = \frac{15}{25} = \frac{3}{5}$ (divide by the 25 with a job). $P(\text{job} | \text{senior}) = \frac{15}{40} = \frac{3}{8}$ (divide by the 40 seniors). The first is larger. The value $\frac{3}{20}$ is $\frac{15}{100}$, the share of all students who are both.', 'checked', '{"lint":[],"solve":{"answer":"$P(\\text{senior} | \\text{job}) = \\frac{3}{5}$, which is larger than $P(\\text{job} | \\text{senior}) = \\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(job|senior) = 15/40 = 3/8; P(senior|job) = 15/25 = 3/5. 3/5 > 3/8.","run_id":"claude-code","at":"2026-10-24T08:49:22.047Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1008e142-0d5f-4c69-a85f-fa32bbace5c7', 'NC17.M2.S-CP.6', 3, 'numeric', 'Use a conditional probability to find a count', 'The probability that a person owns a tent, given that the person is in the hiking club, is $\frac{2}{3}$. If 18 people in the club own a tent, how many people are in the club?', '[]', '27', '18/(2/3)', 'Two thirds of the club own a tent, and that is 18 people. So the club has $18 \div \frac{2}{3} = 18 \times \frac{3}{2} = 27$ people.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3) x N = 18, N = 27.","run_id":"claude-code","at":"2026-10-24T08:49:22.047Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('488ad757-77eb-49cd-9d62-ecff8d92a1d9', 'NC17.M2.S-CP.7', 1, 'numeric', 'Add the probabilities of mutually exclusive events', 'A card is drawn from a standard deck of 52 cards. What is the probability that it is a heart or a spade? Answer as a fraction.', '[]', '1/2', '13/52+13/52', 'A card cannot be both a heart and a spade, so add: $\frac{13}{52} + \frac{13}{52} = \frac{26}{52} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13 + 13 = 26 of 52: 1/2.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0896092f-bac4-41ac-bdbc-6ebce1769efd', 'NC17.M2.S-CP.7', 1, 'numeric', 'Addition Rule with cards, dice, spinners and marbles', 'A bag has 10 marbles. Four are red, 5 are striped, and 2 are red and striped. One marble is drawn at random. What is the probability that it is red or striped? Answer as a fraction.', '[]', '7/10', '4/10+5/10-2/10', 'The 2 red striped marbles are counted in both groups, so subtract them once: $\frac{4}{10} + \frac{5}{10} - \frac{2}{10} = \frac{7}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 5 - 2 = 7: 7/10.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49343d7c-5118-4796-978f-1feb898c5df7', 'NC17.M2.S-CP.7', 1, 'numeric', 'Add the probabilities of mutually exclusive events', 'Events $A$ and $B$ cannot happen together. $P(A \text{ or } B) = 0.9$ and $P(A) = 0.6$. What is $P(B)$?', '[]', '0.3', '0.9-0.6', 'With no overlap, $P(A \text{ or } B) = P(A) + P(B)$. So $P(B) = 0.9 - 0.6 = 0.3$.', 'checked', '{"lint":[],"solve":{"answer":"0.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.9 - 0.6 = 0.3.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('463deddc-9e9b-4578-a572-9d6ef27a211e', 'NC17.M2.S-CP.7', 2, 'numeric', 'Addition Rule with cards, dice, spinners and marbles', 'A fair number cube is rolled. What is the probability of rolling an even number or a number greater than 4? Answer as a fraction.', '[]', '2/3', '3/6+2/6-1/6', 'Even numbers: 2, 4, 6. Numbers greater than 4: 5, 6. The number 6 is in both. So $\frac{3}{6} + \frac{2}{6} - \frac{1}{6} = \frac{4}{6} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even {2,4,6} or >4 {5,6}: {2,4,5,6} = 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4cde740d-7475-4233-88df-b54c6fc13a1c', 'NC17.M2.S-CP.7', 2, 'numeric', 'Find the overlap or a missing probability with the rule', 'At a school, 45% of students are in a club, 30% play a sport, and 60% are in a club or play a sport. What is the probability that a randomly chosen student is in a club and plays a sport? Answer as a decimal.', '[]', '0.15', '0.45+0.3-0.6', 'From the Addition Rule, $P(\text{both}) = P(\text{club}) + P(\text{sport}) - P(\text{club or sport}) = 0.45 + 0.3 - 0.6 = 0.15$.', 'checked', '{"lint":[],"solve":{"answer":"0.15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.45 + 0.30 - 0.60 = 0.15.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c833c9d-74d1-4e42-b585-e55eec6e40b5', 'NC17.M2.S-CP.7', 2, 'numeric', 'Addition Rule with cards, dice, spinners and marbles', 'Two fair number cubes are rolled. What is the probability that the sum is 7 or 11? Answer as a fraction.', '[]', '2/9', '6/36+2/36', 'There are 6 ways to get a sum of 7 and 2 ways to get 11 out of 36 outcomes. They cannot both happen, so add: $\frac{6}{36} + \frac{2}{36} = \frac{8}{36} = \frac{2}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"2/9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 7: 6 ways; sum 11: 2 ways. 8/36 = 2/9.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13bb6b84-491f-40e1-932f-6caabba23e01', 'NC17.M2.S-CP.7', 3, 'numeric', 'Find the overlap or a missing probability with the rule', 'For two events, $P(A \text{ or } B) = 0.85$, $P(A \text{ and } B) = 0.25$ and $P(A) = 0.6$. What is $P(B)$?', '[]', '0.5', '0.85+0.25-0.6', 'Rearrange $P(A \text{ or } B) = P(A) + P(B) - P(A \text{ and } B)$ to get $P(B) = 0.85 + 0.25 - 0.6 = 0.5$.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.85 = 0.6 + P(B) - 0.25, P(B) = 0.5.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0953b2db-b111-416e-bac4-dc0e1c57bb8c', 'NC17.M2.S-CP.7', 3, 'numeric', 'Probability of neither event', 'Of 200 students, 120 have a laptop, 90 have a tablet and 40 have both. A student is chosen at random. What is the probability that the student has neither a laptop nor a tablet? Answer as a fraction.', '[]', '3/20', '1-(120+90-40)/200', 'Students with a laptop or a tablet: $120 + 90 - 40 = 170$. So $200 - 170 = 30$ have neither, and the probability is $\frac{30}{200} = \frac{3}{20}$.', 'checked', '{"lint":[],"solve":{"answer":"3/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Union 120 + 90 - 40 = 170; neither 30. 30/200 = 3/20.","run_id":"claude-code","at":"2026-10-24T08:49:22.085Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be46e8a-3597-4723-b295-c00204118c0a', 'NC17.M2.S-CP.8', 1, 'numeric', 'Independent events: P(A and B) = P(A) * P(B)', 'A fair coin is flipped and a fair six-sided die is rolled. The coin and the die do not affect each other. What is the probability of getting heads and a $4$?', '[]', '1/12', '1/2*1/6', 'The events are independent, so multiply: $\frac{1}{2} \cdot \frac{1}{6} = \frac{1}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"1/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Independent: P(H)=1/2, P(4)=1/6; product 1/12.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1598e662-f896-49c9-aa2e-571db464653a', 'NC17.M2.S-CP.8', 1, 'choice', 'Interpreting P(A and B) in context', 'Let $A$ be "a student plays chess" and $B$ be "the same student plays piano". For a randomly chosen student, $P(A \text{ and } B) = 0.12$. Which statement says what this means?', '["The chance a student plays both chess and piano is 12%","The chance a student plays chess or piano is 12%","The chance a student plays chess but not piano is 12%","The chance a student who plays chess also plays piano is 12%"]', 'The chance a student plays both chess and piano is 12%', NULL, '$P(A \text{ and } B)$ is the probability that both things are true for the same student, so $0.12$ means a 12% chance that the student plays both.', 'checked', '{"lint":[],"solve":{"answer":"The chance a student plays both chess and piano is 12%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(A and B) is the chance of both: plays chess and piano, 12%.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eacec40-ac6a-45af-8777-f559eff71cb2', 'NC17.M2.S-CP.8', 1, 'choice', 'Independent events: P(A and B) = P(A) * P(B)', 'A spinner has $5$ equal sections numbered $1$ to $5$. It is spun twice. What is the probability that the first spin is an even number and the second spin is a $5$?', '["$\\frac{3}{25}$","$\\frac{2}{25}$","$\\frac{7}{5}$","$\\frac{2}{5}$"]', '$\frac{2}{25}$', NULL, 'The spins are independent. $P(\text{even}) = \frac{2}{5}$ (the numbers $2$ and $4$) and $P(5) = \frac{1}{5}$. Multiply: $\frac{2}{5} \cdot \frac{1}{5} = \frac{2}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{25}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even on 1-5: 2,4 so 2/5; a 5 is 1/5; independent spins: 2/25.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06e621c4-2de3-4859-a110-09a15e066884', 'NC17.M2.S-CP.8', 2, 'choice', 'Choosing or checking the product for a draw without replacement', 'A bag has $6$ red marbles and $4$ blue marbles. Two marbles are drawn without replacement. Which expression gives the probability that both are red?', '["$\\frac{6}{10} \\cdot \\frac{5}{9}$","$\\frac{6}{10} \\cdot \\frac{6}{10}$","$\\frac{6}{10} \\cdot \\frac{5}{10}$","$\\frac{6}{10} + \\frac{5}{9}$"]', '$\frac{6}{10} \cdot \frac{5}{9}$', NULL, 'The first draw is red with probability $\frac{6}{10}$. With no replacement, $9$ marbles are left and $5$ are red, so the second draw is red with probability $\frac{5}{9}$. Multiply the two.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{10} \\cdot \\frac{5}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(R1)=6/10, P(R2|R1)=5/9; product.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52061bd6-5115-4cce-bccd-b34f6fc2beaf', 'NC17.M2.S-CP.8', 2, 'choice', 'Finding a missing probability from the rule', 'For events $A$ and $B$, $P(A \text{ and } B) = 0.18$ and $P(A) = 0.3$. What is $P(B | A)$?', '["0.54","0.6","0.12","0.054"]', '0.6', '0.18/0.3', 'Since $P(A \text{ and } B) = P(A) \cdot P(B | A)$, we get $P(B | A) = 0.18 \div 0.3 = 0.6$.', 'checked', '{"lint":[],"solve":{"answer":"0.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(B|A)=P(A and B)/P(A)=0.18/0.3=0.6.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('349f02a3-d760-43e2-8874-45ee08c71357', 'NC17.M2.S-CP.8', 2, 'numeric', 'Finding a missing probability from the rule', 'Events $A$ and $B$ are independent. $P(A) = 0.3$ and $P(A \text{ and } B) = 0.15$. What is $P(B)$?', '[]', '0.5', '0.15/0.3', 'For independent events, $P(A \text{ and } B) = P(A) \cdot P(B)$. So $P(B) = 0.15 \div 0.3 = 0.5$.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Independent: P(B)=0.15/0.3=0.5.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
