INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14ee724e-4e77-4b23-919e-1a9a16841f9d', 'NC17.M2.S-CP.8', 3, 'numeric', 'Draws without replacement: three draws, or two ways to succeed', 'A bag holds $5$ red marbles and $3$ blue marbles. Three marbles are drawn at random without replacement. What is the probability that all three are red?', '[]', '5/28', '5/8*4/7*3/6', 'Each draw leaves one fewer marble and one fewer red marble: $\frac{5}{8} \cdot \frac{4}{7} \cdot \frac{3}{6} = \frac{60}{336} = \frac{5}{28}$.', 'checked', '{"lint":[],"solve":{"answer":"5/28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8*4/7*3/6=60/336=5/28.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07983920-7827-491e-86fd-ee40ace6732c', 'NC17.M2.S-CP.8', 3, 'choice', 'Deciding whether the independent case applies', 'For events $A$ and $B$, $P(A) = 0.5$, $P(B) = 0.4$ and $P(A \text{ and } B) = 0.25$. Are $A$ and $B$ independent?', '["No, because $0.5 + 0.4 = 0.9$, and that sum does not equal $0.25$","Yes, because $0.5 \\times 0.4 = 0.2$, which is close to $0.25$","No, because $0.5 \\times 0.4 = 0.2$, which does not equal $0.25$","Yes, because $0.25$ is less than both $0.5$ and $0.4$"]', 'No, because $0.5 \times 0.4 = 0.2$, which does not equal $0.25$', NULL, 'Events are independent only if $P(A \text{ and } B) = P(A) \cdot P(B)$. Here $P(A) \cdot P(B) = 0.2$, but $P(A \text{ and } B) = 0.25$, so they are not independent. Being close is not enough.', 'checked', '{"lint":[],"solve":{"answer":"No, because $0.5 \\times 0.4 = 0.2$, which does not equal $0.25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5*0.4=0.2, not 0.25, so not independent.","run_id":"claude-code","at":"2026-10-24T08:44:19.564Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088da5a8-1c4d-4e08-aaa9-b78721c39887', 'NC17.M3.N-CN.9', 1, 'numeric', 'Roots and x-intercepts', 'A polynomial of degree 5 has at most ? x-intercepts. What number is the ?', '[]', '5', '5', 'Each x-intercept is a real root, and a polynomial of degree 5 has only 5 roots in all, so it has at most 5 x-intercepts.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A degree 5 polynomial has at most 5 real roots, so at most 5 x-intercepts.","run_id":"claude-code","at":"2026-10-24T02:58:26.400Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('178910e9-1e22-4586-b016-3291abe37df4', 'NC17.M3.N-CN.9', 1, 'numeric', 'Smallest degree from given roots', 'What is the smallest possible degree of a polynomial that has the roots $1$, $2$ and $3$?', '[]', '3', '3', 'Each different root needs its own factor, and three factors make degree 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-1)(x-2)(x-3) has degree 3; fewer degrees cannot have 3 distinct roots.","run_id":"claude-code","at":"2026-10-28T18:48:27.951Z"}}', 'ai', NULL, NULL)
