INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b7e7c1c-dada-47bd-bba1-bc9cb8d8d099', 'NC17.M3.N-CN.9', 1, 'choice', 'Solutions of a power equation', 'Which are all the solutions of $x^{2} = -16$ in the complex numbers?', '["$4$ and $-4$","$16i$ and $-16i$","$4i$ and $-4i$","$4i$ only"]', '$4i$ and $-4i$', NULL, '$(4i)^{2} = 16i^{2} = -16$ and $(-4i)^{2} = -16$. The equation has degree 2, so these two are all the solutions.', 'checked', '{"lint":[],"solve":{"answer":"$4i$ and $-4i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = -16 gives x = +/- sqrt(-16) = +/- 4i. Both 4i and -4i.","run_id":"claude-code","at":"2026-10-28T18:48:28.096Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00097c91-bccb-46e9-b94a-635b7bbe2037', 'NC17.M3.N-CN.9', 2, 'choice', 'Odd degree has a real root', 'Which polynomial with real coefficients must have at least one real root?', '["$x^4 + 1$","$x^2 + 4$","$x^5 + 2x^2 + 1$","$x^4 + 3x^2 + 1$"]', '$x^5 + 2x^2 + 1$', NULL, 'A polynomial of odd degree has an odd number of roots, and nonreal roots come in pairs, so at least one root is real. The others have even degree and no real roots, since each of $x^4$, $x^2$ and $x^6$ is at least 0.', 'checked', '{"lint":[],"solve":{"answer":"$x^5 + 2x^2 + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd degree with real coefficients must have a real root: x^5 + 2x^2 + 1. The others are always positive (x^4+3x^2+1, x^2+4, x^4+1 > 0).","run_id":"claude-code","at":"2026-10-24T02:58:26.400Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05ac63e2-0516-47a0-aa16-414bef64a1be', 'NC17.M3.N-CN.9', 2, 'numeric', 'Number of roots from the degree', 'How many complex roots, counting multiplicity, does $(2x^{3} - 1)(x^{2} + 5)$ have?', '[]', '5', '3+2', 'The product has degree $3 + 2 = 5$, so it has 5 complex roots, counting multiplicity.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Degree 3+2=5, so 5 roots.","run_id":"claude-code","at":"2026-10-28T18:48:28.192Z"}}', 'ai', NULL, NULL)
