INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03fed685-f0a6-4cad-ac19-086797689882', 'NC17.M3.N-CN.9', 2, 'numeric', 'Roots from factored form', 'How many different complex numbers are roots of $(x-1)^{3}(x+4)^{2}(x^{2}+9)$?', '[]', '4', '4', 'The factors give the roots 1 and $-4$, and $x^{2} + 9 = 0$ gives $3i$ and $-3i$. That is 4 different roots.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distinct roots: 1, -4, 3i, -3i. Four.","run_id":"claude-code","at":"2026-10-28T18:48:28.599Z"}}', 'ai', NULL, NULL)
