INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01cc687f-9996-4115-9c8e-3e1d81b6f044', 'NC17.M3.N-CN.9', 3, 'numeric', 'Possible numbers of real and nonreal roots', 'What is the greatest number of nonreal roots, counting multiplicity, that a polynomial of degree 7 with real coefficients can have?', '[]', '6', '6', 'The number of nonreal roots is even and at most 7, so at most 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nonreal roots come in conjugate pairs; degree 7 has at least one real root, so at most 6 nonreal.","run_id":"claude-code","at":"2026-10-28T18:48:28.450Z"}}', 'ai', NULL, NULL)
