INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12d63ee0-5446-4e4a-8e89-19bdc2396929', 'NC17.M3.A-SSE.1', 1, 'numeric', 'Pieces of a piecewise expression', 'A parking fee in dollars for $h$ hours is $5h$ when $h \le 3$, and 15 when $h > 3$. What is the fee for a 5-hour stay, in dollars?', '[]', '15', '15', 'A 5-hour stay has $h > 3$, so the second rule applies and the fee is 15 dollars.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 5 > 3, so the fee is 15.","run_id":"claude-code","at":"2026-10-24T02:59:01.992Z"}}', 'ai', NULL, NULL)
