INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01caf8cb-73a5-4e90-8635-0e3e89771db6', 'NC17.M3.A-SSE.1', 1, 'choice', 'A multi-part expression as a single entity', 'A store takes a fraction $d$ off the original price $P$, so the sale price is $P(1 - d)$ dollars. What does the quantity $1 - d$ represent?', '["the fraction of the original price that is taken off the price","the amount of the discount, in dollars","the fraction of the original price that is still paid","the original price of the item, in dollars"]', 'the fraction of the original price that is still paid', NULL, 'Taking away a fraction $d$ leaves $1 - d$ of the price, so $1 - d$ is the part still paid.', 'checked', '{"lint":[],"solve":{"answer":"the fraction of the original price that is still paid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(1-d): 1 is the whole price, d the fraction removed, so 1-d is the fraction of the original price still paid.","run_id":"claude-code","at":"2026-10-28T19:20:44.430Z"}}', 'ai', NULL, NULL)
