INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d1dd8b6-7f6f-4a17-9872-446f114df4e6', 'NC17.M3.A-SSE.1', 2, 'choice', 'Meaning of a constant term or parameter in context', 'A ball''s height in feet after $t$ seconds is $h(t) = -16t^{2} + 48t + 5$. What does the 5 represent?', '["the greatest height that the ball reaches in flight","the height of the ball at the start, when $t = 0$","the number of seconds before the ball lands","the speed of the ball at the moment it is thrown"]', 'the height of the ball at the start, when $t = 0$', NULL, 'At $t = 0$ the first two terms are 0, so $h(0) = 5$. The 5 is the starting height in feet. The greatest height and the landing time depend on all three terms.', 'checked', '{"lint":[],"solve":{"answer":"the height of the ball at the start, when $t = 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(0) = 5, the starting height.","run_id":"claude-code","at":"2026-10-24T02:59:01.992Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a41ab2f-10fc-4307-89f5-661fda452c2c', 'NC17.M3.A-SSE.1', 2, 'numeric', 'A multi-part expression as a single entity', 'The expression $2(x - 1)^{2} + 3(x - 1)$ is evaluated at $x = 5$. What is its value?', '[]', '44', '2*16+3*4', 'At $x = 5$, the quantity $x - 1$ is 4. Then $2(4)^{2} + 3(4) = 32 + 12 = 44$.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-1 = 4: 2·16 + 3·4 = 32 + 12 = 44.","run_id":"claude-code","at":"2026-10-28T19:20:44.509Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b1fe8fe-dd61-4a44-9638-ea4707ddf02f', 'NC17.M3.A-SSE.1', 2, 'numeric', 'Pieces of a piecewise expression', 'A worker earns $12h$ dollars for $h \le 40$ hours, and $480 + 18(h - 40)$ dollars for $h > 40$ hours. How many hours did a worker work who earned 570 dollars?', '[]', '45', '40+(570-480)/18', 'Since $12 \times 40 = 480 < 570$, the second piece applies: $480 + 18(h - 40) = 570$, so $h - 40 = 5$ and $h = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12h=570 gives 47.5, not <=40. So 480+18(h-40)=570, 18(h-40)=90, h=45.","run_id":"claude-code","at":"2026-10-28T19:20:44.647Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('009289d9-a6ef-42c2-9e34-5ea7d33fc8b2', 'NC17.M3.A-SSE.1', 3, 'numeric', 'Meaning of the exponent and period in an exponential expression', 'The shares of an online post after $t$ hours are $S = 50 \cdot 3^{t/4}$. By what factor do the shares grow every 8 hours?', '[]', '9', '3^2', 'In 8 hours the exponent $\frac{t}{4}$ increases by 2, so the shares are multiplied by $3^{2} = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S(t+8)/S(t)=3^(8/4)=9.","run_id":"claude-code","at":"2026-10-28T19:20:44.649Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0277cc70-eff1-4826-b7e2-409f1ca203d8', 'NC17.M3.A-SSE.1', 3, 'numeric', 'Parts of a rational expression', 'For every real number $x$, what is the greatest value of the expression $\frac{1}{(x - 1)^{2} + 4}$?', '[]', '1/4', '1/4', 'The denominator is smallest when $(x - 1)^{2} = 0$, where it equals 4. A fraction with a positive numerator is largest when the denominator is smallest, so the greatest value is $\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Denominator least is 4 at x = 1, so greatest value 1/4.","run_id":"claude-code","at":"2026-10-28T19:20:44.749Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b29c8c3-9f4b-4195-8591-db94454f8c1e', 'NC17.M3.A-SSE.2', 1, 'choice', 'Rewrite an exponential expression', 'Which expression is equivalent to $\left(2^x\right)^4$?', '["$8^x$","$16^x$","$2^{x+4}$","$6^x$"]', '$16^x$', NULL, '$\left(2^x\right)^4=2^{4x}=\left(2^4\right)^x=16^x$.', 'checked', '{"lint":[],"solve":{"answer":"$16^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2^x)^4 = 2^{4x} = 16^x.","run_id":"claude-code","at":"2026-10-28T19:20:44.290Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035b7014-8f81-4a4f-b4ae-9fa21ae73e5f', 'NC17.M3.A-SSE.2', 1, 'choice', 'Factor an expression in quadratic form', 'Which expression is equivalent to $x^4 + 6x^2 + 9$?', '["$\\left(x^2 + 3\\right)^2$","$(x + 3)^4$","$\\left(x^2 + 9\\right)^2$","$\\left(x^2 - 3\\right)^2$"]', '$\left(x^2 + 3\right)^2$', NULL, 'With $u=x^2$, the expression is $u^2+6u+9=(u+3)^2$, so it equals $(x^2+3)^2$.', 'checked', '{"lint":[],"solve":{"answer":"$\\left(x^2 + 3\\right)^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^2+3)^2 = x^4+6x^2+9.","run_id":"claude-code","at":"2026-10-28T19:20:44.410Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cbddae1-be13-4319-87ee-5efa1ee49977', 'NC17.M3.A-SSE.2', 1, 'numeric', 'Rewrite an exponential expression', 'The expression $4^x \cdot 2^x$ can be written as $b^x$. What is $b$?', '[]', '8', '4*2', 'Powers with the same exponent multiply: $4^x\cdot 2^x=(4\cdot 2)^x=8^x$, so $b=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^x·2^x = (4·2)^x = 8^x.","run_id":"claude-code","at":"2026-10-28T19:20:44.521Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('210d5d1c-08da-46d6-8884-22ac5e048560', 'NC17.M3.A-SSE.2', 2, 'numeric', 'Factor an expression in quadratic form', 'The expression $x^4 - 13x^2 + 36$ can be written as $(x^2 - a)(x^2 - b)$ with $a < b$. What is $b$?', '[]', '9', '9', 'Treat $x^2$ as one unit. Find two numbers with product $36$ and sum $13$: $4$ and $9$. So the expression is $(x^2 - 4)(x^2 - 9)$, $a = 4$ and $b = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"u=x^2: u^2-13u+36=(u-4)(u-9); a=4,b=9","run_id":"claude-code","at":"2026-10-24T02:59:02.090Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('173de39e-2d1f-43a1-be25-ec318bdfdda4', 'NC17.M3.A-SSE.2', 2, 'choice', 'Rewrite a growth factor for a different time period', 'A balance after $t$ years is $1200 \cdot 1.03^{4t}$. Which expression is equal to it and shows the growth factor for one year?', '["$1200\\left(1.03^4\\right)^t$","$1200\\left(1.03 \\cdot 4\\right)^t$","$1200(1.12)^t$","$1200(1.03)^{t/4}$"]', '$1200\left(1.03^4\right)^t$', NULL, '$1.03^{4t}=\left(1.03^4\right)^t$, so the growth factor for one year is $1.03^4\approx 1.1255$. It is not $1.12$.', 'checked', '{"lint":[],"solve":{"answer":"$1200\\left(1.03^4\\right)^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.03^{4t} = (1.03^4)^t; 1.03^4 = 1.1255..., not 1.12, so only (1.03^4)^t is equal.","run_id":"claude-code","at":"2026-10-28T19:20:44.353Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('201b9a51-a53e-4ecd-ac2a-6e704cf797c0', 'NC17.M3.A-SSE.2', 2, 'numeric', 'Use an identity to simplify or compute', 'The numbers $a$ and $b$ satisfy $a + b = 9$ and $a - b = 4$. What is $a^2 - b^2$?', '[]', '36', '9*4', '$a^2-b^2=(a+b)(a-b)=9\cdot 4=36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2 - b^2 = (a+b)(a-b) = 36.","run_id":"claude-code","at":"2026-10-28T19:20:44.541Z"}}', 'ai', NULL, NULL)
