INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('082274c9-18b2-4e0b-b1f1-844e3d60206f', 'NC17.M3.A-SSE.2', 3, 'numeric', 'Factor a sum or difference of cubes', 'The expression $x^6 - 64$ is factored completely using integers, with no factor that can be factored further. How many factors are there?', '[]', '4', NULL, '$x^6-64=(x^3-8)(x^3+8)=(x-2)(x^2+2x+4)(x+2)(x^2-2x+4)$. The quadratic factors have no integer factors, so there are 4 factors.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^3-8)(x^3+8) = (x-2)(x^2+2x+4)(x+2)(x^2-2x+4): 4 factors.","run_id":"claude-code","at":"2026-10-28T19:20:44.419Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d086ab-e8e0-43ca-ba7c-a59d744c42c5', 'NC17.M3.A-SSE.2', 3, 'numeric', 'Complete the square', 'The expression $3x^2 - 12x + 5$ can be written as $3(x - h)^2 + k$. What is $k$?', '[]', '-7', '5-12', '$3x^2-12x+5=3(x^2-4x)+5=3\left[(x-2)^2-4\right]+5=3(x-2)^2-12+5=3(x-2)^2-7$. So $k=-7$.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x^2-4x) + 5 = 3(x-2)^2 - 12 + 5 = 3(x-2)^2 - 7. k = -7.","run_id":"claude-code","at":"2026-10-28T19:20:44.628Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('128e0f30-cb88-4d91-8ee3-ecf7552db1d8', 'NC17.M3.A-SSE.3', 1, 'choice', 'Rewrite with the power of a power rule', 'Which expression is equivalent to $3^{2t}$?', '["$6^t$","$3^{t+2}$","$2 \\cdot 3^t$","$9^t$"]', '$9^t$', NULL, '$3^{2t} = (3^2)^t = 9^t$. The exponent $2t$ means the base is squared first, not multiplied by 2 or added to $t$.', 'checked', '{"lint":[],"solve":{"answer":"$9^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^{2t}=(3^2)^t=9^t.","run_id":"claude-code","at":"2026-10-24T02:59:33.943Z"}}', 'ai', NULL, NULL)
