INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d3b6868-81db-48be-9f42-f9aa02db6d27', 'NC17.M3.A-SSE.3', 1, 'numeric', 'Rewrite with the power of a power rule', '$\left(3^{4}\right)^{t} = 3^{kt}$ for every $t$. What is $k$?', '[]', '4', '4', 'Power of a power: $\left(3^{4}\right)^{t} = 3^{4t}$, so $k = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3^4)^t = 3^{4t}, k=4.","run_id":"claude-code","at":"2026-10-28T19:20:44.384Z"}}', 'ai', NULL, NULL)
