INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18cce49f-3fc3-4eee-aa70-d8fdaedb045e', 'NC17.M3.A-SSE.3', 1, 'numeric', 'Doubling, tripling and half-life periods', 'A medicine has a half-life of 5 days, which means half of it is gone every 5 days. A patient has 200 milligrams. How many milligrams are left after 10 days?', '[]', '50', '200/2/2', '10 days is 2 half-lives. After the first 5 days there are $100$ milligrams, and after 5 more days there are $50$ milligrams.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 days = 2 half-lives: 200/2/2 = 50.","run_id":"claude-code","at":"2026-10-28T19:20:44.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05a63f85-931a-4e15-9119-c4a4091931d0', 'NC17.M3.A-SSE.3', 2, 'choice', 'Rewrite with a different time unit', 'The number of germs is $T = 250 \cdot 3^{d}$, where $d$ is in days. Let $w$ be the same time in weeks, so $d = 7w$. Which expression gives $T$ using $w$?', '["$250 \\cdot 3^{w/7}$","$250 \\cdot 21^{w}$","$1750 \\cdot 3^{w}$","$250 \\cdot 3^{7w}$"]', '$250 \cdot 3^{7w}$', NULL, 'Replace $d$ with $7w$: $T = 250 \cdot 3^{7w}$.', 'checked', '{"lint":[],"solve":{"answer":"$250 \\cdot 3^{7w}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 7w: 250*3^{7w}. (3^7 = 2187, not 21.)","run_id":"claude-code","at":"2026-10-28T19:20:44.371Z"}}', 'ai', NULL, NULL)
