INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('070e0ca3-f89c-41f8-8558-364835a51968', 'NC17.M3.A-SSE.3', 2, 'choice', 'Rewrite with the power of a power rule', 'A student writes $\left(2^{t}\right)^{3} = 2^{t+3}$. What is the error?', '["The exponents should be added, giving $2^{t+3}$","The exponents should be multiplied, giving $2^{3t}$","The bases should be multiplied, giving $6^{t}$","The exponent 3 should be subtracted, giving $2^{t-3}$"]', 'The exponents should be multiplied, giving $2^{3t}$', NULL, 'The power of a power rule says $\left(a^{m}\right)^{n} = a^{mn}$: the exponents are multiplied, so $\left(2^{t}\right)^{3} = 2^{3t}$.', 'checked', '{"lint":[],"solve":{"answer":"The exponents should be multiplied, giving $2^{3t}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Power of a power: (2^t)^3 = 2^{3t}; the student added instead of multiplying.","run_id":"claude-code","at":"2026-10-28T19:20:44.379Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('063398e3-8fc8-43a3-85a5-2fbd3940d345', 'NC17.M3.A-SSE.3', 2, 'choice', 'Change the base of an exponential expression', 'Which expression is equivalent to $4^{3t}$?', '["$2^{6t}$","$2^{3t}$","$8^{t}$","$12^{t}$"]', '$2^{6t}$', NULL, '$4 = 2^2$, so $4^{3t} = \left(2^{2}\right)^{3t} = 2^{6t}$.', 'checked', '{"lint":[],"solve":{"answer":"$2^{6t}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^{3t} = 2^{6t}. 12^t, 2^{3t}, 8^t = 2^{3t} are not equal.","run_id":"claude-code","at":"2026-10-28T19:20:44.510Z"}}', 'ai', NULL, NULL)
