INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03901260-6367-49a3-8f1e-74c7cc839e5f', 'NC17.M3.A-SSE.3', 3, 'choice', 'Compound interest: rate per period and per year', 'Account A has balance $500(1.06)^t$ and account B has balance $500(1.03)^{2t}$, where $t$ is in years. Which statement is true?', '["Account A has more, since 6% is greater than 3%","Account B has more, since $1.03^2$ is greater than $1.06$","The accounts have the same balance, since 3% twice is 6%","Account A has more, since $1.06$ is greater than $1.03^2$"]', 'Account B has more, since $1.03^2$ is greater than $1.06$', NULL, '$1.03^2 = 1.0609$, which is more than 1.06. Each year account B is multiplied by 1.0609 and account A by 1.06, so B has more. (B earns interest on interest after 6 months.)', 'checked', '{"lint":[],"solve":{"answer":"Account B has more, since $1.03^2$ is greater than $1.06$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.03^2=1.0609>1.06, so B grows faster and has more for t>0 (equal at t=0).","run_id":"claude-code","at":"2026-10-24T02:59:33.943Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035ea80c-56c5-4850-86d5-fc312c077e6b', 'NC17.M3.A-SSE.3', 3, 'numeric', 'Rewrite with a different time unit', 'A bacteria count doubles every 20 minutes. Let $h$ be the time in hours. The count is $N = N_0 \cdot 2^{kh}$. What is $k$?', '[]', '3', '60/20', 'There are $60 \div 20 = 3$ periods of 20 minutes in each hour, so the count doubles 3 times per hour: $N = N_0 \cdot 2^{3h}$ and $k = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 min = 1/3 h. Doubling needs kh = 1 at h = 1/3, so k = 3.","run_id":"claude-code","at":"2026-10-28T19:20:44.729Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02b30a10-2e6c-4cdf-b46f-cfd24e7a9464', 'NC17.M3.A-APR.2', 1, 'choice', 'remainder by evaluating p(a)', 'To find the remainder when $p(x)$ is divided by $x - 4$ using the Remainder Theorem, which value should you calculate?', '["$p(-4)$","$p(4)$","$p(0)$","$p(0) - 4$"]', '$p(4)$', NULL, 'The Remainder Theorem says the remainder on division by $x - a$ is $p(a)$. Here $a = 4$.', 'checked', '{"lint":[],"solve":{"answer":"$p(4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remainder on division by x-4 is p(4).","run_id":"claude-code","at":"2026-10-24T03:06:04.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0de1d1df-9a47-42db-90cf-193ed314f09c', 'NC17.M3.A-APR.2', 1, 'numeric', 'remainder by evaluating p(a)', 'Find the remainder when $x^3 + 2x - 1$ is divided by $x - 2$.', '[]', '11', '(1)*(2)^3+(2)*(2)+(-1)', 'The remainder is $p(2) = 2^3 + 2(2) - 1 = 8 + 4 - 1 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p(2)=8+4-1=11.","run_id":"claude-code","at":"2026-10-28T19:29:58.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e95c1f0-b48d-4e2c-b9b2-0cefaa7baeb0', 'NC17.M3.A-APR.2', 1, 'numeric', 'using a known factor to find the other zeros', 'Since $x - 4$ is a factor of $x^2 - 3x - 4$, the polynomial has a second zero. What is it?', '[]', '-1', '3-4', '$x^2 - 3x - 4 = (x - 4)(x + 1)$, so the second zero is $-1$. (The zeros add to 3: $4 + (-1) = 3$.)', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-3x-4=(x-4)(x+1): second zero -1.","run_id":"claude-code","at":"2026-10-28T19:29:58.706Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0261e8ba-2f80-4405-ba38-7c90480016ba', 'NC17.M3.A-APR.2', 2, 'choice', 'interpreting a remainder', 'When $p(x) = x^3 - 4x^2 + 4x - 1$ is divided by $x - 1$, the remainder is 0. What does this tell you about the graph of $y = p(x)$?', '["It meets the $y$-axis at the point $(0, 1)$","It meets the $x$-axis at the point $(-1, 0)$","It meets the $x$-axis at the point $(1, 0)$","It has its highest point at $(1, 0)$"]', 'It meets the $x$-axis at the point $(1, 0)$', NULL, 'A remainder of 0 means $p(1) = 0$, so the point $(1, 0)$ is on the graph, on the $x$-axis. (Indeed $p(1) = 1 - 4 + 4 - 1 = 0$.)', 'checked', '{"lint":[],"solve":{"answer":"It meets the $x$-axis at the point $(1, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p(1)=0 means (1,0) is an x-intercept. p''(1)=3-8+4=-1, not a turning point; p(0)=-1.","run_id":"claude-code","at":"2026-10-24T03:06:04.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1569acb1-f56c-4ae5-a603-82c383b22349', 'NC17.M3.A-APR.2', 2, 'choice', 'interpreting a remainder', 'A polynomial $p(x)$ has $p(3) = 0$, $p(-1) = 0$ and $p(0) = -6$. Which statement is true?', '["$x + 3$ and $x - 1$ are factors, but $x$ is not a factor","$x - 3$ and $x + 1$ are factors, and $x$ is a factor too","$x - 3$ is a factor, but $x + 1$ is not and $x$ is not either","$x - 3$ and $x + 1$ are factors, but $x$ is not a factor"]', '$x - 3$ and $x + 1$ are factors, but $x$ is not a factor', NULL, '$p(3) = 0$ makes $x - 3$ a factor, and $p(-1) = 0$ makes $x + 1$ a factor. Since $p(0) = -6 \ne 0$, $x$ is not a factor.', 'checked', '{"lint":[],"solve":{"answer":"$x - 3$ and $x + 1$ are factors, but $x$ is not a factor","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros 3 and -1 give factors x-3, x+1; p(0)=-6 not 0, so x is not a factor.","run_id":"claude-code","at":"2026-10-28T19:29:58.647Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c0171d3-0c75-48be-9126-a8940c445d59', 'NC17.M3.A-APR.2', 2, 'choice', 'divisor x + a or ax - b', 'Lena divides $p(x) = x^3 - 3x + 4$ by $x + 2$. She finds $p(2) = 6$ and says the remainder is 6. What is the correct remainder?', '["6","-2","2","-6"]', '2', '(-2)^3-3*(-2)+4', 'For the divisor $x + 2$ the remainder is $p(-2) = -8 + 6 + 4 = 2$. Lena used $p(2)$, which is the test for the divisor $x - 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remainder is p(-2) = -8 + 6 + 4 = 2.","run_id":"claude-code","at":"2026-10-28T19:29:58.982Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('015ebd0f-7521-4374-815b-517cc7c0745f', 'NC17.M3.A-APR.2', 3, 'choice', 'the division statement p(x) = (x - a)q(x) + r', 'A polynomial $p(x)$ leaves a remainder of 4 when divided by $x - 1$ and a remainder of $-5$ when divided by $x + 2$. When it is divided by $(x - 1)(x + 2)$, the remainder has the form $ax + b$. What is it?', '["$-3x - 2$","$-3x + 1$","$3x + 1$","$3x - 1$"]', '$3x + 1$', NULL, 'Write $p(x) = (x - 1)(x + 2)q(x) + ax + b$. At $x = 1$: $a + b = 4$. At $x = -2$: $-2a + b = -5$. Subtracting gives $3a = 9$, so $a = 3$ and $b = 1$.', 'checked', '{"lint":[],"solve":{"answer":"$3x + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p(1)=4, p(-2)=-5. a+b=4, -2a+b=-5. Subtract: 3a=9, a=3, b=1. Remainder 3x+1.","run_id":"claude-code","at":"2026-10-28T19:28:58.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0150133a-6c63-43ff-a1a0-3d885e8de182', 'NC17.M3.A-APR.2', 3, 'numeric', 'using a known factor to find the other zeros', 'The volume of a box in cubic inches is $V(x) = x^3 + 7x^2 + 14x + 8$. Its length is $x + 4$ inches, and $V(-4) = 0$. The width and height are the other two factors of $V(x)$. When $x = 2$, what is the area, in square inches, of the face formed by the width and height?', '[]', '12', '2^2+3*2+2', 'Dividing $V(x)$ by $x + 4$ gives $x^2 + 3x + 2 = (x + 1)(x + 2)$. These are the width and height, so the face has area $x^2 + 3x + 2$. At $x = 2$ this is $4 + 6 + 2 = 12$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V/(x+4) = x^2 + 3x + 2 = (x+1)(x+2). At x = 2: 3 x 4 = 12.","run_id":"claude-code","at":"2026-10-28T19:29:58.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28bc3c93-4d0f-4e3b-8fb8-0813bea0b490', 'NC17.M3.A-APR.3', 1, 'choice', 'Zeros, x-intercepts and solutions', 'The zeros of a function $f$ are the values of $x$ where', '["the input $x$ equals $0$","the output $f(x)$ equals $1$","the output $f(x)$ equals $0$","the input $x$ equals the output $f(x)$"]', 'the output $f(x)$ equals $0$', NULL, 'A zero of $f$ is an input that makes the output $0$. On the graph, these are the $x$-intercepts.', 'checked', '{"lint":[],"solve":{"answer":"the output $f(x)$ equals $0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A zero is an input where the output f(x) is 0.","run_id":"claude-code","at":"2026-10-24T03:06:27.841Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('219a9f2c-f0b8-4c0f-b609-844336eb28ef', 'NC17.M3.A-APR.3', 1, 'choice', 'Factor theorem: factors and values', 'A table shows $g(-2) = 0$, $g(0) = 6$ and $g(3) = 0$ for a polynomial $g$. Which two expressions are factors of $g(x)$?', '["$x - 2$ and $x + 3$","$x$ and $x - 6$","$x + 2$ and $x - 3$","$x + 6$ and $x$"]', '$x + 2$ and $x - 3$', NULL, 'The inputs $-2$ and 3 give 0, so they are zeros and $x + 2$ and $x - 3$ are factors. The input 0 gives 6, not 0.', 'checked', '{"lint":[],"solve":{"answer":"$x + 2$ and $x - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros at -2 and 3 give factors x+2 and x-3.","run_id":"claude-code","at":"2026-10-28T19:34:46.153Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02b8d8bc-3cab-49de-a2cf-4c0ed08838b5', 'NC17.M3.A-APR.3', 1, 'numeric', 'Count zeros and find the degree', 'How many different zeros does $f(x) = (x + 2)^3(x - 5)$ have?', '[]', '2', '2', 'The zeros are $-2$ and 5. Repeating a factor does not make a new zero, so there are 2 different zeros.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros -2 and 5: 2 different.","run_id":"claude-code","at":"2026-10-28T19:34:46.385Z"}}', 'ai', NULL, NULL)
