INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cd9984d-9ced-40d0-bddb-59c72f2d4bc8', 'NC17.M3.A-APR.3', 2, 'choice', 'Factor to find zeros', 'What are the zeros of $f(x) = 2x^2 - 8x$?', '["$0$ and $4$","$2$ and $4$","$0$ and $-4$","$0$ and $8$"]', '$0$ and $4$', NULL, 'Factor out $2x$: $2x^2-8x=2x(x-4)$. The zeros are $x=0$ and $x=4$.', 'checked', '{"lint":[],"solve":{"answer":"$0$ and $4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^2-8x=2x(x-4); zeros 0 and 4.","run_id":"claude-code","at":"2026-10-24T03:06:27.841Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d493420-d56c-4553-a8ee-006d9f64fad6', 'NC17.M3.A-APR.3', 2, 'choice', 'Factor to find zeros', 'What are all the solutions of $x^3 - 9x = 0$?', '["$0$, $3$ and $-3$","$3$ and $-3$","$0$ and $3$","$0$, $9$ and $-9$"]', '$0$, $3$ and $-3$', NULL, '$x^3 - 9x = x(x^2 - 9) = x(x - 3)(x + 3)$, so $x = 0$, $3$ or $-3$.', 'checked', '{"lint":[],"solve":{"answer":"$0$, $3$ and $-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x^2-9)=x(x-3)(x+3)=0: 0,3,-3.","run_id":"claude-code","at":"2026-10-28T19:34:46.167Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eb860fd-b80c-4685-9270-b50bdb897c95', 'NC17.M3.A-APR.3', 2, 'numeric', 'Read zeros from a factored polynomial', 'What is the product of the zeros of $f(x) = (x + 2)(x - 3)(x - 5)$?', '[]', '-30', '-2*3*5', 'The zeros are $-2$, 3 and 5. Their product is $-2 \times 3 \times 5 = -30$.', 'checked', '{"lint":[],"solve":{"answer":"-30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros are -2, 3, 5. Product = (-2)(3)(5) = -30.","run_id":"claude-code","at":"2026-10-28T19:34:46.223Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cac1e5b-4a8b-44ea-b0bd-89adc16e7bb5', 'NC17.M3.A-APR.3', 3, 'choice', 'Write a polynomial from its zeros', 'Which function has the zeros $2$, $3i$ and $-3i$?', '["$f(x) = (x - 2)(x^2 + 9)$","$f(x) = (x - 2)(x^2 - 9)$","$f(x) = (x + 2)(x^2 + 9)$","$f(x) = (x - 2)(x - 9)$"]', '$f(x) = (x - 2)(x^2 + 9)$', NULL, 'The zeros $3i$ and $-3i$ come from $x^2 + 9 = 0$, and the zero 2 comes from $x - 2$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = (x - 2)(x^2 + 9)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 + 9 = 0 gives x = +-3i; x - 2 gives 2.","run_id":"claude-code","at":"2026-10-28T19:34:46.082Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01659381-110f-45a4-9e75-491cd807b2ae', 'NC17.M3.A-APR.3', 3, 'choice', 'Count zeros and find the degree', 'What is the least possible degree of a polynomial with a zero of multiplicity 3 at $x = 0$, a zero at $x = 2$ where the graph touches the axis, and a zero at $x = -1$ where the graph crosses it?', '["3","5","6","7"]', '6', '6', 'Touching needs multiplicity at least 2 and crossing needs at least 1. The degree is at least $3 + 2 + 1 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplicity 3 at 0, touching at 2 needs even multiplicity >=2, crossing at -1 needs odd >=1: 3+2+1=6.","run_id":"claude-code","at":"2026-10-28T19:34:46.214Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cc41f6f-3ae6-4222-86d8-08e410ea9b09', 'NC17.M3.A-APR.6', 1, 'choice', 'Rewrite a linear expression over a linear expression', 'Which expression is equal to $\frac{x + 5}{x + 2}$?', '["$1 + \\frac{5}{x + 2}$","$1 + \\frac{3}{x}$","$1 + \\frac{3}{x + 2}$","$x + \\frac{3}{x + 2}$"]', '$1 + \frac{3}{x + 2}$', NULL, 'Write the numerator as the denominator plus what is left: $x + 5 = (x + 2) + 3$. Then $\frac{x + 5}{x + 2} = \frac{x + 2}{x + 2} + \frac{3}{x + 2} = 1 + \frac{3}{x + 2}$.', 'checked', '{"lint":[],"solve":{"answer":"$1 + \\frac{3}{x + 2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 5 = (x + 2) + 3: 1 + 3/(x+2).","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3695f3fc-6eb2-4c05-985a-75be705ee2ca', 'NC17.M3.A-APR.6', 1, 'numeric', 'Use the remainder as the value of the numerator', 'When $a(x)$ is divided by $x - 1$, the remainder is the value of $a(1)$. If $a(x) = x^2 + 4x + 2$, what is the remainder?', '[]', '7', '1+4+2', '$a(1) = 1^2 + 4(1) + 2 = 7$. Check by division: $x^2 + 4x + 2 = (x + 5)(x - 1) + 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a(1) = 1 + 4 + 2 = 7.","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e898483-c444-40eb-ab09-06937265f2b0', 'NC17.M3.A-APR.6', 1, 'choice', 'Rewrite an expression from a situation', 'A club pays a 300 dollar fee plus 50 dollars for each member. For $x$ members, the average cost per member is $\frac{50x + 300}{x}$ dollars. Which expression is equal to this and shows the fixed part of the cost shared among the members?', '["$\\frac{50}{x} + 300$","$300 + \\frac{50}{x}$","$50x + \\frac{300}{x}$","$50 + \\frac{300}{x}$"]', '$50 + \frac{300}{x}$', NULL, 'Split the fraction: $\frac{50x + 300}{x} = \frac{50x}{x} + \frac{300}{x} = 50 + \frac{300}{x}$. Each member pays 50 dollars plus a share of the 300 dollar fee.', 'checked', '{"lint":[],"solve":{"answer":"$50 + \\frac{300}{x}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(50x + 300)/x = 50 + 300/x.","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('191246bd-02d1-4b81-98f3-d2541c0ee6f2', 'NC17.M3.A-APR.6', 2, 'numeric', 'Rewrite a cubic expression over a linear expression', 'Dividing $x^3 - 2x^2 + x + 6$ by $x - 2$ gives a quotient $x^2 + ax + b$ and a remainder. What is $a + b$?', '[]', '1', '0+1', '$x^3 \div x = x^2$, and $x^2(x - 2) = x^3 - 2x^2$, leaving $x + 6$. The $x^2$ column left no $x^2$ term, so $a = 0$. Then $x \div x = 1$, giving $b = 1$ and a remainder of $6 - (-2) = 8$. So $a + b = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Synthetic by 2: 1, 0, 1, remainder 8. Quotient x^2 + 0x + 1: a + b = 1.","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21b1868f-410d-4601-bb86-fc614308f407', 'NC17.M3.A-APR.6', 2, 'numeric', 'Check a rewrite by combining or by testing a value', 'A student rewrites $\frac{x^2 + 3x + 5}{x + 1}$ as $x + 2 + \frac{3}{x + 1}$. To check, put $x = 2$ in the original expression. What value do you get?', '[]', '5', '(4+6+5)/3', '$\frac{2^2 + 3(2) + 5}{2 + 1} = \frac{15}{3} = 5$. The rewrite gives $2 + 2 + \frac{3}{3} = 5$ too, so the two agree at $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4 + 6 + 5)/(2 + 1) = 15/3 = 5 (and 2 + 2 + 1 = 5).","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d43be7a-8ed5-447b-90a1-9ff97e813f75', 'NC17.M3.A-APR.6', 2, 'choice', 'Check a rewrite by combining or by testing a value', 'The expression $\frac{x^2 - 4x + 7}{x - 1}$ equals $x - 3 + \frac{4}{x - 1}$ for most values of $x$. For which value of $x$ can neither expression be evaluated?', '["$x = 0$","$x = 1$","$x = -1$","$x = 4$"]', '$x = 1$', NULL, 'Both expressions have the denominator $x - 1$, which is 0 when $x = 1$. At that value neither expression has a value. For every other $x$ they are equal.', 'checked', '{"lint":[],"solve":{"answer":"$x = 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both have denominator x - 1, zero at x = 1.","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3897c6c4-91ac-4ba2-af93-4db817ce2a17', 'NC17.M3.A-APR.6', 3, 'choice', 'Rewrite a cubic expression over a linear expression', 'Which expression is equal to $\frac{x^3 + 2x^2 - x + 4}{x + 1}$?', '["$x^2 + x - 2 + \\frac{4}{x + 1}$","$x^2 + x - 2 - \\frac{6}{x + 1}$","$x^2 + x - 2 + \\frac{6}{x - 1}$","$x^2 + x - 2 + \\frac{6}{x + 1}$"]', '$x^2 + x - 2 + \frac{6}{x + 1}$', NULL, '$x^3 \div x = x^2$, leaving $x^2 - x + 4$. Then $x^2 \div x = x$, leaving $-2x + 4$. Then $-2x \div x = -2$, leaving $4 - (-2) = 6$. The result is $x^2 + x - 2 + \frac{6}{x + 1}$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 + x - 2 + \\frac{6}{x + 1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Synthetic division by -1: 1, 1, -2, remainder 4 + 2 = 6: x^2 + x - 2 + 6/(x+1).","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25ded1d4-c276-4c2b-9427-d12456878de7', 'NC17.M3.A-APR.6', 3, 'choice', 'Identify the quotient and the remainder', 'A polynomial $a(x)$ gives quotient $2x + 1$ and remainder 3 when divided by $x - 4$. Which expression is $a(x)$?', '["$2x^2 - 7x - 1$","$2x^2 - 7x - 4$","$2x^2 + 9x + 7$","$2x^2 - 7x - 7$"]', '$2x^2 - 7x - 1$', NULL, '$a(x) = (\text{quotient})(\text{divisor}) + \text{remainder} = (2x + 1)(x - 4) + 3 = 2x^2 - 7x - 4 + 3 = 2x^2 - 7x - 1$.', 'checked', '{"lint":[],"solve":{"answer":"$2x^2 - 7x - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+1)(x-4) + 3 = 2x^2 - 7x - 4 + 3 = 2x^2 - 7x - 1.","run_id":"claude-code","at":"2026-10-24T03:07:46.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06ec6903-bdae-445a-9019-15a1da668d02', 'NC17.M3.A-APR.7', 1, 'choice', 'Multiply rational expressions', 'Multiply $\frac{2}{x}\cdot\frac{3}{x+1}$. Which expression is the product?', '["$\\frac{5}{x(x+1)}$","$\\frac{6}{x(x+1)}$","$\\frac{6}{x+1}$","$\\frac{6}{2x+1}$"]', '$\frac{6}{x(x+1)}$', NULL, 'Multiply the numerators and multiply the denominators: $\frac{2 \cdot 3}{x(x+1)}=\frac{6}{x(x+1)}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6}{x(x+1)}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply numerators and denominators: 6/(x(x+1)).","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04130538-d3b0-42b4-9caa-0d1f9d38fa1b', 'NC17.M3.A-APR.7', 1, 'choice', 'Add or subtract with like denominators', 'Which expression equals $\frac{5}{x+2}+\frac{3}{x+2}$?', '["$\\frac{8}{2x+4}$","$\\frac{15}{x+2}$","$\\frac{8}{(x+2)^2}$","$\\frac{8}{x+2}$"]', '$\frac{8}{x+2}$', NULL, 'The denominators are the same, so add the numerators and keep the denominator: $\frac{5+3}{x+2}=\frac{8}{x+2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{8}{x+2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same denominator: (5+3)/(x+2)=8/(x+2). 8/(2x+4)=4/(x+2), not equal.","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1807a384-fe79-43bb-b459-601223238c12', 'NC17.M3.A-APR.7', 1, 'choice', 'Least common denominator', 'What is the least common denominator of $\frac{1}{x+1}$ and $\frac{1}{x+3}$?', '["$(x+1)(x+3)$","$x+4$","$x+3$","$2x+4$"]', '$(x+1)(x+3)$', NULL, 'The two denominators share no factor, so the least common denominator is their product, $(x+1)(x+3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(x+1)(x+3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distinct linear factors: LCD (x+1)(x+3).","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13511b9a-f4d6-492b-b331-0555e8957213', 'NC17.M3.A-APR.7', 2, 'choice', 'Add or subtract with unlike linear denominators', 'What is the sum $\frac{1}{x+1}+\frac{1}{x+2}$ written as one fraction?', '["$\\frac{2}{2x+3}$","$\\frac{2}{(x+1)(x+2)}$","$\\frac{2x+3}{(x+1)(x+2)}$","$\\frac{2x+3}{x+3}$"]', '$\frac{2x+3}{(x+1)(x+2)}$', NULL, 'Use the common denominator $(x+1)(x+2)$: $\frac{x+2}{(x+1)(x+2)}+\frac{x+1}{(x+1)(x+2)}=\frac{2x+3}{(x+1)(x+2)}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2x+3}{(x+1)(x+2)}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"((x+2)+(x+1))/((x+1)(x+2)) = (2x+3)/((x+1)(x+2)).","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09eacbac-db54-4518-a3ed-51bd6e59fcc2', 'NC17.M3.A-APR.7', 2, 'choice', 'Multiply rational expressions', 'Which expression equals $\frac{x^2-9}{x}\cdot\frac{x}{x+3}$, for $x\ne 0$ and $x\ne -3$?', '["$x-3$","$x+3$","$\\frac{x-3}{x}$","$x^2-3$"]', '$x-3$', NULL, 'Factor $x^2-9=(x-3)(x+3)$. The factors $x$ and $x+3$ cancel, leaving $x-3$.', 'checked', '{"lint":[],"solve":{"answer":"$x-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)(x+3)/x * x/(x+3) = x-3.","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c4bffbe-a470-45d8-af21-4ad9a91ae49e', 'NC17.M3.A-APR.7', 2, 'numeric', 'Rational expressions in context', 'A boat travels 24 miles upstream at $x-2$ miles per hour and 24 miles downstream at $x+2$ miles per hour. The total time is $\frac{24}{x-2}+\frac{24}{x+2}$ hours. What is the total time, in hours, when $x=10$?', '[]', '5', '24/8+24/12', 'Substitute $x=10$: $\frac{24}{8}+\frac{24}{12}=3+2=5$ hours.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24/8 + 24/12 = 3+2 = 5.","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0345914a-2129-4270-803f-a3fc160bb798', 'NC17.M3.A-APR.7', 3, 'choice', 'Spot an invalid step', 'Which statement is true for all values of $x$ that make both sides defined?', '["$\\frac{x+2}{x+3}=\\frac{2}{3}$","$\\frac{x^2+1}{x^2+3}=\\frac{1}{3}$","$\\frac{2(x+1)}{2(x+3)}=\\frac{x+1}{x+3}$","$\\frac{x+5}{x}=5$"]', '$\frac{2(x+1)}{2(x+3)}=\frac{x+1}{x+3}$', NULL, 'Only a common factor of the whole numerator and whole denominator can be cancelled, and 2 is one in the first statement. In the others, cancelling terms is invalid: for example, $\frac{x+5}{x}=1+\frac{5}{x}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2(x+1)}{2(x+3)}=\\frac{x+1}{x+3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x+1)/(2(x+3)) = (x+1)/(x+3) wherever defined; the others fail e.g. at x=1.","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01c7afec-fb54-4668-b782-7ca246dffd44', 'NC17.M3.A-APR.7', 3, 'choice', 'Rational expressions in context', 'Pipe A can fill a tank in $x$ minutes, and pipe B can drain the full tank in $x+5$ minutes. Which expression gives the fraction of the tank filled per minute when both are open?', '["$\\frac{1}{x}+\\frac{1}{x+5}$","$\\frac{1}{x}-\\frac{1}{x+5}$","$\\frac{1}{x-(x+5)}$","$\\frac{1}{x}\\cdot\\frac{1}{x+5}$"]', '$\frac{1}{x}-\frac{1}{x+5}$', NULL, 'Pipe A fills $\frac{1}{x}$ of the tank per minute and pipe B removes $\frac{1}{x+5}$ per minute, so the net rate is $\frac{1}{x}-\frac{1}{x+5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{x}-\\frac{1}{x+5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fill rate 1/x minus drain rate 1/(x+5).","run_id":"claude-code","at":"2026-10-24T03:07:50.630Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('311c1704-56de-436f-989b-8c92345a31d1', 'NC17.M3.A-CED.1', 1, 'numeric', 'solve an absolute value equation', 'Solve $|x - 3| = 5$. What is the larger solution?', '[]', '8', '3+5', '$x - 3 = 5$ gives $x = 8$, and $x - 3 = -5$ gives $x = -2$. The larger solution is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-3=5 gives x=8; x-3=-5 gives x=-2. Larger is 8.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
