INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33fd5e6a-4065-4cfc-b8b4-3c4623554b29', 'NC17.M3.A-CED.1', 1, 'numeric', 'solve an exponential equation', 'What value of $x$ makes $2^x = 32$ true?', '[]', '5', NULL, '$2^5 = 2 \times 2 \times 2 \times 2 \times 2 = 32$, so $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32=2^5, so x=5.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
