INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b5aa378-33c6-4594-a404-111d6e49d0c6', 'NC17.M3.A-CED.1', 1, 'choice', 'solve an absolute value inequality', 'Which describes all the solutions of $|x| < 3$?', '["$x < -3$ or $x > 3$","$x < 3$","$x > -3$","$-3 < x < 3$"]', '$-3 < x < 3$', NULL, '$|x| < 3$ means $x$ is less than 3 units from 0, so $x$ is between $-3$ and $3$.', 'checked', '{"lint":[],"solve":{"answer":"$-3 < x < 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|x|<3 means distance from 0 less than 3: -3<x<3.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('082d7c43-e1fc-4d31-ab70-f7ea50d30e46', 'NC17.M3.A-CED.1', 2, 'choice', 'write an exponential equation', 'A car is worth 24,000 dollars and loses 15% of its value each year. Which equation can be solved to find the number of years $t$ until it is worth 12,000 dollars?', '["$24{,}000(0.15)^t = 12{,}000$","$24{,}000(1.15)^t = 12{,}000$","$24{,}000 - 0.15t = 12{,}000$","$24{,}000(0.85)^t = 12{,}000$"]', '$24{,}000(0.85)^t = 12{,}000$', NULL, 'Losing 15% leaves 85% of the value each year, so the value after $t$ years is $24{,}000(0.85)^t$. Set it equal to 12,000.', 'checked', '{"lint":[],"solve":{"answer":"$24{,}000(0.85)^t = 12{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Keeps 85% each year: 24000(0.85)^t=12000.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26df96eb-6773-48fa-b405-82d498acf089', 'NC17.M3.A-CED.1', 2, 'numeric', 'write and solve a rational equation from a situation', 'Anna can paint a fence in 6 hours and Ben can paint the same fence in 4 hours. How many hours does it take them to paint it together? Give your answer as a fraction or a decimal.', '[]', '12/5', '1/(1/6+1/4)', 'In one hour Anna paints $\frac{1}{6}$ of the fence and Ben paints $\frac{1}{4}$. Together, in $t$ hours, $\frac{t}{6} + \frac{t}{4} = 1$. Multiply by 12: $2t + 3t = 12$, so $t = \frac{12}{5} = 2.4$ hours.', 'checked', '{"lint":[],"solve":{"answer":"12/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rates 1/6+1/4=5/12 fence per hour; time 12/5=2.4 hours.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('599fafa4-968f-4273-9f4b-6ffaf1c3a3a4', 'NC17.M3.A-CED.1', 2, 'choice', 'solve an equation using a table of values', 'For $x = -1, 0, 1, 2, 3$, the values of $f(x) = x^2$ are $1, 0, 1, 4, 9$ and the values of $g(x) = 2x + 3$ are $1, 3, 5, 7, 9$. Which of these values of $x$ are solutions of $x^2 = 2x + 3$?', '["$x = 3$ only","$x = 1$ and $x = 9$","$x = -1$ and $x = 3$","$x = -1$ and $x = 1$"]', '$x = -1$ and $x = 3$', NULL, 'A solution is an $x$-value where $f(x) = g(x)$. The two rows match at $x = -1$ (both 1) and at $x = 3$ (both 9).', 'checked', '{"lint":[],"solve":{"answer":"$x = -1$ and $x = 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal values at x=-1 (1=1) and x=3 (9=9). Algebra: x^2-2x-3=(x-3)(x+1)=0.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23119b72-604e-40b7-b236-a28e3b4f20a6', 'NC17.M3.A-CED.1', 3, 'choice', 'solve a polynomial inequality from a situation', 'A company''s profit, in thousands of dollars, is $P(x) = -x^2 + 10x - 16$, where $x$ is the number of hundreds of items sold. For which values of $x$ is the profit positive?', '["$x < 2$ or $x > 8$","$x > 2$","$-2 < x < 8$","$2 < x < 8$"]', '$2 < x < 8$', NULL, 'Solve $-x^2 + 10x - 16 > 0$, which is $x^2 - 10x + 16 < 0$, or $(x - 2)(x - 8) < 0$. The product is negative between the zeros, so $2 < x < 8$.', 'checked', '{"lint":[],"solve":{"answer":"$2 < x < 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-x^2+10x-16>0 iff x^2-10x+16<0 iff (x-2)(x-8)<0 iff 2<x<8.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42c9b11f-6aa8-4f21-90e4-d06585660c7f', 'NC17.M3.A-CED.1', 3, 'numeric', 'write and solve a polynomial equation from a situation', 'The product of three consecutive positive integers is 60. What is the smallest of the three integers?', '[]', '3', '3', 'Let the integers be $n$, $n + 1$, $n + 2$ with $n(n + 1)(n + 2) = 60$. Trying $n = 3$ gives $3 \times 4 \times 5 = 60$. The product grows as $n$ grows, so no other positive integer works. The smallest is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n(n+1)(n+2)=60; 3*4*5=60; function increasing for positive n, so unique. Smallest 3.","run_id":"claude-code","at":"2026-10-24T03:12:37.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f87b923-e75d-4602-9188-102c0fecf449', 'NC17.M3.A-CED.2', 1, 'numeric', 'Exponential: evaluate and read an equation', 'For $y = 3(2)^x$, what is $y$ when $x = 4$?', '[]', '48', '3*2^4', '$3 \cdot 2^4 = 3 \cdot 16 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*16=48.","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
