INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ef7d3e0-f6e7-418d-a445-d655bd77ae93', 'NC17.M3.A-CED.2', 1, 'numeric', 'Polynomial: evaluate and read an equation', 'What is the $y$-intercept of $y = (x - 2)(x + 3)$?', '[]', '-6', '(0-2)*(0+3)', 'The $y$-intercept is the value at $x = 0$: $(0 - 2)(0 + 3) = (-2)(3) = -6$.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=0: (-2)(3)=-6.","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
