INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca42fbb-d0c4-461e-b3ca-1938702ba6ca', 'NC17.M3.A-CED.2', 1, 'numeric', 'Absolute value: read an equation or graph', 'The graph of $y = |x + 4| - 3$ is a V. What is the $x$-coordinate of its vertex?', '[]', '-4', '0-4', 'In $y = |x - h| + k$ the vertex is $(h, k)$. Here $x + 4 = x - (-4)$, so $h = -4$ and the vertex is $(-4, -3)$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex at x=-4.","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24a226f2-58ec-429f-aaf7-443815875fff', 'NC17.M3.A-CED.2', 2, 'numeric', 'Exponential: evaluate and read an equation', 'A car worth 20,000 dollars loses 10% of its value each year, so $y = 20000(0.9)^x$ gives its value after $x$ years. What is its value in dollars after 2 years?', '[]', '16200', '20000*0.9^2', '$20000(0.9)^2 = 20000(0.81) = 16200$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"16200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20000*0.81=16200.","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('092107f9-ba29-41fc-922c-4cf7a985876a', 'NC17.M3.A-CED.2', 2, 'choice', 'Polynomial: write an equation', 'Which cubic equation has zeros at $x = -1$, $x = 2$ and $x = 4$?', '["$y = (x - 1)(x + 2)(x + 4)$","$y = (x + 1)(x - 2)(x - 4)$","$y = (x + 1)(x - 2)(x + 4)$","$y = (x - 1)(x + 2)(x - 4)$"]', '$y = (x + 1)(x - 2)(x - 4)$', NULL, 'Each zero $r$ comes from a factor $(x - r)$. For $-1$ the factor is $(x + 1)$, for 2 it is $(x - 2)$, and for 4 it is $(x - 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$y = (x + 1)(x - 2)(x - 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors (x+1)(x-2)(x-4).","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1027d725-59d5-419b-8575-55e2d2a5916b', 'NC17.M3.A-CED.2', 2, 'choice', 'Exponential: write an equation', 'A sample of 800 milligrams of a substance loses half of its mass every 5 days. Which equation gives the mass $y$ after $x$ days?', '["$y = 800\\left(\\frac{1}{2}\\right)^{x/5}$","$y = 800\\left(\\frac{1}{2}\\right)^{5x}$","$y = 800\\left(\\frac{1}{5}\\right)^{x/2}$","$y = 800 - \\frac{1}{2}x$"]', '$y = 800\left(\frac{1}{2}\right)^{x/5}$', NULL, 'The mass is multiplied by $\frac{1}{2}$ once every 5 days, so the exponent counts groups of 5 days: $\frac{x}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 800\\left(\\frac{1}{2}\\right)^{x/5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half-lives elapsed x/5: 800(1/2)^(x/5).","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b5a226-cc1b-4d31-9702-5b6753ef2b77', 'NC17.M3.A-CED.2', 3, 'numeric', 'Absolute value: read an equation or graph', 'For $y = |2x - 8|$, two values of $x$ give $y = 6$. What is the larger one?', '[]', '7', '(8+6)/2', 'Set $|2x - 8| = 6$. Then $2x - 8 = 6$ or $2x - 8 = -6$, so $x = 7$ or $x = 1$. The larger is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x-8=6 gives 7; 2x-8=-6 gives 1. Larger 7.","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e381fa4-6a7e-490f-b29c-131fb9a492ae', 'NC17.M3.A-CED.2', 3, 'numeric', 'Rational: read asymptotes and intercepts', 'What is the $x$-intercept of $y = \frac{4}{x + 2} - 1$?', '[]', '2', '4-2', 'Set $y = 0$: $\frac{4}{x + 2} = 1$, so $x + 2 = 4$ and $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/(x+2)=1, x+2=4, x=2.","run_id":"claude-code","at":"2026-10-24T03:12:28.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('557b752a-bb29-49ac-93a4-da37eb4b6a09', 'NC17.M3.A-CED.3', 1, 'choice', 'Write a system of linear equations', 'A school sells adult tickets for 8 dollars and student tickets for 5 dollars. In all, 120 tickets were sold for 780 dollars. Let $a$ be the number of adult tickets and $s$ the number of student tickets. Which system models this?', '["$a + s = 120$ and $5a + 8s = 780$","$a + s = 780$ and $8a + 5s = 120$","$a + s = 120$ and $8a + 5s = 780$","$a + s = 120$ and $8a - 5s = 780$"]', '$a + s = 120$ and $8a + 5s = 780$', NULL, 'The number of tickets gives $a + s = 120$. The money gives $8a + 5s = 780$, since adult tickets cost 8 dollars and student tickets cost 5 dollars.', 'checked', '{"lint":[],"solve":{"answer":"$a + s = 120$ and $8a + 5s = 780$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count: a+s=120. Money: 8a+5s=780.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('493ea5ba-370e-4e30-91c2-a5ea0c279a3f', 'NC17.M3.A-CED.3', 1, 'choice', 'Write a system of linear inequalities', 'A baker has at most 50 pounds of flour. A loaf uses 2 pounds and a cake uses 3 pounds. Let $x$ be the number of loaves and $y$ the number of cakes. Which system models the situation?', '["$2x + 3y \\le 50$, $x \\ge 0$, $y \\ge 0$","$2x + 3y \\ge 50$, $x \\ge 0$, $y \\ge 0$","$3x + 2y \\le 50$, $x \\ge 0$, $y \\ge 0$","$2x + 3y \\le 50$, $x \\le 0$, $y \\le 0$"]', '$2x + 3y \le 50$, $x \ge 0$, $y \ge 0$', NULL, 'The flour used is $2x + 3y$, and it must be at most 50. A baker cannot make a negative number of loaves or cakes, so $x \ge 0$ and $y \ge 0$.', 'checked', '{"lint":[],"solve":{"answer":"$2x + 3y \\le 50$, $x \\ge 0$, $y \\ge 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Flour 2x+3y<=50, counts nonnegative.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bf392f9-f990-4292-b2d1-1ec96d6c9591', 'NC17.M3.A-CED.3', 1, 'numeric', 'Break-even and equal-cost systems', 'Phone plan A costs $y = 5x + 20$ dollars for $x$ months. Phone plan B costs $y = 3x + 30$ dollars. After how many months do the two plans cost the same?', '[]', '5', '(30-20)/(5-3)', 'Set the costs equal: $5x + 20 = 3x + 30$. Then $2x = 10$, so $x = 5$ months.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x+20=3x+30, 2x=10, x=5.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3319ef6d-e8b6-4939-a3e0-3677fe98d25e', 'NC17.M3.A-CED.3', 2, 'numeric', 'Break-even and equal-cost systems', 'A craft business has cost $C = 8x + 300$ and revenue $R = 20x$ dollars when it sells $x$ items. How many items must it sell for revenue to equal cost?', '[]', '25', '300/(20-8)', 'Set $20x = 8x + 300$. Then $12x = 300$, so $x = 25$ items.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20x=8x+300, 12x=300, x=25.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0122d6b8-0e14-4c17-919d-c8fd056ed4d2', 'NC17.M3.A-CED.3', 2, 'choice', 'Meaning of a part of the model in context', 'Solving a system for a company that rents $b$ buses and $v$ vans gives $b = 2.5$ and $v = 4$. Why can this not be used as the real answer?', '["The number of vans must be greater than the number of buses.","A company cannot rent buses and vans at the same time.","Every solution of a system must be a positive whole number.","The number of buses must be a whole number."]', 'The number of buses must be a whole number.', NULL, 'A company cannot rent half a bus, so the model needs a whole number of buses. A solution has to make sense in the situation, not only satisfy the equations.', 'checked', '{"lint":[],"solve":{"answer":"The number of buses must be a whole number.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half a bus cannot be rented; b must be a whole number.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('347d6a91-d908-463f-9c6c-9f874b8364f2', 'NC17.M3.A-CED.3', 2, 'numeric', 'Use an inequality constraint', 'Boxes must satisfy $x + y \le 12$ and $10x + 4y \le 100$, where $x$ is the number of large boxes and $y$ the number of small boxes. If $x = 6$, what is the greatest whole number of small boxes $y$ allowed?', '[]', '6', '12-6', 'With $x = 6$: the first rule gives $y \le 6$. The second gives $60 + 4y \le 100$, so $y \le 10$. Both must hold, so the greatest is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=6: y<=6 and 60+4y<=100 so y<=10; greatest is 6.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1089f146-a58f-4d5a-baca-08b4b2504eae', 'NC17.M3.A-CED.3', 3, 'choice', 'Write a system of linear inequalities', 'A student must buy at least 10 items and has at most 60 dollars. Notebooks ($n$) cost 3 dollars and binders ($b$) cost 7 dollars. Which system models this?', '["$n + b \\le 10$ and $3n + 7b \\ge 60$","$n + b \\ge 10$ and $7n + 3b \\le 60$","$n + b \\ge 10$ and $3n + 7b \\le 60$","$n + b \\ge 10$ and $3n + 7b \\ge 60$"]', '$n + b \ge 10$ and $3n + 7b \le 60$', NULL, 'At least 10 items: $n + b \ge 10$. The cost is $3n + 7b$, and it must be at most 60: $3n + 7b \le 60$.', 'checked', '{"lint":[],"solve":{"answer":"$n + b \\ge 10$ and $3n + 7b \\le 60$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Items n+b>=10; cost 3n+7b<=60.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0504b5cd-2012-4431-97b9-153f24ac11be', 'NC17.M3.A-CED.3', 3, 'choice', 'Write a system of linear inequalities', 'A van holds at most 8 people. At least 2 of them must be adults, and the number of children is at most 3 times the number of adults. With $a$ adults and $c$ children, which system models this?', '["$a + c \\ge 8$, $a \\ge 2$ and $c \\le 3a$","$a + c \\le 8$, $a \\ge 2$ and $c \\le 3a$","$a + c \\le 8$, $a \\le 2$ and $c \\le 3a$","$a + c \\le 8$, $a \\ge 2$ and $a \\le 3c$"]', '$a + c \le 8$, $a \ge 2$ and $c \le 3a$', NULL, 'At most 8 people: $a + c \le 8$. At least 2 adults: $a \ge 2$. Children are at most 3 times the adults: $c \le 3a$.', 'checked', '{"lint":[],"solve":{"answer":"$a + c \\le 8$, $a \\ge 2$ and $c \\le 3a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a+c<=8, a>=2, c<=3a.","run_id":"claude-code","at":"2026-10-24T03:15:22.258Z"}}', 'ai', NULL, NULL)
