INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('048522ae-1f84-44ef-b3f1-fdbd8879f45b', 'NC17.M3.A-REI.11', 3, 'numeric', 'Read solutions from intersection points', 'The equation $f(x) = g(x)$ has exactly two solutions, and the graphs cross at $(-3, 2)$. The sum of the two solutions is 5. What is the other solution?', '[]', '8', '5-(-3)', 'One solution is the x-coordinate $-3$. The other is $5 - (-3) = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One solution is x = -3. Other = 5 - (-3) = 8.","run_id":"claude-code","at":"2026-10-24T08:22:22.644Z"}}', 'ai', NULL, NULL)
