INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('071ed8e8-fd28-45c1-a31f-136190c5e489', 'NC17.M3.A-REI.11', 3, 'numeric', 'Count solutions from the intersections', 'The graph of $y = f(x)$ crosses the graph of $y = g(x)$ exactly once between each two neighboring whole numbers from 0 to 5, and nowhere else. How many solutions does $f(x) = g(x)$ have?', '[]', '5', NULL, 'The neighboring pairs from 0 to 5 are 0-1, 1-2, 2-3, 3-4 and 4-5. That is 5 pairs, with one crossing in each, so 5 solutions.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intervals 0-1, 1-2, 2-3, 3-4, 4-5: five crossings, nowhere else, so 5 solutions.","run_id":"claude-code","at":"2026-10-24T08:22:22.644Z"}}', 'ai', NULL, NULL)
