VALUES ('64d2f3fb-f406-477f-a088-874eb5ea4b08', 'NC17.M3.F-IF.1', 1, 'numeric', 'Evaluate a trigonometric function at an angle', 'What is $\sin 30^\circ$?', '[]', '1/2', '1/2', 'From the special right triangle with angles $30^\circ$, $60^\circ$ and $90^\circ$, $\sin 30^\circ = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin 30 = 1/2.","run_id":"claude-code","at":"2026-10-24T08:26:47.520Z"}}', 'ai', NULL, NULL)
