INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48ec122b-8595-4ea1-a49d-3abb14b7ee36', 'NC17.M3.F-IF.1', 2, 'choice', 'How a trigonometric function changes with the angle', 'A student finds $\cos 20^\circ \approx 0.94$, $\cos 50^\circ \approx 0.64$ and $\cos 80^\circ \approx 0.17$. Which statement about acute angles does this pattern support?', '["The larger the angle, the larger its cosine.","The cosine is the same for every angle.","The larger the angle, the smaller its cosine.","The cosine is always more than 1."]', 'The larger the angle, the smaller its cosine.', NULL, 'The angles go up from $20^\circ$ to $80^\circ$ while the cosines go down from $0.94$ to $0.17$. So the cosine gets smaller as the angle gets larger.', 'checked', '{"lint":[],"solve":{"answer":"The larger the angle, the smaller its cosine.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.94, 0.64, 0.17 decrease as angle grows.","run_id":"claude-code","at":"2026-10-24T08:26:47.520Z"}}', 'ai', NULL, NULL)
