INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d09200-4467-4faa-8abc-ad171659d051', 'NC17.M3.F-IF.1', 3, 'choice', 'Evaluate a trigonometric function at an angle', 'Which list of pairs (angle, value) belongs to the function $f(\theta) = \cos \theta$?', '["$(0^\\circ, 0)$, $\\left(60^\\circ, \\frac{1}{2}\\right)$, $(90^\\circ, 1)$","$(0^\\circ, 1)$, $(60^\\circ, 1)$, $(90^\\circ, 0)$","$(0^\\circ, 0)$, $(60^\\circ, 1)$, $\\left(90^\\circ, \\frac{1}{2}\\right)$","$(0^\\circ, 1)$, $\\left(60^\\circ, \\frac{1}{2}\\right)$, $(90^\\circ, 0)$"]', '$(0^\circ, 1)$, $\left(60^\circ, \frac{1}{2}\right)$, $(90^\circ, 0)$', NULL, '$\cos 0^\circ = 1$, $\cos 60^\circ = \frac{1}{2}$ and $\cos 90^\circ = 0$. The other lists have a wrong value or swap the sine and cosine values.', 'checked', '{"lint":[],"solve":{"answer":"$(0^\\circ, 1)$, $\\left(60^\\circ, \\frac{1}{2}\\right)$, $(90^\\circ, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"cos0=1, cos60=1/2, cos90=0.","run_id":"claude-code","at":"2026-10-24T08:26:47.520Z"}}', 'ai', NULL, NULL)
