INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('017e4f93-cea2-406c-8524-ae988c115423', 'NC17.M3.F-IF.1', 3, 'numeric', 'Function notation with trigonometric ratios', 'Let $f(\theta) = 4\cos \theta - 1$. Find $f(60^\circ)$.', '[]', '1', '4*1/2-1', '$f(60^\circ) = 4 \cdot \frac{1}{2} - 1 = 2 - 1 = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*(1/2)-1 = 1.","run_id":"claude-code","at":"2026-10-24T08:26:47.520Z"}}', 'ai', NULL, NULL)
