INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c27b195-9d01-4c92-a091-b76b380497c7', 'NC17.M3.F-IF.2', 1, 'numeric', 'Evaluate a piecewise function at a value', 'A function is defined by $p(x) = x + 4$ if $x < 1$, and $p(x) = 7$ if $x \ge 1$. Find $p(-3)$.', '[]', '1', '-3+4', 'Since $-3 < 1$, use the rule $p(x) = x + 4$. Then $p(-3) = -3 + 4 = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3<1: -3+4=1.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
