INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15febafb-cd87-4fde-a40e-4db04e9ed5c1', 'NC17.M3.F-IF.2', 1, 'choice', 'Evaluate a piecewise function at a value', 'A function is defined by $f(x) = x^2 + 1$ if $x < -1$, $f(x) = 3x$ if $-1 \le x < 2$, $f(x) = 8$ if $2 \le x < 6$, and $f(x) = 20 - x$ if $x \ge 6$. Which rule do you use to find $f(5)$?', '["$f(x) = 8$","$f(x) = 3x$","$f(x) = x^2 + 1$","$f(x) = 20 - x$"]', '$f(x) = 8$', NULL, 'Check where 5 falls. It is at least 2 and less than 6, so use $f(x) = 8$. Then $f(5) = 8$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2<=5<6: f(x)=8.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
