INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d5f6a81-b41d-4196-bd11-3d89478b6beb', 'NC17.M3.F-IF.2', 1, 'numeric', 'Evaluate a piecewise function in context', 'Shipping a package of $w$ pounds costs $S(w)$ dollars, where $S(w) = 6$ if $w \le 3$, and $S(w) = 2w$ if $w > 3$. Find $S(8)$, the cost in dollars of shipping an 8-pound package.', '[]', '16', '2*8', 'Since $8 > 3$, use $S(w) = 2w$. Then $S(8) = 2(8) = 16$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8>3: 2*8=16.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
