INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83a22c17-6194-40dd-be9f-4c15cd4451b8', 'NC17.M3.F-IF.2', 2, 'numeric', 'Evaluate a piecewise function in context', 'A worker is paid $P(h)$ dollars for working $h$ hours in a week, where $P(h) = 12h$ if $0 \le h \le 40$, and $P(h) = 480 + 18(h - 40)$ if $h > 40$. How many dollars is the worker paid for 45 hours?', '[]', '570', '480+18*(45-40)', 'Since $45 > 40$, use $P(h) = 480 + 18(h - 40)$. Then $P(45) = 480 + 18(5) = 570$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"570","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45>40: 480+18*5=570.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
