INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40b12782-82ff-434b-a048-ac17e548e261', 'NC17.M3.F-IF.2', 2, 'choice', 'Combine or nest piecewise values', 'A function is defined by $w(x) = -2x$ if $x < 0$, and $w(x) = x + 3$ if $x \ge 0$. Which statement is true?', '["$w(-4) > w(2)$","$w(0) > w(2)$","$w(-1) = w(0)$","$w(2) > w(-1) + 4$"]', '$w(-4) > w(2)$', NULL, '$w(-4) = -2(-4) = 8$, $w(2) = 2 + 3 = 5$, $w(0) = 3$, $w(-1) = 2$. Only $8 > 5$ is true, so $w(-4) > w(2)$.', 'checked', '{"lint":[],"solve":{"answer":"$w(-4) > w(2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w(2)=5, w(-1)=2, w(0)=3, w(-4)=8. Only w(-4)>w(2) (8>5) true; 5>6, 2=3, 3>5 false.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67685493-97a6-4427-b693-4ee61f04afb2', 'NC17.M3.F-IF.2', 2, 'numeric', 'Combine or nest piecewise values', 'A function is defined by $k(x) = x + 6$ if $x < 2$, and $k(x) = 2x$ if $x \ge 2$. Find $k(k(-1))$.', '[]', '10', '2*(-1+6)', 'First, $k(-1) = -1 + 6 = 5$. Then $k(5)$ uses the second rule: $2(5) = 10$. So $k(k(-1)) = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k(-1)=-1+6=5; k(5)=2*5=10.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
