INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0972ccd9-b90b-47e3-8943-a9a573b66386', 'NC17.M3.F-IF.2', 3, 'numeric', 'Combine or nest piecewise values', 'A function is defined by $g(x) = 3 - x$ if $x \le -1$, and $g(x) = x^2$ if $-1 < x < 3$, and $g(x) = 2x + 3$ if $x \ge 3$. Find $g(-4) - g(2) + g(3)$.', '[]', '12', '(3-(-4))-2^2+(2*3+3)', '$g(-4) = 3 - (-4) = 7$. $g(2) = 2^2 = 4$. $g(3) = 2(3) + 3 = 9$, since $x = 3$ is in the third rule. Then $7 - 4 + 9 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(-4)=3+4=7; g(2)=4; g(3)=9. 7-4+9=12.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
