INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23a2c241-cc58-46e9-8dbd-b333806106ac', 'NC17.M3.F-IF.2', 3, 'numeric', 'Combine or nest piecewise values', 'A function is defined by $f(x) = 2^x$ if $x \le 3$, and $f(x) = 20 - x$ if $x > 3$. Find $f(3) + f(5)$.', '[]', '23', '2^3+(20-5)', '$f(3)$ uses the first rule because $x = 3$ is included: $2^3 = 8$. $f(5)$ uses the second rule: $20 - 5 = 15$. The sum is $8 + 15 = 23$.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(3)=2^3=8; f(5)=15; sum 23.","run_id":"claude-code","at":"2026-10-24T08:26:47.556Z"}}', 'ai', NULL, NULL)
