INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71428c12-1e6b-4068-9c75-338dde14094f', 'NC17.M3.F-IF.4', 1, 'numeric', 'Midline, amplitude, maximum and minimum', 'A rider on a Ferris wheel is at least 2 meters and at most 30 meters above the ground. What is the height, in meters, of the midline of the rider''s height?', '[]', '16', '(2+30)/2', 'The midline is halfway between the minimum and the maximum: $(2 + 30) \div 2 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midline = (max+min)/2 = (30+2)/2 = 16.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
