INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('771becb5-ed8a-43fa-9349-ba14ebd36406', 'NC17.M3.F-IF.4', 1, 'choice', 'Identify a type of discontinuity', 'The graph of $f$ has a break at $x = 2$. Just to the left of 2 the graph is at $y = 1$. At $x = 2$ and just to the right it is at $y = 4$. What kind of discontinuity is this?', '["a jump discontinuity","a removable discontinuity","a vertical asymptote","no discontinuity"]', 'a jump discontinuity', NULL, 'The graph suddenly moves from one level to another at $x = 2$, with no missing point and no unbounded values. That is a jump discontinuity.', 'checked', '{"lint":[],"solve":{"answer":"a jump discontinuity","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left side approaches 1, value and right side at 4: the graph jumps from one level to another, a jump discontinuity.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b9f1c72-9306-4799-8de9-2cb36f5f5aa6', 'NC17.M3.F-IF.4', 1, 'numeric', 'Find the period of a periodic function', 'A rotating light repeats the same flashing pattern every 0.5 seconds. How many full patterns happen in 3 seconds?', '[]', '6', '3/0.5', 'Each full pattern takes 0.5 seconds. In 3 seconds there are $3 \div 0.5 = 6$ full patterns.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 / 0.5 = 6 full patterns.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
