INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1335046a-499b-49b9-a537-96691682161e', 'NC17.M3.F-IF.4', 2, 'choice', 'Use periodicity to find a value', 'A function $f$ is periodic with period 4. It has $f(0) = 3$, $f(1) = 6$, $f(2) = 9$ and $f(3) = 6$. What is $f(10)$?', '["3","6","9","12"]', '9', NULL, '10 is 8 more than 2, and 8 is 2 full periods. So $f(10) = f(2) = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 = 2 + 2*4, f(10) = f(2) = 9.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5adf08ef-da60-4e70-b0e6-d301e7439fa0', 'NC17.M3.F-IF.4', 2, 'numeric', 'Midline, amplitude, maximum and minimum', 'The height of a swing is modeled with a maximum of 2.4 meters and an amplitude of 0.9 meters. What is the minimum height, in meters?', '[]', '0.6', '2.4-2*0.9', 'The maximum and minimum are 2 amplitudes apart: $2 \times 0.9 = 1.8$. The minimum is $2.4 - 1.8 = 0.6$.', 'checked', '{"lint":[],"solve":{"answer":"0.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Min = max - 2*amplitude = 2.4 - 1.8 = 0.6.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
