INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3260d782-f147-4414-922c-3a3b5fb2cefb', 'NC17.M3.F-IF.4', 2, 'choice', 'Read key features from a table', 'A table gives $x = 0, 1, 2, 3, 4$ and $f(x) = -3, 0, 1, 0, -3$. On which interval do the values of $f$ in the table only increase?', '["from $x = 2$ to $x = 4$","from $x = 1$ to $x = 3$","from $x = 0$ to $x = 2$","from $x = 0$ to $x = 4$"]', 'from $x = 0$ to $x = 2$', NULL, 'From $x = 0$ to $x = 2$ the values go $-3, 0, 1$, which only increase. After $x = 2$ they decrease.', 'checked', '{"lint":[],"solve":{"answer":"from $x = 0$ to $x = 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f: -3, 0, 1 for x = 0,1,2 is increasing; then decreases.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
