INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3084cd98-4c4d-432e-8c05-eabb74481d35', 'NC17.M3.F-IF.4', 3, 'numeric', 'Find the period of a periodic function', 'A periodic function has a minimum at $x = 1.5$, and its next minimum is at $x = 5.25$, with no minimum in between. What is the period?', '[]', '3.75', '5.25-1.5', 'The period is the distance between consecutive minimums: $5.25 - 1.5 = 3.75$.', 'checked', '{"lint":[],"solve":{"answer":"3.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Consecutive minima: 5.25 - 1.5 = 3.75.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('101f94e4-d846-40b9-a4b4-4e5846e702f4', 'NC17.M3.F-IF.4', 3, 'choice', 'Find the period of a periodic function', 'Which list of values $f(0), f(1), f(2), f(3), f(4), f(5), f(6)$ could come from a periodic function with period 3?', '["2, 5, 3, 2, 5, 3, 2","2, 5, 3, 3, 5, 2, 2","2, 5, 3, 2, 3, 5, 2","2, 5, 3, 2, 5, 3, 3"]', '2, 5, 3, 2, 5, 3, 2', NULL, 'With period 3, $f(x + 3) = f(x)$. Only the list 2, 5, 3, 2, 5, 3, 2 repeats its first three values in every group of three.', 'checked', '{"lint":[],"solve":{"answer":"2, 5, 3, 2, 5, 3, 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Period 3 needs f(3)=f(0)=2, f(4)=f(1)=5, f(5)=f(2)=3, f(6)=f(0)=2: 2,5,3,2,5,3,2.","run_id":"claude-code","at":"2026-10-24T08:28:50.101Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
