VALUES ('6613407c-0dd4-4f2c-b017-f385674e468d', 'NC17.M3.F-IF.7', 1, 'numeric', 'Key features of a polynomial function', 'What is the y-intercept of the graph of $f(x) = (x - 1)(x + 2)(x - 3)$?', '[]', '6', '(0-1)*(0+2)*(0-3)', 'The y-intercept is f(0). f(0) = (-1)(2)(-3) = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = (-1)(2)(-3) = 6.","run_id":"claude-code","at":"2026-10-24T08:27:26.576Z"}}', 'ai', NULL, NULL)
