INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67747c44-2150-4720-8488-0e460a0232e5', 'NC17.M3.F-IF.7', 1, 'choice', 'Key features of a rational function', 'Which line is a vertical asymptote of the graph of $f(x) = \frac{4}{x + 2}$?', '["$x = 2$","$y = -2$","$x = 4$","$x = -2$"]', '$x = -2$', NULL, 'A vertical asymptote is at a value of x that makes the denominator 0 and not the numerator. x + 2 = 0 gives x = -2.', 'checked', '{"lint":[],"solve":{"answer":"$x = -2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Denominator zero at x = -2, numerator 4 nonzero: x = -2.","run_id":"claude-code","at":"2026-10-24T08:27:26.576Z"}}', 'ai', NULL, NULL)
