VALUES ('24391481-8573-4387-8296-a872ee90294b', 'NC17.M3.F-IF.7', 1, 'choice', 'Key features of a sine or cosine function', 'What is the period of the graph of $y = \sin x$, with $x$ in radians?', '["$\\pi$","$2\\pi$","$\\frac{\\pi}{2}$","$4\\pi$"]', '$2\pi$', NULL, 'The graph of y = sin x repeats every full turn of the circle, which is 2 pi radians.', 'checked', '{"lint":[],"solve":{"answer":"$2\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin x has period 2 pi.","run_id":"claude-code","at":"2026-10-24T08:27:26.576Z"}}', 'ai', NULL, NULL)
