INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43080e7d-f554-4d75-b87d-71d54e619f7d', 'NC17.M3.F-IF.9', 2, 'choice', 'Compare rates of change', 'Plan A costs $C = 25 + 0.10m$ dollars for $m$ minutes. For plan B, when $m$ is 0, 100, 200 the cost is 15, 35, 55 dollars. Which plan costs less for each extra minute, and by how much?', '["Plan B, by 0.10 dollar per minute","Plan A, by 0.20 dollar per minute","Plan A, by 0.10 dollar per minute","Plan B, by 0.20 dollar per minute"]', 'Plan A, by 0.10 dollar per minute', NULL, 'The cost per extra minute is the rate of change. For plan A it is 0.10 dollar. For plan B the cost goes up 20 dollars for each 100 minutes, which is 0.20 dollar per minute. Plan A is cheaper by $0.20 - 0.10 = 0.10$ dollar per minute.', 'checked', '{"lint":[],"solve":{"answer":"Plan A, by 0.10 dollar per minute","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 0.10/min. B: 20/100=0.20/min. A cheaper by 0.10.","run_id":"claude-code","at":"2026-10-24T08:32:47.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06f707ec-1089-4a1f-8681-e23351915a32', 'NC17.M3.F-IF.9', 2, 'numeric', 'Compare amplitude and period of periodic functions', 'Function $f$ is $f(x) = \sin(3x)$, with $x$ in degrees. Function $g$ repeats every 90 degrees. How many degrees longer is the period of $f$ than the period of $g$?', '[]', '30', '360/3-90', 'The period of $\sin(bx)$ is $360^\circ \div b$, so the period of $f$ is $360 \div 3 = 120$ degrees. The period of $g$ is 90 degrees. The difference is $120 - 90 = 30$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Period of sin(3x) = 360/3=120. 120-90=30.","run_id":"claude-code","at":"2026-10-24T08:32:47.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d50f09e-3142-4035-987b-80e0c70d70c3', 'NC17.M3.F-IF.9', 2, 'numeric', 'Compare y-intercepts', 'Function $f$ is $f(x) = 5 \cdot 3^x$. Function $g$ is exponential, and when $x$ is 1, 2, 3, $g(x)$ is 12, 18, 27. How much greater is the $y$-intercept of $g$ than the $y$-intercept of $f$?', '[]', '3', '12/1.5-5*3^0', '$f(0) = 5$. For $g$ each output is 1.5 times the one before, so going back one step from $x = 1$ divides by 1.5: $g(0) = 12 \div 1.5 = 8$. The difference is $8 - 5 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0)=5. g ratio 18/12=1.5; g(0)=12/1.5=8. 8-5=3.","run_id":"claude-code","at":"2026-10-24T08:32:47.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35c155a6-bcd2-448c-8682-e697f6257381', 'NC17.M3.F-IF.9', 3, 'choice', 'Compare maximum and minimum values', 'Ball A has height $h(t) = -16t^2 + 48t + 4$ feet after $t$ seconds. Ball B has a quadratic height, and when $t$ is 0, 1, 2, 3, 4 seconds its height is 6, 42, 54, 42, 6 feet. Which ball goes higher, and by how much?', '["Ball B, by 14 feet","Ball A, by 14 feet","Ball B, by 18 feet","Ball A, by 18 feet"]', 'Ball B, by 14 feet', NULL, 'Ball A is highest at $t = 48 \div 32 = 1.5$: $h = -16(2.25) + 72 + 4 = 40$ feet. Ball B is highest in the middle of its symmetric table, at $t = 2$: 54 feet. Ball B goes higher by $54 - 40 = 14$ feet.', 'checked', '{"lint":[],"solve":{"answer":"Ball B, by 14 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: t=1.5, h=-36+72+4=40. B symmetric about t=2, max 54. B by 14.","run_id":"claude-code","at":"2026-10-24T08:32:47.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c63b4fb-5394-42ec-acd6-c0cf0f094577', 'NC17.M3.F-IF.9', 3, 'numeric', 'Compare exponential growth and decay', 'Function $f$ is $f(x) = 2 \cdot 3^x$. Function $g$ is exponential, and when $x$ is 0, 1, 2, $g(x)$ is 5, 10, 20. How much greater is $f(4)$ than $g(4)$?', '[]', '82', '2*3^4-5*2^4', '$f(4) = 2 \cdot 81 = 162$. The outputs of $g$ double each step, so $g(3) = 40$ and $g(4) = 80$. The difference is $162 - 80 = 82$.', 'checked', '{"lint":[],"solve":{"answer":"82","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(4)=2*81=162. g=5*2^x, g(4)=80. 162-80=82.","run_id":"claude-code","at":"2026-10-24T08:32:47.809Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20e47e1b-335c-42aa-8368-473753f53dea', 'NC17.M3.F-BF.1', 1, 'choice', 'Quadratic from its zeros', 'A quadratic function has leading coefficient 1 and zeros at $x = -1$ and $x = 4$. Which is its equation?', '["$f(x) = (x - 1)(x + 4)$","$f(x) = (x + 1)(x - 4)$","$f(x) = (x + 1)(x + 4)$","$f(x) = (x - 1)(x - 4)$"]', '$f(x) = (x + 1)(x - 4)$', NULL, 'A zero at $x = -1$ comes from the factor $(x + 1)$, and a zero at $x = 4$ from $(x - 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = (x + 1)(x - 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Zeros -1, 4: (x+1)(x-4).","run_id":"claude-code","at":"2026-10-24T08:30:37.380Z"}}', 'ai', NULL, NULL)
