INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('414f6517-70fe-46cf-899a-86e941857309', 'NC17.M3.F-BF.1', 1, 'choice', 'Combine functions: sum or difference in context', 'After $x$ weeks, Ana has saved $A(x) = 30 + 4x$ dollars and Ben has saved $B(x) = 10 + 7x$ dollars. Which expression gives their total savings?', '["$20 - 3x$","$40 + 28x$","$40 + 11x$","$40x + 11$"]', '$40 + 11x$', NULL, 'The total is $A(x) + B(x) = (30 + 10) + (4x + 7x) = 40 + 11x$.', 'checked', '{"lint":[],"solve":{"answer":"$40 + 11x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(30+4x)+(10+7x)=40+11x.","run_id":"claude-code","at":"2026-10-24T08:30:37.380Z"}}', 'ai', NULL, NULL)
