INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14b3eca3-fd6a-4c47-8971-68e2b57c9dcd', 'NC17.M3.F-BF.1', 2, 'numeric', 'Exponential function from two points', 'An exponential function $f(x) = a \cdot b^x$ with $b > 0$ has $f(1) = 6$ and $f(3) = 54$. What is $a$?', '[]', '2', '6/3', 'Dividing, $\frac{f(3)}{f(1)} = b^2 = \frac{54}{6} = 9$, so $b = 3$. Then $a \cdot 3 = 6$, so $a = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(3)/f(1)=b^2=9, b=3 (b>0); a*3=6 so a=2.","run_id":"claude-code","at":"2026-10-24T08:30:37.380Z"}}', 'ai', NULL, NULL)
