INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22e9e9a7-451d-4a9d-8640-4355cfc2092b', 'NC17.M3.F-BF.1', 2, 'numeric', 'Combine functions: product in context', 'A rectangle has width $w(x) = x + 2$ centimeters and length $l(x) = 2x + 1$ centimeters. What is its area, in square centimeters, when $x = 3$?', '[]', '35', '(3+2)*(2*3+1)', 'The area is the product $w(x) \cdot l(x)$. When $x = 3$: $w = 5$ and $l = 7$, so the area is $5 \cdot 7 = 35$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=3: width 5, length 7, area 35.","run_id":"claude-code","at":"2026-10-24T08:30:37.380Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0577e6ec-24f9-4452-b55a-461ca0c4e46c', 'NC17.M3.F-BF.1', 2, 'numeric', 'Combine functions: sum or difference in context', 'After $t$ months, $S(t) = 300 \cdot 2^t$ people have signed up for a class, and there are $K(t) = 40t + 100$ seats. At $t = 4$, how many more people have signed up than there are seats?', '[]', '4540', '300*2^4-(40*4+100)', '$S(4) = 300 \cdot 16 = 4800$ and $K(4) = 160 + 100 = 260$. The difference is $4800 - 260 = 4540$.', 'checked', '{"lint":[],"solve":{"answer":"4540","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S(4)=300*16=4800; K(4)=260; difference 4540.","run_id":"claude-code","at":"2026-10-24T08:30:37.380Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c87299-6947-4abf-97e1-bb0a31d55a93', 'NC17.M3.F-BF.1', 3, 'numeric', 'Exponential function from two points', 'A town had 1600 people in 2020 and 2500 people in 2022. The population multiplies by the same factor each year. What is that yearly growth factor, as a decimal?', '[]', '1.25', '5/4', 'In 2 years the population multiplied by $\frac{2500}{1600} = \frac{25}{16}$. The yearly factor $b$ has $b^2 = \frac{25}{16}$, so $b = \frac{5}{4} = 1.25$.', 'checked', '{"lint":[],"solve":{"answer":"1.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2=2500/1600=25/16, b=5/4=1.25.","run_id":"claude-code","at":"2026-10-24T08:30:37.380Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0046d50f-5216-45ae-921f-6103ca069826', 'NC17.M3.F-BF.1', 3, 'numeric', 'Combine functions: product in context', 'A club has $m(t) = 20 \cdot 2^t$ members after $t$ years, and each member pays $d(t) = 10 + 5t$ dollars in dues that year. What are the total dues, in dollars, at $t = 2$?', '[]', '1600', '20*2^2*(10+5*2)', 'Total dues are $m(t) \cdot d(t)$. At $t = 2$: $m = 80$ and $d = 20$, so the total is $80 \cdot 20 = 1600$.', 'checked', '{"lint":[],"solve":{"answer":"1600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m(2)=80 members, d(2)=20 dollars, total 1600.","run_id":"claude-code","at":"2026-10-24T08:30:37.380Z"}}', 'ai', NULL, NULL)
