INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54555854-37b5-407e-b0a2-3649e2a237df', 'NC17.M3.F-BF.3', 1, 'numeric', 'Vertical stretch, compression or reflection k f(x)', 'A function $f$ has $f(2) = 6$. A new function is $h(x) = 2f(x)$. Find $h(2)$.', '[]', '12', '2*6', 'h(2) = 2 * f(2) = 2 * 6 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(2) = 2·f(2) = 12.","run_id":"claude-code","at":"2026-10-28T18:47:12.708Z"}}', 'ai', NULL, NULL)
