INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0146cdcd-cb62-41fe-8510-351c4349cb79', 'NC17.M3.F-BF.3', 1, 'numeric', 'Horizontal shift f(x + k)', 'A function $f$ has $f(3) = 5$. Let $g(x) = f(x - 3)$. What is $g(6)$?', '[]', '5', '5', 'g(6) = f(6 - 3) = f(3) = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(6)=f(6-3)=f(3)=5.","run_id":"claude-code","at":"2026-10-28T18:48:27.944Z"}}', 'ai', NULL, NULL)
