INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31968c89-cea8-4842-a113-bb0b5b72886d', 'NC17.M3.F-BF.3', 1, 'choice', 'Vertical stretch, compression or reflection k f(x)', 'How is the graph of $g(x) = -f(x)$ related to the graph of $f$?', '["It is reflected over the x-axis","It is reflected over the y-axis","It is turned a quarter turn","It is shifted down 1 unit"]', 'It is reflected over the x-axis', NULL, 'The negative changes the sign of every output, so each point (x, y) becomes (x, -y). That is a reflection over the x-axis.', 'checked', '{"lint":[],"solve":{"answer":"It is reflected over the x-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-f(x) negates every output: reflection over the x-axis.","run_id":"claude-code","at":"2026-10-28T18:48:28.181Z"}}', 'ai', NULL, NULL)
