INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('270c27fe-5946-4611-9bd0-dde0fad956ed', 'NC17.M3.F-BF.3', 2, 'numeric', 'Locate a point on the transformed graph', 'The only point of the graph of $f$ with y-coordinate 4 is $(6, 4)$. Let $g(x) = f(2x)$. For what x-value does $g(x) = 4$?', '[]', '3', '6/2', 'g(x) = 4 when f(2x) = 4. That happens only when 2x = 6, so x = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(x) = 4 means f(2x) = 4, only when 2x = 6, x = 3.","run_id":"claude-code","at":"2026-10-28T18:48:27.960Z"}}', 'ai', NULL, NULL)
