INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('361a7b5d-6ff5-4854-937e-b7768e744a75', 'NC17.M3.F-BF.3', 2, 'choice', 'Combine transformations', 'The graph of $g(x) = f(x - 2) + 5$ is compared with the graph of $f$. What is the change?', '["Every point moves 2 units left and 5 units up","Every point moves 2 units right and 5 units down","Every point moves 5 units right and 2 units up","Every point moves 2 units right and 5 units up"]', 'Every point moves 2 units right and 5 units up', NULL, 'x - 2 inside moves the graph 2 units right. + 5 outside moves it 5 units up.', 'checked', '{"lint":[],"solve":{"answer":"Every point moves 2 units right and 5 units up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(x-2): right 2; +5: up 5.","run_id":"claude-code","at":"2026-10-28T18:48:28.451Z"}}', 'ai', NULL, NULL)
