INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04476e7c-c3f8-48fc-bf3a-ef2a91cb9a2f', 'NC17.M3.F-BF.3', 2, 'numeric', 'Combine transformations', 'Let $f(x) = x^2$ and $g(x) = f(x + 3) - 1$. What is $g(0)$?', '[]', '8', '(0+3)^2-1', 'g(0) = f(0 + 3) - 1 = f(3) - 1 = 9 - 1 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(0) = f(3) - 1 = 9 - 1 = 8.","run_id":"claude-code","at":"2026-10-28T18:48:28.514Z"}}', 'ai', NULL, NULL)
