INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1809dd-5e43-4491-911f-33270741e091', 'NC17.M3.F-BF.3', 3, 'numeric', 'Combine transformations', 'A function $f$ has $f(0) = 3$ and $f(2) = -1$. Let $g(x) = -f(x - 2) + 1$. What is $g(2)$?', '[]', '-2', '-3+1', 'g(2) = -f(2 - 2) + 1 = -f(0) + 1 = -3 + 1 = -2. The value f(2) is not needed.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(2)=-f(0)+1=-3+1=-2.","run_id":"claude-code","at":"2026-10-28T18:48:27.956Z"}}', 'ai', NULL, NULL)
