INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('359808ee-a94f-4bb7-ab4c-12731ed30ed2', 'NC17.M3.F-BF.3', 3, 'choice', 'Horizontal stretch, compression or reflection f(kx)', 'The graph of $g(x) = f(-2x)$ is compared with the graph of $f$. What is the change?', '["Stretched horizontally to twice its width and reflected over the y-axis","Squeezed horizontally to half its width and reflected over the x-axis","Squeezed horizontally to half its width and reflected over the y-axis","Squeezed vertically to half its height and reflected over the y-axis"]', 'Squeezed horizontally to half its width and reflected over the y-axis', NULL, 'The factor 2 inside squeezes the graph horizontally to half its width. The negative sign inside reflects it over the y-axis. A reflection over the x-axis would need a negative outside.', 'checked', '{"lint":[],"solve":{"answer":"Squeezed horizontally to half its width and reflected over the y-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(-2x): factor 2 compresses horizontally to half width; the negative sign reflects across the y-axis.","run_id":"claude-code","at":"2026-10-28T18:48:28.003Z"}}', 'ai', NULL, NULL)
