INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dc120ff-dde5-4df3-a43b-c3410e69d7b3', 'NC17.M3.F-LE.3', 1, 'numeric', 'Find where an exponential overtakes a polynomial', 'Let $f(x) = 2^x$ and $g(x) = 8x$. How much greater is $f(6)$ than $g(6)$?', '[]', '16', '2^6-8*6', '$f(6) = 2^6 = 64$ and $g(6) = 8 \times 6 = 48$. The difference is $64 - 48 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(6)=64, g(6)=48, 64-48=16.","run_id":"claude-code","at":"2026-10-24T08:37:47.438Z"}}', 'ai', NULL, NULL)
