INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0562aa6f-71fd-43f0-bc0c-b7fbede9edd4', 'NC17.M3.F-LE.3', 1, 'numeric', 'Average rate of change of an exponential function', 'The function $g(x) = 2^x$ has the values 2, 4, 8, 16 at $x = 1, 2, 3, 4$. What is the average rate of change of $g$ from $x = 3$ to $x = 4$?', '[]', '8', '(16-8)/(4-3)', 'The average rate of change is the change in $g$ divided by the change in $x$: $\frac{16 - 8}{4 - 3} = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(16-8)/(4-3)=8.","run_id":"claude-code","at":"2026-10-24T08:37:47.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2144320f-42a8-4a2b-9400-496bb9400db9', 'NC17.M3.F-LE.3', 1, 'choice', 'Tell linear, quadratic and exponential growth apart', 'For $x = 0, 1, 2, 3$, which list of $y$-values changes by the same amount each time $x$ increases by 1?', '["2, 4, 8, 16","3, 6, 9, 12","1, 4, 9, 16","1, 3, 9, 27"]', '3, 6, 9, 12', NULL, 'The list 3, 6, 9, 12 goes up by 3 every time. In 2, 4, 8, 16 and 1, 3, 9, 27 the values are multiplied by the same number, and in 1, 4, 9, 16 the changes (3, 5, 7) keep growing.', 'checked', '{"lint":[],"solve":{"answer":"3, 6, 9, 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,6,9,12 changes by 3 each time; others do not (2,6,18 / 2,4,8 / 3,5,7).","run_id":"claude-code","at":"2026-10-24T08:37:47.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a5e45f7-7155-4193-a940-533481a32720', 'NC17.M3.F-LE.3', 2, 'numeric', 'Compare rates of change over equal intervals', 'The table gives $f$ and $g$ at $x = 0, 2, 4, 6$. The values of $f$ are 3, 9, 15, 21 and the values of $g$ are 3, 12, 48, 192. How much greater is the average rate of change of $g$ than that of $f$ from $x = 2$ to $x = 6$?', '[]', '42', '(192-12)/(6-2)-(21-9)/(6-2)', 'For $g$: $\frac{192 - 12}{6 - 2} = 45$. For $f$: $\frac{21 - 9}{6 - 2} = 3$. The difference is $45 - 3 = 42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f: (21-9)/(6-2)=3. g: (192-12)/4=45. 45-3=42.","run_id":"claude-code","at":"2026-10-24T08:37:47.438Z"}}', 'ai', NULL, NULL)
