VALUES ('78f1b518-8d0d-41b9-b460-ab4fe5d8add7', 'NC17.M3.F-LE.4', 1, 'numeric', 'Logarithmic form, change of base and base e', 'Evaluate $\log_2 32$.', '[]', '5', '5', 'The power of 2 that gives 32 is 5, since $2^5 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^5 = 32, so log_2 32 = 5.","run_id":"claude-code","at":"2026-10-28T18:48:28.172Z"}}', 'ai', NULL, NULL)
