INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e20b425-7f97-41fd-b036-6ea22bf1ef20', 'NC17.M3.F-LE.4', 1, 'choice', 'Write the solution of an exponential equation as a logarithm', 'Which is the exact solution of $2^x = 9$?', '["$x = \\log_9 2$","$x = \\frac{9}{2}$","$x = \\log_2 9$","$x = 2^9$"]', '$x = \log_2 9$', NULL, 'The exponent that makes 2 raised to it equal 9 is the logarithm of 9 with base 2: $x = \log_2 9$.', 'checked', '{"lint":[],"solve":{"answer":"$x = \\log_2 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^x = 9 means x = log_2 9.","run_id":"claude-code","at":"2026-10-28T18:48:28.359Z"}}', 'ai', NULL, NULL)
