INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f59f0c7-7633-4eae-9439-521cd872a8bb', 'NC17.M3.F-LE.4', 2, 'numeric', 'Evaluate a logarithm solution with a calculator', 'Use a calculator to solve $2^x = 50$. Give $x$ to the nearest hundredth.', '[]', '5.64', NULL, '$x = \log_2 50 = \frac{\ln 50}{\ln 2} \approx \frac{3.9120}{0.6931} \approx 5.64$.', 'checked', '{"lint":[],"solve":{"answer":"5.64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = ln50/ln2 = 3.91202/0.693147 = 5.6439, so 5.64.","run_id":"claude-code","at":"2026-10-28T18:48:27.958Z"}}', 'ai', NULL, NULL)
