INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16318726-38dd-4b0d-9ab8-a0875c4495a2', 'NC17.M3.F-LE.4', 2, 'numeric', 'Solve an exponential growth or decay model for time', 'A sample of 80 grams of a substance loses half of its mass every 5 years, so after $t$ years its mass is $80\left(\frac{1}{2}\right)^{t/5}$ grams. After how many years is 10 grams left?', '[]', '15', '15', 'Set $80\left(\frac{1}{2}\right)^{t/5} = 10$, so $\left(\frac{1}{2}\right)^{t/5} = \frac{1}{8}$. Since $\left(\frac{1}{2}\right)^3 = \frac{1}{8}$, $\frac{t}{5} = 3$ and $t = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)^(t/5) = 10/80 = 1/8 = (1/2)^3, t/5 = 3, t = 15.","run_id":"claude-code","at":"2026-10-28T18:48:27.970Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fa847c1-6b19-4478-94f5-29f052083f58', 'NC17.M3.F-LE.4', 2, 'numeric', 'Evaluate a logarithm solution with a calculator', 'Solve $7^x = 120$. Give $x$ to the nearest hundredth.', '[]', '2.46', NULL, '$x = \log_7 120 = \frac{\ln 120}{\ln 7} \approx \frac{4.7875}{1.9459} \approx 2.46$.', 'checked', '{"lint":[],"solve":{"answer":"2.46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = ln 120 / ln 7 = 4.7875/1.9459 = 2.4603. Check 7^2.46 = 49 x 2.448 = 119.9. x = 2.46.","run_id":"claude-code","at":"2026-10-28T18:48:28.532Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1855a8c8-6833-4145-8ca8-1a383af0c5f6', 'NC17.M3.F-LE.4', 3, 'numeric', 'Solve an exponential growth or decay model for time', 'A car is worth 20,000 dollars new and loses 15% of its value each year, so after $t$ years it is worth $20000(0.85)^t$ dollars. After how many years is it worth 10,000 dollars? Give $t$ to the nearest tenth.', '[]', '4.3', NULL, 'Set $20000(0.85)^t = 10000$, so $0.85^t = 0.5$. Then $t = \frac{\ln 0.5}{\ln 0.85} \approx \frac{-0.6931}{-0.1625} \approx 4.3$ years.', 'checked', '{"lint":[],"solve":{"answer":"4.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.85^t=0.5, t=ln0.5/ln0.85=0.69315/0.16252=4.265, so 4.3.","run_id":"claude-code","at":"2026-10-28T18:48:27.949Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f2401c9-ccfc-4fc6-ae1f-c5d1f186812a', 'NC17.M3.F-LE.4', 3, 'numeric', 'Solve an exponential growth or decay model for time', 'A population is modeled by $P = 200e^{0.03t}$, where $t$ is in years. When will the population reach 500? Give $t$ to the nearest tenth of a year.', '[]', '30.5', NULL, 'Set $200e^{0.03t} = 500$, so $e^{0.03t} = 2.5$. Then $0.03t = \ln 2.5 \approx 0.9163$ and $t \approx 30.5$ years.', 'checked', '{"lint":[],"solve":{"answer":"30.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"500 = 200e^{0.03t}; e^{0.03t} = 2.5; t = ln 2.5/0.03 = 0.91629/0.03 ≈ 30.54 → 30.5.","run_id":"claude-code","at":"2026-10-28T18:48:28.010Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23d5541a-a7ff-4382-b8de-fb33cc9b6e9c', 'NC17.M3.F-TF.1', 1, 'numeric', 'Arc length from radian measure and radius', 'A central angle measures 2 radians. The circle''s radius is 5 meters. How long, in meters, is the arc that the angle cuts off?', '[]', '10', '2*5', 'Arc length is the radian measure times the radius: $2 \times 5 = 10$ meters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s = r*theta = 5*2 = 10.","run_id":"claude-code","at":"2026-10-24T08:38:28.508Z"}}', 'ai', NULL, NULL)
