INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ac10e66-79a6-4ac6-8504-69be8090f31a', 'NC17.M3.F-TF.1', 1, 'choice', 'Radian measure of common fractions of a circle', 'A central angle cuts off an arc as long as the whole circle. What is its measure in radians?', '["$\\pi$","$\\frac{\\pi}{2}$","$2\\pi$","$360$"]', '$2\pi$', NULL, 'The whole circle has length $2\pi r$. Dividing by the radius $r$ gives $2\pi$ radians.', 'checked', '{"lint":[],"solve":{"answer":"$2\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole circumference 2*pi*r; theta = 2*pi*r/r = 2*pi.","run_id":"claude-code","at":"2026-10-24T08:38:28.508Z"}}', 'ai', NULL, NULL)
