INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19c3c52e-b78b-4188-9b0d-66bc74075663', 'NC17.M3.F-TF.1', 2, 'choice', 'Radian measure of common fractions of a circle', 'A central angle covers exactly one eighth of a circle. What is its measure in radians?', '["$\\frac{\\pi}{4}$","$\\frac{\\pi}{8}$","$\\frac{\\pi}{2}$","$\\frac{3\\pi}{4}$"]', '$\frac{\pi}{4}$', NULL, 'The whole circle is $2\pi$ radians, and $2\pi \div 8 = \frac{\pi}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{\\pi}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2pi/8 = pi/4.","run_id":"claude-code","at":"2026-10-24T08:38:28.508Z"}}', 'ai', NULL, NULL)
