INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('478d5136-291a-4991-86f5-e9542e4398ed', 'NC17.M3.F-TF.1', 2, 'numeric', 'Radian measure as arc length divided by radius', 'A runner goes 90 meters around a circular curve of radius 60 meters. Through how many radians does the runner''s direction from the center turn?', '[]', '3/2', '90/60', 'Radian measure is arc length divided by radius: $90 \div 60 = \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"theta = 90/60 = 1.5.","run_id":"claude-code","at":"2026-10-24T08:38:28.508Z"}}', 'ai', NULL, NULL)
