INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05b314e0-2b9b-4d85-bce5-a7b9492323b9', 'NC17.M3.F-TF.1', 2, 'choice', 'Radian measure is a real number input', 'A student says that $\sin(10)$ cannot be found in radian mode because 10 is greater than $2\pi$. Which response is correct?', '["It cannot be found, because radian inputs must be less than $2\\pi$","It can be found, because any real number is a valid radian input","It can be found only after 10 is changed to a whole number of degrees","It cannot be found, because radian inputs must be fractions of $\\pi$"]', 'It can be found, because any real number is a valid radian input', NULL, 'A radian measure is a real number, the ratio of arc length to radius, and any real number can be the input of sine. A number greater than $2\pi$ just means going around the circle more than once.', 'checked', '{"lint":[],"solve":{"answer":"It can be found, because any real number is a valid radian input","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sine is defined for every real number in radians; 10 radians is just more than one full turn. sin(10) is about -0.544.","run_id":"claude-code","at":"2026-10-24T08:47:25.559Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a151fb3-fa52-4d4e-a5e1-e9c356b9bc06', 'NC17.M3.F-TF.1', 3, 'choice', 'Radian measure of common fractions of a circle', 'A point starts at $(1, 0)$ on the unit circle and moves counterclockwise through 3 full laps and then one more quarter of a lap. What total angle in radians has it moved through?', '["$\\frac{7\\pi}{2}$","$\\frac{13\\pi}{4}$","$\\frac{25\\pi}{4}$","$\\frac{13\\pi}{2}$"]', '$\frac{13\pi}{2}$', NULL, 'Each lap is $2\pi$ radians, so 3 laps are $6\pi$. A quarter lap is $\frac{\pi}{2}$. The total is $6\pi + \frac{\pi}{2} = \frac{13\pi}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{13\\pi}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 laps = 6pi; plus pi/2 = 13pi/2.","run_id":"claude-code","at":"2026-10-24T08:38:28.508Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05c4c3c1-a208-4be0-b6f7-cef79e41f4e9', 'NC17.M3.F-TF.1', 3, 'numeric', 'Radius from arc length and radian measure', 'A sector has a radius of 6 cm and a central angle of 2 radians. In a different circle, an arc of that same length belongs to a central angle of 3 radians. What is that circle''s radius, in centimeters?', '[]', '4', '2*6/3', 'The arc length is $2 \times 6 = 12$ cm. In the other circle, radius is $12 \div 3 = 4$ cm.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"arc = 6*2 = 12; r = 12/3 = 4.","run_id":"claude-code","at":"2026-10-24T08:38:28.508Z"}}', 'ai', NULL, NULL)
