INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1890c3bb-1c3b-4aab-9358-c6308a719ba0', 'NC17.M3.F-TF.2', 1, 'numeric', 'Sine and cosine in tables and graphs', 'A table shows the values of $y = \sin x$. For $x = 0$, $\frac{\pi}{2}$, $\pi$ and $\frac{3\pi}{2}$, the values of $y$ are 0, 1, 0 and one more value. What is the missing value for $x = \frac{3\pi}{2}$?', '[]', '-1', '-1', 'At $\frac{3\pi}{2}$ the point on the unit circle is $(0, -1)$, and sine is the y-coordinate, so the missing value is $-1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin(3pi/2) = -1.","run_id":"claude-code","at":"2026-10-24T08:38:57.032Z"}}', 'ai', NULL, NULL)
