INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('186c8e06-0129-46db-a2a8-c2470e5cbeaa', 'NC17.M3.F-TF.2', 1, 'choice', 'Signs of sine and cosine by quadrant', 'A point on the unit circle has a positive x-coordinate and a positive y-coordinate. In which quadrant is it?', '["Quadrant II","Quadrant III","Quadrant IV","Quadrant I"]', 'Quadrant I', NULL, 'Both coordinates are positive only in Quadrant I. In Quadrant II the x-coordinate is negative, in Quadrant III both are negative, and in Quadrant IV the y-coordinate is negative.', 'checked', '{"lint":[],"solve":{"answer":"Quadrant I","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x>0, y>0 is Quadrant I.","run_id":"claude-code","at":"2026-10-24T08:38:57.032Z"}}', 'ai', NULL, NULL)
