INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76f63eab-e585-4cc0-8329-26f47b8ec670', 'NC17.M3.F-TF.5', 1, 'numeric', 'Interpret key features in context', 'A spring bobs up and down. Its height above a table is $y(t) = 6\sin(\pi t) + 14$ centimeters at time $t$ seconds. What is the lowest height of the spring, in centimeters?', '[]', '8', '14-6', 'The lowest value of the model is $h - |a| = 14 - 6 = 8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Min = 14 - 6 = 8.","run_id":"claude-code","at":"2026-10-24T08:38:17.169Z"}}', 'ai', NULL, NULL)
