INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1410b430-7ba1-4372-8d05-1f496e0c72fa', 'NC17.M3.F-TF.5', 2, 'numeric', 'Midline, maximum and minimum', 'What is the maximum value of $f(x) = 4\sin(3x) - 1$?', '[]', '3', '4-1', 'The sine function reaches 1 at most, so the maximum is $a + h = 4 + (-1) = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max = 4 + (-1) = 3.","run_id":"claude-code","at":"2026-10-24T08:38:17.169Z"}}', 'ai', NULL, NULL)
