INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d38e3ef-8f1c-4dce-ac9c-389ea5800d77', 'NC17.M3.F-TF.5', 2, 'choice', 'Effect of the parameters on the graph', 'How does the graph of $y = \sin(3x)$ compare with the graph of $y = \sin(x)$?', '["The amplitude becomes 3 and the period stays $2\\pi$","The period becomes $6\\pi$ and the amplitude stays 1","The period becomes $\\frac{2\\pi}{3}$ and the amplitude stays 1","The graph moves up 3 units and the period stays $2\\pi$"]', 'The period becomes $\frac{2\pi}{3}$ and the amplitude stays 1', NULL, 'The 3 multiplies $x$, so it changes the period to $\frac{2\pi}{3}$: the graph repeats 3 times as fast. The amplitude is still 1.', 'checked', '{"lint":[],"solve":{"answer":"The period becomes $\\frac{2\\pi}{3}$ and the amplitude stays 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b = 3: period 2pi/3, amplitude still 1.","run_id":"claude-code","at":"2026-10-24T08:38:17.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('548b6e6f-3345-4569-baef-ce42bb3b07f9', 'NC17.M3.F-TF.5', 2, 'choice', 'Effect of the parameters on the graph', 'Let $f(x) = 2\sin(x)$ and $g(x) = 2\sin(x) + 4$. How does the graph of $g$ compare with the graph of $f$?', '["It has an amplitude 4 greater and the same midline","It has the same amplitude and a period 4 times as long","It has the same amplitude and period, and is moved 4 units right","It has the same amplitude and period, and its midline is 4 units higher"]', 'It has the same amplitude and period, and its midline is 4 units higher', NULL, 'Adding 4 to the output moves the graph up 4 units. The midline goes from $y = 0$ to $y = 4$, and the amplitude (2) and period ($2\pi$) do not change.', 'checked', '{"lint":[],"solve":{"answer":"It has the same amplitude and period, and its midline is 4 units higher","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same a and b; h = 4: midline 4 units higher.","run_id":"claude-code","at":"2026-10-24T08:38:17.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b9c1a83-7218-4bd3-9b46-b4454b873e3f', 'NC17.M3.F-TF.5', 3, 'choice', 'Write the equation from key features', 'A sine function $f(x) = a\sin(bx) + h$ with $a > 0$ and $b > 0$ has a maximum value of 3, a minimum value of $-7$ and a period of 4. Which equation matches?', '["$f(x) = 5\\sin(\\frac{\\pi}{2}x) - 2$","$f(x) = 5\\sin(\\frac{\\pi}{4}x) - 2$","$f(x) = 10\\sin(\\frac{\\pi}{2}x) - 2$","$f(x) = 5\\sin(4x) - 2$"]', '$f(x) = 5\sin(\frac{\pi}{2}x) - 2$', NULL, 'Midline: $h = \frac{3 + (-7)}{2} = -2$. Amplitude: $a = \frac{3 - (-7)}{2} = 5$. Period: $\frac{2\pi}{b} = 4$, so $b = \frac{\pi}{2}$. So $f(x) = 5\sin(\frac{\pi}{2}x) - 2$.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = 5\\sin(\\frac{\\pi}{2}x) - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a = (3+7)/2 = 5, h = (3-7)/2 = -2, b = 2pi/4 = pi/2.","run_id":"claude-code","at":"2026-10-24T08:38:17.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d3a4c2e-13ef-46a4-ad37-aff47397b31f', 'NC17.M3.F-TF.5', 3, 'numeric', 'Interpret key features in context', 'A rider sits on a Ferris wheel. The rider''s height above the ground is $h(t) = 18\sin(\frac{\pi}{20}t) + 22$ feet at time $t$ seconds. How many feet above the ground is the lowest point of the ride?', '[]', '4', '22-18', 'The lowest value is $h - |a| = 22 - 18 = 4$ feet. (The wheel has a radius of 18 feet and its center is 22 feet above the ground.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Min = 22 - 18 = 4.","run_id":"claude-code","at":"2026-10-24T08:38:17.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1306d31d-b37d-4c89-9647-71af969bafaf', 'NC17.M3.G-CO.10', 1, 'numeric', 'Centroid coordinates from the vertices', 'A triangle has vertices $(0, 0)$, $(6, 0)$ and $(0, 9)$. What is the $y$-coordinate of its centroid?', '[]', '3', '(0+0+9)/3', 'The centroid''s coordinates are the averages of the vertices'' coordinates. The $y$-values are 0, 0 and 9, so the average is $\frac{0 + 0 + 9}{3} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Centroid y = (0 + 0 + 9)/3 = 3.","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b50784-e262-41a5-abf3-9209a4ca3f2e', 'NC17.M3.G-CO.10', 1, 'choice', 'Identify a center from its definition', 'Which point of a triangle is always the same distance from all three of its vertices?', '["The centroid","The circumcenter","The incenter","The midpoint of a side"]', 'The circumcenter', NULL, 'The circumcenter lies on all three perpendicular bisectors, so it is the same distance from each vertex. It is the center of the circle through the three vertices.', 'checked', '{"lint":[],"solve":{"answer":"The circumcenter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The circumcenter is equidistant from the three vertices.","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('065f981b-62e9-44bf-b776-fb5cf9327b87', 'NC17.M3.G-CO.10', 1, 'choice', 'Choose the center that fits a situation', 'A triangle is cut from a thin sheet of cardboard that is the same thickness everywhere. At which point of the triangle will it balance on a pencil tip?', '["The incenter","The circumcenter","The midpoint of the longest side","The centroid"]', 'The centroid', NULL, 'The centroid is the balance point of a triangle of even thickness.', 'checked', '{"lint":[],"solve":{"answer":"The centroid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A uniform triangular lamina balances at its center of mass, the centroid.","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
