INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e9ce7fe-4af8-4edb-b273-de14515dfbf9', 'NC17.M3.G-CO.10', 2, 'choice', 'Centroid coordinates from the vertices', 'A triangle has vertices $(1, 2)$, $(7, 5)$ and $(4, 11)$. What are the coordinates of its centroid?', '["$(4, 6)$","$(6, 9)$","$(4, 6.5)$","$(12, 18)$"]', '$(4, 6)$', NULL, 'Average the $x$-values: $\frac{1 + 7 + 4}{3} = 4$. Average the $y$-values: $\frac{2 + 5 + 11}{3} = 6$. The centroid is $(4, 6)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = (1+7+4)/3 = 12/3 = 4; y = (2+5+11)/3 = 18/3 = 6. Centroid (4, 6).","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab27b93-9494-497a-9164-62e732266a70', 'NC17.M3.G-CO.10', 2, 'choice', 'Where the centers lie in a triangle', 'Of a triangle''s centroid, incenter and circumcenter, which can lie outside the triangle when the triangle is obtuse?', '["The circumcenter only","The incenter only","The centroid only","All three lie inside the triangle"]', 'The circumcenter only', NULL, 'The centroid and the incenter are always inside a triangle. The circumcenter lies outside an obtuse triangle.', 'checked', '{"lint":[],"solve":{"answer":"The circumcenter only","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Centroid and incenter are always inside. The circumcenter of an obtuse triangle lies outside.","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('056aa0b2-f565-4550-98bd-1761a1688bbd', 'NC17.M3.G-CO.10', 2, 'choice', 'Incenter: angle bisectors and the inscribed circle', 'Ana cuts out a paper triangle. She folds it so that two sides lie exactly on top of each other and presses a crease from their shared vertex. She does this at all three vertices, and the three creases cross at one point. Which center of the triangle is that point?', '["The centroid","The incenter","The circumcenter","The midpoint of the longest side"]', 'The incenter', NULL, 'Folding one side onto another splits the angle between them into two equal angles, so each crease is an angle bisector. The three angle bisectors meet at the incenter.', 'checked', '{"lint":[],"solve":{"answer":"The incenter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Folding so two sides from a vertex coincide makes the crease the angle bisector at that vertex. The three angle bisectors meet at the incenter.","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06799bc5-7c0c-41d9-877f-8abc661d48fe', 'NC17.M3.G-CO.10', 3, 'numeric', 'Circumcenter: perpendicular bisectors and the circumscribed circle', 'A triangle has vertices $A(0, 0)$, $B(8, 0)$ and $C(2, 6)$. Its circumcenter $P$ lies on the perpendicular bisector of $\overline{AB}$, so its $x$-coordinate is 4. The circumcenter is as far from $A$ as from $C$. What is the $y$-coordinate of $P$?', '[]', '2', '(4+36-16)/12', 'Let $P = (4, y)$. Then $PA^2 = 4^2 + y^2$ and $PC^2 = (4 - 2)^2 + (y - 6)^2 = 4 + y^2 - 12y + 36$. Setting them equal: $16 = 40 - 12y$, so $12y = 24$ and $y = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = (4, y). PA^2 = 16 + y^2; PC^2 = (4-2)^2 + (y-6)^2 = 4 + y^2 - 12y + 36. Equal: 16 = 40 - 12y, y = 2. Check PB^2 = 16 + 4 = 20 = PA^2.","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20d6386b-7e5a-4b52-a7cf-9658b41cfbb9', 'NC17.M3.G-CO.10', 3, 'numeric', 'Circumcenter: perpendicular bisectors and the circumscribed circle', 'A right triangle has sides 5 cm, 12 cm and 13 cm. What is the distance from its circumcenter to each vertex, in centimeters?', '[]', '6.5', '13/2', 'The longest side, 13 cm, is the hypotenuse, and the circumcenter of a right triangle is its midpoint. So the circumcenter is $\frac{13}{2} = 6.5$ cm from each vertex.', 'checked', '{"lint":[],"solve":{"answer":"6.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^2 + 12^2 = 169 = 13^2, right triangle. Circumcenter is the midpoint of the hypotenuse, distance 13/2 = 6.5.","run_id":"claude-code","at":"2026-10-24T08:42:31.709Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d608e17-878d-49e0-ae2a-9b70b220339b', 'NC17.M3.G-CO.11', 1, 'choice', 'Congruent diagonals make a parallelogram a rectangle', 'A parallelogram has two diagonals that are the same length. Which kind of parallelogram must it be?', '["A rhombus","A square","A kite","A rectangle"]', 'A rectangle', NULL, 'A parallelogram with congruent diagonals is a rectangle. It does not have to be a rhombus or a square, because its sides need not all be equal.', 'checked', '{"lint":[],"solve":{"answer":"A rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A parallelogram with congruent diagonals is a rectangle (need not be a square).","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
