INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f889d62-03a2-46d3-9274-1d6ac6bc7400', 'NC17.M3.G-CO.11', 1, 'choice', 'Opposite angles of a parallelogram are congruent', 'In parallelogram $WXYZ$, which pair of angles must be congruent?', '["$\\angle W$ and $\\angle X$","$\\angle X$ and $\\angle Y$","$\\angle W$ and $\\angle Y$","$\\angle Y$ and $\\angle Z$"]', '$\angle W$ and $\angle Y$', NULL, 'The vertices go around in order, so $\angle W$ and $\angle Y$ are opposite angles, and opposite angles of a parallelogram are congruent. The other pairs are next to each other.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle W$ and $\\angle Y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite angles W and Y are congruent.","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('141d0abb-1120-4123-ad9b-137abe5696d2', 'NC17.M3.G-CO.11', 1, 'numeric', 'Diagonals of a parallelogram bisect each other', 'A garden is shaped like a parallelogram. Two straight paths run along its diagonals and cross each other. One path is 18 m long. How far, in meters, is the crossing point from one end of that path?', '[]', '9', '18/2', 'The diagonals of a parallelogram bisect each other, so the crossing point is the midpoint of each path. The distance is $18 \div 2 = 9$ m.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Diagonals bisect each other: 18/2 = 9.","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('874e86e5-c79e-4ddb-9503-c7484ca80fb1', 'NC17.M3.G-CO.11', 2, 'numeric', 'Diagonals of a parallelogram in the coordinate plane', 'The diagonals of parallelogram $ABCD$ cross at $M(5, 3)$. Vertex $A$ is at $(2, 1)$. What is the x-coordinate of $C$?', '[]', '8', '2*5-2', '$M$ is the midpoint of $\overline{AC}$, so $\frac{2 + x}{2} = 5$. Then $x = 10 - 2 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M is the midpoint of AC: C = (2*5-2, 2*3-1) = (8, 5). x = 8.","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5baf1a08-5b10-4e3e-a1de-86e1b9d0e27f', 'NC17.M3.G-CO.11', 2, 'choice', 'Reasons in a proof about parallelograms', 'Which statement is NOT true for every parallelogram?', '["Its diagonals are congruent.","Its opposite sides are congruent.","Its opposite angles are congruent.","Its diagonals bisect each other."]', 'Its diagonals are congruent.', NULL, 'Opposite sides, opposite angles and bisecting diagonals all hold for every parallelogram. Congruent diagonals hold only for rectangles.', 'checked', '{"lint":[],"solve":{"answer":"Its diagonals are congruent.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Diagonals are congruent only in rectangles; the other three hold for every parallelogram.","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ea0fde9-d5a8-422c-965a-fee85c85d881', 'NC17.M3.G-CO.11', 2, 'choice', 'Opposite angles of a parallelogram are congruent', 'In parallelogram $PQRS$, $m\angle P = 52^\circ$. Which statement is true?', '["$m\\angle Q = 52^\\circ$","$m\\angle R = 52^\\circ$","$m\\angle R = 128^\\circ$","$m\\angle S = 52^\\circ$"]', '$m\angle R = 52^\circ$', NULL, '$\angle R$ is opposite $\angle P$, and opposite angles of a parallelogram are congruent, so $m\angle R = 52^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$m\\angle R = 52^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite angle R = 52; Q and S = 128.","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('112180b9-28b5-44f0-8074-003cc5e4dace', 'NC17.M3.G-CO.11', 3, 'numeric', 'Diagonals of a parallelogram in the coordinate plane', 'Parallelogram $ABCD$ has vertices $A(-2, 1)$, $B(3, -1)$ and $C(6, 4)$. What is the sum of the coordinates of vertex $D$?', '[]', '7', '(0-2+6-3)+(1+4+1)', 'The diagonals $\overline{AC}$ and $\overline{BD}$ share a midpoint. The midpoint of $\overline{AC}$ is $(2, 2.5)$. If $D = (x, y)$, then $\frac{3 + x}{2} = 2$ and $\frac{-1 + y}{2} = 2.5$, so $D = (1, 6)$ and $1 + 6 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"D = A + C - B = (-2+6-3, 1+4-(-1)) = (1, 6). Sum = 7.","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('265bfbe0-853d-41cc-aa44-f3115e509314', 'NC17.M3.G-CO.11', 3, 'numeric', 'Opposite sides of a parallelogram are congruent', 'In parallelogram $ABCD$, $AB = 2x + 3$, $BC = x + 5$ and $CD = 3x - 4$. What is the perimeter of $ABCD$?', '[]', '58', '2*((2*7+3)+(7+5))', 'Opposite sides are congruent, so $2x + 3 = 3x - 4$ and $x = 7$. Then $AB = 17$ and $BC = 12$. The perimeter is $2(17 + 12) = 58$.', 'checked', '{"lint":[],"solve":{"answer":"58","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = CD: 2x+3 = 3x-4, x = 7. AB = 17, BC = 12. Perimeter = 2(17+12) = 58.","run_id":"claude-code","at":"2026-10-24T08:42:06.024Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('265ea0c0-14dc-44e3-b721-506e131c8f42', 'NC17.M3.G-CO.14', 1, 'numeric', 'Use theorems about triangles to solve problems', 'An exterior angle of a triangle has two remote interior angles measuring $50^\circ$ and $60^\circ$. What is the measure of the exterior angle, in degrees?', '[]', '110', '50+60', 'The exterior angle theorem says an exterior angle equals the sum of the two remote interior angles: $50^\circ + 60^\circ = 110^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior = sum of remote interior: 110.","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5baebe33-f173-42ef-b228-e20b41e6fd33', 'NC17.M3.G-CO.14', 1, 'choice', 'Decide which conclusion about a figure is justified', 'In a quadrilateral, both pairs of opposite sides are congruent. Which conclusion is justified?', '["It must be a trapezoid","It must be a parallelogram","It must be a rhombus","It must be a square"]', 'It must be a parallelogram', NULL, 'If both pairs of opposite sides of a quadrilateral are congruent, the quadrilateral is a parallelogram. Nothing says it has right angles or four equal sides, so it need not be a rectangle, rhombus or square.', 'checked', '{"lint":[],"solve":{"answer":"It must be a parallelogram","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both pairs of opposite sides congruent implies parallelogram.","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58531691-5174-484b-877e-f7fc838255f1', 'NC17.M3.G-CO.14', 1, 'numeric', 'Use theorems about triangles to solve problems', 'In triangle $ABC$, $M$ is the midpoint of $AB$ and $N$ is the midpoint of $AC$. If $BC = 18$ cm, how long is $MN$, in centimeters?', '[]', '9', '18/2', 'The segment joining the midpoints of two sides of a triangle is parallel to the third side and half as long. So $MN = 18 \div 2 = 9$ cm.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midsegment = half of BC = 9.","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b45bcf5-c2b1-4f13-a8b6-02c65ae31e2d', 'NC17.M3.G-CO.14', 2, 'numeric', 'Use theorems about triangles to solve problems', 'In isosceles triangle $ABC$ with $AB = AC$, the base angles are $\angle B = (4x + 6)^\circ$ and $\angle C = (5x - 4)^\circ$. What is the measure of the vertex angle $\angle A$, in degrees?', '[]', '88', '180-2*(4*10+6)', 'Base angles are equal: $4x + 6 = 5x - 4$, so $x = 10$ and each base angle is $4(10) + 6 = 46^\circ$. Then $\angle A = 180^\circ - 2(46^\circ) = 88^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"88","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+6=5x-4, x=10; B=C=46; A=180-92=88.","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83eb7976-f98a-4ced-9d3b-526308d5b844', 'NC17.M3.G-CO.14', 2, 'numeric', 'Use properties of rectangles, rhombi and squares', 'The diagonals of rectangle $ABCD$ meet at $E$, and $\angle BAC = 35^\circ$. What is the measure of $\angle AEB$, in degrees?', '[]', '110', '180-2*35', 'The diagonals of a rectangle are congruent and bisect each other, so $AE = BE$ and triangle $AEB$ is isosceles. Then $\angle EBA = \angle EAB = 35^\circ$ and $\angle AEB = 180^\circ - 2(35^\circ) = 110^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"EA=EB in a rectangle, so angle ABE=35; AEB=180-70=110.","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2717cf06-eb71-4362-8dca-9eeada4567d7', 'NC17.M3.G-CO.14', 2, 'numeric', 'Decide which conclusion about a figure is justified', 'Three vertices of parallelogram $ABCD$ are $A(1, 2)$, $B(6, 2)$ and $C(8, 6)$, with the vertices in order around the figure. The fourth vertex is $D(x, y)$. What is $x + y$?', '[]', '9', '3+6', 'The diagonals of a parallelogram bisect each other, so $AC$ and $BD$ have the same midpoint. The midpoint of $AC$ is $(4.5, 4)$. The midpoint of $BD$ is $\left(\frac{6 + x}{2}, \frac{2 + y}{2}\right)$. So $x = 3$ and $y = 6$, and $x + y = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"D=A+C-B=(3,6); x+y=9.","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1667da89-c70f-42f6-8530-15a581b84c10', 'NC17.M3.G-CO.14', 3, 'numeric', 'Use theorems about triangles to solve problems', 'The exterior angle of a triangle at one vertex measures $(7x - 5)^\circ$. The two remote interior angles measure $(2x + 10)^\circ$ and $(3x + 15)^\circ$. What is the measure of the exterior angle, in degrees?', '[]', '100', '7*15-5', 'The exterior angle equals the sum of the remote interior angles: $7x - 5 = (2x + 10) + (3x + 15) = 5x + 25$. So $2x = 30$ and $x = 15$. The exterior angle is $7(15) - 5 = 100^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x-5=5x+25, x=15; exterior 100 (interiors 40, 60).","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fb22db1-b6d9-484d-bd17-e152d4675390', 'NC17.M3.G-CO.14', 3, 'choice', 'Choose the statement that completes a proof', 'A proof that the diagonals of parallelogram $ABCD$ bisect each other (they meet at $E$) shows $\triangle ABE \cong \triangle CDE$ by ASA, using $AB = CD$ and the alternate interior angles. Which statement comes next, and why?', '["$AE = CE$ and $BE = DE$, by corresponding parts of congruent triangles","$AE = BE$ and $CE = DE$, by corresponding parts of congruent triangles","$AE = CE$ and $BE = DE$, by the reflexive property of equality","$AC = BD$, by corresponding parts of congruent triangles"]', '$AE = CE$ and $BE = DE$, by corresponding parts of congruent triangles', NULL, 'In $\triangle ABE \cong \triangle CDE$ the vertices match $A \to C$, $B \to D$, $E \to E$. So $AE$ corresponds to $CE$ and $BE$ to $DE$, and corresponding parts of congruent triangles are congruent. That shows each diagonal is cut in half by the other.', 'checked', '{"lint":[],"solve":{"answer":"$AE = CE$ and $BE = DE$, by corresponding parts of congruent triangles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"CPCTC: AE corresponds to CE, BE to DE.","run_id":"claude-code","at":"2026-10-24T08:43:49.175Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('287dc98f-ae8d-43a5-b42a-a8d4134fffb3', 'NC17.M3.G-C.2', 1, 'choice', 'Inscribed angle and its arc', 'An inscribed angle in a circle intercepts an arc that measures $80^\circ$. What is the measure of the inscribed angle?', '["$40^\\circ$","$80^\\circ$","$160^\\circ$","$100^\\circ$"]', '$40^\circ$', NULL, 'An inscribed angle is half of its intercepted arc: $80 \div 2 = 40$. Choosing $80^\circ$ treats it like a central angle, and $160^\circ$ doubles instead of halving.', 'checked', '{"lint":[],"solve":{"answer":"$40^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inscribed angle = half its arc = 80/2 = 40.","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a67cbe9c-6a49-4d4e-b747-ef3fe4718846', 'NC17.M3.G-C.2', 1, 'choice', 'Tangent is perpendicular to the radius', 'A tangent line touches a circle at point $P$, and $O$ is the center of the circle. Which statement is true?', '["Radius $\\overline{OP}$ is parallel to the tangent line.","Radius $\\overline{OP}$ makes a $45^\\circ$ angle with the tangent line.","Radius $\\overline{OP}$ is perpendicular to the tangent line.","Radius $\\overline{OP}$ cuts the tangent line into two equal parts."]', 'Radius $\overline{OP}$ is perpendicular to the tangent line.', NULL, 'A radius drawn to the point of tangency is perpendicular to the tangent line.', 'checked', '{"lint":[],"solve":{"answer":"Radius $\\overline{OP}$ is perpendicular to the tangent line.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A tangent is perpendicular to the radius at the point of tangency.","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4aa7b564-62e0-473d-a231-a1e8b891f8fc', 'NC17.M3.G-C.2', 1, 'choice', 'Angles of an inscribed quadrilateral', 'Quadrilateral $ABCD$ is inscribed in a circle, and $\angle A = 100^\circ$. What is the measure of $\angle C$?', '["$100^\\circ$","$260^\\circ$","$50^\\circ$","$80^\\circ$"]', '$80^\circ$', NULL, 'Opposite angles of an inscribed quadrilateral add up to $180^\circ$, so $\angle C = 180 - 100 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"$80^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite angles of a cyclic quadrilateral are supplementary: C = 180 - 100 = 80.","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40915295-4c37-48a6-a876-7240e4c78068', 'NC17.M3.G-C.2', 2, 'numeric', 'Inscribed angle and its arc', 'An inscribed angle measures $(3x + 5)^\circ$ and intercepts an arc that measures $(8x - 10)^\circ$. What is $x$?', '[]', '10', '(10+10)/(8-6)', 'The angle is half the arc: $3x + 5 = \frac{8x - 10}{2} = 4x - 5$. Then $10 = x$. Check: the angle is $35^\circ$ and the arc is $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+5 = (8x-10)/2 = 4x-5 -> x = 10 (angle 35, arc 70).","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ffe0756-710e-40f4-9bbd-7eb467ef0684', 'NC17.M3.G-C.2', 2, 'numeric', 'Angles of an inscribed quadrilateral', 'Quadrilateral $ABCD$ is inscribed in a circle. $\angle A = (2x + 10)^\circ$ and $\angle C = (3x - 20)^\circ$. What is the measure of $\angle A$, in degrees?', '[]', '86', '2*190/5+10', 'Opposite angles are supplementary: $(2x + 10) + (3x - 20) = 180$, so $5x = 190$ and $x = 38$. Then $\angle A = 2(38) + 10 = 86$.', 'checked', '{"lint":[],"solve":{"answer":"86","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A + C = 180: 5x - 10 = 180 -> x = 38; A = 2(38)+10 = 86 (C = 94).","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0de1f99b-5289-4be1-81dd-5e887e6720d7', 'NC17.M3.G-C.2', 2, 'numeric', 'Inscribed angles on the same arc', 'Inscribed angles $\angle ACB$ and $\angle ADB$ intercept the same arc $AB$. $\angle ACB = (4x + 2)^\circ$ and $\angle ADB = (6x - 18)^\circ$. What is the measure of $\angle ACB$, in degrees?', '[]', '42', '4*10+2', 'Inscribed angles on the same arc are equal: $4x + 2 = 6x - 18$, so $x = 10$. Then $\angle ACB = 4(10) + 2 = 42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same arc -> equal: 4x+2 = 6x-18 -> x = 10; angle ACB = 42.","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04057710-7a4c-4acd-91bb-0682fdc87e6d', 'NC17.M3.G-C.2', 3, 'numeric', 'Secant and tangent lengths', 'From point $P$ outside a circle, one secant meets the circle at $A$ and $B$, with $A$ nearer to $P$, $PA = 3$ and $AB = 9$. A second secant meets the circle at $C$ and $D$, with $C$ nearer to $P$ and $PC = 4$. What is the length of $\overline{CD}$?', '[]', '5', '3*(3+9)/4-4', 'Whole secant times outside part is the same for both: $PA \cdot PB = 3 \cdot 12 = 36$. So $PC \cdot PD = 4 \cdot PD = 36$ and $PD = 9$. Then $CD = 9 - 4 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PA*PB = PC*PD: 3*12 = 36 = 4*PD -> PD = 9; CD = 9-4 = 5.","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03f06d9a-096e-4e4c-ac52-60c6e417a90a', 'NC17.M3.G-C.2', 3, 'numeric', 'Angles of an inscribed quadrilateral', 'Quadrilateral $ABCD$ is inscribed in a circle. Arcs $AB$, $BC$, $CD$ and $DA$ measure $70^\circ$, $80^\circ$, $110^\circ$ and $100^\circ$. What is the measure of $\angle ABC$, in degrees?', '[]', '105', '(110+100)/2', '$\angle ABC$ is inscribed and intercepts the arc from $A$ to $C$ that does not contain $B$. That arc is $CD + DA = 110 + 100 = 210$, and half of it is $105$.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Arcs sum to 360. Angle ABC intercepts arc ADC = CD + DA = 110+100 = 210, so ABC = 105.","run_id":"claude-code","at":"2026-10-24T08:41:07.677Z"}}', 'ai', NULL, NULL)
