INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3cbcfec-1489-47e7-b829-d93348174c8c', 'NC17.M3.G-C.5', 1, 'numeric', 'Radian measure is arc length divided by radius', 'A central angle of a circle with radius 5 cm cuts off an arc 15 cm long. What is the radian measure of the angle?', '[]', '3', '15/5', 'Radian measure is arc length divided by radius: $\frac{15}{5} = 3$ radians.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"theta = 15/5 = 3.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8809e329-fc6a-47b9-a3c6-b3b5c61ef256', 'NC17.M3.G-C.5', 1, 'numeric', 'Radius from arc length and a radian angle', 'An arc 12 cm long has a central angle of 3 radians. What is the radius of the circle, in centimeters?', '[]', '4', '12/3', 'From $s = r\theta$, $r = \frac{s}{\theta} = \frac{12}{3} = 4$ cm.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 12/3 = 4.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86f515e3-9522-4fb9-9d18-f67cf86d02c7', 'NC17.M3.G-C.5', 1, 'numeric', 'Arc length from a central angle in degrees', 'A circle has a radius of 10 cm. An arc of the circle has a central angle of $90^\circ$ and a length of $k\pi$ centimeters. What is $k$?', '[]', '5', '2*10*90/360', 'The arc is $\frac{90}{360} = \frac{1}{4}$ of the circumference $2\pi \cdot 10 = 20\pi$, so it is $5\pi$ cm and $k = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90/360 * 20pi = 5pi, k = 5.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f500717-32bd-4c87-902e-4202e3a7d9dd', 'NC17.M3.G-C.5', 2, 'numeric', 'Arc length from a central angle in degrees', 'A circle has a radius of 12 m. An arc has a central angle of $150^\circ$. Use 3.14 for $\pi$. How long is the arc, in meters?', '[]', '31.4', '2*3.14*12*150/360', 'The arc is $\frac{150}{360} = \frac{5}{12}$ of the circumference. Circumference: $2 \cdot 3.14 \cdot 12 = 75.36$ m. Then $\frac{5}{12} \cdot 75.36 = 31.4$ m.', 'checked', '{"lint":[],"solve":{"answer":"31.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/360 * 2*3.14*12 = (5/12)*75.36 = 31.4.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a9f11af-49fb-43a9-a121-83dd07e351c5', 'NC17.M3.G-C.5', 2, 'choice', 'Sector area from a radian angle', 'A sector has a radius of 10 cm and a central angle of $\frac{3}{5}$ radian. What is its area, in square centimeters?', '["60","3","30","15"]', '30', '0.5*10^2*3/5', 'Area $= \frac{1}{2}r^2\theta = \frac{1}{2} \cdot 100 \cdot \frac{3}{5} = 30$. Leaving out the $\frac{1}{2}$ gives 60, using $r$ instead of $r^2$ gives 3, and halving twice gives 15.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 1/2*100*3/5 = 30.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15b7d3f8-366f-4a81-b0bd-bdccba0f3e93', 'NC17.M3.G-C.5', 2, 'choice', 'Sector area from a central angle in degrees', 'A sector of a circle has a radius of 6 cm and a central angle of $150^\circ$. What is the area of the sector, in square centimeters?', '["$15\\pi$","$5\\pi$","$30\\pi$","$\\dfrac{15\\pi}{2}$"]', '$15\pi$', NULL, 'The sector is $\frac{150}{360} = \frac{5}{12}$ of the circle, whose area is $36\pi$: $\frac{5}{12} \cdot 36\pi = 15\pi$. The value $5\pi$ is the arc length, and the others come from dividing by the wrong amount.', 'checked', '{"lint":[],"solve":{"answer":"$15\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150/360 * 36pi = 15pi.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4876cd0f-9f14-478a-b55a-4f6dc7f05754', 'NC17.M3.G-C.5', 3, 'numeric', 'Arc length from the radius and a radian angle', 'Two circles share a center. A central angle of $\frac{5}{3}$ radians cuts off an arc on each circle. The radii are 6 cm and 9 cm. How much longer, in centimeters, is the arc on the larger circle?', '[]', '5', '9*5/3-6*5/3', 'The arcs are $9 \cdot \frac{5}{3} = 15$ cm and $6 \cdot \frac{5}{3} = 10$ cm. The difference is $15 - 10 = 5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9*(5/3) - 6*(5/3) = 15 - 10 = 5.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36240c65-37b3-4d6b-8b68-2807474db30f', 'NC17.M3.G-C.5', 3, 'choice', 'Arc length from a central angle in degrees', 'A circular garden has a radius of 18 meters. A path follows the edge of the garden along an arc with a central angle of $40^\circ$. What is the length of the path, in meters?', '["$4\\pi$","$2\\pi$","$8\\pi$","$36\\pi$"]', '$4\pi$', NULL, 'The path is $\frac{40}{360} = \frac{1}{9}$ of the circumference $2\pi \cdot 18 = 36\pi$, so it is $4\pi$ m. Using $\pi r$ gives $2\pi$, using the diameter as the radius gives $8\pi$, and $36\pi$ is the whole circumference.', 'checked', '{"lint":[],"solve":{"answer":"$4\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40/360 * 36pi = 4pi.","run_id":"claude-code","at":"2026-10-24T08:44:12.928Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95f1948a-38e8-4c74-93fe-fdde448d6364', 'NC17.M3.G-GPE.1', 1, 'numeric', 'Center of a circle by completing the square', 'What is the x-coordinate of the center of the circle $(x - 3)^2 + (y + 2)^2 = 16$?', '[]', '3', '3', 'In $(x - h)^2 + (y - k)^2 = r^2$ the center is $(h, k)$. Here $h = 3$ and $k = -2$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Center (3, -2); x-coordinate 3.","run_id":"claude-code","at":"2026-10-28T18:47:12.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52fbd1df-7c0b-4944-bc7f-0bdc98b519ac', 'NC17.M3.G-GPE.1', 1, 'numeric', 'Radius of a circle by completing the square', 'What is the radius of the circle $(x - 1)^2 + y^2 = 49$?', '[]', '7', '7', 'The right side is $r^2 = 49$, so $r = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r^2 = 49, r = 7.","run_id":"claude-code","at":"2026-10-28T18:48:28.284Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8db2b2db-ea6f-40c6-8e82-fa7054360cae', 'NC17.M3.G-GPE.1', 1, 'choice', 'Radius and equation of a circle from the Pythagorean Theorem', 'To derive the equation of a circle with center $(h, k)$ and radius $r$, draw a right triangle from the center to a point $(x, y)$ on the circle, with legs parallel to the axes. What is the length of the hypotenuse?', '["$r$","$r^2$","$x - h$","$(x - h) + (y - k)$"]', '$r$', NULL, 'The hypotenuse is the segment from the center to the point on the circle. That is a radius, so its length is $r$. The legs have lengths $|x - h|$ and $|y - k|$.', 'checked', '{"lint":[],"solve":{"answer":"$r$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The hypotenuse joins the center to a point on the circle, so it is the radius r.","run_id":"claude-code","at":"2026-10-28T18:48:28.290Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d3cc93c-2489-4a6d-bc59-df5d29bd7045', 'NC17.M3.G-GPE.1', 2, 'choice', 'Radius and equation of a circle from the Pythagorean Theorem', 'A circle has center $(1, -2)$ and passes through the point $(4, 2)$. Which is its equation?', '["$(x - 1)^2 + (y + 2)^2 = 5$","$(x - 1)^2 + (y + 2)^2 = 7$","$(x - 1)^2 + (y + 2)^2 = 25$","$(x + 1)^2 + (y - 2)^2 = 25$"]', '$(x - 1)^2 + (y + 2)^2 = 25$', NULL, 'The legs are $4 - 1 = 3$ and $2 - (-2) = 4$, so $r^2 = 3^2 + 4^2 = 25$. The center is $(1, -2)$, giving $(x - 1)^2 + (y + 2)^2 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"$(x - 1)^2 + (y + 2)^2 = 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r^2 = (4-1)^2 + (2+2)^2 = 9 + 16 = 25. (x-1)^2+(y+2)^2 = 25.","run_id":"claude-code","at":"2026-10-28T18:48:28.030Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a39c28b-2230-4463-a403-29c957876ecf', 'NC17.M3.G-GPE.1', 2, 'numeric', 'Radius of a circle by completing the square', 'The circle $x^2 + y^2 - 6x + 4y - 12 = 0$ has what radius?', '[]', '5', '5', 'Complete the square: $(x^2 - 6x + 9) + (y^2 + 4y + 4) = 12 + 9 + 4 = 25$. So $(x - 3)^2 + (y + 2)^2 = 25$ and $r = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-3)^2-9+(y+2)^2-4-12=0 -> (x-3)^2+(y+2)^2=25, r=5.","run_id":"claude-code","at":"2026-10-28T18:48:28.379Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e3fa26b-3178-4e81-b6dd-25013248a24b', 'NC17.M3.G-GPE.1', 2, 'choice', 'Equation of a circle from its center and radius', 'A circle has center $(-4, 1)$ and radius 6. Which is its equation?', '["$(x + 4)^2 + (y - 1)^2 = 36$","$(x - 4)^2 + (y + 1)^2 = 36$","$(x + 4)^2 + (y - 1)^2 = 6$","$(x + 4)^2 + (y - 1)^2 = 12$"]', '$(x + 4)^2 + (y - 1)^2 = 36$', NULL, 'Use $(x - h)^2 + (y - k)^2 = r^2$. Since $h = -4$, $x - h = x + 4$. Since $k = 1$, the y part is $y - 1$. Also $r^2 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"$(x + 4)^2 + (y - 1)^2 = 36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+4)^2+(y-1)^2=36.","run_id":"claude-code","at":"2026-10-28T18:48:28.502Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4240fa8a-ea35-4f2b-8665-4e10e3cc21d6', 'NC17.M3.G-GPE.1', 3, 'choice', 'Center of a circle by completing the square', 'What is the center of the circle $2x^2 + 2y^2 - 8x + 12y - 8 = 0$?', '["$(4, -6)$","$(2, -3)$","$(-2, 3)$","$(-4, 6)$"]', '$(2, -3)$', NULL, 'Divide every term by 2: $x^2 + y^2 - 4x + 6y - 4 = 0$. Complete the square: $(x - 2)^2 + (y + 3)^2 = 4 + 4 + 9 = 17$. The center is $(2, -3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by 2: x^2+y^2-4x+6y-4=0 -> (x-2)^2+(y+3)^2=17. Center (2,-3).","run_id":"claude-code","at":"2026-10-28T18:48:28.051Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('317d12c2-60cd-49ea-9ce5-91287da62a3c', 'NC17.M3.G-GPE.1', 3, 'choice', 'Points on, inside and outside a circle', 'Which point is on the circle $x^2 + y^2 - 4x - 2y - 4 = 0$?', '["$(2, 5)$","$(5, 1)$","$(0, 0)$","$(4, 3)$"]', '$(5, 1)$', NULL, 'Complete the square: $(x - 2)^2 + (y - 1)^2 = 9$. For $(5, 1)$: $3^2 + 0^2 = 9$, so it is on the circle. $(2, 5)$ gives 16 and $(0, 0)$ gives 5, both not 9; $(4, 3)$ gives 8.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complete the square: (x-2)^2 + (y-1)^2 = 9. (5,1): 9+0 = 9 yes. (0,0): 5; (2,5): 16; (4,3): 8.","run_id":"claude-code","at":"2026-10-28T18:48:28.265Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25dd8aaf-d741-4cef-8231-e3bb36fc3307', 'NC17.M3.G-GMD.3', 1, 'choice', 'Volume of a sphere', 'Which expression gives the volume of a sphere with radius $r$?', '["$4\\pi r^2$","$\\frac{4}{3}\\pi r^2$","$\\frac{4}{3}\\pi r^3$","$\\frac{1}{3}\\pi r^3$"]', '$\frac{4}{3}\pi r^3$', NULL, 'The volume of a sphere is $\frac{4}{3}\pi r^3$. The expression $4\pi r^2$ is its surface area.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{3}\\pi r^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sphere volume is (4/3)πr^3.","run_id":"claude-code","at":"2026-10-28T18:48:27.997Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a437783-6dce-4ef9-a572-661d5f3cdfc2', 'NC17.M3.G-GMD.3', 1, 'numeric', 'Volume of a cone', 'A cone and a cylinder have the same base and the same height. The cylinder has a volume of 90 cubic centimeters. What is the volume of the cone in cubic centimeters?', '[]', '30', '90/3', 'A cone holds one third as much as a cylinder with the same base and height: $90 \div 3 = 30$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone = 1/3 of cylinder: 90/3 = 30.","run_id":"claude-code","at":"2026-10-28T18:48:28.165Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('344ba749-d2fd-493f-81c5-d6dc5c9f9ade', 'NC17.M3.G-GMD.3', 1, 'choice', 'Volume of a cylinder', 'A cylinder has a radius of 3 inches and a height of 5 inches. What is its volume in cubic inches?', '["$15\\pi$","$45\\pi$","$30\\pi$","$180\\pi$"]', '$45\pi$', NULL, '$V = \pi r^2 h = \pi (3^2)(5) = 45\pi$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"$45\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = pi r^2 h = pi x 9 x 5 = 45 pi.","run_id":"claude-code","at":"2026-10-28T18:48:28.332Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cdc1e86-53bb-415f-a76e-726987682d4c', 'NC17.M3.G-GMD.3', 2, 'numeric', 'Use a volume to find a dimension', 'A cylinder has a volume of $200\pi$ cubic centimeters and a radius of 5 centimeters. What is its height in centimeters?', '[]', '8', '200/25', '$V = \pi r^2 h$, so $200\pi = \pi (25) h$ and $h = 200 \div 25 = 8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi x 25 x h = 200pi, h=8.","run_id":"claude-code","at":"2026-10-28T18:48:27.952Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18ca2f82-4e2b-44a0-8559-60622b612785', 'NC17.M3.G-GMD.3', 2, 'choice', 'Use a volume to find a dimension', 'An ice cream cone has a radius of 4 centimeters and holds $80\pi$ cubic centimeters when full to the top. What is the height of the cone in centimeters?', '["$15$","$5$","$7.5$","$30$"]', '$15$', '80*3/16', '$\frac{1}{3}\pi (16) h = 80\pi$, so $16h = 240$ and $h = 15$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/3)pi(16)h = 80pi -> 16h = 240 -> h = 15.","run_id":"claude-code","at":"2026-10-28T18:48:28.061Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d035bfa-3580-4189-8f7e-8cde822669c4', 'NC17.M3.G-GMD.3', 2, 'choice', 'Use a volume to find a dimension', 'A square pyramid has a volume of 100 cubic meters and a base with sides of 5 meters. What is its height in meters?', '["$4$","$20$","$60$","$12$"]', '$12$', '100*3/25', '$\frac{1}{3}(25)h = 100$, so $25h = 300$ and $h = 12$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(25)h = 100, h = 12.","run_id":"claude-code","at":"2026-10-28T18:48:28.367Z"}}', 'ai', NULL, NULL)
