INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('024b37c0-a213-4a9b-be9b-070fc48a491a', 'NC17.M3.G-GMD.3', 3, 'choice', 'Use a volume to find a dimension', 'A sphere has a volume of $972\pi$ cubic inches. What is its radius in inches?', '["$9$","$27$","$18$","$3$"]', '$9$', NULL, '$\frac{4}{3}\pi r^3 = 972\pi$, so $r^3 = 972 \cdot \frac{3}{4} = 729$. Since $9^3 = 729$, $r = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4/3)πr^3 = 972π → r^3 = 729 → r = 9.","run_id":"claude-code","at":"2026-10-28T18:47:12.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c0f20d2-6758-48c7-8e71-9a437f197628', 'NC17.M3.G-GMD.3', 3, 'choice', 'Volume of a cone', 'A cone fits exactly inside a cylinder: they share the same base and the same height. The radius is 3 meters, and the space inside the cylinder but outside the cone has a volume of $48\pi$ cubic meters. What is the height in meters?', '["$16$","$4$","$24$","$8$"]', '$8$', NULL, 'The space is $\pi r^2 h - \frac{1}{3}\pi r^2 h = \frac{2}{3}\pi (9) h = 6\pi h$. Setting $6\pi h = 48\pi$ gives $h = 8$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder - cone = (2/3)pi r^2 h = (2/3)(9pi)h = 6pi h = 48pi -> h = 8.","run_id":"claude-code","at":"2026-10-28T18:48:27.918Z"}}', 'ai', NULL, NULL)
