INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('149a71a5-e34d-4cdf-af0e-bb04e59c6a8f', 'NC17.M3.G-GMD.4', 1, 'numeric', 'Measure a cross-section of a prism, pyramid or cylinder', 'A cube has edges of length 6 centimeters. A plane cuts it parallel to one of its faces. What is the area, in square centimeters, of the cross-section?', '[]', '36', '6^2', 'The cross-section is a square the same size as a face, with side 6. Its area is $6^2 = 36$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The cross-section is a square congruent to a face, 6 by 6, area 36.","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28304905-077b-4835-a78a-f2dd42d73f17', 'NC17.M3.G-GMD.4', 1, 'choice', 'Name the cross-section of a solid', 'Which shape results when a plane cuts a cone parallel to its base?', '["Circle","Triangle","Rectangle","Square"]', 'Circle', NULL, 'Parallel to the base, the slice is a circle that gets smaller the closer the plane is to the tip. It is a circle, not a triangle, which is what a cut through the tip and base gives.', 'checked', '{"lint":[],"solve":{"answer":"Circle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A section of a cone parallel to its base is a circle (smaller than the base).","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12d62a06-2d9e-46d3-afbe-40e643676119', 'NC17.M3.G-GMD.4', 1, 'numeric', 'Measure a circular cross-section', 'A sphere has a diameter of 18 centimeters. A plane passes through its center. What is the radius, in centimeters, of the circular cross-section?', '[]', '9', '18/2', 'A plane through the center cuts the sphere in its largest circle, which has the same radius as the sphere. The radius is $18 \div 2 = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A plane through the centre gives a great circle, with the sphere''s radius: 18/2 = 9.","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17cc2103-d2fd-445b-8927-091e76732ff6', 'NC17.M3.G-GMD.4', 2, 'numeric', 'Measure a circular cross-section', 'A sphere has a radius of 13 centimeters. A plane cuts it at a distance of 5 centimeters from the center. What is the radius, in centimeters, of the circular cross-section?', '[]', '12', '(13^2-5^2)/12', 'The radius of the sphere, the distance 5 to the plane and the radius of the circle form a right triangle with hypotenuse 13. The circle radius is $\sqrt{13^2 - 5^2} = \sqrt{144} = 12$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r^2 = 13^2 - 5^2 = 169 - 25 = 144, r = 12.","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa61144-d745-44e5-b184-987421fa9408', 'NC17.M3.G-GMD.4', 2, 'numeric', 'Measure a cross-section of a prism, pyramid or cylinder', 'A cylinder has a radius of 5 centimeters and a height of 12 centimeters. A plane cuts it through the axis, perpendicular to the bases. What is the area, in square centimeters, of the cross-section?', '[]', '120', '2*5*12', 'The cross-section is a rectangle. Its width is the diameter, $2 \times 5 = 10$, and its height is 12. The area is $10 \times 12 = 120$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Section through the axis is a rectangle of width = diameter 10 and height 12: area 120.","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('149d8022-f827-4b38-b70b-822886b89610', 'NC17.M3.G-GMD.4', 2, 'numeric', 'Measure a solid formed by rotation', 'A right triangle with legs of 6 centimeters and 8 centimeters is rotated $360^\circ$ about its 8-centimeter leg. What is the slant height, in centimeters, of the cone it forms?', '[]', '10', '(6^2+8^2)/10', 'The cone has radius 6 and height 8. Its slant height is the hypotenuse of the triangle, $\sqrt{6^2 + 8^2} = \sqrt{100} = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height 8, radius 6; slant height = hypotenuse = sqrt(36+64) = 10.","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07220a9e-c1e2-4ea7-ac0b-06c127f5f123', 'NC17.M3.G-GMD.4', 3, 'numeric', 'Measure a circular cross-section', 'A cone has a base radius of 10 centimeters and a height of 12 centimeters. A plane cuts it parallel to the base, 3 centimeters above the base. What is the radius, in centimeters, of the circular cross-section?', '[]', '7.5', '10*9/12', 'The plane is $12 - 3 = 9$ centimeters below the tip. The small cone cut off at the tip is similar to the whole cone, so its radius is $10 \times \frac{9}{12} = 7.5$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 cm above the base is 9 cm below the apex. Radius scales: 10 * 9/12 = 7.5.","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14ffff99-2793-45e5-9902-78f2b10a8da0', 'NC17.M3.G-GMD.4', 3, 'choice', 'Name the solid formed by rotating a flat shape', 'A circle is rotated $360^\circ$ about a line in its own plane that does not touch the circle. Which solid does it form?', '["A sphere","A cylinder","A hollow sphere","A doughnut shape (a torus)"]', 'A doughnut shape (a torus)', NULL, 'Each point of the circle travels around the line in a circle of its own, and the line does not touch the circle, so there is a hole in the middle. The solid is a doughnut shape, called a torus.', 'checked', '{"lint":[],"solve":{"answer":"A doughnut shape (a torus)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A circle revolved about a coplanar line not meeting it sweeps a torus (doughnut).","run_id":"claude-code","at":"2026-10-24T08:47:34.385Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d711b45-e8bc-4126-8cc7-bf72d13f2253', 'NC17.M3.G-MG.1', 1, 'numeric', 'Population density', 'A town has 12,000 people living on 8 square miles of land. What is its population density, in people per square mile?', '[]', '1500', '12000/8', 'Population density = people / area = 12000 / 8 = 1500 people per square mile.', 'checked', '{"lint":[],"solve":{"answer":"1500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12000/8 = 1500 people per square mile.","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17e989c6-07c8-4cb4-a3f8-0ef49c4dcbbe', 'NC17.M3.G-MG.1', 1, 'choice', 'Volume of a real object', 'A cylindrical can has a radius of 3 centimeters and a height of 10 centimeters. What is its volume in cubic centimeters?', '["$90\\pi$","$30\\pi$","$60\\pi$","$360\\pi$"]', '$90\pi$', NULL, 'Volume = $\pi r^2 h$ = $\pi \cdot 3^2 \cdot 10 = 90\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$90\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = pi r^2 h = pi*9*10 = 90pi.","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('370861f2-ab5a-473a-b7d7-53c9aff87504', 'NC17.M3.G-MG.1', 1, 'choice', 'Volume as a function of one variable', 'A box is made from a 20-inch by 12-inch sheet of cardboard by cutting a square of side $x$ inches from each corner and folding up the sides. Which function gives the volume of the box?', '["$V(x) = x(20-2x)(12-2x)$","$V(x) = x(20-x)(12-x)$","$V(x) = (20-2x)(12-2x)$","$V(x) = x(20-2x)(12-x)$"]', '$V(x) = x(20-2x)(12-2x)$', NULL, 'The height is $x$. Cutting $x$ from both ends removes $2x$ from each side, so the base is $(20-2x)$ by $(12-2x)$. Volume = base x height.', 'checked', '{"lint":[],"solve":{"answer":"$V(x) = x(20-2x)(12-2x)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base becomes (20-2x) by (12-2x), height x, so V = x(20-2x)(12-2x).","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f04c845-5b6b-49dd-91a2-a0c89c167c14', 'NC17.M3.G-MG.1', 2, 'numeric', 'Density from mass and volume', 'A solid gold bar is 10 centimeters long, 5 centimeters wide and 2 centimeters tall. Gold has a density of 19.3 grams per cubic centimeter. What is the mass of the bar in grams?', '[]', '1930', '10*5*2*19.3', 'Volume = 10 x 5 x 2 = 100 cubic centimeters. Mass = density x volume = 19.3 x 100 = 1930 grams.', 'checked', '{"lint":[],"solve":{"answer":"1930","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 10*5*2 = 100 cm^3; mass = 100*19.3 = 1930 g.","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('332031bf-cb34-4f62-9bf9-645db79c91a0', 'NC17.M3.G-MG.1', 2, 'numeric', 'Perimeter, surface area and cost', 'An open-top box (no lid) is 4 feet long, 3 feet wide and 2 feet tall. Its material costs 3 dollars per square foot. How many dollars does the material for the box cost?', '[]', '120', '(4*3+2*4*2+2*3*2)*3', 'Base: 4 x 3 = 12. Two long sides: 2 x (4 x 2) = 16. Two short sides: 2 x (3 x 2) = 12. Total 40 square feet, and 40 x 3 = 120 dollars.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 4*3 = 12; two sides 4*2 = 8 each (16); two ends 3*2 = 6 each (12). Total 40 sq ft; cost 40*3 = 120.","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cb6ebeb-10ad-46b2-8b80-441b8c748583', 'NC17.M3.G-MG.1', 2, 'choice', 'Scaling a design', 'A cylindrical tank has its radius doubled while its height stays the same. By what factor is its volume multiplied?', '["$4$","$2$","$8$","$16$"]', '$4$', NULL, 'Volume = $\pi r^2 h$. Doubling r multiplies $r^2$ by 4, so the volume is multiplied by 4.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = pi r^2 h; (2r)^2 = 4r^2, so volume is multiplied by 4.","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48a7041e-402d-4ebb-b4a8-c137d8198614', 'NC17.M3.G-MG.1', 3, 'choice', 'Optimizing a design', 'An open-top box with a square base of side $x$ meters has a volume of 32 cubic meters. Its surface area is $S(x) = x^2 + \frac{128}{x}$ square meters. Which value of $x$ gives the smallest surface area?', '["2 m","8 m","4 m","16 m"]', '4 m', NULL, 'S(2) = 4 + 64 = 68. S(4) = 16 + 32 = 48. S(8) = 64 + 16 = 80. S(16) = 256 + 8 = 264. The smallest is at x = 4.', 'checked', '{"lint":[],"solve":{"answer":"4 m","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S''(x) = 2x - 128/x^2 = 0 gives x^3 = 64, x = 4. Check: S(2)=68, S(4)=48, S(8)=80, S(16)=264. Smallest at 4.","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23107ec0-3efe-4a48-9277-81b1689800c6', 'NC17.M3.G-MG.1', 3, 'choice', 'Population density', 'City A has 90,000 people on 30 square kilometers. City B has 64,000 people on 16 square kilometers. Which statement is true?', '["City A is denser, with 3000 people per square kilometer against 4000","City B is denser, with 4000 people per square kilometer against 3000","City A is denser, because it has more people in total","City B is denser, with 400 people per square kilometer against 300"]', 'City B is denser, with 4000 people per square kilometer against 3000', NULL, 'City A: 90000 / 30 = 3000 per square kilometer. City B: 64000 / 16 = 4000 per square kilometer. City B is denser.', 'checked', '{"lint":[],"solve":{"answer":"City B is denser, with 4000 people per square kilometer against 3000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 90000/30 = 3000; B: 64000/16 = 4000. B is denser.","run_id":"claude-code","at":"2026-10-24T08:44:31.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37290ca2-dbc6-4d14-b4b4-9ce799a30a1a', 'NC17.M3.S-IC.1', 1, 'choice', 'Population and sample', 'A city has 50,000 voters. A poll of 400 randomly chosen voters finds that 56% favor a new bridge. Which of these is a sample statistic?', '["The 50,000 voters in the city","The 400 voters who were polled","The 56% of polled voters who favor the bridge","The percent of all voters who favor the bridge"]', 'The 56% of polled voters who favor the bridge', NULL, 'A statistic is a number computed from a sample. The 56% comes from the 400 polled voters. The percent of all voters is the unknown population value.', 'checked', '{"lint":[],"solve":{"answer":"The 56% of polled voters who favor the bridge","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistic describes the sample: the 56% of the 400 polled.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a4f2a8e-d116-4e0d-9ac6-76387fa9e25b', 'NC17.M3.S-IC.1', 1, 'numeric', 'Estimate a count in the population from a sample', 'An inspector randomly picks 60 light bulbs from a shipment of 2,000 bulbs. Three of the 60 are defective. Estimate how many bulbs in the shipment are defective.', '[]', '100', '3/60*2000', '3 of 60 is $\frac{1}{20}$, or 5%. Estimate 5% of 2,000: $\frac{1}{20} \times 2000 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/60 = 1/20; 2000/20 = 100.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22732661-682d-453d-9015-8540b4277189', 'NC17.M3.S-IC.1', 1, 'numeric', 'Estimate a percent or fraction from a sample', 'A random sample of 50 apples from a truckload contains 2 bruised apples. Estimate the percent of all the apples in the truckload that are bruised.', '[]', '4', '2/50*100', '$\frac{2}{50} = 0.04$, which is 4%. Estimate that 4% of the apples in the truckload are bruised.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/50 = 0.04 = 4%.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('113a8cb6-1871-47ef-b133-612f790ecf6a', 'NC17.M3.S-IC.1', 2, 'choice', 'What a sample can and cannot tell us', 'A random sample of 100 students from a school of 1,500 finds that 62 of them prefer to take tests online. Which conclusion is best supported?', '["About 62% of all students probably prefer online tests","Exactly 930 students at the school prefer online tests","Exactly 62 students at the school prefer online tests","Students at every other school also prefer online tests"]', 'About 62% of all students probably prefer online tests', NULL, 'The sample suggests about 62% of the school prefers online tests, though the true value may be a little different. It cannot give an exact count, and it says nothing about other schools.', 'checked', '{"lint":[],"solve":{"answer":"About 62% of all students probably prefer online tests","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"62/100 = 62% is an estimate for the school, not exact, and not for other schools.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dea9c52-1be8-4b1a-a7e9-1eea58d8039f', 'NC17.M3.S-IC.1', 2, 'choice', 'Random and biased sampling', 'Why do statisticians prefer a random sample to a sample of volunteers?', '["Volunteers are usually too busy to answer the questions","A random sample is always larger than a volunteer sample","A random sample always matches the population exactly","Random selection favors no part of the population"]', 'Random selection favors no part of the population', NULL, 'Volunteers often share a strong opinion, which can skew results. A random sample gives every member a fair chance, so it tends to represent the population.', 'checked', '{"lint":[],"solve":{"answer":"Random selection favors no part of the population","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random selection avoids favoring any part of the population; volunteers self-select.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fea87b1-3b51-4f2f-8dd8-5bfd916764ad', 'NC17.M3.S-IC.1', 2, 'numeric', 'Estimate a mean or total from a sample', 'A town has 5,000 households. A random sample of 8 households has 2, 0, 3, 1, 4, 2, 1 and 3 pets. Use the sample mean to estimate the total number of pets in all 5,000 households.', '[]', '10000', '(2+0+3+1+4+2+1+3)/8*5000', 'The sample total is 16 pets, so the mean is $\frac{16}{8} = 2$ pets per household. Estimate $2 \times 5000 = 10000$ pets.', 'checked', '{"lint":[],"solve":{"answer":"10000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 2+0+3+1+4+2+1+3 = 16; mean = 2; 2 x 5000 = 10000.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fa039db-befd-4f60-a9ab-fbd0f5298715', 'NC17.M3.S-IC.1', 3, 'choice', 'Random and biased sampling', 'A student council wants honest opinions about the cafeteria. Which survey question is most likely to bias the answers?', '["How would you rate the cafeteria on a scale from 1 to 5?","Which meal served in the cafeteria do you like best?","Do you agree that the awful cafeteria must be fixed?","How many days a week do you eat lunch in the cafeteria?"]', 'Do you agree that the awful cafeteria must be fixed?', NULL, 'The wording "awful, crowded" pushes people toward agreeing. A fair question uses neutral words, even if the sample itself is random.', 'checked', '{"lint":[],"solve":{"answer":"Do you agree that the awful cafeteria must be fixed?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"\"awful\" and \"must be fixed\" lead the respondent.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2efe9d62-1480-4d4e-af27-55c5399593ef', 'NC17.M3.S-IC.1', 3, 'numeric', 'Sampling variability and sample size', 'Five random samples of 25 students each are taken from the same large school. Their mean test scores are 71, 68, 74, 70 and 67. Combine the five samples to give the best single estimate of the mean test score of the whole school.', '[]', '70', '(71+68+74+70+67)/5', 'All samples are the same size, so the combined mean is the average of the five means: $\frac{71+68+74+70+67}{5} = \frac{350}{5} = 70$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal sample sizes (25 each), so the pooled mean is the mean of the means: (71+68+74+70+67)/5 = 350/5 = 70.","run_id":"claude-code","at":"2026-10-24T08:45:27.438Z"}}', 'ai', NULL, NULL)
