INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aff27b7-e937-48a1-9117-d770e4859c82', 'NC17.M4.AF.1', 2, 'choice', 'Write a composite function as a formula', 'Suppose $f$ squares a number and adds 1, so $f(x) = x^2 + 1$, while $g(x) = 3x - 2$. Which formula gives the output when $f$ comes first and $g$ is applied to its result?', '["$3x^2 + 1$","$9x^2 - 12x + 5$","$3x^2 - 2$","$3x^2 + 3$"]', '$3x^2 + 1$', NULL, 'Put $f(x)$ into $g$: $3(x^2 + 1) - 2 = 3x^2 + 3 - 2 = 3x^2 + 1$. The option $9x^2 - 12x + 5$ is $f(g(x))$.', 'checked', '{"lint":[],"solve":{"answer":"$3x^2 + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(f(x))=3(x^2+1)-2=3x^2+1","run_id":"claude-code","at":"2026-10-24T02:59:02.126Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d6deb9e-c703-42b3-853e-d9018f027198', 'NC17.M4.AF.1', 2, 'numeric', 'Compose with a radical, rational or exponential function', 'Let $f(x) = \sqrt{x}$ and $g(x) = 2x + 1$. What is $f(g(12))$?', '[]', '5', '5', '$g(12) = 25$. Then $f(25) = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(12) = 25; sqrt(25) = 5.","run_id":"claude-code","at":"2026-10-28T19:16:32.495Z"}}', 'ai', NULL, NULL)
