INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00852e91-51c9-45fc-b57d-348c1833e71e', 'NC17.M4.AF.1', 3, 'numeric', 'Evaluate a composite function from formulas', 'Three functions are $f(x) = x + 1$, $g(x) = 2x$ and $h(x) = x^2$. Starting with the input 3, apply $h$ first, then $g$, then $f$. What is the final output?', '[]', '19', '2*3^2+1', 'Work from the inside out. $h(3) = 9$. Then $g(9) = 18$. Then $f(18) = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(3)=9, g(9)=18, f(18)=19","run_id":"claude-code","at":"2026-10-24T02:59:02.126Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b6870b3-af30-429f-931e-9290df680d55', 'NC17.M4.AF.1', 3, 'numeric', 'Use a composite function to find an unknown', 'Let $g(x) = x - 2$. A function $f$ makes $f(g(x)) = x^2 - 4x + 7$ true for every $x$. What is $f(5)$?', '[]', '28', '5^2+3', 'Write $x = u + 2$ where $u = g(x)$: $f(u) = (u + 2)^2 - 4(u + 2) + 7 = u^2 + 3$. Then $f(5) = 25 + 3 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(x)=5 when x=7; f(5)=49-28+7=28. (f(t)=t^2+3.)","run_id":"claude-code","at":"2026-10-28T19:16:32.329Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a18da0c-7c88-4229-be45-4c64d2689b57', 'NC17.M4.AF.2', 1, 'numeric', 'Sine and cosine models in context', 'The depth of water at a dock is modeled by $d(t) = 4\sin\left(\frac{\pi}{6}t\right) + 10$, where $d$ is in feet and $t$ is in hours. What is the period of the model, in hours?', '[]', '12', '2/(1/6)', 'The period of $\sin(Bt)$ is $\frac{2\pi}{B}$. Here $B = \frac{\pi}{6}$, so the period is $2\pi \div \frac{\pi}{6} = 12$ hours.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Period = 2pi/(pi/6) = 12.","run_id":"claude-code","at":"2026-10-24T02:59:34.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02344b1a-5465-4454-8de8-215740af5e69', 'NC17.M4.AF.2', 1, 'choice', 'Features of sine and cosine models', 'For the model $y = 3\cos(2x) + 8$, which pair gives the maximum and minimum values?', '["Maximum 14, minimum 2","Maximum 3, minimum -3","Maximum 11, minimum 5","Maximum 8, minimum 5"]', 'Maximum 11, minimum 5', NULL, 'The cosine swings 3 above and 3 below the midline 8, so the maximum is $8 + 3 = 11$ and the minimum is $8 - 3 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"Maximum 11, minimum 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"cos ranges -1..1: max 3+8 = 11, min -3+8 = 5.","run_id":"claude-code","at":"2026-10-28T19:20:44.287Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0544387b-26b6-4706-8ef1-7849d277fd98', 'NC17.M4.AF.2', 1, 'choice', 'Pythagorean identities', 'Which equation is the Pythagorean identity that connects $\tan x$ and $\sec x$?', '["$\\tan^2 x + \\sec^2 x = 1$","$1 + \\sec^2 x = \\tan^2 x$","$\\tan^2 x - 1 = \\sec^2 x$","$1 + \\tan^2 x = \\sec^2 x$"]', '$1 + \tan^2 x = \sec^2 x$', NULL, 'Divide $\sin^2 x + \cos^2 x = 1$ by $\cos^2 x$ to get $\tan^2 x + 1 = \sec^2 x$.', 'checked', '{"lint":[],"solve":{"answer":"$1 + \\tan^2 x = \\sec^2 x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide sin^2+cos^2=1 by cos^2: tan^2+1=sec^2.","run_id":"claude-code","at":"2026-10-28T19:20:44.678Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('077c037c-4115-43fa-b8ad-c8cedb145058', 'NC17.M4.AF.2', 2, 'choice', 'Choosing the Law of Sines or the Law of Cosines', 'Triangle $ABC$ has known sides $a$ and $b$ and a known angle $A$ opposite side $a$. Which tool gives $\sin B$ directly?', '["The Law of Sines","The Law of Cosines","A reciprocal identity","The Pythagorean theorem"]', 'The Law of Sines', NULL, 'The known side $a$ and its opposite angle $A$ form a pair, so $\frac{\sin B}{b} = \frac{\sin A}{a}$ gives $\sin B$ at once.', 'checked', '{"lint":[],"solve":{"answer":"The Law of Sines","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a/sin A = b/sin B gives sin B = b sin A / a directly.","run_id":"claude-code","at":"2026-10-28T19:20:44.671Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04c6b514-979e-4b4d-9c9a-44c7fe8d9b85', 'NC17.M4.AF.2', 2, 'numeric', 'Pythagorean identities', 'An acute angle $\theta$ has $\csc \theta = \frac{5}{4}$. Find $\cot \theta$.', '[]', '3/4', '3/4', '$\sin \theta = \frac{4}{5}$, so $\cos^2 \theta = 1 - \frac{16}{25} = \frac{9}{25}$ and $\cos \theta = \frac{3}{5}$ (acute). Then $\cot \theta = \frac{3/5}{4/5} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"csc = 5/4 -> sin = 4/5, cos = 3/5 (acute), cot = 3/4.","run_id":"claude-code","at":"2026-10-28T19:20:44.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0312c40c-b4ed-466e-a218-4b9fc152b9a3', 'NC17.M4.AF.2', 2, 'choice', 'Simplifying expressions with identities', 'Simplify $\frac{1 - \cos^2 x}{\sin x}$. Which expression is equivalent for every $x$ where it is defined?', '["$\\cos x$","$\\sin x$","$\\csc x$","$\\tan x$"]', '$\sin x$', NULL, 'The numerator $1 - \cos^2 x$ equals $\sin^2 x$, so the fraction is $\frac{\sin^2 x}{\sin x} = \sin x$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sin x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1 - cos^2 x)/sin x = sin^2 x/sin x = sin x.","run_id":"claude-code","at":"2026-10-28T19:20:44.786Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00ab23d7-8127-440a-a956-8711fcb4a714', 'NC17.M4.AF.2', 3, 'numeric', 'Law of Cosines', 'Two boats leave a dock at the same time and travel in directions that are $120^\circ$ apart. After an hour one boat has gone 7 km and the other has gone 8 km. How far apart are the boats, in kilometers?', '[]', '13', '13', 'The distance $d$ is opposite the $120^\circ$ angle: $d^2 = 7^2 + 8^2 - 2(7)(8)\cos 120^\circ = 49 + 64 + 56 = 169$. So $d = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 49 + 64 - 2(7)(8)cos120 = 113 + 56 = 169; d = 13.","run_id":"claude-code","at":"2026-10-24T02:59:34.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('050e71e0-615e-4f7a-843d-71a789173db8', 'NC17.M4.AF.2', 3, 'numeric', 'Sine and cosine models in context', 'The hours of daylight in a town are modeled by $D(t) = 5\sin\left(\frac{\pi}{6}t\right) + 12$, where $t$ is in months. What is the smallest positive $t$ for which $D(t) = 17$?', '[]', '3', '3', '$D(t) = 17$ means $5\sin\left(\frac{\pi}{6}t\right) = 5$, so $\sin\left(\frac{\pi}{6}t\right) = 1$. The smallest positive angle with sine 1 is $\frac{\pi}{2}$, so $\frac{\pi}{6}t = \frac{\pi}{2}$ and $t = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 sin(pi t/6) + 12 = 17 gives sin(pi t/6) = 1, pi t/6 = pi/2, t = 3.","run_id":"claude-code","at":"2026-10-24T02:59:34.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29b5dd73-d290-40ba-b60c-ef3ff8d8d318', 'NC17.M4.AF.3', 1, 'numeric', 'solving exponential and logarithmic equations in context', 'The pH of a solution is $-\log h$ (base 10), where $h$ is the concentration of hydrogen ions in moles per liter. A solution has pH 5. What is $h$? Give a decimal.', '[]', '0.00001', '1/100000', '$-\log h = 5$ means $\log h = -5$, so $h = 10^{-5} = 0.00001$.', 'checked', '{"lint":[],"solve":{"answer":"0.00001","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-log h = 5, so log h = -5, h = 10^-5 = 0.00001.","run_id":"claude-code","at":"2026-10-28T19:29:58.782Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2769da05-d02b-4091-819f-979742137edd', 'NC17.M4.AF.3', 1, 'choice', 'domain and vertical asymptote', 'Which line is the vertical asymptote of the graph of $f(x) = \log_2 x$?', '["$y = 0$","$x = 1$","$x = 2$","$x = 0$"]', '$x = 0$', NULL, 'The inputs of a logarithm must be positive, and the graph gets closer and closer to the vertical line $x = 0$ without touching it.', 'checked', '{"lint":[],"solve":{"answer":"$x = 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"log_2 x is defined for x > 0 and goes to -infinity as x -> 0+, so vertical asymptote x = 0.","run_id":"claude-code","at":"2026-10-28T19:29:58.788Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aa49d15-33f5-43a7-9b15-52512b254cc5', 'NC17.M4.AF.3', 1, 'choice', 'evaluating a logarithm', 'Which value is equal to $\log_5 \frac{1}{5}$?', '["$1$","$-1$","$5$","$\\frac{1}{5}$"]', '$-1$', '-1', 'Since $5^{-1} = \frac{1}{5}$, the logarithm is $-1$.', 'checked', '{"lint":[],"solve":{"answer":"$-1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^-1 = 1/5, so -1.","run_id":"claude-code","at":"2026-10-28T19:29:58.862Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('032a5e70-7be6-490e-a5b9-d4f31c82deea', 'NC17.M4.AF.3', 2, 'choice', 'solving logarithmic equations', 'Condensing $\log_2 (x + 2) + \log_2 (x - 1) = 2$ gives $x^2 + x - 2 = 4$, whose roots are $x = 2$ and $x = -3$. Which values are solutions of the original equation?', '["Only $x = -3$","Only $x = 2$","Both of them","Neither of them"]', 'Only $x = 2$', NULL, 'For $x = -3$, $\log_2 (x + 2) = \log_2 (-1)$ is undefined, so it is extraneous. For $x = 2$: $\log_2 4 + \log_2 1 = 2 + 0 = 2$, which works.', 'checked', '{"lint":[],"solve":{"answer":"Only $x = 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=2: log2 4 + log2 1 = 2. x=-3: log of negative undefined. Only x=2.","run_id":"claude-code","at":"2026-10-28T19:29:58.697Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01e8a537-a089-49e9-a328-a213ad4bab72', 'NC17.M4.AF.3', 2, 'numeric', 'domain and vertical asymptote', 'What is the $x$-value of the vertical asymptote of $f(x) = \log_2 (3x + 6)$?', '[]', '-2', '-2', 'The asymptote is where the input is 0: $3x + 6 = 0$, so $x = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x+6=0, x=-2.","run_id":"claude-code","at":"2026-10-28T19:29:58.698Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0edf2609-e146-493c-9646-03cf75410406', 'NC17.M4.AF.3', 2, 'choice', 'domain and vertical asymptote', 'Which describes the domain of $f(x) = \log_5 (4 - x)$?', '["All $x$ with $x < 4$","All $x$ with $x > 4$","All $x$ with $x \\le 4$","All $x$ with $x > -4$"]', 'All $x$ with $x < 4$', NULL, 'We need $4 - x > 0$, which gives $x < 4$.', 'checked', '{"lint":[],"solve":{"answer":"All $x$ with $x < 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 - x > 0, x < 4.","run_id":"claude-code","at":"2026-10-28T19:29:58.813Z"}}', 'ai', NULL, NULL)
