INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06ad0586-93fd-4363-8d19-99425cf2ae71', 'NC17.M4.AF.3', 3, 'choice', 'solving exponential and logarithmic equations in context', 'An earthquake''s magnitude is $M = \log \frac{I}{I_0}$ (a base-10 logarithm), where $I$ is its intensity and $I_0$ is a fixed reference intensity. How many times as intense is a magnitude 7 earthquake as a magnitude 5 earthquake?', '["2 times","10 times","1000 times","100 times"]', '100 times', NULL, '$M = 7$ gives $\frac{I}{I_0} = 10^7$ and $M = 5$ gives $\frac{I}{I_0} = 10^5$. The ratio is $\frac{10^7}{10^5} = 10^2 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"100 times","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"I7/I5=10^(7-5)=100.","run_id":"claude-code","at":"2026-10-24T03:06:04.748Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0495cb2e-4bf2-41c9-b57b-33f112080a9b', 'NC17.M4.AF.3', 3, 'numeric', 'transformations and key features of a logarithmic graph', 'What is $g(26)$ for $g(x) = -2\log_3 (x + 1) + 4$?', '[]', '-2', '-2*3+4', '$g(26) = -2\log_3 27 + 4 = -2(3) + 4 = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"log3 27=3; -2(3)+4=-2.","run_id":"claude-code","at":"2026-10-28T19:29:58.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d49ad92-b403-474f-9e0e-286d140b7bbf', 'NC17.M4.AF.4', 1, 'numeric', 'Evaluate a piecewise function', 'Let $f(x) = x + 2$ if $x < 3$, and $f(x) = 2x - 1$ if $x \ge 3$. What is $f(1)$?', '[]', '3', '1+2', 'Since $1<3$, use the rule $x+2$. So $f(1)=1+2=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1<3, use x+2: 3.","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09a6a28b-de87-4b10-8f45-f96286ab9cea', 'NC17.M4.AF.4', 1, 'numeric', 'Evaluate a piecewise function', 'Let $f(x) = x^2$ if $x < 0$, and $f(x) = 2x$ if $x \ge 0$. What is $f(-2) + f(2)$?', '[]', '8', '(-2)^2+2*2', '$f(-2)=(-2)^2=4$ because $-2<0$. $f(2)=2\cdot 2=4$ because $2\ge 0$. The sum is $8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(-2)=4, f(2)=4; sum 8.","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2798b94d-89db-49fc-82fb-4534815b6f19', 'NC17.M4.AF.4', 1, 'numeric', 'Build a piecewise model of a situation', 'A taxi ride of $m$ miles costs $C(m) = 4$ dollars if $m \le 2$, and $C(m) = 4 + 2(m-2)$ dollars if $m > 2$. How many dollars does a 5-mile ride cost?', '[]', '10', '4+2*(5-2)', 'Since $5>2$, use $C(m)=4+2(m-2)$. Then $C(5)=4+2(3)=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5>2: 4+2(3)=10.","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c092515-6066-42a9-8879-f535c825e500', 'NC17.M4.AF.4', 2, 'choice', 'Move from a graph description to a rule', 'The graph of $f$ is a horizontal line at height $3$ for $x < 2$. For $x \ge 2$ it is a line through $(2, 3)$ with slope $2$. Which rule defines $f$?', '["$3$ if $x < 2$, and $2x + 3$ if $x \\ge 2$","$3x$ if $x < 2$, and $2x - 1$ if $x \\ge 2$","$3$ if $x < 2$, and $2x - 3$ if $x \\ge 2$","$3$ if $x < 2$, and $2x - 1$ if $x \\ge 2$"]', '$3$ if $x < 2$, and $2x - 1$ if $x \ge 2$', NULL, 'The second line has slope $2$ and passes through $(2,3)$: $y-3=2(x-2)$, so $y=2x-1$. The first piece is the constant $3$.', 'checked', '{"lint":[],"solve":{"answer":"$3$ if $x < 2$, and $2x - 1$ if $x \\ge 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line through (2,3) slope 2: y=3+2(x-2)=2x-1.","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('180315a2-da86-456e-8490-37a76209a0e4', 'NC17.M4.AF.4', 2, 'numeric', 'Build a piecewise model of a situation', 'A town taxes the first 20,000 dollars of income at 10%, and any income above 20,000 dollars at 15%. How many dollars of tax are due on an income of 36,000 dollars?', '[]', '4400', '20000/10+16000*15/100', 'The first 20,000 dollars is taxed $2{,}000$. The other 16,000 dollars is taxed at 15%, which is $2{,}400$. The total is $4{,}400$.', 'checked', '{"lint":[],"solve":{"answer":"4400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.10(20000)=2000; 0.15(16000)=2400; total 4400.","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('287de966-3799-443b-b194-30a92d8ddf3a', 'NC17.M4.AF.4', 2, 'numeric', 'Build a piecewise model of a situation', 'A garage charges 4 dollars for the first hour or part of it, and 2 dollars for each additional hour or part of an hour. How many dollars does it cost to park for 2 hours 20 minutes?', '[]', '8', '4+2*2', 'The first hour costs $4$. The remaining 1 hour 20 minutes covers 2 additional hours or parts of hours, costing $2\cdot 2=4$. The total is $8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First hour 4; remaining 1 h 20 min is 2 additional parts of an hour: 2(2)=4. Total 8.","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('054a0c2e-cf38-40f8-9b18-8ed3b63b0d36', 'NC17.M4.AF.4', 3, 'numeric', 'Build a piecewise model of a situation', 'A delivery service charges 6 dollars for a package up to 2 pounds, and 1.50 dollars for each pound of weight above 2 pounds, added to the 6 dollars. A package costs 12 dollars to send. How many pounds does it weigh?', '[]', '6', '2+(12-6)/1.5', 'Since $12>6$, the weight is over 2 pounds: $6+1.5(w-2)=12$. So $1.5(w-2)=6$, $w-2=4$ and $w=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6+1.5(w-2)=12 -> w-2=4 -> w=6.","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b07887a-7a46-4c13-9198-b9278813382d', 'NC17.M4.AF.4', 3, 'choice', 'Build a piecewise model of a situation', 'A plumber charges 40 dollars for a visit of up to 1 hour, plus 25 dollars for each hour beyond the first (time is measured exactly). Which rule gives the charge $C$ in dollars for a visit of $h$ hours, $h > 0$?', '["$40$ if $0 < h \\le 1$, and $40 + 25(h-1)$ if $h > 1$","$40$ if $0 < h \\le 1$, and $25h$ if $h > 1$","$40$ if $0 < h \\le 1$, and $40 + 25h$ if $h > 1$","$25h$ if $0 < h \\le 1$, and $40 + 25(h-1)$ if $h > 1$"]', '$40$ if $0 < h \le 1$, and $40 + 25(h-1)$ if $h > 1$', NULL, 'Up to 1 hour the charge is the flat $40$. After that, only the hours beyond the first cost extra: $h-1$ hours at $25$ each, added to $40$.', 'checked', '{"lint":[],"solve":{"answer":"$40$ if $0 < h \\le 1$, and $40 + 25(h-1)$ if $h > 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Beyond the first hour, 25 per hour of the excess: 40+25(h-1).","run_id":"claude-code","at":"2026-10-24T03:06:27.881Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05a39136-5dfc-4107-b658-7528223ccb4b', 'NC17.M4.AF.5', 1, 'numeric', 'Use and interpret a linear regression model', 'A regression line predicts the height of a plant in centimeters: $y = 2.5x + 4$, where $x$ is the number of weeks. What height does the model predict at 6 weeks?', '[]', '19', '2.5*6+4', 'Put $x = 6$ in the model: $2.5(6) + 4 = 15 + 4 = 19$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 2.5(6)+4 = 15+4 = 19.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
