INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18499156-d7bb-4e86-ab96-323b698d175e', 'NC17.M4.AF.5', 1, 'choice', 'Residuals and judging fit', 'Which formula gives the residual of a data point?', '["actual value minus predicted value","predicted value minus actual value","actual value plus predicted value","actual value divided by predicted value"]', 'actual value minus predicted value', NULL, 'A residual is the error of the model at a point: the actual value minus the value the model predicts.', 'checked', '{"lint":[],"solve":{"answer":"actual value minus predicted value","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Residual is defined as actual minus predicted.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
