INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10fc157d-f85c-4e43-beed-4abbf6663a3e', 'NC17.M4.AF.5', 1, 'choice', 'Use and interpret a linear regression model', 'For the model $y = 2.5x + 4$, where $y$ is a plant height in centimeters and $x$ is the number of weeks, what does the slope 2.5 mean?', '["The plant is 2.5 cm tall at the start","The plant grows 4 cm each week","The plant grows for 2.5 weeks","The plant grows 2.5 cm each week"]', 'The plant grows 2.5 cm each week', NULL, 'The slope is the change in $y$ for each increase of 1 in $x$: 2.5 cm of growth per week.', 'checked', '{"lint":[],"solve":{"answer":"The plant grows 2.5 cm each week","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = change in height per week: 2.5 cm each week.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
