INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('149751e7-c8c6-449f-806e-498fa36bb3ee', 'NC17.M4.AF.5', 2, 'numeric', 'Use and interpret an exponential regression model', 'Exponential regression gives $y = 120(2)^x$, where $x$ is the number of days. After how many days does the model predict $y = 960$?', '[]', '3', '3', 'Divide by 120: $2^x = 8$. Since $2^3 = 8$, $x = 3$ days.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120(2)^x = 960 gives 2^x = 8, x = 3.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
