INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1376f35b-e149-437b-957a-9a43ea15f0b4', 'NC17.M4.AF.5', 2, 'numeric', 'Use a sinusoidal regression model', 'Sinusoidal regression models the average temperature in month $x$ as $y = 5\cos\left(\frac{\pi}{6}x\right) + 20$. What is the period of the model, in months?', '[]', '12', '2/(1/6)', 'The period of $\cos(bx)$ is $\frac{2\pi}{b}$. Here $b = \frac{\pi}{6}$, so the period is $2\pi \div \frac{\pi}{6} = 12$ months.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Period = 2pi/(pi/6) = 12.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25cb86a0-adbb-443a-80fa-0e5e4bcfe3ff', 'NC17.M4.AF.5', 2, 'numeric', 'Residuals and judging fit', 'A linear model is $y = 3x + 2$. A data point is $(4, 17)$. What is the residual (actual value minus predicted value)?', '[]', '3', '17-(3*4+2)', 'The predicted value at $x = 4$ is $3(4) + 2 = 14$. The residual is $17 - 14 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Predicted 3(4)+2 = 14; residual 17-14 = 3.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bec3f31-215a-408f-adc0-9e1f58e4d998', 'NC17.M4.AF.5', 3, 'numeric', 'Use a quadratic regression model', 'Quadratic regression gives $y = 2x^2 - 8x + 11$. What is the least value of $y$ predicted by the model?', '[]', '3', '2*4-8*2+11', 'The vertex is at $x = -\frac{-8}{2(2)} = 2$. Then $y = 2(4) - 8(2) + 11 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex x = 8/4 = 2; y = 8-16+11 = 3. Opens upward so least value 3.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d0fd76a-2173-4e58-aa56-7769b0f17276', 'NC17.M4.AF.5', 3, 'numeric', 'Use and interpret an exponential regression model', 'Exponential regression gives $y = 1000(1.2)^x$. The value of the model at $x = 3$ is how many times its value at $x = 0$?', '[]', '1.728', '1.2^3', 'At $x = 0$ the model is 1000. At $x = 3$ it is $1000(1.2)^3$. The ratio is $1.2^3 = 1.728$.', 'checked', '{"lint":[],"solve":{"answer":"1.728","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio = 1.2^3 = 1.728.","run_id":"claude-code","at":"2026-10-24T03:04:41.492Z"}}', 'ai', NULL, NULL)
