INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('146e2f5a-7d0c-4697-b029-3e98e345bb48', 'NC17.M4.SP.1', 1, 'choice', 'Recognize a statistical question', 'Which of these is a statistical question?', '["How many students are in Room 12 of our school right now?","How long do our students spend on homework each night?","What is the name of the capital city of the state of Ohio?","How tall is the flagpole in front of our school building?"]', 'How long do our students spend on homework each night?', NULL, 'A statistical question expects answers that vary from one person or item to the next. Homework time differs from student to student. The other three each have one correct answer.', 'checked', '{"lint":[],"solve":{"answer":"How long do our students spend on homework each night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only homework time varies across students and needs data with variability.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
