INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12ee512e-6022-451a-a421-c3620d461950', 'NC17.M4.SP.1', 1, 'numeric', 'Read a non-standard data display', 'A stem-and-leaf plot of quiz scores is written as stem | leaves: 6 | 2 5; 7 | 0 4 8; 8 | 1 3 3 9. What is the range of the scores?', '[]', '27', '89-62', 'The lowest score is 62 and the highest is 89, so the range is $89-62=27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max 89, min 62; range 27.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
