INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b6c0f7b-e047-48e1-894d-0f0828194946', 'NC17.M4.SP.1', 1, 'choice', 'Read a non-standard data display', 'A bubble chart shows each country as a bubble. A bubble''s horizontal position shows average income, its vertical position shows life expectancy, and its size shows population. What does the size of a country''s bubble tell you?', '["how many people live there","how high the average income is","how long people live there","how large the land area is"]', 'how many people live there', NULL, 'Each feature of a bubble carries one variable. The size is assigned to population.', 'checked', '{"lint":[],"solve":{"answer":"how many people live there","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bubble size encodes population: how many people live there.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
