INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3559427c-2c16-4f00-bcb3-0a153c4fc402', 'NC17.M4.SP.1', 2, 'choice', 'Experiments and observational studies', 'A company wants to test whether a new fertilizer increases yield, using 40 identical plots. Which design is best?', '["Give the fertilizer to the 20 sunniest plots and compare with the rest","Randomly assign 20 plots to the fertilizer and 20 to none and compare","Give the fertilizer to all 40 plots and compare with last year''s yield","Let the farmer choose which 20 plots will get the fertilizer"]', 'Randomly assign 20 plots to the fertilizer and 20 to none and compare', NULL, 'Random assignment makes the groups alike apart from the treatment, so a difference in yield can be credited to the fertilizer. The other plans let sunlight, the year or the farmer''s choice affect the comparison.', 'checked', '{"lint":[],"solve":{"answer":"Randomly assign 20 plots to the fertilizer and 20 to none and compare","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Randomized comparative design with a control group.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('356a4340-ffed-4e70-b225-b6f588baf24b', 'NC17.M4.SP.1', 2, 'numeric', 'Sort, filter and summarize a large dataset', 'In a dataset of 200 students, 80 play a sport. Of the 80 who play a sport, 60 have a GPA above 3.0. Of the 120 who do not play a sport, 66 have a GPA above 3.0. What percent of the students who do not play a sport have a GPA above 3.0?', '[]', '55', '66/120*100', 'Look only at the 120 students who do not play a sport: $\frac{66}{120}=0.55$, which is 55%.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"66/120 = 0.55 = 55%.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
