INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fbf4d27-644d-4b3e-963b-4a6857df2e95', 'NC17.M4.SP.1', 2, 'choice', 'Plan an investigation', 'A student wants to investigate whether students who sleep more earn higher grades. Which two variables should be recorded for each student?', '["hours of sleep per night and grade point average","hours of sleep per night and the student''s shoe size","grade point average and the number of teachers they have","the student''s full name and their home address"]', 'hours of sleep per night and grade point average', NULL, 'The investigation compares sleep with grades, so each student''s hours of sleep and grade point average must be recorded. Names, addresses and shoe size do not help answer the question.', 'checked', '{"lint":[],"solve":{"answer":"hours of sleep per night and grade point average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Explanatory: hours of sleep; response: GPA.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
