INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2015c45e-8ec2-45c6-bb58-511cbd1aa606', 'NC17.M4.SP.1', 3, 'numeric', 'Read a non-standard data display', 'A back-to-back stem-and-leaf plot gives two classes'' scores. Each line is stem: Class A leaves | Class B leaves. Line 1 is 6: 5 8 | 2. Line 2 is 7: 0 4 6 | 1 5 5 8. Line 3 is 8: 2 9 | 3 7 9. By how many points is Class B''s median higher than Class A''s? Give a decimal.', '[]', '2.5', '(75+78)/2-74', 'Class A has 7 scores: 65, 68, 70, 74, 76, 82, 89, so its median is 74. Class B has 8 scores: 62, 71, 75, 75, 78, 83, 87, 89, so its median is $\frac{75+78}{2}=76.5$. The difference is $76.5-74=2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class A: 65,68,70,74,76,82,89 (7) median 74. Class B: 62,71,75,75,78,83,87,89 (8) median (75+78)/2 = 76.5. Difference 2.5.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d0e57b8-80da-4d61-9d81-f381b752c257', 'NC17.M4.SP.1', 3, 'choice', 'Read a non-standard data display', 'A line graph has a vertical axis that starts at 95 instead of 0, and it shows sales rising from 96 to 100. Why might this graph mislead a reader?', '["The shortened axis makes a small change look large","The graph uses a line instead of bars for the sales","Sales cannot be shown over time on a line graph","The values are too close to 100 to be plotted"]', 'The shortened axis makes a small change look large', NULL, 'Starting the axis at 95 stretches a change of 4 units across most of the graph, so the rise looks dramatic, though sales grew only about 4%.', 'checked', '{"lint":[],"solve":{"answer":"The shortened axis makes a small change look large","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Truncated axis exaggerates a small change.","run_id":"claude-code","at":"2026-10-24T03:07:50.669Z"}}', 'ai', NULL, NULL)
