INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00426bd3-a693-4edb-a06f-20975da1260b', 'NC17.M4.SP.2', 1, 'numeric', 'sample proportion from counts', 'In a random sample of 200 voters, 130 favor a proposal. What is the sample proportion of voters who favor it, as a decimal?', '[]', '0.65', '130/200', 'The sample proportion is $\frac{130}{200} = 0.65$.', 'checked', '{"lint":[],"solve":{"answer":"0.65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"130/200=0.65.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
