INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49b2406f-864b-41d3-9c7d-de8832de1997', 'NC17.M4.SP.2', 1, 'numeric', 'compute a z statistic from the standard error', 'A test of $H_0: p = 0.5$ uses a random sample of 100 people, and the sample proportion is 0.60. The standard error under $H_0$ is 0.05. What is the z-statistic?', '[]', '2', '(0.6-0.5)/0.05', '$z = \frac{0.60 - 0.50}{0.05} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=(0.60-0.50)/0.05=2.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ecc53bc-ad1a-4428-9852-d8774bbf7a8b', 'NC17.M4.SP.2', 1, 'choice', 'decide from a p-value', 'A one-proportion z-test gives a p-value of 0.03. The significance level is 0.05. What is the correct decision?', '["Do not reject $H_0$, because the p-value is less than 0.05","Reject $H_0$, because the p-value is less than 0.05","Reject $H_0$, because the p-value is more than 0.05","Accept $H_0$, because the p-value is less than 0.05"]', 'Reject $H_0$, because the p-value is less than 0.05', NULL, 'A p-value below the significance level (0.03 < 0.05) is strong enough evidence to reject the null hypothesis.', 'checked', '{"lint":[],"solve":{"answer":"Reject $H_0$, because the p-value is less than 0.05","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p-value 0.03 < 0.05, reject H0.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a90b9cb-a032-4e15-ba29-453568bccada', 'NC17.M4.SP.2', 2, 'choice', 'build a confidence interval for a proportion', 'In a random sample of 300 students, 75 walk to school. For a 95% confidence interval, $z^* = 1.96$. Which interval is correct for the proportion of all students who walk?', '["0.201 to 0.299","0.225 to 0.275","0.175 to 0.325","0.152 to 0.348"]', '0.201 to 0.299', NULL, 'The sample proportion is $\frac{75}{300} = 0.25$. The standard error is $\sqrt{\frac{0.25 \times 0.75}{300}} = 0.025$, so the margin of error is $1.96 \times 0.025 = 0.049$. The interval is $0.25 \pm 0.049$, from 0.201 to 0.299.', 'checked', '{"lint":[],"solve":{"answer":"0.201 to 0.299","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"phat=75/300=0.25; SE=sqrt(0.1875/300)=sqrt(0.000625)=0.025; ME=0.049; 0.201 to 0.299.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('032884d5-b3ed-4a68-8304-1f1eaf0252f5', 'NC17.M4.SP.2', 2, 'choice', 'interpret a confidence interval', 'A random sample gives a 95% confidence interval of 0.52 to 0.68 for the proportion of students who walk to school. Which statement is a correct interpretation?', '["95% of the students in the sample walk to school and 5% do not","About 95% of all sample proportions are between 0.52 and 0.68","The next sample will have a proportion between 0.52 and 0.68 with probability 0.95","We are 95% confident that the true proportion who walk is between 0.52 and 0.68"]', 'We are 95% confident that the true proportion who walk is between 0.52 and 0.68', NULL, 'A confidence interval is a statement about the true population proportion. The confidence level describes how often the method captures it.', 'checked', '{"lint":[],"solve":{"answer":"We are 95% confident that the true proportion who walk is between 0.52 and 0.68","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Standard interpretation: 95% confident the true proportion is between 0.52 and 0.68.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0597b7b6-df45-4a80-b999-c8efee28cea6', 'NC17.M4.SP.2', 2, 'numeric', 'compute a z statistic for a proportion', 'A company claims that 20% of its parts are defective. In a random sample of 400 parts, 25% are defective. For a test of $H_0: p = 0.2$, what is the z-statistic?', '[]', '2.5', '(0.25-0.2)/0.02', 'Under $H_0$ the standard error is $\sqrt{\frac{0.2 \times 0.8}{400}} = \sqrt{0.0004} = 0.02$. So $z = \frac{0.25 - 0.20}{0.02} = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SE=sqrt(0.2*0.8/400)=sqrt(0.0004)=0.02; z=(0.25-0.20)/0.02=2.5.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b48552b-25cf-42ea-b652-f0d0c66ec6af', 'NC17.M4.SP.2', 3, 'choice', 'what changes the size of the z statistic', 'In a one-proportion z-test, the sample proportion, $p_0$ and the alternative hypothesis stay the same. Which change would make the absolute value of the test statistic larger?', '["Taking a larger random sample of the same population","Taking a smaller random sample of the same population","Lowering the significance level from 0.05 to 0.01","Changing the test from one-sided to two-sided"]', 'Taking a larger random sample of the same population', NULL, 'A larger $n$ makes the standard error smaller, so the same distance from $p_0$ is more standard errors. The significance level and the number of sides do not change $z$.', 'checked', '{"lint":[],"solve":{"answer":"Taking a larger random sample of the same population","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=(phat-p0)/sqrt(p0(1-p0)/n); larger n shrinks SE, increasing |z|. Sidedness and alpha do not change z.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15cacdb0-59f1-495d-ab6f-4f84bbd763bc', 'NC17.M4.SP.2', 3, 'choice', 'one-proportion z-test with a decision', 'A store claims that 90% of its online orders arrive on time. In a random sample of 100 orders, 84 arrive on time. A test of $H_0: p = 0.9$ against $H_a: p < 0.9$ at the 5% level has the critical value $z = -1.645$. Which is the correct test statistic and conclusion?', '["$z = -2$; do not reject $H_0$","$z \\approx -1.64$; do not reject $H_0$","$z = 2$; do not reject $H_0$","$z = -2$; reject $H_0$"]', '$z = -2$; reject $H_0$', NULL, 'Under $H_0$ the standard error is $\sqrt{\frac{0.9 \times 0.1}{100}} = 0.03$, so $z = \frac{0.84 - 0.90}{0.03} = -2$. Since $-2 < -1.645$, reject $H_0$. Using the sample proportion in the standard error gives about $-1.64$, which is a mistake in a test.', 'checked', '{"lint":[],"solve":{"answer":"$z = -2$; reject $H_0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SE=sqrt(0.9*0.1/100)=0.03; z=(0.84-0.90)/0.03=-2; -2 < -1.645, reject H0.","run_id":"claude-code","at":"2026-10-24T03:12:37.904Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e1f5c74-c5cb-4151-9ce7-c0e83599b4b8', 'NC17.M4.SP.3', 1, 'choice', 'Missing probability in a distribution', 'A random variable $X$ takes the values 1, 2, 3 and 4 with probabilities 0.1, 0.4, 0.3 and $p$. Find $p$.', '["0.1","0.3","0.2","0.8"]', '0.2', '1-0.1-0.4-0.3', 'The probabilities add to 1. $0.1 + 0.4 + 0.3 + p = 1$, so $p = 0.2$.', 'checked', '{"lint":[],"solve":{"answer":"0.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.1+0.4+0.3+p=1, p=0.2.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4518c888-b7a5-47b7-9ae9-2cb466adf9d5', 'NC17.M4.SP.3', 1, 'choice', 'Conditions for a binomial distribution', 'Which situation can be modeled by a binomial distribution?', '["The number of heads in 10 flips of a fair coin","The number of rolls needed to get the first six","The total of the numbers on two dice","The heights, in inches, of 10 students"]', 'The number of heads in 10 flips of a fair coin', NULL, 'A binomial distribution counts successes in a fixed number of independent trials, each with the same probability of success. Ten flips of a fair coin fit. The others have no fixed number of trials with a success or failure each time.', 'checked', '{"lint":[],"solve":{"answer":"The number of heads in 10 flips of a fair coin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fixed n=10 independent trials, success = heads, p=0.5: binomial. Others are a sum, geometric, continuous.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
