INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('664a9051-2566-43d1-9aec-0abfc4e22246', 'NC17.M4.SP.3', 1, 'numeric', 'Mean of a binomial distribution', 'A binomial random variable has $n = 40$ trials and success probability $p = 0.25$. Find its mean.', '[]', '10', '40*0.25', 'The mean of a binomial distribution is $np = 40(0.25) = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"np=40(0.25)=10.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
