INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03854adf-03a5-4961-a915-e2a12fdb939b', 'NC17.M4.SP.3', 2, 'choice', 'Expected value from a distribution', 'A spinner gives 10 points with probability $\frac{1}{4}$, 20 points with probability $\frac{1}{2}$ and 40 points with probability $\frac{1}{4}$. Find the expected number of points.', '["70","22.5","17.5","30"]', '22.5', '10*1/4+20*1/2+40*1/4', '$E = 10\cdot\frac{1}{4} + 20\cdot\frac{1}{2} + 40\cdot\frac{1}{4} = 2.5 + 10 + 10 = 22.5$.', 'checked', '{"lint":[],"solve":{"answer":"22.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/4+20/2+40/4=2.5+10+10=22.5.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ba111ad-9c99-4241-81da-2469566b96a6', 'NC17.M4.SP.3', 2, 'numeric', 'Standard deviation of a binomial distribution', 'A binomial random variable has $n = 100$ trials and $p = 0.5$. Find its standard deviation.', '[]', '5', '100*0.5*0.5/5', 'The standard deviation is $\sqrt{np(1-p)} = \sqrt{100(0.5)(0.5)} = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(np(1-p))=sqrt(25)=5.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c1e8faf-005f-4bdd-b90d-7a46e5dec272', 'NC17.M4.SP.3', 2, 'choice', 'Conditions for a normal sampling distribution', 'The sampling distribution of a sample proportion is approximately normal when $np \ge 10$ and $n(1-p) \ge 10$. For which sample size and population proportion is it approximately normal?', '["$n = 20$, $p = 0.1$","$n = 30$, $p = 0.02$","$n = 200$, $p = 0.5$","$n = 15$, $p = 0.5$"]', '$n = 200$, $p = 0.5$', NULL, 'For $n = 200$ and $p = 0.5$, $np = 100$ and $n(1-p) = 100$, both at least 10. In the others, $np$ is 2, 0.6 and 7.5, so one condition fails.', 'checked', '{"lint":[],"solve":{"answer":"$n = 200$, $p = 0.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200(0.5)=100, 100 both >=10. 15(0.5)=7.5 no; 30(0.02)=0.6 no; 20(0.1)=2 no.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b8d1d0d-0246-488d-9025-4176879a5eb3', 'NC17.M4.SP.3', 3, 'numeric', 'Binomial probability', 'A die is rolled 3 times. Find the probability of getting at least one six.', '[]', '91/216', '1-(5/6)^3', '"At least one" is the opposite of "no sixes". $P(\text{no sixes}) = \left(\frac{5}{6}\right)^3 = \frac{125}{216}$. So the probability is $1 - \frac{125}{216} = \frac{91}{216}$.', 'checked', '{"lint":[],"solve":{"answer":"91/216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-(5/6)^3=1-125/216=91/216.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38705ff3-5263-4ff0-8a77-d97d080e719f', 'NC17.M4.SP.3', 3, 'choice', 'Standard deviation of a sample mean', 'A population has standard deviation $\sigma = 20$. A sample of size 25 gives a standard deviation of 4 for the sample mean. What sample size gives a standard deviation of 2 for the sample mean?', '["50","75","100","625"]', '100', '(20/2)^2', 'We need $\frac{20}{\sqrt{n}} = 2$, so $\sqrt{n} = 10$ and $n = 100$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/sqrt(n)=2, sqrt(n)=10, n=100.","run_id":"claude-code","at":"2026-10-24T03:12:17.804Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
