VALUES ('0702d126-11c9-4d8b-8742-1a6bba68c129', 'NC17.PC.N.1', 2, 'numeric', 'Multiply a complex number by its conjugate', 'What is $(4 - i)(4 + i)$?', '[]', '17', '16+1', 'Expand: $16 + 4i - 4i - i^2 = 16 + 1 = 17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16-i^2=16+1=17.","run_id":"claude-code","at":"2026-10-24T02:56:11.988Z"}}', 'ai', NULL, NULL)
