INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e3fdb28-c690-4b06-88d2-b3909a694c5d', 'NC17.PC.N.1', 2, 'numeric', 'Subtract complex numbers', 'What is the imaginary part of $(2 + 5i) - 3(1 - i)$?', '[]', '8', '8', '$3(1 - i) = 3 - 3i$. Then $(2 + 5i) - (3 - 3i) = -1 + 8i$. The imaginary part is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+5i-3+3i = -1+8i; imaginary part 8.","run_id":"claude-code","at":"2026-10-28T18:47:12.692Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03a86f89-1b84-415c-a852-ca7a33dbfce5', 'NC17.PC.N.1', 3, 'numeric', 'Multiply two complex numbers', 'The product $(x + 2i)(3 - i)$ has real part 11. What is $x$?', '[]', '3', '(11-2)/3', 'Expand: $3x - xi + 6i - 2i^2 = (3x + 2) + (6 - x)i$. Set $3x + 2 = 11$, so $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+2i)(3-i)=3x-xi+6i-2i^2=(3x+2)+(6-x)i; 3x+2=11 so x=3.","run_id":"claude-code","at":"2026-10-24T02:56:11.988Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('030c5852-f516-4da2-98ab-9c8d31f6f553', 'NC17.PC.N.1', 3, 'numeric', 'Multiply a complex number by a real number or by i', 'The number $z$ satisfies $2z = 6 - 8i$. What is the real part of $iz$?', '[]', '4', '4', '$z = 3 - 4i$. Then $iz = 3i - 4i^2 = 4 + 3i$. The real part is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z = 3 - 4i; iz = 3i - 4i^2 = 4 + 3i; real part 4.","run_id":"claude-code","at":"2026-10-28T18:48:28.019Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a4cc896-5643-4223-a08d-c132d371ec6f', 'NC17.PC.N.2', 1, 'numeric', 'Combine matrix operations', 'Evaluate $2A + 3B$ for $A$ with rows $[1, 4]$ and $[3, -2]$ and $B$ with rows $[0, 5]$ and $[-1, 2]$. What number is in the bottom left corner of the result?', '[]', '3', '2*3+3*(-1)', '$2 \cdot 3 + 3 \cdot (-1) = 6 - 3 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom left: 2*3 + 3*(-1) = 6-3 = 3.","run_id":"claude-code","at":"2026-10-28T19:20:44.404Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08afe451-ed83-4b5e-8bd3-c82a65f993cb', 'NC17.PC.N.2', 1, 'numeric', 'Identity and zero matrices', 'The matrix $I$ is the 2 by 2 identity matrix, and the matrix $M$ has rows $[4, -3]$ and $[2, 7]$. What is the entry in row 2, column 1 of $MI$?', '[]', '2', '2', 'Multiplying by the identity leaves $M$ unchanged, so the entry is the entry of $M$ in row 2, column 1, which is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MI = M; row 2, column 1 of M is 2.","run_id":"claude-code","at":"2026-10-28T19:20:44.601Z"}}', 'ai', NULL, NULL)
