INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fba1669-98d3-41b3-86bb-63e720bff1bf', 'NC17.PC.N.2', 2, 'numeric', 'Add and subtract matrices', 'A has rows $[9, 6]$ and $[4, 8]$. B has rows $[2, 5]$ and $[1, 3]$. The matrix X satisfies $X + B = A$. What is the entry in row 1, column 2 of X?', '[]', '1', '6-5', '$X = A - B$. Row 1, column 2: $6 - 5 = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X = A - B; entry r1c2 = 6 - 5 = 1.","run_id":"claude-code","at":"2026-10-24T02:57:19.754Z"}}', 'ai', NULL, NULL)
