INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ae0b846-805a-4fc6-96d4-cf828f21da7d', 'NC17.PC.N.2', 2, 'numeric', 'Scalar multiplication of matrices', 'The matrix $A$ has rows $[2, -4]$ and $[6, 0]$. The matrix $B$ has rows $[-3, 6]$ and $[-9, 0]$. The number $k$ satisfies $kA = B$. What is $k$?', '[]', '-3/2', '-3/2', 'Compare the entries in row 1, column 1: $2k = -3$, so $k = -\frac{3}{2}$. Check: $-4 \cdot (-\frac{3}{2}) = 6$.', 'checked', '{"lint":[],"solve":{"answer":"-3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Entry-wise: 2k=-3, -4k=6, 6k=-9 all give k=-3/2 (0=0 fine).","run_id":"claude-code","at":"2026-10-28T19:20:44.384Z"}}', 'ai', NULL, NULL)
