INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09301525-801f-4c6e-b03f-7213f9013af8', 'NC17.PC.N.2', 2, 'choice', 'Sizes in matrix operations', 'The matrix $A$ is 2 by 3, $B$ is 3 by 4 and $C$ is 4 by 1. What size is the product $ABC$?', '["2 by 1","3 by 1","2 by 4","3 by 4"]', '2 by 1', NULL, '$AB$ is 2 by 4. Then $(AB)C$ is 2 by 4 times 4 by 1, which is 2 by 1.', 'checked', '{"lint":[],"solve":{"answer":"2 by 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x3)(3x4) = 2x4, then (2x4)(4x1) = 2x1.","run_id":"claude-code","at":"2026-10-28T19:20:44.734Z"}}', 'ai', NULL, NULL)
