INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00f12b66-0daf-4324-975c-435bf98860ab', 'NC17.PC.N.2', 3, 'choice', 'Distributive property', 'The matrices $A$, $B$, $C$ and $D$ have sizes that allow the operations. Which product is equal to $AB + AC + DB + DC$?', '["$(A + B)(C + D)$","$(B + C)(A + D)$","$(A + D)(B + C)$","$(A + C)(B + D)$"]', '$(A + D)(B + C)$', NULL, 'Distribute $(A + D)(B + C) = AB + AC + DB + DC$. Changing the order of the factors changes the terms to $BA$, $BD$, $CA$ and $CD$.', 'checked', '{"lint":[],"solve":{"answer":"$(A + D)(B + C)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A+D)(B+C) = AB + AC + DB + DC.","run_id":"claude-code","at":"2026-10-28T19:20:44.316Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e48fc6d-9032-4f2c-8682-737ae16b9410', 'NC17.PC.N.2', 3, 'choice', 'Identity and zero matrices', 'Which statement about the product of two matrices is true?', '["Two matrices that are not zero can have a product that is the zero matrix.","If $AB$ is the zero matrix, then $A$ or $B$ must be the zero matrix.","If $AB = AC$, then $B = C$ for every matrix $A$.","If $AB$ is the zero matrix, then $BA$ must be the zero matrix too."]', 'Two matrices that are not zero can have a product that is the zero matrix.', NULL, 'For example, $A$ with rows $[0, 1]$ and $[0, 0]$ and $B$ with rows $[1, 0]$ and $[0, 0]$ are not zero, and $AB$ is the zero matrix while $BA$ is not. So the second and fourth statements fail, and the third fails when $A$ is the zero matrix.', 'checked', '{"lint":[],"solve":{"answer":"Two matrices that are not zero can have a product that is the zero matrix.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"E.g. A = [1,0;0,0], B = [0,0;0,1], AB = 0. So statement 3 true; 0, 1, 2 false.","run_id":"claude-code","at":"2026-10-28T19:20:44.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ee5eb27-1b2c-4fce-9172-ed10643a34fb', 'NC17.PC.N.3', 1, 'choice', 'Vectors versus scalars', 'Which of these is a vector quantity?', '["A car moving 20 miles per hour due north","A car whose gas tank holds 20 gallons","A room whose temperature is 20 degrees","A bag whose mass is 20 kilograms"]', 'A car moving 20 miles per hour due north', NULL, 'A vector has both a magnitude and a direction. "20 miles per hour due north" gives both. The other quantities have a size only.', 'checked', '{"lint":[],"solve":{"answer":"A car moving 20 miles per hour due north","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"velocity has magnitude and direction; the others are scalars","run_id":"claude-code","at":"2026-10-24T02:59:02.163Z"}}', 'ai', NULL, NULL)
