INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a53cbd1-2fa9-4b24-912f-0d7e4416d9d1', 'NC17.PC.N.3', 1, 'choice', 'Direction angle of a vector', 'Measured counterclockwise from the positive $x$-axis, which vector has direction angle $270^\circ$?', '["$(0, 3)$","$(-3, 0)$","$(3, 0)$","$(0, -3)$"]', '$(0, -3)$', NULL, '$270^\circ$ is three quarters of a turn, which points straight down, along the negative $y$-axis.', 'checked', '{"lint":[],"solve":{"answer":"$(0, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"270 deg points along negative y-axis: (0, -3).","run_id":"claude-code","at":"2026-10-28T19:16:32.066Z"}}', 'ai', NULL, NULL)
