INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('085cd939-9205-4726-ad48-43d82353ba8b', 'NC17.PC.N.3', 1, 'numeric', 'Add vectors in a real situation', 'A boat sails 7 miles due west and then 24 miles due south. How far, in miles, is the boat in a straight line from where it started?', '[]', '25', '25', 'The two legs are perpendicular, so the displacement has components $(-7, -24)$. Its magnitude is $\sqrt{49 + 576} = \sqrt{625} = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Displacement components 7 and 24 at right angles; magnitude sqrt(49+576) = sqrt(625) = 25.","run_id":"claude-code","at":"2026-10-28T19:16:32.402Z"}}', 'ai', NULL, NULL)
