INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0eebdfff-a260-44eb-89b2-44d234175fbc', 'NC17.PC.N.3', 2, 'numeric', 'Direction angle of a vector', 'The vector $u$ has components $(2, 5)$ and the vector $v$ has components $(-2, -1)$. Measured counterclockwise from the positive $x$-axis, what is the direction angle of $u + v$, in degrees?', '[]', '90', '90', '$u + v = (0, 4)$, which points straight up, so the direction angle is $90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"u + v = (0, 4), pointing along the positive y-axis: 90 degrees.","run_id":"claude-code","at":"2026-10-28T19:16:32.128Z"}}', 'ai', NULL, NULL)
