INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04ad04d0-7fd0-4d86-881f-bfdbdb7e6ca9', 'NC17.PC.N.3', 2, 'choice', 'Components from magnitude and direction', 'A vector has magnitude 6 and direction $45^\circ$, measured counterclockwise from the positive $x$-axis. Which are its components?', '["$(6, 6)$","$(3, 3)$","$(3\\sqrt{2}, 3\\sqrt{2})$","$(6\\sqrt{2}, 6\\sqrt{2})$"]', '$(3\sqrt{2}, 3\sqrt{2})$', NULL, 'Both components are $6 \cos 45^\circ = 6 \cdot \frac{\sqrt{2}}{2} = 3\sqrt{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$(3\\sqrt{2}, 3\\sqrt{2})$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6cos45, 6sin45) = (3sqrt2, 3sqrt2).","run_id":"claude-code","at":"2026-10-28T19:16:32.167Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('087ed101-df83-4efc-8695-144149b7409e', 'NC17.PC.N.3', 2, 'numeric', 'Components from magnitude and direction', 'A vector has magnitude 20 and direction $150^\circ$, measured counterclockwise from the positive $x$-axis. What is its $y$-component?', '[]', '10', '20/2', 'The $y$-component is $20 \sin 150^\circ = 20 \cdot \frac{1}{2} = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 20 sin 150 deg = 20 x 1/2 = 10.","run_id":"claude-code","at":"2026-10-28T19:16:32.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0289f988-8856-47af-9de8-e8dfa8844acd', 'NC17.PC.N.3', 3, 'choice', 'Add and subtract vectors geometrically', 'Three points $A$, $B$ and $C$ are not on one line. Which vector equals the vector from $A$ to $B$ minus the vector from $A$ to $C$?', '["The vector from $B$ to $C$","The vector from $A$ to $C$","The vector from $B$ to $A$","The vector from $C$ to $B$"]', 'The vector from $C$ to $B$', NULL, 'If $a$ and $c$ are the vectors from $A$ to $B$ and from $A$ to $C$, then $a - c$ goes from the tip of $c$ to the tip of $a$, which is from $C$ to $B$.', 'checked', '{"lint":[],"solve":{"answer":"The vector from $C$ to $B$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB - AC = (B - A) - (C - A) = B - C, the vector from C to B.","run_id":"claude-code","at":"2026-10-28T19:16:32.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0226d798-5db6-4228-b510-22d2d24531da', 'NC17.PC.N.3', 3, 'choice', 'Components from magnitude and direction', 'A force has magnitude 8 and direction $120^\circ$, measured counterclockwise from the positive $x$-axis. Which are its components?', '["$(-4, 4\\sqrt{3})$","$(-4\\sqrt{3}, 4)$","$(4, 4\\sqrt{3})$","$(-8, 8\\sqrt{3})$"]', '$(-4, 4\sqrt{3})$', NULL, '$8 \cos 120^\circ = 8 \cdot (-\frac{1}{2}) = -4$ and $8 \sin 120^\circ = 8 \cdot \frac{\sqrt{3}}{2} = 4\sqrt{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$(-4, 4\\sqrt{3})$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8cos120, 8sin120) = (-4, 4sqrt3).","run_id":"claude-code","at":"2026-10-28T19:16:32.297Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('126fa05b-ec56-4ddb-b8dc-7ec61056daa4', 'NC17.PC.A.1', 1, 'choice', 'Rational inequality: one fraction first', 'Which inequality is equivalent to $\frac{4}{x+1} \le 2$, with $0$ on the right side and one fraction on the left?', '["$\\frac{2x+2}{x+1} \\le 0$","$\\frac{2-2x}{x+1} \\le 0$","$\\frac{2}{x+1} \\le 0$","$\\frac{6-2x}{x+1} \\le 0$"]', '$\frac{2-2x}{x+1} \le 0$', NULL, 'Subtract 2 from both sides and use a common denominator: $\frac{4}{x+1} - \frac{2(x+1)}{x+1} = \frac{4 - 2x - 2}{x+1} = \frac{2 - 2x}{x+1}$. So the inequality is $\frac{2-2x}{x+1} \le 0$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2-2x}{x+1} \\le 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/(x+1) - 2 = (4 - 2x - 2)/(x+1) = (2-2x)/(x+1) <= 0.","run_id":"claude-code","at":"2026-10-24T02:59:34.042Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('123a9ac9-d4c2-4551-9e50-71ff5719791f', 'NC17.PC.A.1', 1, 'choice', 'Solving inequalities from a graph', 'A smooth curve $y = f(x)$ crosses the x-axis only at $x = -1$ and $x = 4$. It lies above the axis for $x < -1$ and for $x > 4$, and below it between them. For which $x$ is $f(x) \le 0$?', '["$-1 < x < 4$","$-1 \\le x \\le 4$","$x \\le -1$ or $x \\ge 4$","$x < -1$ or $x > 4$"]', '$-1 \le x \le 4$', NULL, 'The curve is below the axis for $-1 < x < 4$ and equals 0 at the two crossings, which $\le$ includes: $-1 \le x \le 4$.', 'checked', '{"lint":[],"solve":{"answer":"$-1 \\le x \\le 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f <= 0 where below or on the axis: between and at the zeros, -1 <= x <= 4.","run_id":"claude-code","at":"2026-10-28T19:20:44.344Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e49551d-7aab-464c-8aa1-f95d9f3bd395', 'NC17.PC.A.1', 1, 'choice', 'Excluded values and endpoints', 'Solve $\frac{x+3}{x-6} \le 0$ and write the answer with inequality signs. Which endpoint is included?', '["Only $6$","Only $-3$","Both $-3$ and $6$","Neither $-3$ nor $6$"]', 'Only $-3$', NULL, 'The answer is $-3 \le x < 6$. At $x = -3$ the fraction is 0, which satisfies $\le 0$; at $x = 6$ it is undefined.', 'checked', '{"lint":[],"solve":{"answer":"Only $-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solution -3 <= x < 6: -3 makes it 0 (included), 6 undefined.","run_id":"claude-code","at":"2026-10-28T19:20:44.535Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d554bb0-63ed-46b4-8580-788d8e933c6c', 'NC17.PC.A.1', 2, 'choice', 'Polynomial inequality in factored form', 'Solve $(x+4)(x-1)(x-5) \le 0$.', '["$-4 \\le x \\le 1$ or $x \\ge 5$","$x \\le -4$ or $1 \\le x \\le 5$","$x < -4$ or $1 < x < 5$","$-4 \\le x \\le 5$"]', '$x \le -4$ or $1 \le x \le 5$', NULL, 'The zeros are $-4$, $1$ and $5$. For $x > 5$ every factor is positive, and the sign changes at each zero going left: negative on $(1, 5)$, positive on $(-4, 1)$, negative for $x < -4$. We want negative or zero, so $x \le -4$ or $1 \le x \le 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le -4$ or $1 \\le x \\le 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Roots -4,1,5, leading coefficient positive. Signs: x<-4 neg, (-4,1) pos, (1,5) neg, x>5 pos. With equality: x <= -4 or 1 <= x <= 5.","run_id":"claude-code","at":"2026-10-24T02:59:34.042Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11ba94e8-1ee6-4edd-89cd-e5efea795cb0', 'NC17.PC.A.1', 2, 'choice', 'Excluded values and endpoints', 'Which statement about the solution of $\frac{x-2}{x+1} \ge 0$ is true?', '["The solution includes 2 but not -1.","The solution includes -1 but not 2.","The solution includes both 2 and -1.","The solution includes neither 2 nor -1."]', 'The solution includes 2 but not -1.', NULL, 'At $x = 2$ the fraction is $0$, and $0 \ge 0$ is true, so 2 is included. At $x = -1$ the denominator is zero, so the fraction is undefined and -1 is never included. The solution is $x < -1$ or $x \ge 2$.', 'checked', '{"lint":[],"solve":{"answer":"The solution includes 2 but not -1.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x=2 the fraction is 0, so 2 is included; at x=-1 it is undefined, excluded.","run_id":"claude-code","at":"2026-10-24T02:59:34.042Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('156ee0b4-19c3-40d3-9e23-69482bb1f7d8', 'NC17.PC.A.1', 2, 'choice', 'Polynomial inequality after factoring', 'Factor first, then solve $x^3 - 9x \le 0$.', '["$-3 \\le x \\le 0$ or $x \\ge 3$","$x \\le -3$ or $0 \\le x \\le 3$","$x \\le -3$ or $x \\ge 3$","$-3 \\le x \\le 3$"]', '$x \le -3$ or $0 \le x \le 3$', NULL, '$x^3 - 9x = x(x-3)(x+3)$ with zeros $-3$, $0$, $3$. For large $x$ it is positive, so it is negative for $0 < x < 3$ and for $x < -3$. Adding the zeros gives $x \le -3$ or $0 \le x \le 3$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le -3$ or $0 \\le x \\le 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x-3)(x+3) <= 0. Signs: x<-3 neg, (-3,0) pos, (0,3) neg, >3 pos. So x <= -3 or 0 <= x <= 3.","run_id":"claude-code","at":"2026-10-28T19:20:44.311Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('161b3f77-f597-4304-87ef-4bc821a83aee', 'NC17.PC.A.1', 3, 'choice', 'Rational inequality: one fraction first', 'Solve $\frac{x}{x+3} \ge 2$.', '["$x \\le -6$ or $x > -3$","$-6 \\le x < -3$","$-6 < x < -3$","$-3 < x \\le 6$"]', '$-6 \le x < -3$', NULL, '$\frac{x}{x+3} - 2 = \frac{-x-6}{x+3} \ge 0$, which is $\frac{x+6}{x+3} \le 0$. The critical numbers are $-6$ (included) and $-3$ (excluded), and the quotient is negative between them: $-6 \le x < -3$.', 'checked', '{"lint":[],"solve":{"answer":"$-6 \\le x < -3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/(x+3) - 2 >= 0 -> (-x-6)/(x+3) >= 0 -> (x+6)/(x+3) <= 0 -> -6 <= x < -3. Check x=-5: -5/-2 = 2.5 >= 2. x=-6: -6/-3 = 2.","run_id":"claude-code","at":"2026-10-28T19:20:44.602Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('124b9a91-0ca5-4dfb-8428-456d1aebd6c7', 'NC17.PC.A.1', 3, 'numeric', 'Solving inequalities from a graph', 'The parabola $f(x) = -x^2 + 4x + 5$ and the line $g(x) = 2x + 2$ cross at $x = -1$ and $x = 3$. For how many integers $x$ is $f(x) \ge g(x)$?', '[]', '5', '5', 'Since $f - g = -x^2 + 2x + 3 = -(x-3)(x+1)$, the parabola is on or above the line for $-1 \le x \le 3$. The integers are $-1, 0, 1, 2, 3$: 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f-g=-x^2+2x+3=-(x-3)(x+1)>=0 for -1<=x<=3. Integers -1,0,1,2,3: 5.","run_id":"claude-code","at":"2026-10-28T19:20:44.692Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b4b5ed4-9ee9-4d9c-9a4d-1994be924fd0', 'NC17.PC.A.2', 1, 'choice', 'Solve a logarithmic equation', 'Which value of $x$ satisfies $\log_{10} x = 2$?', '["$x = 100$","$x = 20$","$x = 1000$","$x = \\frac{1}{100}$"]', '$x = 100$', NULL, '$\log_{10} x = 2$ means $x = 10^2 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 100$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=10^2=100.","run_id":"claude-code","at":"2026-10-24T03:04:03.215Z"}}', 'ai', NULL, NULL)
