INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f327505-2bde-427d-a323-83d0477efe3e', 'NC17.PC.A.2', 1, 'numeric', 'Use inverse trig functions and identities', 'In degrees, what is $\sin^{-1}\left(\frac{1}{2}\right)$? Give the value between $-90^\circ$ and $90^\circ$.', '[]', '30', '30', '$\sin 30^\circ = \frac{1}{2}$, and $30^\circ$ is between $-90^\circ$ and $90^\circ$, so $\sin^{-1}\left(\frac{1}{2}\right) = 30^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin 30 deg = 1/2 and 30 is in [-90,90].","run_id":"claude-code","at":"2026-10-24T03:04:03.215Z"}}', 'ai', NULL, NULL)
