INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('121f7275-f94a-4447-9b23-3c2516f7d686', 'NC17.PC.A.2', 1, 'numeric', 'Eliminate the parameter', 'A curve is given by $x = 2t$ and $y = t^2$. Find $y$ when $x = 10$.', '[]', '25', '(10/2)^2', 'From $x = 2t$, $t = 5$ when $x = 10$. Then $y = 5^2 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2t=10 so t=5, y=25.","run_id":"claude-code","at":"2026-10-24T03:04:03.215Z"}}', 'ai', NULL, NULL)
