INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('067f1ba7-4214-4598-993c-5cec5ed402d5', 'NC17.PC.A.2', 2, 'choice', 'Solve an exponential equation', 'Which is the solution of $2e^x = 10$?', '["$x = \\ln 8$","$x = \\frac{\\ln 10}{2}$","$x = \\ln 5$","$x = 5$"]', '$x = \ln 5$', NULL, 'Divide by 2: $e^x = 5$. Then take the natural logarithm: $x = \ln 5$.', 'checked', '{"lint":[],"solve":{"answer":"$x = \\ln 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"e^x = 5, x = ln 5.","run_id":"claude-code","at":"2026-10-28T19:28:58.458Z"}}', 'ai', NULL, NULL)
