INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01fff675-d7a9-4287-8262-91d7cff07d27', 'NC17.PC.A.2', 2, 'numeric', 'Solve a trigonometric equation', 'How many solutions does $2\sin x = 3$ have?', '[]', '0', '0', '$\sin x = \frac{3}{2}$, which is greater than 1. Sine never exceeds 1, so there are no solutions.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin x = 3/2 > 1, impossible. 0 solutions.","run_id":"claude-code","at":"2026-10-28T19:29:58.764Z"}}', 'ai', NULL, NULL)
