INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b0f6122-89be-434d-8a59-2c47240143f3', 'NC17.PC.A.2', 2, 'choice', 'Eliminate the parameter', 'A curve has $x = t + 1$ and $y = t^2 - 2t$. Eliminating $t$ gives which equation?', '["$y = x^2 - 4x + 1$","$y = x^2 - 1$","$y = x^2 - 4x + 3$","$y = x^2 - 2x$"]', '$y = x^2 - 4x + 3$', NULL, 'From $x = t + 1$, $t = x - 1$. Then $y = (x - 1)^2 - 2(x - 1) = x^2 - 2x + 1 - 2x + 2 = x^2 - 4x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = x^2 - 4x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t = x - 1; y = (x-1)^2 - 2(x-1) = x^2 - 2x + 1 - 2x + 2 = x^2 - 4x + 3.","run_id":"claude-code","at":"2026-10-28T19:29:59.001Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bdb6eb3-829d-4c6b-9224-6bb189b8c41f', 'NC17.PC.A.2', 3, 'numeric', 'Use logarithm properties', 'Use $\log 2 \approx 0.30$ and $\log 3 \approx 0.48$ to approximate $\log 18$.', '[]', '1.26', '0.3+2*0.48', '$18 = 2 \cdot 3^2$. So $\log 18 = \log 2 + 2\log 3 \approx 0.30 + 2(0.48) = 1.26$.', 'checked', '{"lint":[],"solve":{"answer":"1.26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"log 18=log 2+2 log 3=0.30+0.96=1.26.","run_id":"claude-code","at":"2026-10-24T03:04:03.215Z"}}', 'ai', NULL, NULL)
