VALUES ('0c2888ed-2722-42fc-9e4c-893c2910c87f', 'NC17.PC.F.1', 1, 'choice', 'Period of a trig function', 'What is the period of $y = \sin(2x)$?', '["$\\pi$","$2\\pi$","$4\\pi$","$\\frac{\\pi}{2}$"]', '$\pi$', NULL, 'The period of $\sin(Bx)$ is $\frac{2\pi}{B}$. With $B=2$ it is $\pi$.', 'checked', '{"lint":[],"solve":{"answer":"$\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Period 2pi/2=pi.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
