INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27401859-31da-47f0-961f-20ddafcc7760', 'NC17.PC.F.1', 1, 'numeric', 'Amplitude, midline and extreme values of sine and cosine', 'The graph of $y = 2\cos x - 3$ oscillates about a horizontal midline $y = D$. What is $D$?', '[]', '-3', NULL, 'Adding $-3$ shifts the whole graph down $3$ units, so the midline is $y=-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midline y=-3.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
