INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('350e198e-53e1-4010-af06-6f31523a872c', 'NC17.PC.F.1', 1, 'choice', 'Secant and cosecant: asymptotes, range and reciprocals', 'What is the range of $y = \csc x$?', '["$y \\le -1$ or $y \\ge 1$","$y < -1$ or $y > 1$","$-1 \\le y \\le 1$","all real numbers"]', '$y \le -1$ or $y \ge 1$', NULL, 'Since $\csc x=\frac{1}{\sin x}$ and $\sin x$ lies between $-1$ and $1$ (and is never $0$ here), $|\csc x|\ge 1$. Values $-1$ and $1$ do occur.', 'checked', '{"lint":[],"solve":{"answer":"$y \\le -1$ or $y \\ge 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"csc=1/sin with |sin|<=1, sin nonzero: |csc|>=1.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8eb248f4-987f-4c9e-9f41-d1be1552dfd3', 'NC17.PC.F.1', 2, 'numeric', 'Amplitude, midline and extreme values of sine and cosine', 'What is the minimum value of $y = -2\sin(3x) + 5$?', '[]', '3', '5-2', '$\sin(3x)$ ranges from $-1$ to $1$, so $-2\sin(3x)$ ranges from $-2$ to $2$. The minimum of $y$ is $5-2=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2 sin(3x) ranges from -2 to 2; min 5-2=3.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
