INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f18f088-cb5f-4f6a-8e8d-ab0f9c745140', 'NC17.PC.F.1', 2, 'numeric', 'Period of a trig function', 'What is the period of $y = 4\sin(\pi x)$?', '[]', '2', '2/1', 'The period of $\sin(Bx)$ is $\frac{2\pi}{B}$. With $B=\pi$ it is $\frac{2\pi}{\pi}=2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2pi/pi=2.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
