INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e9cade5-97ce-46c0-be49-00d9b35ed9c7', 'NC17.PC.F.1', 2, 'numeric', 'Build a trig function from features or a situation', 'The depth of water in a harbor is $d(t) = 6 + 2\cos\left(\frac{\pi}{6}t\right)$ meters, where $t$ is in hours. How many hours pass between one high tide and the next?', '[]', '12', '2/(1/6)', 'High tides are the maxima of the cosine, one per period. The period is $\frac{2\pi}{\pi/6}=12$ hours.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Period 2pi/(pi/6)=12 hours between highs.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
