INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ae08f82-c61f-4be8-8192-511e6bd2b764', 'NC17.PC.F.1', 3, 'numeric', 'Solve a trig equation on an interval', 'A student solves the equation $\cos(2x) = \frac{1}{2}$ on the interval $0 \le x < 2\pi$ and lists every solution. How many solutions are on the list?', '[]', '4', NULL, 'Let $u=2x$, which ranges over $0\le u<4\pi$. $\cos u=\frac{1}{2}$ has $2$ solutions in each turn of $2\pi$, so $4$ solutions in $4\pi$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x in [0,4pi): cos=1/2 at pi/3, 5pi/3, 7pi/3, 11pi/3 -> x=pi/6, 5pi/6, 7pi/6, 11pi/6: 4.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('107eac70-2652-4aea-85c7-23b1069d1520', 'NC17.PC.F.1', 3, 'choice', 'Secant and cosecant: asymptotes, range and reciprocals', 'Which statement about $y = \sec x$ for $0 \le x \le 2\pi$ is true?', '["It has a local maximum value of $1$ at $x=0$ and a local minimum value of $-1$ at $x=\\pi$","It has a local minimum value of $1$ at $x=\\pi$ and a local maximum value of $-1$ at $x=0$","It has a local minimum value of $1$ at $x=0$ and a local maximum value of $-1$ at $x=2\\pi$","It has a local minimum value of $1$ at $x=0$ and a local maximum value of $-1$ at $x=\\pi$"]', 'It has a local minimum value of $1$ at $x=0$ and a local maximum value of $-1$ at $x=\pi$', NULL, 'Secant is the reciprocal of cosine. Where $\cos x=1$ (at $x=0$) the reciprocal has a local minimum of $1$. Where $\cos x=-1$ (at $x=\pi$) it has a local maximum of $-1$.', 'checked', '{"lint":[],"solve":{"answer":"It has a local minimum value of $1$ at $x=0$ and a local maximum value of $-1$ at $x=\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: x=0 is an endpoint of the stated interval; some courses do not call an endpoint a local minimum. Still only one option is defensible.","work":"sec 0=1 with sec>1 just right of 0: minimum 1 at x=0; sec pi=-1 with sec<-1 nearby: local max -1 at pi. sec 2pi=1, so A false; B, C false.","run_id":"claude-code","at":"2026-10-24T03:06:27.920Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ef7459c-b16e-4244-ad30-9843379c1058', 'NC17.PC.F.2', 1, 'choice', 'Signs of the functions by quadrant', 'In which quadrant is $\cos \theta$ negative and $\sin \theta$ positive?', '["Quadrant I","Quadrant II","Quadrant III","Quadrant IV"]', 'Quadrant II', NULL, 'Cosine is the $x$-coordinate and sine is the $y$-coordinate. Negative $x$ with positive $y$ is Quadrant II.', 'checked', '{"lint":[],"solve":{"answer":"Quadrant II","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"cos<0 (x negative) and sin>0 (y positive): Quadrant II.","run_id":"claude-code","at":"2026-10-24T03:04:41.530Z"}}', 'ai', NULL, NULL)
