INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ccb80e2-b868-4793-bb04-59c968cf83f3', 'NC17.PC.F.2', 1, 'numeric', 'Tangent or cotangent at a special angle', 'A unit circle point has equal $x$ and $y$ coordinates, both positive. What is the tangent of the angle that point makes with the positive $x$-axis?', '[]', '1', '1', 'At $45^\circ$ the point is $\left(\frac{\sqrt{2}}{2}, \frac{\sqrt{2}}{2}\right)$, so $\tan 45^\circ = \frac{y}{x} = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = y > 0, angle 45 degrees; tan = y/x = 1.","run_id":"claude-code","at":"2026-10-24T03:04:41.530Z"}}', 'ai', NULL, NULL)
