INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b30c2d8-b38f-4127-91b1-2d23035e86bb', 'NC17.PC.F.2', 2, 'numeric', 'Secant or cosecant at a special angle', 'The unit circle point at $180^\circ$ is $(-1, 0)$. Find $\sec 180^\circ$.', '[]', '-1', '1/-1', '$\cos 180^\circ = -1$, so $\sec 180^\circ = \frac{1}{-1} = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sec = 1/cos = 1/(-1) = -1.","run_id":"claude-code","at":"2026-10-24T03:04:41.530Z"}}', 'ai', NULL, NULL)
