INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c19e93f-6776-49d8-98b8-64e29a9d871a', 'NC17.PC.F.2', 2, 'numeric', 'Tangent or cotangent at a special angle', 'What is $\tan 135^\circ$?', '[]', '-1', '-1', 'The reference angle of $135^\circ$ is $45^\circ$, and $\tan 45^\circ = 1$. Tangent is negative in Quadrant II, so $\tan 135^\circ = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"135 in QII, reference 45, tan negative: -1.","run_id":"claude-code","at":"2026-10-24T03:04:41.530Z"}}', 'ai', NULL, NULL)
