VALUES ('0848f70f-d529-4211-a506-e37d92848020', 'NC26.1.ANR.1', 1, 'choice', 'Count by fives', 'Count by fives: 30, 35, 40. What number comes next?', '["41","50","55","45"]', '45', '40+5', 'Counting by fives means 5 more each time. 5 more than 40 is 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counting by fives: 30, 35, 40, then 45.","run_id":"claude-code","at":"2026-10-22T12:46:59.545Z"}}', 'ai', NULL, NULL)
