INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('002b0a59-2b3e-42d5-ae29-56cd4cdad160', 'NC26.2.ANR.2', 2, 'choice', 'Ten tens make a hundred', 'Which is not a way to make 1 hundred?', '["6 tens and 4 tens","7 tens and 3 tens","6 tens and 5 tens","2 tens and 8 tens"]', '6 tens and 5 tens', NULL, '10 tens make 100. 6 + 5 = 11 tens, which is more than 100 (it is 110). The other pairs add to 10 tens: 6 + 4, 7 + 3 and 2 + 8.', 'checked', '{"lint":[],"solve":{"answer":"6 tens and 5 tens","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6+5=11 tens, not 10; the others make 10 tens.","run_id":"claude-code","at":"2026-10-22T19:30:51.525Z"}}', 'ai', NULL, NULL)
