INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('048bf7e4-7418-4f8a-8c43-6dc0b8d9ef71', 'NC26.2.ANR.3', 2, 'choice', 'Compare two numbers with >, < and =', 'Which number is greater than 748 but less than 752?', '["747","753","758","749"]', '749', '749', 'The number must be more than 748 and less than 752. 749 is. 747 is less than 748, and 753 and 758 are greater than 752.', 'checked', '{"lint":[],"solve":{"answer":"749","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Between 748 and 752: 749, 750, 751. Only 749 is listed.","run_id":"claude-code","at":"2026-10-22T19:32:45.646Z"}}', 'ai', NULL, NULL)
