INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e93a48f-df93-4919-a784-7926a0d222a1', 'NC26.2.ANR.3', 2, 'choice', 'Read a number on a number line', 'A number line is marked in tens. A dot is on the mark 2 marks to the left of 300. Which number is the dot on?', '["280","298","302","320"]', '280', '300-2*10', 'Each mark to the left is 10 less. Two marks to the left of 300 is 300 - 10 - 10 = 280.', 'checked', '{"lint":[],"solve":{"answer":"280","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Marks in tens: 300 -> 290 -> 280.","run_id":"claude-code","at":"2026-10-22T19:32:45.646Z"}}', 'ai', NULL, NULL)
