INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15fd280c-34e7-4a0f-8950-54d17a685a70', 'NC26.2.ANR.3', 3, 'choice', 'Order numbers', 'Kofi has the numbers 404, 44, 440 and 4. Which list shows them from greatest to least?', '["440, 404, 44, 4","404, 440, 44, 4","4, 44, 404, 440","440, 44, 404, 4"]', '440, 404, 44, 4', NULL, 'The two numbers with 4 hundreds come first: 440 is more than 404. Then 44, which has 4 tens, and last 4. The order is 440, 404, 44, 4.', 'checked', '{"lint":[],"solve":{"answer":"440, 404, 44, 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"440 > 404 > 44 > 4.","run_id":"claude-code","at":"2026-10-22T19:32:45.646Z"}}', 'ai', NULL, NULL)
