INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('092ce2f8-51d3-47eb-bfe2-2b8faa7f5290', 'NC26.2.ANR.5', 1, 'choice', 'Use properties and the relationship between adding and subtracting', 'Which number sentence has the same sum as $23 + 45$?', '["$45 - 23$","$32 + 45$","$23 + 54$","$45 + 23$"]', '$45 + 23$', NULL, 'Numbers can be added in any order, so $23 + 45 = 45 + 23 = 68$. The others give 22, 77 and 77.', 'checked', '{"lint":[],"solve":{"answer":"$45 + 23$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: the options are expressions, not number sentences; ''Which has the same sum as 23 + 45?'' would be more precise.","work":"23 + 45 = 68. 45 + 23 = 68 (commutative). 23 + 54 = 77, 45 - 23 = 22, 32 + 45 = 77.","run_id":"claude-code","at":"2026-10-22T19:21:45.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13cbef34-7e6f-4539-bb28-069ef8d70cfa', 'NC26.2.ANR.5', 1, 'choice', 'Find the unknown in an addition or subtraction equation', 'Which number makes this sentence true? $15 - ? = 5$', '["20","10","5","11"]', '10', '15-5', '$15 - 10 = 5$, so the ? is $10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15-10=5, so ?=10.","run_id":"claude-code","at":"2026-10-22T19:35:39.674Z"}}', 'ai', NULL, NULL)
