VALUES ('0984e625-cbf3-47fd-809a-8adfc4419e5e', 'NC26.2.ANR.6', 3, 'choice', 'Finding the unknown in a subtraction sentence', 'Which number goes in the ? to make this true? $90 - ? = 47$', '["57","47","43","137"]', '43', '90-47', '90 - ? = 47, so the ? is 90 - 47 = 43. Check: 90 - 43 = 47. The number 57 comes from not trading a ten when subtracting.', 'checked', '{"lint":[],"solve":{"answer":"43","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 - 47 = 43; check 90 - 43 = 47.","run_id":"claude-code","at":"2026-10-22T12:58:18.828Z"}}', 'ai', NULL, NULL)
