INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dbff3c5-105f-4600-92c0-0725fd7359ee', 'NC26.2.ANR.6', 3, 'choice', 'Justifying that two expressions are equal or not equal', 'The sign $\ne$ means is not equal to. Which sentence is true?', '["$63 + 7 \\ne 70$","$40 + 30 \\ne 80 - 10$","$45 + 5 \\ne 60 - 10$","$45 + 5 \\ne 60 - 5$"]', '$45 + 5 \ne 60 - 5$', NULL, '45 + 5 = 50 and 60 - 5 = 55. These are not equal, so the sentence is true. In the other sentences the two sides are equal (70 and 70, 70 and 70, 50 and 50), so they are false.', 'checked', '{"lint":[],"solve":{"answer":"$45 + 5 \\ne 60 - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 + 5 = 50 and 60 - 10 = 50, equal, so the first is false. 63 + 7 = 70, false. 40 + 30 = 70 and 80 - 10 = 70, false. 45 + 5 = 50 and 60 - 5 = 55, not equal, so true.","run_id":"claude-code","at":"2026-10-22T12:58:18.828Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0362e3ea-643e-4803-a2ef-c502987af0ae', 'NC26.2.ANR.7', 1, 'numeric', 'Subtract three-digit numbers (no regrouping)', 'A pool has 925 liters of water. Then 400 liters leak out. How many liters of water are left in the pool?', '[]', '525', '925-400', '925 - 400 = 525. Only the hundreds change: 9 hundreds - 4 hundreds = 5 hundreds.', 'checked', '{"lint":[],"solve":{"answer":"525","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"925-400=525.","run_id":"claude-code","at":"2026-10-22T19:40:34.720Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06744263-96d0-40ea-b329-38ba97ef4396', 'NC26.2.ANR.7', 1, 'choice', 'Explain why a strategy works', 'Which statement is true?', '["Taking 138 away from 462 gives the same answer as taking 462 away from 138.","Adding 138 to 462 gives a bigger total than adding 462 to 138.","Adding 138 to 462 gives a smaller total than adding 462 to 138.","Adding 138 to 462 gives the same total as adding 462 to 138."]', 'Adding 138 to 462 gives the same total as adding 462 to 138.', NULL, 'Numbers can be added in any order and the total stays the same. Both ways give 600. Subtraction does not work that way.', 'checked', '{"lint":[],"solve":{"answer":"Adding 138 to 462 gives the same total as adding 462 to 138.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Addition is commutative: 138+462 = 462+138 = 600. Subtraction is not.","run_id":"claude-code","at":"2026-10-22T19:40:34.720Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
