VALUES ('06bbcf0d-cc96-4e49-84b7-691ddc7bf6c2', 'NC26.2.ANR.7', 1, 'choice', 'Find a missing number', 'Which number makes $350 + ? = 380$ true?', '["730","130","300","30"]', '30', '380-350', 'The ? is the difference between 380 and 350. 380 - 350 = 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"380-350=30.","run_id":"claude-code","at":"2026-10-22T19:40:34.720Z"}}', 'ai', NULL, NULL)
