VALUES ('2313e8aa-db27-4b09-80c3-0f8ae6a624f3', 'NC26.2.ANR.7', 2, 'numeric', 'Add three two-digit numbers', 'A toy shop sold 24 balls in the morning, 37 at lunch time and 18 in the evening. How many balls did it sell in all?', '[]', '79', '24+37+18', '24 + 37 = 61. 61 + 18 = 79 balls.', 'checked', '{"lint":[],"solve":{"answer":"79","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 + 37 = 61; 61 + 18 = 79.","run_id":"claude-code","at":"2026-10-22T12:47:46.479Z"}}', 'ai', NULL, NULL)
