INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1060cd81-f945-4405-b3a4-a9126fa3ff4b', 'NC26.2.SGMR.1', 2, 'numeric', 'Decompose shapes', 'A square is cut by one straight line from the middle of its top side to the middle of its bottom side. It is also cut by another straight line from the middle of its left side to the middle of its right side. How many pieces are made?', '[]', '4', '2*2', 'The first cut makes 2 pieces. The second cut crosses the first and cuts each piece in 2. That makes 4 pieces, and each one is a smaller square.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A vertical midline and a horizontal midline cross in the centre, making 4 smaller squares.","run_id":"claude-code","at":"2026-10-22T12:57:31.940Z"}}', 'ai', NULL, NULL)
