VALUES ('065d8e17-3e81-4d6c-a744-066244a8a6cf', 'NC26.2.SGMR.1', 2, 'numeric', 'Compose shapes', 'Eva covers a rectangle with square tiles in 4 rows. Each row has 5 tiles. How many tiles does she use?', '[]', '20', '4*5', '4 rows of 5 tiles is 5 + 5 + 5 + 5 = 20 tiles.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 rows x 5 = 20.","run_id":"claude-code","at":"2026-10-22T19:40:34.760Z"}}', 'ai', NULL, NULL)
