INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a58cd08-9822-4232-a878-14b8307d7d77', 'NC26.2.SGMR.1', 3, 'choice', 'Decompose shapes', 'Which statement is true?', '["A circle can be cut into 2 triangles with 1 straight cut.","A square can be cut into 2 triangles with 1 straight cut.","A triangle can be cut into 2 squares with 1 straight cut.","A square can be cut into 3 triangles with 1 straight cut."]', 'A square can be cut into 2 triangles with 1 straight cut.', NULL, 'One cut from corner to opposite corner turns a square into 2 triangles. One cut always makes 2 pieces, a circle has no corners, and a triangle cannot be cut into squares.', 'checked', '{"lint":[],"solve":{"answer":"A square can be cut into 2 triangles with 1 straight cut.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A diagonal cuts a square into 2 triangles.","run_id":"claude-code","at":"2026-10-22T19:40:34.760Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e14a5f3-89d7-4f91-bdf8-5f0e1008dc9c', 'NC26.2.SGMR.2', 1, 'choice', 'Tell equal shares from unequal parts', 'Which circle is cut into halves?', '["A circle cut into 2 parts of the same size","A circle cut into 2 parts, one much bigger","A circle cut into 3 parts of the same size","A circle cut into 4 parts of the same size"]', 'A circle cut into 2 parts of the same size', NULL, 'Halves are 2 equal shares. Only the circle cut into 2 parts of the same size has halves. Parts of different sizes are not halves, and 3 or 4 parts are thirds or fourths.', 'checked', '{"lint":[],"solve":{"answer":"A circle cut into 2 parts of the same size","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halves need 2 parts of the same size. The unequal 2-part cut is not halves; 3 or 4 equal parts are thirds or fourths.","run_id":"claude-code","at":"2026-10-22T13:01:53.112Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2daeb731-8f6e-4e5e-9fec-d6de0d3d4cf5', 'NC26.2.SGMR.2', 1, 'choice', 'Tell equal shares from unequal parts', 'Max cuts a pizza into 3 parts. Two parts are small and one part is big. Are the parts thirds?', '["Yes, there are 3 parts in all, so they are thirds","Yes, a pizza can be cut into thirds","No, a pizza can never be cut into thirds","No, the parts are not all the same size"]', 'No, the parts are not all the same size', NULL, 'Thirds must be 3 parts of the same size. These parts are not the same size.', 'checked', '{"lint":[],"solve":{"answer":"No, the parts are not all the same size","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thirds must be 3 equal shares; these are unequal.","run_id":"claude-code","at":"2026-10-22T19:43:59.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e0fb06f-ca57-4e8e-a1fb-b6dc3f83ab27', 'NC26.2.SGMR.2', 1, 'numeric', 'Equal shares can look different', 'A square napkin is folded in half. Then it is cut along the fold. How many pieces are there?', '[]', '2', '2', 'The fold cuts the napkin into 2 equal pieces.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Folding in half and cutting along the fold gives 2 pieces.","run_id":"claude-code","at":"2026-10-22T19:43:59.781Z"}}', 'ai', NULL, NULL)
