INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1500847b-78c0-465f-bf75-1d2e2dd6296e', 'NC26.2.SGMR.2', 2, 'numeric', 'Partition a whole into 2, 3 or 4 equal shares', 'Max cuts a cake into halves. Sam cuts a cake of the same size into fourths. How many more shares does Sam''s cake have than Max''s cake?', '[]', '2', '4-2', 'Max''s cake has 2 shares and Sam''s cake has 4 shares. $4 - 2 = 2$, so Sam''s cake has 2 more shares.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halves: 2 shares. Fourths: 4 shares. 4 - 2 = 2 more.","run_id":"claude-code","at":"2026-10-22T13:01:53.112Z"}}', 'ai', NULL, NULL)
