INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('132f4673-7dcc-473a-bc9e-da29edb3521d', 'NC26.2.SGMR.2', 2, 'numeric', 'Describe the whole as 2 halves, 3 thirds or 4 fourths', 'Pam colors 3 fourths of a rectangle that is cut into fourths. How many fourths are not colored?', '[]', '1', '4-3', 'The whole rectangle is 4 fourths. 4 - 3 = 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 fourths - 3 colored = 1.","run_id":"claude-code","at":"2026-10-22T19:43:59.781Z"}}', 'ai', NULL, NULL)
