INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00389340-2760-42f2-a556-403bcee65d22', 'NC26.2.RD.1', 2, 'choice', 'Choose the rule that describes a group', 'Which rule describes this group: 12, 15, 18, 19?', '["numbers with a 1 in the ones place","even numbers","numbers with a 1 in the tens place","numbers greater than 15"]', 'numbers with a 1 in the tens place', NULL, 'Every number starts with the digit 1, so each has 1 ten. Not all are even, 12 is not greater than 15, and none has a 1 in the ones place.', 'checked', '{"lint":[],"solve":{"answer":"numbers with a 1 in the tens place","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12, 15, 18, 19 all have 1 in the tens place; not all even, 12 and 15 not > 15.","run_id":"claude-code","at":"2026-10-23T00:09:24.126Z"}}', 'ai', NULL, NULL)
