INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('076923d5-be51-4f79-8a39-bf3dc13671cc', 'NC26.2.RD.1', 3, 'choice', 'Find the object that does not belong', 'Ned makes a group of shapes that have an even number of sides: square, rectangle, hexagon, triangle. Which shape does not belong?', '["square","rectangle","triangle","hexagon"]', 'triangle', NULL, 'A square and a rectangle have 4 sides and a hexagon has 6, which are even. A triangle has 3 sides, which is odd.', 'checked', '{"lint":[],"solve":{"answer":"triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle has 3 sides (odd).","run_id":"claude-code","at":"2026-10-23T00:09:24.126Z"}}', 'ai', NULL, NULL)
