INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09e92d85-9ff6-4f0c-8c5b-719e5e4356df', 'NC26.2.RD.1', 3, 'numeric', 'Compare the sizes of groups', 'A teacher sorts 29 stickers. There are 10 stars. There are 3 more hearts than stars. The rest are moons. How many more hearts than moons are there?', '[]', '7', '(10+3)-(29-10-(10+3))', 'Hearts = 10 + 3 = 13. Moons = 29 - 10 - 13 = 6. 13 - 6 = 7 more hearts.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hearts 13; moons 29 - 10 - 13 = 6; 13 - 6 = 7.","run_id":"claude-code","at":"2026-10-23T00:09:24.126Z"}}', 'ai', NULL, NULL)
