INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05e0fb7e-c9de-4b95-8972-9e05ed0d3b1d', 'NC26.2.RD.2', 2, 'choice', 'Use a graph to draw and check conclusions', 'A bar graph shows the pets in a class. The Dogs bar reaches 9, Cats reach 7, Fish reach 4 and Birds reach 2. Each child has one pet. Which conclusion does the graph show?', '["Fish are more common than cats in the class.","Birds are the most common pet in the class.","The class has 20 pets in all, one each.","Dogs are the most common pet in the class."]', 'Dogs are the most common pet in the class.', NULL, 'Dogs have the tallest bar, at 9. Fish (4) are fewer than cats (7), birds (2) are the fewest, and the total is 9 + 7 + 4 + 2 = 22, not 20.', 'checked', '{"lint":[],"solve":{"answer":"Dogs are the most common pet in the class.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 9 most; total is 22, not 20.","run_id":"claude-code","at":"2026-10-23T00:09:24.162Z"}}', 'ai', NULL, NULL)
