VALUES ('2551ac9a-359b-470c-af14-8182ed3d0b7f', 'NC26.3.ANR.1', 1, 'numeric', 'Equivalent forms: regroup place values', '$1{,}000$ is the same as how many hundreds?', '[]', '10', '1000/100', 'Ten hundreds make one thousand: $10 \times 100 = 1{,}000$. So 1,000 is 10 hundreds.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,000 / 100 = 10 hundreds.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
