INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12181159-24d6-4df1-9614-87a20249095d', 'NC26.3.ANR.1', 2, 'choice', 'Expanded form', 'Which choice does NOT equal $6{,}205$?', '["$5 + 200 + 6{,}000$","$6{,}000 + 100 + 100 + 5$","$6{,}000 + 20 + 5$","$6{,}000 + 205$"]', '$6{,}000 + 20 + 5$', NULL, '6,205 is $6{,}000 + 200 + 5$. The choices $5 + 200 + 6{,}000$, $6{,}000 + 100 + 100 + 5$ and $6{,}000 + 205$ all add to 6,205. But $6{,}000 + 20 + 5$ is only 6,025.', 'checked', '{"lint":[],"solve":{"answer":"$6{,}000 + 20 + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 200 + 6,000 = 6,205. 6,000 + 205 = 6,205. 6,000 + 100 + 100 + 5 = 6,205. 6,000 + 20 + 5 = 6,025, not 6,205.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a6bccfb-a045-4616-8efa-b018f4189420', 'NC26.3.ANR.1', 2, 'choice', 'Number words and standard form', 'In which choice do the words and the standard form name the same number?', '["four thousand, thirty = $4{,}300$","four hundred three = $4{,}030$","four thousand, three = $4{,}300$","four thousand, three hundred = $4{,}300$"]', 'four thousand, three hundred = $4{,}300$', NULL, '"Four thousand, three hundred" is 4,300, so that pair matches. "Four thousand, thirty" is 4,030, "four hundred three" is 403, and "four thousand, three" is 4,003.', 'checked', '{"lint":[],"solve":{"answer":"four thousand, three hundred = $4{,}300$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"four thousand, three = 4,003 (not 4,300). four hundred three = 403 (not 4,030). four thousand, thirty = 4,030 (not 4,300). four thousand, three hundred = 4,300: match.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
