INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10f51dd5-a48e-4d0f-a10a-e48972004c38', 'NC26.3.ANR.2', 1, 'numeric', 'Subtract in a story (take away or compare)', 'A truck carried 450 boxes. It dropped off 200 boxes. How many boxes are still on the truck?', '[]', '250', '450-200', '"How many are still on" means take away: $450 - 200 = 250$. (45 tens minus 20 tens is 25 tens.)', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"450 - 200 = 250.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
