INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26ebabaa-2430-4e8a-ae0a-47e8de08437f', 'NC26.3.ANR.2', 1, 'choice', 'Add or subtract by place value', 'What is the sum of $200 + 40 + 3$ and $100 + 20 + 5$?', '["268","378","368","358"]', '368', '243+125', 'Add the hundreds: $200 + 100 = 300$. Add the tens: $40 + 20 = 60$. Add the ones: $3 + 5 = 8$. The sum is $300 + 60 + 8 = 368$.', 'checked', '{"lint":[],"solve":{"answer":"368","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"243 + 125 = 368 (300 + 60 + 8).","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('020acb22-ed64-49d2-ad72-94e9b7c13d17', 'NC26.3.ANR.2', 2, 'numeric', 'Add or subtract by place value', 'Lia finds $752 - 238$ by taking away 200, then 30, then 8. What is the answer?', '[]', '514', '752-238', '$752 - 200 = 552$. $552 - 30 = 522$. $522 - 8 = 514$.', 'checked', '{"lint":[],"solve":{"answer":"514","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"752 - 200 = 552; 552 - 30 = 522; 522 - 8 = 514.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
