INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1491e6c1-f963-430e-8648-8ac20c825897', 'NC26.3.ANR.2', 3, 'numeric', 'Subtract in a story (take away or compare)', 'A concert hall has 905 seats. There are 487 people in the hall, and every person is sitting in a seat. How many seats are empty?', '[]', '418', '905-487', 'Subtract: $905 - 487$. Trade so that 9 hundreds, 0 tens, 5 ones becomes 8 hundreds, 9 tens, 15 ones. Ones: $15 - 7 = 8$. Tens: $9 - 8 = 1$. Hundreds: $8 - 4 = 4$. The answer is 418. Check: $418 + 487 = 905$.', 'checked', '{"lint":[],"solve":{"answer":"418","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"905 - 487 = 905 - 500 + 13 = 405 + 13 = 418. Check 487 + 418 = 905.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14323d8a-31c9-422f-88a9-09e6be7f7873', 'NC26.3.ANR.2', 3, 'numeric', 'Add with regrouping', 'Find $598 + 394$.', '[]', '992', '598+394', 'Ones: $8 + 4 = 12$, write 2 and carry 1. Tens: $9 + 9 + 1 = 19$, write 9 and carry 1. Hundreds: $5 + 3 + 1 = 9$. The sum is 992.', 'checked', '{"lint":[],"solve":{"answer":"992","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"598 + 394 = 600 + 394 - 2 = 994 - 2 = 992.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0298ac36-84f6-4bb7-ac5a-8fa6a4ba579c', 'NC26.3.ANR.3', 1, 'choice', 'Equal groups and multiplication sentences', 'Ben has 6 bags with 2 toy cars in each bag. He writes $6 \times 2 = 12$. What does the 2 tell us?', '["the number of bags Ben has","the number of cars in each bag","the number of cars in all of the bags","how many more cars than bags"]', 'the number of cars in each bag', NULL, 'In $6 \times 2$ the 6 is the number of bags and the 2 is the number of cars in each bag. The total, 12, is the number of cars in all.', 'checked', '{"lint":[],"solve":{"answer":"the number of cars in each bag","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 bags, 2 cars in each bag; 6 x 2 = 12. The 6 is the number of bags, the 2 is the number in each bag, 12 is the total.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
