VALUES ('034da8d4-e40b-4170-828e-ebbf3c742e3a', 'NC26.3.ANR.3', 2, 'choice', 'Arrays: rows and columns', 'Pia says an array with 6 rows and 4 columns has the same number of squares as an array with 4 rows and 6 columns. Is she right?', '["Yes, both have 24 squares","No, the first has more squares","No, the second has more squares","Yes, both have 10 squares"]', 'Yes, both have 24 squares', NULL, '$6 \times 4 = 24$ and $4 \times 6 = 24$. The two arrays have the same number of squares.', 'checked', '{"lint":[],"solve":{"answer":"Yes, both have 24 squares","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 = 24 and 4 x 6 = 24: yes, both 24.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
