INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cbbd784-af92-4b35-aa2c-2128bbc95ea7', 'NC26.3.ANR.3', 3, 'choice', 'Equal groups and multiplication sentences', 'Which expression shows 5 groups of 3 together with 2 more groups of 3?', '["$7 \\times 3$","$(5 \\times 3) + 2$","$5 \\times (3 + 2)$","$7 + 3$"]', '$7 \times 3$', NULL, '5 groups of 3 plus 2 more groups of 3 make 7 groups of 3, which is $7 \times 3 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"$7 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 groups of 3 plus 2 more groups of 3 = 7 groups of 3 = 7 x 3 = 21. (5 x 3) + 2 = 17, 5 x (3+2) = 25, 7 + 3 = 10 are wrong.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
