INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05336053-b200-4840-9c56-00e0c6e6e750', 'NC26.3.ANR.6', 1, 'numeric', 'Two-step: add or subtract first, then multiply', 'There are 2 red balloons and 3 blue balloons in each bunch. How many balloons are in 3 bunches?', '[]', '15', '(2+3)*3', 'One bunch has $2 + 3 = 5$ balloons. Three bunches have $3 \times 5 = 15$ balloons.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 = 5 balloons per bunch; 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
