INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('098e1dae-24e6-4cc6-81c0-0ffe6e568cf4', 'NC26.3.ANR.7', 2, 'numeric', 'Compare a fraction with one half and one whole', 'How many of these fractions are greater than $\frac{1}{2}$? $\frac{1}{3}$, $\frac{3}{4}$, $\frac{3}{8}$, $\frac{5}{6}$, $\frac{4}{8}$, $\frac{2}{3}$', '[]', '3', '3', 'The fractions greater than one half are $\frac{3}{4}$, $\frac{5}{6}$ and $\frac{2}{3}$. The fractions $\frac{1}{3}$ and $\frac{3}{8}$ are less than one half, and $\frac{4}{8}$ equals one half.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 < 1/2; 3/4 > ; 3/8 < (4/8); 5/6 > (3/6); 4/8 = 1/2 not greater; 2/3 > (2/4). Greater: 3/4, 5/6, 2/3. Count 3.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
