INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1359ee62-023a-4fbf-973d-4c8fe00496f5', 'NC26.3.SGMR.1', 1, 'choice', 'Right, acute and obtuse angles', 'Which of these is a good model of a right angle?', '["the corner of a notebook page","the sharp tip of a pencil","a book opened until it lies flat","the narrow tip of a slice of pie"]', 'the corner of a notebook page', NULL, 'The corner of a notebook page is a square corner, which is a right angle. The pencil tip and the pie tip are narrow, so they are acute. A book lying flat is a straight line.', 'checked', '{"lint":[],"solve":{"answer":"the corner of a notebook page","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A notebook page corner is a square corner (right angle). Pie tip and pencil tip are acute; a flat-open book is a straight angle.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4b834d-71c2-4183-9eb2-056a1b6d5647', 'NC26.3.SGMR.1', 2, 'choice', 'Perpendicular lines', 'Which of these shapes has sides that are perpendicular to each other?', '["a circle","a rectangle","a triangle with 3 equal sides","a rhombus with no right angles"]', 'a rectangle', NULL, 'Perpendicular sides meet at square corners. A rectangle has 4 square corners. The triangle and the rhombus have no square corners, and a circle has no sides.', 'checked', '{"lint":[],"solve":{"answer":"a rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rectangle''s adjacent sides meet at right angles, so they are perpendicular. Equilateral triangle (60 degree angles), circle, non-square rhombus have none.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('043a87ef-4272-4e61-94b6-019ecd8f060d', 'NC26.3.SGMR.1', 2, 'numeric', 'Right angles in shapes', 'Ben draws 3 rectangles. How many right angles do the 3 rectangles have in all?', '[]', '12', '3*4', 'Each rectangle has 4 right angles. $3 \times 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 rectangles x 4 right angles = 12.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
