INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09e08d67-6195-47af-928a-73753e915985', 'NC26.3.SGMR.2', 1, 'choice', 'Choose the right measuring tool', 'Which tool is best for finding how heavy a bag of rice is?', '["a ruler","a scale","a measuring cup","a clock"]', 'a scale', NULL, 'A scale measures weight. A ruler measures length, a measuring cup measures how much a container holds and a clock tells time.', 'checked', '{"lint":[],"solve":{"answer":"a scale","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Weight: a scale.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
