INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d6309f2-ffe8-49fc-939d-2c0eaea27310', 'NC26.3.SGMR.2', 2, 'choice', 'Estimate length, capacity and weight', 'About how much does a loaf of bread weigh?', '["1 ounce","10 pounds","1 pound","100 pounds"]', '1 pound', NULL, 'A loaf of bread weighs about 1 pound. 1 ounce is about one slice, and 10 or 100 pounds is far too heavy.', 'checked', '{"lint":[],"solve":{"answer":"1 pound","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A loaf of bread weighs about 1 pound.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
