INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d3c3706-3e7f-491e-9385-905d7aecfb1c', 'NC26.3.SGMR.2', 2, 'choice', 'One-step problem: weight', 'A bag of flour weighs 5 pounds. How many pounds do 6 bags of flour weigh?', '["11","1","30","56"]', '30', '6*5', '6 bags of 5 pounds each: $6 \times 5 = 30$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 5 = 30 pounds.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
