INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f03cf6f-9d36-4cef-a942-614343b0f3d6', 'NC26.3.SGMR.2', 3, 'numeric', 'Elapsed time: find the end time', 'A game starts at 6:20. The first half lasts 25 minutes, then there is a break of 10 minutes, and the second half lasts 25 minutes. The game ends at 7:__. What number goes in the blank?', '[]', '20', '20+(25+10+25-60)', 'The game takes $25 + 10 + 25 = 60$ minutes, which is 1 hour. 1 hour after 6:20 is 7:20. The blank is 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 + 10 + 25 = 60 min. 6:20 + 60 = 7:20. Blank is 20.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07895798-38d2-4bf2-803a-e8ebd8b3654f', 'NC26.3.SGMR.2', 3, 'numeric', 'Elapsed time: find the start time', 'Pablo finished his chores at 6:05. He worked for 50 minutes. He started at 5:__. What number goes in the blank?', '[]', '15', '60+5-50', 'Go back 5 minutes from 6:05 to 6:00. The other 45 minutes go back to 5:15. The blank is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6:05 - 5 = 6:00, - 45 more = 5:15. Blank is 15.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('007adc3d-8c14-4562-8542-67d2d0555103', 'NC26.3.SGMR.3', 1, 'numeric', 'Perimeter of a square', 'A square has sides that are each 5 inches long. What is the perimeter of the square in inches?', '[]', '20', '4*5', 'The perimeter is the distance around. A square has 4 equal sides: 5 + 5 + 5 + 5 = 20 inches.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 sides x 5 inches = 20 inches.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
