INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05f28318-886b-41e6-b07c-eabb41b0f4d3', 'NC26.3.SGMR.3', 1, 'choice', 'Area by tiling with unit squares', 'Which unit is best for measuring the area of a classroom floor?', '["feet","inches","square feet","miles"]', 'square feet', NULL, 'Area is the amount of flat space a shape covers, so it is measured in square units. Square feet suits a floor. Feet, inches and miles measure lengths.', 'checked', '{"lint":[],"solve":{"answer":"square feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area needs square units; a classroom floor suits square feet (not inches/feet/miles).","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
