INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('043092f8-0cbe-4397-97e9-ebfc3543e170', 'NC26.3.SGMR.3', 2, 'choice', 'Missing side length from the perimeter', 'A four-sided field has a perimeter of 50 meters. Three of its sides are 12 meters, 15 meters and 9 meters long. How many meters long is the fourth side?', '["36","86","14","26"]', '14', '50-12-15-9', 'The three known sides total $12 + 15 + 9 = 36$ meters. The fourth side is $50 - 36 = 14$ meters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 15 + 9 = 36; 50 - 36 = 14 meters.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
