INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15b40287-cf51-452c-b443-113324f46f5f', 'NC26.3.RD.1', 2, 'numeric', 'Compare categories: how many more or fewer', 'A frequency table shows how many books were borrowed: Monday 24, Tuesday 18 and Wednesday 31. How many more books were borrowed on Wednesday than on Tuesday?', '[]', '13', '31-18', 'Subtract: $31 - 18 = 13$ more books on Wednesday.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"31 - 18 = 13.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
