INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03708a97-6ed3-489b-96a8-b2abad2d5f65', 'NC26.3.RD.1', 2, 'numeric', 'Compare categories: how many more or fewer', 'In a picture graph, each picture stands for 2 students. The pizza row has 7 pictures and the taco row has 4 pictures. How many more students chose pizza than tacos?', '[]', '6', '(7-4)*2', 'Pizza has $7 - 4 = 3$ more pictures, and each picture stands for 2 students: $3 \times 2 = 6$ more students.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pizza 14, tacos 8. 14 - 8 = 6 (or 3 pictures x 2).","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
