VALUES ('9b000000-0000-4000-8000-000000000010', 'NC26.4.ANR.2', 2, 'numeric', 'Subtracting across zeros', 'Work out $60{,}000 - 24{,}375$.', '[]', '35625', '60000-24375', 'Regroup across the zeros: $60{,}000 - 24{,}375 = 35{,}625$. Check: $35{,}625 + 24{,}375 = 60{,}000$.', 'approved', '{"lint":[],"solve":null}', 'manual', '0c000000-0000-4000-8000-000000000001', '2026-10-17T00:00:00.000Z')
