INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b000000-0000-4000-8000-000000000011', 'NC26.4.ANR.2', 3, 'choice', 'Two steps: subtract, then add', 'A library had $52{,}318$ books. It gave away $8{,}749$ books and then bought $3{,}560$ new ones. How many books does it have now?', '["47,129","40,009","64,627","47,029"]', '47,129', '52318-8749+3560', '$52{,}318 - 8{,}749 = 43{,}569$, then $43{,}569 + 3{,}560 = 47{,}129$.', 'approved', '{"lint":[],"solve":null}', 'manual', '0c000000-0000-4000-8000-000000000001', '2026-10-17T00:00:00.000Z')
