INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05a9e7c2-dd86-4437-8032-46b27955efb0', 'NC26.4.ANR.1', 2, 'choice', 'Digit in a given place', 'Which number has the digit 7 in the hundreds place?', '["41,723","27,413","34,271","12,347"]', '41,723', '41723', 'In 41,723 the digits are 4 ten-thousands, 1 thousand, 7 hundreds, 2 tens, 3 ones. The other numbers have the 7 in the thousands, tens and ones places.', 'checked', '{"lint":[],"solve":{"answer":"41,723","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds digits: 41,723 -> 7; 12,347 -> 3; 27,413 -> 4; 34,271 -> 2. Only 41,723.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
