VALUES ('0b9ef42d-4f2a-48e9-9c8b-1b5f01f27b74', 'NC26.4.ANR.1', 3, 'choice', 'Write a number from its parts (expanded form)', 'Which number is equal to $3 \times 10{,}000 + 5 \times 1{,}000 + 4 \times 10 + 6$?', '["35,406","35,046","3,546","30,546"]', '35,046', '35046', '3 x 10,000 = 30,000; 5 x 1,000 = 5,000; 4 x 10 = 40; plus 6. The total is 35,046 (there are no hundreds).', 'checked', '{"lint":[],"solve":{"answer":"35,046","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30,000 + 5,000 + 40 + 6 = 35,046 (hundreds digit 0).","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
