INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03d85aa8-eb16-4013-8f4b-45ef78a85615', 'NC26.4.ANR.4', 1, 'numeric', 'Equation with a letter: write and solve for a story', 'Tomas buys 5 tickets that cost $t$ dollars each. He pays 40 dollars in all. The equation $5 \times t = 40$ matches the story. How many dollars does one ticket cost?', '[]', '8', '40/5', '$t = 40 \div 5 = 8$, so one ticket costs 8 dollars. Check: $5 \times 8 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t = 40 / 5 = 8.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('086c2995-24a0-487f-9222-0d75131ef6e6', 'NC26.4.ANR.4', 1, 'numeric', 'Equation with a letter: find the unknown in one step', 'Find the value of $m$: $m \div 4 = 8$.', '[]', '32', '8*4', 'Undo the division by multiplying: $m = 8 \times 4 = 32$. Check: $32 \div 4 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: a one-step equation, while the standard is two-step problems; still within ''equations with a letter for the unknown''.","work":"m = 8 x 4 = 32.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ca5c500-28a0-4dd7-ab90-9865eaa4147b', 'NC26.4.ANR.4', 1, 'numeric', 'Check by estimation: quotient', 'There are 355 students on 7 buses, with about the same number on each bus. Use $350 \div 7$ to estimate how many students ride on each bus.', '[]', '50', '350/7', '355 is close to 350, and $350 \div 7 = 50$. About 50 students ride on each bus.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"350 / 7 = 50.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c87929-a084-4177-aa96-c2ce57820ec6', 'NC26.4.ANR.4', 2, 'numeric', 'Solve a two-step equation with a letter', 'Find the value of $n$ in this equation: $n \times 6 + 4 = 52$.', '[]', '8', '(52-4)/6', 'Undo the adding first: $n \times 6 = 52 - 4 = 48$. Then undo the multiplying: $n = 48 \div 6 = 8$. Check: $8 \times 6 + 4 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n x 6 + 4 = 52 -> n x 6 = 48 -> n = 8.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f0d1100-229f-4951-b70a-4f110288f94c', 'NC26.4.ANR.4', 2, 'numeric', 'Equation with a letter: solve a two-step equation', 'Solve for $y$: $y \div 4 + 7 = 15$.', '[]', '32', '(15-7)*4', 'Take away 7: $15 - 7 = 8$, so $y \div 4 = 8$. Then $y = 8 \times 4 = 32$. Check: $32 \div 4 + 7 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y / 4 = 15 - 7 = 8; y = 32.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04fa1e85-4bff-4e0e-90a1-1e150b60e987', 'NC26.4.ANR.4', 2, 'choice', 'Equation with a letter: solve a two-step equation', 'What is the value of $k$ in $4 \times k - 10 = 30$?', '["5","40","10","30"]', '10', '(30+10)/4', 'Undo the subtraction: $30 + 10 = 40$, so $4 \times k = 40$ and $k = 10$. Check: $4 \times 10 - 10 = 30$. The choice 5 subtracts 10 instead of adding it, and 40 stops before dividing.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4k = 40; k = 10.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
