INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ce907a4-bdb7-452d-b207-80223dd4493e', 'NC26.4.ANR.5', 2, 'choice', 'Find a number between two numbers', 'The decimal 0.47 is between which two tenths?', '["0.3 and 0.4","0.5 and 0.6","0.4 and 0.5","0.7 and 0.8"]', '0.4 and 0.5', NULL, '0.47 is 47 hundredths. That is more than 40 hundredths (0.4) and less than 50 hundredths (0.5).', 'checked', '{"lint":[],"solve":{"answer":"0.4 and 0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.47 = 4 tenths 7 hundredths, between 0.4 and 0.5.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
