INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f97be20-bdb9-4d35-be0a-69dfc7b0907f', 'NC26.4.ANR.6', 1, 'numeric', 'Find a missing fraction in an equation', '$\frac{n}{9} - \frac{2}{9} = \frac{5}{9}$ What is $n$?', '[]', '7', '5+2', 'Before 2 ninths were taken away there were $5 + 2 = 7$ ninths. So $n = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n - 2 = 5, n = 7.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
