VALUES ('0a5449b4-1864-4fd0-8ef2-d57840d37f87', 'NC26.4.SGMR.3', 2, 'numeric', 'Find elapsed time across the hour', 'A train leaves at 10:35 a.m. and arrives at 12:10 p.m. How many minutes long is the trip?', '[]', '95', '25+60+10', 'From 10:35 to 11:00 is 25 minutes. From 11:00 to 12:00 is 60 minutes. From 12:00 to 12:10 is 10 minutes. In all, $25 + 60 + 10 = 95$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"95","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10:35 to 11:00 is 25; 11:00 to 12:00 is 60; 12:00 to 12:10 is 10. 25 + 60 + 10 = 95.","run_id":"claude-code","at":"2026-10-17T19:22:55.011Z"}}', 'ai', NULL, NULL)
