INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f091522-c16b-4427-8c1e-3e77adb291a9', 'NC26.4.SGMR.3', 2, 'choice', 'Convert between hours and minutes', 'Which is the same length of time as 85 minutes?', '["1 hour 15 minutes","1 hour 85 minutes","8 hours 5 minutes","1 hour 25 minutes"]', '1 hour 25 minutes', NULL, '85 minutes is 60 minutes plus 25 minutes. That is 1 hour 25 minutes.', 'checked', '{"lint":[],"solve":{"answer":"1 hour 25 minutes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"85 = 60 + 25: 1 hour 25 minutes.","run_id":"claude-code","at":"2026-10-17T19:22:55.011Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('096d62a9-4a36-4383-828a-f52f38b38a94', 'NC26.4.SGMR.3', 2, 'numeric', 'Metric length: convert larger units to smaller and solve', 'A bookshelf is 3 meters long. Each book is 5 centimeters thick. How many books fit side by side along the whole shelf?', '[]', '60', '3*100/5', '3 meters is 300 centimeters. The number of books is $300 \div 5 = 60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 m = 300 cm; 300 / 5 = 60 books.","run_id":"claude-code","at":"2026-10-17T19:22:55.011Z"}}', 'ai', NULL, NULL)
