INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e5437b8-cf17-4536-accb-4ba78a77577e', 'NC26.4.SGMR.3', 3, 'numeric', 'Mass: convert and subtract', 'A recipe needs 2 kilograms of flour. Mia has 1,450 grams of flour. How many more grams of flour does she need?', '[]', '550', '2*1000-1450', '2 kilograms is 2 x 1,000 = 2,000 grams. She needs 2,000 - 1,450 = 550 more grams.', 'checked', '{"lint":[],"solve":{"answer":"550","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 kg = 2,000 g; 2,000 - 1,450 = 550.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
