INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('097fedde-16f3-42c5-bcab-6428e17f4956', 'NC26.4.SGMR.4', 1, 'choice', 'Choose area or perimeter for the situation', 'Which job needs the perimeter of a rectangle?', '["Covering a rectangular floor with tiles","Finding how much paint covers a rectangular wall","Putting a fence around a rectangular yard","Finding how much grass seed covers a rectangular lawn"]', 'Putting a fence around a rectangular yard', NULL, 'A fence goes around the edge, so it is the distance around, the perimeter. The other jobs cover a surface, which is area.', 'checked', '{"lint":[],"solve":{"answer":"Putting a fence around a rectangular yard","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tiles, paint and grass seed all cover a surface (area). A fence goes around the edge (perimeter).","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
