INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0efaf739-7597-43ce-a013-23c25c7a341d', 'NC26.4.SGMR.4', 2, 'choice', 'Perimeter of a rectilinear figure', 'An L-shaped garden has six sides. Going around the edge, they measure 8 m, 3 m, 5 m, 4 m, 3 m and 7 m. What is its perimeter in meters?', '["30","27","36","60"]', '30', '8+3+5+4+3+7', 'Add all six sides: $8 + 3 + 5 + 4 + 3 + 7 = 30$ meters. 27 leaves out a side, and 36 is the area of the garden.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Check shape: 8 = 5 + 3 and 7 = 3 + 4, consistent. Perimeter = 8 + 3 + 5 + 4 + 3 + 7 = 30 m.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('065f9633-b463-4482-bae1-6ce3bc003d80', 'NC26.4.SGMR.4', 3, 'choice', 'Smallest perimeter for a given area', 'Which rectangle has an area of 64 square centimeters and the smallest perimeter?', '["8 cm by 8 cm","4 cm by 16 cm","2 cm by 32 cm","1 cm by 64 cm"]', '8 cm by 8 cm', NULL, 'All four have area 64 square centimeters. Perimeters: 8 by 8 is 2 x 16 = 32 cm, 4 by 16 is 2 x 20 = 40 cm, 2 by 32 is 2 x 34 = 68 cm and 1 by 64 is 2 x 65 = 130 cm. The smallest is 8 cm by 8 cm.', 'checked', '{"lint":[],"solve":{"answer":"8 cm by 8 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 1x64 -> 130, 2x32 -> 68, 4x16 -> 40, 8x8 -> 32. Smallest: 8 cm by 8 cm.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0378e4ed-44bb-4e24-8bc0-6ff529368f8e', 'NC26.4.SGMR.4', 3, 'choice', 'Fixed perimeter, changing area', 'A rectangle is 12 units long and 4 units wide. Its length is made 2 units shorter and its width is made 2 units longer. Which statement is true?', '["The perimeter stays the same; the area decreases by 12 square units","The perimeter stays the same; the area increases by 12 square units","The perimeter stays the same; the area stays the same","The perimeter decreases; the area increases by 12 square units"]', 'The perimeter stays the same; the area increases by 12 square units', NULL, 'Old: 12 by 4, perimeter 32, area 48. New: 10 by 6, perimeter 32, area 60. The perimeter is the same and the area goes up by $60 - 48 = 12$ square units.', 'checked', '{"lint":[],"solve":{"answer":"The perimeter stays the same; the area increases by 12 square units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original 12 x 4: perimeter 32, area 48. New 10 x 6: perimeter 32, area 60. Perimeter same, area up 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19506edb-8e16-45c2-8e5e-02e6f721ddc3', 'NC26.4.RD.1', 1, 'numeric', 'Numerical or categorical question', 'Four survey questions are listed. 1. What is your favorite snack? 2. How many cousins do you have? 3. What color is your backpack? 4. In which month is your birthday? Which question number is the only numerical question?', '[]', '2', '2', 'Only question 2 is answered with a number. The others are answered with names (snacks, colors, months), so they are categorical.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 snack: word. 2 cousins: number. 3 backpack color: word. 4 birthday month: a month name. Only question 2 is numerical.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
