INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01720654-2c1a-47ac-a78e-2e02798ab9c4', 'NC26.4.RD.1', 3, 'numeric', 'Line plot with fractional measurements', 'A line plot shows the lengths of carrots in inches. The shortest carrot is $2\frac{1}{4}$ inches and the longest is $4\frac{3}{4}$ inches. What is the range of the lengths, in inches?', '[]', '2 1/2', '19/4-9/4', 'Range = $4\frac{3}{4} - 2\frac{1}{4} = 2\frac{2}{4} = 2\frac{1}{2}$ inches.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 3/4 - 2 1/4 = 2 2/4 = 2 1/2 inches.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
