VALUES ('1ba0a199-cf38-4d51-b8eb-83f902849dcb', 'NC26.5.ANR.2', 3, 'numeric', 'Expanded form of a number', 'What number is equal to $6 + 14 \times 0.1 + 5 \times 0.001$?', '[]', '7.405', '6+14*0.1+5*0.001', '$14 \times 0.1 = 1.4$ and $5 \times 0.001 = 0.005$. So the number is $6 + 1.4 + 0.005 = 7.405$.', 'checked', '{"lint":[],"solve":{"answer":"7.405","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 0.1 = 1.4; 5 x 0.001 = 0.005; 6 + 1.4 + 0.005 = 7.405.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
