INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('195dc91c-2f35-4338-b6be-4d07bce71f38', 'NC26.5.ANR.3', 2, 'choice', 'Multiply a three-digit number by a two-digit number', 'Ana says that $256 \times 34 = 1{,}792$. Which sentence explains what she most likely did?', '["She multiplied 256 by the tens digit 3 only.","She added $256 \\times 4$ and $256 \\times 3$, but she should have added $256 \\times 4$ and $256 \\times 30$.","She multiplied 256 by the ones digit 4 only.","She added 256 and 34 instead of multiplying."]', 'She added $256 \times 4$ and $256 \times 3$, but she should have added $256 \times 4$ and $256 \times 30$.', NULL, '$256 \times 4 = 1{,}024$ and $256 \times 3 = 768$, and $1{,}024 + 768 = 1{,}792$. Ana forgot that the 3 in 34 means 30. The correct product is $1{,}024 + 7{,}680 = 8{,}704$.', 'checked', '{"lint":[],"solve":{"answer":"She added $256 \\times 4$ and $256 \\times 3$, but she should have added $256 \\times 4$ and $256 \\times 30$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct: 256 x 34 = 8,704. 256 x 4 = 1,024 and 256 x 3 = 768; 1,024 + 768 = 1,792, which is her answer. So she used 3 instead of 30. 256 x 3 = 768, 256 x 4 = 1,024, 256 + 34 = 290 all differ from 1,792.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
