VALUES ('02f7f4c9-7018-4338-9503-216798adcf9c', 'NC26.5.ANR.3', 2, 'choice', 'Find the quotient and remainder', 'What is $3{,}947 \div 6$? Give the quotient with its remainder.', '["657","658","657 R 5","656 R 5"]', '657 R 5', NULL, '$6 \times 657 = 3{,}942$, and $3{,}947 - 3{,}942 = 5$. So the answer is 657 with remainder 5.', 'checked', '{"lint":[],"solve":{"answer":"657 R 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 657 = 3,942; 3,947 - 3,942 = 5. So 657 R 5.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
