INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12bf8b08-8c49-40ef-84bb-01b0657bbf4b', 'NC26.5.SGMR.2', 2, 'numeric', 'Read the coordinates of a point', 'A point is 7 units from the y-axis and 3 units from the x-axis. What is the sum of its x-coordinate and its y-coordinate?', '[]', '10', '7+3', 'The point is $(7, 3)$ because the distance from the y-axis is the x-coordinate. The sum is 7 + 3 = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 7 (distance from y-axis), y = 3 (distance from x-axis). 7 + 3 = 10.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
