INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14e554d4-6e96-4a47-9216-531e2bf9152b', 'NC26.5.SGMR.2', 2, 'choice', 'Find a missing corner of a shape', 'A square has its top-left corner at $(3, 9)$ and each side is 5 units long. What is its bottom-left corner?', '["$(3, 4)$","$(8, 9)$","$(8, 4)$","$(3, 14)$"]', '$(3, 4)$', NULL, 'The bottom-left corner is directly below the top-left corner. Going down 5 gives a y-coordinate of 9 - 5 = 4, so it is $(3, 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom-left is 5 below the top-left: (3, 9 - 5) = (3, 4).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0df0fbfb-a8d9-402a-b9f2-87ebcc66e65d', 'NC26.5.SGMR.2', 2, 'choice', 'Ordered pairs from two number patterns', 'A pattern of ordered pairs is $(1, 4)$, $(2, 5)$, $(3, 6)$, $(4, 7)$. Which rule describes how each y-coordinate is related to its x-coordinate?', '["y is 3 more than x","y is 3 times x","y is 4 more than x","y is 4 times x"]', 'y is 3 more than x', NULL, 'In every pair the y-coordinate is 3 greater than the x-coordinate: 1 + 3 = 4, 2 + 3 = 5, and so on.', 'checked', '{"lint":[],"solve":{"answer":"y is 3 more than x","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4-1 = 5-2 = 6-3 = 7-4 = 3: y is 3 more than x.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014fef62-bbc9-4cb9-b8b4-11019095e252', 'NC26.5.SGMR.2', 3, 'numeric', 'Points on an axis or on the same line', 'Here are five points: $(0, 7)$, $(7, 0)$, $(0, 0)$, $(5, 5)$ and $(9, 0)$. How many of them are on the x-axis? The origin counts.', '[]', '3', NULL, 'A point is on the x-axis when its y-coordinate is 0. That is true for $(7, 0)$, $(0, 0)$ and $(9, 0)$. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"On the x-axis means y = 0: (7, 0), (0, 0), (9, 0). That is 3.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01617946-46c8-4b4b-8b4a-e0286fbea954', 'NC26.5.SGMR.2', 3, 'numeric', 'Ordered pairs from a real situation', 'A taxi charges a flat fee of 3 dollars plus 2 dollars for each mile. A point (miles, cost in dollars) is plotted for each trip. What is the y-coordinate of the point for a 9-mile trip?', '[]', '21', '3+2*9', 'The trip costs 2 x 9 = 18 dollars for the miles plus the flat fee of 3 dollars, which is 21 dollars. The point is $(9, 21)$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2 x 9 = 21.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
