INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25f2a8b9-363f-4d76-8ad4-1d04d700bf7a', 'NC26.5.SGMR.3', 3, 'choice', 'Convert a larger customary unit to a smaller one', 'A road is 7 miles long. How many yards long is it? (1 mile = 1,760 yards)', '["1,767","12,320","36,960","1,232"]', '12,320', '7*1760', '$7 \times 1{,}760 = 12{,}320$ yards. Adding gives 1,767; using the 5,280 feet in a mile gives 36,960; and 1,232 drops a zero.', 'checked', '{"lint":[],"solve":{"answer":"12,320","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 mi x 1,760 yd/mi = 12,320 yd.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
