INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cd5d704-017e-47b9-ad29-9b0352959e50', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume in a real-world problem', 'A rectangular tank is 5 meters long and 4 meters wide. Water 2 meters deep is poured in, and then 10 more cubic meters of water are added. How deep is the water now, in meters?', '[]', '2.5', '(5*4*2+10)/(5*4)', 'The first water is $5 \times 4 \times 2 = 40$ cubic meters, so now there are $40 + 10 = 50$ cubic meters. The base area is $5 \times 4 = 20$ square meters, so the depth is $50 \div 20 = 2.5$ meters.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 5 x 4 = 20 sq m. Water 20 x 2 = 40, plus 10 = 50 cubic m. Depth 50 / 20 = 2.5 m (assuming the tank is tall enough; its height is not given).","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1446b605-fb15-49c5-966e-8dad0d9b12bb', 'NC26.5.RD.1', 1, 'choice', 'Choose the best graph for the data', 'Which graph is best for showing how the height of a plant changes each week?', '["A bar graph of favorite plants","A line plot of leaf lengths","A tally chart of plant colors","A line graph"]', 'A line graph', NULL, 'A line graph joins points in order of time, so it shows how something changes from week to week. The other displays show favorite plants, one set of lengths or counts of colors.', 'checked', '{"lint":[],"solve":{"answer":"A line graph","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change over time (weekly height) is shown with a line graph.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('077b5701-b12e-41cc-9923-d322ef9f4b3d', 'NC26.5.RD.1', 1, 'choice', 'Read a line plot with fractional measurements', 'A line plot shows the cups of sugar used by 5 cooks: $\frac{1}{2}$, $\frac{1}{4}$, $\frac{3}{4}$, $\frac{1}{4}$, $\frac{1}{2}$. What is the greatest amount shown on the line plot?', '["$\\frac{1}{2}$ cup","$\\frac{1}{4}$ cup","$\\frac{3}{4}$ cup","$2\\frac{1}{4}$ cups"]', '$\frac{3}{4}$ cup', NULL, 'The amounts are $\frac{1}{4}$, $\frac{1}{2}$ and $\frac{3}{4}$ cup, and $\frac{3}{4}$ is the greatest. ($2\frac{1}{4}$ cups is the total of all five amounts, not the greatest amount.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$ cup","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values 1/4, 1/2, 3/4; greatest is 3/4 cup. (2 1/4 is the total, not a value on the plot.)","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
