INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c1cecd3-e06e-4302-80a2-80b5917f2daa', 'NC26.5.RD.1', 2, 'choice', 'Make a graph: scale, labels and plotting', 'Marcus makes a bar graph for these numbers of votes: 12, 28, 36, 44 and 20. Which scale is best?', '["0 to 50, counting by 1s","0 to 50, counting by 10s","0 to 100, counting by 50s","0 to 20, counting by 5s"]', '0 to 50, counting by 10s', NULL, 'The scale must reach past the greatest number, 44, so 0 to 50 works. Counting by 10s gives a few lines that are easy to read. Counting by 1s has far too many lines, counting by 50s is too coarse, and a scale to 20 is too short for 44.', 'checked', '{"lint":[],"solve":{"answer":"0 to 50, counting by 10s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max 44 needs a scale to at least 44. 0-20 too short; by 1s too many lines; by 50s too coarse; 0 to 50 by 10s fits.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
