INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0393b797-1db1-4689-9509-7e74ba6185ac', 'NC26.5.RD.1', 2, 'choice', 'Make a graph: scale, labels and plotting', 'Kai makes a line graph of a plant''s height. Weeks are along the bottom and height in centimeters is up the side. The plant was 40 cm tall in Week 3. Where should Kai plot the point?', '["Above Week 3 and across from 40 cm","Above Week 40 and across from 3 cm","Above Week 3 and across from 3 cm","Above Week 40 and across from 40 cm"]', 'Above Week 3 and across from 40 cm', NULL, 'The point goes above the Week 3 mark on the bottom axis and level with 40 on the side axis, because the week is on the bottom and the height is up the side.', 'checked', '{"lint":[],"solve":{"answer":"Above Week 3 and across from 40 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = Week 3 on the bottom, y = 40 cm up the side.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
