VALUES ('03a0c259-4e37-4e74-826a-88086f142172', 'NC26.6.ANR.3', 2, 'numeric', 'One-step decimal word problem', 'Gas costs 3.49 dollars per gallon. How many dollars do 8 gallons cost?', '[]', '27.92', '3.49*8', '$8 \times 3.49 = 27.92$ dollars. Check: 8 x 3.50 is 28.', 'checked', '{"lint":[],"solve":{"answer":"27.92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 3.49 = 27.92 dollars.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
