INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1883760a-2150-4b01-a11f-404b0165d04d', 'NC26.6.ANR.3', 2, 'choice', 'One-step decimal word problem', 'Zed walks 1.25 kilometers each day. How many kilometers does he walk in 12 days?', '["1.5","15","150","13.25"]', '15', '1.25*12', '$12 \times 1.25 = 15$ kilometers. Four days make 5 kilometers, and 12 days is 3 times that.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 1.25 = 15 km.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
