INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16c5bebe-d028-464e-b3d6-9bb8857ed286', 'NC26.6.ANR.3', 2, 'numeric', 'Finding a missing number in a decimal equation', 'What is the value of n in $17.5 - n = 9.875$?', '[]', '7.625', '17.5-9.875', 'The missing amount is what is left after taking 9.875 from 17.5: $n = 17.500 - 9.875 = 7.625$.', 'checked', '{"lint":[],"solve":{"answer":"7.625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 17.500 - 9.875 = 7.625. Check: 9.875 + 7.625 = 17.5.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bbf5f48-236a-4622-8f1a-da33560e7311', 'NC26.6.ANR.3', 3, 'choice', 'Estimating with decimals', 'Which expression gives the best estimate of $24.9 \times 0.31$?', '["$25 \\times 3$","$2.5 \\times 0.3$","$25 \\times 0.3$","$25 \\times 0.03$"]', '$25 \times 0.3$', NULL, '24.9 is about 25 and 0.31 is about 0.3, so the estimate is $25 \times 0.3 = 7.5$. (The exact product is 7.719.) The other expressions are 10 times too big or 10 times too small.', 'checked', '{"lint":[],"solve":{"answer":"$25 \\times 0.3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24.9 is about 25 and 0.31 is about 0.3, so 25 x 0.3 (= 7.5; exact 7.719).","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
