VALUES ('042aed9b-e9c3-482f-b4e2-fbf49451fd20', 'NC26.6.ANR.4', 1, 'numeric', 'Subtracting integers', 'What is $5 - 9$?', '[]', '-4', '5-9', '$5 - 9 = 5 + (-9)$. Nine negative units cancel 5 positive units and leave 4 negative units, so the answer is $-4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 9 = 5 + (-9) = -4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
