VALUES ('018d9ff7-95f3-41b7-8c19-6391f5c5290b', 'NC26.6.ANR.5', 2, 'choice', 'Absolute value', 'Select the true statement.', '["$|-4| < |4|$","$|-4| = -4$","$|-4| < 0$","$|-4| = |4|$"]', '$|-4| = |4|$', NULL, 'Both $-4$ and 4 are 4 units from 0, so $|-4| = |4| = 4$. An absolute value is never negative.', 'checked', '{"lint":[],"solve":{"answer":"$|-4| = |4|$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-4| = 4 = |4|. 4 < 0 false; 4 = -4 false; 4 < 4 false.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
