INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e2c31d0-3975-4ae5-a191-1b6be36be267', 'NC26.6.ANR.6', 2, 'choice', 'Parts of an expression', 'A phone plan costs $20 + 5g$ dollars for $g$ gigabytes of data. What does the 5 stand for?', '["the cost of each gigabyte, in dollars","the fixed fee, in dollars","the number of gigabytes","the total cost, in dollars"]', 'the cost of each gigabyte, in dollars', NULL, 'The 5 is multiplied by $g$, the number of gigabytes, so it is the price of each gigabyte. The 20 is the fixed fee.', 'checked', '{"lint":[],"solve":{"answer":"the cost of each gigabyte, in dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 multiplies g (gigabytes), so it is the cost per gigabyte; 20 is the fixed fee.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
