VALUES ('09444dbf-74ba-42f5-af53-5557fbde302a', 'NC26.6.ANR.7', 1, 'choice', 'Checking a solution by substitution', 'Which equation is true when $x = 5$?', '["$x + 3 = 2$","$x + 3 = 8$","$x - 3 = 8$","$3x = 8$"]', '$x + 3 = 8$', NULL, 'Put 5 in place of $x$: $5 + 3 = 8$ is true. The others give $5 + 3 = 8 \ne 2$, $5 - 3 = 2 \ne 8$ and $3 \times 5 = 15 \ne 8$.', 'checked', '{"lint":[],"solve":{"answer":"$x + 3 = 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 5: 5 - 3 = 2, 15, 8, 5 + 3 = 8. Only x + 3 = 8 is true.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
