INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('168d6950-7bfc-4781-a2c2-e07ed4e6d9e7', 'NC26.6.SGMR.2', 1, 'numeric', 'Distance from a point to an axis', 'How many units is the point $(0, -7)$ from the origin?', '[]', '7', '7', 'The point is on the y-axis, 7 units below the origin. The distance is 7 units.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"On the y-axis, 7 below the origin: 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
