INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c853b7-613d-48d0-8158-0f6e6631159c', 'NC26.6.RD.3', 1, 'choice', 'Reading displays with unusual scales or layouts', 'A line plot of the lengths of pencil stubs, in inches, has these stacks of dots: $\frac{1}{2}$ inch, 2 dots; $\frac{3}{4}$ inch, 4 dots; 1 inch, 3 dots. Which length is the most common?', '["$\\frac{1}{2}$ inch","$\\frac{3}{4}$ inch","1 inch","$\\frac{1}{4}$ inch"]', '$\frac{3}{4}$ inch', NULL, 'The tallest stack is above $\frac{3}{4}$ inch, with 4 dots, so $\frac{3}{4}$ inch is the most common length. The stack at $\frac{1}{2}$ inch has 2 dots and the stack at 1 inch has 3. There are no dots at $\frac{1}{4}$ inch.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$ inch","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 inch has the tallest stack (4 dots).","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('005ee6d7-1483-40fc-9894-b73714af9ec6', 'NC26.6.RD.3', 2, 'choice', 'Placing values in histogram intervals', 'A histogram of lengths in centimeters uses the intervals 0 up to 5, 5 up to 10 and 10 up to 15. Each interval includes its left end but not its right end. A length of exactly 10 cm is counted in which bar?', '["5 up to 10","0 up to 5","10 up to 15","It is not counted in any bar"]', '10 up to 15', NULL, 'The interval 5 up to 10 does not include 10, because it leaves out its right end. The interval 10 up to 15 includes its left end, 10, so a length of exactly 10 cm goes in that bar.', 'checked', '{"lint":[],"solve":{"answer":"10 up to 15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intervals include the left end: 10 is in [10, 15), not in [5, 10).","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0947c324-8ff2-4bf4-8758-34b8846cce88', 'NC26.6.RD.3', 2, 'numeric', 'Finding the median from a display', 'A histogram shows 41 values. When the values are listed in order from least to greatest, the median is the value in which position? Count the smallest value as position 1.', '[]', '21', '(41+1)/2', 'With an odd number of values, the median is the middle one. There are 20 values below it and 20 above it, so it is in position $20 + 1 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"41 values: (41+1)/2 = 21st position, 20 on each side.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03800d7f-71c6-4494-96cd-1e5387941435', 'NC26.6.RD.3', 2, 'choice', 'Choosing a display and knowing what it shows', 'Which question can a histogram answer that a box plot cannot?', '["What is the median?","How many values are in the interval 20 to 29?","What is the third quartile?","What is the interquartile range?"]', 'How many values are in the interval 20 to 29?', NULL, 'The height of a histogram bar tells how many values are in its interval. A box plot shows the median, the quartiles and the IQR, but not how many values fall in a particular interval.', 'checked', '{"lint":[],"solve":{"answer":"How many values are in the interval 20 to 29?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A box plot shows Q3, the median and the IQR, but not counts in an interval; a histogram with that interval does.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b0c489a-5619-4f68-bf2f-dcc713150b9e', 'NC26.6.RD.3', 3, 'numeric', 'Share of the data in a part of a box plot', 'In a box plot, exactly one quarter of the values are above the third quartile. Kayla counts 15 values above the third quartile. How many values are in the data set?', '[]', '60', '15*4', 'The 15 values are one quarter of the data, so the whole data set is 4 times as large: $15 \times 4 = 60$ values.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 is one quarter, so the total is 15 x 4 = 60.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07ee4024-f594-4e16-bee6-8d2f0ab798d8', 'NC26.6.RD.3', 3, 'choice', 'Comparing the center and spread of two displays', 'Two histograms use the same five intervals, and each shows 20 values. Histogram P has bar heights 2, 5, 6, 5 and 2, from left to right. Histogram Q has bar heights 8, 2, 0, 2 and 8. Which statement is true?', '["P is more spread out, because its bars are taller in the middle","Q is more spread out, because more of its values are in the outer bars","P and Q have the same spread, because they have the same intervals","Q is less spread out, because its middle bar is empty"]', 'Q is more spread out, because more of its values are in the outer bars', NULL, 'In P, 12 of the 20 values are in the three middle bars and only 4 are in the two outer bars. In Q, 16 of the 20 values are in the outer bars, so many values are far from the middle. That makes Q more spread out. Having the same intervals does not make the spread the same.', 'checked', '{"lint":[],"solve":{"answer":"Q is more spread out, because more of its values are in the outer bars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P (2,5,6,5,2) piles values in the middle; Q (8,2,0,2,8) puts 16 of 20 in the outer bars, far from the centre, so Q is more spread out.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0990908b-760d-41cf-bdc0-21020237dd1c', 'NC26.6.RD.4', 1, 'choice', 'The mean as a balance point or fair share', 'Which statement describes the mean of a data set as its balance point?', '["The mean is the value that appears most often in the data set","The mean is the middle value when the data are put in order","The total distance of the values above the mean equals the total distance of the values below the mean","The mean is the distance from the least value to the greatest value"]', 'The total distance of the values above the mean equals the total distance of the values below the mean', NULL, 'If the data were weights on a see-saw, the mean is the point where it balances: the distances of the values above it add up to the same total as the distances of the values below it. The value that appears most often is the mode, the middle value is the median, and the distance from the least to the greatest value is the range.', 'checked', '{"lint":[],"solve":{"answer":"The total distance of the values above the mean equals the total distance of the values below the mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The balance-point view: the sum of distances above the mean equals the sum of distances below it. The others describe median, mode, range.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('068f4518-a46b-43f6-99d8-59c94825d889', 'NC26.6.RD.4', 1, 'choice', 'The mean as a balance point or fair share', 'A data set has the values 2, 6 and 10, and its mean is 6. Which statement is true?', '["The 2 is 4 below the mean and the 10 is 6 above it, so they balance each other","The 2 is 4 below the mean and the 10 is 4 above it, so they balance each other","The 2 is 6 below the mean and the 10 is 4 above it, so they balance each other","The 2 and the 10 are both 4 above the mean, so they balance each other"]', 'The 2 is 4 below the mean and the 10 is 4 above it, so they balance each other', NULL, '$6 - 2 = 4$, so the 2 is 4 below the mean. $10 - 6 = 4$, so the 10 is 4 above the mean. Equal distances on the two sides balance each other. The 6 itself is exactly at the mean.', 'checked', '{"lint":[],"solve":{"answer":"The 2 is 4 below the mean and the 10 is 4 above it, so they balance each other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 is 6-2 = 4 below; 10 is 10-6 = 4 above; they balance. Third option.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('091aa4f3-1949-4412-b3ff-52a160e1f201', 'NC26.6.RD.4', 1, 'numeric', 'Finding a mean', 'Rosa read 12, 15 and 18 pages on three nights. What was the mean number of pages she read per night?', '[]', '15', '(12+15+18)/3', 'She read $12 + 15 + 18 = 45$ pages in 3 nights. The mean is $45 \div 3 = 15$ pages per night.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12+15+18 = 45; 45/3 = 15.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('245fd1c4-db55-46b2-bdb2-bb49748b604b', 'NC26.6.RD.4', 2, 'numeric', 'The mean as a balance point or fair share', 'A data set of four values has a mean of 20. Three of the values are 13, 17 and 26. How many units above the mean is the fourth value?', '[]', '4', '(4*20-13-17-26)-20', 'Four values with a mean of 20 add up to $4 \times 20 = 80$. The three known values add up to $13 + 17 + 26 = 56$, so the fourth value is $80 - 56 = 24$. That is $24 - 20 = 4$ units above the mean.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 4*20 = 80. 13+17+26 = 56. Fourth = 24, which is 24-20 = 4 above the mean. (Check deviations: -7, -3, +6, +4 sum to 0.)","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1494a086-e224-4273-8e21-7081c749b665', 'NC26.6.RD.4', 2, 'choice', 'Using a mean to find a missing value or a total', 'Five students have a mean of 14 books each. Four of the students have 10, 12, 15 and 18 books. How many books does the fifth student have?', '["15","14","13.75","70"]', '15', '5*14-10-12-15-18', 'Five students with a mean of 14 have $5 \times 14 = 70$ books in all. The four known students have $10 + 12 + 15 + 18 = 55$ books, so the fifth has $70 - 55 = 15$ books.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 5*14 = 70. 10+12+15+18 = 55. Fifth = 15.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3c4b93-7a11-41dd-a0a6-516ac2a0a8ce', 'NC26.6.RD.4', 2, 'choice', 'Choosing the best measure of center', 'For which data set is the median a better description of the center than the mean?', '["10, 11, 12, 13, 14","5, 6, 7, 8, 9","3, 4, 4, 5, 90","21, 22, 22, 23, 24"]', '3, 4, 4, 5, 90', NULL, 'In the first set the value 90 is far from the others, so the mean (21.2) is higher than four of the five values, while the median (4) is typical. The other sets have values close together, so the mean and the median agree.', 'checked', '{"lint":[],"solve":{"answer":"3, 4, 4, 5, 90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 3, 4, 4, 5, 90 has an outlier (mean 21.2 vs median 4). Others are symmetric, mean = median.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00db0187-13a2-4409-b258-78625e11c1e7', 'NC26.6.RD.4', 3, 'choice', 'Finding a mean', 'A shop sold 36, 42, 29, 51 and 38 sandwiches on five days. What is the mean number of sandwiches sold per day?', '["38","39.2","49","196"]', '39.2', '(36+42+29+51+38)/5', 'The sales add up to $36 + 42 + 29 + 51 + 38 = 196$. Dividing by 5 days gives $196 \div 5 = 39.2$. The number 38 is the median, 49 comes from dividing by 4, and 196 is the total.', 'checked', '{"lint":[],"solve":{"answer":"39.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36+42+29+51+38 = 196; 196/5 = 39.2.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0936791b-7dcf-4bc4-911d-0b6b933c2dd9', 'NC26.6.RD.4', 3, 'choice', 'Comparing the variability of two data sets', 'A data set is 15, 18, 20, 22 and 25. A new value, 30, is added to the set. By how many units does the range increase?', '["5","15","10","30"]', '5', '(30-15)-(25-15)', 'Before, the range is $25 - 15 = 10$. After adding 30, the range is $30 - 15 = 15$. It increases by $15 - 10 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old range 25-15 = 10; new 30-15 = 15; increase 5.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12c6952f-c1c4-4879-a314-e45fb3073960', 'NC26.6.RD.5', 1, 'choice', 'Reflecting on the question and the methods of an investigation', 'A class wants to choose 20 students from the whole school to answer a survey. Which is the fairest way to choose them?', '["Put every student''s name in a hat and draw 20 names","Choose the 20 students who sit closest to the teacher","Choose the first 20 students who arrive at school","Choose the 20 students who are the class''s best friends"]', 'Put every student''s name in a hat and draw 20 names', NULL, 'Drawing names from a hat gives every student the same chance of being chosen. The other ways favor certain students, such as early arrivals or friends, and so can give a biased sample.', 'checked', '{"lint":[],"solve":{"answer":"Put every student''s name in a hat and draw 20 names","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawing names from a hat gives every student an equal chance.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e6704b0-1df5-480f-a46e-4b4f941c6e5f', 'NC26.6.RD.5', 1, 'numeric', 'Reflecting on the question and the methods of an investigation', 'A student stands at the school door and surveys every 5th student who walks out. A total of 100 students walk out. How many students does she survey?', '[]', '20', '100/5', 'Every 5th student means 1 student out of every 5, so she surveys $100 \div 5 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Students 5, 10, ..., 100: 100/5 = 20.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e95f5c5-c249-40ff-beb8-6c390ed1c0b5', 'NC26.6.RD.5', 1, 'choice', 'Drawing an inference from variability', 'Bus 1 was late by 5, 6, 5, 6 and 5 minutes on five days. Bus 2 was late by 0, 12, 3, 10 and 0 minutes on the same days. Which statement is best supported?', '["Bus 1 is easier to plan around, because its lateness varies much less from day to day than Bus 2''s","Bus 2 is easier to plan around, because it was on time on two of the five days","Bus 2 is easier to plan around, because its lateness varies more from day to day","Neither bus is easier to plan around, because both were late on at least one of the five days"]', 'Bus 1 is easier to plan around, because its lateness varies much less from day to day than Bus 2''s', NULL, 'Bus 1''s lateness stays between 5 and 6 minutes, so you can predict it. Bus 2''s lateness ranges from 0 to 12 minutes, so it is hard to predict.', 'checked', '{"lint":[],"solve":{"answer":"Bus 1 is easier to plan around, because its lateness varies much less from day to day than Bus 2''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Soft: Bus 2 has the slightly lower mean lateness (5 vs 5.4), but ''plan around'' points clearly to predictability, so the key holds.","work":"Bus 1 range 6-5=1 (mean 5.4); Bus 2 range 12-0=12 (mean 5). Bus 1 is predictable, so easier to plan around.","run_id":"claude-code","at":"2026-10-18T03:35:29.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07cb9560-3062-442c-890a-c26a1aac2164', 'NC26.6.RD.5', 2, 'numeric', 'Drawing an inference from variability', 'Set K is 40, 42, 44, 46, 48. Set L has the same mean as Set K, but its range is 4 times as large as the range of Set K. What is the range of Set L?', '[]', '32', '4*(48-40)', 'The range of Set K is $48 - 40 = 8$. Set L''s range is $4 \times 8 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range K = 48-40 = 8; L = 4*8 = 32.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('077a2563-018f-4338-a799-1dc835091f00', 'NC26.6.RD.5', 2, 'choice', 'Reflecting on the question and the methods of an investigation', 'A student wants to find out how many hours students sleep. She asks, "Do you get enough sleep?" What is the problem with this question?', '["Sleep cannot be measured, so no question could give her the number of hours","The question is too long for most students to answer in the time that they have","The answers are yes or no, so they do not give the number of hours","It should ask for each student''s favorite bedtime, because that tells how long they sleep"]', 'The answers are yes or no, so they do not give the number of hours', NULL, 'The investigation needs a number of hours from each student. A yes or no answer does not give that, so the question should be changed to "How many hours did you sleep last night?"', 'checked', '{"lint":[],"solve":{"answer":"The answers are yes or no, so they do not give the number of hours","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Yes/no answers do not give numerical hours of sleep.","run_id":"claude-code","at":"2026-10-18T03:35:29.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bb811ee-2590-4984-a4a7-e832bdb7934a', 'NC26.6.RD.5', 2, 'choice', 'Reflecting on the question and the methods of an investigation', 'A student asks classmates, "Don''t you agree that homework takes far too long?" What is the problem with this question?', '["The question is too short for a survey","It pushes students toward one particular answer","The answers will all be the same anyway","It cannot be answered by collecting data"]', 'It pushes students toward one particular answer', NULL, 'The wording suggests the answer the student wants, so the results would be biased. A fair question would ask, "How many minutes do you spend on homework each night?"', 'checked', '{"lint":[],"solve":{"answer":"It pushes students toward one particular answer","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''Don''t you agree...far too long?'' is a leading question pushing one answer.","run_id":"claude-code","at":"2026-10-18T03:35:29.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4bd989-1e13-4935-9716-f8cdf3dcb290', 'NC26.6.RD.5', 3, 'numeric', 'Calculating the summary an investigation needs', 'Seven students'' bus rides, in minutes, were 14, 15, 15, 17, 18, 19 and 52. By how many minutes does the range decrease when the 52 is removed?', '[]', '33', '(52-14)-(19-14)', 'With the 52, the range is $52 - 14 = 38$ minutes. Without it, the range is $19 - 14 = 5$ minutes. The range decreases by $38 - 5 = 33$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 52: 52-14 = 38. Without: 19-14 = 5. Decrease 33.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04af63cf-d047-4451-8a3a-ed2de3d59720', 'NC26.6.RD.5', 3, 'choice', 'Communicating findings that the data support', 'A student surveys the 20 students in her class and finds that the median time spent on screens is 3 hours a day. She writes, "Students in our state spend a median of 3 hours a day on screens." What is the biggest problem with her claim?', '["She surveyed only one class, which may not represent the students in the whole state","A median cannot be used for time data like hours, so she should have used a mean","She should have used the range instead, because the range is always the best summary of data","The class has 20 students, an even number, so she could not have found a median for it"]', 'She surveyed only one class, which may not represent the students in the whole state', NULL, 'A conclusion can only be as wide as the group that was sampled. One class may not look like all the students in the state. A median can be found for time data, and a median can be found for an even number of values.', 'checked', '{"lint":[],"solve":{"answer":"She surveyed only one class, which may not represent the students in the whole state","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One class is not representative of the state; the median of an even count is the mean of the two middle values, so D false.","run_id":"claude-code","at":"2026-10-18T03:35:29.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('123da428-7571-4697-bed7-0802c0d34287', 'NC26.7.RPR.1', 1, 'choice', 'Recognize a proportional relationship from pairs of values', 'Which list of $(x, y)$ pairs shows a proportional relationship?', '["(1, 3), (2, 6), (3, 9)","(1, 3), (2, 5), (3, 7)","(1, 4), (2, 6), (3, 8)","(1, 2), (2, 5), (3, 8)"]', '(1, 3), (2, 6), (3, 9)', NULL, 'In a proportional relationship, $y \div x$ is the same for every pair. For (1, 3), (2, 6), (3, 9) it is always 3. In the other lists $y$ goes up by a fixed amount each time, but $y \div x$ changes, so they are not proportional.', 'checked', '{"lint":[],"solve":{"answer":"(1, 3), (2, 6), (3, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Proportional means y/x constant (and passes through origin). (1,4),(2,6),(3,8): 4, 3, 2.67 no. (1,2),(2,5),(3,8): 2, 2.5, 2.67 no. (1,3),(2,5),(3,7): 3, 2.5, 2.33 no. (1,3),(2,6),(3,9): 3, 3, 3 yes.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b82f56-0da7-4fe5-85a2-a456843d02fd', 'NC26.7.RPR.1', 1, 'choice', 'Test whether a relationship is proportional', 'A table shows the pairs $(x, y)$: $(1, 4)$, $(2, 8)$, $(3, 12)$ and $(4, 16)$. Is $y$ proportional to $x$?', '["No, because $y$ is not equal to $x$","No, because $y$ keeps getting larger","Yes, because $y \\div x$ is 4 for every pair","No, because the table has no pair with $x = 0$"]', 'Yes, because $y \div x$ is 4 for every pair', NULL, '$4 \div 1$, $8 \div 2$, $12 \div 3$ and $16 \div 4$ are all 4, so $y = 4x$ and the relationship is proportional. A proportional relationship does not need $y = x$, may increase, and the table need not list $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"Yes, because $y \\div x$ is 4 for every pair","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/1 = 8/2 = 12/3 = 16/4 = 4, so y = 4x: proportional.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0adceb1f-9c5c-4256-8e75-8325972d1fba', 'NC26.7.RPR.1', 1, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(3, 12)$ is on the graph of a proportional relationship between the hours $x$ Kim works and the dollars $y$ she earns. What does the point mean?', '["In 12 hours, Kim earns 3 dollars","In 3 hours, Kim earns 12 dollars","Kim earns 12 dollars each hour","Kim earns 3 dollars each hour"]', 'In 3 hours, Kim earns 12 dollars', NULL, 'A point $(x, y)$ means $x$ hours go with $y$ dollars, so $(3, 12)$ means 3 hours earn 12 dollars. That is $12 \div 3 = 4$ dollars for each hour.', 'checked', '{"lint":[],"solve":{"answer":"In 3 hours, Kim earns 12 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) = (3 hours, 12 dollars): in 3 hours she earns 12 dollars (rate 4 per hour, so the 3 and 12 per hour options are wrong).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b1b8ee0-37d0-4475-a88c-b9d845fe0bce', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate with fractions', '$\frac{3}{4}$ pound of cheese costs 6 dollars. How many dollars does 1 pound of the cheese cost?', '[]', '8', '6/(3/4)', '$6 \div \frac{3}{4} = 6 \times \frac{4}{3} = 8$ dollars per pound. (Check: $\frac{3}{4}$ of 8 is 6.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / (3/4) = 8 dollars per pound.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066c93c7-64d3-4af2-a71a-84fdec2f37af', 'NC26.7.RPR.1', 2, 'numeric', 'Write and use an equation y = kx', 'A canoe rental costs the same amount for each hour. The cost $c$, in dollars, for $h$ hours is $c = 6.5h$. Jo pays 52 dollars. For how many hours does Jo rent the canoe?', '[]', '8', '52/6.5', 'Put $c = 52$ into the equation: $52 = 6.5h$, so $h = 52 \div 6.5 = 8$ hours.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 = 6.5h, h = 8.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09c4edf2-4426-4aa5-8aed-4978be69dab0', 'NC26.7.RPR.1', 2, 'choice', 'Compare proportional relationships', 'Plant A grows 12 cm in 4 weeks. Plant B grows $h$ cm in $w$ weeks, where $h = 2.5w$. Plant C grows 7 cm in 2 weeks. All grow at constant rates. Which plant grows the least each week?', '["Plant A","Plant B","Plant C","All three grow equally fast"]', 'Plant B', NULL, 'Plant A grows $12 \div 4 = 3$ cm a week, Plant B grows 2.5 cm a week and Plant C grows $7 \div 2 = 3.5$ cm a week. Plant B grows the least.', 'checked', '{"lint":[],"solve":{"answer":"Plant B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 12/4 = 3 cm/wk. B: 2.5 cm/wk. C: 7/2 = 3.5 cm/wk. Least is B.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04282769-46d8-432a-af30-84eea38b747b', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A table for a proportional relationship lists $y = 11.2$ when $x = 2$, $y = 28$ when $x = 5$ and $y = 44.8$ when $x = 8$. What is the constant of proportionality?', '[]', '5.6', '11.2/2', '$k = 11.2 \div 2 = 5.6$. Check: $28 \div 5 = 5.6$ and $44.8 \div 8 = 5.6$.', 'checked', '{"lint":[],"solve":{"answer":"5.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11.2/2 = 5.6, 28/5 = 5.6, 44.8/8 = 5.6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037ef9e9-9410-47f5-a8eb-9055ac151f21', 'NC26.7.RPR.1', 3, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(1.5, 9)$ is on the graph of a proportional relationship between the hours $x$ and the gallons $y$ of water a pump moves. Which statement is true?', '["The pump moves 9 gallons each hour","The pump moves 13.5 gallons each hour","The pump moves 6 gallons each hour","The pump moves 1.5 gallons each hour"]', 'The pump moves 6 gallons each hour', NULL, '1.5 hours move 9 gallons, so each hour the pump moves $9 \div 1.5 = 6$ gallons. (13.5 is $1.5 \times 9$.)', 'checked', '{"lint":[],"solve":{"answer":"The pump moves 6 gallons each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/1.5 = 6 gallons per hour.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0290d825-7aa1-42d5-a027-f71f7e254a50', 'NC26.7.RPR.2', 1, 'numeric', 'Sales tax and tip', 'Leo''s family has a meal that costs 50 dollars and leaves a tip of 10% of the cost. How many dollars is the tip?', '[]', '5', '50*0.1', '10% of 50 is $50 \times 0.10 = 5$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.10 x 50 = 5.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
