INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1895652a-4e33-4800-9844-b00bd2cafe9f', 'NC26.7.RPR.2', 1, 'choice', 'Commission', 'Sam earns a commission of 10% on every sale. He sells a bike for 150 dollars and a helmet for 30 dollars. How many dollars of commission does he earn?', '["180","18","15","3"]', '18', '(150+30)*0.1', 'His sales are $150 + 30 = 180$ dollars. His commission is 10% of 180, which is 18 dollars. (15 and 3 are the commissions on only one of the sales.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sales 150 + 30 = 180; 0.10 x 180 = 18.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03321989-51a2-4508-9790-fba8ac1e33d0', 'NC26.7.RPR.2', 2, 'numeric', 'Use a scale drawing with fractional measurements', 'A scale drawing of a room uses 1 inch for every 3 feet. On the drawing, the room''s length is $4\frac{1}{2}$ inches. What is the room''s actual length, in feet?', '[]', '13.5', '4.5*3', 'Each inch on the drawing is 3 feet, so $4\frac{1}{2}$ inches is $4.5 \times 3 = 13.5$ feet.', 'checked', '{"lint":[],"solve":{"answer":"13.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.5 inches x 3 feet per inch = 13.5 feet.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ad559d6-d424-4f20-8548-de65386adab6', 'NC26.7.RPR.2', 2, 'choice', 'Convert measurement units', 'Which of these is the fastest speed?', '["700 meters per minute","40 kilometers per hour","12 meters per second","0.5 kilometer per minute"]', '12 meters per second', NULL, 'Change each speed to meters per minute. 12 meters per second is $12 \times 60 = 720$ meters per minute. 700 stays 700. 40 kilometers per hour is $40000 \div 60 \approx 667$ meters per minute. 0.5 kilometer per minute is 500 meters per minute. The fastest is 12 meters per second.', 'checked', '{"lint":[],"solve":{"answer":"12 meters per second","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In m/min: 700; 40 km/h = 40000/60 = 666.7; 0.5 km/min = 500; 12 m/s = 720. Fastest is 12 m/s.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d3c647-350a-4e7a-a2d2-9052bac8b666', 'NC26.7.RPR.2', 2, 'numeric', 'Construct a scale drawing or find a scale', 'A rectangular garden is 18 feet long and 12 feet wide. A scale drawing of the garden uses the scale 1 inch : 3 feet. What is the perimeter of the garden on the drawing, in inches?', '[]', '20', '2*(18/3+12/3)', 'On the drawing the length is $18 \div 3 = 6$ inches and the width is $12 \div 3 = 4$ inches. The perimeter is $2 \times (6 + 4) = 20$ inches.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawing: 18/3 = 6 in by 12/3 = 4 in. Perimeter 2(6 + 4) = 20 in.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('084911cc-6294-4ab3-a609-b29ad28c2d55', 'NC26.7.RPR.2', 3, 'choice', 'Markup and discount', 'A store marks up an item by 50% of its cost. Later it sells the item at 50% off that marked-up price. Compared with what the store paid, the final price is...', '["the same as the cost","25% less than the cost","25% more than the cost","50% less than the cost"]', '25% less than the cost', NULL, 'With a cost of 100, the marked-up price is 150. Half off is 75. Compared with the cost of 100, 75 is 25% less.', 'checked', '{"lint":[],"solve":{"answer":"25% less than the cost","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost c: marked up to 1.5c, then 0.5 x 1.5c = 0.75c, which is 25% less than the cost.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('018ebbd5-0d61-48da-9b3b-0bbaf143e9ed', 'NC26.7.RPR.2', 3, 'choice', 'Commission', 'Plan A pays a commission of 8% of sales. Plan B pays 150 dollars plus a commission of 3% of sales. Jin''s sales are 2000 dollars. How many more dollars would Plan B pay than Plan A?', '["160","210","60","50"]', '50', '150+2000*0.03-2000*0.08', 'Plan A pays 8% of 2000, which is 160 dollars. Plan B pays $150 + 0.03 \times 2000 = 150 + 60 = 210$ dollars. Plan B pays $210 - 160 = 50$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 0.08 x 2000 = 160. B: 150 + 0.03 x 2000 = 210. B pays 50 more.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1421b931-be78-4adf-87dd-24c1b6462d2b', 'NC26.7.RPR.3', 1, 'choice', 'Relate radius and diameter', 'Which statement about any circle is true?', '["The radius is twice the diameter.","The radius and the diameter are equal.","The diameter is twice the radius.","The diameter is half the radius."]', 'The diameter is twice the radius.', NULL, 'The diameter goes all the way across the circle through the center and the radius goes only halfway, so the diameter is twice the radius.', 'checked', '{"lint":[],"solve":{"answer":"The diameter is twice the radius.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 2r for every circle, so the diameter is twice the radius.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1dcf60a2-c890-4e55-a54d-3560a19cfd82', 'NC26.7.RPR.3', 1, 'choice', 'Find circumference from diameter', 'A pie pan has a diameter of 20 centimeters. Use 3.14 for $\pi$. What is the circumference of the pan, in centimeters?', '["31.4","62.8","23.14","628"]', '62.8', '3.14*20', '$3.14 \times 20 = 62.8$ centimeters. (31.4 uses half the diameter, 23.14 adds instead of multiplying, and 628 slips the decimal.)', 'checked', '{"lint":[],"solve":{"answer":"62.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3.14 x 20 = 62.8 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0344569a-c422-4d6e-ad8d-a991024bf893', 'NC26.7.RPR.3', 1, 'numeric', 'Find circumference from diameter', 'A circle has a diameter of 7 inches. Use $\frac{22}{7}$ for $\pi$. What is the circumference, in inches?', '[]', '22', '22/7*7', '$\frac{22}{7} \times 7 = 22$ inches.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 22/7 x 7 = 22 in.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('202bf9fa-30cc-4197-9730-b1a97618ec19', 'NC26.7.RPR.3', 2, 'choice', 'Find a missing sector of a circle graph', 'A circle graph shows four categories. Three of them are 22%, 31% and 18% of the circle, and the last one is "other". What percent of the circle is "other"?', '["71","47","51","29"]', '29', '100-22-31-18', '$22 + 31 + 18 = 71$, so "other" is $100 - 71 = 29\%$. (71 is the three sectors together; 47 and 51 each leave out one of the three.)', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22 + 31 + 18 = 71; 100 - 71 = 29%.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04425e40-bdf6-43c8-a8d9-0050df0f703f', 'NC26.7.RPR.3', 2, 'choice', 'Compare sectors of a circle graph', 'A circle graph has four sectors: red is 30% of the circle, blue measures 80 degrees, green is $\frac{1}{5}$ of the circle, and yellow measures 100 degrees. Which color has the largest sector?', '["Blue","Green","Red","Yellow"]', 'Red', NULL, 'Red is $0.3 \times 360 = 108$ degrees, blue is 80, green is $\frac{1}{5} \times 360 = 72$, and yellow is 100. (These make $108 + 80 + 72 + 100 = 360$.) Red is the largest.', 'checked', '{"lint":[],"solve":{"answer":"Red","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 30% of 360 = 108; blue 80; green 1/5 of 360 = 72; yellow 100. Sum 360 (consistent). Largest is red at 108.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be8700a-1cfb-479d-9d8e-db7e15cfc28c', 'NC26.7.RPR.3', 2, 'numeric', 'Know that circumference divided by diameter is pi', 'A bicycle wheel has a diameter of 70 centimeters and a circumference of 219.8 centimeters. What is the circumference divided by the diameter?', '[]', '3.14', '219.8/70', '$219.8 \div 70 = 3.14$, the value of $\pi$ rounded to two decimal places.', 'checked', '{"lint":[],"solve":{"answer":"3.14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"219.8 / 70 = 3.14 (70 x 3.14 = 219.8).","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d2a7257-a714-42a2-a252-a3e6e0802093', 'NC26.7.RPR.3', 3, 'choice', 'Convert a percent or fraction to degrees in a circle graph', 'A circle graph of a farm shows that corn takes up $\frac{3}{8}$ of the whole farm. How many degrees is the corn sector?', '["37.5","135","45","960"]', '135', '3/8*360', '$\frac{3}{8}$ of 360 is $360 \div 8 \times 3 = 45 \times 3 = 135$ degrees. (37.5 is the percent, 45 is only $\frac{1}{8}$, and 960 divides by the fraction.)', 'checked', '{"lint":[],"solve":{"answer":"135","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 x 360 = 3 x 45 = 135 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('124e3fa7-0ee8-4d99-97e9-b95f3c327f23', 'NC26.7.RPR.3', 3, 'numeric', 'Find diameter or radius from circumference', 'Circle A has a circumference of 31.4 centimeters. Circle B has a diameter that is 4 centimeters longer than the diameter of circle A. Use 3.14 for $\pi$. What is the diameter of circle B, in centimeters?', '[]', '14', '31.4/3.14+4', 'Diameter of A $= 31.4 \div 3.14 = 10$ centimeters. Circle B is 4 centimeters more: $10 + 4 = 14$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d_A = 31.4 / 3.14 = 10 cm; d_B = 10 + 4 = 14 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
