INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0815fd02-7d85-4ca8-b17c-050682382066', 'NC26.7.ANR.1', 1, 'choice', 'Add and subtract integers', 'What is $-9 + 4$?', '["5","-5","-13","13"]', '-5', '-9+4', 'Start at $-9$ and move 4 to the right: $-9 + 4 = -5$. (5 drops the sign, and 13 and $-13$ add the numbers instead of finding the difference.)', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9 + 4 = -(9 - 4) = -5.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
