INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('180e6a0e-261c-43d9-9360-1f335dcd3570', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle', 'A circle has a radius of 6 centimeters. Which expression gives its area, in square centimeters?', '["$2 \\times \\pi \\times 6$","$\\pi \\times 6^2$","$\\pi \\times 12^2$","$\\pi \\times 6$"]', '$\pi \times 6^2$', NULL, 'The area of a circle is $\pi r^2$. With $r = 6$ this is $\pi \times 6^2$.', 'checked', '{"lint":[],"solve":{"answer":"$\\pi \\times 6^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = pi r^2 = pi x 6^2.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c4bc6d-c055-41aa-97ed-a24825ea0453', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle', 'A round pond has a diameter of 20 meters. Use 3.14 for $\pi$. What is the area of the water''s surface, in square meters?', '["314","1256","62.8","31.4"]', '314', '3.14*(20/2)^2', 'The radius is half the diameter: 20 $\div$ 2 = 10 meters. Area = $3.14 \times 10 \times 10 = 314$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"314","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 10. A = 3.14 x 100 = 314.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01311a2b-8c50-417a-9273-c34f374ab49e', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a composite figure by subtraction', 'A rectangular garden is 12 meters long and 9 meters wide. A rectangular pond that is 4 meters by 3 meters sits inside the garden. How many square meters of the garden are not covered by the pond?', '[]', '96', '12*9-4*3', 'Garden: $12 \times 9 = 108$ square meters. Pond: $4 \times 3 = 12$ square meters. Not covered: $108 - 12 = 96$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Garden 12 x 9 = 108; pond 4 x 3 = 12. 108 - 12 = 96.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('089b76a1-b38c-4e0e-9b45-45cea26c8b57', 'NC26.7.SGMR.1', 2, 'choice', 'Pi as the ratio of circumference to diameter', 'Four students each measured a round object: the distance around it and the distance across it (its diameter). Whose measurements fit what we know about $\pi$?', '["Around 20 cm, across 10 cm","Around 31 cm, across 10 cm","Around 40 cm, across 10 cm","Around 62 cm, across 10 cm"]', 'Around 31 cm, across 10 cm', NULL, 'The distance around should be about 3.14 times the distance across. For a diameter of 10 cm that is about 31.4 cm, so 31 cm fits. The others are about 2, 4 and 6 times the diameter.', 'checked', '{"lint":[],"solve":{"answer":"Around 31 cm, across 10 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratios around/across: 2, 4, 6.2, 3.1. Only 3.1 is close to pi.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c300280-2c5e-4497-ac41-737e78423f67', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a figure with a part removed', 'A metal washer is a circle with a radius of 10 millimeters, with a circle of radius 4 millimeters cut out of its center. Use 3.14 for $\pi$. What is the area of the metal, in square millimeters?', '["263.76","113.04","364.24","50.24"]', '263.76', '3.14*10^2 - 3.14*4^2', 'Big circle: $3.14 \times 10^2 = 314$. Hole: $3.14 \times 4^2 = 50.24$. Metal: 314 $-$ 50.24 = 263.76 square millimeters.', 'checked', '{"lint":[],"solve":{"answer":"263.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x (100 - 16) = 3.14 x 84 = 263.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12066343-6637-4c66-8a37-6135a7cc7817', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a parallelogram or trapezoid', 'A trapezoid has an area of 70 square centimeters and a height of 7 centimeters. One of its parallel sides is 6 centimeters long. How long is the other parallel side, in centimeters?', '[]', '14', '2*70/7 - 6', 'Area = $\frac{1}{2} \times$ (sum of parallel sides) $\times$ height, so the sum of the parallel sides is $2 \times 70 \div 7 = 20$ centimeters. The other side is 20 $-$ 6 = 14 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70 = 1/2 (6 + b) x 7, so 6 + b = 20, b = 14.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d5f5c47-70d1-4105-8a34-d1aa5b357a75', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a parallelogram or trapezoid', 'A parallelogram has an area of 91 square inches and a base of 13 inches. A rectangle has the same height as the parallelogram, and its base is 5 inches longer than the parallelogram''s base. What is the area of the rectangle, in square inches?', '[]', '126', '(13+5)*(91/13)', 'Height of the parallelogram = 91 $\div$ 13 = 7 inches. The rectangle''s base is 13 + 5 = 18 inches, so its area is 18 $\times$ 7 = 126 square inches.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 91 / 13 = 7. Rectangle base = 13 + 5 = 18. Area = 18 x 7 = 126.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c0391ce-1839-47ce-999d-fd1d4dc216ba', 'NC26.7.SGMR.2', 1, 'numeric', 'Volume from base area and height', 'The base of a right prism has an area of 12 square centimeters. The prism is 7 centimeters tall. What is its volume in cubic centimeters?', '[]', '84', '12*7', 'A right prism is the base layer repeated for the whole height. Volume = area of base $\times$ height = $12 \times 7 = 84$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = base area x height = 12 x 7 = 84.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20d43f73-4c41-4fda-8a5f-9939435162a7', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area of a rectangular prism or cube', 'A box is 6 cm long, 2 cm wide and 3 cm high. Which expression gives its total surface area, in square centimeters?', '["$6 \\times 2 \\times 3$","$6 \\times 2 + 6 \\times 3 + 2 \\times 3$","$2(6 + 2 + 3)$","$2(6 \\times 2) + 2(6 \\times 3) + 2(2 \\times 3)$"]', '$2(6 \times 2) + 2(6 \times 3) + 2(2 \times 3)$', NULL, 'The box has three pairs of faces: $6 \times 2$, $6 \times 3$ and $2 \times 3$. Surface area is the sum of all six faces, so each product is counted twice.', 'checked', '{"lint":[],"solve":{"answer":"$2(6 \\times 2) + 2(6 \\times 3) + 2(2 \\times 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three pairs of faces: 2(lw) + 2(lh) + 2(wh).","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d344b5d-df95-4404-8c1b-457cb2b8f5da', 'NC26.7.SGMR.2', 1, 'numeric', 'Unknown dimension from volume or surface area', 'A can has a circular base with an area of 78.5 square centimeters. The can holds 628 cubic centimeters. How tall is the can, in centimeters?', '[]', '8', '628/78.5', 'Volume = base area $\times$ height, so height = 628 $\div$ 78.5 = 8 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"628 / 78.5 = 8.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06409297-a2de-43ba-9170-9153976a344e', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a rectangular prism or cube', 'A gift box is 12 cm long, 8 cm wide and 5 cm high. How many square centimeters of wrapping paper cover the whole box exactly, with no overlap?', '["480","196","392","312"]', '392', '2*(12*8+12*5+8*5)', 'Top and bottom: 2 $\times$ 12 $\times$ 8 = 192. Front and back: 2 $\times$ 12 $\times$ 5 = 120. Two sides: 2 $\times$ 8 $\times$ 5 = 80. Total = 392 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"392","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12x8 + 12x5 + 8x5) = 2(96 + 60 + 40) = 392.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d9debfa-628c-4417-ad39-774b62ee591b', 'NC26.7.SGMR.2', 2, 'numeric', 'Surface area of a composite solid', 'A cylinder with a radius of 2 cm and a height of 5 cm stands on the top face of a cube with edges of 6 cm. Use 3.14 for $\pi$. What is the surface area of the combined solid, including the bottom of the cube, in square centimeters?', '[]', '278.8', '6*6^2 + 2*3.14*2*5', 'The circle where the cylinder touches the cube is hidden, but the top of the cylinder is a circle of the same size, so the flat surfaces total the same as the cube alone: 6 $\times$ $6^2$ = 216. The curved side of the cylinder adds 2 $\times$ 3.14 $\times$ 2 $\times$ 5 = 62.8. Total = 278.8 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"278.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 6 x 36 = 216 (the circle hidden on its top is replaced by the cylinder''s top). Add cylinder side 2 x 3.14 x 2 x 5 = 62.8. Total 278.8.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('107276a0-2944-4f20-816c-cb701f10560a', 'NC26.7.SGMR.2', 2, 'choice', 'How changing dimensions changes volume', 'A cube has a volume of 8 cubic centimeters. Every edge is made 3 times as long. What is the volume of the new cube, in cubic centimeters?', '["216","72","24","35"]', '216', '8*27', 'Each of the three lengths is multiplied by 3, so the volume is multiplied by 3 $\times$ 3 $\times$ 3 = 27. New volume = 8 $\times$ 27 = 216 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Edge 2 becomes 6; 6^3 = 216 (or 8 x 27).","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14c4381e-4d5b-45e3-84d5-efd8b9a3310c', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a cylinder', 'A closed cylindrical tank has a radius of 2 meters and a height of 5 meters. Its whole outside is painted with paint that costs 3 dollars per square meter. Use 3.14 for $\pi$. How many dollars does the paint cost?', '[]', '263.76', '(2*3.14*2^2 + 2*3.14*2*5)*3', 'Ends: 2 $\times$ 3.14 $\times$ $2^2$ = 25.12. Curved side: 2 $\times$ 3.14 $\times$ 2 $\times$ 5 = 62.8. Surface area = 87.92 square meters. Cost = 87.92 $\times$ 3 = 263.76 dollars.', 'checked', '{"lint":[],"solve":{"answer":"263.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x 3.14 x 4 = 25.12. Side 2 x 3.14 x 2 x 5 = 62.8. Total 87.92. Cost 87.92 x 3 = 263.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('044540df-be75-4969-a1ea-89045af5faf7', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a composite solid', 'A building is a rectangular prism 12 m long, 8 m wide and 6 m tall. Its roof is a triangular prism 12 m long, with triangular ends that have a base of 8 m and a height of 3 m. A chimney shaped like a 2 m by 2 m by 3 m box stands on the roof. What is the volume of the building, roof and chimney together, in cubic meters?', '[]', '732', '12*8*6 + 1/2*8*3*12 + 2*2*3', 'Rectangular part: 12 $\times$ 8 $\times$ 6 = 576. Roof: $\frac{1}{2} \times 8 \times 3 \times 12 = 144$. Chimney: 2 $\times$ 2 $\times$ 3 = 12. Total = 576 + 144 + 12 = 732 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"732","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: a box cannot stand flat on a sloped roof without part of it overlapping the roof; the intended reading (just add 12) is clear at this grade.","work":"Building 12 x 8 x 6 = 576. Roof 1/2 x 8 x 3 x 12 = 144. Chimney 2 x 2 x 3 = 12. Total 732.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00ec38cc-a3eb-4dd0-81a8-644a9433a54f', 'NC26.7.SGMR.3', 1, 'numeric', 'Vertical angles with expressions (equation)', 'Two vertical angles measure $(x + 12)^\circ$ and $40^\circ$. What is $x$?', '[]', '28', '40-12', 'Vertical angles are equal, so $x + 12 = 40$ and $x = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles equal: x + 12 = 40, x = 28.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03a5691a-7596-491a-9462-59bb0676282f', 'NC26.7.SGMR.3', 1, 'choice', 'Choose the equation for an unknown angle', 'Angles $A$ and $B$ lie side by side along a straight line. Angle $A$ measures $x^\circ$ and angle $B$ measures $110^\circ$. Which equation can be used to find $x$?', '["$x + 110 = 90$","$x = 110$","$x + 110 = 180$","$x + 110 = 360$"]', '$x + 110 = 180$', NULL, 'Angles along a straight line add up to 180, so $x + 110 = 180$. The others use 90 (complementary), equal angles (vertical), or 360 (a full turn).', 'checked', '{"lint":[],"solve":{"answer":"$x + 110 = 180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Along a straight line: x + 110 = 180.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f376150-5e0b-4ee1-bd1b-bed9557a624b', 'NC26.7.SGMR.3', 1, 'numeric', 'Intersecting lines: several angles, several steps', 'Two lines cross. One angle measures $135^\circ$. What is the measure of the smallest of the four angles in degrees?', '[]', '45', '180-135', 'The angle across from it is $135^\circ$. The two angles next to it are $180 - 135 = 45$ degrees each. The smallest angle is 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles are 135, 45, 135, 45. Smallest 45.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01dcc5ef-2ec9-4121-b9eb-ee4091c109a6', 'NC26.7.SGMR.3', 2, 'numeric', 'Supplementary angles and straight lines with expressions (equation)', 'An angle measures $(2x + 6)^\circ$ and its supplement measures $(4x - 18)^\circ$. What is the measure of the angle in degrees?', '[]', '70', '2*32+6', 'The angles add up to 180: $(2x + 6) + (4x - 18) = 180$, so $6x - 12 = 180$, $6x = 192$ and $x = 32$. The angle is $2 \times 32 + 6 = 70$ degrees (and its supplement is 110).', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 12 = 180, x = 32. Angle = 2(32) + 6 = 70 (supplement 110).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02834243-e4ef-49c2-8a35-b7bdd0631d16', 'NC26.7.SGMR.3', 2, 'choice', 'Vertical angles with expressions (equation)', 'Angle 1 and angle 3 are vertical angles. Angle 1 measures $(2x + 18)^\circ$ and angle 3 measures $(5x - 24)^\circ$. What is the measure of angle 1 in degrees?', '["14","46","134","28"]', '46', '2*14+18', 'Vertical angles are equal: $2x + 18 = 5x - 24$, so $3x = 42$ and $x = 14$. Angle 1 is $2 \times 14 + 18 = 46$ degrees. The choice 14 is just $x$, 134 is the supplement, and 28 is $2x$.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 18 = 5x - 24, 3x = 42, x = 14. Angle 1 = 28 + 18 = 46.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1277938b-bbd7-485a-a746-09462d5f22c5', 'NC26.7.SGMR.3', 2, 'choice', 'Choose the equation for an unknown angle', 'The complement of an angle is three times the angle. If the angle measures $x^\circ$, which equation can be used to find $x$?', '["$x + 3x = 180$","$3x = 90$","$x + 3x = 90$","$x + 3 = 90$"]', '$x + 3x = 90$', NULL, 'The complement measures $3x$, and an angle and its complement add up to 90. So $x + 3x = 90$.', 'checked', '{"lint":[],"solve":{"answer":"$x + 3x = 90$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complement = 3x, angle + complement = 90: x + 3x = 90 (x = 22.5).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1901c4ee-ce31-4b2b-9b15-119524c42204', 'NC26.7.SGMR.3', 3, 'choice', 'Vertical angles: find the measure', 'Two lines cross. One pair of vertical angles has a sum of $146^\circ$. What is the measure, in degrees, of each of the other two angles?', '["73","107","34","214"]', '107', '180-146/2', 'Each angle of the first pair is $146 \div 2 = 73$ degrees. An angle next to it is $180 - 73 = 107$ degrees, and the other pair are vertical angles with the same measure. The choice 73 is one of the first pair, 34 is $180 - 146$, and 214 is $360 - 146$.', 'checked', '{"lint":[],"solve":{"answer":"107","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical pair equal, each 146/2 = 73. Each of the other two = 180 - 73 = 107.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09f2dbd7-2059-446a-8432-e1e46e6598f7', 'NC26.7.SGMR.3', 3, 'numeric', 'Vertical angles with expressions (equation)', 'Two lines cross. One angle measures $(3x + 10)^\circ$ and its vertical angle measures $(5x - 20)^\circ$. What is the sum of the measures of the other two angles in degrees?', '[]', '250', '360-2*(3*15+10)', 'Vertical angles are equal: $3x + 10 = 5x - 20$, so $30 = 2x$ and $x = 15$. Each of these angles is $3 \times 15 + 10 = 55$ degrees. The four angles add up to 360, so the other two add up to $360 - 2 \times 55 = 250$ degrees. (Each is $180 - 55 = 125$.)', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 10 = 5x - 20, x = 15. Angle = 55. Others each 125, sum 250 (= 360 - 110).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08349673-5ad4-4f5f-85de-6f3662a7340c', 'NC26.7.RD.1', 1, 'numeric', 'Theoretical probability of one event', 'A bag has 3 red marbles, 5 blue marbles and 2 green marbles. One marble is drawn at random. What is the probability that it is green? Write your answer as a fraction.', '[]', '1/5', '2/10', 'There are $3 + 5 + 2 = 10$ marbles and 2 of them are green. The probability is $\frac{2}{10} = \frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 marbles, 2 green: 2/10 = 1/5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17c74c95-420c-4856-a07e-46ad7354aeab', 'NC26.7.RD.1', 1, 'numeric', 'Using a tree diagram', 'In a tree diagram for a game, the first branch "win" has probability $\frac{3}{4}$. From the end of that branch, the second branch "win again" has probability $\frac{1}{2}$. What is the probability of the path win, then win again? Write your answer as a fraction.', '[]', '3/8', '3/4*1/2', 'To find the probability of a path, multiply the probabilities along its branches: $\frac{3}{4} \times \frac{1}{2} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply along the path: 3/4 x 1/2 = 3/8.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1517cd4e-d0f7-418c-a628-7a156046f75c', 'NC26.7.RD.1', 1, 'choice', 'Compound events without replacement', 'Three tickets labeled A, B and C are in a hat. Two tickets are drawn one after the other, and the first ticket is NOT put back. How many different ordered outcomes are there?', '["9","3","5","6"]', '6', '3*2', 'There are 3 choices for the first ticket and then 2 left for the second, so $3 \times 2 = 6$ outcomes: AB, AC, BA, BC, CA, CB. (9 would be right only if the first ticket were put back.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 choices for first, 2 for second: 3 x 2 = 6 (AB, AC, BA, BC, CA, CB).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bfd3d3e-0069-479a-8a9b-1a974eb26467', 'NC26.7.RD.1', 2, 'choice', 'Using a table of outcomes', 'When two fair six-sided dice are rolled and the numbers are added, which sum is the most likely?', '["6","12","7","9"]', '7', '7', 'In the table of all 36 outcomes, a sum of 7 appears 6 times, more than any other sum. A sum of 6 appears 5 times, a sum of 9 appears 4 times, and a sum of 12 appears only once.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 7 has 6 ways, more than any other sum (6 and 8 have 5, 9 has 4, 12 has 1).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02e394d7-6722-4a51-ae01-25a329e50829', 'NC26.7.RD.1', 2, 'numeric', 'Compound events without replacement', 'A basket holds 4 apples and 2 pears. Pia takes two pieces of fruit, one after the other, without looking and without putting the first one back. What is the probability that both are pears? Write your answer as a fraction.', '[]', '1/15', '2/6*1/5', 'The first piece is a pear with probability $\frac{2}{6}$. Then 1 pear is left among 5 pieces, so the second is a pear with probability $\frac{1}{5}$. Both pears: $\frac{2}{6} \times \frac{1}{5} = \frac{2}{30} = \frac{1}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"1/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 fruits, 2 pears: 2/6 x 1/5 = 2/30 = 1/15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f48f429-a553-4957-bda9-de194d47eec0', 'NC26.7.RD.1', 2, 'numeric', 'Expected results and the effect of more trials', 'On a spinner, the probability of landing on green is $\frac{3}{10}$. If the spinner is spun 250 times, about how many times would you expect it to land on green?', '[]', '75', '3/10*250', 'The expected number is the probability times the number of spins: $\frac{3}{10} \times 250 = 75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/10 x 250 = 75.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bce1a22-b1a6-4e61-b7cb-357ba686f096', 'NC26.7.RD.1', 3, 'choice', 'Compound event with unequal outcomes', 'A spinner lands on red with probability $\frac{1}{2}$, on blue with probability $\frac{1}{3}$ and on green with probability $\frac{1}{6}$. A fair coin is flipped and the spinner is spun. What is the probability of getting tails and a spinner color that is not red?', '["1/2","1/4","1/6","1/12"]', '1/4', '1/2*(1/3+1/6)', 'The chance of tails is $\frac{1}{2}$. The chance the spinner is not red is $\frac{1}{3} + \frac{1}{6} = \frac{1}{2}$. Both together: $\frac{1}{2} \times \frac{1}{2} = \frac{1}{4}$. (1/6 leaves out green, and 1/12 leaves out blue.)', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(tails) = 1/2. P(not red) = 1/3 + 1/6 = 1/2. Independent: 1/2 x 1/2 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f6ed2e9-b4cd-4c38-bed1-baab6698ae4c', 'NC26.7.RD.1', 3, 'numeric', 'Probability when outcomes are not equally likely', 'A weighted die lands on 6 with probability $\frac{1}{3}$. The other five faces are equally likely to come up. What is the probability of rolling a 2? Write your answer as a fraction.', '[]', '2/15', '(1-1/3)/5', 'The five other faces share the remaining probability $1 - \frac{1}{3} = \frac{2}{3}$ equally. Each gets $\frac{2}{3} \div 5 = \frac{2}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"2/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other five faces share 1 - 1/3 = 2/3; each 2/3 / 5 = 2/15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0556a0c3-e214-4048-8f3f-1e33424b526b', 'NC26.7.RD.2', 1, 'choice', 'Write or choose a question that compares two groups', 'Ana wants to compare how long seventh graders and eighth graders read each week. Which question compares these two groups?', '["How many minutes did Ana spend reading during the last week?","How many minutes does a typical seventh grader read in one week?","Do seventh graders read more minutes each week than eighth graders?","What is the title of the longest book that an eighth grader has read?"]', 'Do seventh graders read more minutes each week than eighth graders?', NULL, 'A comparison question names both groups and the same measurement for each. Only the first question asks about reading time for both seventh graders and eighth graders.', 'checked', '{"lint":[],"solve":{"answer":"Do seventh graders read more minutes each week than eighth graders?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only ''Do seventh graders read more minutes each week than eighth graders?'' involves both groups and compares them.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00f53cc2-abde-42bd-aae0-c8f99c689624', 'NC26.7.RD.2', 1, 'choice', 'Write or choose a question that compares two groups', 'Which question compares two groups?', '["Are soccer team members taller, on average, than swim team members?","How tall is the person who coaches the soccer team at our school?","How many students are on the swim team and on the soccer team?","What is the typical height of the students on the soccer team?"]', 'Are soccer team members taller, on average, than swim team members?', NULL, 'The correct question measures the same thing (height) for two groups and asks how they compare. The question about the typical height of the soccer team asks about one group only.', 'checked', '{"lint":[],"solve":{"answer":"Are soccer team members taller, on average, than swim team members?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Comparing heights of soccer vs swim team members compares two groups. Counting members of both is a total, not a comparison of a variable.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8571e8-849c-48f9-bbcf-681bc6f7f53d', 'NC26.7.RD.2', 1, 'choice', 'Simulate a sample with random numbers or a device', 'Which tool could be used to simulate choosing at random among exactly 6 equally likely choices?', '["a fair coin","a spinner with 5 equal sections","a fair six-sided number cube","a deck of 8 different cards"]', 'a fair six-sided number cube', NULL, 'A number cube has 6 faces that are equally likely, one for each choice. A coin has 2 outcomes, the spinner 5, and the deck 8.', 'checked', '{"lint":[],"solve":{"answer":"a fair six-sided number cube","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A fair six-sided cube gives 6 equally likely outcomes; coin 2, spinner 5, cards 8.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1379e58e-3b90-4020-abae-494bfe478a60', 'NC26.7.RD.2', 2, 'choice', 'Spot a biased sample', 'To find out how all 500 students at a school feel about a new music class, a survey is given to 100 students as they leave a band concert. Why might the results be biased?', '["100 students is too few for any survey to be fair","Students at a band concert are more likely to like music than other students","The survey should have been given to teachers instead","The students were asked as they left, not as they arrived"]', 'Students at a band concert are more likely to like music than other students', NULL, 'A sample is biased when some members of the population are more likely to be chosen or to answer a certain way. People at a band concert probably like music more than the average student. A sample of 100 out of 500 is large enough, and when they were asked does not matter.', 'checked', '{"lint":[],"solve":{"answer":"Students at a band concert are more likely to like music than other students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample is drawn from concert-goers, who are more likely to favour music: selection bias.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bcf2080-0633-4e24-a449-776040e3688e', 'NC26.7.RD.2', 2, 'numeric', 'Spot and explain bias in a sample', 'A school wants to know the favorite music of all its students. Four plans for choosing 30 students are listed. A: ask the 30 students in the school band. B: choose 30 names at random from the list of all students. C: ask the first 30 students who volunteer after an announcement. D: use a computer to pick 30 student ID numbers at random. How many of the four plans are likely to give a biased sample?', '[]', '2', '2', 'Plan A is biased because band students may like different music from other students. Plan C is biased because volunteers may have stronger opinions than other students. Plans B and D give every student the same chance. So 2 plans are likely to be biased.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A (band members) biased; C (volunteers) biased; B and D random. 2 biased.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1936c87a-8e31-42ea-a75e-c0fbbf97db03', 'NC26.7.RD.2', 2, 'choice', 'Judge a conclusion drawn from a sample', 'A random sample of 50 students from a school of 1,000 students finds that 30 ride the bus. Which statement is the best conclusion?', '["Exactly 600 of the 1,000 students ride the bus every day.","Only 30 students at the school ride the bus.","Fewer than half of the students ride the bus.","About 600 of the 1,000 students probably ride the bus."]', 'About 600 of the 1,000 students probably ride the bus.', NULL, '$\frac{30}{50} = 60\%$ of the sample ride the bus, so about 60% of 1,000, or 600, probably do. A sample gives an estimate, not an exact count.', 'checked', '{"lint":[],"solve":{"answer":"About 600 of the 1,000 students probably ride the bus.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/50 = 60%; 0.6 x 1000 = about 600, an estimate not exact.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d94f7f5-c46b-4c86-991e-fc8716a27e58', 'NC26.7.RD.2', 3, 'choice', 'Why a random sample represents a population, and how samples vary', 'Which statement about random samples is correct?', '["A random sample always has exactly the same percents as the population does.","A sample can, by chance, differ from the population in the share of a group.","A random sample can never include members from a large group in the population.","A random sample is always biased, even when chance picks the members."]', 'A sample can, by chance, differ from the population in the share of a group.', NULL, 'Because chance picks the members, a sample can have somewhat more or fewer members of a group than the population has. That is why estimates from samples are approximate.', 'checked', '{"lint":[],"solve":{"answer":"A sample can, by chance, differ from the population in the share of a group.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"By chance a random sample can differ from the population in a group''s share; the other statements are false.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0608a313-5390-498a-93f0-ecdc43d0c829', 'NC26.7.RD.2', 3, 'numeric', 'Simulate a sample with random numbers or a device', 'Eli numbers the 24 students in his class from 01 to 24. To choose a random sample of 3 students, he reads random two-digit numbers: 47, 12, 88, 05, 12, 31, 19, 22. He skips any number that is not from 01 to 24 and any number he has already chosen. What is the sum of the numbers of the three students chosen?', '[]', '36', '12+5+19', '47 is too big, so skip it. 12 is chosen. 88 is too big. 05 is chosen. 12 is a repeat, so skip it. 31 is too big. 19 is chosen, which makes three students. The sum is $12 + 5 + 19 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47 skip; 12 chosen; 88 skip; 05 chosen; 12 repeat skip; 31 skip; 19 chosen (3 found). Sum 12 + 5 + 19 = 36.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1341ba47-d7f9-4c5f-9b6c-cdf0b8a6b635', 'NC26.7.RD.3', 1, 'numeric', 'Compare the centers of two distributions', 'Ravi practiced piano for 15, 20, 25, 30, 35 minutes on five days. Lena practiced for 25, 30, 35, 40, 45 minutes on five days. How many minutes greater is Lena''s mean practice time than Ravi''s?', '[]', '10', '(25+30+35+40+45)/5-(15+20+25+30+35)/5', 'Ravi''s mean is (15 + 20 + 25 + 30 + 35) / 5 = 125 / 5 = 25 minutes. Lena''s mean is (25 + 30 + 35 + 40 + 45) / 5 = 175 / 5 = 35 minutes. The difference is 35 - 25 = 10 minutes.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ravi: 15+20+25+30+35=125, mean 25. Lena: 25+30+35+40+45=175, mean 35. 35-25=10.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0700ab9d-6219-44b9-8656-f4b9c0079160', 'NC26.7.RD.3', 1, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the number of seconds students took to run a lap. The row for stem 3 has leaves 0, 2, 5. The row for stem 4 has leaves 1, 1, 7, 9. The row for stem 5 has leaves 2, 6. How many students are shown?', '[]', '9', '3+4+2', 'Each leaf is one student. Stem 3 has 3 leaves, stem 4 has 4 leaves and stem 5 has 2 leaves, so 3 + 4 + 2 = 9 students.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leaves 3+4+2=9.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b7517f1-ff67-4f7f-b89b-98e31c5be05a', 'NC26.7.RD.3', 1, 'numeric', 'Read a box plot from its five-number summary', 'A box plot of the minutes students took to get to school has a minimum of 5, a first quartile of 12, a median of 18, a third quartile of 27 and a maximum of 41. What is the interquartile range, the length of the box?', '[]', '15', '27-12', 'The interquartile range is the third quartile minus the first quartile: 27 - 12 = 15 minutes.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27-12=15.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('027cec05-910a-4bdf-8e47-4dd6a0fd59f4', 'NC26.7.RD.3', 2, 'numeric', 'Compare the spread of two distributions', 'Plot A has dots at 12, 12, 13, 15, 18. Plot B has dots at 10, 14, 14, 15, 16, 22. The range of Plot B is how many times the range of Plot A?', '[]', '2', '(22-10)/(18-12)', 'The range of A is 18 - 12 = 6. The range of B is 22 - 10 = 12. Since 12 / 6 = 2, the range of B is 2 times the range of A.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A 18-12=6; range B 22-10=12; 12/6=2.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa35108-282c-4483-8bc3-19d29bba6c6e', 'NC26.7.RD.3', 2, 'choice', 'Describe the shape of a distribution', 'A dot plot shows how many books 14 students read last month: 5 dots at 1, 4 dots at 2, 3 dots at 3, 1 dot at 7 and 1 dot at 9. Which describes the shape?', '["Most values are low, with a tail stretching toward the high values.","Most values are high, with a tail stretching toward the low values.","The values are balanced evenly on both sides of the center.","The values form two clusters of equal size."]', 'Most values are low, with a tail stretching toward the high values.', NULL, 'The tallest stacks are at the low values 1, 2 and 3, and a few dots trail off toward 7 and 9. A tail toward the high values is called skewed to the right.', 'checked', '{"lint":[],"solve":{"answer":"Most values are low, with a tail stretching toward the high values.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Most dots at 1-3, a few far out at 7 and 9: right tail toward high values.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a72d6f5-9723-4e70-932d-3936258980b8', 'NC26.7.RD.3', 2, 'choice', 'Draw a conclusion the data support', 'Group A walked between 4 and 12 thousand steps a day, with a median of 8. Group B walked between 5 and 13 thousand steps a day, with a median of 9. A student says, "Every person in Group B walks more than every person in Group A." Which reply is best?', '["No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.","Yes: Group B has the greater median, 9, so all of its values are greater.","Yes: Group B''s greatest value, 13, is greater than Group A''s greatest value, 12.","No: both groups have a range of 8, so the two groups must be identical."]', 'No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.', NULL, 'The claim is about every person, so one counterexample is enough. Group A has a value of 12, which is more than Group B''s least value of 5. So some person in Group A walks more than some person in Group B, and the claim is not supported. A greater median or a greater maximum does not mean every value is greater, and equal ranges do not make two groups identical.', 'checked', '{"lint":[],"solve":{"answer":"No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges overlap (A up to 12, B from 5), so someone in A may walk more than someone in B. The correct reply cites that overlap.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0568f81b-53aa-4063-94cf-70c3f23bd3f5', 'NC26.7.RD.3', 3, 'choice', 'Compare the centers of two distributions', 'Each choice shows two small data sets, A and B. In which choice is the median of B exactly 3 greater than the median of A?', '["A: 2, 5, 11 and B: 3, 6, 18","A: 1, 6, 8 and B: 2, 4, 11","A: 6, 2, 9 and B: 4, 5, 8","A: 2, 5, 9 and B: 3, 8, 9"]', 'A: 2, 5, 9 and B: 3, 8, 9', NULL, 'For A: 2, 5, 9 and B: 3, 8, 9 the medians are 5 and 8, which differ by 3. For A: 2, 5, 11 and B: 3, 6, 18 the means differ by 3 (6 and 9), but the medians are 5 and 6. For A: 1, 6, 8 and B: 2, 4, 11 the greatest values differ by 3, but the medians are 6 and 4. For A: 6, 2, 9 and B: 4, 5, 8 the lists are not in order; the true medians are 6 and 5.', 'checked', '{"lint":[],"solve":{"answer":"A: 2, 5, 9 and B: 3, 8, 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: medians 5 and 8, diff 3. B: 6 and 4. C: A sorted 2,6,9 median 6; B 4,5,8 median 5. D: 5 and 6. Only first choice works.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0815b226-e008-4721-a586-ec4fef019561', 'NC26.7.RD.3', 3, 'choice', 'Read a stem-and-leaf plot', 'Two teams'' points in nine games are shown in a back-to-back stem-and-leaf plot. Team X: stem 3 has leaves 2, 6, 8; stem 4 has leaves 0, 1, 5, 5, 7; stem 5 has leaf 2. Team Y: stem 3 has leaf 1; stem 4 has leaves 4, 6; stem 5 has leaves 0, 3, 5, 7, 8, 9. A stem of 3 and a leaf of 2 means 32. Which statement is true?', '["Team X''s median is 12 greater than Team Y''s median.","Team Y''s median is 12 greater than Team X''s median.","Team X has the greater range of the two teams.","Both teams have the same median."]', 'Team Y''s median is 12 greater than Team X''s median.', NULL, 'Team X''s scores in order: 32, 36, 38, 40, 41, 45, 45, 47, 52, so the median is 41 and the range is 20. Team Y''s: 31, 44, 46, 50, 53, 55, 57, 58, 59, so the median is 53 and the range is 28. Y''s median is 53 - 41 = 12 greater, and Y has the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Team Y''s median is 12 greater than Team X''s median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: 32,36,38,40,41,45,45,47,52, median 41, range 20. Y: 31,44,46,50,53,55,57,58,59, median 53, range 28. Y median 12 greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18debec1-7fef-4be2-a8fd-957f38873649', 'NC26.7.RD.4', 1, 'numeric', 'Find the mean absolute deviation', 'The mean of the data 3, 5, 9, 11 is 7. What is the mean absolute deviation (MAD) of the data?', '[]', '3', '(16+8+8+16)/16', 'The distances from the mean 7 are 4, 2, 2 and 4. Their mean is (4 + 2 + 2 + 4) / 4 = 12 / 4 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 7: 4,2,2,4, sum 12; 12/4=3.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135040fa-41c4-456e-9d06-00c6dea459d2', 'NC26.7.RD.4', 1, 'numeric', 'Describe the effect of an extreme value', 'The data set 10, 12, 13, 15 has a range of 5. A new value, 40, is added. What is the range of the data set now?', '[]', '30', '40-10', 'The new value is the greatest, so the range is 40 - 10 = 30. One extreme value raised the range from 5 to 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40-10 = 30.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('019a2c74-39c9-47c9-bfd0-1482a9381d7f', 'NC26.7.RD.4', 1, 'numeric', 'Describe the effect of an extreme value', 'The data set 22, 25, 27, 30, 31, 78 has an extreme value, 78. By how much does the range decrease if 78 is removed?', '[]', '47', '(78-22)-(31-22)', 'With 78 the range is 78 - 22 = 56. Without it the greatest value is 31, so the range is 31 - 22 = 9. The range decreases by 56 - 9 = 47.', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 78: 78-22=56. Without: 31-22=9. Decrease 47.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ba38a15-c2c2-414b-aabd-59350a4bc42b', 'NC26.7.RD.4', 2, 'choice', 'Find the interquartile range', 'The data set 6, 8, 9, 12, 14, 17, 19, 25 is in order. What are its first and third quartiles?', '["8 and 17","9 and 17","6 and 25","8.5 and 18"]', '8.5 and 18', NULL, 'There are 8 values, so each half has 4. The lower half 6, 8, 9, 12 has median (8 + 9) / 2 = 8.5, which is Q1. The upper half 14, 17, 19, 25 has median (17 + 19) / 2 = 18, which is Q3. (6 and 25 are the least and greatest values.)', 'checked', '{"lint":[],"solve":{"answer":"8.5 and 18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,8,9,12 | 14,17,19,25: Q1=(8+9)/2=8.5, Q3=(17+19)/2=18.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c66872a-d916-45d6-af96-18e7b1914dfa', 'NC26.7.RD.4', 2, 'numeric', 'Find the mean absolute deviation', 'Find the mean absolute deviation (MAD) of the data 12, 15, 9, 18 and 6.', '[]', '3.6', '(0+15+15+30+30)/25', 'The mean is 60 / 5 = 12. The distances from 12 are 0, 3, 3, 6 and 6, which add to 18. The MAD is 18 / 5 = 3.6.', 'checked', '{"lint":[],"solve":{"answer":"3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 60, mean 12. Distances 0,3,3,6,6 = 18; 18/5 = 3.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0718805a-2ee8-48b3-a0bf-866281c60873', 'NC26.7.RD.4', 2, 'choice', 'Compare two data sets using center and spread', 'Class 1''s test scores have a median of 78 and an IQR of 6. Class 2''s test scores have a median of 82 and an IQR of 16. Which statement is correct?', '["Class 2''s scores are typically higher, and they vary less.","Class 1''s scores are typically higher, and they vary more.","Class 1''s scores are typically higher, but they vary less.","Class 2''s scores are typically higher, but they vary more."]', 'Class 2''s scores are typically higher, but they vary more.', NULL, 'The median of Class 2 (82) is greater than that of Class 1 (78), so its scores are typically higher. The IQR of Class 2 (16) is greater than that of Class 1 (6), so its middle half is more spread out: its scores vary more.', 'checked', '{"lint":[],"solve":{"answer":"Class 2''s scores are typically higher, but they vary more.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 2 median 82 > 78 (typically higher) and IQR 16 > 6 (varies more).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0baf79a5-681b-49ef-8d0f-9740724297c7', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using IQR', 'Set X is 3, 5, 6, 8, 9, 12, 14, 17. Set Y is 10, 11, 12, 13, 14, 15, 16, 17. How much greater is the interquartile range of Set X than the interquartile range of Set Y?', '[]', '3.5', '((12+14)/2-(5+6)/2)-((15+16)/2-(11+12)/2)', 'Set X: the lower half is 3, 5, 6, 8 with first quartile $(5 + 6) \div 2 = 5.5$. The upper half is 9, 12, 14, 17 with third quartile $(12 + 14) \div 2 = 13$. IQR = $13 - 5.5 = 7.5$. Set Y: the lower half is 10, 11, 12, 13 with first quartile 11.5. The upper half is 14, 15, 16, 17 with third quartile 15.5. IQR = $15.5 - 11.5 = 4$. The difference is $7.5 - 4 = 3.5$.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: lower 3, 5, 6, 8 -> Q1 5.5; upper 9, 12, 14, 17 -> Q3 13; IQR 7.5. Y: lower 10-13 -> 11.5; upper 14-17 -> 15.5; IQR 4. Difference 3.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093da897-6232-4f79-829e-427b8391b539', 'NC26.7.RD.4', 3, 'numeric', 'Compare two data sets using center and spread', 'Plot R has 2 dots at 3, 6 dots at 5 and 2 dots at 7. Plot S has 4 dots at 3, 2 dots at 5 and 4 dots at 7. Both plots have a mean of 5. The MAD of Plot S is how many times the MAD of Plot R?', '[]', '2', '((20+20+20+20+0+0+20+20+20+20)/100)/((20+20+0+0+0+0+0+0+20+20)/100)', 'Plot R: the distances from 5 are 2 (twice), 0 (six times) and 2 (twice), which add to 8, so MAD = 8 / 10 = 0.8. Plot S: 2 (four times), 0 (twice) and 2 (four times), which add to 16, so MAD = 16 / 10 = 1.6. Since 1.6 / 0.8 = 2, the MAD of S is 2 times the MAD of R.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R: distances 2*2 + 6*0 + 2*2 = 8, MAD 0.8. S: 4*2 + 2*0 + 4*2 = 16, MAD 1.6. 1.6/0.8 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f953a86-767d-4d42-a7e8-ea5ff5321ee5', 'NC26.7.RD.5', 1, 'choice', 'Compare the IQRs of two groups', 'Group A has an IQR of 6 and Group B has an IQR of 11. Which statement must be true?', '["The middle half of Group A''s values is more spread out than the middle half of Group B''s","The median of Group B is 5 greater than the median of Group A","Group B has 5 more values than Group A","The middle half of Group B''s values is more spread out than the middle half of Group A''s"]', 'The middle half of Group B''s values is more spread out than the middle half of Group A''s', NULL, 'The IQR measures how spread out the middle half of the data is. A larger IQR means more spread, so the middle half of Group B (IQR 11) is more spread out than that of Group A (IQR 6). The IQR says nothing about the medians or the number of values.', 'checked', '{"lint":[],"solve":{"answer":"The middle half of Group B''s values is more spread out than the middle half of Group A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR measures the spread of the middle half; 11>6 so B''s middle half is more spread. Says nothing about count or median.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0031c807-d824-4893-b641-c6c4052acda9', 'NC26.7.RD.5', 1, 'choice', 'Describe the shape of a distribution', 'Test scores: 70, 72, 73, 74, 75, 76, 77, 79, 20. Which statement describes the score of 20?', '["It is the median of the scores","It is an outlier, far below the other scores","It is in the cluster where most scores are","It is the score that occurs most often"]', 'It is an outlier, far below the other scores', NULL, 'Eight of the nine scores are between 70 and 79, forming a cluster. The score of 20 is far from that cluster, so it is an outlier. It is not the median (the median is 74) and it occurs only once.', 'checked', '{"lint":[],"solve":{"answer":"It is an outlier, far below the other scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All other scores are 70-79; 20 is far below them: an outlier. No mode; median is 74.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07496a24-a48d-48e2-8799-942b57797475', 'NC26.7.RD.5', 1, 'choice', 'Reflect on sampling and sample size', 'A student wants to compare the lunch preferences of sixth graders and eighth graders at her school. Which is the best way to choose the students to ask?', '["Choose students at random from each grade''s list","Ask only her friends in each grade","Ask only the students in her own class","Ask the first five students to arrive each morning in each grade"]', 'Choose students at random from each grade''s list', NULL, 'A random sample gives every student in the grade an equal chance of being asked, so it is likely to represent the whole grade. Friends, classmates or early arrivers may all differ from the rest of the grade.', 'checked', '{"lint":[],"solve":{"answer":"Choose students at random from each grade''s list","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from each grade''s list is representative; the others are convenience samples.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03f80deb-1d6d-4edf-815d-1e3dffed9d6c', 'NC26.7.RD.5', 2, 'choice', 'Describe centre and spread together', 'Group A has a median score of 78 and an IQR of 6. Group B has a median score of 78 and an IQR of 18. Which statement is correct?', '["Group B scored higher, since its IQR is greater","The typical scores are about the same, but A''s scores vary more","The typical scores are about the same, but B''s scores vary more","Group A''s typical score is lower, since its IQR is smaller"]', 'The typical scores are about the same, but B''s scores vary more', NULL, 'The medians are equal, so the typical scores are the same. The IQR measures spread, and B''s IQR is greater, so B''s scores vary more. A greater IQR does not mean a higher score.', 'checked', '{"lint":[],"solve":{"answer":"The typical scores are about the same, but B''s scores vary more","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same medians, so typical scores alike; B''s IQR 18 > 6, so B varies more.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00e7232c-23b6-41b8-a473-5741b644ef08', 'NC26.7.RD.5', 2, 'choice', 'Compare the mean absolute deviations of two groups', 'Group 1 has the values 18, 19, 20, 21, 22. Group 2 has the values 10, 15, 20, 25, 30. Both groups have a mean of 20. Which group has the smaller MAD?', '["Group 2, because its values are closer to the mean on average","Neither, because the groups have the same mean, so their MADs are equal","Group 1, because its values are closer to the mean on average","Group 2, because its data have the greater range"]', 'Group 1, because its values are closer to the mean on average', NULL, 'Group 1 distances from 20: 2, 1, 0, 1, 2, so the MAD is 6 / 5 = 1.2. Group 2 distances from 20: 10, 5, 0, 5, 10, so the MAD is 30 / 5 = 6. Group 1 has the smaller MAD because its values sit closer to the mean. Equal means do not mean equal MADs.', 'checked', '{"lint":[],"solve":{"answer":"Group 1, because its values are closer to the mean on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group 1 deviations 2,1,0,1,2 -> MAD 1.2; Group 2 deviations 10,5,0,5,10 -> MAD 6. Group 1 smaller.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09d10498-2ba1-416f-ae7b-1583d4dfec44', 'NC26.7.RD.5', 2, 'choice', 'Draw a conclusion the data support', 'Maya chose a random sample of 30 sixth graders and a random sample of 30 seventh graders at her school. The sixth graders slept a mean of 9.4 hours a night and the seventh graders slept a mean of 8.6 hours. Which conclusion is best supported?', '["Every seventh grader at the school sleeps less than every sixth grader","Seventh graders at the school probably sleep less than sixth graders on average","All seventh graders in the country sleep exactly 8.6 hours","Growing older makes students need less sleep"]', 'Seventh graders at the school probably sleep less than sixth graders on average', NULL, 'Random samples let us make a careful statement about the whole grades at that school: the seventh graders probably sleep less on average, with some chance variation. The data cannot show that every student differs, cannot describe other schools, and cannot explain why the difference exists.', 'checked', '{"lint":[],"solve":{"answer":"Seventh graders at the school probably sleep less than sixth graders on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random samples of 30 support a tentative inference about the school''s grades; not causation, not the country, not every student.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b19757b-49b9-434b-9731-af397f0f04a5', 'NC26.7.RD.5', 3, 'choice', 'Communicate a comparison in words', 'A student writes: "Team A is better because its mean score is 5 higher." Team A''s MAD is 20 and Team B''s MAD is 3. What should the report add?', '["Nothing more: the means alone show which team is better","That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3","That Team A is more consistent, since its MAD is larger","That Team B scored more in total, since its MAD is smaller"]', 'That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3', NULL, 'A comparison of centres alone leaves out how spread out the scores are. Team A''s MAD of 20 is far larger than Team B''s MAD of 3, so A''s scores vary a lot and its mean is not very typical of its games. A larger MAD means less consistent, and the MAD does not tell us anything about total scores.', 'checked', '{"lint":[],"solve":{"answer":"That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A difference of 5 is small against A''s MAD of 20; the report should note A''s far greater variability.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('072c6387-2267-4e3b-8a69-378d0438a0af', 'NC26.7.RD.5', 3, 'numeric', 'Compare the variability of two groups with the IQR', 'Two groups of students timed how many minutes they took to finish a puzzle. Group A: 3, 7, 9, 12, 17, 20. Group B: 10, 12, 13, 15, 17, 19. Each list is in order. The quartiles are the medians of the lower half and the upper half of the data. The IQR of Group A is how many times the IQR of Group B?', '[]', '2', '(17-7)/(17-12)', 'Group A: the lower half is 3, 7, 9 so Q1 = 7, and the upper half is 12, 17, 20 so Q3 = 17. The IQR is 17 - 7 = 10. Group B: the lower half is 10, 12, 13 so Q1 = 12, and the upper half is 15, 17, 19 so Q3 = 17. The IQR is 17 - 12 = 5. Then 10 / 5 = 2, so the IQR of Group A is 2 times the IQR of Group B.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group A (6 values): lower half 3, 7, 9 -> Q1 = 7; upper half 12, 17, 20 -> Q3 = 17; IQR = 10. Group B: lower half 10, 12, 13 -> Q1 = 12; upper half 15, 17, 19 -> Q3 = 17; IQR = 5. Ratio 10 / 5 = 2.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('084c344b-7ea5-4dd8-bc0a-7dfe6b9bf52e', 'NC26.8.ANFR.1', 1, 'numeric', 'Find the whole numbers that satisfy an inequality with the variable on both sides', 'What is the greatest whole number $x$ that makes $4x - 5 < x + 7$ true?', '[]', '3', '12/3-1', 'Subtract $x$ from both sides: $3x - 5 < 7$. Add 5: $3x < 12$. Divide by 3: $x < 4$. The greatest whole number less than 4 is 3. Check: for $x = 3$, $4(3) - 5 = 7$ and $3 + 7 = 10$, and $7 < 10$. For $x = 4$ both sides equal 11, so 4 does not work.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 5 < x + 7 -> 3x < 12 -> x < 4. Greatest whole number below 4 is 3. Check x=3: 7 < 10 true; x=4: 11 < 11 false.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06583071-f2d6-4107-9231-93bf5262947a', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation that needs the distributive property', 'Solve: $4(x + 1) = 2x + 12$', '[]', '4', '(8)/(2)', 'Simplify each side: $4x + 4 = 2x + 12$. Move the $x$ terms to one side and the numbers to the other: $2x = 8$. Divide both sides by $2$: $x = 4$. Check: with $x = 4$ both sides equal $20$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 4 = 2x + 12 -> 2x = 8 -> x = 4. Check: 20 = 20.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('031686c6-8c13-4962-9c3b-c1a77711db45', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an equation that needs the distributive property', 'Which equation is the result of using the distributive property on the left side of $4(2x - 3) = x + 5$?', '["$8x - 3 = x + 5$","$8x + 12 = x + 5$","$8x - 12 = x + 5$","$2x - 12 = x + 5$"]', '$8x - 12 = x + 5$', NULL, 'The 4 multiplies both terms inside the parentheses: $4(2x - 3) = 4 \cdot 2x - 4 \cdot 3 = 8x - 12$. So the equation becomes $8x - 12 = x + 5$. The other choices multiply only one of the terms, change a sign, or multiply the wrong term.', 'checked', '{"lint":[],"solve":{"answer":"$8x - 12 = x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(2x - 3) = 8x - 12; right side unchanged.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d8da1cf-3986-4006-9479-e564c0e96021', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an equation that needs the distributive property', 'Which value of $x$ is the solution of $2(3x + 1) = 4(x + 4)$?', '["$\\frac{15}{2}$","$1$","$9$","$7$"]', '$7$', '14/2', 'Simplify each side: $6x + 2 = 4x + 16$. Move the $x$ terms to one side and the numbers to the other: $2x = 14$. Divide both sides by $2$: $x = 7$. Check: with $x = 7$ both sides equal $44$. The wrong choices come from multiplying only some terms: $\frac{15}{2}$ forgets to multiply the 1 by 2, and $1$ forgets to multiply the 4 by 4.', 'checked', '{"lint":[],"solve":{"answer":"$7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 2 = 4x + 16 -> 2x = 14 -> x = 7. Check: 44 = 44.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11ffa26c-aecd-4408-919d-6654f58abb11', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation after combining like terms', 'Solve: $5x - 3 + 2x = 4 - x + 17$', '[]', '3', '(24)/(8)', 'Simplify each side: $7x - 3 = -x + 21$. Move the $x$ terms to one side and the numbers to the other: $8x = 24$. Divide both sides by $8$: $x = 3$. Check: with $x = 3$ both sides equal $18$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x - 3 = 21 - x -> 8x = 24 -> x = 3. Check: 18 = 18.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1546e754-c16b-4c48-8003-498806fc5d80', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'Solve for $x$: $1.5x - 2.4 = 0.3x + 3.6$', '[]', '5', '(6)/(6/5)', 'Move the $x$ terms to one side and the numbers to the other: $1.2x = 6$. Divide both sides by $1.2$: $x = 5$. Check: with $x = 5$ both sides equal $5.1$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2x = 6 -> x = 5. Check: 5.1 = 5.1.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02621f40-d1a5-4939-b6f1-44c2b51912d5', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'Solve: $0.25(x + 8) = 0.5x - 1$', '[]', '12', '((0-3))/((0-1/4))', 'Simplify each side: $0.25x + 2 = 0.5x - 1$. Move the $x$ terms to one side and the numbers to the other: $-0.25x = -3$. Divide both sides by $-0.25$: $x = 12$. Check: with $x = 12$ both sides equal $5$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.25x + 2 = 0.5x - 1 -> 3 = 0.25x -> x = 12. Check: 5 = 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01eb7680-9ee9-4c19-8a62-5b8ab5cca175', 'NC26.8.ANFR.1', 3, 'choice', 'Write an equation for a situation', 'Three consecutive integers have a sum that is 9 less than five times the smallest integer. Let $n$ be the smallest integer. Which equation represents this?', '["$n + (n + 1) + (n + 2) = 5n + 9$","$n + (n + 1) + (n + 2) = 9 - 5n$","$n + (n + 1) + (n + 2) = 5n - 9$","$n + (n + 1) + (n + 2) = 5(n - 9)$"]', '$n + (n + 1) + (n + 2) = 5n - 9$', NULL, 'The three integers are $n$, $n + 1$ and $n + 2$. Their sum is $n + (n + 1) + (n + 2)$. "9 less than five times the smallest" is $5n - 9$. So the equation is $n + (n + 1) + (n + 2) = 5n - 9$. The other choices add 9, subtract $5n$ from 9, or subtract 9 before multiplying.', 'checked', '{"lint":[],"solve":{"answer":"$n + (n + 1) + (n + 2) = 5n - 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum n + (n+1) + (n+2); 9 less than five times the smallest: 5n - 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04f5242a-f8d7-4304-acb0-23d8c822b6b3', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a set of pairs is a function', 'Lena wrote four lists of (input, output) pairs. Only one of the lists is a function. Which one is it?', '["$(1, 2), (1, 3), (4, 5)$","$(2, 6), (3, 8), (2, 9)$","$(1, 7), (2, 7), (3, 7)$","$(5, 1), (6, 2), (5, 3)$"]', '$(1, 7), (2, 7), (3, 7)$', NULL, 'A function gives every input exactly one output. In the list $(1, 7), (2, 7), (3, 7)$ the inputs 1, 2 and 3 each have one output; it does not matter that the output 7 is used three times. In each other list one input has two outputs: 1 goes to 2 and 3, 2 goes to 6 and 9, and 5 goes to 1 and 3.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 7), (2, 7), (3, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: input 5 has outputs 1 and 3, not a function. B: inputs 1,2,3 each once (same output 7 is allowed), function. C: input 1 -> 2 and 3, not. D: input 2 -> 6 and 9, not. Only B.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('027eaa4f-176f-4bff-90b1-d28e99c7388a', 'NC26.8.ANFR.2', 1, 'numeric', 'Use a function rule to find an output or an input', 'A function is given by $y = 5x - 2$. What is $y$ when $x = 4$?', '[]', '18', '5*4-2', 'Put $x = 4$ into the rule: $5 \times 4 - 2 = 20 - 2 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 5(4) - 2 = 20 - 2 = 18.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06b4f292-0d93-44e6-8cfa-9ef1e0efb08b', 'NC26.8.ANFR.2', 1, 'choice', 'Match a real situation to the shape of its graph', 'A bathtub is filled, stays full while someone bathes, and is then drained. Imagine the graph of the depth of the water against time. Which describes the graph, from left to right?', '["It falls, stays flat, then rises","It rises, stays flat, then falls","It rises, falls, then stays flat","It stays flat, rises, then falls"]', 'It rises, stays flat, then falls', NULL, 'Filling makes the depth rise, bathing keeps it level, and draining makes it fall, in that order.', 'checked', '{"lint":[],"solve":{"answer":"It rises, stays flat, then falls","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Filling: rises; full: flat; draining: falls.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11d82900-2a66-411d-adfc-ebce871291c1', 'NC26.8.ANFR.2', 2, 'choice', 'Decide whether a function is increasing or decreasing', 'Which equation describes a decreasing function?', '["$y = 4x - 1$","$y = -x + 8$","$y = \\frac{x}{2}$","$y = 7 + 3x$"]', '$y = -x + 8$', NULL, 'In $y = -x + 8$ the output goes down by 1 each time $x$ goes up by 1. In the other three equations the number multiplying $x$ is positive, so the output goes up as $x$ goes up.', 'checked', '{"lint":[],"solve":{"answer":"$y = -x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slopes: -1, 1/2, 3, 4. Only y = -x + 8 has a negative rate, so it decreases.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('081ed6da-c0c9-427f-9197-731cbb2f51b4', 'NC26.8.ANFR.2', 2, 'choice', 'Find where a function increases or decreases', 'The outputs of a function for the inputs 0, 1, 2, 3, 4, 5 and 6 are 10, 8, 6, 6, 9, 12 and 15. On which interval of inputs is the function decreasing?', '["From input 2 to input 3","From input 3 to input 6","From input 2 to input 5","From input 0 to input 2"]', 'From input 0 to input 2', NULL, 'Between inputs 0 and 2 the outputs go 10, 8, 6, which is falling. From 2 to 3 the output stays at 6, and from 3 to 6 it rises (6, 9, 12, 15). The interval from 2 to 5 is flat and then rising.', 'checked', '{"lint":[],"solve":{"answer":"From input 0 to input 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10, 8, 6 for inputs 0-2 (falling), 6 to 6 flat (2-3), then rising 3-6. Decreasing on 0 to 2.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0024a946-e52d-49e6-af7f-82cc17d563ae', 'NC26.8.ANFR.2', 2, 'numeric', 'Tell linear from non-linear using pairs or a table', 'A function has the outputs 3, 8, 15 and 24 for the inputs 1, 2, 3 and 4. How much greater is the change in the output from input 3 to input 4 than the change from input 1 to input 2?', '[]', '4', '(24-15)-(8-3)', 'The change from input 1 to 2 is $8 - 3 = 5$. The change from input 3 to 4 is $24 - 15 = 9$. The difference is $9 - 5 = 4$. The changes are not equal, so the function is not linear.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Changes: 3->8 is 5, 8->15 is 7, 15->24 is 9. From 3 to 4: 9; from 1 to 2: 5. 9 - 5 = 4.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1019ed24-c01e-470a-8443-1cadd2f49ea7', 'NC26.8.ANFR.2', 3, 'numeric', 'Fix a relation so that it becomes a function', 'The pairs (1, 2), (1, 3), (1, 4), (2, 5), (3, 7), (3, 9) are written as (input, output) and do not make a function. What is the fewest number of pairs that must be removed so that every input has exactly one output?', '[]', '3', '(3-1)+(2-1)', 'Input 1 has three pairs, so two must be removed. Input 2 has one pair, which is fine. Input 3 has two pairs, so one must be removed. In total $2 + 0 + 1 = 3$ pairs are removed.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Input 1 has 3 outputs (keep 1, remove 2). Input 2 has 1. Input 3 has 2 outputs (remove 1). Fewest removals = 2 + 1 = 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('127bda65-ff31-4801-961f-05357c7a0049', 'NC26.8.ANFR.2', 3, 'numeric', 'Use a function rule to find an output or an input', 'A function has the rule $y = \frac{3}{4}x - 5$. For what input $x$ is the output 10?', '[]', '20', '(10+5)/(3/4)', 'Set $\frac{3}{4}x - 5 = 10$. Add 5: $\frac{3}{4}x = 15$. Divide by $\frac{3}{4}$: $x = 15 \times \frac{4}{3} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4)x - 5 = 10, (3/4)x = 15, x = 15 x 4/3 = 20.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08886967-e6da-4eb3-a5af-dc6b17e668bc', 'NC26.8.ANFR.3', 1, 'choice', 'Read the slope and y-intercept from an equation', 'Which of these lines has the greatest $y$-intercept?', '["$y = 20 - x$","$y = 3x + 5$","$y = -2x + 12$","$y = 9x - 30$"]', '$y = 20 - x$', NULL, 'The $y$-intercepts are 5, 20, 12 and $-30$ (the number that is added or subtracted without $x$). The greatest is 20, from $y = 20 - x$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 20 - x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intercepts: 20, -30, 5, 12. Greatest is 20.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f70214c-6887-4872-a732-73f7c886106f', 'NC26.8.ANFR.3', 1, 'choice', 'Write the equation of a line in slope-intercept form', 'A line crosses the $y$-axis at $(0, 6)$ and goes down 2 units for every 1 unit it goes to the right. Which equation is the equation of the line?', '["$y = -2x + 6$","$y = 2x + 6$","$y = 6x - 2$","$y = -2x - 6$"]', '$y = -2x + 6$', NULL, 'Going down 2 for every 1 to the right means a slope of $-2$. The line crosses the $y$-axis at 6, so the $y$-intercept is 6. The equation is $y = -2x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$y = -2x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intercept 6, slope -2/1 = -2: y = -2x + 6.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('033fa2fd-7664-44fe-ba3f-f614ed509ec9', 'NC26.8.ANFR.3', 1, 'choice', 'Rewrite an equation in slope-intercept form', 'Which equation is $y - 3 = 2x$ written in the form $y = mx + b$?', '["$y = 2x - 3$","$y = 2x + 3$","$y = -2x + 3$","$y = 3x + 2$"]', '$y = 2x + 3$', NULL, 'Add 3 to both sides: $y = 2x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 3: y = 2x + 3.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e62970f-b1d8-4a08-90d0-258605705147', 'NC26.8.ANFR.3', 2, 'choice', 'Find the equation of a linear function from a list of pairs', 'A linear function has these $(x, y)$ pairs: (0, 4), (2, 10), (4, 16). Which equation matches it?', '["$y = 6x + 4$","$y = 3x + 4$","$y = 4x + 3$","$y = 3x - 4$"]', '$y = 3x + 4$', NULL, 'When $x = 0$, $y = 4$, so the $y$-intercept is 4. When $x$ goes up by 2, $y$ goes up by 6, so the slope is $\frac{6}{2} = 3$. The equation is $y = 3x + 4$. Check: $x = 4$ gives $3(4) + 4 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 3x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (10 - 4)/(2 - 0) = 3; intercept 4 (from (0,4)). y = 3x + 4. Check (4,16): 12 + 4 = 16.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c323675-5555-4fa9-9720-cdd458fcaffd', 'NC26.8.ANFR.3', 2, 'choice', 'Identify a linear function and its form', 'A table gives the $x$-values 2, 4, 6 and 8 and the $y$-values 1, 4, 9 and 16. Which statement is correct?', '["It is linear, because $y$ keeps increasing","It is not linear, because $y$ goes up by a different amount each time","It is linear, because $x$ increases by 2 each time","It is linear, because $y$ starts at 1"]', 'It is not linear, because $y$ goes up by a different amount each time', NULL, 'The input goes up by 2 each time, but $y$ goes up by 3, then 5, then 7. The change is not constant, so the function is not linear. An increasing output or a steady step in $x$ is not enough.', 'checked', '{"lint":[],"solve":{"answer":"It is not linear, because $y$ goes up by a different amount each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x steps by 2; y changes 3, 5, 7: unequal changes for equal x steps, so not linear.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11e1ed56-0410-49a5-9f28-09bfa5b49e0f', 'NC26.8.ANFR.3', 2, 'choice', 'Find the slope of a line from points or a table', 'A table gives the $x$-values 2, 4, 6 and 8 and the $y$-values 11, 8, 5 and 2 of a linear function. What is the slope?', '["$-3$","$\\frac{3}{2}$","$-\\frac{3}{2}$","$-\\frac{2}{3}$"]', '$-\frac{3}{2}$', NULL, 'When $x$ goes up by 2, $y$ changes by $-3$. The slope is the change in $y$ over the change in $x$: $\frac{-3}{2} = -\frac{3}{2}$. The choice $-3$ forgets that $x$ went up by 2 each time.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y drops 3 when x rises 2: slope -3/2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014b7a82-a5e0-46fe-b0ca-9eb9c83c28e2', 'NC26.8.ANFR.3', 3, 'numeric', 'Identify a linear function and its form', 'A linear function has the $(x, y)$ pairs $(1, 5)$, $(3, 11)$, $(4, 14)$ and $(8, k)$. What is $k$?', '[]', '26', '14+(11-5)/(3-1)*(8-4)', 'The rate of change is constant: from $x = 1$ to $x = 3$ the output goes up by 6 in 2 steps, which is 3 per step. From $x = 4$ to $x = 8$ there are 4 steps, so the output goes up by $4 \times 3 = 12$ to $14 + 12 = 26$.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (11-5)/(3-1) = 3; y = 3x + 2 (check (4,14)). k = 3(8) + 2 = 26.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01ad89c7-af92-4f8f-a361-e895a6007534', 'NC26.8.ANFR.3', 3, 'numeric', 'Compare two linear functions shown in different ways', 'Mia has 40 dollars and saves 15 dollars each week. Noah has 100 dollars and saves 10 dollars each week. After how many weeks do they have the same amount?', '[]', '12', '(100-40)/(15-10)', 'Mia has $40 + 15x$ dollars after $x$ weeks and Noah has $100 + 10x$. Set them equal: $40 + 15x = 100 + 10x$. Then $5x = 60$ and $x = 12$ weeks.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 + 15w = 100 + 10w, 5w = 60, w = 12.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
