INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('054b69c9-3dc6-4936-89c3-196ccc1210b8', 'NC26.8.ANFR.5', 1, 'numeric', 'Use square and cube roots in a measurement problem', 'A square has an area of 49 square centimeters. How long is each side, in centimeters?', '[]', '7', '7', 'The side is $\sqrt{49} = 7$ centimeters, since $7 \times 7 = 49$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"side = sqrt(49) = 7.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
