INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1193d36b-ec47-4bf2-868a-2d69adb993e9', 'NC26.8.ANFR.5', 2, 'choice', 'Use zero and negative exponents', 'Write $\frac{1}{3^4}$ using a negative exponent. Which choice is correct?', '["$3^{-4}$","$3^{4}$","$-3^{4}$","$4^{-3}$"]', '$3^{-4}$', NULL, 'A reciprocal of a power has the opposite exponent: $\frac{1}{3^4} = 3^{-4}$.', 'checked', '{"lint":[],"solve":{"answer":"$3^{-4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3^4 = 3^-4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
