INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00668dd1-f136-48e9-87bf-5eb8311cf08d', 'NC26.8.ANFR.5', 3, 'numeric', 'Compute with numbers in scientific notation', 'One building holds $4 \times 10^{5}$ books and another holds $3 \times 10^{4}$ books. How many books are in the two buildings together?', '[]', '430000', '4*10^5+3*10^4', '$4 \times 10^5 = 400{,}000$ and $3 \times 10^4 = 30{,}000$. The sum is $430{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"430000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"400,000 + 30,000 = 430,000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
