INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d812996-fbc2-407b-9e57-86739c015f1a', 'NC26.8.SGMR.1', 1, 'numeric', 'Work backwards from the image', 'After a point is moved 3 units to the right, it is at (7, 2). What was its $x$-coordinate before the move?', '[]', '4', '7-3', 'Undo the move: 3 units to the left of $x = 7$ is $7 - 3 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 3 back: 7 - 3 = 4.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
