INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0923d4ae-8073-4da9-8f88-b5210428f0f2', 'NC26.ALR.NQ.3', 2, 'numeric', 'Complement', 'A school has 240 students, and they are the universal set. The set $R$ contains the students who ride the bus, and $n(R) = 135$. How many students are in the complement of $R$?', '[]', '105', '240-135', 'The complement holds the students who do not ride the bus: $240 - 135 = 105$.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"240 - 135 = 105.","run_id":"claude-code","at":"2026-10-22T19:24:56.250Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('052ede0a-9c96-4d71-93ec-3fd7f35e57a7', 'NC26.ALR.NQ.3', 2, 'choice', 'Set difference', 'Set $A$ is {1, 3, 5, 7, 9, 11} and set $B$ is {3, 6, 9, 12}. What is $B - A$?', '["{1, 5, 7, 11}","{6, 12}","{3, 9}","{1, 3, 5, 6, 7, 9, 11, 12}"]', '{6, 12}', NULL, '$B - A$ holds the elements of $B$ that are not in $A$. Of 3, 6, 9 and 12, the numbers 3 and 9 are in $A$, so what is left is {6, 12}.', 'checked', '{"lint":[],"solve":{"answer":"{6, 12}","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B - A: elements of B not in A: 6, 12.","run_id":"claude-code","at":"2026-10-22T19:24:56.250Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dbf2ec7-3703-47a1-81e6-6e6b2b6ff0a4', 'NC26.ALR.NQ.3', 2, 'numeric', 'Union', 'Let $A$ be the multiples of 3 from 1 to 20 and $B$ be the multiples of 4 from 1 to 20. How many numbers are in the union of $A$ and $B$?', '[]', '10', '6+5-1', '$A$ = {3, 6, 9, 12, 15, 18} has 6 numbers and $B$ = {4, 8, 12, 16, 20} has 5. The number 12 is in both. So the union has $6 + 5 - 1 = 10$ numbers.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mult of 3: 6; of 4: 5; of 12: 1. 6+5-1 = 10.","run_id":"claude-code","at":"2026-10-23T00:25:05.767Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('018e7b21-78b8-4aa1-8ead-1a2c9ad6f47a', 'NC26.ALR.NQ.3', 3, 'numeric', 'Subsets', 'How many subsets of {1, 2, 3, 4, 5, 6} contain both 1 and 2?', '[]', '16', '2^4', 'The elements 1 and 2 must be in the subset. Each of the other 4 elements (3, 4, 5, 6) is either in or out, giving $2^4 = 16$ subsets.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Include 1 and 2; any choice of 3,4,5,6: 2^4 = 16.","run_id":"claude-code","at":"2026-10-23T00:25:05.767Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('169b5c7e-b8e5-458f-af08-b46544e1c34d', 'NC26.ALR.NQ.3', 3, 'choice', 'Combining three sets', 'Let $A$ be the whole numbers from 1 to 10, $B$ the even numbers from 1 to 10 and $C$ the multiples of 3 from 1 to 10. Which set holds the elements of $A$ that are in neither $B$ nor $C$?', '["{1, 2, 3, 4, 5, 7, 8, 9, 10}","{1, 3, 5, 7, 9}","{1, 5, 7}","{1, 2, 4, 5, 7, 8, 10}"]', '{1, 5, 7}', NULL, 'The union of $B$ and $C$ is {2, 3, 4, 6, 8, 9, 10}. Removing these from $A$ leaves 1, 5 and 7. Taking out only $B$ would leave 3 and 9 too, and taking out only $C$ would leave the even numbers 2, 4, 8 and 10.', 'checked', '{"lint":[],"solve":{"answer":"{1, 5, 7}","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd and not a multiple of 3 in 1..10: 1,5,7.","run_id":"claude-code","at":"2026-10-23T00:25:05.767Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('156c8da1-c275-444c-95d7-64232748b8bf', 'NC26.ALR.NQ.4', 1, 'choice', 'Prime factorization and the Fundamental Theorem of Arithmetic', 'Which is the prime factorization of 60?', '["$2^2 \\times 3 \\times 5$","$2 \\times 3 \\times 10$","$4 \\times 3 \\times 5$","$2 \\times 3^2 \\times 5$"]', '$2^2 \times 3 \times 5$', NULL, '$60 = 2 \times 30 = 2 \times 2 \times 15 = 2^2 \times 3 \times 5$, and 2, 3 and 5 are all prime. The products with 10 or with 4 equal 60 but 10 and 4 are not prime. The product $2 \times 3^2 \times 5$ equals 90.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 3 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 = 4*15 = 2^2 * 3 * 5. Others contain non-primes or equal 90.","run_id":"claude-code","at":"2026-10-22T19:24:56.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('079f1ea3-b7a5-4328-8654-1c6a13bd0601', 'NC26.ALR.NQ.4', 1, 'numeric', 'Set equality', 'The sets {3, $x$, 9} and {9, 5, 3} are equal. What is the value of $x$?', '[]', '5', NULL, 'Equal sets have exactly the same elements, in any order. The elements 3 and 9 appear in both, so the remaining element $x$ must be 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal sets have the same elements, so x = 5.","run_id":"claude-code","at":"2026-10-22T19:24:56.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05396197-5065-4e91-a80d-e415779f7060', 'NC26.ALR.NQ.4', 1, 'numeric', 'Euclidean algorithm for the GCF', 'To use the Euclidean algorithm, divide the larger number by the smaller and note the remainder. Then divide the previous divisor by that remainder, and repeat until a remainder is 0. For 36 and 27, what is the last nonzero remainder?', '[]', '9', '9', 'Divide: $36 = 1 \times 27 + 9$. Then $27 = 3 \times 9 + 0$. The remainder is now 0, so the last nonzero remainder is 9 (which is also the GCF of 36 and 27).', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 1x27 + 9; 27 = 3x9 + 0. Last nonzero remainder 9.","run_id":"claude-code","at":"2026-10-23T00:09:42.702Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0573a696-e5d4-49de-be71-3a8353d880cb', 'NC26.ALR.NQ.4', 2, 'choice', 'Arguments about primes', 'Aisha claims that the only two consecutive integers that are both prime are 2 and 3. Which reason supports her claim?', '["One of two consecutive integers is odd, and an odd number greater than 1 is not prime","One of two consecutive integers is a multiple of 3, and a multiple of 3 greater than 3 is not prime","Two consecutive integers always share a factor greater than 1, so they cannot both be prime","One of two consecutive integers is even, and an even number greater than 2 is not prime"]', 'One of two consecutive integers is even, and an even number greater than 2 is not prime', NULL, 'Of any two consecutive integers, one is even. An even number greater than 2 has 2 as a factor, so it is not prime. So both can be prime only if the even one is 2, which gives the pair 2 and 3. The other reasons are false: 3 and 5 are odd primes, 4 and 5 contain no multiple of 3, and consecutive integers never share a factor greater than 1.', 'checked', '{"lint":[],"solve":{"answer":"One of two consecutive integers is even, and an even number greater than 2 is not prime","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Of two consecutive integers one is even; the only even prime is 2, so the pair is 2,3 (1,2 fails since 1 is not prime). Other options are false (e.g. 4,5 has no multiple of 3).","run_id":"claude-code","at":"2026-10-22T19:24:56.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1207ad28-58c8-4e96-9525-08d5cc1decb6', 'NC26.ALR.NQ.4', 2, 'choice', 'Arguments about factors and divisibility', 'A student wants to show that if $a$ divides $b$ and $a$ divides $c$, then $a$ divides $b + c$. Which argument is a correct proof?', '["Write $b = am$ and $c = ak$ for whole numbers $m$, $k$. Then $b + c = a(m + k)$, a multiple of $a$.","Try $a = 2$, $b = 4$, $c = 6$. Then $b + c = 10$ and 2 divides 10, so it is always true.","Write $b + c = an$ for a whole number $n$. Then $b = an$ and $c = an$, so $a$ divides each of them.","Since $b + c$ is larger than $b$ and larger than $c$, the number $a$ must divide it."]', 'Write $b = am$ and $c = ak$ for whole numbers $m$, $k$. Then $b + c = a(m + k)$, a multiple of $a$.', NULL, 'A proof must work for all values. Writing $b = am$ and $c = ak$ and adding gives $b + c = a(m + k)$, a multiple of $a$. One example does not prove a statement for all numbers. The argument that begins with $b + c = an$ proves the reverse statement, which is false: for $a = 2$, $b = 1$, $c = 3$, the sum 4 is divisible by 2 but 1 and 3 are not. Being larger has nothing to do with dividing.', 'checked', '{"lint":[],"solve":{"answer":"Write $b = am$ and $c = ak$ for whole numbers $m$, $k$. Then $b + c = a(m + k)$, a multiple of $a$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b = am, c = ak gives b + c = a(m+k). The others are an example, a non-sequitur, or a converse.","run_id":"claude-code","at":"2026-10-22T19:24:56.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e76dc40-55ee-492a-97c8-7e630bcb0dc4', 'NC26.ALR.NQ.4', 2, 'numeric', 'LCM from the GCF', 'Three alarms ring every 6 minutes, every 8 minutes and every 10 minutes. They all ring together at noon. How many minutes later do all three next ring together?', '[]', '120', '120', 'The time must be a multiple of 6, 8 and 10. With $6 = 2 \times 3$, $8 = 2^3$ and $10 = 2 \times 5$, the LCM is $2^3 \times 3 \times 5 = 120$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(6,8,10) = 2^3x3x5 = 120.","run_id":"claude-code","at":"2026-10-23T00:09:42.702Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25c8f3c8-543e-425f-a02f-6784aa7dd876', 'NC26.ALR.NQ.4', 3, 'choice', 'Arguments about primes', 'What is the largest integer that divides $p^2 - 1$ for every prime number $p$ greater than 3?', '["24","48","12","8"]', '24', '24', 'Write $p^2 - 1 = (p - 1)(p + 1)$. These are two even numbers two apart, so one is a multiple of 4, giving a factor of 8. Among $p - 1$, $p$, $p + 1$ one is a multiple of 3, and it is not $p$, so 3 divides the product. So 24 always divides $p^2 - 1$. For $p = 5$ the value is exactly 24, so nothing larger works for every prime.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p^2-1 = (p-1)(p+1): consecutive evens give a factor 8, one of p-1,p,p+1 is a multiple of 3 and p is not, so 24 divides. p = 5 gives 24, so it is the largest.","run_id":"claude-code","at":"2026-10-22T19:24:56.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25284947-d021-455e-a8c3-e06e1e7c7fe9', 'NC26.ALR.NQ.4', 3, 'numeric', 'Arguments about primes', 'Wei claims that $n^2 + n + 11$ is prime for every positive integer $n$. What is the smallest positive integer $n$ that shows the claim is false?', '[]', '10', NULL, 'Try each n from 1 to 9: the values are 13, 17, 23, 31, 41, 53, 67, 83 and 101, all prime. For $n = 10$ the value is $100 + 10 + 11 = 121 = 11 \times 11$, which is not prime. So the smallest counterexample is $n = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n=1..9: 13, 17, 23, 31, 41, 53, 67, 83, 101, all prime. n=10: 121 = 11^2.","run_id":"claude-code","at":"2026-10-22T19:24:56.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18d26f42-51a6-4c4a-aaf9-45cad05b8fe3', 'NC26.ALR.GT.1', 1, 'choice', 'Euler paths and circuits', 'Which description matches an Euler circuit?', '["a path that starts and ends at the same vertex and visits every vertex exactly once","a path that starts and ends at different vertices and uses every edge exactly once","a path that starts and ends at the same vertex and uses every edge exactly once","a path that starts and ends at different vertices and visits every vertex exactly once"]', 'a path that starts and ends at the same vertex and uses every edge exactly once', NULL, 'An Euler circuit uses every edge exactly once and ends where it started. Visiting every vertex exactly once and returning is a Hamiltonian circuit, and the versions that end at a different vertex are paths, not circuits.', 'checked', '{"lint":[],"solve":{"answer":"a path that starts and ends at the same vertex and uses every edge exactly once","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An Euler circuit uses every edge exactly once and returns to its start.","run_id":"claude-code","at":"2026-10-22T12:53:50.694Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18c0c5c4-92c1-4654-b7db-d24fafd8ece4', 'NC26.ALR.GT.1', 1, 'choice', 'Hamiltonian paths and circuits', 'A graph has vertices A, B, C, D and E and edges AB, BC, CD and DE. Which route visits every vertex exactly once?', '["A-B-C-E-D","B-C-D-E","A-C-B-D-E","A-B-C-D-E"]', 'A-B-C-D-E', NULL, 'A-B-C-D-E uses the edges AB, BC, CD and DE and visits all five vertices once. A-B-C-E-D needs CE and A-C-B-D-E needs AC, which are not edges, and B-C-D-E leaves out A.', 'checked', '{"lint":[],"solve":{"answer":"A-B-C-D-E","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Edges form the path A-B-C-D-E. A-C-B-D-E uses AC (not an edge); A-B-C-E-D uses CE (not an edge); B-C-D-E misses A. Only A-B-C-D-E follows edges and visits every vertex once.","run_id":"claude-code","at":"2026-10-22T12:53:50.694Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13db35eb-f61e-4739-85c1-6de953cae753', 'NC26.ALR.GT.1', 1, 'numeric', 'Ranking with a complete digraph', 'In a complete digraph for a round-robin, each pair of teams is joined by one arrow, from the winner to the loser. Five teams each play every other team once. How many arrows does the digraph have?', '[]', '10', '5*4/2', 'There is one arrow for each game. Each of 5 teams plays 4 others, which counts every game twice, so there are $5 \times 4 \div 2 = 10$ games and 10 arrows.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(5,2) = 10 games, 10 arrows.","run_id":"claude-code","at":"2026-10-22T19:41:15.200Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11837867-7ce9-4029-b716-9a7e68eeca19', 'NC26.ALR.GT.1', 2, 'choice', 'Adjacency matrices and tables', 'A graph has no loops, no repeated edges, and edges with no direction. Which matrix could be its adjacency matrix?', '["rows [0, 1, 1], [1, 0, 0] and [0, 0, 0]","rows [1, 1, 0], [1, 0, 1] and [0, 1, 0]","rows [0, 1, 1], [1, 0, 0] and [1, 0, 0]","rows [0, 1, 0], [0, 0, 1] and [1, 0, 0]"]', 'rows [0, 1, 1], [1, 0, 0] and [1, 0, 0]', NULL, 'The adjacency matrix of such a graph is symmetric about its main diagonal, and its main diagonal is all 0. The first matrix is. The second has a 1 in row 1, column 3 but a 0 in row 3, column 1; the third has a 1 on its main diagonal; the fourth is not symmetric.', 'checked', '{"lint":[],"solve":{"answer":"rows [0, 1, 1], [1, 0, 0] and [1, 0, 0]","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Needs symmetric, zero diagonal. Option 1 and 3 [0,0,0] row break symmetry; [1,1,0] has a loop. [0,1,1],[1,0,0],[1,0,0] works.","run_id":"claude-code","at":"2026-10-22T19:41:15.200Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('018972ec-9f51-4e0a-94e7-6eb18cc98f0d', 'NC26.ALR.GT.1', 2, 'choice', 'Euler paths and circuits', 'Which graph has an Euler circuit?', '["a line of 6 vertices, each joined only to the next one","one center vertex joined to each of 5 other vertices","a ring of 6 vertices, each joined to the next, with the last joined back to the first","the complete graph on 4 vertices"]', 'a ring of 6 vertices, each joined to the next, with the last joined back to the first', NULL, 'An Euler circuit needs every vertex to have even degree. In the ring every vertex has degree 2. In the line the two end vertices have degree 1. In the star the five outer vertices have degree 1. In the complete graph on 4 vertices every vertex has degree 3.', 'checked', '{"lint":[],"solve":{"answer":"a ring of 6 vertices, each joined to the next, with the last joined back to the first","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ring of 6: all degree 2, connected: Euler circuit. Star, line, K4 have odd vertices.","run_id":"claude-code","at":"2026-10-22T19:41:15.200Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d02dde1-2158-4c53-a285-df792f02c19f', 'NC26.ALR.GT.1', 2, 'choice', 'Hamiltonian paths and circuits', 'In the complete graph on the vertices A, B, C, D and E, every pair of vertices is joined by an edge. Which route is a Hamiltonian circuit?', '["A-C-E-B-D-A","A-C-E-B-A","A-C-E-B-D-C-A","A-B-C-D-E"]', 'A-C-E-B-D-A', NULL, 'A Hamiltonian circuit visits all 5 vertices once and returns to the start. A-C-E-B-D-A does that. A-C-E-B-A misses D, A-C-E-B-D-C-A visits C twice, and A-B-C-D-E does not return to A.', 'checked', '{"lint":[],"solve":{"answer":"A-C-E-B-D-A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A-C-E-B-D-A visits all 5 once and returns. Others miss return, repeat C, or miss D.","run_id":"claude-code","at":"2026-10-22T19:41:15.200Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('312f70e2-2144-4fd0-9e5d-b3a9f896a441', 'NC26.ALR.GT.1', 3, 'choice', 'Adjacency matrices and tables', 'Which statement is true of the adjacency matrix of the complete graph on 4 vertices?', '["every entry is 1","every entry is 1 except the entries on the main diagonal, which are 0","every entry on the main diagonal is 1 and every other entry is 0","every row has four 1s and no 0s"]', 'every entry is 1 except the entries on the main diagonal, which are 0', NULL, 'In a complete graph every pair of different vertices is joined, so every entry off the main diagonal is 1. A vertex is not joined to itself, so the main diagonal entries are 0. Each row therefore has three 1s and one 0.', 'checked', '{"lint":[],"solve":{"answer":"every entry is 1 except the entries on the main diagonal, which are 0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"K4: 1 off diagonal, 0 on diagonal.","run_id":"claude-code","at":"2026-10-22T19:41:15.200Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c973b84-e0c7-4464-87d4-a965f77eda1f', 'NC26.ALR.GT.1', 3, 'choice', 'Euler paths and circuits', 'Which graph has an Euler path but no Euler circuit?', '["a ring of 5 vertices, each joined to the next, with the last joined back to the first","a line of 5 vertices, each joined only to the next one","the complete graph on 5 vertices","the complete graph on 4 vertices"]', 'a line of 5 vertices, each joined only to the next one', NULL, 'The line has two vertices of degree 1 and three of degree 2: exactly two odd vertices, so an Euler path but no circuit. The ring and the complete graph on 5 vertices have only even degrees (2 and 4), so they have Euler circuits. The complete graph on 4 vertices has four vertices of degree 3, so it has neither.', 'checked', '{"lint":[],"solve":{"answer":"a line of 5 vertices, each joined only to the next one","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line of 5: two odd endpoints, Euler path not circuit. K5, ring: circuits; K4: four odd.","run_id":"claude-code","at":"2026-10-22T19:41:15.200Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00f51120-db15-4d59-9655-8d150bd66372', 'NC26.ALR.GT.2', 1, 'choice', 'Traveling Salesperson: brute force and comparing methods', 'Four cities A, B, C and D have these distances in miles: AB 10, AC 15, AD 20, BC 35, BD 25, CD 40. Using brute force, check every circuit that starts and ends at A (a circuit and its reverse count as the same). How long is the shortest circuit?', '["90","95","105","145"]', '90', '10+25+40+15', 'There are three circuits. A-B-C-D-A: $10+35+40+20=105$. A-B-D-C-A: $10+25+40+15=90$. A-C-B-D-A: $15+35+25+20=95$. The shortest is 90 miles. (145 is the sum of all six distances, which is not a circuit.)', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ABCDA 10+35+40+20 = 105; ABDCA 10+25+40+15 = 90; ACBDA 15+35+25+20 = 95. Shortest 90.","run_id":"claude-code","at":"2026-10-22T19:24:56.327Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca88319-1c66-4c07-a559-875227d1c477', 'NC26.ALR.GT.2', 1, 'numeric', 'Vertex coloring: the fewest colors', 'Four clubs each need a meeting time. Every two of the clubs have at least one member in common, and a person cannot be at two meetings at once, so no two of the clubs can meet at the same time. What is the fewest number of time slots needed?', '[]', '4', '4', 'Every club conflicts with every other, so each needs its own slot. In graph terms, four vertices all joined to each other need 4 different colors. The answer is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Conflict graph is K4: needs 4 slots.","run_id":"claude-code","at":"2026-10-22T19:24:56.327Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b405b26-1550-42e0-9090-cbe7639a0406', 'NC26.ALR.GT.2', 1, 'choice', 'Traveling Salesperson: cheapest-link algorithm', 'Five cities have these distances in miles: AB 14, AC 9, AD 11, AE 7, BC 12, BD 6, BE 13, CD 8, CE 10, DE 5. The cheapest-link algorithm starts by picking the shortest road. Which road does it pick first?', '["BD","DE","AE","CD"]', 'DE', NULL, 'The cheapest-link algorithm starts with the shortest road of all. Here DE (5 miles) is shorter than BD (6), AE (7) and CD (8).', 'checked', '{"lint":[],"solve":{"answer":"DE","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest road is DE 5 (unique).","run_id":"claude-code","at":"2026-10-23T00:25:05.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02296387-e8a4-4a61-b27b-97ba305ca06b', 'NC26.ALR.GT.2', 2, 'choice', 'Critical path: slack and shortening a task', 'In a project plan, each task is shown with how long it takes and, in brackets, its prerequisite tasks: A 4 days (none), B 2 days (A), C 6 days (A), D 3 days (B), E 2 days (C and D). Tasks can be done at the same time whenever their prerequisites are finished. Task D takes 2 days longer than planned and nothing else changes. What is the new shortest time, in days, to finish the project?', '["13","12","14","11"]', '13', '12+2-1', 'The critical path is A, C, E ($4 + 6 + 2 = 12$ days). Task D has 1 day of slack: it ends on day 9 and E cannot start until day 10. Two extra days push D to end on day 11, one day past the slack, so E starts on day 11 and the project ends on day 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"D becomes 5: A4, B6, C10, D11, E 11+2 = 13 (was 12).","run_id":"claude-code","at":"2026-10-23T00:25:05.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ce5ce01-ac2f-4e9f-8bb2-22b85000dde9', 'NC26.ALR.GT.2', 2, 'numeric', 'Vertex coloring: modeling with a graph', 'Six radio towers T1 to T6 each need a frequency. Two towers that are close enough to interfere must use different frequencies. The pairs that interfere are: T1 and T2, T1 and T3, T1 and T4, T2 and T3, T2 and T4, T3 and T4, T4 and T5, T5 and T6, T3 and T6. What is the fewest number of frequencies needed?', '[]', '4', '4', 'The towers T1, T2, T3 and T4 all interfere with each other, so they need 4 different frequencies. T5 interferes with T4 and T6, and T6 with T3 and T5: give T5 the frequency of T1 and T6 the frequency of T2. So 4 frequencies are enough, and fewer cannot work.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"T1-T4 all mutually interfere (K4) -> at least 4. T1..T4 = 1..4, T5 = 1, T6 = 2 works. 4.","run_id":"claude-code","at":"2026-10-23T00:25:05.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ea4f64d-9385-4a9d-b6c4-7e98d264dc92', 'NC26.ALR.GT.2', 2, 'choice', 'Minimum spanning tree: Kruskal''s algorithm', 'Six stations A to F can be joined by cables with these costs: AB 10, AC 6, AD 12, BC 4, BD 8, CD 5, CE 9, DE 3, DF 7, EF 11, BF 13. Use Kruskal''s algorithm to find the cheapest way to connect all six. What is the total cost?', '["29","22","25","33"]', '25', '3+4+5+6+7', 'Take edges from cheapest, skipping any that form a cycle: DE 3 (added), BC 4 (added), CD 5 (added), AC 6 (added), DF 7 (added). The five edges added cost $3 + 4 + 5 + 6 + 7 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"DE3, BC4, CD5, AC6, DF7 -> 5 edges, all six joined: 25.","run_id":"claude-code","at":"2026-10-23T00:25:05.803Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2acc2182-856b-4f1e-b24c-8f0173f46c42', 'NC26.ALR.GT.2', 3, 'choice', 'Minimum spanning tree: Prim''s algorithm', 'A graph on vertices A to F has edges with these weights: AB 7, AC 4, AD 9, BC 6, BE 3, CD 5, CF 8, DF 2, EF 10, BD 11. Prim''s algorithm starts at vertex A. In what order does it add edges to the tree?', '["DF, BE, AC, CD, BC","AC, CD, DF, BE, BC","AC, CD, DF, BC, BE","AC, BC, CD, DF, BE"]', 'AC, CD, DF, BC, BE', NULL, 'Prim''s algorithm always adds the cheapest edge joining the tree to a new vertex. From A: AC (4). Tree {A, C}: CD (5) is cheapest. Tree {A, C, D}: DF (2). Tree {A, C, D, F}: BC (6) (BE is not yet available, because neither B nor E is in the tree). Then BE (3). Total weight 20.', 'checked', '{"lint":[],"solve":{"answer":"AC, CD, DF, BC, BE","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From A: AC4; then CD5 (vs BC6, AB7, CF8, AD9); then DF2; then BC6 (vs AB7, EF10, BD11); then BE3.","run_id":"claude-code","at":"2026-10-22T19:24:56.327Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29050c69-280b-44f5-bae8-b544965fc675', 'NC26.ALR.GT.2', 3, 'numeric', 'Minimum spanning tree: Kruskal''s algorithm', 'Six offices A to F can be joined by cables with these costs (in thousands of dollars): AB 5, AC 8, BC 3, BD 9, CD 6, CE 4, DE 2, DF 7, EF 10, AF 12, BF 11. Use Kruskal''s algorithm to find the cheapest way to connect all six offices. What is the total cost, in thousands of dollars?', '[]', '21', '2+3+4+5+7', 'Go through the cables from cheapest, skipping any that make a cycle: DE (2), BC (3), CE (4), AB (5). CD (6) would join C and D, which are already connected through E, so skip it. DF (7) joins F, the last office, so take it. Five cables now connect all six offices, so stop: $2+3+4+5+7=21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"DE2, BC3, CE4, AB5, CD6 rejected (cycle), DF7. Total 2+3+4+5+7 = 21.","run_id":"claude-code","at":"2026-10-22T19:24:56.327Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06c1b7c3-dd6e-4607-ae86-487bad04de50', 'NC26.ALR.L.1', 1, 'choice', 'Tautologies and contradictions', 'A statement that is false for every possible combination of truth values of its letters is called what?', '["A tautology","A contradiction","A contingency","A converse"]', 'A contradiction', NULL, 'A statement that is always false is a contradiction. A tautology is always true, and a contingency is true for some combinations and false for others.', 'checked', '{"lint":[],"solve":{"answer":"A contradiction","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Always false = contradiction.","run_id":"claude-code","at":"2026-10-22T19:26:03.710Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a8cc569-0afd-47f2-bc92-c42582724e78', 'NC26.ALR.L.1', 1, 'choice', 'Converse, inverse and contrapositive', 'Statement: "If it rains, then the ground is wet." Which statement is its converse?', '["If the ground is wet, then it rains.","If it does not rain, then the ground is not wet.","If the ground is not wet, then it does not rain.","If it rains, then the ground is not wet."]', 'If the ground is wet, then it rains.', NULL, 'The converse swaps the "if" part and the "then" part: "If the ground is wet, then it rains." The statement with both parts swapped and negated is the contrapositive, and the one with both parts negated but not swapped is the inverse.', 'checked', '{"lint":[],"solve":{"answer":"If the ground is wet, then it rains.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Converse swaps hypothesis and conclusion: If the ground is wet, then it rains.","run_id":"claude-code","at":"2026-10-22T19:26:03.710Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('081b7675-553a-4740-a443-8045a9e26544', 'NC26.ALR.L.1', 1, 'numeric', 'Logical equivalence', 'Two statements are logically equivalent when they have the same truth value in every row of the truth table. In how many of the 4 rows (for the letters $p$ and $q$) do "$p$ and $q$" and "$q$ and $p$" have different values?', '[]', '0', NULL, 'Both statements are true only when $p$ and $q$ are both true, so they always match. They differ in 0 rows, and "$p$ and $q$" is equivalent to "$q$ and $p$".', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AND is commutative; the two agree in all 4 rows, differ in 0.","run_id":"claude-code","at":"2026-10-23T00:27:24.629Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('087227e6-7761-42ab-9676-5ccffbaea97f', 'NC26.ALR.L.1', 2, 'numeric', 'Conditional and biconditional', 'In the truth table for "if $p$, then (not $q$)", how many of the 4 rows give the value true?', '[]', '3', '3', 'The statement is false only when $p$ is true and "not $q$" is false, that is, when $p$ and $q$ are both true. That is 1 row, so the statement is true in $4 - 1 = 3$ rows.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p -> not q is false only when p=T and not q=F, i.e. q=T. 1 false row, 3 true.","run_id":"claude-code","at":"2026-10-22T19:26:03.710Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fec3e3e-e9aa-48c5-98be-4538db2c7a44', 'NC26.ALR.L.1', 2, 'numeric', 'Constructing truth tables', 'How many of the 4 rows of the truth table for "($p$ or $q$) and (not $p$)" give the value true?', '[]', '1', NULL, 'The statement needs "not $p$", so $p$ must be false. Then "$p$ or $q$" is true only if $q$ is true. Only the row with $p$ false and $q$ true works: 1 row.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(p or q) and not p: TT F, TF F, FT T, FF F. One row.","run_id":"claude-code","at":"2026-10-23T00:27:24.629Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab4d8f4-c210-4722-96c6-c9e6f94401ff', 'NC26.ALR.L.1', 2, 'choice', 'Logical equivalence', 'Which statement is logically equivalent to "$p$ if and only if $q$"?', '["(if $p$, then $q$) or (if $q$, then $p$)","(if $p$, then $q$) and (if $q$, then $p$)","(if $p$, then $q$) and (if (not $q$), then $p$)","($p$ and $q$) and ((not $p$) and (not $q$))"]', '(if $p$, then $q$) and (if $q$, then $p$)', NULL, '"$p$ if and only if $q$" says the conditional works in both directions: if $p$ then $q$, and if $q$ then $p$, joined by "and". With "or" instead, the statement would be true in the rows where $p$ and $q$ differ.', 'checked', '{"lint":[],"solve":{"answer":"(if $p$, then $q$) and (if $q$, then $p$)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Biconditional = (p->q) and (q->p).","run_id":"claude-code","at":"2026-10-23T00:27:24.629Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06bfde1f-9920-407a-abc8-1c12674f15c4', 'NC26.ALR.L.1', 3, 'choice', 'Negation and De Morgan', 'Which statement is the negation of "If a figure is a square or a rhombus, then it has four equal sides"?', '["A figure is neither a square nor a rhombus, and it does not have four equal sides","If a figure is neither a square nor a rhombus, then it does not have four equal sides","A figure is both a square and a rhombus, and it does not have four equal sides","A figure is a square or a rhombus, and it does not have four equal sides"]', 'A figure is a square or a rhombus, and it does not have four equal sides', NULL, 'The negation of "if $A$, then $B$" is "$A$ and (not $B$)", and here $A$ is the whole "square or rhombus" statement, left unchanged. So the negation says the figure is a square or a rhombus and does not have four equal sides.', 'checked', '{"lint":[],"solve":{"answer":"A figure is a square or a rhombus, and it does not have four equal sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"not(P->Q) = P and not Q: a figure is a square or a rhombus, and it does not have four equal sides.","run_id":"claude-code","at":"2026-10-23T00:27:24.629Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0327ea88-c7bf-4632-b868-4c4e3c4e33bf', 'NC26.ALR.L.1', 3, 'choice', 'Logical equivalence', 'Which of these has exactly the same truth table as "($p$ and $q$) or ($p$ and (not $q$))"?', '["$q$","$p$ and $q$","$p$ or $q$","$p$"]', '$p$', NULL, 'Whatever the value of $q$, one of the two parts matches it, so the whole statement is true exactly when $p$ is true: $p$ and ($q$ or not $q$) simplifies to $p$.', 'checked', '{"lint":[],"solve":{"answer":"$p$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(p and q) or (p and not q) = p and (q or not q) = p.","run_id":"claude-code","at":"2026-10-23T00:27:24.629Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00398475-92f6-471c-a324-b7bd3a499069', 'NC26.ALR.MDMF.1', 1, 'choice', 'Pairwise comparison', 'Twenty voters rank three candidates, from first choice to last: 9 voters: A, B, C; 6 voters: B, C, A; 5 voters: C, A, B. Who wins the head-to-head comparison of A and B, and by how many votes?', '["A, by 9 votes to 6","B, by 11 votes to 9","A and B tie, with 10 votes each","A, by 14 votes to 6"]', 'A, by 14 votes to 6', NULL, 'In a head-to-head comparison every ranking counts, not just first choices. A is ranked above B by the 9 voters who rank A first and by the 5 voters who rank C, A, B: 14 voters. B is ranked above A by only the 6 voters in the middle group. A wins 14 to 6.', 'checked', '{"lint":[],"solve":{"answer":"A, by 14 votes to 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A above B: 9 (A,B,C) + 5 (C,A,B) = 14. B above A: 6. A wins 14 to 6.","run_id":"claude-code","at":"2026-10-23T00:27:24.666Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38547e13-a474-4e03-aa44-0194633fe300', 'NC26.ALR.MDMF.1', 1, 'choice', 'Fairness criteria', 'Which fairness criterion says that if a candidate wins an election and some voters then move that candidate higher on their ballots, with nothing else changed, the candidate should still win?', '["The majority criterion","The monotonicity criterion","The Condorcet criterion","The independence of irrelevant alternatives criterion"]', 'The monotonicity criterion', NULL, 'This is the definition of monotonicity: more support should never turn a winner into a loser. The majority criterion is about first-place majorities, the Condorcet criterion about head-to-head wins, and independence of irrelevant alternatives about a candidate dropping out.', 'checked', '{"lint":[],"solve":{"answer":"The monotonicity criterion","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"That is the monotonicity criterion.","run_id":"claude-code","at":"2026-10-23T00:27:24.666Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22967750-5281-4e7c-8e0d-2b0472f65ca9', 'NC26.ALR.MDMF.1', 1, 'numeric', 'Fairness criteria', 'A Condorcet winner is a candidate who wins every head-to-head comparison against the other candidates. In an election with 5 candidates, how many head-to-head comparisons must a Condorcet winner win?', '[]', '4', '5-1', 'A Condorcet winner must beat each of the other candidates, and there are $5 - 1 = 4$ of them. So the winner must win 4 comparisons.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One head-to-head against each of the other 4 candidates.","run_id":"claude-code","at":"2026-10-23T00:27:24.666Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('129d1ea9-0e5b-41d9-a066-516bec1e5357', 'NC26.ALR.MDMF.1', 2, 'choice', 'Defending a voting method', 'A committee defends pairwise comparison by saying, "The winner is a candidate whom most voters prefer to each of the others." Which fairness criterion does this defense appeal to?', '["The majority criterion","The monotonicity criterion","The independence of irrelevant alternatives","The Condorcet criterion"]', 'The Condorcet criterion', NULL, 'A candidate whom most voters prefer to each other candidate is a Condorcet winner, and the Condorcet criterion says that such a candidate should win. The majority criterion is about first-place votes, monotonicity is about gaining support, and independence of irrelevant alternatives is about a candidate withdrawing.', 'checked', '{"lint":[],"solve":{"answer":"The Condorcet criterion","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Preferred by a majority to each other candidate: Condorcet criterion.","run_id":"claude-code","at":"2026-10-22T19:26:03.747Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e2a5735-12d7-4fec-b0ee-ffdcc108dcbb', 'NC26.ALR.MDMF.1', 2, 'choice', 'Fairness criteria', 'Which method always elects a candidate who wins every head-to-head comparison, whenever such a candidate exists?', '["Plurality","The Borda count","Pairwise comparison","Plurality with elimination"]', 'Pairwise comparison', NULL, 'A candidate who wins every head-to-head comparison earns the most possible points in pairwise comparison, so pairwise comparison elects that candidate. The others can miss them: for example, with 14 voters ranking 3: C, A, B; 6: B, A, C; 5: C, B, A, candidate C beats both others 8 to 6, but the Borda count (2, 1, 0 points) gives B 17 points and C only 16.', 'checked', '{"lint":[],"solve":{"answer":"Pairwise comparison","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairwise comparison elects a candidate who wins every head-to-head (Condorcet criterion); the other three can fail it.","run_id":"claude-code","at":"2026-10-23T00:27:24.666Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa06868-409c-468f-ad91-42a7fde85364', 'NC26.ALR.MDMF.1', 2, 'choice', 'Arrow''s Impossibility Theorem', 'A voting method ranks X above Y. Then some voters change how they rank a third candidate Z, but no voter changes how they rank X against Y. The method now ranks Y above X. Which of Arrow''s conditions does the method break?', '["Unanimity: if every voter ranks X above Y, the group should rank X above Y","Non-dictatorship: no single voter''s ranking should always decide the result","Universal domain: every possible set of voter rankings should be allowed","Independence of irrelevant alternatives: the order of X and Y should depend only on how voters rank X and Y"]', 'Independence of irrelevant alternatives: the order of X and Y should depend only on how voters rank X and Y', NULL, 'Z is irrelevant to the order of X and Y, yet moving Z changed that order. That is exactly a violation of independence of irrelevant alternatives.', 'checked', '{"lint":[],"solve":{"answer":"Independence of irrelevant alternatives: the order of X and Y should depend only on how voters rank X and Y","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The X-Y order changed though no one changed X vs Y: IIA is broken.","run_id":"claude-code","at":"2026-10-23T00:27:24.666Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bc018ec-8a54-4033-ac6d-441689803f74', 'NC26.ALR.MDMF.1', 3, 'choice', 'Fairness criteria', 'Which scenario shows a violation of the monotonicity criterion?', '["Candidate X wins. Some voters then move X higher on their ballots, nothing else changes, and X no longer wins","Candidate X wins. Some voters then move X lower on their ballots, nothing else changes, and X no longer wins","Candidate X wins. Some voters then move Y higher on their ballots, nothing else changes, and Y wins instead","Candidate X loses. Some voters then move X lower on their ballots, nothing else changes, and X still loses"]', 'Candidate X wins. Some voters then move X higher on their ballots, nothing else changes, and X no longer wins', NULL, 'Monotonicity says that extra support must not hurt a winner. The violation is a winner who loses after being moved UP. A winner who loses after being moved down, or a candidate who benefits from more support, is not a violation.', 'checked', '{"lint":[],"solve":{"answer":"Candidate X wins. Some voters then move X higher on their ballots, nothing else changes, and X no longer wins","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Monotonicity: raising the winner on ballots should not make them lose.","run_id":"claude-code","at":"2026-10-23T00:27:24.666Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('159d0708-90c3-4f8f-8361-64f993a1e007', 'NC26.ALR.MDMF.1', 3, 'numeric', 'Fairness criteria', 'In a plurality election the first-place votes are Ruth 41, Sam 37 and Tia 22, so Ruth wins. Tia then withdraws. Of Tia''s 22 voters, 14 vote for Sam and 8 for Ruth, and nobody else changes. In the new plurality election, how many votes does the winner receive?', '[]', '51', '37+14', 'The new totals are Ruth $41 + 8 = 49$ and Sam $37 + 14 = 51$. Sam wins with 51 votes. Removing Tia, who could not win, changed the winner from Ruth to Sam, which violates the independence of irrelevant alternatives.', 'checked', '{"lint":[],"solve":{"answer":"51","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ruth 41+8 = 49, Sam 37+14 = 51. Sam wins with 51.","run_id":"claude-code","at":"2026-10-23T00:27:24.666Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aa5320b-825d-4088-b280-c4a026ab3f0d', 'NC26.ALR.MDMF.2', 1, 'numeric', 'Shapley-Shubik power index', 'In a weighted voting system with 4 players, the Shapley-Shubik power index of a player is the fraction of the 24 possible orders in which that player is pivotal. Player $P_3$ is pivotal in 6 of the 24 orders. What is the Shapley-Shubik power index of $P_3$?', '[]', '1/4', '6/24', 'The index is the fraction of orders in which $P_3$ is pivotal: $6 \div 24 = 1/4$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/24 = 1/4.","run_id":"claude-code","at":"2026-10-22T12:53:50.738Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('086e7cd3-4810-4ef7-a91e-6c444eb14490', 'NC26.ALR.MDMF.2', 1, 'numeric', 'Counting coalitions and orders', 'A committee has 5 voters. How many different coalitions of exactly 2 voters can be formed?', '[]', '10', '5*4/2', 'Choose a first voter in 5 ways and a second in 4 ways, which gives 20 ordered pairs. Each pair is counted twice, so there are 20 / 2 = 10 coalitions.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(5,2)=10.","run_id":"claude-code","at":"2026-10-22T19:38:13.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f37795-3b3b-4d3f-a146-16c24dcb2389', 'NC26.ALR.MDMF.2', 1, 'choice', 'Critical players, dictators, veto power and dummies', 'A dictator is a player who wins alone while every coalition without that player loses. Each system below is written $[q: w_1, w_2, w_3, w_4]$, with the quota first and then the weights of $P_1$ to $P_4$. Which system has a dictator?', '["$[7: 8, 2, 2, 1]$","$[9: 5, 4, 3, 2]$","$[8: 4, 3, 3, 2]$","$[6: 4, 3, 2, 1]$"]', '$[7: 8, 2, 2, 1]$', NULL, 'In $[7: 8, 2, 2, 1]$, $P_1$ has weight 8, which is at least 7, and the other three together have only 5, so they cannot win. In each other system no single player reaches the quota.', 'checked', '{"lint":[],"solve":{"answer":"$[7: 8, 2, 2, 1]$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"[7:8,2,2,1]: P1 8>=7 alone, others total 5<7, so P1 is dictator. Others: no single weight reaches quota.","run_id":"claude-code","at":"2026-10-22T19:38:13.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0eceb9f9-3d32-4615-be0b-cc8de4e16ebd', 'NC26.ALR.MDMF.2', 2, 'choice', 'Banzhaf power index', 'In a weighted voting system with quota 7, the weights of $P_1$, $P_2$, $P_3$ and $P_4$ are 4, 3, 2 and 1. Which statement about the Banzhaf power indices is true?', '["$P_2$ has twice the index of $P_3$","$P_3$ and $P_4$ have the same index, even though their weights differ","$P_1$ has an index greater than 3/5","$P_4$ is a dummy"]', '$P_3$ and $P_4$ have the same index, even though their weights differ', NULL, 'The winning coalitions are $(P_1, P_2)$ 7, $(P_1, P_2, P_3)$ 9, $(P_1, P_2, P_4)$ 8, $(P_1, P_3, P_4)$ 7, $(P_1, P_2, P_3, P_4)$ 10. The critical counts are 5, 3, 1, 1 out of 10. So $P_3$ and $P_4$ are tied at 1/10; $P_2$ has 3 times $P_3$''s index; $P_1$ has 1/2; and $P_4$ is critical once, so it is not a dummy.', 'checked', '{"lint":[],"solve":{"answer":"$P_3$ and $P_4$ have the same index, even though their weights differ","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts: P1 5, P2 3, P3 1, P4 1 (total 10). P3 and P4 both 1/10 despite weights 2 and 1. Others false (P2 is 3x P3; P4 not dummy; P1 = 1/2).","run_id":"claude-code","at":"2026-10-22T19:38:13.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b1f1039-7108-421c-9566-2f56a36020d2', 'NC26.ALR.MDMF.2', 2, 'numeric', 'Shapley-Shubik power index', 'In a weighted voting system with quota 7, the weights of $P_1$, $P_2$, $P_3$ and $P_4$ are 5, 3, 2 and 2. The four players join in each of the 24 possible orders. In how many of these orders is $P_2$ the pivotal player, the one whose joining first brings the total to 7 or more?', '[]', '4', NULL, 'Pivotal player in each order: 1234:P2, 1243:P2, 1324:P3, 1342:P3, 1423:P4, 1432:P4, 2134:P1, 2143:P1, 2314:P1, 2341:P4, 2413:P1, 2431:P3, 3124:P1, 3142:P1, 3214:P1, 3241:P4, 3412:P1, 3421:P2, 4123:P1, 4132:P1, 4213:P1, 4231:P3, 4312:P1, 4321:P2. $P_2$ is pivotal in 4 of the 24 orders.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Enumeration: pivotal counts P1 12, P2 4, P3 4, P4 4. P2 = 4.","run_id":"claude-code","at":"2026-10-22T19:38:13.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cf86e50-ed06-40e5-ace4-4cd5ead5785c', 'NC26.ALR.MDMF.2', 2, 'numeric', 'Fairness of weighted voting systems', 'A board has five members with 1 vote each, and a motion needs 3 votes. A member is critical in a winning coalition if the coalition would lose without that member. Counting every winning coalition, how many times in total are the members critical?', '[]', '30', '10*3', 'A coalition of 3 members wins, and each of its 3 members is critical (removing one leaves 2). There are 5 × 4 × 3 / (3 × 2 × 1) = 10 such coalitions, so 10 × 3 = 30 critical positions. Coalitions of 4 or 5 members still win after losing one member, so nobody is critical there.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 3-member coalitions have critical members: C(5,3)=10, each with 3 critical: 30.","run_id":"claude-code","at":"2026-10-22T19:38:13.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08fcecc9-5781-4717-8257-205a4d51aa59', 'NC26.ALR.MDMF.2', 3, 'choice', 'Quota, weights and winning coalitions', 'In a weighted voting system with quota 8, the weights of $P_1$, $P_2$, $P_3$ and $P_4$ are 5, 4, 3 and 2. A winning coalition is minimal if it would lose whenever any one of its members left. Which choice lists all the minimal winning coalitions?', '["$(P_1, P_2)$ and $(P_1, P_3)$","$(P_1, P_2)$, $(P_1, P_3)$, $(P_2, P_3, P_4)$ and $(P_1, P_2, P_3)$","$(P_1, P_2)$, $(P_1, P_3)$ and $(P_1, P_4)$","$(P_1, P_2)$, $(P_1, P_3)$ and $(P_2, P_3, P_4)$"]', '$(P_1, P_2)$, $(P_1, P_3)$ and $(P_2, P_3, P_4)$', NULL, '$(P_1, P_2)$ has weight 9 and $(P_1, P_3)$ has weight 8; each loses if either member leaves. $(P_2, P_3, P_4)$ has weight 9, and it loses if any member leaves (4+3 = 7, 4+2 = 6, 3+2 = 5). $(P_1, P_4)$ has weight 7 and loses. Any other winning coalition contains one of these three, so it is not minimal.', 'checked', '{"lint":[],"solve":{"answer":"$(P_1, P_2)$, $(P_1, P_3)$ and $(P_2, P_3, P_4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Winning: P1P2=9, P1P3=8, P2P3P4=9, and supersets. P1P4=7 loses. P1P2P3, P1P2P4, P1P3P4 are not minimal (drop P3/P4 still wins). Minimal: P1P2, P1P3, P2P3P4.","run_id":"claude-code","at":"2026-10-22T19:38:13.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02cee31e-0e4e-4ac1-8d06-c22be5506853', 'NC26.ALR.MDMF.2', 3, 'choice', 'Counting coalitions and orders', 'A council has 7 voters, including Dev. How many coalitions of exactly 3 voters do not include Dev?', '["15","35","21","20"]', '20', '6*5*4/(3*2*1)', 'Without Dev there are 6 voters. The number of ways to choose 3 of them is 6 × 5 × 4 / (3 × 2 × 1) = 20. (15 counts the coalitions that do include Dev; 35 counts all coalitions of 3.)', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Choose 3 from the other 6: C(6,3)=20.","run_id":"claude-code","at":"2026-10-22T19:38:13.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17405a51-a7e8-4c88-8245-78761a7573a6', 'NC26.ALR.MDMF.3', 1, 'numeric', 'Fair shares and fairness', 'Five people share a prize that Dana values at 150 dollars. In a fair division, each person must receive a share that he or she values as at least $\frac{1}{5}$ of the whole. What is the least value, in dollars, that Dana can place on her share?', '[]', '30', '150/5', 'A fair share for 5 people is $\frac{1}{5}$ of the whole, by the player''s own values: $150\div5=30$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 / 5 = 30.","run_id":"claude-code","at":"2026-10-22T19:26:03.785Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a2280c0-e625-4fe6-9f4f-1716b4ac7aaa', 'NC26.ALR.MDMF.3', 1, 'numeric', 'Lone-chooser method', 'Ana, Ben and Cy share a cake by the lone-chooser method. Ana and Ben first split the cake between them, and each then cuts his or her own share into three pieces. Cy takes one piece from Ana''s pieces and one from Ben''s pieces. How many pieces does Cy get?', '[]', '2', '1+1', 'Cy chooses one piece from each of the two sets of three pieces, so Cy gets $1+1=2$ pieces.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One from Ana''s pieces and one from Ben''s: 2.","run_id":"claude-code","at":"2026-10-22T19:26:03.785Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c8a41cf-63ea-43e7-9a99-6abd97392dbe', 'NC26.ALR.MDMF.3', 1, 'choice', 'Strengths and fairness of the methods', 'Which fair-division method uses cash payments between the players to make up differences in value?', '["Divider-chooser","Lone-divider","Sealed bids","Lone-chooser"]', 'Sealed bids', NULL, 'In sealed bids, items go to the highest bidders, and players who receive more than their fair share pay cash to those who receive less. The other three methods divide a cake without money changing hands.', 'checked', '{"lint":[],"solve":{"answer":"Sealed bids","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sealed bids settles with cash payments.","run_id":"claude-code","at":"2026-10-22T19:26:03.785Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0071a573-1a7e-49db-8561-78a2f2d27f22', 'NC26.ALR.MDMF.3', 2, 'choice', 'Fair shares and fairness', 'A division is envy-free if no player values another player''s share more than his or her own. Ann values her own share at 40 percent of the cake, Bo''s share at 35 percent and Cy''s share at 25 percent. Bo values Ann''s share at 30 percent, his own at 30 percent and Cy''s at 40 percent. Cy values Ann''s share at 30 percent, Bo''s at 30 percent and his own at 40 percent. Which statement is true?', '["Only Ann envies another player''s share, because Bo''s share is worth 35 percent to her","Only Bo envies another player''s share, because he values Cy''s share more than his own","Ann and Cy both envy another player''s share, because each values another share at 30 percent or more","Nobody envies another player''s share, so the division is envy-free, because every player holds a share worth 30 or more"]', 'Only Bo envies another player''s share, because he values Cy''s share more than his own', NULL, 'Ann values her own share (40) more than the others (35 and 25), so she does not envy anyone. Cy values his own share (40) more than the others (30 and 30), so he does not either. Bo values Cy''s share at 40, which is more than his own 30, so Bo envies Cy. Only Bo envies another player.', 'checked', '{"lint":[],"solve":{"answer":"Only Bo envies another player''s share, because he values Cy''s share more than his own","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ann: own 40 vs 35, 25 - no envy. Bo: own 30 but Cy''s 40 - envies Cy. Cy: own 40 vs 30, 30 - no envy. Only Bo envies.","run_id":"claude-code","at":"2026-10-23T00:52:20.686Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('118fa05b-f06d-4497-821d-504bd906773e', 'NC26.ALR.MDMF.3', 2, 'choice', 'Fair shares and fairness', 'Two players divide a cake. Ana values her own piece at 55 percent of the whole cake. Bo values his own piece at 47 percent of the whole cake. Which statement must be true?', '["Ana values Bo''s piece at more than she values her own piece, 55 percent","The division is proportional, because 55 and 47 are both close to half of the cake","Each player values his or her own piece at more than the other player''s piece","Bo values Ana''s piece at 53 percent, which is more than he values his own piece"]', 'Bo values Ana''s piece at 53 percent, which is more than he values his own piece', NULL, 'Bo values the two pieces at 100 percent in all. His own piece is 47, so Ana''s piece is 100 - 47 = 53 percent to him, which is more than 47. Ana values Bo''s piece at only 100 - 55 = 45 percent, less than her own. The division is not proportional because Bo''s 47 is below 50, and Bo values Ana''s piece more than his own.', 'checked', '{"lint":[],"solve":{"answer":"Bo values Ana''s piece at 53 percent, which is more than he values his own piece","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two pieces make the whole. Ana values Bo''s piece at 45 < 55, so A false. Bo values Ana''s piece at 100-47 = 53 > 47, so B true. C false for Bo. D false: Bo has 47 < 50.","run_id":"claude-code","at":"2026-10-23T00:52:20.686Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0014461a-a581-4ed1-9392-f46177d8b6f3', 'NC26.ALR.MDMF.3', 2, 'numeric', 'Lone-chooser method', 'Ana and Ben split a cake and Ana gets a share she values at $\frac{1}{2}$ of the whole cake. In the lone-chooser method she cuts her share into three pieces that she values equally, and Cy takes one of them. What fraction of the whole cake does Ana keep, in her own view?', '[]', '1/3', '1/2*2/3', 'Ana keeps 2 of her 3 equal pieces, which is 2/3 of her share. Her share is worth 1/2 of the cake to her, so she keeps 1/2 x 2/3 = 1/3 of the cake.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 of 1/2 = 1/3.","run_id":"claude-code","at":"2026-10-23T00:52:20.686Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0749ed40-19b5-477c-b46c-61457d8b788a', 'NC26.ALR.MDMF.3', 3, 'numeric', 'Fair shares and fairness', 'Dev and four others share an estate, and Dev values the whole estate at 350 dollars. A division is fair to him when the items and cash he ends up with are worth at least $\frac{1}{5}$ of 350 dollars to him. He receives a boat he values at 90 dollars, pays some cash into a pool, and later gets 6 dollars back as his share of the money left over. What is the most he can pay into the pool and still have a fair share, in dollars?', '[]', '26', '90+6-350/5', 'His fair share is 350 / 5 = 70 dollars. He ends with the boat (90 dollars) plus 6 dollars back, minus what he pays in. So 90 + 6 - x must be at least 70, which gives x at most 26 dollars.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fair = 350/5 = 70. Value = 90 - x + 6 >= 70, so x <= 26.","run_id":"claude-code","at":"2026-10-23T00:52:20.686Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('021506fb-e255-4c8d-9b72-378f2ebe1796', 'NC26.ALR.MDMF.3', 3, 'numeric', 'Sealed bids', 'Ann, Ben and Cy use the sealed-bids method for a truck and a trailer. Ann bids 50 and 100 dollars for them, in that order. Ben bids 170 and 220 dollars. Cy bids 70 and 110 dollars. Items go to the highest bidders. A player''s fair share is the total of his or her bids divided by 3. Each player pays the pool, or is paid from it, the difference between the items won (by his or her own bids) and the fair share, and the leftover is split equally. How many dollars does Ben pay in NET, that is, the amount he pays into the pool minus his equal share of the leftover?', '[]', '210', '(170+220-(170+220)/3)-((170+220-(170+220)/3)-(50+100)/3-(70+110)/3)/3', 'Ben wins both items, worth 170 + 220 = 390 dollars by his bids. His fair share is 390 / 3 = 130, so he pays 390 - 130 = 260 dollars into the pool. Ann is paid her fair share, (50 + 100) / 3 = 50, and Cy is paid (70 + 110) / 3 = 60. The leftover is 260 - 50 - 60 = 150 dollars, so each player gets 50. Ben''s net payment is 260 - 50 = 210 dollars.', 'checked', '{"lint":[],"solve":{"answer":"210","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ben wins both (170, 220) = 390. Fair: Ann 150/3=50, Ben 390/3=130, Cy 180/3=60. Ben pays 260; Ann paid 50, Cy paid 60. Leftover 150, each 50. Ben net 260-50 = 210.","run_id":"claude-code","at":"2026-10-23T00:52:20.686Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('060a6a33-b7d2-490d-ab82-e24e8b635c3e', 'NC26.ALR.MDMF.4', 1, 'choice', 'Average constituency', 'The average constituency of a state is its number of people per seat. Which state has the largest average constituency? North has 3000 people and 10 seats. East has 2100 people and 6 seats. South has 2200 people and 5 seats. West has 1900 people and 5 seats.', '["South","North","East","West"]', 'South', NULL, 'Divide each population by its seats: North 300, East 350, South 440, West 380. South has the most people per seat. North has the largest population, but it also has the most seats.', 'checked', '{"lint":[],"solve":{"answer":"South","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"North 300, East 350, South 440, West 380. South largest.","run_id":"claude-code","at":"2026-10-22T19:26:03.824Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04915c02-530e-4703-9b49-71765c0fd9be', 'NC26.ALR.MDMF.4', 1, 'choice', 'Jefferson method', 'In the Jefferson method, a trial modified divisor gives a total of 22 seats when only 20 seats are to be shared. What should be done next?', '["Try a smaller modified divisor, so that the modified quotas get larger","Take a seat from each of the two states with the smallest decimal parts","Round the modified quotas up instead of down, to settle the total","Try a larger modified divisor, so that the modified quotas get smaller"]', 'Try a larger modified divisor, so that the modified quotas get smaller', NULL, 'Each state''s modified quota is its population divided by the divisor. A larger divisor makes every quota smaller and so lowers the total number of seats. The Jefferson method keeps rounding down and only changes the divisor.', 'checked', '{"lint":[],"solve":{"answer":"Try a larger modified divisor, so that the modified quotas get smaller","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Too many seats: larger divisor to make quotas smaller. Option D.","run_id":"claude-code","at":"2026-10-23T00:52:20.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00d40e87-df3b-4653-9c9a-df8962b65285', 'NC26.ALR.MDMF.4', 1, 'choice', 'Average constituency', 'The average constituency of a state is its number of people per seat. Lake has 4,800 people and 8 seats, Hill has 3,500 people and 5 seats, Bay has 2,160 people and 3 seats, and Glen has 5,700 people and 10 seats. Which state has the smallest average constituency?', '["Lake","Hill","Glen","Bay"]', 'Glen', NULL, 'The averages are Lake 4,800 / 8 = 600, Hill 3,500 / 5 = 700, Bay 2,160 / 3 = 720 and Glen 5,700 / 10 = 570. The smallest is Glen, with 570 people per seat.', 'checked', '{"lint":[],"solve":{"answer":"Glen","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lake 600, Hill 700, Bay 720, Glen 570. Smallest Glen.","run_id":"claude-code","at":"2026-10-23T00:52:20.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1acb4f02-ddc1-4518-8666-b290ace47256', 'NC26.ALR.MDMF.4', 2, 'choice', 'Bias of the methods', 'Which statement is true?', '["Adams tends to favor states with large populations.","Jefferson tends to favor states with small populations.","Jefferson tends to favor states with large populations.","Hamilton rounds every quota up to the next whole number."]', 'Jefferson tends to favor states with large populations.', NULL, 'Jefferson rounds down, so it must use a smaller divisor to reach the total, and that helps the states with large populations. Adams rounds up and so tends to favor small states. Hamilton rounds quotas down first and then gives leftover seats to the largest decimal parts.', 'checked', '{"lint":[],"solve":{"answer":"Jefferson tends to favor states with large populations.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Jefferson (rounding down) favors large states; Adams favors small; Hamilton does not round all up.","run_id":"claude-code","at":"2026-10-22T19:26:03.824Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a9c20a3-3558-49b9-a4fd-45c63a28bfa1', 'NC26.ALR.MDMF.4', 2, 'numeric', 'Webster method', 'Twenty seats are shared by the Webster method among five regions with populations, in thousands, of 395, 201, 157, 25 and 22. The modified divisor 42 gives exactly 20 seats. How many seats does the region with 22 thousand people receive?', '[]', '1', NULL, 'With the modified divisor 42 the modified quotas are 9.40, 4.79, 3.74, 0.60 and 0.52, and the Webster method rounds to the nearest whole number: 9, 5, 4, 1 and 1, which is 20 seats. The region with 22 thousand people has a modified quota of 0.52, which rounds to 1, so it receives 1 seat.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22/42 = 0.52 -> 1 (others 9.40->9, 4.79->5, 3.74->4, 0.60->1; total 20).","run_id":"claude-code","at":"2026-10-23T00:52:20.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('013bf059-1540-4c70-930e-d32e79247c97', 'NC26.ALR.MDMF.4', 2, 'numeric', 'Average constituency', 'The average constituency of a state is its number of people per seat. A county with 21,000 people has 3 seats, and a fourth seat is added. What is the average constituency of the county after the fourth seat is added?', '[]', '5250', '21000/4', 'The average constituency is now 21,000 / 4 = 5,250 people per seat. (It was 7,000 before.)', 'checked', '{"lint":[],"solve":{"answer":"5250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21,000/4 = 5,250.","run_id":"claude-code","at":"2026-10-23T00:52:20.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08e3add3-b131-4a97-9fef-db45dcbec8cf', 'NC26.ALR.MDMF.4', 3, 'choice', 'Jefferson method', 'In the Jefferson method, 14 seats are shared among four states whose populations, in thousands, are Aspen 316, Birch 306, Cedar 199 and Dogwood 103. Which modified divisor gives exactly 14 seats?', '["50","60","66","70"]', '60', '60', 'Divide each population by the divisor and round down, then add. With 60 the seats are 5, 5, 3 and 1, a total of 14. With 50 the total is 17, with 66 (the standard divisor) it is 12, and with 70 it is 11.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d=60: 5.27->5, 5.1->5, 3.32->3, 1.72->1 = 14. d=66: 4,4,3,1 = 12. d=70: 4,4,2,1 = 11. d=50: 6,6,3,2 = 17. Answer 60.","run_id":"claude-code","at":"2026-10-22T19:26:03.824Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a6122ee-f9dc-430e-bedb-fca9b85cd8b4', 'NC26.ALR.MDMF.4', 3, 'numeric', 'Adams method', 'Use the Adams method to share 18 seats among four states. Their populations, in thousands, are Aspen 257, Birch 234, Cedar 97 and Dogwood 42. How many seats does Dogwood receive?', '[]', '2', NULL, 'The standard divisor is $630 \div 18 = 35$. Rounding the quotas up (about 7.34, 6.69, 2.77, 1.20) gives 8, 7, 3 and 2, a total of 20, which is 2 too many. A larger divisor is needed. With 40 the quotas are about 6.43, 5.85, 2.43, 1.05, which round up to 7, 6, 3 and 2, a total of 18. Dogwood gets 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 630, SD 35: ceilings 8+7+3+2 = 20, too many. d=40: A 6.43->7, B 5.85->6, C 2.43->3, D 1.05->2 = 18. Dogwood drops to 1 only at d>=42, where total is 7+6+3+1 = 17, so any valid divisor gives Dogwood 2.","run_id":"claude-code","at":"2026-10-22T19:26:03.824Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b39c311-dab4-4cc0-8e73-db94c69bdef2', 'NC26.ASDS.FSP.1', 1, 'choice', 'Tell statistical questions from non-statistical ones', 'Which question can be answered only by collecting data from many students, whose answers are expected to differ?', '["How tall is the flagpole in front of our school?","How tall are the students in grade 9 at our school?","How many inches are there in one foot?","How tall was Mia on her last birthday?"]', 'How tall are the students in grade 9 at our school?', NULL, 'A statistical question expects answers that vary, so many pieces of data are needed. Students in grade 9 have different heights. The other questions each have one single answer.', 'checked', '{"lint":[],"solve":{"answer":"How tall are the students in grade 9 at our school?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights of grade 9 students vary and need data from many students; others have a single answer.","run_id":"claude-code","at":"2026-10-23T00:16:22.459Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01cab39b-8239-4d4c-905e-f3180b67ab1e', 'NC26.ASDS.FSP.1', 1, 'numeric', 'See how framing shapes conclusions', 'The same 80 students were asked about a later start time using two different wordings. Wording 1 got 56 "yes" answers. Wording 2 got 40 "yes" answers. By how many percentage points do the two "yes" percents differ?', '[]', '20', '56/80*100-40/80*100', 'Wording 1: 56 / 80 = 70%. Wording 2: 40 / 80 = 50%. The difference is 70 - 50 = 20 percentage points, so the wording changed the result.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56/80 = 70%; 40/80 = 50%; difference 20 points.","run_id":"claude-code","at":"2026-10-22T19:37:12.782Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1be9d963-b668-4c45-986d-a6f898c1b686', 'NC26.ASDS.FSP.1', 1, 'choice', 'Refine a question so data can answer it', 'A well-framed statistical question names the group asked, the thing measured and the time. Look at this question: "How many minutes do the 7th graders at Park Middle School spend on homework on a school night?" Which part is the thing that is measured?', '["the minutes of homework","the 7th graders at Park","Park Middle School itself","on a school night"]', 'the minutes of homework', NULL, 'The group asked is the 7th graders at Park Middle School. The time is a school night. What is measured is how long each student works, which is the minutes of homework.', 'checked', '{"lint":[],"solve":{"answer":"the minutes of homework","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The group is the 7th graders at Park; the time is a school night; the thing measured is minutes of homework.","run_id":"claude-code","at":"2026-10-23T00:29:46.866Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cd97274-9f60-494e-8833-6810eb713f7e', 'NC26.ASDS.FSP.1', 2, 'choice', 'Tell statistical questions from non-statistical ones', 'Which question is NOT a statistical question?', '["How do the scores of the Hawks'' games this season compare?","What was the score of the final game of the Hawks'' season?","What is a typical score for the Hawks in a game this season?","How much do the Hawks'' scores vary from game to game?"]', 'What was the score of the final game of the Hawks'' season?', NULL, 'The other three questions ask about all the games in a season, where the scores vary. The question about the final game has a single answer, so there is no variability to study.', 'checked', '{"lint":[],"solve":{"answer":"What was the score of the final game of the Hawks'' season?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Variation from game to game, a typical score and comparing scores all involve many varying values. The score of one particular game is a single fact, so it is not statistical.","run_id":"claude-code","at":"2026-10-22T12:51:22.253Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07bde9fd-eeec-4e46-ae1f-fa76e2c2bae3', 'NC26.ASDS.FSP.1', 2, 'choice', 'Refine a question for its audience and purpose', 'The town council is deciding whether to add bike lanes. Which statistical question is best for the council''s purpose?', '["How many bikes were sold in the whole country last year?","What is the most popular bike color among students at one school?","How many trips do residents of the town take by bike in a week?","How fast can a professional cyclist ride?"]', 'How many trips do residents of the town take by bike in a week?', NULL, 'The council needs to know how much residents of the town would use the lanes. Trips by bike in a week for town residents is related to that purpose and varies from person to person. The other questions are about the wrong group, an unrelated feature or a single answer.', 'checked', '{"lint":[],"solve":{"answer":"How many trips do residents of the town take by bike in a week?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The council needs local bike use: trips by town residents per week. National sales, bike colour at one school, pro speed are irrelevant.","run_id":"claude-code","at":"2026-10-22T12:51:22.253Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1028007a-0a94-4ae5-8535-1a72609249d9', 'NC26.ASDS.FSP.1', 2, 'choice', 'Refine a question for its audience and purpose', 'A principal is deciding whether to start school 30 minutes later. Which statistical question best fits that purpose?', '["What time did school start in the building at the start of last year?","How many hours do the students at our school sleep on school nights?","What is the principal''s favorite time of the day to work?","How many students are in the whole school this year?"]', 'How many hours do the students at our school sleep on school nights?', NULL, 'The decision is about students'' sleep and morning schedules, so the question should measure sleep. The others do not give evidence about whether a later start would help.', 'checked', '{"lint":[],"solve":{"answer":"How many hours do the students at our school sleep on school nights?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Students'' sleep on school nights is statistical and relevant to a later start.","run_id":"claude-code","at":"2026-10-22T19:37:12.782Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d7b2036-cee7-49b0-a32c-e5f1da28e98a', 'NC26.ASDS.FSP.1', 3, 'numeric', 'Refine a question so data can answer it', 'A student refines her question to "What percent of the students in grade 9 at Elm High walk to school?" She asks a random group of 50 students in grade 9, and 14 say they walk. What percent of the 50 students walk?', '[]', '28', '14/50*100', 'The percent is 14 out of 50, which is 14 / 50 = 0.28 = 28%.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/50 = 0.28 = 28%.","run_id":"claude-code","at":"2026-10-22T19:37:12.782Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1803b278-0ead-4fce-af25-34b9b39e52a3', 'NC26.ASDS.FSP.1', 3, 'choice', 'See how framing shapes conclusions', 'A soda company pays for a survey titled "Why Teens Love Sugary Drinks." What is the most important concern about its results?', '["Surveys that are paid for by any company are always correct.","Teens cannot give opinions about drinks that they have never bought.","The survey must be wrong, because the results of a sponsored survey can never be trusted at all.","The sponsor and title may shape the questions and how results are reported."]', 'The sponsor and title may shape the questions and how results are reported.', NULL, 'Who pays for a study and how it is titled can influence the question wording and the conclusions. That is a reason to look more closely, though it does not prove the results are wrong.', 'checked', '{"lint":[],"solve":{"answer":"The sponsor and title may shape the questions and how results are reported.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sponsor bias and a leading title may shape questions and reporting.","run_id":"claude-code","at":"2026-10-23T00:16:22.459Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1012e81d-3766-4ee0-850e-5bdbba25d4c8', 'NC26.ASDS.CCD.1', 1, 'choice', 'Random assignment and experimental design', 'Researchers give bean plants different amounts of water and measure how tall each plant grows. Which variable is the response variable?', '["The amount of water each plant gets","The type of bean in each pot","The height of each plant","The size of each flower pot"]', 'The height of each plant', NULL, 'The response variable is the outcome that is measured, which here is plant height. The amount of water is the explanatory variable that the researchers change.', 'checked', '{"lint":[],"solve":{"answer":"The height of each plant","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Response variable is the outcome measured: plant height.","run_id":"claude-code","at":"2026-10-22T19:37:12.822Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f31c820-9466-46e0-b60c-fe7faa48da18', 'NC26.ASDS.CCD.1', 1, 'choice', 'Ethics in data collection', 'A researcher gives students'' names and test scores to a newspaper without their permission. Which ethical principle is broken?', '["Random sampling","Confidentiality","Double blinding","Replication"]', 'Confidentiality', NULL, 'Confidentiality means keeping participants'' personal information private. Sharing names with scores without permission breaks that principle.', 'checked', '{"lint":[],"solve":{"answer":"Confidentiality","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Releasing names with scores without permission breaks confidentiality.","run_id":"claude-code","at":"2026-10-22T19:37:12.822Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('143203a0-ea72-435a-9e1b-757ee12de202', 'NC26.ASDS.CCD.1', 1, 'choice', 'Neutral survey questions and answer choices', 'Which set of answer choices is balanced?', '["Disagree, neutral, agree, strongly agree, completely agree","Strongly disagree, neutral, agree, strongly agree, completely agree","Neutral, agree, strongly agree, completely agree, totally agree","Strongly disagree, disagree, neutral, agree, strongly agree"]', 'Strongly disagree, disagree, neutral, agree, strongly agree', NULL, 'A balanced scale has the same number of choices on each side of the middle. Each of the other lists has more agreeing choices than disagreeing ones.', 'checked', '{"lint":[],"solve":{"answer":"Strongly disagree, disagree, neutral, agree, strongly agree","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B has two negative, neutral, two positive: balanced.","run_id":"claude-code","at":"2026-10-22T19:37:12.822Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ba03d79-5260-4e45-bd65-6ffab31528d1', 'NC26.ASDS.CCD.1', 2, 'numeric', 'Random sampling methods', 'A district has 40 schools with 500 students each. A researcher uses a cluster sample: she chooses 5 schools at random and surveys every student at those 5 schools. Exactly 80% of the students surveyed answer. How many answers does she receive?', '[]', '2000', '5*500*8/10', 'She surveys $5 \times 500 = 2500$ students. Of these, 80% answer: $2500 \times 0.8 = 2000$.', 'checked', '{"lint":[],"solve":{"answer":"2000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Surveyed: 5 schools x 500 = 2,500 students. 80% answer: 0.8 x 2500 = 2,000.","run_id":"claude-code","at":"2026-10-22T12:51:31.716Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2163b552-47d4-4927-ae70-e55f11b160b8', 'NC26.ASDS.CCD.1', 2, 'choice', 'Sources of bias in samples', 'To learn about all adults in a town, a researcher chooses a random sample of homes from the town''s landline telephone directory. Many adults in the town have only a cell phone and are not listed. What kind of bias does this cause?', '["Nonresponse bias","Undercoverage bias","Voluntary response bias","Wording bias"]', 'Undercoverage bias', NULL, 'Adults with only a cell phone have no chance of being chosen, because they are not on the list. Leaving part of the population out of the list is undercoverage.', 'checked', '{"lint":[],"solve":{"answer":"Undercoverage bias","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Part of the population (cell-only adults) has no chance of being chosen because they are not on the sampling frame: undercoverage.","run_id":"claude-code","at":"2026-10-22T12:51:31.716Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1554c608-03b9-4c2b-a3d5-d988e7cc3325', 'NC26.ASDS.CCD.1', 2, 'choice', 'Sources of bias in samples', 'A teacher stands next to students while they answer, "In the last month, how many times did you cheat on a test?" Why might the answers be biased?', '["Students always overstate how much they did, which is called undercoverage bias.","Students may not answer honestly with the teacher watching: response bias.","Students will not be able to count the number of times they cheated.","Students in a class can only answer with numbers that are less than 10."]', 'Students may not answer honestly with the teacher watching: response bias.', NULL, 'When a question is sensitive, people often give answers that make them look good. That is response bias. It is unrelated to who was chosen for the sample.', 'checked', '{"lint":[],"solve":{"answer":"Students may not answer honestly with the teacher watching: response bias.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Teacher watching on a sensitive question leads to dishonest answers: response bias.","run_id":"claude-code","at":"2026-10-22T19:37:12.822Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09297749-dfd1-488c-b687-f6e44de92ad4', 'NC26.ASDS.CCD.1', 3, 'numeric', 'Random sampling methods', 'A list has 1,500 names. A systematic sample takes every 12th name, starting with name number 7. What is the number of the 5th name chosen?', '[]', '55', '7+4*12', 'The chosen names are 7, 19, 31, 43, 55, ... Each one is 12 more than the last. The 5th is 7 + 4 x 12 = 55.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7, 19, 31, 43, 55: the 5th is 7 + 4*12 = 55.","run_id":"claude-code","at":"2026-10-22T19:37:12.822Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('058a64f0-e921-4bdb-bbde-6db447906adc', 'NC26.ASDS.CCD.1', 3, 'choice', 'Using random digits to choose a sample', 'A researcher numbers 500 people in alphabetical order and then chooses numbers with a random number generator. Is the alphabetical order a problem?', '["Yes; the list must first be shuffled into a random order for the sample to be truly random.","No; every number has the same chance, so the order of the list is not a problem.","Yes; people near the start of the alphabet have a better chance, because their numbers are smaller.","No, but only if the digits are read from the end of the list."]', 'No; every number has the same chance, so the order of the list is not a problem.', NULL, 'The random number generator, not the list, decides who is chosen. Each of the 500 numbers is equally likely, so listing the people alphabetically does not change anyone''s chance.', 'checked', '{"lint":[],"solve":{"answer":"No; every number has the same chance, so the order of the list is not a problem.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With a random number generator every number equally likely, so list order doesn''t matter.","run_id":"claude-code","at":"2026-10-23T00:16:22.459Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad30f53-b573-4659-a35b-fa39dfa7cef6', 'NC26.ASDS.CCD.2', 1, 'choice', 'Identify the population and the sample', 'A company has 1,200 employees. To learn how long employees spend commuting, a manager asks 80 of them, chosen at random, how many minutes they travel to work. What is the population in this study?', '["The 80 employees who were asked","The 80 commute times that were reported","All 1,200 employees of the company","The manager who ran the survey"]', 'All 1,200 employees of the company', NULL, 'The population is the whole group the manager wants to learn about: all 1,200 employees. The 80 employees who were asked are the sample.', 'checked', '{"lint":[],"solve":{"answer":"All 1,200 employees of the company","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The population is the whole group the manager wants to learn about: all 1,200 employees. The 80 asked are the sample; their times are the data.","run_id":"claude-code","at":"2026-10-22T13:00:46.834Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dcde8ec-e22c-4850-b2ca-a4967a7f0251', 'NC26.ASDS.CCD.2', 1, 'choice', 'Choose a sampling method', 'A principal wants to know how all 900 students feel about a new bell schedule. Which plan is the best way to choose 90 students to ask?', '["Ask the 90 students who are in the first class of the day","Ask the first 90 students who happen to stop by her office","Number all the students and pick 90 numbers at random","Ask the 90 students who are on the school football team"]', 'Number all the students and pick 90 numbers at random', NULL, 'Only a random choice from the full list gives every student a fair chance. The other plans take students who are easy to reach, which may leave out many kinds of students.', 'checked', '{"lint":[],"solve":{"answer":"Number all the students and pick 90 numbers at random","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numbering all students and picking at random gives every student an equal chance; the others are convenience/biased groups.","run_id":"claude-code","at":"2026-10-22T19:37:54.918Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12292a35-84ee-4606-875b-f71726ffb34b', 'NC26.ASDS.CCD.2', 1, 'choice', 'Sample size, bias and validity of conclusions', 'Two random samples are taken from the same large population, one of 25 people and one of 250 people. Which sample will usually give a result closer to the true value for the population?', '["The sample of 25, because small samples are chosen more carefully","Both are always equally close to the true value","Neither, because a sample can never be close to the truth","The sample of 250, because larger random samples vary less"]', 'The sample of 250, because larger random samples vary less', NULL, 'Bigger random samples usually give results that are closer to the value for the whole population and vary less from sample to sample. A sample can be close, even though it is rarely exactly right.', 'checked', '{"lint":[],"solve":{"answer":"The sample of 250, because larger random samples vary less","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples have less sampling variability, so 250 is usually closer.","run_id":"claude-code","at":"2026-10-22T19:37:54.918Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f83cd87-de14-4188-a2c9-893c0cd9bc58', 'NC26.ASDS.CCD.2', 2, 'numeric', 'Simple random sample', 'The 60 students in a class are numbered 01 to 60. A teacher reads this list of random digits two digits at a time, from left to right: 47 83 15 62 09 31. She skips any number that is not from 01 to 60 and any repeat. What is the number of the third student she selects?', '[]', '9', NULL, 'Read the numbers in order: 47 is chosen (first), 83 is skipped (too big), 15 is chosen (second), 62 is skipped (too big), 09 is chosen (third). The third student is number 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47 valid (1st), 83 skip, 15 valid (2nd), 62 skip, 09 valid (3rd). Third student = 9.","run_id":"claude-code","at":"2026-10-22T13:00:46.834Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ced7a90-ca6f-4531-945a-0dcfcc068415', 'NC26.ASDS.CCD.2', 2, 'numeric', 'Identify the population and the sample', 'A sample of 150 people is 3 percent of the population it was taken from. How many people are in the population?', '[]', '5000', '150/0.03', 'If 3 percent of the population is 150 people, then the population is $150 \div 0.03 = 5000$ people.', 'checked', '{"lint":[],"solve":{"answer":"5000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 = 0.03 N, so N = 150/0.03 = 5000.","run_id":"claude-code","at":"2026-10-22T19:37:54.918Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14c98fb5-ee14-486a-a545-2475a795c95b', 'NC26.ASDS.CCD.2', 2, 'numeric', 'Voluntary response and convenience bias', 'A student government asks a question in the school newsletter and counts the replies that students email back. It receives 120 replies from a school of 1500 students. What percent of the school''s students replied? Give the number only, without the percent sign.', '[]', '8', '120/1500*100', 'The percent that replied is $\frac{120}{1500} \times 100 = 8$. Only students who chose to reply are counted, and the other 92 percent are missing, so the replies may not show what the whole school thinks.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120/1500 = 0.08 = 8%.","run_id":"claude-code","at":"2026-10-22T19:37:54.918Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03a3bead-3b8a-4f86-afb0-7dd78875df1c', 'NC26.ASDS.CCD.2', 3, 'numeric', 'Systematic sampling', 'A researcher chooses a systematic sample from a list of 600 people. She picks person number 7, and then every 12th person after that. What is the number of the 5th person she picks?', '[]', '55', '7+4*12', 'The picks are 7, 19, 31, 43, 55. The 5th pick is the start plus 4 steps of 12: 7 + 4 x 12 = 55.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7, 19, 31, 43, 55. The 5th is 7 + 4(12) = 55.","run_id":"claude-code","at":"2026-10-22T13:00:46.834Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0617a3b9-e82c-4980-8370-ddd37a171298', 'NC26.ASDS.CCD.2', 3, 'choice', 'Response bias and question wording', 'In a survey, 85 percent of people say they "always" recycle, but a check of household trash shows that far fewer do. What is the best explanation?', '["Undercoverage, because the survey was too short to be fair","Response bias, because people want to look good to others","The sample was too large for the answers to be accurate","The people who recycle all chose not to answer the survey"]', 'Response bias, because people want to look good to others', NULL, 'People often give answers that make them look good. That is response bias: the answers given differ from what is true.', 'checked', '{"lint":[],"solve":{"answer":"Response bias, because people want to look good to others","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"People overstate socially desirable behavior: response bias.","run_id":"claude-code","at":"2026-10-22T19:37:54.918Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('173ead03-f3aa-4478-9cb6-c87f44d045b8', 'NC26.ASDS.CCD.3', 1, 'numeric', 'Organize raw data into a table', 'Eight students were asked how many pets they have. The answers were 1, 0, 2, 1, 1, 3, 0 and 1. The answers are put in a frequency table. How many students have exactly 1 pet?', '[]', '4', NULL, 'Count the answers equal to 1. The answers 1, 1, 1 and 1 appear four times, so 4 students have exactly 1 pet.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Answers equal to 1: 1, 1, 1, 1 (positions 1, 4, 5, 8) = 4.","run_id":"claude-code","at":"2026-10-22T19:37:54.958Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a21cd0a-4187-41ab-9313-a873b93cd81e', 'NC26.ASDS.CCD.3', 1, 'numeric', 'Handle missing values', 'Five students'' heights in centimeters are 150, 155, (missing), 160 and 165. What is the mean of the four recorded heights?', '[]', '157.5', '(150+155+160+165)/4', 'Add the four recorded heights: $150 + 155 + 160 + 165 = 630$. Divide by 4: $630 \div 4 = 157.5$.', 'checked', '{"lint":[],"solve":{"answer":"157.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(150 + 155 + 160 + 165)/4 = 630/4 = 157.5.","run_id":"claude-code","at":"2026-10-22T19:37:54.958Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('134bd504-46c5-4c34-85ae-a8d27e7993dc', 'NC26.ASDS.CCD.3', 1, 'numeric', 'Recognize sources of bias', 'Mia wants to know the favorite sport of the 600 students at her school. She asks only the 15 members of the basketball team. What percent of the students at her school did she ask? Give the number only, without the percent sign.', '[]', '2.5', '15/600*100', 'She asked $\frac{15}{600} \times 100 = 2.5$ percent of the students. These are also not typical students, so the data may be biased.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/600 = 0.025 = 2.5%.","run_id":"claude-code","at":"2026-10-22T19:37:54.958Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad81b67-aa01-433a-8c07-2d1b8fb03db8', 'NC26.ASDS.CCD.3', 2, 'numeric', 'Standardize units and labels', 'A weather data set is in degrees Celsius, but one temperature is recorded as 68 degrees Fahrenheit. Use $C = \frac{5}{9}(F - 32)$ to convert it. What is the temperature in degrees Celsius?', '[]', '20', '5/9*(68-32)', 'Substitute $F = 68$: $C = \frac{5}{9}(68 - 32) = \frac{5}{9} \times 36 = 20$ degrees Celsius.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 5/9 (68 - 32) = 5/9 * 36 = 20.","run_id":"claude-code","at":"2026-10-22T13:01:58.579Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00cb8171-f563-4ec7-8fc4-fee8dcd49253', 'NC26.ASDS.CCD.3', 2, 'choice', 'Find and fix errors and outliers', 'A data set of player heights includes one very tall player of 231 centimeters, who was measured correctly. What should the analyst do with this value?', '["Keep it, since it is real, and note that it is unusual","Delete it, because every outlier must be removed","Change it to the mean so it matches the others","Keep it only if it makes the mean look larger"]', 'Keep it, since it is real, and note that it is unusual', NULL, 'An outlier that is a real, correct measurement belongs in the data. The analyst should keep it and mention that it is unusual.', 'checked', '{"lint":[],"solve":{"answer":"Keep it, since it is real, and note that it is unusual","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A real, correctly measured extreme value should be kept and noted.","run_id":"claude-code","at":"2026-10-22T19:37:54.958Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08bb7dd4-e6cc-4d3d-b8ba-d2a374f3b2b4', 'NC26.ASDS.CCD.3', 2, 'choice', 'Note data sources and limitations', 'A student finds a bar chart on a website that does not say who made it or where its data came from. What should she do before using it?', '["Use it, since a chart on a website must be right","Use it, but remove the title so nobody can ask about it","Use the chart only if it looks professional and neat","Look for the original source before using the chart"]', 'Look for the original source before using the chart', NULL, 'Without a source she cannot tell how reliable the data are. She should find the original source first, and not use the chart if she cannot.', 'checked', '{"lint":[],"solve":{"answer":"Look for the original source before using the chart","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Find the original source to judge reliability before use.","run_id":"claude-code","at":"2026-10-22T19:37:54.958Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('057e9b2e-a962-44b2-8f9c-e18d1ef294ac', 'NC26.ASDS.CCD.3', 3, 'numeric', 'Handle missing values', 'The mean of the 10 test scores in a table is 70. Two of the 10 scores are 0, typed in for students who were absent, so those two scores are really missing. What is the mean of the 8 real scores?', '[]', '87.5', '10*70/8', 'The 10 scores add up to $10 \times 70 = 700$. The two zeros add nothing, so the 8 real scores also add up to 700. Their mean is $700 \div 8 = 87.5$.', 'checked', '{"lint":[],"solve":{"answer":"87.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of 10 scores = 10 * 70 = 700. The two zeros add 0, so the 8 real scores sum to 700. Mean = 700/8 = 87.5.","run_id":"claude-code","at":"2026-10-22T13:01:58.579Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f6b210-99f9-4085-af37-1188969de76f', 'NC26.ASDS.CCD.3', 3, 'choice', 'Tell original from secondary data and combine sources', 'Table 1 lists each student''s student ID, name and grade. Table 2 lists each student''s student ID, name and club. The rows are not in the same order, and two different students are both named Jamie Cruz. Which column should be used to match the rows of the two tables?', '["Name, because both tables include it","First name, because it is short and easy to match","Row number, because both tables list the students","Student ID, because no two students share one"]', 'Student ID, because no two students share one', NULL, 'To match rows you need a column that identifies one student and no other. Names can repeat, as the two students called Jamie Cruz show. The rows are in different orders, so row numbers would match the wrong students. A student ID is different for each student.', 'checked', '{"lint":[],"solve":{"answer":"Student ID, because no two students share one","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Names are not unique (two Jamie Cruz), rows are in different orders, so match on the unique key, Student ID.","run_id":"claude-code","at":"2026-10-22T13:01:58.579Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02954a12-e97c-49eb-9ac1-009fdeaa76a0', 'NC26.ASDS.CCD.4', 1, 'choice', 'Informed consent', 'Which statement best describes informed consent in a research study?', '["A person agrees to take part, and the purpose is explained only after all the data have been collected.","A person is told the study is required for everyone, so there is no chance to say no and no explanation.","A person agrees to take part after being told what the study is for, what they will do and what the risks are.","A person signs a form whose pages are all blank, trusting the researcher to fill in the details later."]', 'A person agrees to take part after being told what the study is for, what they will do and what the risks are.', NULL, 'Informed consent means a person freely agrees after being told the purpose, what taking part involves and the risks. Agreeing before knowing these things, or having no choice, is not informed consent.', 'checked', '{"lint":[],"solve":{"answer":"A person agrees to take part after being told what the study is for, what they will do and what the risks are.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Informed consent means agreeing after being told the purpose, the tasks and the risks. A explains only afterwards, B is a blank form, D gives no choice and no explanation. Only C fits.","run_id":"claude-code","at":"2026-10-22T19:21:45.727Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('163b2147-b700-4a76-b5e6-78cc695acb11', 'NC26.ASDS.CCD.4', 1, 'numeric', 'Fair and representative data collection', 'A club has 60 members: 36 are juniors and 24 are seniors. A committee of 10 members is to reflect the club, with the same share of juniors as the club has. How many juniors should be on the committee?', '[]', '6', '10*36/60', 'Juniors are $\frac{36}{60} = \frac{3}{5}$ of the club. $\frac{3}{5}$ of 10 members is 6, so 6 juniors should be on the committee.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Juniors share = 36/60 = 0.6. 0.6 x 10 = 6 juniors.","run_id":"claude-code","at":"2026-10-22T19:21:45.727Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1488a2b4-db31-4049-8a7c-4ceb748bc1c3', 'NC26.ASDS.CCD.4', 1, 'numeric', 'The right to withdraw', 'The consent form for a quiz study promises that if a volunteer withdraws, all of their answers are deleted. Each volunteer answers 10 questions. Three volunteers each withdraw after answering 6 questions. How many answers are deleted in all?', '[]', '18', '3*6', 'Each of the 3 volunteers has 6 answers, so 3 x 6 = 18 answers are deleted.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All answers of each withdrawing volunteer are deleted: 3*6 = 18.","run_id":"claude-code","at":"2026-10-22T19:41:57.356Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d684fe5-60f0-43dd-9dcb-9f3506f10a39', 'NC26.ASDS.CCD.4', 2, 'choice', 'Fair and representative data collection', 'A city posts an online-only survey to learn how all of its residents feel about its public Wi-Fi. Which statement about this plan is true?', '["The plan is fair, because every resident has the same chance to answer the survey.","The plan is fair, because residents who skip the survey do not affect the results.","Residents without internet access cannot answer, so their views are left out.","The plan is fair as long as at least 100 residents take part in the survey."]', 'Residents without internet access cannot answer, so their views are left out.', NULL, 'An online-only survey cannot reach people who have no internet, and they may feel differently from those who do. Leaving them out is a fairness problem. The number of responses does not fix it.', 'checked', '{"lint":[],"solve":{"answer":"Residents without internet access cannot answer, so their views are left out.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An online-only survey excludes residents without internet access, so it is not representative of all residents. A, B, C are false claims of fairness. D.","run_id":"claude-code","at":"2026-10-22T19:21:45.727Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04414e9a-81a2-465a-a975-b7f781071b3f', 'NC26.ASDS.CCD.4', 2, 'choice', 'The right to withdraw', 'A volunteer in a three-week diet study withdraws in week 2 because of a health worry. The researcher would like complete data. Which response respects the volunteer''s rights?', '["Accept the withdrawal and stop collecting data from the volunteer.","Ask the volunteer to stay until week 3 so that the data are complete.","Keep collecting the volunteer''s data without telling them.","Tell the volunteer that leaving early will be noted in their school record."]', 'Accept the withdrawal and stop collecting data from the volunteer.', NULL, 'Participants may leave at any time, so the researcher must stop collecting data. Pressure, secrecy or threats violate the right to withdraw.', 'checked', '{"lint":[],"solve":{"answer":"Accept the withdrawal and stop collecting data from the volunteer.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The volunteer''s withdrawal must be accepted and data collection stopped.","run_id":"claude-code","at":"2026-10-22T19:41:57.356Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d0f83b6-cfbc-488e-b29e-4d45b6a59067', 'NC26.ASDS.CCD.4', 2, 'numeric', 'Justifying ethical collection choices', 'A researcher''s records for 2,400 participants may be kept for 3 years, as the consent form promised. 15% of the records are older than 3 years. How many records must be deleted?', '[]', '360', '2400*15/100', '15% of 2,400 is 360. These records are past the promised time and must be deleted.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15% of 2,400 = 360.","run_id":"claude-code","at":"2026-10-22T19:41:57.356Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13d7955a-38d1-4879-85ec-cb66aaefdfff', 'NC26.ASDS.CCD.4', 3, 'numeric', 'The right to withdraw', 'A study assigns 120 volunteers to a treatment group and 120 to a control group. In the treatment group 18 withdraw, and in the control group 6 withdraw. What percent of all 240 volunteers withdrew?', '[]', '10', '(18+6)/240*100', 'In total 18 + 6 = 24 volunteers withdrew. 24 out of 240 is 10%.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18+6 = 24 withdrew; 24/240 = 10%.","run_id":"claude-code","at":"2026-10-22T19:41:57.356Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08ef540b-ee2e-4ae6-bfe1-e625bb9cab75', 'NC26.ASDS.CCD.4', 3, 'choice', 'Fair and representative data collection', 'A survey of drivers has answers from 90% men, but drivers are about half men and half women. What is the most ethical way to report the results?', '["Report the results as if they describe all drivers equally.","Hide the gender breakdown so that readers do not question the sample.","Report only the answers from the women who replied.","State that men are over-represented and say who the results cover."]', 'State that men are over-represented and say who the results cover.', NULL, 'Honest reporting shows the sample''s limits. Hiding the imbalance or pretending it does not matter misleads readers.', 'checked', '{"lint":[],"solve":{"answer":"State that men are over-represented and say who the results cover.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ethical reporting discloses the over-representation of men and states who the results cover.","run_id":"claude-code","at":"2026-10-22T19:41:57.356Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ba6642b-83e4-4918-aff2-671766300964', 'NC26.ASDS.DV.1', 1, 'choice', 'Choose a display that fits the data and the purpose', 'A town''s population was recorded every year from 2010 to 2020. Which display best shows how the population changed over time?', '["A pie chart with one slice for each of the eleven years","A line graph with the years along the horizontal axis","A box plot made from the eleven population values","A histogram made from the eleven years"]', 'A line graph with the years along the horizontal axis', NULL, 'Data recorded over time are best shown with a line graph, because the line shows whether the values rise or fall from year to year. The other displays lose the order of the years.', 'checked', '{"lint":[],"solve":{"answer":"A line graph with the years along the horizontal axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change over time: line graph with years on the horizontal axis.","run_id":"claude-code","at":"2026-10-22T12:51:22.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0edcbff7-ed14-4abb-8019-c5379b00fbab', 'NC26.ASDS.DV.1', 1, 'choice', 'Find patterns in multivariate data', 'The points in a scatterplot are scattered all over with no pattern. Which correlation is most likely?', '["r = 0.95","r = 0.05","r = -0.95","r = 1.5"]', 'r = 0.05', NULL, 'No pattern means a correlation close to 0. The value 1.5 is impossible, because r is always between -1 and 1.', 'checked', '{"lint":[],"solve":{"answer":"r = 0.05","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No pattern: r near 0, i.e. 0.05 (1.5 is impossible).","run_id":"claude-code","at":"2026-10-22T19:41:57.397Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11174d94-1ec5-4326-abe7-6b8115ef7fdb', 'NC26.ASDS.DV.1', 1, 'numeric', 'Build and label a display with technology', 'A data table has 12 rows (people) and 5 columns (variables). A scatterplot uses 2 of the columns. How many columns are not shown in the scatterplot?', '[]', '3', '5-2', '5 - 2 = 3 columns are left out.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 2 = 3 columns.","run_id":"claude-code","at":"2026-10-22T19:41:57.397Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06dd5251-ba38-4a9c-b621-7d9e05f79187', 'NC26.ASDS.DV.1', 2, 'choice', 'Compare distributions', 'Group 1 has mean 48, median 48 and standard deviation 5. Group 2 has mean 55, median 40 and standard deviation 25. Which statement is best supported by these numbers?', '["Group 2 is less variable than group 1, because its mean is larger.","Group 1 is more variable than group 2, because its standard deviation is smaller.","Group 2 is probably skewed right, because its mean is far above its median.","Group 1 must be skewed, because its mean and its median are equal."]', 'Group 2 is probably skewed right, because its mean is far above its median.', NULL, 'When the mean is far above the median, a few high values are pulling the mean up, which is the sign of a right-skewed distribution. A larger standard deviation means more variability, so group 2 varies more. A mean equal to the median suggests symmetry.', 'checked', '{"lint":[],"solve":{"answer":"Group 2 is probably skewed right, because its mean is far above its median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group 2''s mean (55) is well above its median (40) with a large SD: likely right skew. A and B confuse variability with mean or invert SD; C is false (equal mean and median suggests symmetry).","run_id":"claude-code","at":"2026-10-22T12:51:22.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00599c6d-5a61-4610-a662-14722ad283f0', 'NC26.ASDS.DV.1', 2, 'numeric', 'Build and label a display with technology', 'A tool counts 40 values into four groups: 6, 14, 12 and 8. A pie chart is drawn from these counts. What angle, in degrees, should the slice for the group of 14 have?', '[]', '126', '14/40*360', 'The group of 14 is 14 / 40 of all the values, and the full circle is 360 degrees, so the angle is 14 / 40 x 360 = 126 degrees.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 6+14+12+8 = 40. 14/40 x 360 = 126 degrees.","run_id":"claude-code","at":"2026-10-22T12:51:22.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f6a2c05-2a03-418d-bad1-980fe011383d', 'NC26.ASDS.DV.1', 2, 'choice', 'Find patterns in multivariate data', 'A scatterplot of the weights and heights of 100 animals shows two clearly separate groups of points. What is the most likely explanation?', '["The data contain mistakes, so all the points must be deleted.","The data probably include two different kinds of animals.","Weight and height are not related at all.","The sample was too large to be useful."]', 'The data probably include two different kinds of animals.', NULL, 'Separate clusters often mean different subgroups mixed in the same data. The kind of animal is another variable that helps explain the pattern.', 'checked', '{"lint":[],"solve":{"answer":"The data probably include two different kinds of animals.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two clusters suggest two kinds of animals.","run_id":"claude-code","at":"2026-10-22T19:41:57.397Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e088927-a323-4788-a3c4-64ce37fdfd00', 'NC26.ASDS.DV.1', 3, 'choice', 'Choose a display that fits the data and the purpose', 'For 100 homes, an agent has the size in square feet, the price, and the number of bedrooms (2, 3 or 4). She wants one display that shows how price relates to size and whether the number of bedrooms matters. Which display fits best?', '["A scatterplot of price against size, with points colored by bedrooms","A scatterplot of price against size that does not use the number of bedrooms","Three separate pie charts, one for each of the three variables","A histogram of the number of bedrooms for the 100 homes"]', 'A scatterplot of price against size, with points colored by bedrooms', NULL, 'A scatterplot shows price against size, and coloring the points by bedrooms adds the third variable to the same display. The other choices drop a variable or do not show the relationship.', 'checked', '{"lint":[],"solve":{"answer":"A scatterplot of price against size, with points colored by bedrooms","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Price vs size is a scatterplot; colouring points by bedrooms adds the third (categorical) variable in one display.","run_id":"claude-code","at":"2026-10-22T12:51:22.288Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('149d9b5d-5e60-43a4-99db-0e68547d1cfd', 'NC26.ASDS.DV.1', 3, 'choice', 'Compare distributions', 'In group 1, 45 of 120 people said yes. In group 2, 50 of 200 people said yes. Which group has the higher share of yes answers?', '["Group 2, because 50 is greater than 45","Group 2, with 25% compared with 37.5%","Group 1, with 37.5% compared with 25%","The groups are equal, because both are about one third"]', 'Group 1, with 37.5% compared with 25%', NULL, 'Compare shares, not counts. Group 1: 45/120 = 37.5%. Group 2: 50/200 = 25%. Group 1 is higher even though its count is smaller.', 'checked', '{"lint":[],"solve":{"answer":"Group 1, with 37.5% compared with 25%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45/120 = 37.5%, 50/200 = 25%: group 1 higher.","run_id":"claude-code","at":"2026-10-22T19:41:57.397Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c96cf1d-ce91-4589-bcfb-328ab5c58901', 'NC26.ASDS.DV.2', 1, 'numeric', 'Bar chart axis that does not start at zero', 'A bar chart has a vertical axis that starts at 0. Store P sold 30 bikes and Store Q sold 60 bikes. The bar for Store Q is how many times as tall as the bar for Store P?', '[]', '2', '60/30', 'When the axis starts at 0, a bar''s height is proportional to its value. Store Q''s bar is $60 \div 30 = 2$ times as tall as Store P''s bar.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Axis starts at 0, so heights are proportional: 60/30 = 2.","run_id":"claude-code","at":"2026-10-22T19:45:50.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10e2d387-1aea-4234-9f36-bb4b3579e4c6', 'NC26.ASDS.DV.2', 1, 'choice', 'Bar chart axis that does not start at zero', 'Two classes have mean scores of 91 and 93. A bar chart of the two means has a vertical axis that runs from 90 to 94. What impression does the chart give?', '["The two bars look almost exactly the same height","The bar for 91 looks taller than the bar for 93","The bar for 93 looks 3 times as tall as the bar for 91","The bar for 93 looks only a little taller than the bar for 91"]', 'The bar for 93 looks 3 times as tall as the bar for 91', NULL, 'Measured from the axis start of 90, the bars are 1 and 3 units tall. The bar for 93 looks 3 times as tall, although the scores differ by only about 2 percent.', 'checked', '{"lint":[],"solve":{"answer":"The bar for 93 looks 3 times as tall as the bar for 91","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights from 90: 91 -> 1 unit, 93 -> 3 units, so the 93 bar looks 3 times as tall.","run_id":"claude-code","at":"2026-10-22T19:45:50.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15a5f5fa-027b-4272-b763-f6634c7de2e8', 'NC26.ASDS.DV.2', 1, 'choice', 'What averages, bins and aggregation hide', 'A bar chart shows the mean salary of each department in a company. What does it hide?', '["Which department has the highest mean salary in the company","How many departments the company has","The names of the departments","How much the salaries vary inside each department"]', 'How much the salaries vary inside each department', NULL, 'A mean is one number for a whole group. The chart cannot show whether the salaries in a department are all alike or very spread out.', 'checked', '{"lint":[],"solve":{"answer":"How much the salaries vary inside each department","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A mean per department hides the spread within each department.","run_id":"claude-code","at":"2026-10-22T19:45:50.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09abf99b-0f40-4544-9d04-035ccc60a9c3', 'NC26.ASDS.DV.2', 2, 'numeric', 'Axis range and shape of a line graph', 'A line graph is 8 centimeters tall and its vertical axis runs from 0 to 400. A line on it rises from the value 100 to the value 300. How many centimeters tall does that rise look on the graph?', '[]', '4', '(300-100)/400*8', 'The rise is $300 - 100 = 200$ units, which is $\frac{200}{400}$ of the axis. That is $\frac{200}{400} \times 8 = 4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rise of 200 on a 400-unit, 8 cm axis: 200/400 x 8 = 4 cm.","run_id":"claude-code","at":"2026-10-22T19:45:50.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f8e8577-4da1-4322-bc66-8a98b4a31844', 'NC26.ASDS.DV.2', 2, 'choice', 'Order of categories', 'A bar chart shows how many students earned each letter grade: A, B, C, D and F. Which order of the bars is best?', '["The order from the most students to the fewest students","The order from the fewest students to the most","A, B, C, D, F, the order of the grades themselves","A random order chosen by the designer"]', 'A, B, C, D, F, the order of the grades themselves', NULL, 'Grades are ordered categories, so the bars should follow the grade order. Then the shape of the grade distribution can be seen.', 'checked', '{"lint":[],"solve":{"answer":"A, B, C, D, F, the order of the grades themselves","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grades are ordinal: keep A, B, C, D, F.","run_id":"claude-code","at":"2026-10-22T19:45:50.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('299c7ccf-cb00-45f8-8539-c0ee3d4ad8d1', 'NC26.ASDS.DV.2', 2, 'choice', 'Color and accessibility', 'A report is likely to be printed in black and white. It has a line graph with four lines that differ only in color. Which revision helps most?', '["Add line patterns, such as dashes, and labels","Use four brighter colors for all four of the lines","Make all the lines much thinner than now","Put a darker background behind the lines"]', 'Add line patterns, such as dashes, and labels', NULL, 'Different colors can turn into the same gray when printed. Patterns and labels still work in black and white.', 'checked', '{"lint":[],"solve":{"answer":"Add line patterns, such as dashes, and labels","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In greyscale colours are lost; dashes and labels survive.","run_id":"claude-code","at":"2026-10-22T19:45:50.540Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('005b31ca-09c6-4799-919f-27b7dd83365e', 'NC26.ASDS.DV.2', 3, 'choice', 'Order of categories', 'A stacked bar chart splits each of 6 bars into four colored segments. A reader wants to compare one segment''s size across all the bars. Which segment is easiest to compare?', '["The segment in the middle, because it is surrounded by two other segments","The bottom segment, because all of them start at the same baseline","The segment at the top, because it is the last one drawn on each bar","All the segments are equally easy to compare"]', 'The bottom segment, because all of them start at the same baseline', NULL, 'Only the bottom segment starts at the common baseline, so its lengths can be compared directly. The other segments start at different heights, which makes comparison harder.', 'checked', '{"lint":[],"solve":{"answer":"The bottom segment, because all of them start at the same baseline","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only the bottom segments share a common baseline.","run_id":"claude-code","at":"2026-10-22T19:45:50.540Z"}}', 'ai', NULL, NULL)
