INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088db34d-f96b-440b-8b0e-7cc433092145', 'NC26.M1.RMM.1', 1, 'choice', 'Build a model from a situation or data', 'A pottery studio charges 30 dollars to register plus 12 dollars for each class. Which equation gives the total cost $C$ after $n$ classes?', '["$C = 12 + 30n$","$C = 42n$","$C = 30 + 12n$","$C = 30n + 12$"]', '$C = 30 + 12n$', NULL, 'The 30 dollar registration is paid once. The 12 dollar fee is paid for each of the $n$ classes, so the total is $30 + 12n$.', 'checked', '{"lint":[],"solve":{"answer":"$C = 30 + 12n$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fixed 30 plus 12 per class: C = 30 + 12n.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05edecb1-7dbd-4862-872b-6542b614e545', 'NC26.M1.RMM.1', 1, 'choice', 'Choose the model that fits the data', 'At $x = 0, 1, 2, 3$ the values of $y$ are 5, 7, 9, 11. Which model fits all four values?', '["$y = 5 \\times 2^x$","$y = 5x + 2$","$y = 5 + 2x$","$y = 7x - 2$"]', '$y = 5 + 2x$', NULL, 'The value goes up by 2 each time, starting at 5, so $y = 5 + 2x$. Check $x = 3$: $5 + 6 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5 + 2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 5, +2 each step: y = 5 + 2x. Check 5x+2: 2 at x=0 no; 7x-2: -2 no; 5*2^x: 5,10 no.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30eacbca-0b1d-4a41-86a1-c5d741dead98', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'A model for a trip says the time is $t = \frac{d}{50}$ hours for a distance of $d$ miles. Which real-world factor does this model ignore?', '["The total length of the trip in miles, which the model uses","The assumed speed of 50 miles per hour on the whole trip","Traffic and stops that slow the average speed","The units of the distance"]', 'Traffic and stops that slow the average speed', NULL, 'The model assumes a steady 50 miles per hour, so it ignores anything that changes the speed, such as traffic and stops.', 'checked', '{"lint":[],"solve":{"answer":"Traffic and stops that slow the average speed","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d/50 assumes constant 50 mph; ignores traffic and stops. Other options are things the model uses.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d6d0e58-48a7-496d-9a7b-75169ea52785', 'NC26.M1.RMM.1', 2, 'numeric', 'Explain what a model''s parts mean', 'In the model $N = 250(1.06)^t$, $N$ is the number of members after $t$ years. By what percent does the membership grow each year?', '[]', '6', '6', 'The factor 1.06 means 100% of last year plus 6% more, so the membership grows 6% each year.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.06 -> 6% growth.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f2592f1-b82b-4b1b-b27d-19445d487411', 'NC26.M1.RMM.1', 2, 'choice', 'Choose the model that fits the data', 'At $x = 0, 1, 2, 3$ the values of $y$ are 0, 5, 8, 9. Which model fits all four values?', '["$y = 5x$","$y = x^2 + 4x$","$y = 5 \\times 2^x - 5$","$y = -x^2 + 6x$"]', '$y = -x^2 + 6x$', NULL, 'The differences 5, 3, 1 drop by 2 each time, which suggests a quadratic with $-x^2$. Check: $-1 + 6 = 5$, $-4 + 12 = 8$, $-9 + 18 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$y = -x^2 + 6x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-x^2 + 6x: 0, 5, 8, 9. Check x^2+4x: 12 at x=2; 5x: 10; 5*2^x - 5: 15.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a0c1101-26e0-45c7-ba83-21d1c12751f8', 'NC26.M1.RMM.1', 3, 'numeric', 'Build a model from a situation or data', 'A kayak rental costs 22 dollars for 2 hours and 34 dollars for 4 hours, and the cost is linear in the number of hours. What would 7 hours cost, in dollars?', '[]', '52', '22+6*(7-2)', 'The cost rises $34 - 22 = 12$ dollars for 2 extra hours, so 6 dollars per hour. From 2 to 7 hours is 5 more hours: $22 + 6 \times 5 = 52$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (34 - 22)/2 = 6; intercept 22 - 12 = 10; 10 + 6(7) = 52.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b462674-f0d3-4937-b59a-f2b2a6de9395', 'NC26.M1.RMM.1', 3, 'numeric', 'Analyse a model to predict or solve', 'Pool A holds 400 liters and fills at 30 liters a minute. Pool B holds 700 liters and drains at 20 liters a minute. After how many minutes do the two pools hold the same amount?', '[]', '6', '(700-400)/(30+20)', 'Set $400 + 30m = 700 - 20m$. Then $50m = 300$, so $m = 6$. Both pools then hold 580 liters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"400 + 30t = 700 - 20t -> 50t = 300 -> t = 6 (both 580).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe2c67b-3982-455a-a975-adb67cae1792', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply powers with the same base', 'Simplify $x^3 \cdot x^4$.', '["$x^7$","$x^{12}$","$2x^7$","$x^{-1}$"]', '$x^7$', NULL, 'When you multiply powers with the same base, add the exponents: $x^3 \cdot x^4 = x^{3+4} = x^7$.', 'checked', '{"lint":[],"solve":{"answer":"$x^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base, add exponents: x^(3+4) = x^7.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07ae5de0-31ef-49f0-af8b-71093c795f26', 'NC26.M1.ANFR.1', 1, 'choice', 'Add polynomials', 'Add: $(2x + 5) + (4x + 3)$.', '["$6x + 8$","$6x^{2} + 8$","$6x + 15$","$14x$"]', '$6x + 8$', NULL, 'Add the $x$ terms: $2x + 4x = 6x$. Add the constants: $5 + 3 = 8$. The sum is $6x + 8$. The $x$ terms and the constants are different kinds of terms, so they stay separate.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x + 4x) + (5 + 3) = 6x + 8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3106cd-e717-455b-882d-6ef6a1475f84', 'NC26.M1.ANFR.1', 1, 'numeric', 'Rewrite an expression in an equivalent form', 'The expression $5(x + 2) - 3x$ is equivalent to $2x + k$. What is $k$?', '[]', '10', '5*2', 'Distribute the 5: $5x + 10 - 3x$. Combine the $x$ terms: $5x - 3x = 2x$. So the expression is $2x + 10$ and $k = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 10 - 3x = 2x + 10, k = 10.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('013027b5-a920-4892-b9d9-aea9aa5a9756', 'NC26.M1.ANFR.1', 2, 'choice', 'Raise a product or quotient to a power', 'Simplify $(-2a^{3}b^{2})^{4}$.', '["$-8a^{12}b^{8}$","$16a^{7}b^{6}$","$16a^{12}b^{8}$","$-16a^{12}b^{8}$"]', '$16a^{12}b^{8}$', NULL, 'Raise each factor to the 4th power. $(-2)^{4} = 16$, because an even power of a negative number is positive. $(a^{3})^{4} = a^{12}$ and $(b^{2})^{4} = b^{8}$. The result is $16a^{12}b^{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$16a^{12}b^{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2)^4 = 16; (a^3)^4 = a^12; (b^2)^4 = b^8. Result 16a^12b^8 (even power makes it positive).","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13c6fd86-287d-4e36-aaf7-c52e4a2e2163', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply a monomial by a polynomial', 'Multiply: $-2x(3x^{2} - 4x + 5)$.', '["$-6x^{3} - 8x^{2} - 10x$","$-6x^{3} + 8x^{2} - 10x$","$-6x^{2} + 8x - 10$","$-6x^{3} + 8x^{2} - 10$"]', '$-6x^{3} + 8x^{2} - 10x$', NULL, 'Multiply $-2x$ by each term: $-2x \cdot 3x^{2} = -6x^{3}$; $-2x \cdot (-4x) = 8x^{2}$; $-2x \cdot 5 = -10x$. The result is $-6x^{3} + 8x^{2} - 10x$.', 'checked', '{"lint":[],"solve":{"answer":"$-6x^{3} + 8x^{2} - 10x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x*3x^2 = -6x^3; -2x*(-4x) = 8x^2; -2x*5 = -10x. Result -6x^3 + 8x^2 - 10x.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
