VALUES ('13556fbf-781b-445d-ba75-7a4c384e75c6', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve a linear inequality in one variable', 'Solve the inequality $x + 5 > 12$.', '["$x < 7$","$x > 17$","$x > -7$","$x > 7$"]', '$x > 7$', NULL, 'Subtract 5 from both sides: $x > 7$.', 'checked', '{"lint":[],"solve":{"answer":"$x > 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 5 > 12 -> x > 7.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
