INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f72229-bb6b-4fe0-9751-158713cd2558', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve an exponential equation with a table or by reasoning', 'Which value of $x$ makes $3^x = 81$ true?', '["4","27","3","9"]', '4', '4', '$3^1 = 3$, $3^2 = 9$, $3^3 = 27$, $3^4 = 81$. So $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^4 = 81 -> x = 4.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
