INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bd64c52-0611-4333-a967-cf21df064e50', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a formula for a quantity', 'The simple interest formula is $I = Prt$. A loan of 600 dollars earned 90 dollars in interest over 3 years. What is the yearly rate $r$, written as a decimal?', '[]', '0.05', '90/(600*3)', 'Solve for $r$: $r = \frac{I}{Pt} = \frac{90}{600 \cdot 3} = \frac{90}{1800} = 0.05$.', 'checked', '{"lint":[],"solve":{"answer":"0.05","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"I = Prt -> r = I/(Pt) = 90/(600*3) = 90/1800 = 0.05.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
