INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fb05779-cb77-4442-865b-682c513e85d6', 'NC26.M1.ANFR.6', 1, 'choice', 'Test a point in a linear inequality', 'Which ordered pair is a solution of $2x + y < 7$?', '["$(3, 2)$","$(2, 3)$","$(4, 0)$","$(1, 3)$"]', '$(1, 3)$', NULL, 'Substitute each pair. For $(1, 3)$: $2(1) + 3 = 5$, and $5 < 7$ is true. For $(3, 2)$ the value is 8, for $(2, 3)$ it is 7 (not less than 7), and for $(4, 0)$ it is 8. Only $(1, 3)$ works.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3): 7 < 7 no. (3,2): 8 no. (1,3): 5 < 7 yes. (4,0): 8 no.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be98430-d144-4f08-b852-5ebe41c3f66b', 'NC26.M1.ANFR.6', 1, 'choice', 'Intercepts of the boundary line', 'What is the $y$-intercept of the boundary line of $y > 2x + 7$?', '["$(7, 0)$","$(0, 2)$","$(0, -7)$","$(0, 7)$"]', '$(0, 7)$', NULL, 'The boundary line is $y = 2x + 7$. At $x = 0$, $y = 7$, so the line crosses the $y$-axis at $(0, 7)$.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 2x + 7 crosses the y-axis at (0, 7).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
