INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06a6c872-8639-4a32-8edb-4d912398c37b', 'NC26.M1.SDSR.5', 3, 'choice', 'Outliers and influential points', 'Removing point A changes the slope of a line from 2.0 to 1.9. Removing point B changes the slope from 2.0 to 0.4. Which statement is best?', '["Point A is much more influential on the line than point B is","Point B is much more influential on the line than point A","Both points are equally influential on the line as a whole","Neither of the two points has any influence on the line at all"]', 'Point B is much more influential on the line than point A', NULL, 'The slope hardly changes without A but changes a great deal without B, so B has the greater influence.', 'checked', '{"lint":[],"solve":{"answer":"Point B is much more influential on the line than point A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B changes slope by 1.6 vs 0.1: B much more influential.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01bf72af-b1b7-4101-bd06-ad420ff47fa2', 'NC26.M1.SDSR.5', 3, 'numeric', 'Making and judging predictions', 'A phone''s value is modeled by $V = 800(0.75)^t$ dollars after $t$ years. How many dollars of value does the model say the phone loses in its first 2 years?', '[]', '350', '800-800*0.75^2', '$(0.75)^2 = 0.5625$, so $V = 800 \times 0.5625 = 450$ after 2 years. The loss is 800 - 450 = 350 dollars.', 'checked', '{"lint":[],"solve":{"answer":"350","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"800(0.75)^2=800(0.5625)=450; 800-450=350.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08a331d8-b776-4cf1-a173-01ae00b0af2c', 'NC26.M1.SDSR.6', 1, 'choice', 'Reporting a conclusion accurately', 'In a random sample of 100 students, 60 said they prefer online homework. Which statement reports this accurately?', '["60 percent of all students everywhere prefer online homework","Online homework is better for learning","Exactly 60 percent of the students in the school prefer online homework","In the sample, 60 percent of the students prefer online homework"]', 'In the sample, 60 percent of the students prefer online homework', NULL, 'The data tell us what happened in the sample: 60 of 100 students prefer online homework. They do not show that online homework is better for learning, and a sample cannot tell us the exact percent for everyone.', 'checked', '{"lint":[],"solve":{"answer":"In the sample, 60 percent of the students prefer online homework","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60/100 = 60 percent of the sample. The other options over-generalize, claim exactness for the school, or claim causation.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a512656-e22c-41f5-a771-398757794e19', 'NC26.M1.SDSR.6', 1, 'choice', 'Critiquing a percent claim in the media', 'A poster says, "Our class improved 200 percent!" Which question should you ask first to judge the claim?', '["What day of the week was the poster put up in the hallway, and who made it?","What is the favorite subject of the students in the class, and of their teacher?","How many days long is the school year at the school that made the poster?","What was the starting score, and how many students are in the class that made the poster?"]', 'What was the starting score, and how many students are in the class that made the poster?', NULL, 'A percent change depends on the starting amount. A rise from 1 point to 3 points is 200 percent, but it is still a tiny score. The starting score and the size of the class show how much the claim means.', 'checked', '{"lint":[],"solve":{"answer":"What was the starting score, and how many students are in the class that made the poster?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: the second half (class size) is less relevant than the starting score, but the option is still clearly the best.","work":"A percent increase depends on the base: 200% of a tiny starting score could be small. Need the starting score. Only option addressing this.","run_id":"claude-code","at":"2026-10-18T03:35:29.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0792f026-b742-48c7-be45-377f20897f7a', 'NC26.M1.SDSR.6', 1, 'choice', 'Critiquing a claim in the media', 'A report says, "Our test scores went up every year." The average scores were 70 in 2021, 74 in 2022, 73 in 2023 and 78 in 2024. Which statement about the claim is correct?', '["It is supported, because the score in 2024 is higher than the score in 2021","It is not supported, because the average fell from 74 in 2022 to 73 in 2023","It is supported, because the scores rose in two of the three yearly changes","It cannot be judged, because averages never show how any one student did"]', 'It is not supported, because the average fell from 74 in 2022 to 73 in 2023', NULL, 'To go up every year, each score must be higher than the one before. The score fell from 74 to 73 between 2022 and 2023, so the claim is not supported even though the last score is the highest.', 'checked', '{"lint":[],"solve":{"answer":"It is not supported, because the average fell from 74 in 2022 to 73 in 2023","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Changes: 70->74 up, 74->73 down, 73->78 up. ''Every year'' fails because of the 2022-2023 drop. Option D.","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06137c33-b870-49c6-a39d-3c4279714947', 'NC26.M1.SDSR.6', 2, 'choice', 'Critiquing a percent claim in the media', 'An ad says, "Our running shoes cut injuries by 50 percent!" In the test, 2 of 40 runners in the new shoes were injured, and 4 of 40 runners in the old shoes were injured. What is the best critique?', '["The groups were so small that a difference of 2 injuries could easily happen by chance","The ad is wrong, because injuries went down by only 2 percent","Injuries cannot be compared unless each group has exactly 100 runners","The ad should say 100 percent instead, since the new shoes had fewer injuries than the old shoes did"]', 'The groups were so small that a difference of 2 injuries could easily happen by chance', NULL, 'Going from 4 injuries to 2 is a 50 percent drop, so the arithmetic is right. But a difference of just 2 injuries in groups of 40 could happen by chance, so the test is too small to be convincing.', 'checked', '{"lint":[],"solve":{"answer":"The groups were so small that a difference of 2 injuries could easily happen by chance","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Injury rates 4/40=10% vs 2/40=5%: relative cut 50% (ad''s arithmetic is right), absolute 5 points. But the difference is only 2 injuries in small groups, easily due to chance. B is wrong (5 points, not 2).","run_id":"claude-code","at":"2026-10-18T03:35:29.491Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1257f299-978e-430d-99f6-90e7b2e71019', 'NC26.M1.SDSR.6', 2, 'choice', 'Choosing a summary or display', 'A report on the prices of 40 homes uses the median to describe the center, because a few very expensive homes pull the mean up. Which measure of spread should the report pair with the median?', '["The standard deviation","The interquartile range","The mean","The mode"]', 'The interquartile range', NULL, 'The median is paired with the interquartile range, which is not pulled by a few extreme values. The standard deviation is paired with the mean. The mean and the mode are measures of center, not of spread.', 'checked', '{"lint":[],"solve":{"answer":"The interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With a skewed distribution and the median as center, the resistant measure of spread is the interquartile range. Standard deviation pairs with the mean; mode and mean are not spreads.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15fdae87-1d99-4c61-9290-108e99e7b186', 'NC26.M1.SDSR.6', 2, 'choice', 'Critiquing an average in the media', 'A tutor writes, "Students here average 40 minutes of homework a night." The tutor''s data are 20, 25, 30, 35 and 90 minutes. Which statement about the claim is best?', '["The mean is 40, but four of the five students do less than 40 minutes, so 40 is not typical.","The mean is not 40, because adding the times and dividing by 5 gives 30.","The claim is fair because most of the students do 40 minutes or more.","The claim is fair because a mean always describes a typical student."]', 'The mean is 40, but four of the five students do less than 40 minutes, so 40 is not typical.', NULL, 'The sum is 20 + 25 + 30 + 35 + 90 = 200, and 200 divided by 5 is 40, so the mean is 40. But the 90 pulls the mean up: four of the five students do less than 40 minutes, and the median is 30. The report should say so.', 'checked', '{"lint":[],"solve":{"answer":"The mean is 40, but four of the five students do less than 40 minutes, so 40 is not typical.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 20+25+30+35+90 = 200; 200/5 = 40, so the mean is 40. Four of five values are below 40; the 90 outlier pulls the mean up, so 40 is not typical (median 30).","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe0a7f0-a908-4bf0-9e24-10298e58883c', 'NC26.M1.SDSR.6', 3, 'numeric', 'Critiquing a percent claim in the media', 'A store raised the price of a game by 20 percent, then advertised a 20 percent price cut, saying prices are "back where they started." The original price was 50 dollars. What is the price after the cut, in dollars?', '[]', '48', '50*(120/100)*(80/100)', 'After the 20 percent rise the price is $50 \times 1.2 = 60$ dollars. A 20 percent cut of 60 dollars takes off 12 dollars, leaving 48 dollars. It is not back to 50 dollars, because the 20 percent was taken from a larger amount.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 x 1.2 = 60; 60 x 0.8 = 48 dollars, not back to 50.","run_id":"claude-code","at":"2026-10-18T01:10:01.037Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0db967ef-3c8a-4ee5-ab22-1a771f7e04e0', 'NC26.M1.SDSR.6', 3, 'numeric', 'Applying a sample result to a population', 'To estimate the number of fish in a pond, 40 fish were caught, tagged and released. Later a sample of 50 fish was caught, and 5 of them had tags. If the sample is typical of the pond, about how many fish are in the pond?', '[]', '400', '40/(5/50)', 'In the sample, $5 \div 50 = 0.1$, so about 10 percent of the fish are tagged. The 40 tagged fish are about 10 percent of the pond, so the pond holds about $40 \div 0.1 = 400$ fish.', 'checked', '{"lint":[],"solve":{"answer":"400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Capture-recapture: 5/50 = 40/N, so N = 40 x 10 = 400.","run_id":"claude-code","at":"2026-10-18T01:10:01.037Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3be8da3b-62a3-4aef-88cf-681872bcbf86', 'NC26.M2.RMM.1', 1, 'choice', 'Order of the modeling cycle', 'A team has stated its problem and listed the quantities and assumptions it will use. According to the modeling cycle, what should the team do next?', '["Announce the final answer and stop working on the whole problem","Compare the model''s predictions with real data","Build a model, such as an equation, from those quantities","Revise the model because it did not fit the data"]', 'Build a model, such as an equation, from those quantities', NULL, 'The modeling cycle runs: state the problem, name the quantities and assumptions, build a model, use the model, test it against data, then revise and explain. The team has finished the first two steps, so the next step is to build a model.', 'checked', '{"lint":[],"solve":{"answer":"Build a model, such as an equation, from those quantities","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Modeling cycle: identify the problem, name quantities and assumptions (formulate), then build/compute a model, then interpret, validate against data, revise. Having stated the problem and listed quantities and assumptions, the next step is to build a model from them. Announcing the answer skips steps; revising and comparing with data come after a model exists.","run_id":"claude-code","at":"2026-10-22T12:51:46.468Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b816edf-dfd5-49dd-9b0e-ad0df7c889de', 'NC26.M2.RMM.1', 1, 'choice', 'Identify the problem to be modeled', 'Which question can be answered by building a mathematical model?', '["Which season of the year is the most fun for most of the people who live in our town?","Which song should the whole class sing at the graduation ceremony at the end of the year?","What is the nicest name for a new puppy that has just joined a family with two children?","How many 2-pound bags of seed are needed for a field that needs 18 pounds of seed?"]', 'How many 2-pound bags of seed are needed for a field that needs 18 pounds of seed?', NULL, 'Only the seed question is about quantities that can be measured and related with math (bags, pounds and the field). The others are matters of taste.', 'checked', '{"lint":[],"solve":{"answer":"How many 2-pound bags of seed are needed for a field that needs 18 pounds of seed?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/2 = 9 bags: quantitative. Others are taste/opinion. B.","run_id":"claude-code","at":"2026-10-23T00:17:54.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ca2a322-84e8-4e00-bd0f-cbb268a0297d', 'NC26.M2.RMM.1', 1, 'choice', 'Explain and critique a model', 'A model for a savings jar is $S = 12 + 3w$, where $S$ is the number of dollars in the jar after $w$ weeks. What does the 12 mean?', '["The jar gains 12 dollars each week","The jar holds 12 dollars after 3 weeks","The jar will be full after 12 weeks","The jar holds 12 dollars at the start"]', 'The jar holds 12 dollars at the start', NULL, 'When $w = 0$, $S = 12$, so 12 dollars is the starting amount. The 3 is the amount added each week.', 'checked', '{"lint":[],"solve":{"answer":"The jar holds 12 dollars at the start","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At w = 0, S = 12: starting amount.","run_id":"claude-code","at":"2026-10-22T19:33:44.569Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07d2bac7-fbcf-489e-aed1-b01b247b2a1d', 'NC26.M2.RMM.1', 2, 'numeric', 'Analyze a model', 'The height, in feet, of a ball thrown upward is modeled by $h = -16t^2 + 48t + 4$, where $t$ is the time in seconds after the throw. What height does the model give at $t = 2$ seconds?', '[]', '36', '-16*2^2+48*2+4', 'Put $t = 2$ into the model: $h = -16(2)^2 + 48(2) + 4 = -64 + 96 + 4 = 36$. The model gives a height of 36 feet.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(2) = -16(4) + 48(2) + 4 = -64 + 96 + 4 = 36 feet.","run_id":"claude-code","at":"2026-10-22T12:51:46.468Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('124aab9a-576c-423d-a0db-620a384ecc16', 'NC26.M2.RMM.1', 2, 'choice', 'Order of the modeling cycle', 'Which step must be finished before a team can write an equation for its model?', '["Testing the model against new data","Revising the model after finding a mismatch","Explaining the finished model to the class","Naming the quantities and assumptions"]', 'Naming the quantities and assumptions', NULL, 'An equation is built from the quantities and assumptions. Testing, revising and explaining all come after a model exists.', 'checked', '{"lint":[],"solve":{"answer":"Naming the quantities and assumptions","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before formulating an equation, the quantities and assumptions must be named. C.","run_id":"claude-code","at":"2026-10-23T00:17:54.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('133ff40c-6871-4c98-8aba-02f606823e60', 'NC26.M2.RMM.1', 2, 'choice', 'Build a model', 'A savings account holds 800 dollars and earns 3 percent interest each year, added at the end of the year. Which function models the amount $A$, in dollars, after $t$ years?', '["$A = 800 + 0.03t$","$A = 800 \\times 0.03^t$","$A = 800 \\times 3^t$","$A = 800 \\times 1.03^t$"]', '$A = 800 \times 1.03^t$', NULL, 'Each year the amount is multiplied by 1.03, so after $t$ years it is $800 \times 1.03^t$.', 'checked', '{"lint":[],"solve":{"answer":"$A = 800 \\times 1.03^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth factor 1.03 per year: A = 800 x 1.03^t.","run_id":"claude-code","at":"2026-10-22T19:33:44.569Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cc036b1-d1d9-4beb-b3d5-909caafbb9b9', 'NC26.M2.RMM.1', 3, 'numeric', 'Analyze a model', 'A store models its daily revenue, in dollars, from selling a toy at a price of $p$ dollars by $R = p(60 - 2p)$. According to the model, what price, in dollars, gives the greatest revenue?', '[]', '15', '60/(2*2)', 'Expand: $R = 60p - 2p^2$. This is a parabola that opens downward, so its greatest value is at the vertex, $p = \frac{60}{2 \times 2} = 15$. A price of 15 dollars gives the greatest revenue (450 dollars).', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R = 60p - 2p^2, a downward parabola with zeros p = 0 and p = 30; vertex at p = 15. R(15) = 15 x 30 = 450 dollars, the maximum.","run_id":"claude-code","at":"2026-10-22T12:51:46.468Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04a9d8ad-9c9a-43e7-8b6c-9efb9004bcd8', 'NC26.M2.RMM.1', 3, 'choice', 'Identify the problem to be modeled', 'A team''s notes say: (1) Each cabin holds 6 campers. (2) Find how many cabins are needed for 70 campers. (3) Campers do not share bunks with other cabins. Which sentence states the problem itself, rather than a given quantity or an assumption?', '["Each cabin holds 6 campers","Campers do not share bunks with other cabins","Find how many cabins are needed for 70 campers","Seventy campers will each need a bunk of their own"]', 'Find how many cabins are needed for 70 campers', NULL, 'The problem is the question to be answered: how many cabins. The other sentences give a quantity or make an assumption.', 'checked', '{"lint":[],"solve":{"answer":"Find how many cabins are needed for 70 campers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2) is the problem: find cabins for 70 campers (ceil(70/6) = 12). D.","run_id":"claude-code","at":"2026-10-23T00:17:54.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1677f149-83fb-4b4b-837a-05c86a0ed4f7', 'NC26.M2.ANFR.1', 1, 'choice', 'Perfect square trinomials', 'Which of these is a perfect square trinomial?', '["$x^2+10x+10$","$x^2+10x+5$","$x^2+10x+25$","$x^2+5x+25$"]', '$x^2+10x+25$', NULL, 'A perfect square trinomial has the form $x^2+2ax+a^2$. For $x^2+10x+25$, $a=5$: $2a=10$ and $a^2=25$, so it equals $(x+5)^2$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2+10x+25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+10x+25 = (x+5)^2. x^2+10x+10 and x^2+10x+5 would need 25; x^2+5x+25 would need 10x. Only one is a perfect square.","run_id":"claude-code","at":"2026-10-22T12:48:57.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15faa7c2-7d08-4843-8077-9328ae0ad7e6', 'NC26.M2.ANFR.1', 1, 'choice', 'Factor ax^2 + bx + c', 'Which is $2x^2+5x+2$ factored?', '["$(2x+2)(x+1)$","$(x+1)(x+2)$","$(2x-1)(x-2)$","$(2x+1)(x+2)$"]', '$(2x+1)(x+2)$', NULL, 'Try $(2x+1)(x+2) = 2x^2 + 4x + x + 2 = 2x^2 + 5x + 2$. It matches.', 'checked', '{"lint":[],"solve":{"answer":"$(2x+1)(x+2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x+1)(x+2) = 2x^2 + 4x + x + 2 = 2x^2 + 5x + 2.","run_id":"claude-code","at":"2026-10-22T19:33:44.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad9dada-2b06-4ac7-9acf-7cce49714a62', 'NC26.M2.ANFR.1', 1, 'choice', 'Factor a difference of squares', 'Which of these is a difference of squares?', '["$9x^2+4$","$9x^2-12x+4$","$9x^2-4x$","$9x^2-4$"]', '$9x^2-4$', NULL, 'A difference of squares is one perfect square minus another: $9x^2 = (3x)^2$ and $4 = 2^2$, so $9x^2-4 = (3x)^2-2^2$.', 'checked', '{"lint":[],"solve":{"answer":"$9x^2-4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9x^2 - 4 = (3x)^2 - 2^2.","run_id":"claude-code","at":"2026-10-22T19:33:44.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01f1c6f1-6595-4ec1-8407-257e3674b11c', 'NC26.M2.ANFR.1', 2, 'numeric', 'Area model for factoring', 'An area model for factoring $x^2+bx+12$ has four parts with areas $x^2$, $3x$, $4x$ and $12$. What is $b$?', '[]', '7', '3+4', 'The two middle parts are added to give the middle term: $3x+4x=7x$. So $x^2+7x+12=(x+3)(x+4)$ and $b=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of the parts: x^2 + 3x + 4x + 12 = x^2 + 7x + 12, so b = 7. (Consistent: (x+3)(x+4).)","run_id":"claude-code","at":"2026-10-22T12:48:57.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f3c9754-4683-4b21-832d-37a9c2c5ff85', 'NC26.M2.ANFR.1', 2, 'choice', 'Factor ax^2 + bx + c', 'Which is $3x^2-8x+4$ factored?', '["$(3x-2)(x-2)$","$(3x+2)(x+2)$","$(3x-4)(x-1)$","$(3x-1)(x-4)$"]', '$(3x-2)(x-2)$', NULL, 'Try $(3x-2)(x-2) = 3x^2 - 6x - 2x + 4 = 3x^2 - 8x + 4$. It matches.', 'checked', '{"lint":[],"solve":{"answer":"$(3x-2)(x-2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x-2)(x-2) = 3x^2 - 6x - 2x + 4 = 3x^2 - 8x + 4. Others give -13x, -7x, +8x.","run_id":"claude-code","at":"2026-10-22T19:33:44.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0127c4d5-2dbf-4ae5-93aa-304ec9d59f54', 'NC26.M2.ANFR.1', 2, 'numeric', 'Area model for factoring', 'A rectangular field has an area of $x^2+11x+24$ square meters and a length of $x+8$ meters. What is its width, in meters, when $x=10$?', '[]', '13', '10+3', 'The width is $x+3$, since $(x+8)(x+3) = x^2+11x+24$. When $x=10$ the width is $10+3 = 13$ meters.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 + 11x + 24 = (x+8)(x+3); width x + 3 = 13.","run_id":"claude-code","at":"2026-10-22T19:33:44.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2198fceb-6b1c-4484-9e6a-27fc917a8a1f', 'NC26.M2.ANFR.1', 3, 'choice', 'Complete the square: rewrite a quadratic', 'The quadratic $y=x^2-8x+19$ is rewritten by completing the square. What is its vertex (lowest point)?', '["$(-4, 3)$","$(4, 19)$","$(4, -3)$","$(4, 3)$"]', '$(4, 3)$', NULL, 'Half of $-8$ is $-4$ and $(-4)^2=16$. So $y=(x^2-8x+16)-16+19=(x-4)^2+3$. The lowest point is where $x-4=0$, which is $(4, 3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-8x+19 = (x-4)^2 - 16 + 19 = (x-4)^2 + 3. Vertex (4, 3), the minimum since the parabola opens up.","run_id":"claude-code","at":"2026-10-22T12:48:57.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23214f43-4c7f-438e-ba24-6483946a42b2', 'NC26.M2.ANFR.1', 3, 'choice', 'Factor x^2 + bx + c', 'Exactly one of these trinomials can be written as a product of two binomials with integer constants. Which one?', '["$x^2+3x+14$","$x^2+2x-6$","$x^2-3x-10$","$x^2-5x+7$"]', '$x^2-3x-10$', NULL, 'For $x^2+bx+c$ we need two integers with product $c$ and sum $b$. For $x^2-3x-10$, the integers $-5$ and $2$ have product $-10$ and sum $-3$, so it equals $(x-5)(x+2)$. For $x^2+3x+14$, $x^2+2x-6$ and $x^2-5x+7$ no pair of integers has the needed product and sum.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-3x-10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-3x-10: need product -10, sum -3: -5 and 2, so (x-5)(x+2). Others: x^2-5x+7 disc 25-28<0; x^2+3x+14 disc 9-56<0; x^2+2x-6 disc 4+24=28 not a perfect square. Only one factors.","run_id":"claude-code","at":"2026-10-23T00:29:46.866Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01d084e7-5689-4ccd-9424-22278d115236', 'NC26.M2.ANFR.2', 1, 'choice', 'Identify the type of relationship from a situation', 'A colony starts with 100 bacteria, and the number of bacteria doubles every hour. What type of relationship connects the number of bacteria and the number of hours?', '["Linear","Quadratic","Reciprocal","Exponential"]', 'Exponential', NULL, 'The number is multiplied by the same amount, 2, every hour. Repeated multiplication by a constant gives an exponential relationship.', 'checked', '{"lint":[],"solve":{"answer":"Exponential","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling each hour: N=100*2^t, a constant ratio per equal step, so exponential.","run_id":"claude-code","at":"2026-10-22T13:00:43.812Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a476489-61e2-49e6-95c2-4d9a851c9667', 'NC26.M2.ANFR.2', 1, 'numeric', 'Recognize an exponential pattern (constant ratios)', 'In an exponential relationship, $x=0, 1, 2$ go with $y=1, 4, 16$, and each $y$-value is the one before it multiplied by the same number. What is $y$ when $x=4$?', '[]', '256', '4^4', 'Each $y$-value is 4 times the one before it. At $x=3$ the value is $16\cdot 4=64$, and at $x=4$ it is $64\cdot 4=256$.', 'checked', '{"lint":[],"solve":{"answer":"256","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 4: y(3)=64, y(4)=256.","run_id":"claude-code","at":"2026-10-22T19:35:05.558Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d48f380-0124-4cfd-a1b1-cfa5bdfc3992', 'NC26.M2.ANFR.2', 1, 'choice', 'Identify the type of relationship from its equation', 'Which equation shows an exponential relationship?', '["$y=3x+2$","$y=3x^2+2$","$y=3\\cdot 2^x$","$y=\\frac{3}{x}+2$"]', '$y=3\cdot 2^x$', NULL, 'The variable $x$ is in the exponent only in $y=3\cdot 2^x$. The others are linear, quadratic and reciprocal.', 'checked', '{"lint":[],"solve":{"answer":"$y=3\\cdot 2^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*2^x has the variable in the exponent: exponential.","run_id":"claude-code","at":"2026-10-22T19:35:05.558Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3033d8c3-ceaa-4449-a645-c0770e38fb85', 'NC26.M2.ANFR.2', 2, 'numeric', 'Recognize an exponential pattern (constant ratios)', 'The $x$-values 0, 1, 2, 3 go with the $y$-values 64, 32, 16, 8, and the pattern continues. What is $y$ when $x=6$?', '[]', '1', '8*(1/2)^3', 'Each $y$-value is half the one before it. After 8 come 4 (at $x=4$), 2 (at $x=5$) and 1 (at $x=6$).', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64,32,16,8: each y is half the previous (exponential). x=4:4, x=5:2, x=6:1.","run_id":"claude-code","at":"2026-10-22T13:00:43.812Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2988db10-63d7-45f3-b8a4-aa59cfdddc81', 'NC26.M2.ANFR.2', 2, 'numeric', 'Recognize an exponential pattern (constant ratios)', 'In an exponential relationship, $y=16$ when $x=0$, $y=24$ when $x=1$ and $y=36$ when $x=2$. What is $y$ when $x=3$?', '[]', '54', '36*36/24', 'Each $y$-value is $1.5$ times the one before it ($24\div 16=1.5$). So at $x=3$ the value is $36\cdot 1.5=54$.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 24/16=1.5: y(3)=36*1.5=54.","run_id":"claude-code","at":"2026-10-22T19:35:05.558Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01615e30-52e1-42b3-9624-2f52902f0caf', 'NC26.M2.ANFR.2', 2, 'choice', 'Recognize a reciprocal pattern (constant product)', 'For positive $x$, which statement is true about $y=\frac{36}{x}$ as $x$ gets larger and larger?', '["$y$ gets smaller and smaller until it eventually becomes negative","$y$ gets larger and larger without any end","$y$ gets closer and closer to 36 but never reaches it","$y$ gets closer and closer to 0 but never reaches 0"]', '$y$ gets closer and closer to 0 but never reaches 0', NULL, 'The numerator 36 stays the same while the denominator grows, so the fraction shrinks toward 0. It is always positive, so it never reaches 0 or goes below it.', 'checked', '{"lint":[],"solve":{"answer":"$y$ gets closer and closer to 0 but never reaches 0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36/x decreases toward 0 for positive x and stays positive.","run_id":"claude-code","at":"2026-10-22T19:35:05.558Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('021f189f-88ae-422a-bba2-9b933d4e19b1', 'NC26.M2.ANFR.2', 3, 'numeric', 'Predict a value from a table or graph', 'In an exponential relationship, each $y$-value is the one before it multiplied by the same positive number as $x$ goes up by 1. If $y=3$ when $x=1$ and $y=48$ when $x=5$, what is $y$ when $x=3$?', '[]', '12', '3*2^2', 'From $x=1$ to $x=5$ the value is multiplied four times: $3r^4=48$, so $r^4=16$ and $r=2$. Then $y=3\cdot 2^2=12$ at $x=3$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3b^4=48, b^4=16, b=2; y(3)=3*4=12.","run_id":"claude-code","at":"2026-10-22T19:35:05.558Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07348d07-a1ae-408e-acef-efe0c4c5e136', 'NC26.M2.ANFR.2', 3, 'numeric', 'Recognize a quadratic pattern (constant second differences)', 'A quadratic relationship has a constant second difference of 6 for $x=0, 1, 2, 3$. If $y=1$ when $x=0$ and $y=2$ when $x=1$, what is $y$ when $x=3$?', '[]', '22', '1+1+7+13', 'The first difference from $x=0$ to $x=1$ is 1. Each next first difference is 6 more: 7, then 13. So $y$ is $2+7=9$ at $x=2$ and $9+13=22$ at $x=3$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First diffs 1, 7, 13: y=1,2,9,22. y(3)=22.","run_id":"claude-code","at":"2026-10-22T19:35:05.558Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cd4cbf5-e443-49a9-b109-70d68366b26e', 'NC26.M2.ANFR.3', 1, 'choice', 'Domain and range', 'The domain of $f(x)=x^2-4$ is all real numbers. What is its range?', '["$y \\le -4$","$y \\ge 4$","$y \\ge 0$","$y \\ge -4$"]', '$y \ge -4$', NULL, 'Since $x^2\ge 0$, the least value of $x^2-4$ is $-4$ and the outputs get larger without end. The range is $y\ge -4$.', 'checked', '{"lint":[],"solve":{"answer":"$y \\ge -4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2>=0 so x^2-4>=-4.","run_id":"claude-code","at":"2026-10-22T19:35:05.595Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08531981-dd51-4e11-a250-c4ccad0699b3', 'NC26.M2.ANFR.3', 1, 'numeric', 'Reciprocal functions', 'Let $f(x)=\frac{5}{x}$. What is $f(10)$?', '[]', '1/2', '5/10', 'Replace $x$ with 10: $f(10)=\frac{5}{10}=\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/10=1/2.","run_id":"claude-code","at":"2026-10-22T19:35:05.595Z"}}', 'ai', NULL, NULL)
