INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('015c9029-bfad-4b0f-ab5b-1ba3843a5aa2', 'NC26.M2.ANFR.3', 1, 'choice', 'Comparing function types', 'Which function has outputs that go up by exactly 3 every time $x$ goes up by 1?', '["$y=3x$","$y=3^x$","$y=x^2+3$","$y=\\frac{3}{x}$"]', '$y=3x$', NULL, 'The linear function $y=3x$ gives 3, 6, 9, ... for $x=1, 2, 3$. The function $y=3^x$ gives 3, 9, 27, $y=x^2+3$ gives 4, 7, 12, and $y=\frac{3}{x}$ goes down.', 'checked', '{"lint":[],"solve":{"answer":"$y=3x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x: slope 3, outputs rise by exactly 3. Others do not.","run_id":"claude-code","at":"2026-10-22T19:35:05.595Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b579da1-bb62-4da7-93a0-137c831edbb7', 'NC26.M2.ANFR.3', 2, 'numeric', 'Zeros of a quadratic', 'What is the larger zero of $f(x) = x^2 - 5x - 14$?', '[]', '7', NULL, 'Factor: $x^2 - 5x - 14 = (x - 7)(x + 2)$. Setting each factor to 0 gives $x = 7$ and $x = -2$. The larger zero is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 5x - 14 = (x - 7)(x + 2); zeros 7 and -2. Larger is 7.","run_id":"claude-code","at":"2026-10-22T19:22:02.472Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1addeac1-8fb3-462d-8960-6bc3a80a4ffd', 'NC26.M2.ANFR.3', 2, 'choice', 'Discrete versus continuous domains', 'Which of these quantities is a function with a discrete domain?', '["The cost of buying $n$ pencils, where $n$ is the number of pencils","The temperature of a cup of tea at every moment as it cools for 10 minutes","The height of a plant at every moment during one week","The amount of water in a tank at every moment while it fills"]', 'The cost of buying $n$ pencils, where $n$ is the number of pencils', NULL, 'The number of pencils must be a whole number, so the inputs are separate values. The other three can be measured at any moment, so their domains are continuous.', 'checked', '{"lint":[],"solve":{"answer":"The cost of buying $n$ pencils, where $n$ is the number of pencils","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pencils come in whole numbers: discrete domain. Others are measured at every moment.","run_id":"claude-code","at":"2026-10-22T19:35:05.595Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a5a84e6-e6b6-4fc9-9518-3fc0bfb3da5e', 'NC26.M2.ANFR.3', 2, 'choice', 'Average rate of change', 'What is the average rate of change of $f(x)=x^2$ from $x=-2$ to $x=2$?', '["4","0","2","-2"]', '0', '(4-4)/(2-(-2))', 'Here $f(-2)=4$ and $f(2)=4$. The average rate of change is $\frac{4-4}{2-(-2)}=0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(2)=f(-2)=4; rate 0.","run_id":"claude-code","at":"2026-10-22T19:35:05.595Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d7dd4fb-69c2-47db-8be5-5dd5f38c3c0c', 'NC26.M2.ANFR.3', 3, 'numeric', 'Zeros of a quadratic', 'A ball''s height, in feet, is $h(t) = -16t^2 + 64t + 80$ at $t$ seconds after it is thrown. After how many seconds does the ball reach the ground (height 0)?', '[]', '5', NULL, 'Set $-16t^2 + 64t + 80 = 0$ and divide by $-16$: $t^2 - 4t - 5 = 0$, which factors as $(t - 5)(t + 1) = 0$. So $t = 5$ or $t = -1$. A time cannot be negative, so the ball lands after 5 seconds.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-16t^2 + 64t + 80 = 0 -> t^2 - 4t - 5 = 0 -> (t - 5)(t + 1) = 0 -> t = 5 (t = -1 rejected).","run_id":"claude-code","at":"2026-10-22T19:22:02.472Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a8355c3-b1e2-4fc4-99ab-3ead6fcbacdc', 'NC26.M2.ANFR.3', 3, 'numeric', 'Reciprocal functions', 'Let $f(x)=\frac{8}{x-3}+2$. What is $f(7)$?', '[]', '4', '8/(7-3)+2', 'Replace $x$ with 7: $\frac{8}{4}+2=2+2=4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/4+2=4.","run_id":"claude-code","at":"2026-10-22T19:35:05.595Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1398c8ba-20b1-4fbf-b314-a94a19628f6c', 'NC26.M2.ANFR.4', 1, 'numeric', 'Recursive rule for a quadratic sequence', 'A sequence starts with $a_1 = 2$ and follows the rule $a_{n+1} = a_n + 2n$ for $n \ge 1$. What is $a_4$?', '[]', '14', '2+2*1+2*2+2*3', 'Use the rule one step at a time. $a_2 = 2 + 2(1) = 4$. $a_3 = 4 + 2(2) = 8$. $a_4 = 8 + 2(3) = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1=2, a2=2+2(1)=4, a3=4+2(2)=8, a4=8+2(3)=14.","run_id":"claude-code","at":"2026-10-22T19:23:59.728Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d46568a-5f04-4e39-97ce-668f3af02bf7', 'NC26.M2.ANFR.4', 1, 'choice', 'Write a quadratic function from a situation', 'A rectangle has width $x$ meters and length $x + 5$ meters. Which function gives its area $A$, in square meters?', '["$A(x) = x^2 + 5x$","$A(x) = x^2 + 5$","$A(x) = 2x + 5$","$A(x) = 5x^2$"]', '$A(x) = x^2 + 5x$', NULL, 'Area is length times width: $x(x + 5) = x^2 + 5x$.', 'checked', '{"lint":[],"solve":{"answer":"$A(x) = x^2 + 5x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A=x(x+5)=x^2+5x.","run_id":"claude-code","at":"2026-10-22T19:38:53.379Z"}}', 'ai', NULL, NULL)
