INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04dc7bd6-d0b7-4240-870c-134b11446c16', 'NC26.M2.SGMR.1', 2, 'numeric', 'Find the image of a point or figure', 'The point $(2, -5)$ is reflected across the $y$-axis and then translated 4 units right and 1 unit down. What is the sum of the two coordinates of the final point?', '[]', '-4', '2+(-6)', 'The reflection gives $(-2, -5)$. The translation gives $(-2 + 4,\ -5 - 1) = (2, -6)$. The sum is $2 + (-6) = -4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect y-axis: (-2,-5); translate: (2,-6); sum -4.","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d1de77e-4ba4-41de-a87c-e347dca58eb1', 'NC26.M2.SGMR.1', 2, 'numeric', 'Transformations in function notation', 'The dilation $D(x, y) = (1.5x,\ 1.5y)$ is applied to the point $(6, -8)$. What is the sum of the coordinates of the image?', '[]', '-3', '1.5*6+1.5*(-8)', '$D(6, -8) = (9, -12)$, and $9 + (-12) = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9,-12); sum -3.","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('051e9ec2-4867-4f3f-8571-8356ffc5d8d8', 'NC26.M2.SGMR.1', 2, 'choice', 'Map one figure onto another', 'The triangle with vertices $(1, 1)$, $(3, 1)$ and $(3, 4)$ is mapped to the triangle with vertices $(-1, -1)$, $(-3, -1)$ and $(-3, -4)$, in that order. Which single transformation does this?', '["A reflection across the $y$-axis","A reflection across the $x$-axis","A rotation of $180^\\circ$ about the origin","A translation 2 units left and 2 units down"]', 'A rotation of $180^\circ$ about the origin', NULL, 'Both coordinates of every point change sign, which is a $180^\circ$ rotation about the origin.', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $180^\\circ$ about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each point maps to (-x,-y): 180° rotation about origin. Translation fails for (3,1)->(-3,-1).","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18cc2917-5142-4961-894c-d548c1cdb01d', 'NC26.M2.SGMR.1', 3, 'choice', 'Center and scale factor of a dilation', 'A dilation centered at the origin maps the rectangle with vertices $(2, 1)$, $(6, 1)$, $(6, 4)$ and $(2, 4)$ onto the rectangle with vertices $(3, 1.5)$, $(9, 1.5)$, $(9, 6)$ and $(3, 6)$, in that order. What is the scale factor?', '["$\\frac{3}{2}$","$\\frac{2}{3}$","$2$","$3$"]', '$\frac{3}{2}$', NULL, 'Compare corresponding vertices: $(2, 1)\to(3, 1.5)$, and $3\div 2=1.5=\frac{3}{2}$. Every other coordinate is also multiplied by $\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,1)->(3,1.5): 3/2 = 1.5, 1.5/1 = 1.5; (6,4)->(9,6) also 1.5. Scale factor 3/2.","run_id":"claude-code","at":"2026-10-22T12:48:57.299Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13ef862b-03ce-4161-aab5-152c731d836e', 'NC26.M2.SGMR.1', 3, 'numeric', 'Center and scale factor of a dilation', 'A dilation with scale factor $\frac{1}{2}$ maps the point $(8, 6)$ to the point $(5, 4)$. What is the $x$-coordinate of the center of the dilation?', '[]', '2', '(5-0.5*8)/(1-0.5)', 'With center $(h, k)$: $5 = h + \frac{1}{2}(8 - h)$, so $5 = \frac{h}{2} + 4$ and $h = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c + (8-c)/2 = 5 -> c=2 (y: c+(6-c)/2=4 -> c=2, consistent).","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('149ece8b-fbfd-49b1-a5e4-a7a613121627', 'NC26.M2.SGMR.2', 1, 'numeric', 'Corresponding parts of congruent and similar triangles', 'Triangle $ABC$ is congruent to triangle $XYZ$, with $A$ matching $X$, $B$ matching $Y$ and $C$ matching $Z$. If $\angle C=65^\circ$, what is the measure of $\angle Z$, in degrees?', '[]', '65', '65', 'Matching parts of congruent triangles are equal. $\angle Z$ matches $\angle C$, so $\angle Z=65^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles of congruent triangles are equal: angle Z = angle C = 65.","run_id":"claude-code","at":"2026-10-22T13:00:43.849Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15ab2dbf-faef-446e-90a8-be0f33c1a26f', 'NC26.M2.SGMR.2', 1, 'numeric', 'Perimeter and area of similar figures', 'Two similar triangles have matching sides of 3 centimeters and 12 centimeters. The smaller triangle has a perimeter of 8 centimeters. What is the perimeter of the larger triangle, in centimeters?', '[]', '32', '8*12/3', 'The scale factor from the smaller to the larger triangle is $\frac{12}{3} = 4$. Perimeters grow by the same factor, so the larger perimeter is $8 \cdot 4 = 32$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale 12/3 = 4; perimeter 8*4 = 32.","run_id":"claude-code","at":"2026-10-23T00:09:53.031Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('120a1cea-62f7-4dc8-8ad6-fb9e1dd2ba4e', 'NC26.M2.SGMR.2', 1, 'choice', 'A line parallel to a side of a triangle', 'In triangle $ABC$, point $D$ is on $AB$ and point $E$ is on $AC$, with $DE$ parallel to $BC$. Why does $\angle ADE$ equal $\angle ABC$?', '["They are alternate interior angles, since $DE \\parallel BC$ and $AB$ crosses both","They are corresponding angles, since $DE \\parallel BC$ and $AB$ crosses both","They are vertical angles, since $DE$ and $BC$ both meet $AB$","They are equal because both triangles share the angle at $A$"]', 'They are corresponding angles, since $DE \parallel BC$ and $AB$ crosses both', NULL, 'Line $AB$ crosses the parallel lines $DE$ and $BC$, and $\angle ADE$ and $\angle ABC$ are in matching positions, so they are corresponding angles and are equal. This is why triangle $ADE$ is similar to triangle $ABC$.', 'checked', '{"lint":[],"solve":{"answer":"They are corresponding angles, since $DE \\parallel BC$ and $AB$ crosses both","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB is a transversal of parallel DE and BC; ADE and ABC are in matching positions: corresponding angles.","run_id":"claude-code","at":"2026-10-23T00:09:53.031Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f3f6120-e100-4a5b-bda4-9879b39f9eef', 'NC26.M2.SGMR.2', 2, 'choice', 'Triangle similarity rules (AA, SAS, SSS)', 'In triangles $ABC$ and $DEF$, $\angle A=\angle D=50^\circ$, $AB=6$, $AC=9$, $DE=8$ and $DF=12$. Which rule shows that the triangles are similar?', '["AA similarity: two pairs of angles are equal, so the third pair is equal as well","SSS similarity: all three pairs of sides are in proportion, so no angle is needed","SAS congruence: two pairs of sides are equal and the angles between them are equal","SAS similarity: two pairs of sides are in proportion, with the angles between them equal"]', 'SAS similarity: two pairs of sides are in proportion, with the angles between them equal', NULL, 'The sides around $\angle A$ and $\angle D$ are in proportion: $\frac{6}{8}=\frac{3}{4}$ and $\frac{9}{12}=\frac{3}{4}$, and those angles are equal, so SAS similarity applies. Only one pair of angles is given, the third pair of sides is not given, and the sides are not equal, so the other rules do not apply.', 'checked', '{"lint":[],"solve":{"answer":"SAS similarity: two pairs of sides are in proportion, with the angles between them equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB/DE = 6/8 = 3/4, AC/DF = 9/12 = 3/4, and the included angles A and D are equal: SAS similarity. Not congruent (sides differ); only one angle pair, so not AA; third sides unknown, so not SSS.","run_id":"claude-code","at":"2026-10-22T13:00:43.849Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('155c8195-1647-4622-bf3a-7a1074331c49', 'NC26.M2.SGMR.2', 2, 'choice', 'Corresponding parts of congruent and similar triangles', 'Triangle $PQR$ is congruent to triangle $XYZ$, with the letters listed in matching order. Which statement must be true?', '["$QR=XY$","$PQ=XZ$","$QR=YZ$","$PR=YZ$"]', '$QR=YZ$', NULL, '$P$ matches $X$, $Q$ matches $Y$ and $R$ matches $Z$. So side $QR$ matches side $YZ$, and matching sides of congruent triangles are equal.', 'checked', '{"lint":[],"solve":{"answer":"$QR=YZ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding sides: QR matches YZ.","run_id":"claude-code","at":"2026-10-23T00:09:53.031Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a2dbe34-82dd-4872-a22e-58b6f7c19a47', 'NC26.M2.SGMR.2', 2, 'numeric', 'A line parallel to a side of a triangle', 'Segment $DE$ is parallel to side $BC$ of triangle $ABC$, with $D$ on $AB$ and $E$ on $AC$. If $AD=6$, $DB=3$ and $BC=12$, what is the length of $DE$?', '[]', '8', '12*6/9', 'Triangle $ADE$ is similar to triangle $ABC$, with $AB = AD + DB = 9$. So $\frac{DE}{BC} = \frac{AD}{AB} = \frac{6}{9}$ and $DE = 12 \cdot \frac{6}{9} = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AD/AB = 6/9 = 2/3 = DE/BC; DE = 8.","run_id":"claude-code","at":"2026-10-23T00:09:53.031Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04488d4a-e0f2-4723-b7f2-36b1e8c554c1', 'NC26.M2.SGMR.2', 3, 'numeric', 'Perimeter and area of similar figures', 'Two similar triangles have areas of 12 and 75 square units. The perimeter of the larger triangle is 30 units. What is the perimeter of the smaller triangle, in units?', '[]', '12', '30*2/5', 'The areas are in the ratio $\frac{12}{75} = \frac{4}{25}$, so the sides (and perimeters) are in the ratio $\sqrt{\frac{4}{25}} = \frac{2}{5}$. The smaller perimeter is $30 \cdot \frac{2}{5} = 12$ units.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side ratio sqrt(12/75) = 2/5; perimeter 30*2/5 = 12.","run_id":"claude-code","at":"2026-10-23T00:09:53.031Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('038218ab-4091-4c2a-98d4-687df4bf60e5', 'NC26.M2.SGMR.2', 3, 'numeric', 'Indirect measurement with similar triangles', 'A lamp is at the top of a post on level ground. A 2-meter-tall person stands 6 meters from the base of the post, and the person''s shadow is 3 meters long, ending farther from the post than the person does. How tall is the post, in meters?', '[]', '6', '2*9/3', 'The tip of the shadow is $6 + 3 = 9$ meters from the post''s base. The post with its distance to the shadow''s tip, and the person with the shadow, form similar right triangles: $\frac{\text{post}}{9} = \frac{2}{3}$. So the post is $\frac{2 \cdot 9}{3} = 6$ meters tall.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shadow tip 9 m from post. H/9 = 2/3 -> H = 6.","run_id":"claude-code","at":"2026-10-23T00:09:53.031Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06d27887-6fc9-49e4-93ff-96c892a2f966', 'NC26.M2.SGMR.3', 1, 'choice', 'How the ratios relate (tangent, sine, cosine)', 'For an acute angle $A$ in a right triangle, which expression is equal to $\tan A$?', '["$\\frac{\\cos A}{\\sin A}$","$\\sin A \\cdot \\cos A$","$\\frac{1}{\\sin A}$","$\\frac{\\sin A}{\\cos A}$"]', '$\frac{\sin A}{\cos A}$', NULL, 'Using sides, $\frac{\sin A}{\cos A} = \frac{\text{opposite}/\text{hypotenuse}}{\text{adjacent}/\text{hypotenuse}} = \frac{\text{opposite}}{\text{adjacent}} = \tan A$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{\\sin A}{\\cos A}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"tan A = opp/adj = (opp/hyp)/(adj/hyp) = sin A / cos A.","run_id":"claude-code","at":"2026-10-22T19:22:02.509Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b5b192-3164-4354-b5f9-059646d6ee91', 'NC26.M2.SGMR.3', 1, 'choice', 'Sine, cosine and tangent as side ratios', 'In a right triangle, which ratio gives the cosine of an acute angle?', '["The adjacent side divided by the hypotenuse","The opposite side divided by the hypotenuse","The opposite side divided by the adjacent side","The hypotenuse divided by the adjacent side"]', 'The adjacent side divided by the hypotenuse', NULL, 'Cosine is adjacent over hypotenuse. (Sine is opposite over hypotenuse, and tangent is opposite over adjacent.)', 'checked', '{"lint":[],"solve":{"answer":"The adjacent side divided by the hypotenuse","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"cos = adjacent/hypotenuse.","run_id":"claude-code","at":"2026-10-23T00:09:53.067Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05b381cb-9f30-4613-b801-c558406b0d5b', 'NC26.M2.SGMR.3', 1, 'numeric', 'Sine, cosine and tangent as side ratios', 'In a right triangle, angle $B$ is acute. The side next to angle $B$ (not the hypotenuse) is 6, the side opposite angle $B$ is 8, and the hypotenuse is 10. What is $\cos B$? Give a fraction.', '[]', '3/5', '6/10', 'Cosine is adjacent over hypotenuse: $\cos B = \frac{6}{10} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"cos B = adjacent/hyp = 6/10 = 3/5.","run_id":"claude-code","at":"2026-10-23T00:09:53.067Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cea0c33-bc02-456a-9a30-f3e946e7e358', 'NC26.M2.SGMR.3', 2, 'numeric', 'Sine, cosine and tangent as side ratios', 'In a right triangle, the hypotenuse is 15 and the side opposite angle $\theta$ is 9. What is $\tan \theta$? Give a fraction.', '[]', '3/4', '9/12', 'First find the other leg: $\sqrt{15^2 - 9^2} = \sqrt{225 - 81} = \sqrt{144} = 12$. Then $\tan \theta = \frac{\text{opposite}}{\text{adjacent}} = \frac{9}{12} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent = sqrt(225 - 81) = sqrt(144) = 12. tan = 9/12 = 3/4.","run_id":"claude-code","at":"2026-10-22T19:22:02.509Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b34c114-4e4f-4376-930e-314e5c5454ea', 'NC26.M2.SGMR.3', 2, 'numeric', 'Sine, cosine and tangent as side ratios', 'In a right triangle, the side opposite angle $\theta$ is 20 and the side next to angle $\theta$ (not the hypotenuse) is 21. What is $\sin \theta$? Give a fraction.', '[]', '20/29', '20/29', 'The hypotenuse is $\sqrt{20^2 + 21^2} = \sqrt{841} = 29$. Sine is opposite over hypotenuse: $\sin \theta = \frac{20}{29}$.', 'checked', '{"lint":[],"solve":{"answer":"20/29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"hyp = sqrt(400+441) = 29; sin = 20/29.","run_id":"claude-code","at":"2026-10-23T00:09:53.067Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b25e9ef-92fc-46e2-bc14-64976bb71a2b', 'NC26.M2.SGMR.3', 2, 'numeric', 'Finding an acute angle from a ratio or sides', 'A right triangle has a hypotenuse of 12 and a leg of 6. What is the measure of the acute angle opposite the leg of length 6, in degrees?', '[]', '30', '30', 'The sine of the angle is $\frac{6}{12} = \frac{1}{2}$, so the angle is $30^\circ$. (A leg that is half the hypotenuse is the shorter leg of a 30-60-90 triangle.)', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin = 6/12 = 1/2 -> 30.","run_id":"claude-code","at":"2026-10-23T00:09:53.067Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05bf0206-68e9-4bbe-9a3d-0a2567b5a931', 'NC26.M2.SGMR.3', 3, 'numeric', 'Sine, cosine and tangent as side ratios', 'A right triangle has legs of length 7 and 24. What is the cosine of its larger acute angle? Give a fraction.', '[]', '7/25', '7/25', 'The hypotenuse is $\sqrt{7^2 + 24^2} = \sqrt{625} = 25$. The larger acute angle is opposite the longer leg (24), so the leg next to it is 7. Then $\cos = \frac{\text{adjacent}}{\text{hypotenuse}} = \frac{7}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"7/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hypotenuse = sqrt(49 + 576) = 25. Larger acute angle is opposite the leg 24; its adjacent leg is 7. cos = 7/25.","run_id":"claude-code","at":"2026-10-22T19:22:02.509Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0312eaed-3f64-4df9-af5c-442b17e61022', 'NC26.M2.SGMR.3', 3, 'numeric', 'How the ratios relate (tangent, sine, cosine)', '$A$ is an acute angle of a right triangle and $\sin A = \frac{4}{5}$. What is $\tan A$? Give a fraction.', '[]', '4/3', '4/3', 'Think of a right triangle with opposite side 4 and hypotenuse 5. The adjacent side is $\sqrt{5^2 - 4^2} = 3$, so $\cos A = \frac{3}{5}$ and $\tan A = \frac{\sin A}{\cos A} = \frac{4/5}{3/5} = \frac{4}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"4/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sin A = 4/5 -> opposite 4, hyp 5, adjacent 3. tan A = 4/3.","run_id":"claude-code","at":"2026-10-22T19:22:02.509Z"}}', 'ai', NULL, NULL)
