INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06e16351-c183-4767-9380-3f40a6526803', 'NC26.MSM.RMM.4', 3, 'numeric', 'Key features of a sinusoidal model', 'The height of a bicycle pedal above the ground is modeled by a sinusoidal function of the time $t$ in seconds. At $t = 0$ the pedal is at its lowest, 20 centimeters. At $t = 1.5$ it is at its highest, 60 centimeters, half a turn later. What is the height of the pedal at $t = 0.75$ seconds, in centimeters?', '[]', '40', '(20+60)/2', 'The highest point comes half a period after the lowest, so the period is 3 seconds. Then $t = 0.75$ is a quarter of a period after the lowest point. A quarter of the way from the lowest point to the highest, a sinusoidal function is on its midline, which is $\frac{20 + 60}{2} = 40$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Min 20 at t = 0, max 60 at t = 1.5 (half a period), so period 3 s, midline 40, amplitude 20. h(t) = 40 - 20cos(2 pi t/3). At t = 0.75 (quarter period), cos(pi/2) = 0, so h = 40 cm.","run_id":"claude-code","at":"2026-10-22T12:52:38.183Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('002460b8-921d-44bd-af8f-644f80c8fd13', 'NC26.MSM.RMM.4', 3, 'numeric', 'Key features of an exponential model', 'A population is modeled by an exponential function. It is 400 when $t=1$ and 900 when $t=3$, where $t$ is in years. What population does the model give at $t=5$?', '[]', '2025', '900*(900/400)', 'Over 2 years the population is multiplied by $\frac{900}{400}=\frac94$. Another 2 years multiplies by $\frac94$ again: $900\times\frac94=2025$.', 'checked', '{"lint":[],"solve":{"answer":"2025","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 900/400 = 9/4; P(5) = 900*9/4 = 2025.","run_id":"claude-code","at":"2026-10-22T19:36:18.210Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02128299-7d08-4ceb-8581-7239dbb408df', 'NC26.MSM.RSM.1', 1, 'numeric', 'Relate a sample to its population', 'A school has 900 students. A researcher asks a random sample of 45 of them about their favorite sport. What percent of the school''s students are in the sample?', '[]', '5', '45/900*100', 'The sample is a part of the population of 900 students. $45 \div 900 = 0.05$, which is 5 percent.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 / 900 = 0.05 = 5 percent.","run_id":"claude-code","at":"2026-10-22T12:51:14.678Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09b8222a-eefa-4ecc-a3b4-4b26c1d52ca7', 'NC26.MSM.RSM.1', 1, 'numeric', 'Plan data collection around response rates', 'A questionnaire was given to 250 residents, and 200 residents returned it. What percent of the residents did NOT return it?', '[]', '20', '(250-200)/250*100', '250 - 200 = 50 residents did not return it. 50 / 250 = 0.20, which is 20 percent.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Not returned 250-200 = 50; 50/250 = 20%.","run_id":"claude-code","at":"2026-10-22T19:42:08.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26147c4c-968b-4a29-bdcb-388d15b378a2', 'NC26.MSM.RSM.1', 1, 'choice', 'Plan how to measure', 'A teacher wants to measure how long students take to solve a puzzle. Which way of recording the data is the most precise?', '["Ask each student if the puzzle felt long or short","Record each student as fast or slow by first impression","Time each student with a stopwatch and record the seconds","Ask students to guess how many minutes they took"]', 'Time each student with a stopwatch and record the seconds', NULL, 'A stopwatch gives a measured number for every student. The other methods rely on opinions or guesses.', 'checked', '{"lint":[],"solve":{"answer":"Time each student with a stopwatch and record the seconds","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Stopwatch in seconds is the most precise measurement.","run_id":"claude-code","at":"2026-10-22T19:42:08.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c5cf94a-7e8d-49b8-9947-7568f274082b', 'NC26.MSM.RSM.1', 2, 'choice', 'Recognize bias in how a sample is chosen', 'A researcher phones only households with landline phones to learn about the opinions of all residents of a town. What is the main problem with this plan?', '["Leading-question bias: phone calls push residents toward one answer","Undercoverage: residents who have no landline cannot be chosen","Voluntary response bias: residents choose whether to be called","Cluster bias: the households called are all next to each other"]', 'Undercoverage: residents who have no landline cannot be chosen', NULL, 'Residents without a landline have no chance of being in the sample, so the sample leaves out a part of the population that may think differently (for example, younger residents). That is undercoverage.', 'checked', '{"lint":[],"solve":{"answer":"Undercoverage: residents who have no landline cannot be chosen","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"People without a landline (for example cell-only households) have no chance to be chosen: undercoverage.","run_id":"claude-code","at":"2026-10-22T12:51:14.678Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1817f913-3646-4a0f-90bf-93d5c41244e5', 'NC26.MSM.RSM.1', 2, 'choice', 'Anticipate sampling variability', 'In a population, 30 percent of people say yes to a question. Many random samples of size 40 are taken. Which sample proportion of yes answers would be the most surprising?', '["0.28","0.33","0.25","0.65"]', '0.65', NULL, 'Samples of size 40 from a 30 percent population usually give proportions fairly close to 0.30. A value as high as 0.65 is very far from it, so it would be the most surprising.', 'checked', '{"lint":[],"solve":{"answer":"0.65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SD of p-hat = sqrt(0.3x0.7/40) ~ 0.072. Distances from 0.30: 0.25 (0.05), 0.65 (0.35, ~4.8 SD), 0.33 (0.03), 0.28 (0.02). Most surprising 0.65.","run_id":"claude-code","at":"2026-10-22T19:42:08.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f13cd3-da12-4f03-acf1-a260a1346e43', 'NC26.MSM.RSM.1', 2, 'choice', 'State the scope and limits of conclusions', 'A random sample of 100 students is chosen from a single school and surveyed. To which population can the results be generalized?', '["All students in the state","All students at that school","All students in the country","Only the 100 students surveyed"]', 'All students at that school', NULL, 'A random sample lets us generalize to the population it was drawn from, which is the students at that school, not to groups that had no chance of being chosen.', 'checked', '{"lint":[],"solve":{"answer":"All students at that school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from one school generalizes to that school.","run_id":"claude-code","at":"2026-10-22T19:42:08.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04e4c2cc-0baa-4eae-b7cc-1fcfceb873b5', 'NC26.MSM.RSM.1', 3, 'choice', 'Recognize bias in how a sample is chosen', 'A town wants to know whether its residents support a plan to expand the library. A volunteer stands outside the library for one afternoon and asks 100 people who are leaving the building. Which statement best describes the limits of this plan?', '["One hundred people are too few to trust, however they are chosen","People asked in person always give false answers, so the data are useless","The people asked mostly use the library, so the results may not describe all residents","The people were picked at random, so the results apply to the whole town"]', 'The people asked mostly use the library, so the results may not describe all residents', NULL, 'The people leaving the library are not chosen by chance. They are the ones who use the library, and they are likely to favor it more than other residents, so the results cannot be applied to the whole town. The size of the sample is not the main problem, and it is not random.', 'checked', '{"lint":[],"solve":{"answer":"The people asked mostly use the library, so the results may not describe all residents","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"People leaving the library are mostly library users, likely to favour expansion, so the sample may not represent all residents. The other options are false claims.","run_id":"claude-code","at":"2026-10-22T12:51:14.678Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07707f5a-6e1a-40cc-bdd5-39a55d5bbb6a', 'NC26.MSM.RSM.1', 3, 'numeric', 'Plan a systematic or stratified sample', 'A systematic sample of exactly 40 names is taken from a list of 480 names by taking every k-th name, starting at name 3. What is the position on the list of the 12th name chosen?', '[]', '135', '3+11*(480/40)', 'The step is k = 480 / 40 = 12. The 12th name is at 3 + 11 x 12 = 135.', 'checked', '{"lint":[],"solve":{"answer":"135","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 480/40 = 12; 12th name = 3 + 11x12 = 135.","run_id":"claude-code","at":"2026-10-22T19:42:08.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fda3555-60b3-475f-8c91-ce198fd49633', 'NC26.MSM.RSM.2', 1, 'choice', 'Choosing a display for the data', 'A survey asks 80 students to name their favorite season. Which display is best for comparing how many students chose each season?', '["A histogram with the seasons as its bins","A bar chart with one bar for each season","A scatterplot of the season against the student","A box plot of the seasons"]', 'A bar chart with one bar for each season', NULL, 'The favorite season is a category, not a number, so the counts for the categories are compared with a bar chart. Histograms and box plots are for numerical data, and a scatterplot needs two numerical variables.', 'checked', '{"lint":[],"solve":{"answer":"A bar chart with one bar for each season","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Season is categorical; a bar chart with one bar per season compares counts. Box plots, scatterplots and histograms need quantitative data.","run_id":"claude-code","at":"2026-10-22T19:22:02.620Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1679e670-ae61-465a-9670-07d98609bb84', 'NC26.MSM.RSM.2', 1, 'numeric', 'Calculating measures of spread', 'The daily high temperatures, in degrees, on five days were 61, 68, 64, 72 and 59. What is the range of these temperatures, in degrees?', '[]', '13', '72-59', 'The range is the greatest value minus the least value: $72-59=13$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = 72 - 59 = 13.","run_id":"claude-code","at":"2026-10-22T19:22:02.620Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a1aa62b-0d32-4796-97a5-ef0bcdc2d6bd', 'NC26.MSM.RSM.2', 1, 'numeric', 'Comparing groups and values', 'On a test, the mean is 50 and the standard deviation is 10. A student scores 70. How many standard deviations above the mean is the score?', '[]', '2', '(70-50)/10', 'The score is 70 - 50 = 20 points above the mean. 20 / 10 = 2 standard deviations.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(70-50)/10 = 2.","run_id":"claude-code","at":"2026-10-22T19:42:08.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01f2e812-2361-4177-9121-c4905608c69f', 'NC26.MSM.RSM.2', 2, 'choice', 'Two-way tables and relative frequencies', 'Of 250 people surveyed, 100 are under 18, 40 are left-handed, and 12 are both under 18 and left-handed. What fraction of all 250 people are both under 18 and left-handed?', '["0.12","0.048","0.3","0.4"]', '0.048', '12/250', 'The fraction of all 250 people is $12\div 250=0.048$. The value $12\div 100=0.12$ is the fraction of the people under 18 who are left-handed, $12\div 40=0.3$ is the fraction of the left-handed people who are under 18, and $100\div 250=0.4$ is the fraction under 18.', 'checked', '{"lint":[],"solve":{"answer":"0.048","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/250 = 0.048.","run_id":"claude-code","at":"2026-10-22T19:22:02.620Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('011c37e1-0dd2-4a37-b129-58900049c9db', 'NC26.MSM.RSM.2', 2, 'numeric', 'Calculating mean and median', 'The mean of five numbers is 18. Four of the numbers are 10, 15, 20 and 25. What is the fifth number?', '[]', '20', '18*5-(10+15+20+25)', 'The five numbers total 18 x 5 = 90. The four known numbers total 70. So the fifth is 90 - 70 = 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 90; 90 - 70 = 20.","run_id":"claude-code","at":"2026-10-22T19:42:08.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03d3c9b4-08a8-4403-a786-be448d09c248', 'NC26.MSM.RSM.2', 2, 'numeric', 'Two-way tables and relative frequencies', 'In a survey of 150 people, 60 prefer tea and 90 prefer coffee. Of the 90 coffee drinkers, 36 are over 40 years old. What percent of the coffee drinkers are over 40?', '[]', '40', '36/90*100', '36 / 90 = 0.40, which is 40 percent.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36/90 = 40%.","run_id":"claude-code","at":"2026-10-22T19:42:08.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07dc10d1-444e-4bb9-b710-2fa3eba1bab1', 'NC26.MSM.RSM.2', 3, 'choice', 'Choosing a display for the data', 'Researchers want to compare the commute times of about 300 workers in each of four cities, looking at the median, the spread and the outliers of each city side by side. Which display is the most efficient?', '["Four pie charts, one for each city","One histogram that combines the workers from all four cities","One bar chart showing the mean commute time of each city","Four box plots drawn side by side on one common scale"]', 'Four box plots drawn side by side on one common scale', NULL, 'Box plots show the median, the quartiles and the outliers of each group, and drawing them on one scale makes the cities easy to compare. A combined histogram hides the differences between cities, a bar chart of means shows no spread, and pie charts show parts of a whole.', 'checked', '{"lint":[],"solve":{"answer":"Four box plots drawn side by side on one common scale","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side-by-side box plots on a common scale show each city''s median, spread and outliers efficiently for large groups.","run_id":"claude-code","at":"2026-10-22T19:22:02.620Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b82a14b-0cc0-48eb-b4dc-16951ae80bb9', 'NC26.MSM.RSM.2', 3, 'choice', 'Two-way tables and relative frequencies', 'Of 120 students, 70 of the 80 who study every day passed a test, and 20 of the 40 who do not study every day passed. Which statement is best supported?', '["There is no association, since 70 studiers passed and only 20 non-studiers passed","There is an association: 87.5 percent of daily studiers passed, 50 percent of others","There is an association: 70 percent of daily studiers passed, compared with 20 percent of the others","There is no association, since 90 of the 120 students passed the test overall"]', 'There is an association: 87.5 percent of daily studiers passed, 50 percent of others', NULL, 'The pass rate among daily studiers is 70 / 80 = 87.5 percent. Among the others it is 20 / 40 = 50 percent. The rates differ a lot, so the variables are associated. Comparing counts alone is misleading because the group sizes differ.', 'checked', '{"lint":[],"solve":{"answer":"There is an association: 87.5 percent of daily studiers passed, 50 percent of others","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70/80 = 87.5%, 20/40 = 50%: association.","run_id":"claude-code","at":"2026-10-22T19:42:08.607Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15a0440a-7f92-45ec-8039-59e52c6b59ad', 'NC26.MSM.RSM.3', 1, 'numeric', 'Binomial probabilities', 'A spinner lands on blue with probability 0.3 on each spin, independently. What is the probability that both of two spins are blue?', '[]', '0.09', '0.3*0.3', 'The spins are independent, so multiply: $0.3 \times 0.3 = 0.09$.', 'checked', '{"lint":[],"solve":{"answer":"0.09","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3^2=0.09.","run_id":"claude-code","at":"2026-10-22T19:45:59.172Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11730118-1fe8-4fe2-b20f-c543a5d97d8e', 'NC26.MSM.RSM.3', 1, 'choice', 'Properties of the normal distribution', 'What is the total area under the curve of any normal distribution?', '["0.5","1","100","the mean"]', '1', '1', 'The area under a density curve represents the total probability, which is always 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total area under any density curve is 1.","run_id":"claude-code","at":"2026-10-22T19:45:59.172Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0140a337-3003-4117-a53d-3a48ae49ae4a', 'NC26.MSM.RSM.3', 1, 'numeric', 'Normal probabilities from a given area', 'For the standard normal distribution, the probability of a z-score less than 1.28 is 0.90. What is the probability of a z-score greater than 1.28?', '[]', '0.1', '1-0.9', 'The total probability is 1, so the probability above 1.28 is $1 - 0.90 = 0.10$.', 'checked', '{"lint":[],"solve":{"answer":"0.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-0.90=0.10.","run_id":"claude-code","at":"2026-10-22T19:45:59.172Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('183444c1-1ec0-4c6d-b775-72e67e0fdd71', 'NC26.MSM.RSM.3', 2, 'choice', 'Probabilities from a discrete distribution', 'The number of goals a team scores in a game is a random variable $X$ with $P(0) = 0.25$, $P(1) = 0.35$, $P(2) = 0.2$, $P(3) = 0.15$ and $P(4) = 0.05$. What is the probability that the team scores at least 2 goals?', '["0.6","0.2","0.65","0.4"]', '0.4', '0.2+0.15+0.05', '"At least 2" means 2, 3 or 4 goals: $0.2 + 0.15 + 0.05 = 0.4$. (Check: $1 - 0.25 - 0.35 = 0.4$.) The value 0.6 is the probability of fewer than 2 goals, and 0.2 is only $P(2)$.', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(2)+P(3)+P(4)=0.2+0.15+0.05=0.4.","run_id":"claude-code","at":"2026-10-22T19:45:59.172Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('195bff26-f3f3-4c29-b4b4-3cc5506bd1e6', 'NC26.MSM.RSM.3', 2, 'numeric', 'Expected value of a discrete distribution', 'A fair six-sided die has faces 1, 1, 2, 2, 2 and 5. What is the expected value of one roll?', '[]', '13/6', '13/6', 'Add the six faces and divide by 6: $\frac{1 + 1 + 2 + 2 + 2 + 5}{6} = \frac{13}{6}$. Equivalently, $1(\frac{2}{6}) + 2(\frac{3}{6}) + 5(\frac{1}{6}) = \frac{13}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"13/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1+1+2+2+2+5)/6=13/6.","run_id":"claude-code","at":"2026-10-22T19:45:59.172Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02852029-5ec8-466c-ab01-0abc91b77a97', 'NC26.MSM.RSM.3', 2, 'numeric', 'Spread of a discrete distribution', 'A random variable $X$ takes the values 1, 2 and 3 with probabilities 0.25, 0.5 and 0.25, so its mean is 2. What is the variance of $X$?', '[]', '0.5', '0.25*(1-2)^2+0.5*(2-2)^2+0.25*(3-2)^2', 'The variance is the probability-weighted average of the squared deviations from the mean: $0.25(1) + 0.5(0) + 0.25(1) = 0.5$.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.25*1+0.5*0+0.25*1=0.5.","run_id":"claude-code","at":"2026-10-22T19:45:59.172Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('048dc98b-f9bb-4646-90a7-e22e75c378ca', 'NC26.MSM.RSM.3', 3, 'choice', 'Judge a claim using likelihood', 'A bus company claims that 90 percent of its buses arrive on time. In a random sample of 100 arrivals, 78 were on time. If the claim is true, the number on time has mean 90 and standard deviation 3. Which conclusion is best supported?', '["78 is only 12 below the mean, which is small compared with the sample of 100, so it supports the claim","78 is 4 standard deviations below the mean, which is common if the claim is true, so it supports the claim","78 is 4 standard deviations below the mean, so the claim has been proven false for every single bus","78 is 4 standard deviations below the mean, very unlikely if the claim is true, so it counts against the claim"]', '78 is 4 standard deviations below the mean, very unlikely if the claim is true, so it counts against the claim', NULL, 'The z-score is $\frac{78 - 90}{3} = -4$. A result 4 standard deviations from the mean is extremely unlikely if the claim is true, so it is good evidence against the claim. It cannot prove anything about every single bus, only that the claim is doubtful.', 'checked', '{"lint":[],"solve":{"answer":"78 is 4 standard deviations below the mean, very unlikely if the claim is true, so it counts against the claim","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z = (78 - 90)/3 = -4. Four sd below is very unlikely if the claim were true, so it is evidence against the claim (not proof). A calls it common; C ignores sd; D overclaims proof for every bus.","run_id":"claude-code","at":"2026-10-22T12:52:38.218Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('077c0cc1-77fb-4bb3-adec-5ebeff6aac4c', 'NC26.MSM.RSM.3', 3, 'numeric', 'Judge a claim using likelihood', 'A machine is claimed to make a defective part with probability 0.05, independently for each part. An inspector checks 3 parts and finds at least one defective. If the claim is true, what is the probability of finding at least one defective part among 3 parts?', '[]', '0.142625', '1-0.95^3', 'Use the complement: none defective has probability $0.95^3 = 0.857375$. So at least one defective has probability $1 - 0.857375 = 0.142625$, about 14 percent, which is not unusual enough to doubt the claim.', 'checked', '{"lint":[],"solve":{"answer":"0.142625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-0.95^3=1-0.857375=0.142625.","run_id":"claude-code","at":"2026-10-22T19:45:59.172Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a8f063b-4ed3-4a0c-abaa-805a1dbfe996', 'NC26.MSM.RSM.4', 1, 'choice', 'Interpret r and r squared', 'Four regression models are fit to the same data. Which has the best fit, judged by r squared?', '["The model with $r^2 = 0.97$","The model with $r^2 = 0.35$","The model with $r^2 = 0.62$","The model with $r^2 = 0.80$"]', 'The model with $r^2 = 0.97$', NULL, 'A larger r squared means the model explains more of the variation in y. Of the four values, 0.97 is the largest, so that model fits best.', 'checked', '{"lint":[],"solve":{"answer":"The model with $r^2 = 0.97$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The largest r^2 (closest to 1) indicates the best fit: 0.97.","run_id":"claude-code","at":"2026-10-22T12:51:14.714Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b02c55c-ae68-459f-8346-e32bfc92008d', 'NC26.MSM.RSM.4', 1, 'choice', 'Judge fit from residuals and residual plots', 'Which description of a residual plot suggests that the model is appropriate for the data?', '["The residuals form a clear curve, rising and then falling","The residuals are all positive, for every value of $x$","The residuals get steadily larger as $x$ increases","The residuals scatter randomly above and below zero, with no pattern"]', 'The residuals scatter randomly above and below zero, with no pattern', NULL, 'A good model leaves only random errors, so its residuals scatter with no pattern around zero. A curve, a one-sided set of residuals or a steady trend each show that the model is missing something.', 'checked', '{"lint":[],"solve":{"answer":"The residuals scatter randomly above and below zero, with no pattern","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random scatter about zero indicates an appropriate model.","run_id":"claude-code","at":"2026-10-22T19:45:59.210Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f97ea98-e6d2-41f9-b320-2178326b738e', 'NC26.MSM.RSM.4', 1, 'numeric', 'Interpret r and r squared', 'A linear model has $r = 0.6$. What percent of the variation in $y$ is explained by the model?', '[]', '36', '0.6^2*100', 'The percent explained is $r^2 = 0.6^2 = 0.36$, or 36 percent.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r^2=0.36 -> 36 percent.","run_id":"claude-code","at":"2026-10-22T19:45:59.210Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07ee05de-2ec0-441c-a267-1ec7a876550b', 'NC26.MSM.RSM.4', 2, 'numeric', 'Use a fitted polynomial model', 'A quadratic regression model for profit P, in dollars, from selling x gadgets is $P = -2x^2 + 12x + 5$. What is the greatest profit the model predicts, in dollars?', '[]', '23', '-2*9+12*3+5', 'The parabola opens downward, so its highest point is at $x = -\frac{12}{2(-2)} = 3$. Then $P = -2(9) + 12(3) + 5 = -18 + 36 + 5 = 23$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertex at x = -12 / (2*(-2)) = 3. P(3) = -18 + 36 + 5 = 23.","run_id":"claude-code","at":"2026-10-22T12:51:14.714Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e5440cb-ca58-41fb-ae61-04c88a74b7c3', 'NC26.MSM.RSM.4', 2, 'choice', 'Use a fitted exponential model', 'The number of students who know a rumor starts at 8 and, according to an exponential regression model, triples every hour. Which equation gives the number $y$ who know the rumor after $x$ hours?', '["$y = 3(8)^x$","$y = 8 + 3x$","$y = 8x^3$","$y = 8(3)^x$"]', '$y = 8(3)^x$', NULL, 'An exponential model has the form $y = a \cdot b^x$, where $a$ is the starting value 8 and $b$ is the multiplier per hour, 3. So $y = 8(3)^x$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 8(3)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 8, factor 3 per hour: y=8(3)^x.","run_id":"claude-code","at":"2026-10-22T19:45:59.210Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ee1650b-686d-40a7-95ed-4e72f486db04', 'NC26.MSM.RSM.4', 2, 'choice', 'Use and interpret a fitted logarithmic model', 'A logarithmic regression model $y = 12 + 5\ln(x)$ was fit to data with $x$ between 2 and 20. What does the model say about $x = 0$?', '["It predicts $y = 12$, because the logarithm term vanishes","It predicts $y = 0$, because the log of zero is zero","It makes no prediction, because $\\ln(0)$ is undefined","It predicts $y = 17$, because $\\ln(0)$ equals 1"]', 'It makes no prediction, because $\ln(0)$ is undefined', NULL, 'The natural logarithm is defined only for positive numbers, so $\ln(0)$ does not exist and the model gives no value at $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"It makes no prediction, because $\\ln(0)$ is undefined","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ln(0) undefined (and 0 is outside the data), so no prediction.","run_id":"claude-code","at":"2026-10-22T19:45:59.210Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f0c0942-4717-4a55-b336-14c9882d6147', 'NC26.MSM.RSM.4', 3, 'numeric', 'Interpret r and r squared', 'A linearized exponential model has $r = -0.9$. What percent of the variation in $\text{ln}(y)$ is NOT explained by the model?', '[]', '19', '(1-0.9^2)*100', 'The value of r squared is $(-0.9)^2 = 0.81$, so 81 percent of the variation is explained. The rest, $100 - 81 = 19$ percent, is not explained. (The sign of r does not matter for r squared.)', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r^2 = (-0.9)^2 = 0.81, so 81 percent is explained and 100 - 81 = 19 percent is not.","run_id":"claude-code","at":"2026-10-22T12:51:14.714Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35567fd7-9dc9-4748-adc5-2e34b590ddef', 'NC26.MSM.RSM.4', 3, 'numeric', 'Use and interpret a fitted logarithmic model', 'A logarithmic regression model is $y = 1 + 2\log_{10}(x)$. For what value of $x$ does the model predict $y = 7$?', '[]', '1000', '10^3', 'Set $1 + 2\log_{10}(x) = 7$, so $\log_{10}(x) = 3$ and $x = 10^3 = 1000$.', 'checked', '{"lint":[],"solve":{"answer":"1000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+2log(x)=7 -> log(x)=3 -> x=1000.","run_id":"claude-code","at":"2026-10-22T19:45:59.210Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a3e5416-6d7e-42d0-8edb-f9682cc67615', 'NC26.MSM.RSM.5', 1, 'numeric', 'Evaluating a data collection plan', 'A school has 600 students: 360 girls and 240 boys. A stratified random sample of 50 students has the same percent of boys as the school. How many boys should be in the sample?', '[]', '20', '240/600*50', 'Boys are $\frac{240}{600}=40\%$ of the school. The sample should also be 40% boys: $0.40\times 50=20$ boys.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys = 240/600 = 40%. 40% of 50 = 20.","run_id":"claude-code","at":"2026-10-22T19:22:02.657Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04fd4dc3-f978-4221-8637-b9224273bb44', 'NC26.MSM.RSM.5', 1, 'numeric', 'Reporting results clearly', 'In a survey of 250 students, 60 said they walk to school. What percent of the students surveyed walk to school?', '[]', '24', '60/250*100', '$\frac{60}{250}=0.24$, which is 24%.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60/250 = 0.24 = 24%.","run_id":"claude-code","at":"2026-10-22T19:46:10.497Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11cd4762-e3cd-4581-863b-1238602298a4', 'NC26.MSM.RSM.5', 1, 'choice', 'Reporting results clearly', 'Sixty students each named their favorite fruit: apple, banana or grape. Which is the best way to report the results?', '["Give the mean favorite fruit, found by adding up all of the answers and dividing by the 60 students","Give the count or the percent of students who chose each fruit, in a table or a bar graph","Give the range of the fruits, found by subtracting the smallest fruit from the largest fruit","Give the median fruit, found by putting the 60 students in order by their height and taking the middle"]', 'Give the count or the percent of students who chose each fruit, in a table or a bar graph', NULL, 'Fruit names are categories, so we report how many chose each. Means, ranges and medians need numbers.', 'checked', '{"lint":[],"solve":{"answer":"Give the count or the percent of students who chose each fruit, in a table or a bar graph","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Categorical data: report counts or percents per category in a table or bar graph.","run_id":"claude-code","at":"2026-10-22T19:46:10.497Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('150ce6a5-af2a-4bd9-a0c5-f42b258c4d30', 'NC26.MSM.RSM.5', 2, 'choice', 'Evaluating a statistical question', 'A survey asks students, "Do you think the cafeteria food is healthy and cheap?" What is the main problem with this question?', '["It leads students toward answering yes by praising the food first","It asks about the past instead of asking about the cafeteria food now","It uses words that are much too difficult for most students to understand","It asks about two things at once, so one answer cannot fit both parts"]', 'It asks about two things at once, so one answer cannot fit both parts', NULL, 'A student who thinks the food is healthy but expensive cannot answer yes or no. A good question asks about one thing at a time, so "healthy" and "cheap" should be asked in two separate questions.', 'checked', '{"lint":[],"solve":{"answer":"It asks about two things at once, so one answer cannot fit both parts","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double-barreled question: food could be healthy but not cheap, so one yes/no cannot fit both.","run_id":"claude-code","at":"2026-10-22T19:22:02.657Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12aeba3b-856d-4062-b4c6-f4ab4ea06ca1', 'NC26.MSM.RSM.5', 2, 'choice', 'Evaluating a probability model', 'A meteorologist models rain by saying each day has a 30% chance of rain, independent of the other days. Which is the main reason this model may be unrealistic?', '["A chance of rain on a day cannot be as low as 30% in any real place","Rainy weather tends to last for several days, so the days are not independent","Rain either happens or it does not, so no probability can be given to it at all","Each day should have a 50% chance of rain, since there are two outcomes"]', 'Rainy weather tends to last for several days, so the days are not independent', NULL, 'Weather comes in spells: if it rained yesterday, rain today is more likely, so the days are not independent. A probability of 30% is allowed, probabilities are used for events that either happen or not, and two outcomes need not be equally likely.', 'checked', '{"lint":[],"solve":{"answer":"Rainy weather tends to last for several days, so the days are not independent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Weather is persistent from day to day, so the independence assumption is unrealistic. The other options are false reasoning.","run_id":"claude-code","at":"2026-10-22T19:22:02.657Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c10a526-8b9e-4cfb-b67c-7c499249f0d1', 'NC26.MSM.RSM.5', 2, 'choice', 'Evaluating a probability model', 'In 100 rolls of a die, 1 came up 10 times, 2 came up 11 times, 3 came up 9 times, 4 came up 12 times, 5 came up 10 times and 6 came up 48 times. Which probability model fits these data best?', '["Each of the numbers 1 to 6 has the same probability, and that probability is one sixth","The number 6 has probability 0.25 and each of the numbers 1 to 5 has probability 0.15","The number 6 has probability 0.5 and each of 1 to 5 has probability 0.1","The number 6 has probability 0.5 and each of the numbers 1 to 5 has probability 0.2"]', 'The number 6 has probability 0.5 and each of 1 to 5 has probability 0.1', NULL, 'The 6 came up about half the time and each other number about a tenth of the time. A model has to add to 1: $0.5+5(0.1)=1$, but $0.5+5(0.2)=1.5$.', 'checked', '{"lint":[],"solve":{"answer":"The number 6 has probability 0.5 and each of 1 to 5 has probability 0.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Observed: 6 about 0.48, others about 0.09-0.12. D: 0.5 + 5(0.1) = 1, fits. A sums to 1.5 (invalid), B ignores the 48, C gives 6 only 0.25.","run_id":"claude-code","at":"2026-10-22T19:46:10.497Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('183216fa-d4a5-4b92-8aef-35b8bc279e64', 'NC26.MSM.RSM.5', 3, 'choice', 'Evaluating a statistical question', 'A survey asks, "How often do you skip breakfast?" with the options Never, Rarely, Sometimes and Often. What is the main weakness of the options?', '["There are fewer than ten options, so the data cannot be summarized into counts of each answer","The options go in order from least to most, which forces every student to choose the middle one","Words cannot be counted, so no summary of the answers is possible with options like these ones","The words are not defined, so two students with the same habit might choose different answers"]', 'The words are not defined, so two students with the same habit might choose different answers', NULL, '"Rarely" and "Sometimes" mean different things to different students. Clear ranges, such as 0 days, 1 to 2 days, and so on, would fix this. Word answers can still be counted.', 'checked', '{"lint":[],"solve":{"answer":"The words are not defined, so two students with the same habit might choose different answers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Never/Rarely/Sometimes/Often are vague; the same habit could be labelled differently by different students.","run_id":"claude-code","at":"2026-10-22T19:46:10.497Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0322870e-6f53-4b5c-a1f1-3c894e97d583', 'NC26.MSM.RSM.5', 3, 'numeric', 'Critiquing an investigation', 'A test finds every person who has a condition, and it also gives a positive result for 5% of the people who do not have the condition. Among 1000 people, 2% have the condition. How many of the people who test positive do not have the condition?', '[]', '49', '1000*0.98*0.05', '20 people have the condition and 980 do not. 5% of 980 is 49 false positives. So of the 69 positive results, 49 are false.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 have the condition, 980 do not. False positives = 5% of 980 = 49.","run_id":"claude-code","at":"2026-10-22T19:46:10.497Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('040e23f1-5265-4026-9cf8-23200341b57b', 'PRE.01', 1, 'numeric', 'Multiplying and dividing negative numbers', 'What is the product of $-3$ and 4?', '[]', '-12', '-3*4', 'A negative number times a positive number is negative: $3 \times 4 = 12$, so the answer is $-12$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3)(4) = -12.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
