VALUES ('118548fc-20ea-4037-8566-78150bffe2a6', 'PRE.01', 1, 'choice', 'Naming the property used', 'Which property says that $(2 + 3) + 4 = 2 + (3 + 4)$?', '["Commutative","Distributive","Identity","Associative"]', 'Associative', NULL, 'Changing how the numbers are grouped, without changing their order, is the associative property.', 'checked', '{"lint":[],"solve":{"answer":"Associative","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grouping changed: associative.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
