VALUES ('1c43e665-5545-4d91-8e3f-d8a848ebb1fc', 'PRE.01', 2, 'choice', 'Adding and subtracting negative numbers', 'Find $-7 - (-3)$.', '["$-10$","$-4$","$10$","$4$"]', '$-4$', '-7+3', 'Subtracting $-3$ is the same as adding 3: $-7 + 3 = -4$.', 'checked', '{"lint":[],"solve":{"answer":"$-4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-7 - (-3) = -7 + 3 = -4.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
