VALUES ('07f5e20b-3a89-4a5b-9389-ad5e8f4d1538', 'PRE.01', 2, 'choice', 'Multiplying and dividing negative numbers', 'Find $(-4) \times (-5) \times (-2)$.', '["$-40$","$40$","$-20$","$-3$"]', '$-40$', '-4*-5*-2', '$(-4) \times (-5) = 20$, and $20 \times (-2) = -40$.', 'checked', '{"lint":[],"solve":{"answer":"$-40$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-4)(-5) = 20; 20 x (-2) = -40.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
