VALUES ('0cf85187-c9da-4b3e-a574-17ac003dbaa5', 'PRE.01', 2, 'numeric', 'Computing cleverly with the properties', 'Find $25 \times 13 \times 4$.', '[]', '1300', '100*13', '$25 \times 4 = 100$, and $100 \times 13 = 1300$.', 'checked', '{"lint":[],"solve":{"answer":"1300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 x 4 = 100, x 13 = 1300.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
