INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06aaf990-c89e-4d9d-9a45-c101c47ca10a', 'PRE.02', 1, 'choice', 'Product and quotient laws of exponents', 'Which is equal to $10^7 \div 10^2$?', '["$10^9$","$10^{14}$","$1^5$","$10^5$"]', '$10^5$', NULL, 'Keep the base and subtract the exponents: $7 - 2 = 5$. Adding gives $10^9$, multiplying gives $10^{14}$, and the base does not become 1.', 'checked', '{"lint":[],"solve":{"answer":"$10^5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10^(7-2) = 10^5.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
