INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('029fb746-232f-4176-b6ce-9450bc8753ce', 'PRE.02', 1, 'numeric', 'Order of operations', 'Evaluate $3 \times 2^2$. Remember that powers come before multiplication.', '[]', '12', '3*2^2', 'The exponent comes before the multiplication: $2^2 = 4$, then $3 \times 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^2 = 4; 3 x 4 = 12.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
