INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11325a66-4d49-4a34-9a55-7ef5fe4e4824', 'PRE.02', 3, 'numeric', 'Evaluating powers', 'Find $2^0 + 2^1 + 2^2 + 2^3 + 2^4 + 2^5 + 2^6 + 2^7$.', '[]', '255', '1+2+4+8+16+32+64+128', 'Each power is one more than all the earlier ones added together, so the total is $2^8 - 1 = 255$. Or add: $1 + 2 + 4 + 8 + 16 + 32 + 64 + 128 = 255$.', 'checked', '{"lint":[],"solve":{"answer":"255","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^8 - 1 = 255.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
