INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05f42e21-c387-4f43-ba5f-b797068eb764', 'PRE.02', 3, 'choice', 'Powers of negative numbers', 'Evaluate $(-3)^2 - 3^2 + (-3)^3 - 3^3$, taking care with the signs.', '["$0$","$-18$","$54$","$-54$"]', '$-54$', '9-9-27-27', '$(-3)^2 = 9$, $3^2 = 9$, $(-3)^3 = -27$ and $3^3 = 27$. So $9 - 9 + (-27) - 27 = -54$.', 'checked', '{"lint":[],"solve":{"answer":"$-54$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 9 + (-27) - 27 = -54.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
