INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0734bb35-0a6c-4f9c-beaf-9517d016dc5c', 'PRE.03', 1, 'numeric', 'Greatest common divisor', 'What is the greatest whole number that divides evenly into both $15$ and $45$?', '[]', '15', '15', 'The number 45 is $3\times 15$, so 15 divides both 15 and 45. No number larger than 15 can divide 15, so the answer is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 divides 45, so 15.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad1a846-0957-4d59-865b-a0a6bc3e25e4', 'PRE.03', 1, 'choice', 'Least common multiple', 'What is the least common multiple of $3$ and $5$?', '["8","15","30","1"]', '15', '15', 'Neither 3 nor 5 divides the other, and they share no prime, so the LCM is their product, $3\times 5=15$. The number 8 is their sum, 30 is a common multiple that is not the least, and 1 is a common divisor.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(3,5)=15.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0965979e-8b4a-43fe-ae0e-0d67cd91afc7', 'PRE.03', 2, 'choice', 'Divisibility rules', 'Which of these numbers is divisible by $4$?', '["$1{,}214$","$3{,}426$","$7{,}324$","$5{,}718$"]', '$7{,}324$', NULL, 'A number is divisible by 4 when its last two digits make a number divisible by 4. $24=4\times 6$, so $7324$ works. The endings 14, 26 and 18 are not multiples of 4.', 'checked', '{"lint":[],"solve":{"answer":"$7{,}324$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Last two digits 18, 24, 26, 14: only 24 divisible by 4.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04832e57-ac2f-42a5-af8b-05ed96eac818', 'PRE.03', 2, 'numeric', 'Greatest common divisor', 'What is the greatest common divisor of $91$ and $143$?', '[]', '13', '13', '$91=7\times 13$ and $143=11\times 13$. The only shared prime is 13, so the GCD is 13.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"91=7*13, 143=11*13; gcd 13.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
