INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093d6ad0-9613-43cd-8810-cb88e4159c14', 'PRE.03', 2, 'numeric', 'Least common multiple', 'What is the least common multiple of $6$, $10$ and $15$?', '[]', '30', '30', '$6=2\times 3$, $10=2\times 5$ and $15=3\times 5$. The LCM uses 2, 3 and 5 once each: $2\times 3\times 5=30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(6,10,15)=30.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('044a32c2-5dc5-4297-9104-3d183c530fa4', 'PRE.03', 3, 'numeric', 'Identify primes and composites', 'The numbers $p$, $p+2$ and $p+4$ are all prime numbers. What is the value of $p$?', '[]', '3', '3', 'Try $p=2$: then $p+2=4$ is not prime. Try $p=3$: 3, 5 and 7 are all prime. For any larger $p$, one of the three numbers $p$, $p+2$, $p+4$ is a multiple of 3 (they leave different remainders when divided by 3), and it is bigger than 3, so it is not prime. So $p=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One of p, p+2, p+4 is divisible by 3, so it must equal 3; p=3 gives 3,5,7 (p=1 not prime).","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02d533d4-ec28-4840-8493-d9e8081b7207', 'PRE.03', 3, 'numeric', 'GCD and LCM in word problems and relationships', 'Two different whole numbers, both between $10$ and $30$, have a greatest common divisor of $6$ and a least common multiple of $72$. What is the sum of the two numbers?', '[]', '42', '18+24', 'Both numbers are multiples of 6 between 10 and 30: 12, 18, 24. GCD times LCM equals the product, so the product is $6\times 72=432$. Of the pairs, $18\times 24=432$. Check: GCD of 18 and 24 is 6, LCM is 72. The sum is $18+24=42$.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a=6x, b=6y, xy=12, coprime: (1,12)->6,72 or (3,4)->18,24. Both in 10-30: 18+24=42.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1482fe19-ae94-4efd-aad7-129467452a0a', 'PRE.04', 1, 'choice', 'Simplify, compare and find equivalent fractions', 'Which fraction is $\frac{6}{8}$ in simplest form?', '["$\\frac{3}{8}$","$\\frac{4}{3}$","$\\frac{3}{4}$","$\\frac{2}{3}$"]', '$\frac{3}{4}$', NULL, 'Both 6 and 8 can be divided by 2: $6\div 2=3$ and $8\div 2=4$. So $\frac{6}{8}=\frac{3}{4}$. Nothing but 1 divides both 3 and 4, so this is simplest.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by 2: 3/4.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04d86797-9d2c-4d0b-9a59-8defa2c9aa02', 'PRE.04', 1, 'choice', 'Simplify, compare and find equivalent fractions', 'Which of these fractions is already in simplest form?', '["$\\frac{6}{9}$","$\\frac{7}{12}$","$\\frac{10}{15}$","$\\frac{14}{21}$"]', '$\frac{7}{12}$', NULL, 'The fractions $\frac{6}{9}$, $\frac{10}{15}$ and $\frac{14}{21}$ can be reduced (by 3, 5 and 7). The only number that divides both 7 and 12 is 1, so $\frac{7}{12}$ is in simplest form.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 and 12 share no factor; 10/15, 14/21, 6/9 all reduce to 2/3.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04371914-2a98-4b74-93cc-ed210b3af5d6', 'PRE.04', 1, 'numeric', 'Multiply fractions and find a fraction of a number', 'What is $\frac{1}{2}\times\frac{3}{5}$?', '[]', '3/10', '1/2*3/5', 'Multiply the tops and the bottoms: $\frac{1\times 3}{2\times 5}=\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/10.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
