INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0484fc2b-c29a-46e6-a383-a6191bb0b872', 'PRE.04', 2, 'choice', 'Fractions within fractions (complex fractions)', 'What is $\dfrac{4}{\frac{2}{5}}$?', '["$\\frac{8}{5}$","10","$\\frac{1}{10}$","$4\\frac{2}{5}$"]', '10', '4/(2/5)', '$4\div\frac{2}{5}=4\times\frac{5}{2}=10$. The value $\frac{8}{5}$ comes from multiplying by $\frac{2}{5}$ instead, and $\frac{1}{10}$ is $\frac{2}{5}\div 4$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*5/2=10.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31128ac0-bba1-4b44-ba85-38107ad894e0', 'PRE.04', 2, 'choice', 'Fraction word problems and order of operations', 'A tank holds $60$ liters. It is $\dfrac{2}{5}$ full. How many more liters are needed to make it $\dfrac{3}{4}$ full?', '["21","36","45","24"]', '21', '3/4*60-2/5*60', 'Now it has $\frac{2}{5}\times 60=24$ liters. At three fourths it would have $\frac{3}{4}\times 60=45$ liters. The difference is $45-24=21$ liters.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4*60=45, 2/5*60=24; 21.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0293cbff-2345-4b54-80d6-bdd2c7cd017e', 'PRE.04', 2, 'choice', 'Fraction word problems and order of operations', 'Max walks $\frac{2}{5}$ of the way to school. Then he walks $\frac{1}{3}$ of the distance that is still left. What fraction of the whole way has he walked?', '["$\\frac{11}{15}$","$\\frac{3}{5}$","$\\frac{1}{5}$","$\\frac{2}{3}$"]', '$\frac{3}{5}$', NULL, 'After the first part, $\frac{3}{5}$ of the way is left. He walks $\frac{1}{3}$ of that, which is $\frac{1}{3}\times\frac{3}{5}=\frac{1}{5}$. In all he has walked $\frac{2}{5}+\frac{1}{5}=\frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 + 1/3*3/5 = 2/5+1/5=3/5.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c0e89eb-4a88-437c-873d-525a3dd049f6', 'PRE.04', 3, 'choice', 'Divide fractions and use reciprocals', 'A number divided by $\frac{2}{3}$ is $12$. What is the number?', '["18","9","16","8"]', '8', '12*2/3', 'Dividing by $\frac{2}{3}$ is multiplying by $\frac{3}{2}$, so $\text{number}\times\frac{3}{2}=12$. Undo it: $12\times\frac{2}{3}=8$. Check: $8\div\frac{2}{3}=12$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12*2/3=8.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fb1a4ad-a381-41be-9f73-067980c6030d', 'PRE.04', 3, 'choice', 'Fraction word problems and order of operations', 'A hiker walks $\frac{2}{3}$ of a trail on the first day and half of what is left on the second day. On the third day the last 5 miles remain. How many miles long is the trail?', '["20","15","30","60"]', '30', '5/(1/3*1/2)', 'After day 1, $\frac{1}{3}$ of the trail is left. Half of that, $\frac{1}{6}$, is walked on day 2, so $\frac{1}{6}$ remains. If $\frac{1}{6}$ of the trail is 5 miles, the trail is $6\times 5=30$ miles.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After day 1: 1/3 left; day 2 takes 1/6; 1/6 of trail = 5 -> 30.","run_id":"claude-code","at":"2026-10-19T01:39:57.148Z"}}', 'ai', NULL, NULL)
