INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dca7ed2-8802-47db-8898-bec4278f76ab', 'PRE.05', 1, 'numeric', 'Solve an equation with parentheses or fractions', 'Solve $\frac{3}{5}x=12$. What is $x$?', '[]', '20', '12*5/3', 'Multiply both sides by $\frac{5}{3}$ (or multiply by 5 and divide by 3): $x=12\times5\div3=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 12*5/3 = 20.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
