VALUES ('0897b18c-a005-4424-9f10-03c6dc7df638', 'PRE.06', 1, 'choice', 'Turn a repeating decimal into a fraction', 'Which fraction is equal to $0.\overline{3}$?', '["$\\frac{3}{10}$","$\\frac{1}{3}$","$\\frac{3}{100}$","$\\frac{1}{30}$"]', '$\frac{1}{3}$', NULL, '$0.\overline{3}=0.333\ldots$ is what you get when you divide 1 by 3, so it equals $\frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.(3) = 3/9 = 1/3.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
