INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('011044f8-cea7-43b3-a885-e9f763025c78', 'PRE.08', 3, 'choice', 'Finding what percent one number is of another', '$\frac{3}{4}$ is what percent of $\frac{5}{6}$?', '["111.1%","62.5%","75%","90%"]', '90%', NULL, '$\frac{3/4}{5/6}=\frac{3}{4}\times\frac{6}{5}=\frac{18}{20}=\frac{90}{100}$, which is 90%.', 'checked', '{"lint":[],"solve":{"answer":"90%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4)/(5/6)=18/20=90%","run_id":"claude-code","at":"2026-10-19T01:39:00.653Z"}}', 'ai', NULL, NULL)
