INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10ccb7a9-f35f-491a-91f3-1104fc7472f1', 'PRE.08', 3, 'choice', 'Finding the whole from a percent', '20% of a number plus 30% of the same number is 45. What is the number?', '["90","9","22.5","225"]', '90', '45/0.5', '20% + 30% = 50% of the number, so half of the number is 45 and the number is 90.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50% of n=45, n=90","run_id":"claude-code","at":"2026-10-19T01:39:00.653Z"}}', 'ai', NULL, NULL)
