VALUES ('17c7ca07-b4b6-44fb-98d7-6f5c1b2ba1a7', 'PRE.09', 1, 'numeric', 'Estimating square roots', 'What is the largest whole number that is less than $\sqrt{30}$?', '[]', '5', '5', '$5^2=25$ and $6^2=36$, so $\sqrt{30}$ is between 5 and 6. The largest whole number below it is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25<30<36, sqrt30 about 5.48; largest whole number below is 5.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
