VALUES ('44d789ab-4b2f-48fa-9a77-a1e999b6e1ff', 'PRE.09', 2, 'choice', 'Simplifying square roots', 'Sam wants to simplify $\sqrt{98}$. Which answer is correct and fully simplified?', '["$7\\sqrt{2}$","$49\\sqrt{2}$","$2\\sqrt{7}$","$7\\sqrt{3}$"]', '$7\sqrt{2}$', NULL, 'Find the biggest perfect square that divides 98: 98 = 49 × 2. Then $\sqrt{98}=\sqrt{49}\times\sqrt{2}=7\sqrt{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$7\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"98=49*2 -> 7sqrt2.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
