VALUES ('01f18c77-8019-481c-aad1-a0f817ac7ffe', 'PRE.10', 3, 'numeric', 'Vertical angles', 'Two lines cross. A pair of vertical angles measure $(4x+15)^\circ$ and $(6x-25)^\circ$. How many degrees is an angle that is next to one of them?', '[]', '85', '180-(4*20+15)', 'Vertical angles are equal: $4x+15=6x-25$, so $x=20$. Each of them is $4\times 20+15=95$ degrees. An angle next to it is $180-95=85$.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+15=6x-25, x=20, angle 95, adjacent 180-95=85.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
