VALUES ('1d8f1745-7c5f-42ac-8a46-45b949f45ec8', 'PRE.11', 1, 'numeric', 'Perimeter and area of a rectangle', 'A garden is a rectangle 9 meters long and 4 meters wide. What is its perimeter, in meters?', '[]', '26', '2*(9+4)', 'The perimeter is the distance around: $9+4+9+4=26$ meters.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 2(9+4) = 26.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
