INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('151ed99f-3c34-4d17-ba41-2b0170612257', 'PRE.12', 1, 'numeric', 'Missing leg of a right triangle', 'The longest side of a right triangle is 15 inches. Another side is 12 inches. How long is the third side, in inches?', '[]', '9', '9', 'The longest side is the hypotenuse. $15^2-12^2=225-144=81$, and $\sqrt{81}=9$ inches.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(225-144) = 9.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d898cab-f4b3-4fa5-8b7b-e7073072d9e7', 'PRE.12', 1, 'numeric', 'Pythagorean triples', 'A triangle with sides 3, 4 and 5 is made 4 times as big in every direction. How long is its longest side?', '[]', '20', '5*4', 'Every side is multiplied by 4, so the longest side is $5\times 4=20$. (The sides 12, 16, 20 still make a right triangle.)', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*4 = 20.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21aff682-b223-4f68-881f-75422d3345b8', 'PRE.12', 1, 'choice', 'Area of quadrilaterals', 'A kite has diagonals of 8 centimeters and 12 centimeters. What is its area, in square centimeters?', '["96","48","20","40"]', '48', '8*12/2', 'The area of a kite is half the product of its diagonals: $\frac12\times 8\times 12=48$. (96 forgets the half.)', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8*12/2 = 48.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4f2f11-09d6-4abc-838e-f3830fb25d93', 'PRE.12', 2, 'numeric', 'Angles and properties of quadrilaterals', 'Two angles of a parallelogram that are next to each other are in the ratio 1 : 4. How many degrees is the smaller angle?', '[]', '36', '180/5', 'Next angles add to 180 degrees. The ratio parts add to 5, so one part is $180\div 5=36$ degrees. The smaller angle is 36 degrees.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 4x = 180, x = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02765202-9abb-45e6-abd4-66e25a1b1758', 'PRE.12', 2, 'choice', 'Area of quadrilaterals', 'A rhombus has an area of 60 square centimeters, and one diagonal is 10 centimeters long. How long is the other diagonal, in centimeters?', '["6","50","24","12"]', '12', '60*2/10', 'Area $=\frac12 d_1 d_2$, so $\frac12\times 10\times d_2=60$, $5d_2=60$ and $d_2=12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*60/10 = 12.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab8c985-6d0f-41f2-8cb0-fa24f66fc25c', 'PRE.12', 2, 'choice', 'Classifying quadrilaterals and their diagonals', 'Which statement is true?', '["Every rectangle is a square.","Every parallelogram is a rhombus.","Every trapezoid is a parallelogram.","Every square is a rectangle."]', 'Every square is a rectangle.', NULL, 'A square has four right angles, so it is a rectangle. A rectangle need not have equal sides, a parallelogram need not have equal sides, and a trapezoid has only one pair of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Every square is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every square is a rectangle.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24c3e85e-7305-4ec2-9cf4-7584518cbd98', 'PRE.12', 3, 'numeric', '30-60-90 triangles', 'An equilateral triangle is $5\sqrt{3}$ centimeters tall. What is its perimeter, in centimeters?', '[]', '30', '3*10', 'The height is the shortest side times $\sqrt3$, so half of the base is 5 and the side is 10 centimeters. The perimeter is $3\times 10=30$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s*sqrt3/2 = 5sqrt3 -> s = 10, P = 30.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f960951-d6b9-48df-971e-82fb87943502', 'PRE.12', 3, 'numeric', 'Classifying quadrilaterals and their diagonals', 'A rectangle has a diagonal of 25 centimeters and a perimeter of 62 centimeters. What is its area, in square centimeters?', '[]', '168', '(31*31-625)/2', 'The two sides add to $62\div 2=31$, and their squares add to $25^2=625$. Since $31^2=961=625+2ab$, we get $ab=168$. (The sides are 24 and 7.)', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L+W = 31, L^2+W^2 = 625; 2LW = 961-625 = 336, LW = 168 (7 by 24).","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dfaf9d5-df22-4c51-9dc4-9d3509584e42', 'PRE.13', 1, 'numeric', 'Mean of a list', 'Five friends have 4, 6, 8, 10 and 12 stickers. What is the mean number of stickers?', '[]', '8', '(4+6+8+10+12)/5', 'Add the numbers: $4+6+8+10+12=40$. Divide by how many numbers there are: $40\div5=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+6+8+10+12=40; 40/5=8.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d3bc5a7-d651-438d-96ab-d8ba86e34fa5', 'PRE.13', 1, 'choice', 'Adding or removing a value', 'Three test scores of 70, 80 and 90 have a mean of 80. A fourth score of 100 is added. What is the new mean?', '["$90$","$340$","$80$","$85$"]', '$85$', '(70+80+90+100)/4', 'The four scores total $70+80+90+100=340$. The new mean is $340\div4=85$.', 'checked', '{"lint":[],"solve":{"answer":"$85$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"340/4=85.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
