INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('218bccfe-824f-4e11-91ce-c4d5ece1fd7d', 'PRE.13', 2, 'numeric', 'Median of a list', 'What is the median of 4, 8, 10, 15, 20 and 3?', '[]', '9', '(8+10)/2', 'In order: 3, 4, 8, 10, 15, 20. There are six numbers, so the median is halfway between the 3rd and 4th: $(8+10)\div2=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted 3,4,8,10,15,20; median (8+10)/2=9.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
