INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09ca58a5-47be-4617-89bb-a4d909b66a1c', 'PRE.14', 1, 'choice', 'Overlapping groups', 'In a group of 20 children, 11 have a dog and 7 have a cat. Nobody has both. How many children have neither?', '["$0$","$2$","$18$","$9$"]', '$2$', '20-11-7', 'Since no child is in both groups, $11+7=18$ children have a pet. So $20-18=2$ have neither.', 'checked', '{"lint":[],"solve":{"answer":"$2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11+7=18 with something; 20-18=2.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
