INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a4f449c-8326-4c8c-af9f-6f6f67b19f27', 'PRE.14', 2, 'numeric', 'Choosing in order (offices and places)', 'Three-letter "words" (they need not be real words) are made from the letters A, B, C, D, E and F, with no letter used twice in a word. How many such words are there?', '[]', '120', '6*5*4', '6 choices for the first letter, 5 for the second and 4 for the third: $6\times5\times4=120$.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*5*4=120.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c366b09-315d-4613-bae8-034c1bf2fa07', 'PRE.14', 2, 'choice', 'Choosing a group (order does not matter)', 'A pizza has 3 different toppings, chosen from 6 toppings. The order of the toppings does not matter. How many different pizzas are possible?', '["$120$","$18$","$20$","$40$"]', '$20$', '6*5*4/(3*2*1)', 'In order there are $6\times5\times4=120$ ways. Each set of 3 toppings can be put in $3\times2\times1=6$ orders, so $120\div6=20$.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(6,3)=20.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16d8f7fa-49b7-4a1c-9321-9ec81610bacf', 'PRE.14', 2, 'choice', 'Coins, dice and repeated choices', 'A test has 3 questions, and each has 4 answer choices. In how many different ways can all three questions be answered?', '["$64$","$12$","$81$","$24$"]', '$64$', '4^3', 'Each question has 4 choices: $4\times4\times4=64$. ($81$ swaps the 3 and the 4.)', 'checked', '{"lint":[],"solve":{"answer":"$64$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^3=64.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('019623a1-baaa-418c-ad20-31abf7e335c1', 'PRE.14', 3, 'numeric', 'Choosing from separate groups', 'A committee of 3 is chosen from 5 men and 4 women. How many committees have at least one woman?', '[]', '74', '84-10', 'All committees: $\frac{9\times8\times7}{3\times2\times1}=84$. Committees of men only: $\frac{5\times4\times3}{3\times2\times1}=10$. So $84-10=74$.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C(9,3)=84; all men C(5,3)=10; 74.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0029e5df-f90c-4f8d-a6d1-00db6c951cdb', 'PRE.14', 3, 'numeric', 'Coins, dice and repeated choices', 'Three dice (red, blue and green) are rolled. In how many outcomes do the three dice show three different numbers?', '[]', '120', '6*5*4', 'The red die shows any of 6 numbers. The blue die must differ: 5 numbers. The green die must differ from both: 4 numbers. $6\times5\times4=120$.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6*5*4=120.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
