INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f7fde82-3bba-4cb7-b1e2-a2601259209c', 'PRE.15', 1, 'numeric', 'Work backwards', 'A number is doubled, and then 5 is subtracted. The result is 21. What is the number?', '[]', '13', '(21+5)/2', 'Undo the steps in reverse order. Add 5: $21+5=26$. Then halve: $26\div2=13$. Check: $13\times2-5=21$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo: 21 + 5 = 26, 26 / 2 = 13. Check 2*13 - 5 = 21.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05d3f7d0-23b9-4172-8584-8eb0f77d5643', 'PRE.15', 1, 'numeric', 'Find and extend a pattern', 'Pattern 1 is made with 4 sticks, pattern 2 with 7 sticks, and pattern 3 with 10 sticks. Each pattern uses 3 more sticks than the one before. How many sticks does pattern 6 use?', '[]', '19', '4+5*3', 'From pattern 1 to pattern 6 there are 5 steps of 3 sticks. So pattern 6 uses $4+5\times3=19$ sticks.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3n + 1; n = 6 gives 19.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
